SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."organizer_player_access" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "jugador_id" "uuid" NOT NULL,
    "owner_organizador_id" "uuid" NOT NULL,
    "grantee_organizer_id" "uuid" NOT NULL,
    "access_type" "text" DEFAULT 'granted_by_admin'::"text" NOT NULL,
    "granted_by_admin_id" "uuid",
    "is_active" boolean DEFAULT true NOT NULL,
    "is_public_ranking" boolean DEFAULT false NOT NULL,
    "local_category" "text",
    "local_display_name" "text",
    "local_jugador_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "joined_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "left_at" timestamp with time zone,
    "joined_via" "text",
    CONSTRAINT "opa_active_left_at_chk" CHECK (((("is_active" = true) AND ("left_at" IS NULL)) OR ("is_active" = false))),
    CONSTRAINT "opa_joined_via_chk" CHECK ((("joined_via" IS NULL) OR ("joined_via" = ANY (ARRAY['admin_legacy'::"text", 'riviera_id'::"text", 'registration'::"text", 'qr'::"text"])))),
    CONSTRAINT "opa_left_after_joined_chk" CHECK ((("left_at" IS NULL) OR ("left_at" >= "joined_at"))),
    CONSTRAINT "organizer_player_access_access_type_check" CHECK (("access_type" = ANY (ARRAY['owner'::"text", 'granted_by_admin'::"text"]))),
    CONSTRAINT "organizer_player_access_not_self" CHECK (("owner_organizador_id" <> "grantee_organizer_id"))
);


ALTER TABLE "public"."organizer_player_access" OWNER TO "postgres";


COMMENT ON TABLE "public"."organizer_player_access" IS 'Player Membership — relación operativa entre un jugador (Carrera Deportiva) y un organizador. La Carrera pertenece al jugador; el organizador administra eventos. is_active=true: membresía activa; is_active=false: salió del organizador (historial intacto). Evolución de Fase 1 acceso concedido; sin tablas paralelas.';



COMMENT ON COLUMN "public"."organizer_player_access"."jugador_id" IS 'Perfil de registro (referencia a la Carrera): riviera_jugadores.id del jugador en su contexto canonical. Mismo jugador puede tener membresías en múltiples organizadores (filas distintas por grantee).';



COMMENT ON COLUMN "public"."organizer_player_access"."owner_organizador_id" IS 'Organizador de Registro (Debut Riviera) — dónde inició la Carrera Deportiva. NO representa propiedad del jugador. Columna legacy; no renombrada físicamente en 2.1.1.';



COMMENT ON COLUMN "public"."organizer_player_access"."grantee_organizer_id" IS 'Organizador donde existe esta membresía (club que opera al jugador localmente).';



COMMENT ON COLUMN "public"."organizer_player_access"."access_type" IS 'Legacy Fase 1: owner | granted_by_admin. Valores futuros en Fase 2.1.2+.';



COMMENT ON COLUMN "public"."organizer_player_access"."granted_by_admin_id" IS 'Legacy: admin que otorgó acceso Fase 1. Futuro: joined_by_user_id en RPC membership.';



COMMENT ON COLUMN "public"."organizer_player_access"."is_active" IS 'Membresía activa. false = salió del organizador; no elimina Carrera ni participaciones.';



COMMENT ON COLUMN "public"."organizer_player_access"."local_jugador_id" IS 'Perfil operativo local riviera_jugadores en grantee_organizer_id (stats/rating del club).';



COMMENT ON COLUMN "public"."organizer_player_access"."joined_at" IS 'Fecha en que el jugador se unió a este organizador (inicio de membresía).';



COMMENT ON COLUMN "public"."organizer_player_access"."left_at" IS 'Fecha en que el jugador salió de este organizador. NULL mientras is_active=true.';



COMMENT ON COLUMN "public"."organizer_player_access"."joined_via" IS 'Canal de alta: admin_legacy | riviera_id | registration | qr (futuro).';



CREATE TABLE IF NOT EXISTS "public"."riviera_jugadores" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "nombre" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "foto_url" "text",
    "email" "text",
    "telefono" "text",
    "whatsapp" "text",
    "nivel" "public"."riviera_jugador_nivel" DEFAULT 'intermedio'::"public"."riviera_jugador_nivel" NOT NULL,
    "genero" "text",
    "fecha_nacimiento" "date",
    "club" "text",
    "organizador_id" "uuid" NOT NULL,
    "estado" "public"."riviera_jugador_estado" DEFAULT 'activo'::"public"."riviera_jugador_estado" NOT NULL,
    "legacy_player_id" "uuid",
    "legacy_liga_jugador_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "categoria" "text" DEFAULT 'open'::"text" NOT NULL,
    "edad" smallint,
    "mano_dominante" "text",
    "instagram_url" "text",
    "facebook_url" "text",
    "visible_publico" boolean DEFAULT true NOT NULL,
    "tiktok_url" "text",
    "en_cancha" "text",
    "pais_codigo" character(2),
    "rating" numeric DEFAULT 3.00,
    "rating_partidos" integer DEFAULT 0,
    "rating_fiabilidad" numeric DEFAULT 0.20,
    "suma_ranking" boolean DEFAULT true NOT NULL,
    "coaching_sobre_mi" "text",
    CONSTRAINT "riviera_jugadores_categoria_check" CHECK ((("categoria" IS NULL) OR ("categoria" = ANY (ARRAY['open'::"text", '1ra_fuerza'::"text", '2da_fuerza'::"text", '3ra_fuerza'::"text", '4ta_fuerza'::"text", '5ta_fuerza'::"text", '6ta_fuerza'::"text"])))),
    CONSTRAINT "riviera_jugadores_coaching_sobre_mi_len" CHECK ((("coaching_sobre_mi" IS NULL) OR ("char_length"("coaching_sobre_mi") <= 200))),
    CONSTRAINT "riviera_jugadores_edad_check" CHECK ((("edad" IS NULL) OR (("edad" >= 5) AND ("edad" <= 99)))),
    CONSTRAINT "riviera_jugadores_en_cancha_check" CHECK ((("en_cancha" IS NULL) OR ("en_cancha" = ANY (ARRAY['reves'::"text", 'drive'::"text"])))),
    CONSTRAINT "riviera_jugadores_genero_check" CHECK ((("genero" IS NULL) OR ("genero" = ANY (ARRAY['M'::"text", 'F'::"text", 'otro'::"text"])))),
    CONSTRAINT "riviera_jugadores_mano_check" CHECK ((("mano_dominante" IS NULL) OR ("mano_dominante" = ANY (ARRAY['derecha'::"text", 'izquierda'::"text", 'ambidiestro'::"text"])))),
    CONSTRAINT "riviera_jugadores_pais_codigo_check" CHECK ((("pais_codigo" IS NULL) OR ("pais_codigo" ~ '^[A-Z]{2}$'::"text")))
);


ALTER TABLE "public"."riviera_jugadores" OWNER TO "postgres";


COMMENT ON TABLE "public"."riviera_jugadores" IS 'Registro central de jugadores Riviera Open por organizador';



COMMENT ON COLUMN "public"."riviera_jugadores"."en_cancha" IS 'Lado en cancha de pádel: reves (revés) o drive (derecha)';



COMMENT ON COLUMN "public"."riviera_jugadores"."pais_codigo" IS 'Código ISO 3166-1 alpha-2 del país del jugador (bandera en ranking y ficha pública).';



COMMENT ON COLUMN "public"."riviera_jugadores"."suma_ranking" IS 'Si false, no aparece en ranking público ni acumula puntos nuevos.';



CREATE OR REPLACE FUNCTION "public"."_apply_granted_local_identity_sync"("p_access" "public"."organizer_player_access", "p_source" "public"."riviera_jugadores") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_nombre text;
  v_categoria text;
BEGIN
  IF p_access.local_jugador_id IS NULL THEN
    RETURN;
  END IF;

  v_nombre := coalesce(nullif(trim(p_access.local_display_name), ''), p_source.nombre);
  v_categoria := coalesce(nullif(trim(p_access.local_category), ''), p_source.categoria::text);

  UPDATE public.riviera_jugadores local
  SET
    nombre = v_nombre,
    categoria = v_categoria,
    foto_url = p_source.foto_url,
    nivel = p_source.nivel,
    edad = p_source.edad,
    mano_dominante = p_source.mano_dominante,
    en_cancha = p_source.en_cancha,
    pais_codigo = p_source.pais_codigo,
    updated_at = now()
  WHERE local.id = p_access.local_jugador_id;

  UPDATE public.players p
  SET name = v_nombre
  FROM public.riviera_jugadores local
  WHERE local.id = p_access.local_jugador_id
    AND local.legacy_player_id IS NOT NULL
    AND local.legacy_player_id = p.id
    AND p.name IS DISTINCT FROM v_nombre;
END;
$$;


ALTER FUNCTION "public"."_apply_granted_local_identity_sync"("p_access" "public"."organizer_player_access", "p_source" "public"."riviera_jugadores") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_are_legal_padel_sets"("p_sets" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_set jsonb;
BEGIN
  IF p_sets IS NULL OR jsonb_typeof(p_sets) = 'null' THEN
    RETURN true;
  END IF;
  IF jsonb_typeof(p_sets) <> 'array' THEN
    RETURN false;
  END IF;
  IF jsonb_array_length(p_sets) = 0 THEN
    RETURN true;
  END IF;
  IF jsonb_array_length(p_sets) > 3 THEN
    RETURN false;
  END IF;

  FOR v_set IN SELECT * FROM jsonb_array_elements(p_sets)
  LOOP
    IF jsonb_typeof(v_set) <> 'object' THEN
      RETURN false;
    END IF;
    IF jsonb_typeof(v_set->'local') <> 'number'
       OR jsonb_typeof(v_set->'visitante') <> 'number' THEN
      RETURN false;
    END IF;
    IF NOT public._is_legal_padel_set(
      (v_set->>'local')::integer,
      (v_set->>'visitante')::integer
    ) THEN
      RETURN false;
    END IF;
  END LOOP;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."_are_legal_padel_sets"("p_sets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_assert"("cond" boolean, "msg" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NOT cond THEN
    RAISE EXCEPTION 'FAIL: %', msg;
  END IF;
  RAISE NOTICE 'PASS: %', msg;
END;
$$;


ALTER FUNCTION "public"."_assert"("cond" boolean, "msg" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_assert_concedidos_ranking_caller"("p_grantee_organizer_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
BEGIN
  IF p_grantee_organizer_id IS NULL THEN
    RAISE EXCEPTION 'grantee_organizer_id requerido'
      USING ERRCODE = '22023';
  END IF;

  v_uid := public._assert_rating_rpc_authenticated();

  IF public.is_master_admin() THEN
    RETURN;
  END IF;

  IF v_uid = p_grantee_organizer_id THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'No autorizado para el mapa de cedidos de este club'
    USING ERRCODE = '42501';
END;
$$;


ALTER FUNCTION "public"."_assert_concedidos_ranking_caller"("p_grantee_organizer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_assert_convocatoria_mode_allowed"("p_mode" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v text := lower(trim(coalesce(p_mode, '')));
BEGIN
  IF v IN ('liga', 'torneo', 'torneo_express', 'evento_multicategoria', 'mini-torneo') THEN
    RAISE EXCEPTION 'modo excluido de convocatoria';
  END IF;
  IF v NOT IN ('reta', 'americano', 'duelo_2v2') THEN
    RAISE EXCEPTION 'mode_type inválido';
  END IF;
  RETURN v;
END;
$$;


ALTER FUNCTION "public"."_assert_convocatoria_mode_allowed"("p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_assert_rating_rpc_authenticated"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autorizado'
      USING ERRCODE = '42501';
  END IF;
  RETURN v_uid;
END;
$$;


ALTER FUNCTION "public"."_assert_rating_rpc_authenticated"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_assert_rating_rpc_authenticated"() IS 'PR2: exige sesión authenticated (rechaza anon).';



CREATE OR REPLACE FUNCTION "public"."_assert_rating_rpc_organizador_caller"("p_organizador_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid;
BEGIN
  IF p_organizador_id IS NULL THEN
    RAISE EXCEPTION 'organizador_id requerido'
      USING ERRCODE = '22023';
  END IF;

  v_uid := public._assert_rating_rpc_authenticated();

  IF public.is_master_admin() THEN
    RETURN;
  END IF;

  IF v_uid = p_organizador_id THEN
    RETURN;
  END IF;

  -- Grant activo: grantee autenticado operando datos de su club anfitrión
  IF EXISTS (
    SELECT 1
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND opa.grantee_organizer_id = v_uid
      AND opa.grantee_organizer_id = p_organizador_id
  ) THEN
    RETURN;
  END IF;

  -- Grant activo: grantee autenticado con jugadores cuyo registro es del owner
  IF EXISTS (
    SELECT 1
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND opa.grantee_organizer_id = v_uid
      AND opa.owner_organizador_id = p_organizador_id
  ) THEN
    RETURN;
  END IF;

  -- Grant activo: owner autenticado consultando su club origen
  IF EXISTS (
    SELECT 1
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND opa.owner_organizador_id = v_uid
      AND opa.owner_organizador_id = p_organizador_id
  ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'No autorizado para este organizador'
    USING ERRCODE = '42501';
END;
$$;


ALTER FUNCTION "public"."_assert_rating_rpc_organizador_caller"("p_organizador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_assert_rating_rpc_organizador_caller"("p_organizador_id" "uuid") IS 'PR2 + grantee fix: caller = organizador, master admin, o cuenta con grant activo (grantee u owner del perfil origen).';



CREATE OR REPLACE FUNCTION "public"."_assign_riviera_id_to_identity"("p_official_player_key" "uuid") RETURNS TABLE("assigned" boolean, "riviera_id" "text", "riviera_id_serial" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_serial bigint;
  v_formatted text;
  v_existing record;
BEGIN
  IF p_official_player_key IS NULL THEN
    RAISE EXCEPTION 'official_player_key requerido';
  END IF;

  SELECT i.riviera_id, i.riviera_id_serial
  INTO v_existing
  FROM public.riviera_official_player_identity i
  WHERE i.official_player_key = p_official_player_key;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Identidad no encontrada: %', p_official_player_key;
  END IF;

  IF v_existing.riviera_id IS NOT NULL THEN
    assigned := false;
    riviera_id := v_existing.riviera_id;
    riviera_id_serial := v_existing.riviera_id_serial;
    RETURN NEXT;
    RETURN;
  END IF;

  v_serial := public._allocate_riviera_id_serial();
  v_formatted := public._format_riviera_id(v_serial);

  UPDATE public.riviera_official_player_identity i
  SET
    riviera_id_serial = v_serial,
    riviera_id = v_formatted
  WHERE i.official_player_key = p_official_player_key
    AND i.riviera_id IS NULL;

  IF FOUND THEN
    assigned := true;
    riviera_id := v_formatted;
    riviera_id_serial := v_serial;
    RETURN NEXT;
    RETURN;
  END IF;

  -- Carrera concurrente: otra transacción asignó primero
  SELECT i.riviera_id, i.riviera_id_serial
  INTO v_existing
  FROM public.riviera_official_player_identity i
  WHERE i.official_player_key = p_official_player_key;

  assigned := false;
  riviera_id := v_existing.riviera_id;
  riviera_id_serial := v_existing.riviera_id_serial;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."_assign_riviera_id_to_identity"("p_official_player_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_block_hard_delete_event_with_career"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tipo text;
  v_count integer := 0;
BEGIN
  IF TG_TABLE_NAME = 'duelos_2v2' THEN
    v_tipo := 'duelo_2v2';
  ELSIF TG_TABLE_NAME = 'tournaments' THEN
    v_tipo := 'reta';
  ELSE
    RETURN OLD;
  END IF;

  SELECT count(*)::int INTO v_count
  FROM public.jugador_participaciones jp
  WHERE jp.tipo_evento::text = v_tipo
    AND jp.evento_id::text = OLD.id::text;

  IF v_count > 0 THEN
    RAISE EXCEPTION
      'No se puede eliminar definitivamente: hay % participación(es) de carrera. Archiva el evento (archived_at) en su lugar.',
      v_count;
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."_block_hard_delete_event_with_career"() OWNER TO "postgres";


