$$;


ALTER FUNCTION "public"."_create_empty_jugador_stats"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_legal_padel_sets"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Solo cuando sets_resultado se escribe o cambia: no re-valida histórico.
  IF TG_OP = 'UPDATE'
     AND NEW.sets_resultado IS NOT DISTINCT FROM OLD.sets_resultado THEN
    RETURN NEW;
  END IF;

  IF NOT public._are_legal_padel_sets(NEW.sets_resultado) THEN
    RAISE EXCEPTION
      'Marcador de set inválido: se permiten 6-0 a 6-4, 7-5 y 7-6; el tercer set admite además súper muerte súbita a 10 con 2 de diferencia (recibido: %)',
      NEW.sets_resultado
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_enforce_legal_padel_sets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_debut_riviera_if_missing"("p_official_player_key" "uuid", "p_registration_jugador_id" "uuid", "p_fallback_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated boolean := false;
  v_row_count integer;
BEGIN
  IF p_official_player_key IS NULL OR p_registration_jugador_id IS NULL THEN
    RETURN false;
  END IF;

  UPDATE public.riviera_official_player_identity i
  SET
    debut_organizer_id = rj.organizador_id,
    debut_at = coalesce(p_fallback_at, now())
  FROM public.riviera_jugadores rj
  WHERE i.official_player_key = p_official_player_key
    AND i.debut_at IS NULL
    AND rj.id = p_registration_jugador_id;

  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  v_updated := v_row_count > 0;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."_ensure_debut_riviera_if_missing"("p_official_player_key" "uuid", "p_registration_jugador_id" "uuid", "p_fallback_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_granted_player_local_as"("p_source_jugador_id" "uuid", "p_grantee" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_access public.organizer_player_access%ROWTYPE;
  v_source public.riviera_jugadores%ROWTYPE;
  v_local_id uuid;
  v_nombre text;
  v_categoria text;
  v_slug text;
BEGIN
  IF p_grantee IS NULL OR p_source_jugador_id IS NULL THEN RETURN NULL; END IF;

  SELECT * INTO v_access FROM public.organizer_player_access opa
  WHERE opa.jugador_id = p_source_jugador_id
    AND opa.grantee_organizer_id = p_grantee AND opa.is_active = true LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_access.local_jugador_id IS NOT NULL THEN RETURN v_access.local_jugador_id; END IF;

  SELECT * INTO v_source FROM public.riviera_jugadores WHERE id = p_source_jugador_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  v_nombre := coalesce(nullif(trim(v_access.local_display_name), ''), v_source.nombre);
  v_categoria := coalesce(nullif(trim(v_access.local_category), ''), v_source.categoria::text);
  v_slug := public._ensure_unique_jugador_slug(
    p_grantee, public._slugify_jugador_nombre(v_nombre), coalesce(v_source.genero, 'M')
  );

  INSERT INTO public.riviera_jugadores (
    nombre, slug, email, telefono, whatsapp, nivel, categoria, edad,
    mano_dominante, en_cancha, pais_codigo, genero, club, foto_url,
    instagram_url, facebook_url, tiktok_url, visible_publico, suma_ranking,
    organizador_id, estado, legacy_player_id, rating, rating_partidos, rating_fiabilidad
  ) VALUES (
    v_nombre, v_slug, v_source.email, v_source.telefono, v_source.whatsapp,
    v_source.nivel, v_categoria, v_source.edad, v_source.mano_dominante,
    v_source.en_cancha, v_source.pais_codigo, v_source.genero, v_source.club,
    v_source.foto_url, v_source.instagram_url, v_source.facebook_url,
    v_source.tiktok_url, false, true, p_grantee, 'activo',
    v_source.legacy_player_id,
    COALESCE(v_source.rating, 3), COALESCE(v_source.rating_partidos, 0),
    COALESCE(v_source.rating_fiabilidad, 0.2)
  ) RETURNING id INTO v_local_id;

  BEGIN PERFORM public._create_empty_jugador_stats(v_local_id); EXCEPTION WHEN OTHERS THEN NULL; END;

  UPDATE public.organizer_player_access
  SET local_jugador_id = v_local_id, updated_at = now() WHERE id = v_access.id;

  RETURN v_local_id;
END;
$$;


ALTER FUNCTION "public"."_ensure_granted_player_local_as"("p_source_jugador_id" "uuid", "p_grantee" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_official_identity_for_participation_jugador"("p_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canonical uuid;
  v_key uuid;
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_key := public._resolve_official_player_key(p_jugador_id);
  IF v_key IS NOT NULL THEN
    RETURN v_key;
  END IF;

  v_canonical := public._resolve_canonical_jugador_for_official(p_jugador_id);
  v_key := public._ensure_official_player_identity_for_jugador(v_canonical);

  IF v_key IS NOT NULL AND v_canonical IS DISTINCT FROM p_jugador_id THEN
    PERFORM public._ensure_official_profile_link_for_granted_local(p_jugador_id, v_key);
  END IF;

  RETURN COALESCE(public._resolve_official_player_key(p_jugador_id), v_key);
END;
$$;


ALTER FUNCTION "public"."_ensure_official_identity_for_participation_jugador"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_official_player_identity_for_jugador"("p_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key uuid;
  v_jugador record;
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_key := public._resolve_official_player_key(p_jugador_id);
  IF v_key IS NOT NULL THEN
    RETURN v_key;
  END IF;

  SELECT i.official_player_key
  INTO v_key
  FROM public.riviera_official_player_identity i
  WHERE i.canonical_riviera_jugador_id = p_jugador_id;

  IF v_key IS NULL THEN
    SELECT rj.id, rj.organizador_id, rj.nombre
    INTO v_jugador
    FROM public.riviera_jugadores rj
    WHERE rj.id = p_jugador_id;

    IF NOT FOUND THEN
      RETURN NULL;
    END IF;

    INSERT INTO public.riviera_official_player_identity (
      canonical_riviera_jugador_id,
      created_by
    )
    VALUES (p_jugador_id, NULL)
    RETURNING official_player_key INTO v_key;

    INSERT INTO public.riviera_official_player_profile_link (
      official_player_key,
      riviera_jugador_id,
      organizer_id,
      link_source,
      created_by
    )
    VALUES (v_key, p_jugador_id, v_jugador.organizador_id, 'owner', NULL)
    ON CONFLICT (riviera_jugador_id) DO NOTHING;

    INSERT INTO public.riviera_official_player_totals (official_player_key, points_total)
    VALUES (v_key, 0)
    ON CONFLICT (official_player_key) DO NOTHING;

    RETURN v_key;
  END IF;

  INSERT INTO public.riviera_official_player_profile_link (
    official_player_key,
    riviera_jugador_id,
    organizer_id,
    link_source,
    created_by
  )
  SELECT
    v_key,
    rj.id,
    rj.organizador_id,
    'owner',
    NULL
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_jugador_id
  ON CONFLICT (riviera_jugador_id) DO NOTHING;

  RETURN v_key;
END;
$$;


ALTER FUNCTION "public"."_ensure_official_player_identity_for_jugador"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_official_profile_link_for_granted_local"("p_local_jugador_id" "uuid", "p_official_player_key" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_access public.organizer_player_access%ROWTYPE;
  v_org_id uuid;
BEGIN
  IF p_local_jugador_id IS NULL OR p_official_player_key IS NULL THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.riviera_official_player_profile_link l
    WHERE l.riviera_jugador_id = p_local_jugador_id
  ) THEN
    RETURN;
  END IF;

  SELECT *
  INTO v_access
  FROM public.organizer_player_access opa
  WHERE opa.is_active = true
    AND opa.local_jugador_id = p_local_jugador_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT rj.organizador_id
  INTO v_org_id
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_local_jugador_id;

  IF v_org_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.riviera_official_player_profile_link (
    official_player_key,
    riviera_jugador_id,
    organizer_id,
    link_source,
    organizer_player_access_id,
    created_by
  )
  VALUES (
    p_official_player_key,
    p_local_jugador_id,
    v_org_id,
    'granted_local',
    v_access.id,
    NULL
  )
  ON CONFLICT (riviera_jugador_id) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."_ensure_official_profile_link_for_granted_local"("p_local_jugador_id" "uuid", "p_official_player_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_unique_jugador_slug"("p_organizador_id" "uuid", "p_base_slug" "text", "p_genero" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slug text := coalesce(nullif(trim(p_base_slug), ''), 'jugador');
  v_try text := v_slug;
  v_suffix int := 0;
BEGIN
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.riviera_jugadores rj
      WHERE rj.organizador_id = p_organizador_id
        AND rj.slug = v_try
        AND (
          (p_genero = 'F' AND rj.genero = 'F')
          OR (coalesce(p_genero, 'M') <> 'F' AND (rj.genero IS NULL OR rj.genero = 'M'))
        )
    ) THEN
      RETURN v_try;
    END IF;
    v_suffix := v_suffix + 1;
    v_try := v_slug || '-' || v_suffix::text;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."_ensure_unique_jugador_slug"("p_organizador_id" "uuid", "p_base_slug" "text", "p_genero" "text") OWNER TO "postgres";


