CREATE OR REPLACE FUNCTION "public"."_is_official_ranking_emitter"("p_organizador_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_organizador_id IS NULL THEN false
    WHEN EXISTS (
      SELECT 1
      FROM public.riviera_official_ranking_emitters e
      WHERE e.organizador_id = p_organizador_id
        AND e.is_active = false
    ) THEN false
    ELSE EXISTS (
      SELECT 1
      FROM public.users u
      WHERE u.id = p_organizador_id
    )
  END;
$$;


