CREATE OR REPLACE FUNCTION "public"."_link_membership_local_profile"("p_official_player_key" "uuid", "p_local_jugador_id" "uuid", "p_organizer_id" "uuid", "p_access_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_inserted uuid;
BEGIN
  IF p_official_player_key IS NULL OR p_local_jugador_id IS NULL OR p_organizer_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.riviera_official_player_profile_link (
    official_player_key,
    riviera_jugador_id,
    organizer_id,
    link_source,
    organizer_player_access_id,
    created_by
  )
  VALUES (
    p_official_player_key,
    p_local_jugador_id,
    p_organizer_id,
    'granted_local',
    p_access_id,
    v_actor
  )
  ON CONFLICT (riviera_jugador_id) DO NOTHING
  RETURNING id INTO v_inserted;

  RETURN v_inserted IS NOT NULL;
END;
$$;


