CREATE OR REPLACE FUNCTION "public"."_map_liga_nivel_to_riviera"("p_nivel" integer) RETURNS "public"."riviera_jugador_nivel"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_nivel IS NULL THEN 'intermedio'::public.riviera_jugador_nivel
    WHEN p_nivel <= 2 THEN 'iniciación'::public.riviera_jugador_nivel
    WHEN p_nivel <= 4 THEN 'intermedio'::public.riviera_jugador_nivel
    WHEN p_nivel = 5 THEN 'avanzado'::public.riviera_jugador_nivel
    ELSE 'élite'::public.riviera_jugador_nivel
  END;
$$;


ALTER FUNCTION "public"."_map_liga_nivel_to_riviera"("p_nivel" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_normalize_riviera_id_exact"("p_input" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_trimmed text;
BEGIN
  v_trimmed := trim(coalesce(p_input, ''));
  IF v_trimmed = '' THEN
    RETURN NULL;
  END IF;

  IF v_trimmed !~ '^RIV-[0-9]{8}$' THEN
    RETURN NULL;
  END IF;

  RETURN v_trimmed;
END;
$_$;


ALTER FUNCTION "public"."_normalize_riviera_id_exact"("p_input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_normalize_riviera_id_loose"("p_input" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE v text;
BEGIN
  v := upper(trim(coalesce(p_input, '')));
  v := regexp_replace(v, '[[:space:]]+', '', 'g');
  IF v ~ '^RIV[0-9]{8}$' THEN v := 'RIV-' || substr(v, 4);
  ELSIF v ~ '^[0-9]{8}$' THEN v := 'RIV-' || v;
  END IF;
  IF v !~ '^RIV-[0-9]{8}$' THEN RETURN NULL; END IF;
  RETURN v;
END;
$_$;


ALTER FUNCTION "public"."_normalize_riviera_id_loose"("p_input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_open_reg_auto_promote_waitlist"("p_registration_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cfg public.tournament_open_registration%ROWTYPE;
  v_confirmed int;
  v_promoted int := 0;
  v_entry_id uuid;
  v_started boolean := false;
BEGIN
  IF p_registration_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT * INTO v_cfg
  FROM public.tournament_open_registration
  WHERE id = p_registration_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  -- No promover si la convocatoria está desactivada, cerrada o cancelada
  IF v_cfg.enabled IS NOT TRUE OR v_cfg.status IN ('closed', 'cancelled') THEN
    RETURN 0;
  END IF;

  -- No alterar slots si el evento ya inició o finalizó
  IF v_cfg.mode_type = 'duelo_2v2' THEN
    SELECT estado IN ('en_juego', 'finalizado') INTO v_started
    FROM public.duelos_2v2 WHERE id = v_cfg.entity_id;
  ELSE
    SELECT coalesce(is_started, false) OR coalesce(is_finished, false)
      INTO v_started
    FROM public.tournaments WHERE id = v_cfg.entity_id;
  END IF;

  IF coalesce(v_started, false) THEN
    RETURN 0;
  END IF;

  SELECT count(*)::int INTO v_confirmed
  FROM public.tournament_open_registration_entries
  WHERE registration_id = v_cfg.id
    AND status = 'confirmed';

  WHILE v_confirmed < v_cfg.capacity LOOP
    SELECT e.id INTO v_entry_id
    FROM public.tournament_open_registration_entries e
    WHERE e.registration_id = v_cfg.id
      AND e.status = 'waitlist'
    ORDER BY e.created_at ASC, e.id ASC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    EXIT WHEN v_entry_id IS NULL;

    UPDATE public.tournament_open_registration_entries
    SET status = 'confirmed',
        confirmed_at = coalesce(confirmed_at, now()),
        updated_at = now()
    WHERE id = v_entry_id;

    v_confirmed := v_confirmed + 1;
    v_promoted := v_promoted + 1;
    v_entry_id := NULL;
  END LOOP;

  IF v_promoted > 0 THEN
    IF v_cfg.mode_type = 'americano' THEN
      PERFORM public._open_reg_sync_americano_roster(v_cfg.entity_id);
    ELSIF v_cfg.mode_type = 'duelo_2v2' THEN
      PERFORM public._open_reg_sync_duelo_slots(v_cfg.entity_id);
    END IF;
  END IF;

  RETURN v_promoted;
END;
$$;


ALTER FUNCTION "public"."_open_reg_auto_promote_waitlist"("p_registration_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_open_reg_entity_title"("p_mode" "text", "p_entity" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v text;
BEGIN
  IF p_mode = 'duelo_2v2' THEN
    SELECT nombre INTO v FROM public.duelos_2v2 WHERE id = p_entity;
  ELSE
    SELECT name INTO v FROM public.tournaments WHERE id = p_entity;
  END IF;
  RETURN coalesce(v, 'Convocatoria');
END;
$$;


