CREATE OR REPLACE FUNCTION "public"."_open_reg_sync_americano_roster"("p_tournament_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_live jsonb;
  v_phase text;
  v_roster jsonb := '[]'::jsonb;
  v_ranking jsonb := '[]'::jsonb;
  r record;
  v_pid text;
BEGIN
  SELECT americano_live INTO v_live
  FROM public.tournament_public_config WHERE tournament_id = p_tournament_id;

  v_phase := coalesce(v_live->>'tournamentPhase', 'registration');
  IF v_phase IN ('playing', 'finished') THEN
    RETURN;
  END IF;

  FOR r IN
    SELECT e.display_name_snapshot, e.riviera_jugador_id, rj.nombre, rj.legacy_player_id,
           opa.local_jugador_id
    FROM public.tournament_open_registration_entries e
    JOIN public.tournament_open_registration cfg ON cfg.id = e.registration_id
    JOIN public.riviera_jugadores rj ON rj.id = e.riviera_jugador_id
    LEFT JOIN public.organizer_player_access opa
      ON opa.jugador_id = e.riviera_jugador_id
     AND opa.grantee_organizer_id = (SELECT user_id FROM public.tournaments WHERE id = p_tournament_id)
     AND opa.is_active = true
    WHERE cfg.entity_id = p_tournament_id
      AND cfg.mode_type = 'americano'
      AND e.status = 'confirmed'
    ORDER BY coalesce(e.confirmed_at, e.created_at)
  LOOP
    v_pid := coalesce(
      nullif(r.legacy_player_id::text, ''),
      nullif(r.local_jugador_id::text, ''),
      r.riviera_jugador_id::text
    );
    v_roster := v_roster || jsonb_build_array(jsonb_build_object(
      'id', v_pid,
      'name', coalesce(nullif(trim(r.display_name_snapshot), ''), r.nombre)
    ));
    v_ranking := v_ranking || jsonb_build_array(jsonb_build_object(
      'id', v_pid,
      'name', coalesce(nullif(trim(r.display_name_snapshot), ''), r.nombre),
      'stats', jsonb_build_object(
        'pointsFor', 0, 'pointsAgainst', 0, 'gamesPlayed', 0, 'roundsOnBench', 0
      )
    ));
  END LOOP;

  INSERT INTO public.tournament_public_config AS tpc (tournament_id, format, americano_live)
  VALUES (
    p_tournament_id,
    'americano',
    jsonb_build_object(
      'version', 1,
      'savedAt', to_jsonb(now()::text),
      'tournamentPhase', 'registration',
      'roster', v_roster,
      'ranking', v_ranking,
      'rounds', '[]'::jsonb
    )
  )
  ON CONFLICT (tournament_id) DO UPDATE SET
    americano_live = CASE
      WHEN coalesce(tpc.americano_live->>'tournamentPhase', 'registration') IN ('playing', 'finished')
        THEN tpc.americano_live
      ELSE jsonb_build_object(
        'version', 1,
        'savedAt', to_jsonb(now()::text),
        'tournamentPhase', 'registration',
        'roster', v_roster,
        'ranking', v_ranking,
        'rounds', coalesce(tpc.americano_live->'rounds', '[]'::jsonb)
      )
    END;
EXCEPTION WHEN undefined_column OR undefined_table THEN
  NULL;
END;
$$;


ALTER FUNCTION "public"."_open_reg_sync_americano_roster"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_open_reg_sync_duelo_slots"("p_duelo_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  ids uuid[] := ARRAY[NULL, NULL, NULL, NULL];
  names text[] := ARRAY[NULL, NULL, NULL, NULL];
  r record;
  placed int := 0;
  idx int;
  try_idxs int[];
  i int;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.duelos_2v2 d
    WHERE d.id = p_duelo_id AND d.estado IN ('en_juego', 'finalizado')
      AND d.pareja_a_j1_id IS NOT NULL AND d.pareja_a_j2_id IS NOT NULL
      AND d.pareja_b_j1_id IS NOT NULL AND d.pareja_b_j2_id IS NOT NULL
      AND coalesce(d.sets_pareja_a, 0) + coalesce(d.sets_pareja_b, 0) > 0
  ) THEN
    RETURN;
  END IF;

  -- 1) Preferencias A/B en orden de confirmación
  FOR r IN
    SELECT e.riviera_jugador_id,
           coalesce(nullif(trim(e.display_name_snapshot), ''), rj.nombre) AS nombre,
           opa.local_jugador_id,
           upper(nullif(trim(e.preferred_side), '')) AS pref
    FROM public.tournament_open_registration_entries e
    JOIN public.tournament_open_registration cfg ON cfg.id = e.registration_id
    JOIN public.riviera_jugadores rj ON rj.id = e.riviera_jugador_id
    LEFT JOIN public.organizer_player_access opa
      ON opa.jugador_id = e.riviera_jugador_id
     AND opa.grantee_organizer_id = (SELECT organizador_id FROM public.duelos_2v2 WHERE id = p_duelo_id)
     AND opa.is_active = true
    WHERE cfg.entity_id = p_duelo_id
      AND cfg.mode_type = 'duelo_2v2'
      AND e.status = 'confirmed'
      AND upper(nullif(trim(e.preferred_side), '')) IN ('A', 'B')
    ORDER BY coalesce(e.confirmed_at, e.created_at)
    LIMIT 4
  LOOP
    IF r.pref = 'A' THEN
      try_idxs := ARRAY[1, 2, 3, 4];
    ELSE
      try_idxs := ARRAY[3, 4, 1, 2];
    END IF;
    FOREACH idx IN ARRAY try_idxs LOOP
      IF ids[idx] IS NULL THEN
        ids[idx] := coalesce(r.local_jugador_id, r.riviera_jugador_id);
        names[idx] := r.nombre;
        placed := placed + 1;
        EXIT;
      END IF;
    END LOOP;
    EXIT WHEN placed >= 4;
  END LOOP;

  -- 2) Sin preferencia → primer hueco libre
  FOR r IN
    SELECT e.riviera_jugador_id,
           coalesce(nullif(trim(e.display_name_snapshot), ''), rj.nombre) AS nombre,
           opa.local_jugador_id
    FROM public.tournament_open_registration_entries e
    JOIN public.tournament_open_registration cfg ON cfg.id = e.registration_id
    JOIN public.riviera_jugadores rj ON rj.id = e.riviera_jugador_id
    LEFT JOIN public.organizer_player_access opa
      ON opa.jugador_id = e.riviera_jugador_id
     AND opa.grantee_organizer_id = (SELECT organizador_id FROM public.duelos_2v2 WHERE id = p_duelo_id)
     AND opa.is_active = true
    WHERE cfg.entity_id = p_duelo_id
      AND cfg.mode_type = 'duelo_2v2'
      AND e.status = 'confirmed'
      AND coalesce(upper(nullif(trim(e.preferred_side), '')), '') NOT IN ('A', 'B')
    ORDER BY coalesce(e.confirmed_at, e.created_at)
    LIMIT 4
  LOOP
    FOR i IN 1..4 LOOP
      IF ids[i] IS NULL THEN
        ids[i] := coalesce(r.local_jugador_id, r.riviera_jugador_id);
        names[i] := r.nombre;
        placed := placed + 1;
        EXIT;
      END IF;
    END LOOP;
    EXIT WHEN placed >= 4;
  END LOOP;

  UPDATE public.duelos_2v2 SET
    pareja_a_j1_id = ids[1],
    pareja_a_j1_nombre = coalesce(names[1], ''),
    pareja_a_j2_id = ids[2],
    pareja_a_j2_nombre = coalesce(names[2], ''),
    pareja_b_j1_id = ids[3],
    pareja_b_j1_nombre = coalesce(names[3], ''),
    pareja_b_j2_id = ids[4],
    pareja_b_j2_nombre = coalesce(names[4], ''),
    estado = 'configuracion',
    updated_at = now()
  WHERE id = p_duelo_id;
END;
$$;


ALTER FUNCTION "public"."_open_reg_sync_duelo_slots"("p_duelo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_playoffs_match_ranking_pts"("p_set_scores" "jsonb", "p_for_p1" boolean) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_stb jsonb;
  v_s1 jsonb;
  v_s2 jsonb;
  s1p1 int;
  s1p2 int;
  s2p1 int;
  s2p2 int;
  sw1 int := 0;
  sw2 int := 0;
  p1_won_stb boolean;
BEGIN
  IF p_set_scores IS NULL THEN
    RETURN 0;
  END IF;

  IF coalesce((p_set_scores->>'wo')::boolean, false) THEN
    RETURN 0;
  END IF;

  v_s1 := p_set_scores->'sets'->0;
  v_s2 := p_set_scores->'sets'->1;
  IF v_s1 IS NULL OR v_s2 IS NULL THEN
    RETURN 0;
  END IF;

  s1p1 := coalesce((v_s1->>'p1')::int, 0);
  s1p2 := coalesce((v_s1->>'p2')::int, 0);
  s2p1 := coalesce((v_s2->>'p1')::int, 0);
  s2p2 := coalesce((v_s2->>'p2')::int, 0);

  IF s1p1 > s1p2 THEN
    sw1 := sw1 + 1;
  ELSIF s1p2 > s1p1 THEN
    sw2 := sw2 + 1;
  END IF;

  IF s2p1 > s2p2 THEN
    sw1 := sw1 + 1;
  ELSIF s2p2 > s2p1 THEN
    sw2 := sw2 + 1;
  END IF;

  v_stb := p_set_scores->'stb';
  IF v_stb IS NOT NULL AND ((sw1 = 1 AND sw2 = 1) OR (sw1 = 0 AND sw2 = 0)) THEN
    p1_won_stb := coalesce((v_stb->>'p1')::int, 0) > coalesce((v_stb->>'p2')::int, 0);
    IF p_for_p1 THEN
      RETURN CASE WHEN p1_won_stb THEN 2 ELSE 1 END;
    END IF;
    RETURN CASE WHEN p1_won_stb THEN 1 ELSE 2 END;
  END IF;

  IF sw1 > sw2 THEN
    RETURN CASE WHEN p_for_p1 THEN 3 ELSE 0 END;
  ELSIF sw2 > sw1 THEN
    RETURN CASE WHEN p_for_p1 THEN 0 ELSE 3 END;
  END IF;

  RETURN 0;
END;
$$;


ALTER FUNCTION "public"."_playoffs_match_ranking_pts"("p_set_scores" "jsonb", "p_for_p1" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_propagate_source_jugador_delete"("p_source_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_grant record;
  v_purge_result jsonb;
  v_purged integer := 0;
  v_skipped integer := 0;
  v_grants_removed integer := 0;
  v_details jsonb := '[]'::jsonb;
BEGIN
  IF p_source_jugador_id IS NULL THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'missing_source');
  END IF;

  FOR v_grant IN
    SELECT
      opa.id,
      opa.local_jugador_id,
      opa.grantee_organizador_id,
      opa.is_active
    FROM public.organizer_player_access opa
    WHERE opa.jugador_id = p_source_jugador_id
    ORDER BY opa.grantee_organizador_id
  LOOP
    IF v_grant.local_jugador_id IS NOT NULL THEN
      v_purge_result := public._purge_granted_local_jugador(
        v_grant.local_jugador_id,
        v_grant.grantee_organizador_id,
        p_source_jugador_id
      );

      IF coalesce(v_purge_result->>'status', '') = 'purged' THEN
        v_purged := v_purged + 1;
      ELSE
        v_skipped := v_skipped + 1;
      END IF;

      v_details := v_details || jsonb_build_array(v_purge_result);
    END IF;

    DELETE FROM public.organizer_player_access
    WHERE id = v_grant.id;
    v_grants_removed := v_grants_removed + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'propagated',
    'source_jugador_id', p_source_jugador_id,
    'locals_purged', v_purged,
    'locals_skipped', v_skipped,
    'grants_removed', v_grants_removed,
    'details', v_details
  );
END;
$$;


ALTER FUNCTION "public"."_propagate_source_jugador_delete"("p_source_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_purge_granted_local_jugador"("p_local_jugador_id" "uuid", "p_grantee_organizador_id" "uuid", "p_source_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_official_key uuid;
  v_part_id uuid;
  v_new_canonical uuid;
  v_liga_jugador_id uuid;
  v_deleted_participaciones integer := 0;
BEGIN
  IF p_local_jugador_id IS NULL OR p_grantee_organizador_id IS NULL THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'missing_params');
  END IF;

  SELECT
    rj.id,
    rj.nombre,
    rj.legacy_player_id,
    rj.legacy_liga_jugador_id,
    rj.organizador_id
  INTO v_row
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_local_jugador_id
    AND rj.organizador_id = p_grantee_organizador_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'local_clone_not_found',
      'local_jugador_id', p_local_jugador_id
    );
  END IF;

  v_official_key := public._safe_resolve_official_player_key(p_local_jugador_id);

  -- 1) Ledger ANTES que participaciones (FK RESTRICT en ledger.participacion_id).
  FOR v_part_id IN
    SELECT jp.id
    FROM public.jugador_participaciones jp
    WHERE jp.jugador_id = p_local_jugador_id
  LOOP
    PERFORM public._reverse_ledger_for_participacion_safe(v_part_id);
  END LOOP;

  -- 2) Participaciones del clon únicamente.
  DELETE FROM public.jugador_participaciones
  WHERE jugador_id = p_local_jugador_id;
  GET DIAGNOSTICS v_deleted_participaciones = ROW_COUNT;

  -- 3) Ledger huérfano del clon.
  IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
    DELETE FROM public.riviera_official_points_ledger
    WHERE source_local_jugador_id = p_local_jugador_id;
  END IF;

  -- 4) Exclusiones scoped al clon.
  IF to_regclass('public.jugador_participacion_exclusiones') IS NOT NULL THEN
    DELETE FROM public.jugador_participacion_exclusiones
    WHERE scope_jugador_id = p_local_jugador_id;
  END IF;

  -- 5) Rating / stats del clon únicamente.
  IF to_regclass('public.rating_historial') IS NOT NULL THEN
    DELETE FROM public.rating_historial
    WHERE jugador_id = p_local_jugador_id;
  END IF;

  DELETE FROM public.jugador_stats
  WHERE jugador_id = p_local_jugador_id;

  -- 6) ROMC: desvincular perfil del clon (origen puede seguir vivo).
  IF to_regclass('public.riviera_official_player_profile_link') IS NOT NULL THEN
    SELECT l.official_player_key
    INTO v_official_key
    FROM public.riviera_official_player_profile_link l
    WHERE l.riviera_jugador_id = p_local_jugador_id;

    IF v_official_key IS NOT NULL THEN
      IF EXISTS (
        SELECT 1
        FROM public.riviera_official_player_identity i
        WHERE i.official_player_key = v_official_key
          AND i.canonical_riviera_jugador_id = p_local_jugador_id
      ) THEN
        -- Preferir reasignar canonical al origen si aún está enlazado.
        SELECT l.riviera_jugador_id
        INTO v_new_canonical
        FROM public.riviera_official_player_profile_link l
        WHERE l.official_player_key = v_official_key
          AND l.riviera_jugador_id = p_source_jugador_id
        LIMIT 1;

        IF v_new_canonical IS NULL THEN
          SELECT l.riviera_jugador_id
          INTO v_new_canonical
          FROM public.riviera_official_player_profile_link l
          WHERE l.official_player_key = v_official_key
            AND l.riviera_jugador_id <> p_local_jugador_id
          ORDER BY l.created_at
          LIMIT 1;
        END IF;

        IF v_new_canonical IS NOT NULL THEN
          UPDATE public.riviera_official_player_identity
          SET canonical_riviera_jugador_id = v_new_canonical
          WHERE official_player_key = v_official_key;
        END IF;
      END IF;

      DELETE FROM public.riviera_official_player_profile_link
      WHERE riviera_jugador_id = p_local_jugador_id;

      IF v_new_canonical IS NULL AND NOT EXISTS (
        SELECT 1
        FROM public.riviera_official_player_profile_link l
        WHERE l.official_player_key = v_official_key
      ) THEN
        IF to_regclass('public.riviera_official_player_totals') IS NOT NULL THEN
          DELETE FROM public.riviera_official_player_totals
          WHERE official_player_key = v_official_key;
        END IF;
        IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
          DELETE FROM public.riviera_official_points_ledger
          WHERE official_player_key = v_official_key;
        END IF;
        DELETE FROM public.riviera_official_player_identity
        WHERE official_player_key = v_official_key;
      END IF;
    END IF;
  END IF;

  -- 7) Duelos del anfitrión: conservar encuentro, quitar referencia al clon.
  IF to_regclass('public.duelos_2v2') IS NOT NULL THEN
    UPDATE public.duelos_2v2
    SET
      pareja_a_j1_id = CASE
        WHEN pareja_a_j1_id = p_local_jugador_id THEN NULL ELSE pareja_a_j1_id
      END,
      pareja_a_j2_id = CASE
        WHEN pareja_a_j2_id = p_local_jugador_id THEN NULL ELSE pareja_a_j2_id
      END,
      pareja_b_j1_id = CASE
        WHEN pareja_b_j1_id = p_local_jugador_id THEN NULL ELSE pareja_b_j1_id
      END,
      pareja_b_j2_id = CASE
        WHEN pareja_b_j2_id = p_local_jugador_id THEN NULL ELSE pareja_b_j2_id
      END,
      updated_at = now()
    WHERE organizador_id = p_grantee_organizador_id
      AND (
        pareja_a_j1_id = p_local_jugador_id
        OR pareja_a_j2_id = p_local_jugador_id
        OR pareja_b_j1_id = p_local_jugador_id
        OR pareja_b_j2_id = p_local_jugador_id
      );
  END IF;

  -- 8) Liga local del clon (scoped al anfitrión).
  v_liga_jugador_id := NULLIF(trim(v_row.legacy_liga_jugador_id::text), '')::uuid;

  IF v_liga_jugador_id IS NOT NULL THEN
    IF to_regclass('public.liga_inscripciones') IS NOT NULL THEN
      DELETE FROM public.liga_inscripciones
      WHERE jugador_id = v_liga_jugador_id;
    END IF;

    IF to_regclass('public.liga_jugadores') IS NOT NULL THEN
      UPDATE public.liga_jugadores
      SET estado = 'inactivo'
      WHERE id = v_liga_jugador_id
        AND organizador_id = p_grantee_organizador_id;
    END IF;
  END IF;

  -- 9) Blocklist en el club anfitrión (evita re-import del clon).
  PERFORM public._insert_jugador_import_blocklist_internal(
    p_grantee_organizador_id,
    v_row.nombre,
    v_row.legacy_player_id,
    v_liga_jugador_id
  );

  -- 10) Borrar clon (NO toca players / pairs / matches / games / tournaments).
  DELETE FROM public.riviera_jugadores
  WHERE id = p_local_jugador_id
    AND organizador_id = p_grantee_organizador_id;

  RETURN jsonb_build_object(
    'status', 'purged',
    'local_jugador_id', p_local_jugador_id,
    'grantee_organizador_id', p_grantee_organizador_id,
    'participaciones_deleted', v_deleted_participaciones
  );
END;
$$;


ALTER FUNCTION "public"."_purge_granted_local_jugador"("p_local_jugador_id" "uuid", "p_grantee_organizador_id" "uuid", "p_source_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_purge_riviera_jugador_scoped"("p_jugador_id" "uuid", "p_organizador_id" "uuid", "p_backup_suffix" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_row record;
  v_official_key uuid;
  v_part_id uuid;
  v_liga_jugador_id uuid;
  v_deleted_participaciones integer := 0;
  v_bt text;
  v_ident_key uuid;
  v_alt_canonical uuid;
  v_bk text;
BEGIN
  IF p_jugador_id IS NULL OR p_organizador_id IS NULL THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'missing_params');
  END IF;

  SELECT rj.id, rj.nombre, rj.legacy_player_id, rj.legacy_liga_jugador_id, rj.organizador_id
  INTO v_row
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_jugador_id
    AND rj.organizador_id = p_organizador_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'jugador_not_found',
      'jugador_id', p_jugador_id
    );
  END IF;

  v_bt := COALESCE(NULLIF(trim(p_backup_suffix), ''), to_char(now() AT TIME ZONE 'utc', 'YYYYMMDD_HH24MISS'));

  -- ── Backup scoped (tablas permanentes; no TEMP: deben sobrevivir la sesión) ──
  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS public.%I AS
       SELECT * FROM public.riviera_jugadores WHERE false',
    'jugador_delete_backup_riviera_jugadores_' || v_bt
  );
  EXECUTE format(
    'INSERT INTO public.%I SELECT * FROM public.riviera_jugadores WHERE id = $1',
    'jugador_delete_backup_riviera_jugadores_' || v_bt
  ) USING p_jugador_id;

  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS public.%I AS
       SELECT * FROM public.jugador_participaciones WHERE false',
    'jugador_delete_backup_participaciones_' || v_bt
  );
  EXECUTE format(
    'INSERT INTO public.%I SELECT * FROM public.jugador_participaciones WHERE jugador_id = $1',
    'jugador_delete_backup_participaciones_' || v_bt
  ) USING p_jugador_id;

  IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS public.%I AS
         SELECT * FROM public.riviera_official_points_ledger WHERE false',
      'jugador_delete_backup_ledger_' || v_bt
    );
    EXECUTE format(
      'INSERT INTO public.%I
         SELECT * FROM public.riviera_official_points_ledger
         WHERE source_local_jugador_id = $1
            OR participacion_id IN (
                 SELECT id FROM public.jugador_participaciones WHERE jugador_id = $1
               )',
      'jugador_delete_backup_ledger_' || v_bt
    ) USING p_jugador_id;
  END IF;

  IF to_regclass('public.organizer_player_access') IS NOT NULL THEN
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS public.%I AS
         SELECT * FROM public.organizer_player_access WHERE false',
      'jugador_delete_backup_opa_' || v_bt
    );
    EXECUTE format(
      'INSERT INTO public.%I
         SELECT opa.*
         FROM public.organizer_player_access opa
         WHERE (opa.jugador_id = $1 OR opa.local_jugador_id = $1)
           AND NOT EXISTS (
             SELECT 1 FROM public.%I b WHERE b.id = opa.id
           )',
      'jugador_delete_backup_opa_' || v_bt,
      'jugador_delete_backup_opa_' || v_bt
    ) USING p_jugador_id;
  END IF;

  -- Endurecimiento de backups (0053): RLS + sin acceso para la API publica.
  FOREACH v_bk IN ARRAY ARRAY[
    'jugador_delete_backup_riviera_jugadores_' || v_bt,
    'jugador_delete_backup_participaciones_'   || v_bt,
    'jugador_delete_backup_ledger_'            || v_bt,
    'jugador_delete_backup_opa_'               || v_bt
  ]
  LOOP
    IF to_regclass(format('public.%I', v_bk)) IS NOT NULL THEN
      EXECUTE format(
        'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',
        v_bk
      );

      EXECUTE format(
        'REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated',
        v_bk
      );
    END IF;
  END LOOP;

  v_official_key := public._safe_resolve_official_player_key(p_jugador_id);

  -- 1) Ledger antes de participaciones (FK RESTRICT)
  FOR v_part_id IN
    SELECT jp.id FROM public.jugador_participaciones jp WHERE jp.jugador_id = p_jugador_id
  LOOP
    PERFORM public._reverse_ledger_for_participacion_safe(v_part_id);
  END LOOP;

  DELETE FROM public.jugador_participaciones WHERE jugador_id = p_jugador_id;
  GET DIAGNOSTICS v_deleted_participaciones = ROW_COUNT;

  IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
    DELETE FROM public.riviera_official_points_ledger
    WHERE source_local_jugador_id = p_jugador_id;
  END IF;

  IF to_regclass('public.jugador_participacion_exclusiones') IS NOT NULL THEN
    DELETE FROM public.jugador_participacion_exclusiones
    WHERE scope_jugador_id = p_jugador_id
       OR (v_official_key IS NOT NULL AND official_player_key = v_official_key);
  END IF;

  IF to_regclass('public.rating_historial') IS NOT NULL THEN
    DELETE FROM public.rating_historial WHERE jugador_id = p_jugador_id;
  END IF;

  DELETE FROM public.jugador_stats WHERE jugador_id = p_jugador_id;

  -- Sharing requests (RESTRICT en registration_jugador_id)
  IF to_regclass('public.riviera_player_sharing_request') IS NOT NULL THEN
    DELETE FROM public.riviera_player_sharing_request
    WHERE riviera_jugador_id = p_jugador_id
       OR registration_jugador_id = p_jugador_id;
  END IF;

  -- ROMC: soltar identity.canonical ANTES de borrar el perfil (si no, FK 409).
  IF to_regclass('public.riviera_official_player_identity') IS NOT NULL THEN
    FOR v_ident_key IN
      SELECT i.official_player_key
      FROM public.riviera_official_player_identity i
      WHERE i.canonical_riviera_jugador_id = p_jugador_id
    LOOP
      v_alt_canonical := NULL;
      IF to_regclass('public.riviera_official_player_profile_link') IS NOT NULL THEN
        SELECT l.riviera_jugador_id INTO v_alt_canonical
        FROM public.riviera_official_player_profile_link l
        WHERE l.official_player_key = v_ident_key
          AND l.riviera_jugador_id IS DISTINCT FROM p_jugador_id
        ORDER BY l.created_at
        LIMIT 1;
      END IF;
      IF v_alt_canonical IS NOT NULL THEN
        UPDATE public.riviera_official_player_identity
        SET canonical_riviera_jugador_id = v_alt_canonical
        WHERE official_player_key = v_ident_key;
      ELSE
        IF to_regclass('public.riviera_official_player_profile_link') IS NOT NULL THEN
          DELETE FROM public.riviera_official_player_profile_link
          WHERE official_player_key = v_ident_key;
        END IF;
        IF to_regclass('public.riviera_official_player_totals') IS NOT NULL THEN
          DELETE FROM public.riviera_official_player_totals
          WHERE official_player_key = v_ident_key;
        END IF;
        IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
          DELETE FROM public.riviera_official_points_ledger
          WHERE official_player_key = v_ident_key;
        END IF;
        DELETE FROM public.riviera_official_player_identity
        WHERE official_player_key = v_ident_key;
      END IF;
    END LOOP;
  END IF;

  IF to_regclass('public.riviera_official_player_profile_link') IS NOT NULL THEN
    DELETE FROM public.riviera_official_player_profile_link
    WHERE riviera_jugador_id = p_jugador_id;
  END IF;

  -- Duelos: conservar encuentro; solo null FK (nombres históricos quedan)
  IF to_regclass('public.duelos_2v2') IS NOT NULL THEN
    UPDATE public.duelos_2v2
    SET
      pareja_a_j1_id = CASE WHEN pareja_a_j1_id = p_jugador_id THEN NULL ELSE pareja_a_j1_id END,
      pareja_a_j2_id = CASE WHEN pareja_a_j2_id = p_jugador_id THEN NULL ELSE pareja_a_j2_id END,
      pareja_b_j1_id = CASE WHEN pareja_b_j1_id = p_jugador_id THEN NULL ELSE pareja_b_j1_id END,
      pareja_b_j2_id = CASE WHEN pareja_b_j2_id = p_jugador_id THEN NULL ELSE pareja_b_j2_id END,
      updated_at = now()
    WHERE pareja_a_j1_id = p_jugador_id
       OR pareja_a_j2_id = p_jugador_id
       OR pareja_b_j1_id = p_jugador_id
       OR pareja_b_j2_id = p_jugador_id;
  END IF;

  v_liga_jugador_id := NULLIF(trim(v_row.legacy_liga_jugador_id::text), '')::uuid;
  IF v_liga_jugador_id IS NOT NULL THEN
    IF to_regclass('public.liga_inscripciones') IS NOT NULL THEN
      DELETE FROM public.liga_inscripciones WHERE jugador_id = v_liga_jugador_id;
    END IF;
    IF to_regclass('public.liga_jugadores') IS NOT NULL THEN
      UPDATE public.liga_jugadores
      SET estado = 'inactivo'
      WHERE id = v_liga_jugador_id
        AND organizador_id = p_organizador_id;
    END IF;
  END IF;

  PERFORM public._insert_jugador_import_blocklist_internal(
    p_organizador_id,
    v_row.nombre,
    v_row.legacy_player_id,
    v_liga_jugador_id
  );

  -- OPA residual scoped a este id
  IF to_regclass('public.organizer_player_access') IS NOT NULL THEN
    DELETE FROM public.organizer_player_access
    WHERE jugador_id = p_jugador_id
       OR local_jugador_id = p_jugador_id;
  END IF;

  -- Nunca touch players / pairs / matches / tournaments
  DELETE FROM public.riviera_jugadores
  WHERE id = p_jugador_id
    AND organizador_id = p_organizador_id;

  RETURN jsonb_build_object(
    'status', 'purged',
    'jugador_id', p_jugador_id,
    'organizador_id', p_organizador_id,
    'participaciones_deleted', v_deleted_participaciones,
    'backup_suffix', v_bt,
    'official_player_key', v_official_key
  );
END;
$_$;


ALTER FUNCTION "public"."_purge_riviera_jugador_scoped"("p_jugador_id" "uuid", "p_organizador_id" "uuid", "p_backup_suffix" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recalc_official_player_totals"("p_official_player_key" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total integer;
  v_last timestamptz;
BEGIN
  IF p_official_player_key IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COALESCE(SUM(l.points), 0)::integer,
    MAX(l.created_at)
  INTO v_total, v_last
  FROM public.riviera_official_points_ledger l
  WHERE l.official_player_key = p_official_player_key
    AND COALESCE(l.counts_for_official_ranking, true) = true;

  UPDATE public.riviera_official_player_totals
  SET
    points_total = GREATEST(0, v_total),
    last_activity_at = v_last,
    updated_at = now()
  WHERE official_player_key = p_official_player_key;

  IF NOT FOUND AND v_total > 0 THEN
    INSERT INTO public.riviera_official_player_totals (
      official_player_key,
      points_total,
      last_activity_at
    ) VALUES (
      p_official_player_key,
      v_total,
      v_last
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."_recalc_official_player_totals"("p_official_player_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_resolve_canonical_jugador_for_official"("p_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_source_id uuid;
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT opa.jugador_id
  INTO v_source_id
  FROM public.organizer_player_access opa
  WHERE opa.is_active = true
    AND opa.local_jugador_id = p_jugador_id
  LIMIT 1;

  IF v_source_id IS NOT NULL THEN
    RETURN v_source_id;
  END IF;

  RETURN p_jugador_id;
END;
$$;


ALTER FUNCTION "public"."_resolve_canonical_jugador_for_official"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_resolve_home_organizador_for_jugador"("p_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key uuid;
  v_home uuid;
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_key := public._resolve_official_player_key(p_jugador_id);

  IF v_key IS NOT NULL THEN
    SELECT rj.organizador_id
    INTO v_home
    FROM public.riviera_official_player_identity i
    INNER JOIN public.riviera_jugadores rj
      ON rj.id = i.canonical_riviera_jugador_id
    WHERE i.official_player_key = v_key;
  END IF;

  IF v_home IS NOT NULL THEN
    RETURN v_home;
  END IF;

  SELECT rj.organizador_id
  INTO v_home
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_jugador_id;

  RETURN v_home;
END;
$$;


ALTER FUNCTION "public"."_resolve_home_organizador_for_jugador"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_resolve_identity_by_riviera_id"("p_riviera_id" "text") RETURNS TABLE("official_player_key" "uuid", "riviera_id" "text", "riviera_id_serial" bigint, "canonical_riviera_jugador_id" "uuid", "registration_organizer_id" "uuid", "display_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_normalized text;
BEGIN
  v_normalized := public._normalize_riviera_id_exact(p_riviera_id);
  IF v_normalized IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    i.official_player_key,
    i.riviera_id,
    i.riviera_id_serial,
    i.canonical_riviera_jugador_id,
    coalesce(i.debut_organizer_id, rj.organizador_id) AS registration_organizer_id,
    rj.nombre::text AS display_name
  FROM public.riviera_official_player_identity i
  JOIN public.riviera_jugadores rj
    ON rj.id = i.canonical_riviera_jugador_id
  WHERE i.riviera_id = v_normalized
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."_resolve_identity_by_riviera_id"("p_riviera_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_resolve_official_player_key"("p_riviera_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key uuid;
  v_source_id uuid;
  v_grant_source uuid;
BEGIN
  SELECT l.official_player_key
  INTO v_key
  FROM public.riviera_official_player_profile_link l
  WHERE l.riviera_jugador_id = p_riviera_jugador_id;

  IF v_key IS NOT NULL THEN
    RETURN v_key;
  END IF;

  -- Grant: clon local → jugador origen con profile_link
  SELECT opa.jugador_id
  INTO v_source_id
  FROM public.organizer_player_access opa
  WHERE opa.is_active = true
    AND opa.local_jugador_id = p_riviera_jugador_id
  LIMIT 1;

  IF v_source_id IS NOT NULL THEN
    SELECT l.official_player_key
    INTO v_key
    FROM public.riviera_official_player_profile_link l
    WHERE l.riviera_jugador_id = v_source_id;
    IF v_key IS NOT NULL THEN
      RETURN v_key;
    END IF;
  END IF;

  -- Grant inverso: perfil origen → buscar profile_link en cualquier clon activo
  SELECT l.official_player_key
  INTO v_key
  FROM public.organizer_player_access opa
  JOIN public.riviera_official_player_profile_link l
    ON l.riviera_jugador_id = opa.local_jugador_id
  WHERE opa.is_active = true
    AND opa.jugador_id = p_riviera_jugador_id
  LIMIT 1;

  IF v_key IS NOT NULL THEN
    RETURN v_key;
  END IF;

  -- Grant inverso vía canonical en identity
  SELECT i.official_player_key
  INTO v_key
  FROM public.organizer_player_access opa
  JOIN public.riviera_official_player_identity i
    ON i.canonical_riviera_jugador_id = opa.jugador_id
  WHERE opa.is_active = true
    AND opa.local_jugador_id = p_riviera_jugador_id
  LIMIT 1;

  RETURN v_key;
END;
$$;


ALTER FUNCTION "public"."_resolve_official_player_key"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_resolve_organizador_for_player"("p_player_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT org_id FROM (
    SELECT t.user_id AS org_id
    FROM public.pairs pr
    JOIN public.tournaments t ON t.id = pr.tournament_id
    WHERE (pr.player1_id = p_player_id OR pr.player2_id = p_player_id)
      AND t.user_id IS NOT NULL
    UNION ALL
    SELECT te.organizador_id AS org_id
    FROM public.pairs pr
    JOIN public.torneo_express_grupo_parejas gp ON gp.pareja_id = pr.id
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    JOIN public.torneo_express te ON te.id = g.torneo_id
    WHERE (pr.player1_id = p_player_id OR pr.player2_id = p_player_id)
      AND te.organizador_id IS NOT NULL
  ) sub
  WHERE org_id IS NOT NULL
  LIMIT 1;
$$;


ALTER FUNCTION "public"."_resolve_organizador_for_player"("p_player_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_reverse_ledger_for_participacion_safe"("p_participacion_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_participacion_id IS NULL THEN
    RETURN;
  END IF;
  BEGIN
    PERFORM public.reverse_riviera_official_ledger_for_participacion(p_participacion_id);
  EXCEPTION
    WHEN undefined_function THEN
      NULL;
    WHEN OTHERS THEN
      -- Mejor fallar el delete completo que dejar ledger inconsistente.
      RAISE;
  END;
END;
$$;


