CREATE OR REPLACE FUNCTION "public"."_riviera_id_lookup_client_key"() RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT coalesce(
    nullif(split_part(current_setting('request.headers', true)::json ->> 'x-forwarded-for', ',', 1), ''),
    auth.uid()::text,
    'unknown'
  );
$$;


ALTER FUNCTION "public"."_riviera_id_lookup_client_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_riviera_id_lookup_rate_limited"("p_action" "text", "p_max_attempts" integer, "p_window" interval) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key text := public._riviera_id_lookup_client_key();
  v_count int;
BEGIN
  SELECT count(*) INTO v_count
  FROM public._riviera_id_lookup_throttle
  WHERE client_key = v_key AND action = p_action
    AND created_at > now() - p_window;

  INSERT INTO public._riviera_id_lookup_throttle (client_key, action) VALUES (v_key, p_action);

  RETURN v_count >= p_max_attempts;
END;
$$;


