CREATE OR REPLACE FUNCTION "public"."_riviera_orphan_profile_audit"() RETURNS TABLE("orphan_jugador_id" "uuid", "orphan_nombre" "text", "orphan_organizador_id" "uuid", "orphan_club_name" "text", "total_participaciones" bigint, "total_puntos" bigint, "eventos" "text", "host_clubs" "text", "in_career_rpc" boolean, "candidate_official_jugador_id" "uuid", "candidate_nombre" "text", "candidate_riviera_id" "text", "candidate_official_player_key" "uuid", "candidate_count" integer, "confidence" "text", "reason" "text", "action_sugerida" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH orphan_stats AS (
    SELECT
      rj.id AS jugador_id,
      COUNT(jp.id)::bigint AS total_participaciones,
      COALESCE(SUM(jp.puntos_obtenidos), 0)::bigint AS total_puntos,
      string_agg(DISTINCT jp.evento_nombre, ' | ' ORDER BY jp.evento_nombre) AS eventos,
      string_agg(
        DISTINCT COALESCE(NULLIF(trim(jp.metadata->>'organizador_id'), ''), rj.organizador_id::text),
        ', '
      ) AS host_clubs
    FROM public.riviera_jugadores rj
    INNER JOIN public.jugador_participaciones jp ON jp.jugador_id = rj.id
    WHERE rj.estado = 'activo'
      AND COALESCE(jp.puntos_obtenidos, 0) > 0
      AND NOT EXISTS (
        SELECT 1 FROM public.riviera_official_player_profile_link pl
        WHERE pl.riviera_jugador_id = rj.id
      )
    GROUP BY rj.id
  )
  SELECT
    r.jugador_id,
    r.jugador_nombre,
    r.jugador_organizador_id,
    public.get_organizador_display_name(r.jugador_organizador_id),
    os.total_participaciones,
    os.total_puntos,
    os.eventos,
    os.host_clubs,
    EXISTS (
      SELECT 1 FROM public.get_public_career_jugador_ids(r.candidate_official_jugador_id) g(jugador_id)
      WHERE g.jugador_id = r.jugador_id
    ),
    r.candidate_official_jugador_id,
    r.candidate_nombre,
    r.candidate_riviera_id,
    r.candidate_official_player_key,
    r.candidate_count,
    r.confidence,
    r.reason,
    r.action_sugerida
  FROM orphan_stats os
  INNER JOIN public._riviera_profile_link_resolution(os.jugador_id) r
    ON r.jugador_id = os.jugador_id;
$$;


ALTER FUNCTION "public"."_riviera_orphan_profile_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_riviera_participacion_parent_lookup_table"("p_tipo_evento" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE p_tipo_evento
    WHEN 'reta' THEN 'tournaments'
    WHEN 'americano' THEN 'tournaments'
    WHEN 'duelo_2v2' THEN 'duelos_2v2'
    WHEN 'torneo_express' THEN 'torneo_express'
    WHEN 'liga' THEN 'liga_jornadas|ligas'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."_riviera_participacion_parent_lookup_table"("p_tipo_evento" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_riviera_participacion_parent_row_exists"("p_tipo_evento" "text", "p_evento_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE p_tipo_evento
    WHEN 'reta' THEN EXISTS (
      SELECT 1 FROM public.tournaments t
      WHERE t.id = NULLIF(trim(p_evento_id), '')::uuid
    )
    WHEN 'americano' THEN EXISTS (
      SELECT 1 FROM public.tournaments t
      WHERE t.id = NULLIF(trim(p_evento_id), '')::uuid
    )
    WHEN 'duelo_2v2' THEN EXISTS (
      SELECT 1 FROM public.duelos_2v2 d
      WHERE d.id = NULLIF(trim(p_evento_id), '')::uuid
    )
    WHEN 'torneo_express' THEN EXISTS (
      SELECT 1 FROM public.torneo_express t
      WHERE t.id = NULLIF(trim(p_evento_id), '')::uuid
    )
    WHEN 'liga' THEN (
      EXISTS (
        SELECT 1 FROM public.liga_jornadas lj
        WHERE lj.id = NULLIF(trim(p_evento_id), '')::uuid
      )
      OR EXISTS (
        SELECT 1 FROM public.ligas l
        WHERE l.id = NULLIF(trim(p_evento_id), '')::uuid
      )
    )
    ELSE false
  END;
$$;


ALTER FUNCTION "public"."_riviera_participacion_parent_row_exists"("p_tipo_evento" "text", "p_evento_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_riviera_participaciones_canonicas_mensual"("p_organizador_id" "uuid", "p_year" integer, "p_month" integer) RETURNS TABLE("participacion_id" "uuid", "jugador_id" "uuid", "tipo_evento" "text", "evento_id" "uuid", "subtipo" "text", "evento_nombre" "text", "fecha" "date", "resultado" "text", "puntos_obtenidos" integer, "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH params AS (
    SELECT
      GREATEST(1, LEAST(12, COALESCE(p_month, 1))) AS mm,
      GREATEST(1900, LEAST(9999, COALESCE(p_year, 1900))) AS yy
  ),
  rango AS (
    SELECT
      make_date(yy, mm, 1) AS inicio,
      (make_date(yy, mm, 1) + interval '1 month')::date AS fin
    FROM params
  ),
  allowlist(tipo_evento, subtipo) AS (
    VALUES
      ('reta', 'reta_cierre'),
      ('duelo_2v2', 'duelo_2v2_cierre'),
      ('americano', 'americano_cierre'),
      ('torneo_express', 'express_cierre'),
      ('liga', 'liga_jornada')
  ),
  filtrado AS (
    SELECT
      jp.id,
      jp.jugador_id,
      jp.tipo_evento::text AS tipo_evento,
      jp.evento_id,
      COALESCE(jp.metadata->>'subtipo', '') AS subtipo,
      jp.evento_nombre,
      jp.fecha,
      jp.resultado::text AS resultado,
      jp.puntos_obtenidos,
      jp.metadata,
      jp.created_at
    FROM public.jugador_participaciones jp
    INNER JOIN allowlist al
      ON al.tipo_evento = jp.tipo_evento::text
     AND al.subtipo = COALESCE(jp.metadata->>'subtipo', '')
    CROSS JOIN rango r
    WHERE jp.metadata->>'organizador_id' = p_organizador_id::text
      AND jp.fecha >= r.inicio
      AND jp.fecha < r.fin
      AND NOT public.is_jugador_participacion_excluded(
        jp.jugador_id,
        jp.tipo_evento::text,
        jp.evento_id
      )
  )
  SELECT DISTINCT ON (
    jugador_id,
    tipo_evento,
    evento_id,
    subtipo
  )
    id AS participacion_id,
    jugador_id,
    tipo_evento,
    evento_id,
    subtipo,
    evento_nombre,
    fecha,
    resultado,
    puntos_obtenidos,
    metadata,
    created_at
  FROM filtrado
  ORDER BY
    jugador_id,
    tipo_evento,
    evento_id,
    subtipo,
    created_at DESC,
    id DESC;
$$;


ALTER FUNCTION "public"."_riviera_participaciones_canonicas_mensual"("p_organizador_id" "uuid", "p_year" integer, "p_month" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_riviera_participaciones_canonicas_mensual"("p_organizador_id" "uuid", "p_year" integer, "p_month" integer) IS 'Fuente canónica única de Ranking -> Participaciones. Allowlist fail-closed: reta/reta_cierre, duelo_2v2/duelo_2v2_cierre, americano/americano_cierre, torneo_express/express_cierre, liga/liga_jornada.';



CREATE OR REPLACE FUNCTION "public"."_riviera_profile_link_resolution"("p_jugador_id" "uuid") RETURNS TABLE("jugador_id" "uuid", "jugador_nombre" "text", "jugador_organizador_id" "uuid", "has_profile_link" boolean, "existing_official_player_key" "uuid", "existing_riviera_id" "text", "candidate_official_jugador_id" "uuid", "candidate_nombre" "text", "candidate_riviera_id" "text", "candidate_official_player_key" "uuid", "candidate_count" integer, "grant_to_canonical" boolean, "grant_to_identity" boolean, "same_legacy" boolean, "host_club_overlap" boolean, "cross_club_profile" boolean, "confidence" "text", "reason" "text", "action_sugerida" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH jugador AS (
    SELECT rj.id, rj.nombre, rj.organizador_id, rj.legacy_player_id
    FROM public.riviera_jugadores rj
    WHERE rj.id = p_jugador_id
  ),
  existing_link AS (
    SELECT l.official_player_key, i.riviera_id
    FROM jugador j
    INNER JOIN public.riviera_official_player_profile_link l
      ON l.riviera_jugador_id = j.id
    LEFT JOIN public.riviera_official_player_identity i
      ON i.official_player_key = l.official_player_key
  ),
  host_clubs AS (
    SELECT string_agg(
      DISTINCT COALESCE(
        NULLIF(trim(jp.metadata->>'organizador_id'), ''),
        j.organizador_id::text
      ),
      ', '
    ) AS host_clubs
    FROM jugador j
    LEFT JOIN public.jugador_participaciones jp
      ON jp.jugador_id = j.id
     AND COALESCE(jp.puntos_obtenidos, 0) > 0
  ),
  official_profiles AS (
    SELECT
      rj.id AS jugador_id,
      rj.nombre,
      rj.organizador_id,
      rj.legacy_player_id,
      i.official_player_key,
      i.riviera_id,
      i.canonical_riviera_jugador_id,
      public._riviera_normalize_player_name(rj.nombre) AS name_key
    FROM public.riviera_jugadores rj
    INNER JOIN public.riviera_official_player_profile_link pl
      ON pl.riviera_jugador_id = rj.id
    INNER JOIN public.riviera_official_player_identity i
      ON i.official_player_key = pl.official_player_key
    WHERE rj.estado = 'activo'
      AND i.riviera_id IS NOT NULL
  ),
  official_clubs AS (
    SELECT
      pl.official_player_key,
      array_agg(DISTINCT pl.organizer_id::text) AS organizer_ids
    FROM public.riviera_official_player_profile_link pl
    GROUP BY pl.official_player_key
  ),
  candidate_pairs AS (
    SELECT
      j.id AS orphan_id,
      op.jugador_id AS candidate_id,
      op.nombre AS candidate_nombre,
      op.riviera_id AS candidate_riviera_id,
      op.official_player_key AS candidate_key,
      op.canonical_riviera_jugador_id,
      EXISTS (
        SELECT 1 FROM public.organizer_player_access opa
        WHERE opa.is_active = true
          AND opa.local_jugador_id = j.id
          AND opa.jugador_id = op.canonical_riviera_jugador_id
      ) AS grant_to_canonical,
      EXISTS (
        SELECT 1 FROM public.organizer_player_access opa
        INNER JOIN public.riviera_official_player_profile_link pls
          ON pls.riviera_jugador_id = opa.jugador_id
        WHERE opa.is_active = true
          AND opa.local_jugador_id = j.id
          AND pls.official_player_key = op.official_player_key
      ) AS grant_to_identity,
      (j.legacy_player_id IS NOT NULL AND j.legacy_player_id = op.legacy_player_id) AS same_legacy,
      EXISTS (
        SELECT 1
        FROM unnest(string_to_array(COALESCE(hc.host_clubs, ''), ', ')) AS h(host_org)
        WHERE trim(h.host_org) <> ''
          AND trim(h.host_org) = ANY (
            SELECT unnest(oc.organizer_ids) FROM official_clubs oc
            WHERE oc.official_player_key = op.official_player_key
          )
      ) AS host_club_overlap,
      (j.organizador_id IS DISTINCT FROM op.organizador_id) AS cross_club_profile,
      (
        j.organizador_id = ANY (
          SELECT unnest(oc.organizer_ids)::uuid FROM official_clubs oc
          WHERE oc.official_player_key = op.official_player_key
        )
      ) AS orphan_org_in_official_clubs
    FROM jugador j
    CROSS JOIN host_clubs hc
    INNER JOIN official_profiles op
      ON public._riviera_normalize_player_name(j.nombre) = op.name_key
    WHERE NOT EXISTS (SELECT 1 FROM existing_link)
  ),
  candidate_ranked AS (
    SELECT
      cp.*,
      COUNT(*) OVER (PARTITION BY cp.orphan_id) AS candidate_count,
      ROW_NUMBER() OVER (
        PARTITION BY cp.orphan_id
        ORDER BY
          (cp.grant_to_canonical OR cp.grant_to_identity) DESC,
          cp.same_legacy DESC,
          cp.host_club_overlap DESC,
          cp.candidate_riviera_id NULLS LAST
      ) AS rn
    FROM candidate_pairs cp
  ),
  scored AS (
    SELECT
      cr.*,
      CASE
        WHEN cr.candidate_count > 1 THEN 'REVIEW'
        WHEN cr.candidate_count = 1
          AND (cr.grant_to_canonical OR cr.grant_to_identity OR cr.same_legacy OR cr.host_club_overlap)
        THEN 'HIGH'
        WHEN cr.candidate_count = 1
          AND (cr.cross_club_profile OR cr.orphan_org_in_official_clubs)
        THEN 'REVIEW'
        WHEN cr.candidate_count = 1 THEN 'LOW'
        ELSE 'LOW'
      END AS confidence,
      CASE
        WHEN cr.candidate_count > 1 THEN 'múltiples candidatos oficiales con el mismo nombre'
        WHEN cr.candidate_count = 1 AND (cr.grant_to_canonical OR cr.grant_to_identity) THEN
          'grant activo entre perfil y carrera oficial'
        WHEN cr.candidate_count = 1 AND cr.same_legacy THEN
          'mismo legacy_player_id que perfil oficial'
        WHEN cr.candidate_count = 1 AND cr.host_club_overlap THEN
          'participaciones en club(es) de la identidad oficial'
        WHEN cr.candidate_count = 1 AND (cr.cross_club_profile OR cr.orphan_org_in_official_clubs) THEN
          'solo evidencia débil (nombre/cross-club); requiere revisión manual'
        WHEN cr.candidate_count = 1 THEN 'nombre coincide pero sin evidencia fuerte'
        ELSE 'sin candidato oficial con Riviera ID'
      END AS reason
    FROM candidate_ranked cr
    WHERE cr.rn = 1
  )
  SELECT
    j.id,
    j.nombre,
    j.organizador_id,
    EXISTS (SELECT 1 FROM existing_link),
    (SELECT el.official_player_key FROM existing_link el LIMIT 1),
    (SELECT el.riviera_id::text FROM existing_link el LIMIT 1),
    s.candidate_id,
    s.candidate_nombre,
    s.candidate_riviera_id,
    s.candidate_key,
    COALESCE(s.candidate_count, 0)::integer,
    COALESCE(s.grant_to_canonical, false),
    COALESCE(s.grant_to_identity, false),
    COALESCE(s.same_legacy, false),
    COALESCE(s.host_club_overlap, false),
    COALESCE(s.cross_club_profile, false),
    CASE WHEN EXISTS (SELECT 1 FROM existing_link) THEN 'OK' ELSE COALESCE(s.confidence, 'LOW') END,
    CASE WHEN EXISTS (SELECT 1 FROM existing_link) THEN 'perfil ya enlazado' ELSE COALESCE(s.reason, 'sin candidato oficial con Riviera ID') END,
    CASE
      WHEN EXISTS (SELECT 1 FROM existing_link) THEN 'NONE'
      WHEN COALESCE(s.confidence, 'LOW') = 'HIGH' THEN 'LINK_TO_OFFICIAL'
      WHEN COALESCE(s.confidence, 'LOW') = 'REVIEW' THEN 'MANUAL_REVIEW'
      ELSE 'INSUFFICIENT_EVIDENCE'
    END
  FROM jugador j
  LEFT JOIN scored s ON s.orphan_id = j.id;
$$;


ALTER FUNCTION "public"."_riviera_profile_link_resolution"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_riviera_ranking_interno_scored_roster"("p_organizador_id" "uuid", "p_categoria" "text" DEFAULT NULL::"text", "p_genero" "text" DEFAULT 'M'::"text") RETURNS TABLE("jugador_id" "uuid", "nombre" "text", "puntos" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH revoked_locals AS (
    SELECT DISTINCT opa.local_jugador_id AS id
    FROM public.organizer_player_access opa
    WHERE opa.grantee_organizer_id = p_organizador_id
      AND opa.is_active = false
      AND opa.local_jugador_id IS NOT NULL
  ),
  natives AS (
    SELECT
      rj.id AS jugador_id,
      rj.nombre,
      rj.categoria,
      rj.genero
    FROM public.riviera_jugadores rj
    WHERE rj.organizador_id = p_organizador_id
      AND rj.estado = 'activo'
      AND (p_categoria IS NULL OR rj.categoria = p_categoria)
      AND (
        p_genero IS NULL
        OR (upper(p_genero) IN ('F', 'FEMENIL') AND rj.genero = 'F')
        OR (
          upper(p_genero) IN ('M', 'VARONIL')
          AND (rj.genero = 'M' OR rj.genero IS NULL)
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM revoked_locals rl WHERE rl.id = rj.id
      )
  ),
  active_grants AS (
    SELECT
      opa.jugador_id AS source_jugador_id,
      opa.local_jugador_id,
      opa.local_display_name,
      opa.local_category
    FROM public.organizer_player_access opa
    WHERE opa.grantee_organizer_id = p_organizador_id
      AND opa.is_active = true
  ),
  -- Grants con clon local ya en natives: el roster id sigue siendo el local.
  -- Grants sin clon: fila sintética con id = source (si cat/género coinciden).
  synthetic AS (
    SELECT
      g.source_jugador_id AS jugador_id,
      COALESCE(
        NULLIF(TRIM(g.local_display_name), ''),
        src.nombre,
        'Jugador'
      ) AS nombre
    FROM active_grants g
    JOIN public.riviera_jugadores src
      ON src.id = g.source_jugador_id
     AND src.estado = 'activo'
    WHERE g.local_jugador_id IS NULL
      AND COALESCE(NULLIF(TRIM(g.local_category), ''), src.categoria, 'open')
          = COALESCE(p_categoria, COALESCE(NULLIF(TRIM(g.local_category), ''), src.categoria, 'open'))
      AND (
        p_genero IS NULL
        OR (upper(p_genero) IN ('F', 'FEMENIL') AND src.genero = 'F')
        OR (
          upper(p_genero) IN ('M', 'VARONIL')
          AND (src.genero = 'M' OR src.genero IS NULL)
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM natives n WHERE n.jugador_id = g.source_jugador_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM natives n
        JOIN active_grants g2
          ON g2.local_jugador_id = n.jugador_id
         AND g2.source_jugador_id = g.source_jugador_id
      )
  ),
  roster AS (
    SELECT n.jugador_id, n.nombre FROM natives n
    UNION ALL
    SELECT s.jugador_id, s.nombre FROM synthetic s
  ),
  career_links AS (
    SELECT c.anchor_jugador_id, c.jugador_id AS linked_jugador_id
    FROM public.get_public_career_jugador_ids_batch(
      ARRAY(SELECT r.jugador_id FROM roster r)
    ) c
  ),
  parts AS (
    SELECT
      cl.anchor_jugador_id,
      jp.puntos_obtenidos,
      CASE
        WHEN COALESCE(jp.metadata->>'organizador_id', '') <> '' THEN jp.metadata->>'organizador_id'
        WHEN d.id IS NOT NULL THEN d.organizador_id::text
        WHEN t.id IS NOT NULL THEN t.organizador_id::text
        ELSE NULL
      END AS host_org
    FROM career_links cl
    JOIN public.jugador_participaciones jp
      ON jp.jugador_id = cl.linked_jugador_id
    JOIN public.riviera_jugadores rj
      ON rj.id = jp.jugador_id
     AND rj.estado = 'activo'
    LEFT JOIN public.duelos_2v2 d
      ON jp.tipo_evento = 'duelo_2v2'
     AND jp.evento_id::uuid = d.id
    LEFT JOIN public.torneo_express t
      ON jp.tipo_evento = 'torneo_express'
     AND jp.evento_id::uuid = t.id
    WHERE NOT public.is_jugador_participacion_excluded(
      jp.jugador_id,
      jp.tipo_evento::text,
      jp.evento_id
    )
  ),
  scored AS (
    SELECT
      r.jugador_id,
      r.nombre,
      COALESCE(
        SUM(p.puntos_obtenidos) FILTER (
          WHERE p.host_org = p_organizador_id::text
        ),
        0
      )::integer AS puntos
    FROM roster r
    LEFT JOIN parts p ON p.anchor_jugador_id = r.jugador_id
    GROUP BY r.jugador_id, r.nombre
  )
  SELECT s.jugador_id, s.nombre, s.puntos
  FROM scored s;
$$;


ALTER FUNCTION "public"."_riviera_ranking_interno_scored_roster"("p_organizador_id" "uuid", "p_categoria" "text", "p_genero" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_riviera_ranking_interno_scored_roster"("p_organizador_id" "uuid", "p_categoria" "text", "p_genero" "text") IS 'Roster puntuado del ranking interno (carrera@host + grants). Uso interno por la RPC 1-jugador. REVOKE a anon.';



CREATE OR REPLACE FUNCTION "public"."_safe_resolve_official_player_key"("p_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key uuid;
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;
  BEGIN
    IF to_regprocedure('public.resolve_official_player_key_for_jugador(uuid)') IS NOT NULL THEN
      v_key := public.resolve_official_player_key_for_jugador(p_jugador_id);
      RETURN v_key;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  BEGIN
    IF to_regprocedure('public._resolve_official_player_key(uuid)') IS NOT NULL THEN
      RETURN public._resolve_official_player_key(p_jugador_id);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."_safe_resolve_official_player_key"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_slugify_jugador_nombre"("p_nombre" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT trim(both '-' FROM regexp_replace(
    lower(coalesce(p_nombre, 'jugador')),
    '[^a-z0-9]+',
    '-',
    'g'
  ));
$$;


