CREATE OR REPLACE FUNCTION "public"."actualizar_participacion_jugador_con_ledger"("p_participacion_id" "uuid", "p_evento_nombre" "text", "p_resultado" "public"."jugador_resultado", "p_sets_favor" integer, "p_sets_contra" integer, "p_puntos_obtenidos" integer, "p_pareja_con" "text", "p_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_jugador_organizador uuid;
  v_rows int;
  v_ledger_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT rj.organizador_id INTO v_jugador_organizador
  FROM public.jugador_participaciones jp
  JOIN public.riviera_jugadores rj ON rj.id = jp.jugador_id
  WHERE jp.id = p_participacion_id;

  IF v_jugador_organizador IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_jugador_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'No autorizado para actualizar esta participación';
  END IF;

  UPDATE public.jugador_participaciones
  SET evento_nombre = p_evento_nombre,
      resultado = p_resultado,
      sets_favor = p_sets_favor,
      sets_contra = p_sets_contra,
      puntos_obtenidos = p_puntos_obtenidos,
      pareja_con = coalesce(p_pareja_con, pareja_con),
      metadata = p_metadata
  WHERE id = p_participacion_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  v_ledger_result := public.try_write_riviera_official_ledger(p_participacion_id);

  RETURN jsonb_build_object(
    'ok', true,
    'participacion_id', p_participacion_id,
    'ledger', v_ledger_result
  );
END;
$$;


ALTER FUNCTION "public"."actualizar_participacion_jugador_con_ledger"("p_participacion_id" "uuid", "p_evento_nombre" "text", "p_resultado" "public"."jugador_resultado", "p_sets_favor" integer, "p_sets_contra" integer, "p_puntos_obtenidos" integer, "p_pareja_con" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_organizer_membership_by_riviera_id"("p_riviera_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_grantee uuid := auth.uid();
  v_identity record;
  v_owner uuid;
  v_access_id uuid;
  v_local_id uuid;
  v_existing public.organizer_player_access%ROWTYPE;
  v_created boolean := false;
  v_reactivated boolean := false;
  v_link_created boolean := false;
BEGIN
  IF v_grantee IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  SELECT *
  INTO v_identity
  FROM public._resolve_identity_by_riviera_id(p_riviera_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Riviera ID no encontrado';
  END IF;

  v_owner := v_identity.registration_organizer_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Organizador de Registro no resuelto';
  END IF;

  IF v_owner = v_grantee THEN
    RAISE EXCEPTION 'El jugador ya pertenece a tu organizador de registro';
  END IF;

  PERFORM pg_advisory_xact_lock(
    212012,
    hashtext(v_grantee::text || ':' || v_identity.canonical_riviera_jugador_id::text)
  );

  SELECT *
  INTO v_existing
  FROM public.organizer_player_access opa
  WHERE opa.grantee_organizer_id = v_grantee
    AND opa.jugador_id = v_identity.canonical_riviera_jugador_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.is_active THEN
      v_access_id := v_existing.id;
    ELSE
      UPDATE public.organizer_player_access
      SET
        is_active = true,
        left_at = NULL,
        joined_at = now(),
        joined_via = 'riviera_id',
        access_type = 'granted_by_admin',
        updated_at = now()
      WHERE id = v_existing.id
      RETURNING id INTO v_access_id;

      v_reactivated := true;

      IF v_existing.local_jugador_id IS NOT NULL THEN
        UPDATE public.riviera_jugadores rj
        SET
          estado = 'activo',
          suma_ranking = true,
          updated_at = now()
        WHERE rj.id = v_existing.local_jugador_id
          AND rj.organizador_id = v_grantee;
      END IF;
    END IF;
  ELSE
    INSERT INTO public.organizer_player_access (
      jugador_id,
      owner_organizador_id,
      grantee_organizer_id,
      access_type,
      granted_by_admin_id,
      is_active,
      is_public_ranking,
      joined_at,
      joined_via
    )
    VALUES (
      v_identity.canonical_riviera_jugador_id,
      v_owner,
      v_grantee,
      'granted_by_admin',
      NULL,
      true,
      false,
      now(),
      'riviera_id'
    )
    RETURNING id INTO v_access_id;

    v_created := true;
  END IF;

  v_local_id := public.ensure_granted_player_local(v_identity.canonical_riviera_jugador_id);

  v_link_created := public._link_membership_local_profile(
    v_identity.official_player_key,
    v_local_id,
    v_grantee,
    v_access_id
  );

  RETURN jsonb_build_object(
    'membership_id', v_access_id,
    'local_jugador_id', v_local_id,
    'source_jugador_id', v_identity.canonical_riviera_jugador_id,
    'riviera_id', v_identity.riviera_id,
    'display_name', v_identity.display_name,
    'registration_organizer_id', v_owner,
    'created', v_created,
    'reactivated', v_reactivated,
    'already_member', NOT v_created AND NOT v_reactivated,
    'profile_link_created', v_link_created
  );
END;
$$;


ALTER FUNCTION "public"."add_organizer_membership_by_riviera_id"("p_riviera_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_organizer_membership_by_riviera_id"("p_riviera_id" "text") IS 'Sprint 2.1.2 — Alta de membresía por Riviera ID exacto. Reutiliza Carrera existente; crea clon local + profile_link si faltan. No asigna Riviera ID ni modifica debut. Idempotente si ya activa.';



CREATE OR REPLACE FUNCTION "public"."adjust_coach_student_classes"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_student_id" "uuid", "p_delta" integer, "p_motivo" "text", "p_reference_ledger_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_expected_current_balance" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_trimmed_motivo text := NULLIF(btrim(COALESCE(p_motivo, '')), '');
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_orig record;
  v_rel record;
  v_bal record;
  v_relationship_id uuid;
  v_cur_balance integer;
  v_new_balance integer;
  v_scheduled_count integer;
  v_existing_adj record;
  v_adj_id uuid;
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo el administrador del club puede corregir saldos de clases.');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organizador_game_modes
    WHERE organizador_id = p_organizador_id AND coaching_enabled = true
  ) AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El club no tiene habilitado el módulo de Coaching.');
  END IF;

  IF v_trimmed_motivo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El motivo de la corrección es obligatorio.');
  END IF;

  IF p_delta IS NULL OR p_delta = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El ajuste debe ser una cantidad distinta de cero.');
  END IF;

  IF p_reference_ledger_id IS NOT NULL THEN
    SELECT *
    INTO v_orig
    FROM public.coach_class_ledger
    WHERE id = p_reference_ledger_id AND organizador_id = p_organizador_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Movimiento original referenciado no encontrado o no pertenece a este club.');
    END IF;

    IF v_orig.coach_id <> p_coach_id OR v_orig.jugador_id <> p_student_id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'El movimiento referenciado no coincide con el entrenador y alumno especificados.');
    END IF;

    v_relationship_id := v_orig.relationship_id;
  ELSE
    SELECT id, status, coach_id, jugador_id
    INTO v_rel
    FROM public.coach_player_relationships
    WHERE organizador_id = p_organizador_id
      AND coach_id = p_coach_id
      AND jugador_id = p_student_id
    ORDER BY (status = 'ACTIVE') DESC, created_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'No se encontró la asignación entre este alumno y el entrenador en el club.');
    END IF;

    v_relationship_id := v_rel.id;
  END IF;

  SELECT id, status, coach_id, jugador_id
  INTO v_rel
  FROM public.coach_player_relationships
  WHERE id = v_relationship_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Relación coach-alumno no encontrada.');
  END IF;

  -- GUARDA DE BACKEND: No permitir sumar créditos a relaciones pausadas o terminadas
  IF v_rel.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No se pueden ajustar saldos en una relación en pausa o terminada. El estado actual es: ' || COALESCE(v_rel.status, 'DESCONOCIDO') || '.'
    );
  END IF;

  IF v_trimmed_key IS NOT NULL THEN
    SELECT *
    INTO v_existing_adj
    FROM public.coach_class_ledger
    WHERE idempotency_key = v_trimmed_key;

    IF FOUND THEN
      IF v_existing_adj.recorded_by <> v_caller
         OR v_existing_adj.organizador_id <> p_organizador_id
         OR v_existing_adj.relationship_id <> v_relationship_id
         OR v_existing_adj.coach_id <> p_coach_id
         OR v_existing_adj.jugador_id <> p_student_id
         OR COALESCE(v_existing_adj.reference_ledger_id, '00000000-0000-0000-0000-000000000000'::uuid) <> COALESCE(p_reference_ledger_id, '00000000-0000-0000-0000-000000000000'::uuid)
         OR v_existing_adj.delta <> p_delta
         OR v_existing_adj.tipo <> 'ADJUSTMENT' THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de idempotencia: la clave ya fue utilizada en otra operación o con parámetros distintos.'
        );
      END IF;

      SELECT balance_classes INTO v_cur_balance
      FROM public.coach_player_class_balances
      WHERE relationship_id = v_relationship_id;

      RETURN jsonb_build_object(
        'ok', true,
        'idempotent', true,
        'adjustment_id', v_existing_adj.id,
        'delta', v_existing_adj.delta,
        'previous_balance', v_cur_balance - v_existing_adj.delta,
        'new_balance', v_cur_balance,
        'message', 'Ajuste completado previamente (idempotente).'
      );
    END IF;
  END IF;

  SELECT *
  INTO v_bal
  FROM public.coach_player_class_balances
  WHERE relationship_id = v_relationship_id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.coach_player_class_balances (
      relationship_id, organizador_id, coach_id, jugador_id, balance_classes, total_classes_given, updated_at
    ) VALUES (
      v_relationship_id, p_organizador_id, p_coach_id, p_student_id, 0, 0, v_now
    ) RETURNING * INTO v_bal;
  END IF;

  v_cur_balance := COALESCE(v_bal.balance_classes, 0);

  IF p_expected_current_balance IS NOT NULL AND v_cur_balance <> p_expected_current_balance THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El saldo actual (' || v_cur_balance || ') no coincide con el esperado (' || p_expected_current_balance || '). Refresca los datos antes de continuar.'
    );
  END IF;

  v_new_balance := v_cur_balance + p_delta;
  IF v_new_balance < 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El ajuste resultaría en un saldo negativo (' || v_new_balance || '). El saldo actual es ' || v_cur_balance || '.'
    );
  END IF;

  SELECT count(*)
  INTO v_scheduled_count
  FROM public.coach_sessions
  WHERE relationship_id = v_relationship_id AND status = 'SCHEDULED';

  IF v_new_balance < v_scheduled_count THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El nuevo saldo (' || v_new_balance || ') no puede ser menor a las ' || v_scheduled_count || ' clases agendadas pendientes.'
    );
  END IF;

  UPDATE public.coach_player_class_balances
  SET balance_classes = v_new_balance,
      updated_at = v_now
  WHERE relationship_id = v_relationship_id;

  INSERT INTO public.coach_class_ledger (
    relationship_id,
    organizador_id,
    coach_id,
    jugador_id,
    delta,
    tipo,
    notas,
    reference_ledger_id,
    idempotency_key,
    recorded_by,
    created_at
  ) VALUES (
    v_relationship_id,
    p_organizador_id,
    p_coach_id,
    p_student_id,
    p_delta,
    'ADJUSTMENT',
    v_trimmed_motivo,
    p_reference_ledger_id,
    v_trimmed_key,
    v_caller,
    v_now
  ) RETURNING id INTO v_adj_id;

  INSERT INTO public.coach_audit_log (
    actor_auth_user_id,
    action,
    entity_type,
    entity_id,
    payload,
    created_at
  ) VALUES (
    v_caller,
    'BALANCE_ADJUSTED',
    'coach_player_class_balances',
    v_relationship_id,
    jsonb_build_object(
      'delta', p_delta,
      'previous_balance', v_cur_balance,
      'new_balance', v_new_balance,
      'motivo', v_trimmed_motivo,
      'reference_ledger_id', p_reference_ledger_id,
      'adjustment_id', v_adj_id,
      'idempotency_key', v_trimmed_key
    ),
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'adjustment_id', v_adj_id,
    'delta', p_delta,
    'previous_balance', v_cur_balance,
    'new_balance', v_new_balance,
    'message', 'Saldo corregido exitosamente (' || (CASE WHEN p_delta > 0 THEN '+' ELSE '' END) || p_delta || ' clases).'
  );
END;
$$;


ALTER FUNCTION "public"."adjust_coach_student_classes"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_student_id" "uuid", "p_delta" integer, "p_motivo" "text", "p_reference_ledger_id" "uuid", "p_idempotency_key" "text", "p_expected_current_balance" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_official_player_identity_from_jugador"("p_riviera_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_nombre text;
  v_points integer;
  v_profile_link_id uuid;
  v_official_key uuid;
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede crear identidad oficial';
  END IF;

  IF p_riviera_jugador_id IS NULL THEN
    RAISE EXCEPTION 'Jugador requerido';
  END IF;

  -- Punto de entrada único para crear/reutilizar Carrera Deportiva + Riviera ID
  v_result := public.ensure_riviera_identity(p_riviera_jugador_id);

  v_official_key := (v_result ->> 'official_player_key')::uuid;

  SELECT rj.nombre
  INTO v_nombre
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_riviera_jugador_id;

  SELECT l.id
  INTO v_profile_link_id
  FROM public.riviera_official_player_profile_link l
  WHERE l.riviera_jugador_id = p_riviera_jugador_id
  LIMIT 1;

  SELECT coalesce(t.points_total, 0)
  INTO v_points
  FROM public.riviera_official_player_totals t
  WHERE t.official_player_key = v_official_key;

  RETURN jsonb_build_object(
    'official_player_key', v_official_key,
    'canonical_riviera_jugador_id', v_result -> 'registration_jugador_id',
    'canonical_nombre', v_nombre,
    'profile_link_id', v_profile_link_id,
    'points_total', coalesce(v_points, 0),
    'riviera_id', v_result -> 'riviera_id',
    'riviera_id_serial', v_result -> 'riviera_id_serial',
    'debut_organizer_id', v_result -> 'debut_organizer_id',
    'debut_at', v_result -> 'debut_at',
    'identity_created', v_result -> 'identity_created',
    'link_created', v_result -> 'link_created',
    'riviera_id_assigned', v_result -> 'riviera_id_assigned',
    'debut_assigned', v_result -> 'debut_assigned',
    'ensure', v_result
  );
END;
$$;


ALTER FUNCTION "public"."admin_create_official_player_identity_from_jugador"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_create_official_player_identity_from_jugador"("p_riviera_jugador_id" "uuid") IS 'Sprint 2.0.2A — Wrapper admin que delega en ensure_riviera_identity. No inserta identidad directamente. Idempotente si el jugador ya tiene carrera.';



CREATE OR REPLACE FUNCTION "public"."admin_delete_liga_cascade"("p_organizador_id" "uuid", "p_liga_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner uuid;
  v_partido_id uuid;
  v_participacion_id uuid;
  v_participaciones_revertidas int := 0;
  v_rating_revertido int := 0;
BEGIN
  IF p_organizador_id IS NULL OR p_liga_id IS NULL THEN
    RAISE EXCEPTION 'Parámetros incompletos';
  END IF;

  SELECT organizador_id INTO v_owner FROM ligas WHERE id = p_liga_id;
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found', 'liga_id', p_liga_id);
  END IF;

  IF auth.uid() IS NULL OR (v_owner IS DISTINCT FROM auth.uid() AND NOT public.is_master_admin()) THEN
    RAISE EXCEPTION 'Sin permiso para eliminar esta liga' USING ERRCODE = '42501';
  END IF;
  IF v_owner IS DISTINCT FROM p_organizador_id THEN
    RAISE EXCEPTION 'p_organizador_id no coincide con el dueño real de la liga' USING ERRCODE = '42501';
  END IF;

  -- 1) Revertir rating de cada partido de la liga.
  FOR v_partido_id IN
    SELECT lp.id
    FROM liga_partidos lp
    JOIN liga_jornadas lj ON lj.id = lp.jornada_id
    WHERE lj.liga_id = p_liga_id
  LOOP
    PERFORM public._revert_rating_for_partido_ref('liga:' || v_partido_id::text);
    v_rating_revertido := v_rating_revertido + 1;
  END LOOP;

  -- 2) Revertir ledger y borrar participaciones de esta liga -- evento_id
  --    históricamente se guardó a veces como ligas.id, a veces como
  --    liga_jornadas.id (confirmado en auditoría de solo lectura), así que
  --    se cubren ambos.
  FOR v_participacion_id IN
    SELECT id FROM jugador_participaciones
    WHERE tipo_evento = 'liga'
      AND (
        evento_id = p_liga_id
        OR evento_id IN (SELECT id FROM liga_jornadas WHERE liga_id = p_liga_id)
      )
  LOOP
    PERFORM public._reverse_ledger_for_participacion_safe(v_participacion_id);
    DELETE FROM jugador_participaciones WHERE id = v_participacion_id;
    v_participaciones_revertidas := v_participaciones_revertidas + 1;
  END LOOP;

  -- 3) Borrar la liga. Verificado vía pg_constraint (2026-07-29): todo el
  --    árbol (liga_jornadas, liga_partidos, liga_jornada_parejas,
  --    liga_inscripciones, liga_equipos) ya tiene ON DELETE CASCADE hacia
  --    ligas -- no hace falta borrarlo a mano.
  DELETE FROM ligas WHERE id = p_liga_id;

  RETURN jsonb_build_object(
    'status', 'deleted',
    'liga_id', p_liga_id,
    'participaciones_revertidas', v_participaciones_revertidas,
    'partidos_rating_revertido', v_rating_revertido
  );
END;
$$;


ALTER FUNCTION "public"."admin_delete_liga_cascade"("p_organizador_id" "uuid", "p_liga_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_torneo_express_categoria_cascade"("p_organizador_id" "uuid", "p_torneo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner uuid;
  v_partido_id uuid;
  v_participacion_id uuid;
  v_participaciones_revertidas int := 0;
  v_rating_revertido int := 0;
BEGIN
  IF p_organizador_id IS NULL OR p_torneo_id IS NULL THEN
    RAISE EXCEPTION 'Parámetros incompletos';
  END IF;

  SELECT organizador_id INTO v_owner FROM torneo_express WHERE id = p_torneo_id;
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found', 'torneo_id', p_torneo_id);
  END IF;

  IF auth.uid() IS NULL OR (v_owner IS DISTINCT FROM auth.uid() AND NOT public.is_master_admin()) THEN
    RAISE EXCEPTION 'Sin permiso para eliminar este torneo' USING ERRCODE = '42501';
  END IF;
  IF v_owner IS DISTINCT FROM p_organizador_id THEN
    RAISE EXCEPTION 'p_organizador_id no coincide con el dueño real del torneo' USING ERRCODE = '42501';
  END IF;

  -- 1) Revertir rating de cada partido de grupo.
  FOR v_partido_id IN
    SELECT tep.id
    FROM torneo_express_partidos tep
    JOIN torneo_express_grupos g ON g.id = tep.grupo_id
    WHERE g.torneo_id = p_torneo_id
  LOOP
    PERFORM public._revert_rating_for_partido_ref('te-grupo:' || v_partido_id::text);
    v_rating_revertido := v_rating_revertido + 1;
  END LOOP;

  -- 2) Revertir rating de cada partido de eliminatoria.
  FOR v_partido_id IN
    SELECT teep.id
    FROM torneo_express_eliminatoria_partidos teep
    WHERE teep.torneo_id = p_torneo_id
  LOOP
    PERFORM public._revert_rating_for_partido_ref('te-elim:' || v_partido_id::text);
    v_rating_revertido := v_rating_revertido + 1;
  END LOOP;

  -- 3) Revertir ledger y borrar participaciones de este torneo.
  FOR v_participacion_id IN
    SELECT id FROM jugador_participaciones
    WHERE tipo_evento = 'torneo_express' AND evento_id = p_torneo_id
  LOOP
    PERFORM public._reverse_ledger_for_participacion_safe(v_participacion_id);
    DELETE FROM jugador_participaciones WHERE id = v_participacion_id;
    v_participaciones_revertidas := v_participaciones_revertidas + 1;
  END LOOP;

  -- 4) Borrar el torneo. Verificado vía pg_constraint (2026-07-29): todo el
  --    árbol (torneo_express_grupos, torneo_express_partidos,
  --    torneo_express_grupo_parejas, torneo_express_eliminatoria_partidos,
  --    notificaciones_log, notificaciones_eventos_queue) ya tiene
  --    ON DELETE CASCADE hacia torneo_express -- no hace falta borrarlo a
  --    mano ni replicar ese orden aquí.
  DELETE FROM torneo_express WHERE id = p_torneo_id;

  RETURN jsonb_build_object(
    'status', 'deleted',
    'torneo_id', p_torneo_id,
    'participaciones_revertidas', v_participaciones_revertidas,
    'partidos_rating_revertido', v_rating_revertido
  );
END;
$$;


ALTER FUNCTION "public"."admin_delete_torneo_express_categoria_cascade"("p_organizador_id" "uuid", "p_torneo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_user_completo"("p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_uid uuid := p_target_user_id;
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'No tienes permisos de administrador maestro';
  END IF;

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario inválido';
  END IF;

  IF v_uid = auth.uid() THEN
    RAISE EXCEPTION 'No puedes eliminar tu propia cuenta desde el panel';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = v_uid) THEN
    RAISE EXCEPTION 'Usuario no encontrado';
  END IF;

  -- ── Notificaciones (Torneo Express) — columna torneo_express_id ──
  IF to_regclass('public.notificaciones_log') IS NOT NULL
     AND to_regclass('public.torneo_express') IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'notificaciones_log'
         AND column_name = 'torneo_express_id'
     ) THEN
    DELETE FROM public.notificaciones_log
    WHERE torneo_express_id IN (
      SELECT id FROM public.torneo_express WHERE organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.notificaciones_eventos_queue') IS NOT NULL
     AND to_regclass('public.torneo_express') IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'notificaciones_eventos_queue'
         AND column_name = 'torneo_express_id'
     ) THEN
    DELETE FROM public.notificaciones_eventos_queue
    WHERE torneo_express_id IN (
      SELECT id FROM public.torneo_express WHERE organizador_id = v_uid
    );
  END IF;

  -- ── Torneo Express (hijos → padre). Schema actual: torneo_id / grupo_id ──
  IF to_regclass('public.torneo_express_partidos') IS NOT NULL
     AND to_regclass('public.torneo_express_grupos') IS NOT NULL THEN
    DELETE FROM public.torneo_express_partidos
    WHERE grupo_id IN (
      SELECT g.id
      FROM public.torneo_express_grupos g
      JOIN public.torneo_express te ON te.id = g.torneo_id
      WHERE te.organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.torneo_express_grupo_parejas') IS NOT NULL
     AND to_regclass('public.torneo_express_grupos') IS NOT NULL THEN
    DELETE FROM public.torneo_express_grupo_parejas
    WHERE grupo_id IN (
      SELECT g.id
      FROM public.torneo_express_grupos g
      JOIN public.torneo_express te ON te.id = g.torneo_id
      WHERE te.organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.torneo_express_eliminatoria_partidos') IS NOT NULL THEN
    DELETE FROM public.torneo_express_eliminatoria_partidos
    WHERE torneo_id IN (
      SELECT id FROM public.torneo_express WHERE organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.torneo_express_grupos') IS NOT NULL THEN
    DELETE FROM public.torneo_express_grupos
    WHERE torneo_id IN (
      SELECT id FROM public.torneo_express WHERE organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.torneo_express') IS NOT NULL THEN
    DELETE FROM public.torneo_express WHERE organizador_id = v_uid;
  END IF;

  -- ── Liga ──
  IF to_regclass('public.liga_partidos') IS NOT NULL THEN
    DELETE FROM public.liga_partidos
    WHERE jornada_id IN (
      SELECT j.id
      FROM public.liga_jornadas j
      JOIN public.ligas l ON l.id = j.liga_id
      WHERE l.organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.liga_jornada_parejas') IS NOT NULL THEN
    DELETE FROM public.liga_jornada_parejas
    WHERE jornada_id IN (
      SELECT j.id
      FROM public.liga_jornadas j
      JOIN public.ligas l ON l.id = j.liga_id
      WHERE l.organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.liga_jornadas') IS NOT NULL THEN
    DELETE FROM public.liga_jornadas
    WHERE liga_id IN (SELECT id FROM public.ligas WHERE organizador_id = v_uid);
  END IF;

  IF to_regclass('public.liga_inscripciones') IS NOT NULL THEN
    DELETE FROM public.liga_inscripciones
    WHERE liga_id IN (SELECT id FROM public.ligas WHERE organizador_id = v_uid);
  END IF;

  IF to_regclass('public.liga_equipos') IS NOT NULL THEN
    DELETE FROM public.liga_equipos
    WHERE liga_id IN (SELECT id FROM public.ligas WHERE organizador_id = v_uid);
  END IF;

  IF to_regclass('public.ligas') IS NOT NULL THEN
    DELETE FROM public.ligas WHERE organizador_id = v_uid;
  END IF;

  IF to_regclass('public.liga_jugadores') IS NOT NULL THEN
    DELETE FROM public.liga_jugadores WHERE organizador_id = v_uid;
  END IF;

  -- ── Duelos 2v2 (antes de riviera_jugadores por FK) ──
  IF to_regclass('public.duelos_2v2') IS NOT NULL THEN
    DELETE FROM public.duelos_2v2 WHERE organizador_id = v_uid;
  END IF;

  -- ── Reta abierta / convocatoria ──
  IF to_regclass('public.reta_abierta_inscripciones') IS NOT NULL
     AND to_regclass('public.reta_abierta') IS NOT NULL THEN
    DELETE FROM public.reta_abierta_inscripciones
    WHERE convocatoria_id IN (
      SELECT id FROM public.reta_abierta WHERE organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.reta_abierta') IS NOT NULL THEN
    DELETE FROM public.reta_abierta WHERE organizador_id = v_uid;
  END IF;

  -- ── Registro Riviera Open ──
  IF to_regclass('public.jugador_participaciones') IS NOT NULL THEN
    DELETE FROM public.jugador_participaciones
    WHERE jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.rating_historial') IS NOT NULL THEN
    DELETE FROM public.rating_historial
    WHERE jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.jugador_stats') IS NOT NULL THEN
    DELETE FROM public.jugador_stats
    WHERE jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    );
  END IF;

  -- ── ROMC / identidad oficial (FK RESTRICT hacia riviera_jugadores) ──
  IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
    DELETE FROM public.riviera_official_points_ledger
    WHERE source_local_jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    )
       OR source_organizer_id = v_uid
       OR official_player_key IN (
            SELECT i.official_player_key
            FROM public.riviera_official_player_identity i
            WHERE i.canonical_riviera_jugador_id IN (
              SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
            )
          );
  END IF;

  IF to_regclass('public.jugador_participacion_exclusiones') IS NOT NULL THEN
    DELETE FROM public.jugador_participacion_exclusiones
    WHERE scope_jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    )
       OR official_player_key IN (
            SELECT i.official_player_key
            FROM public.riviera_official_player_identity i
            WHERE i.canonical_riviera_jugador_id IN (
              SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
            )
          );
  END IF;

  IF to_regclass('public.riviera_player_sharing_request') IS NOT NULL THEN
    DELETE FROM public.riviera_player_sharing_request
    WHERE riviera_jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    )
       OR registration_jugador_id IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          );
  END IF;

  -- Reasignar o borrar identidades cuyo canonical pertenece a esta cuenta.
  -- (sin UPDATE…FROM LATERAL: Postgres marca "invalid reference to FROM-clause entry for table i")
  IF to_regclass('public.riviera_official_player_identity') IS NOT NULL THEN
    IF to_regclass('public.riviera_official_player_profile_link') IS NOT NULL THEN
      UPDATE public.riviera_official_player_identity i
      SET canonical_riviera_jugador_id = (
        SELECT l.riviera_jugador_id
        FROM public.riviera_official_player_profile_link l
        WHERE l.official_player_key = i.official_player_key
          AND l.riviera_jugador_id NOT IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          )
        ORDER BY l.created_at
        LIMIT 1
      )
      WHERE i.canonical_riviera_jugador_id IN (
        SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
      )
        AND EXISTS (
          SELECT 1
          FROM public.riviera_official_player_profile_link l
          WHERE l.official_player_key = i.official_player_key
            AND l.riviera_jugador_id NOT IN (
              SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
            )
        );

      DELETE FROM public.riviera_official_player_profile_link
      WHERE riviera_jugador_id IN (
        SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
      );
    END IF;

    IF to_regclass('public.riviera_official_player_totals') IS NOT NULL THEN
      DELETE FROM public.riviera_official_player_totals
      WHERE official_player_key IN (
        SELECT i.official_player_key
        FROM public.riviera_official_player_identity i
        WHERE i.canonical_riviera_jugador_id IN (
          SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
        )
      );
    END IF;

    IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
      DELETE FROM public.riviera_official_points_ledger
      WHERE official_player_key IN (
        SELECT i.official_player_key
        FROM public.riviera_official_player_identity i
        WHERE i.canonical_riviera_jugador_id IN (
          SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
        )
      );
    END IF;

    DELETE FROM public.riviera_official_player_identity
    WHERE canonical_riviera_jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    );
  ELSIF to_regclass('public.riviera_official_player_profile_link') IS NOT NULL THEN
    DELETE FROM public.riviera_official_player_profile_link
    WHERE riviera_jugador_id IN (
      SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
    );
  END IF;

  IF to_regclass('public.organizer_player_access') IS NOT NULL THEN
    DELETE FROM public.organizer_player_access
    WHERE grantee_organizer_id = v_uid
       OR owner_organizador_id = v_uid
       OR jugador_id IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          )
       OR local_jugador_id IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          );
  END IF;

  -- Coaching ledger / vínculos con RESTRICT hacia riviera_jugadores
  IF to_regclass('public.coach_class_ledger') IS NOT NULL THEN
    DELETE FROM public.coach_class_ledger
    WHERE organizador_id = v_uid
       OR jugador_id IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          )
       OR (
            to_regclass('public.riviera_coaches') IS NOT NULL
            AND coach_id IN (
              SELECT id FROM public.riviera_coaches WHERE auth_user_id = v_uid
            )
          );
  END IF;

  IF to_regclass('public.coach_sessions') IS NOT NULL THEN
    DELETE FROM public.coach_sessions
    WHERE organizador_id = v_uid
       OR (
            to_regclass('public.riviera_coaches') IS NOT NULL
            AND coach_id IN (
              SELECT id FROM public.riviera_coaches WHERE auth_user_id = v_uid
            )
          );
  END IF;

  IF to_regclass('public.coach_player_relationships') IS NOT NULL THEN
    DELETE FROM public.coach_player_relationships
    WHERE organizador_id = v_uid
       OR jugador_id IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          )
       OR (
            to_regclass('public.riviera_coaches') IS NOT NULL
            AND coach_id IN (
              SELECT id FROM public.riviera_coaches WHERE auth_user_id = v_uid
            )
          );
  END IF;

  IF to_regclass('public.coach_student_invitations') IS NOT NULL THEN
    DELETE FROM public.coach_student_invitations
    WHERE organizador_id = v_uid
       OR jugador_id IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          );
  END IF;

  IF to_regclass('public.coach_student_account_links') IS NOT NULL THEN
    DELETE FROM public.coach_student_account_links
    WHERE organizador_id = v_uid
       OR jugador_id IN (
            SELECT id FROM public.riviera_jugadores WHERE organizador_id = v_uid
          );
  END IF;

  IF to_regclass('public.coach_club_memberships') IS NOT NULL THEN
    DELETE FROM public.coach_club_memberships
    WHERE organizador_id = v_uid
       OR (
            to_regclass('public.riviera_coaches') IS NOT NULL
            AND coach_id IN (
              SELECT id FROM public.riviera_coaches WHERE auth_user_id = v_uid
            )
          );
  END IF;

  -- La bitácora de membresía apuntaba al coach con ON DELETE RESTRICT y
  -- abortaba el borrado aunque la cuenta no tuviera clases ni alumnos.
  IF to_regclass('public.coach_club_membership_audit_log') IS NOT NULL THEN
    DELETE FROM public.coach_club_membership_audit_log
    WHERE to_regclass('public.riviera_coaches') IS NOT NULL
      AND coach_id IN (
        SELECT id FROM public.riviera_coaches WHERE auth_user_id = v_uid
      );
  END IF;

  IF to_regclass('public.riviera_coaches') IS NOT NULL THEN
    DELETE FROM public.riviera_coaches
    WHERE auth_user_id = v_uid;
  END IF;

  IF to_regclass('public.riviera_jugadores') IS NOT NULL THEN
    DELETE FROM public.riviera_jugadores WHERE organizador_id = v_uid;
  END IF;

  -- ── Retas clásicas ──
  IF to_regclass('public.games') IS NOT NULL
     AND to_regclass('public.matches') IS NOT NULL
     AND to_regclass('public.tournaments') IS NOT NULL THEN
    DELETE FROM public.games
    WHERE match_id IN (
      SELECT m.id
      FROM public.matches m
      JOIN public.tournaments t ON t.id = m.tournament_id
      WHERE t.user_id = v_uid
    );
  END IF;

  IF to_regclass('public.matches') IS NOT NULL
     AND to_regclass('public.tournaments') IS NOT NULL THEN
    DELETE FROM public.matches
    WHERE tournament_id IN (SELECT id FROM public.tournaments WHERE user_id = v_uid);
  END IF;

  IF to_regclass('public.pairs') IS NOT NULL
     AND to_regclass('public.tournaments') IS NOT NULL THEN
    DELETE FROM public.pairs
    WHERE tournament_id IN (SELECT id FROM public.tournaments WHERE user_id = v_uid);
  END IF;

  IF to_regclass('public.tournament_public_config') IS NOT NULL
     AND to_regclass('public.tournaments') IS NOT NULL THEN
    DELETE FROM public.tournament_public_config
    WHERE tournament_id IN (SELECT id FROM public.tournaments WHERE user_id = v_uid);
  END IF;

  IF to_regclass('public.players') IS NOT NULL
     AND to_regclass('public.tournaments') IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'players'
         AND column_name = 'tournament_id'
     ) THEN
    DELETE FROM public.players
    WHERE tournament_id IN (SELECT id FROM public.tournaments WHERE user_id = v_uid);
  END IF;

  IF to_regclass('public.tournaments') IS NOT NULL THEN
    DELETE FROM public.tournaments WHERE user_id = v_uid;
  END IF;

  IF to_regclass('public.players') IS NOT NULL THEN
    DELETE FROM public.players WHERE user_id = v_uid;
  END IF;

  IF to_regclass('public.pairs') IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'pairs'
         AND column_name = 'user_id'
     ) THEN
    DELETE FROM public.pairs WHERE user_id = v_uid;
  END IF;

  IF to_regclass('public.matches') IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'matches'
         AND column_name = 'user_id'
     ) THEN
    DELETE FROM public.matches WHERE user_id = v_uid;
  END IF;

  IF to_regclass('public.games') IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'games'
         AND column_name = 'user_id'
     ) THEN
    DELETE FROM public.games WHERE user_id = v_uid;
  END IF;

  -- ── Config admin por cuenta ──
  IF to_regclass('public.organizador_game_modes') IS NOT NULL THEN
    DELETE FROM public.organizador_game_modes WHERE organizador_id = v_uid;
  END IF;

  IF to_regclass('public.organizador_account_settings') IS NOT NULL THEN
    DELETE FROM public.organizador_account_settings WHERE organizador_id = v_uid;
  END IF;

  -- ── Perfil público y auth ──
  DELETE FROM public.users WHERE id = v_uid;
  DELETE FROM auth.users WHERE id = v_uid;

  RETURN jsonb_build_object('ok', true, 'user_id', v_uid);
END;
$$;


ALTER FUNCTION "public"."admin_delete_user_completo"("p_target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_official_player_identity_by_jugador"("p_riviera_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key uuid;
  v_identity record;
  v_profiles jsonb;
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede consultar identidades oficiales';
  END IF;

  v_key := public._resolve_official_player_key(p_riviera_jugador_id);

  IF v_key IS NULL THEN
    SELECT l.official_player_key
    INTO v_key
    FROM public.riviera_official_player_profile_link l
    WHERE l.riviera_jugador_id = p_riviera_jugador_id;
  END IF;

  IF v_key IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT
    i.official_player_key,
    i.canonical_riviera_jugador_id,
    i.created_at,
    cj.nombre AS canonical_nombre,
    coalesce(t.points_total, 0) AS points_total
  INTO v_identity
  FROM public.riviera_official_player_identity i
  LEFT JOIN public.riviera_official_player_totals t
    ON t.official_player_key = i.official_player_key
  LEFT JOIN public.riviera_jugadores cj
    ON cj.id = i.canonical_riviera_jugador_id
  WHERE i.official_player_key = v_key;

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'profile_link_id', l.id,
        'riviera_jugador_id', l.riviera_jugador_id,
        'jugador_nombre', rj.nombre,
        'organizer_id', l.organizer_id,
        'organizer_name', coalesce(u.name, u.email, 'Organizador'),
        'link_source', l.link_source,
        'organizer_player_access_id', l.organizer_player_access_id,
        'created_at', l.created_at
      )
      ORDER BY l.created_at
    ),
    '[]'::jsonb
  )
  INTO v_profiles
  FROM public.riviera_official_player_profile_link l
  JOIN public.riviera_jugadores rj ON rj.id = l.riviera_jugador_id
  LEFT JOIN public.users u ON u.id = l.organizer_id
  WHERE l.official_player_key = v_key;

  RETURN jsonb_build_object(
    'official_player_key', v_identity.official_player_key,
    'canonical_riviera_jugador_id', v_identity.canonical_riviera_jugador_id,
    'canonical_nombre', v_identity.canonical_nombre,
    'points_total', v_identity.points_total,
    'created_at', v_identity.created_at,
    'profiles', v_profiles
  );
END;
$$;


ALTER FUNCTION "public"."admin_get_official_player_identity_by_jugador"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_grant_organizer_player_access"("p_jugador_ids" "uuid"[], "p_grantee_organizer_id" "uuid", "p_is_public_ranking" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin uuid := auth.uid();
  v_jugador_id uuid;
  v_owner uuid;
  v_granted int := 0;
  v_reactivated int := 0;
  v_skipped int := 0;
  v_was_active boolean;
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede otorgar acceso';
  END IF;

  IF p_grantee_organizer_id IS NULL THEN
    RAISE EXCEPTION 'Organizador destino requerido';
  END IF;

  IF p_jugador_ids IS NULL OR array_length(p_jugador_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Selecciona al menos un jugador';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_grantee_organizer_id) THEN
    RAISE EXCEPTION 'Organizador destino no encontrado';
  END IF;

  FOREACH v_jugador_id IN ARRAY p_jugador_ids LOOP
    SELECT rj.organizador_id
    INTO v_owner
    FROM public.riviera_jugadores rj
    WHERE rj.id = v_jugador_id;

    IF NOT FOUND THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    IF v_owner = p_grantee_organizer_id THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    SELECT opa.is_active
    INTO v_was_active
    FROM public.organizer_player_access opa
    WHERE opa.grantee_organizer_id = p_grantee_organizer_id
      AND opa.jugador_id = v_jugador_id;

    IF FOUND THEN
      IF v_was_active THEN
        v_skipped := v_skipped + 1;
        UPDATE public.organizer_player_access
        SET is_public_ranking = coalesce(p_is_public_ranking, organizer_player_access.is_public_ranking),
            updated_at = now()
        WHERE grantee_organizer_id = p_grantee_organizer_id
          AND jugador_id = v_jugador_id;
      ELSE
        UPDATE public.organizer_player_access
        SET is_active = true,
            granted_by_admin_id = v_admin,
            is_public_ranking = coalesce(p_is_public_ranking, organizer_player_access.is_public_ranking),
            updated_at = now()
        WHERE grantee_organizer_id = p_grantee_organizer_id
          AND jugador_id = v_jugador_id;

        UPDATE public.riviera_jugadores rj
        SET estado = 'activo',
            suma_ranking = true,
            visible_publico = CASE
              WHEN coalesce(p_is_public_ranking, opa.is_public_ranking) THEN true
              ELSE rj.visible_publico
            END,
            updated_at = now()
        FROM public.organizer_player_access opa
        WHERE opa.grantee_organizer_id = p_grantee_organizer_id
          AND opa.jugador_id = v_jugador_id
          AND opa.local_jugador_id = rj.id
          AND rj.organizador_id = p_grantee_organizer_id;

        v_reactivated := v_reactivated + 1;
      END IF;
    ELSE
      INSERT INTO public.organizer_player_access (
        jugador_id,
        owner_organizador_id,
        grantee_organizer_id,
        access_type,
        granted_by_admin_id,
        is_active,
        is_public_ranking
      )
      VALUES (
        v_jugador_id,
        v_owner,
        p_grantee_organizer_id,
        'granted_by_admin',
        v_admin,
        true,
        coalesce(p_is_public_ranking, false)
      );
      v_granted := v_granted + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'granted', v_granted,
    'reactivated', v_reactivated,
    'skipped', v_skipped
  );
END;
$$;


ALTER FUNCTION "public"."admin_grant_organizer_player_access"("p_jugador_ids" "uuid"[], "p_grantee_organizer_id" "uuid", "p_is_public_ranking" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_link_official_player_profile"("p_official_player_key" "uuid", "p_riviera_jugador_id" "uuid", "p_link_source" "text" DEFAULT 'manual_admin'::"text", "p_organizer_player_access_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin uuid := auth.uid();
  v_jugador record;
  v_link_id uuid;
  v_source text;
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede vincular perfiles oficiales';
  END IF;

  IF p_official_player_key IS NULL OR p_riviera_jugador_id IS NULL THEN
    RAISE EXCEPTION 'Identidad y jugador requeridos';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.riviera_official_player_identity i
    WHERE i.official_player_key = p_official_player_key
  ) THEN
    RAISE EXCEPTION 'Identidad oficial no encontrada';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.riviera_official_player_profile_link l
    WHERE l.riviera_jugador_id = p_riviera_jugador_id
  ) THEN
    RAISE EXCEPTION 'Este jugador ya está vinculado a otra identidad oficial';
  END IF;

  v_source := coalesce(nullif(trim(p_link_source), ''), 'manual_admin');
  IF v_source NOT IN ('owner', 'granted_origin', 'granted_local', 'manual_admin') THEN
    RAISE EXCEPTION 'link_source inválido';
  END IF;

  IF p_organizer_player_access_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.organizer_player_access opa
      WHERE opa.id = p_organizer_player_access_id
        AND opa.is_active = true
        AND (
          opa.jugador_id = p_riviera_jugador_id
          OR opa.local_jugador_id = p_riviera_jugador_id
        )
    ) THEN
      RAISE EXCEPTION 'Acceso concedido no válido para este jugador';
    END IF;
  END IF;

  SELECT rj.id, rj.organizador_id, rj.nombre
  INTO v_jugador
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_riviera_jugador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jugador no encontrado';
  END IF;

  INSERT INTO public.riviera_official_player_profile_link (
    official_player_key,
    riviera_jugador_id,
    organizer_id,
    link_source,
    organizer_player_access_id,
    created_by
  )
  VALUES (
    p_official_player_key,
    p_riviera_jugador_id,
    v_jugador.organizador_id,
    v_source,
    p_organizer_player_access_id,
    v_admin
  )
  RETURNING id INTO v_link_id;

  RETURN jsonb_build_object(
    'profile_link_id', v_link_id,
    'official_player_key', p_official_player_key,
    'riviera_jugador_id', p_riviera_jugador_id,
    'jugador_nombre', v_jugador.nombre,
    'organizer_id', v_jugador.organizador_id,
    'link_source', v_source
  );
END;
$$;


ALTER FUNCTION "public"."admin_link_official_player_profile"("p_official_player_key" "uuid", "p_riviera_jugador_id" "uuid", "p_link_source" "text", "p_organizer_player_access_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_official_player_profiles"("p_official_player_key" "uuid") RETURNS TABLE("profile_link_id" "uuid", "riviera_jugador_id" "uuid", "jugador_nombre" "text", "organizer_id" "uuid", "organizer_name" "text", "link_source" "text", "organizer_player_access_id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede listar perfiles oficiales';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.riviera_official_player_identity i
    WHERE i.official_player_key = p_official_player_key
  ) THEN
    RAISE EXCEPTION 'Identidad oficial no encontrada';
  END IF;

  RETURN QUERY
  SELECT
    l.id,
    l.riviera_jugador_id,
    rj.nombre::text,
    l.organizer_id,
    coalesce(u.name, u.email, 'Organizador')::text,
    l.link_source,
    l.organizer_player_access_id,
    l.created_at
  FROM public.riviera_official_player_profile_link l
  JOIN public.riviera_jugadores rj ON rj.id = l.riviera_jugador_id
  LEFT JOIN public.users u ON u.id = l.organizer_id
  WHERE l.official_player_key = p_official_player_key
  ORDER BY l.created_at;
END;
$$;


ALTER FUNCTION "public"."admin_list_official_player_profiles"("p_official_player_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_official_ranking_emitters"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede listar emisores oficiales';
  END IF;

  RETURN coalesce(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'organizador_id', e.organizador_id,
          'organizador_name', coalesce(u.name, u.email, 'Organizador'),
          'is_active', e.is_active,
          'notes', e.notes,
          'created_at', e.created_at,
          'updated_at', e.updated_at
        )
        ORDER BY coalesce(u.name, u.email)
      )
      FROM public.riviera_official_ranking_emitters e
      LEFT JOIN public.users u ON u.id = e.organizador_id
    ),
    '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."admin_list_official_ranking_emitters"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_organizer_player_access"("p_jugador_id" "uuid") RETURNS TABLE("id" "uuid", "grantee_organizer_id" "uuid", "grantee_name" "text", "grantee_email" "text", "is_active" boolean, "is_public_ranking" boolean, "local_jugador_id" "uuid", "granted_by_admin_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede ver accesos';
  END IF;

  RETURN QUERY
  SELECT
    opa.id,
    opa.grantee_organizer_id,
    coalesce(u.name, '')::text AS grantee_name,
    coalesce(u.email, '')::text AS grantee_email,
    opa.is_active,
    opa.is_public_ranking,
    opa.local_jugador_id,
    opa.granted_by_admin_id,
    opa.created_at,
    opa.updated_at
  FROM public.organizer_player_access opa
  LEFT JOIN public.users u ON u.id = opa.grantee_organizer_id
  WHERE opa.jugador_id = p_jugador_id
  ORDER BY opa.is_active DESC, u.name NULLS LAST, opa.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."admin_list_organizer_player_access"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_merge_riviera_jugador_history"("p_source_riviera_id" "text", "p_target_riviera_id" "text", "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_source_jugador_id uuid;
  v_target_jugador_id uuid;
  v_source_key uuid;
  v_target_key uuid;
  v_key uuid;
  v_source_org uuid;
  v_target_org uuid;
  v_source_nombre text;
  v_moved_parts integer := 0;
  v_skipped_parts integer := 0;
  v_moved_rating integer := 0;
  v_skipped_rating integer := 0;
  v_moved_ledger integer := 0;
  v_part record;
  v_rating record;
BEGIN
  IF p_source_riviera_id IS NULL OR p_target_riviera_id IS NULL THEN
    RAISE EXCEPTION 'riviera_id source/target requeridos';
  END IF;

  IF p_source_riviera_id = p_target_riviera_id THEN
    RAISE EXCEPTION 'source y target no pueden ser el mismo riviera_id';
  END IF;

  SELECT rj.id, rj.organizador_id, rj.nombre, i.official_player_key
  INTO v_source_jugador_id, v_source_org, v_source_nombre, v_source_key
  FROM public.riviera_official_player_profile_link pl
  INNER JOIN public.riviera_jugadores rj ON rj.id = pl.riviera_jugador_id
  INNER JOIN public.riviera_official_player_identity i
    ON i.official_player_key = pl.official_player_key
  WHERE i.riviera_id = p_source_riviera_id
  LIMIT 1;

  IF v_source_jugador_id IS NULL THEN
    RAISE EXCEPTION 'No se encontró jugador source para %', p_source_riviera_id;
  END IF;

  SELECT rj.id, rj.organizador_id, i.official_player_key
  INTO v_target_jugador_id, v_target_org, v_target_key
  FROM public.riviera_official_player_profile_link pl
  INNER JOIN public.riviera_jugadores rj ON rj.id = pl.riviera_jugador_id
  INNER JOIN public.riviera_official_player_identity i
    ON i.official_player_key = pl.official_player_key
  WHERE i.riviera_id = p_target_riviera_id
  LIMIT 1;

  IF v_target_jugador_id IS NULL THEN
    RAISE EXCEPTION 'No se encontró jugador target para %', p_target_riviera_id;
  END IF;

  IF p_dry_run THEN
    RETURN jsonb_build_object(
      'dry_run', true,
      'source_riviera_id', p_source_riviera_id,
      'target_riviera_id', p_target_riviera_id,
      'source_jugador_id', v_source_jugador_id,
      'target_jugador_id', v_target_jugador_id,
      'source_org', v_source_org,
      'target_org', v_target_org,
      'source_nombre', v_source_nombre,
      'participaciones_source', (
        SELECT count(*) FROM public.jugador_participaciones jp
        WHERE jp.jugador_id = v_source_jugador_id
      ),
      'rating_source', (
        SELECT count(*) FROM public.rating_historial rh
        WHERE rh.jugador_id = v_source_jugador_id
      ),
      'ledger_source', (
        SELECT count(*) FROM public.riviera_official_points_ledger l
        WHERE l.source_local_jugador_id = v_source_jugador_id
      )
    );
  END IF;

  -- Participaciones
  FOR v_part IN
    SELECT jp.*
    FROM public.jugador_participaciones jp
    WHERE jp.jugador_id = v_source_jugador_id
    ORDER BY jp.fecha, jp.id
  LOOP
    IF EXISTS (
      SELECT 1
      FROM public.jugador_participaciones tgt
      WHERE tgt.jugador_id = v_target_jugador_id
        AND tgt.tipo_evento = v_part.tipo_evento
        AND tgt.evento_id = v_part.evento_id
        AND tgt.resultado = v_part.resultado
    ) THEN
      v_skipped_parts := v_skipped_parts + 1;
      CONTINUE;
    END IF;

    UPDATE public.jugador_participaciones
    SET jugador_id = v_target_jugador_id
    WHERE id = v_part.id;
    v_moved_parts := v_moved_parts + 1;
  END LOOP;

  -- Rating
  IF to_regclass('public.rating_historial') IS NOT NULL THEN
    FOR v_rating IN
      SELECT rh.*
      FROM public.rating_historial rh
      WHERE rh.jugador_id = v_source_jugador_id
      ORDER BY rh.fecha, rh.id
    LOOP
      IF v_rating.partido_ref IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.rating_historial tgt
        WHERE tgt.jugador_id = v_target_jugador_id
          AND tgt.partido_ref = v_rating.partido_ref
      ) THEN
        v_skipped_rating := v_skipped_rating + 1;
        DELETE FROM public.rating_historial WHERE id = v_rating.id;
        CONTINUE;
      END IF;

      UPDATE public.rating_historial
      SET jugador_id = v_target_jugador_id
      WHERE id = v_rating.id;
      v_moved_rating := v_moved_rating + 1;
    END LOOP;
  END IF;

  -- Ledger oficial → identidad canónica target
  IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL
     AND v_target_key IS NOT NULL THEN
    UPDATE public.riviera_official_points_ledger l
    SET official_player_key = v_target_key,
        source_local_jugador_id = v_target_jugador_id
    WHERE l.source_local_jugador_id = v_source_jugador_id;
    GET DIAGNOSTICS v_moved_ledger = ROW_COUNT;
  END IF;

  -- Totales oficiales recalculados desde ledger
  IF to_regclass('public.riviera_official_player_totals') IS NOT NULL THEN
    FOR v_key IN
      SELECT DISTINCT k.official_player_key
      FROM (
        VALUES (v_source_key), (v_target_key)
      ) AS k(official_player_key)
      WHERE k.official_player_key IS NOT NULL
    LOOP
      UPDATE public.riviera_official_player_totals t
      SET points_total = COALESCE((
            SELECT SUM(l.points)::integer
            FROM public.riviera_official_points_ledger l
            WHERE l.official_player_key = v_key
              AND l.counts_for_official_ranking = true
          ), 0),
          last_activity_at = (
            SELECT MAX(l.created_at)
            FROM public.riviera_official_points_ledger l
            WHERE l.official_player_key = v_key
          ),
          updated_at = now()
      WHERE t.official_player_key = v_key;
    END LOOP;
  END IF;

  -- Desenganchar identidad source antes de borrar jugador
  IF v_source_key IS NOT NULL THEN
    DELETE FROM public.riviera_official_player_profile_link
    WHERE riviera_jugador_id = v_source_jugador_id;

    IF NOT EXISTS (
      SELECT 1
      FROM public.riviera_official_player_profile_link pl
      WHERE pl.official_player_key = v_source_key
    ) THEN
      DELETE FROM public.riviera_official_player_totals
      WHERE official_player_key = v_source_key;

      DELETE FROM public.riviera_official_player_identity
      WHERE official_player_key = v_source_key;
    END IF;
  END IF;

  DELETE FROM public.jugador_stats
  WHERE jugador_id = v_source_jugador_id;

  -- Soltar FK canonical si la identidad source sigue viva con otro perfil local
  IF to_regclass('public.riviera_official_player_identity') IS NOT NULL THEN
    UPDATE public.riviera_official_player_identity i
    SET canonical_riviera_jugador_id = (
      SELECT pl.riviera_jugador_id
      FROM public.riviera_official_player_profile_link pl
      WHERE pl.official_player_key = i.official_player_key
        AND pl.riviera_jugador_id IS DISTINCT FROM v_source_jugador_id
      ORDER BY pl.created_at
      LIMIT 1
    )
    WHERE i.canonical_riviera_jugador_id = v_source_jugador_id
      AND EXISTS (
        SELECT 1
        FROM public.riviera_official_player_profile_link pl
        WHERE pl.official_player_key = i.official_player_key
          AND pl.riviera_jugador_id IS DISTINCT FROM v_source_jugador_id
      );
  END IF;

  IF to_regclass('public.riviera_jugador_import_blocklist') IS NOT NULL
     AND v_source_org IS NOT NULL THEN
    BEGIN
      PERFORM public.register_riviera_jugador_import_blocklist(
        v_source_org,
        v_source_nombre,
        NULL,
        NULL
      );
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END IF;

  -- Reasignar inscripciones abiertas y duelos (FK RESTRICT / histórico)
  IF to_regclass('public.tournament_open_registration_entries') IS NOT NULL THEN
    UPDATE public.tournament_open_registration_entries e
    SET
      riviera_jugador_id = v_target_jugador_id,
      riviera_id = p_target_riviera_id,
      official_player_key = v_target_key,
      updated_at = now()
    WHERE e.riviera_jugador_id = v_source_jugador_id;
  END IF;

  IF to_regclass('public.duelos_2v2') IS NOT NULL THEN
    UPDATE public.duelos_2v2
    SET
      pareja_a_j1_id = CASE WHEN pareja_a_j1_id = v_source_jugador_id THEN v_target_jugador_id ELSE pareja_a_j1_id END,
      pareja_a_j2_id = CASE WHEN pareja_a_j2_id = v_source_jugador_id THEN v_target_jugador_id ELSE pareja_a_j2_id END,
      pareja_b_j1_id = CASE WHEN pareja_b_j1_id = v_source_jugador_id THEN v_target_jugador_id ELSE pareja_b_j1_id END,
      pareja_b_j2_id = CASE WHEN pareja_b_j2_id = v_source_jugador_id THEN v_target_jugador_id ELSE pareja_b_j2_id END,
      updated_at = now()
    WHERE pareja_a_j1_id = v_source_jugador_id
       OR pareja_a_j2_id = v_source_jugador_id
       OR pareja_b_j1_id = v_source_jugador_id
       OR pareja_b_j2_id = v_source_jugador_id;
  END IF;

  DELETE FROM public.riviera_jugadores
  WHERE id = v_source_jugador_id;

  BEGIN
    PERFORM public.refresh_jugador_stats(v_target_jugador_id);
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  RETURN jsonb_build_object(
    'dry_run', false,
    'status', 'merged',
    'source_riviera_id', p_source_riviera_id,
    'target_riviera_id', p_target_riviera_id,
    'source_jugador_id', v_source_jugador_id,
    'target_jugador_id', v_target_jugador_id,
    'moved_participaciones', v_moved_parts,
    'skipped_participaciones', v_skipped_parts,
    'moved_rating', v_moved_rating,
    'skipped_rating', v_skipped_rating,
    'moved_ledger_rows', v_moved_ledger
  );
END;
$$;


ALTER FUNCTION "public"."admin_merge_riviera_jugador_history"("p_source_riviera_id" "text", "p_target_riviera_id" "text", "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_merge_riviera_jugador_history"("p_source_riviera_id" "text", "p_target_riviera_id" "text", "p_dry_run" boolean) IS 'Fusiona historial (participaciones/rating/ledger) de un riviera_id duplicado hacia el canónico. p_dry_run=true solo preview.';



CREATE OR REPLACE FUNCTION "public"."admin_repair_liga_inscripcion_career"("p_liga_id" "uuid", "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_liga record;
  v_jugador_id uuid;
  v_part_id uuid;
  v_inserted integer := 0;
  v_skipped integer := 0;
  v_ledger integer := 0;
  v_refreshed integer := 0;
  v_meta jsonb;
  v_evento_nombre text;
BEGIN
  IF p_liga_id IS NULL THEN
    RAISE EXCEPTION 'p_liga_id requerido';
  END IF;

  SELECT id, nombre, organizador_id, modalidad
  INTO v_liga
  FROM public.ligas
  WHERE id = p_liga_id;

  IF v_liga.id IS NULL THEN
    RAISE EXCEPTION 'Liga no encontrada: %', p_liga_id;
  END IF;

  IF v_liga.organizador_id IS NULL THEN
    RAISE EXCEPTION 'Liga sin organizador_id';
  END IF;

  v_evento_nombre := 'Liga ' || v_liga.nombre || ' — Inscripción';

  FOR v_jugador_id IN
    SELECT DISTINCT rj.id
    FROM (
      -- Parejas fijas / playoffs
      SELECT le.jugador1_id AS legacy_id
      FROM public.liga_equipos le
      WHERE le.liga_id = p_liga_id
      UNION
      SELECT le.jugador2_id
      FROM public.liga_equipos le
      WHERE le.liga_id = p_liga_id
      UNION
      -- Rotativo
      SELECT li.jugador_id
      FROM public.liga_inscripciones li
      WHERE li.liga_id = p_liga_id
    ) AS participants
    INNER JOIN public.riviera_jugadores rj
      ON rj.legacy_liga_jugador_id = participants.legacy_id
     AND rj.organizador_id = v_liga.organizador_id
    WHERE participants.legacy_id IS NOT NULL
  LOOP
    IF EXISTS (
      SELECT 1
      FROM public.jugador_participaciones jp
      WHERE jp.jugador_id = v_jugador_id
        AND jp.tipo_evento = 'liga'
        AND jp.evento_id = p_liga_id
        AND jp.metadata->>'subtipo' = 'liga_inscripcion'
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    v_meta := jsonb_build_object(
      'subtipo', 'liga_inscripcion',
      'organizador_id', v_liga.organizador_id::text,
      'liga_id', p_liga_id::text,
      'liga_nombre', v_liga.nombre,
      'modalidad', 'liga',
      'modalidad_label', 'Liga',
      'lugar', 'Inscripción a la liga',
      'puntos_desglose', jsonb_build_object('liga_inscripcion', 100),
      'esquema_puntos', 'riviera_open_v1'
    );

    IF p_dry_run THEN
      v_inserted := v_inserted + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.jugador_participaciones (
      jugador_id,
      tipo_evento,
      evento_id,
      evento_nombre,
      fecha,
      resultado,
      sets_favor,
      sets_contra,
      puntos_obtenidos,
      metadata
    )
    VALUES (
      v_jugador_id,
      'liga',
      p_liga_id,
      v_evento_nombre,
      CURRENT_DATE,
      'participación',
      0,
      0,
      100,
      v_meta
    )
    RETURNING id INTO v_part_id;

    v_inserted := v_inserted + 1;

    BEGIN
      PERFORM public.try_write_riviera_official_ledger(v_part_id);
      v_ledger := v_ledger + 1;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;

    BEGIN
      PERFORM public.refresh_jugador_stats(v_jugador_id);
      v_refreshed := v_refreshed + 1;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'liga_id', p_liga_id,
    'liga_nombre', v_liga.nombre,
    'organizador_id', v_liga.organizador_id,
    'inserted', v_inserted,
    'skipped_existing', v_skipped,
    'ledger_written', v_ledger,
    'stats_refreshed', v_refreshed
  );
END;
$$;


ALTER FUNCTION "public"."admin_repair_liga_inscripcion_career"("p_liga_id" "uuid", "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_repair_liga_inscripcion_career"("p_liga_id" "uuid", "p_dry_run" boolean) IS 'Backfill +100 inscripción liga (participaciones + ledger). p_dry_run=true solo preview.';



CREATE OR REPLACE FUNCTION "public"."admin_repair_liga_jornada_career"("p_jornada_id" "uuid", "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jornada record;
  v_liga record;
  v_winner_pareja_id uuid;
  v_winner_j1 uuid;
  v_winner_j2 uuid;
  v_legacy_id uuid;
  v_jugador_id uuid;
  v_part_id uuid;
  v_inserted integer := 0;
  v_skipped integer := 0;
  v_ledger integer := 0;
  v_refreshed integer := 0;
  v_winners integer := 0;
  v_meta jsonb;
  v_pts integer;
  v_gano boolean;
  v_evento_nombre text;
  v_nombre text;
BEGIN
  IF p_jornada_id IS NULL THEN
    RAISE EXCEPTION 'p_jornada_id requerido';
  END IF;

  SELECT j.id, j.liga_id, j.numero, j.estado
  INTO v_jornada
  FROM public.liga_jornadas j
  WHERE j.id = p_jornada_id;

  IF v_jornada.id IS NULL THEN
    RAISE EXCEPTION 'Jornada no encontrada: %', p_jornada_id;
  END IF;

  IF v_jornada.estado IS DISTINCT FROM 'completed' THEN
    RAISE EXCEPTION 'Jornada % no está completed (estado=%)', p_jornada_id, v_jornada.estado;
  END IF;

  SELECT l.id, l.nombre, l.organizador_id, l.modalidad
  INTO v_liga
  FROM public.ligas l
  WHERE l.id = v_jornada.liga_id;

  IF v_liga.organizador_id IS NULL THEN
    RAISE EXCEPTION 'Liga sin organizador_id';
  END IF;

  v_evento_nombre := 'Liga ' || v_liga.nombre || ' - Jornada ' || v_jornada.numero;

  WITH partidos AS (
    SELECT
      lp.pareja1_id,
      lp.pareja2_id,
      lp.set_scores,
      coalesce(lp.score_pareja1, 0) AS score1,
      coalesce(lp.score_pareja2, 0) AS score2
    FROM public.liga_partidos lp
    WHERE lp.jornada_id = p_jornada_id
      AND lp.estado = 'completed'
  ),
  stats AS (
    SELECT
      p.pareja1_id AS pareja_id,
      public._playoffs_match_ranking_pts(p.set_scores, true) AS puntos,
      p.score1 AS gf,
      p.score2 AS gc,
      CASE
        WHEN public._playoffs_match_ranking_pts(p.set_scores, true)
           > public._playoffs_match_ranking_pts(p.set_scores, false) THEN 1
        ELSE 0
      END AS victorias
    FROM partidos p
    UNION ALL
    SELECT
      p.pareja2_id,
      public._playoffs_match_ranking_pts(p.set_scores, false),
      p.score2,
      p.score1,
      CASE
        WHEN public._playoffs_match_ranking_pts(p.set_scores, false)
           > public._playoffs_match_ranking_pts(p.set_scores, true) THEN 1
        ELSE 0
      END
    FROM partidos p
  ),
  agg AS (
    SELECT
      s.pareja_id,
      sum(s.puntos) AS puntos,
      sum(s.victorias) AS victorias,
      sum(s.gf) AS gf,
      sum(s.gc) AS gc,
      sum(s.gf) - sum(s.gc) AS dif
    FROM stats s
    GROUP BY s.pareja_id
  ),
  ranked AS (
    SELECT
      a.pareja_id,
      row_number() OVER (
        ORDER BY a.puntos DESC, a.dif DESC, a.gf DESC, a.victorias DESC, a.pareja_id
      ) AS rn
    FROM agg a
  )
  SELECT r.pareja_id, jp.jugador1_id, jp.jugador2_id
  INTO v_winner_pareja_id, v_winner_j1, v_winner_j2
  FROM ranked r
  JOIN public.liga_jornada_parejas jp ON jp.id = r.pareja_id
  WHERE r.rn = 1;

  IF v_winner_pareja_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo determinar ganador de jornada %', p_jornada_id;
  END IF;

  FOR v_legacy_id, v_nombre IN
    SELECT DISTINCT lj.id, lj.nombre
    FROM (
      SELECT jp.jugador1_id AS legacy_id
      FROM public.liga_jornada_parejas jp
      WHERE jp.jornada_id = p_jornada_id
        AND EXISTS (
          SELECT 1
          FROM public.liga_partidos lp
          WHERE lp.jornada_id = p_jornada_id
            AND lp.estado = 'completed'
            AND (lp.pareja1_id = jp.id OR lp.pareja2_id = jp.id)
        )
      UNION
      SELECT jp.jugador2_id
      FROM public.liga_jornada_parejas jp
      WHERE jp.jornada_id = p_jornada_id
        AND EXISTS (
          SELECT 1
          FROM public.liga_partidos lp
          WHERE lp.jornada_id = p_jornada_id
            AND lp.estado = 'completed'
            AND (lp.pareja1_id = jp.id OR lp.pareja2_id = jp.id)
        )
    ) AS played
    JOIN public.liga_jugadores lj ON lj.id = played.legacy_id
  LOOP
    SELECT rj.id
    INTO v_jugador_id
    FROM public.riviera_jugadores rj
    WHERE rj.legacy_liga_jugador_id = v_legacy_id
      AND rj.organizador_id = v_liga.organizador_id
    LIMIT 1;

    IF v_jugador_id IS NULL THEN
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.jugador_participaciones jp
      WHERE jp.jugador_id = v_jugador_id
        AND jp.tipo_evento = 'liga'
        AND jp.evento_id = p_jornada_id
        AND jp.metadata->>'subtipo' = 'liga_jornada'
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    v_gano := v_legacy_id IN (v_winner_j1, v_winner_j2);
    v_pts := CASE WHEN v_gano THEN 50 ELSE 0 END;

    v_meta := jsonb_build_object(
      'subtipo', 'liga_jornada',
      'organizador_id', v_liga.organizador_id::text,
      'liga_id', v_liga.id::text,
      'liga_nombre', v_liga.nombre,
      'jornada_numero', v_jornada.numero,
      'jornada_ganada', v_gano,
      'modalidad', 'liga',
      'modalidad_label', 'Liga',
      'lugar', CASE WHEN v_gano THEN 'Ganador jornada ' || v_jornada.numero::text ELSE 'Participación en jornada' END,
      'puntos_desglose', CASE
        WHEN v_gano THEN jsonb_build_object('liga_jornada_ganada', 50)
        ELSE '{}'::jsonb
      END,
      'esquema_puntos', 'riviera_open_v1',
      'repair', 'admin_repair_liga_jornada_career'
    );

    IF p_dry_run THEN
      v_inserted := v_inserted + 1;
      IF v_gano THEN
        v_winners := v_winners + 1;
      END IF;
      CONTINUE;
    END IF;

    INSERT INTO public.jugador_participaciones (
      jugador_id,
      tipo_evento,
      evento_id,
      evento_nombre,
      fecha,
      resultado,
      sets_favor,
      sets_contra,
      puntos_obtenidos,
      metadata
    )
    VALUES (
      v_jugador_id,
      'liga',
      p_jornada_id,
      v_evento_nombre,
      CURRENT_DATE,
      'participación',
      0,
      0,
      v_pts,
      v_meta
    )
    RETURNING id INTO v_part_id;

    v_inserted := v_inserted + 1;
    IF v_gano THEN
      v_winners := v_winners + 1;
    END IF;

    BEGIN
      PERFORM public.try_write_riviera_official_ledger(v_part_id);
      v_ledger := v_ledger + 1;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;

    BEGIN
      PERFORM public.refresh_jugador_stats(v_jugador_id);
      v_refreshed := v_refreshed + 1;
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'jornada_id', p_jornada_id,
    'jornada_numero', v_jornada.numero,
    'liga_id', v_liga.id,
    'liga_nombre', v_liga.nombre,
    'organizador_id', v_liga.organizador_id,
    'winner_pareja_id', v_winner_pareja_id,
    'winner_legacy_jugador_ids', jsonb_build_array(v_winner_j1, v_winner_j2),
    'inserted', v_inserted,
    'winners_credited', v_winners,
    'skipped_existing', v_skipped,
    'ledger_written', v_ledger,
    'stats_refreshed', v_refreshed
  );
END;
$$;


ALTER FUNCTION "public"."admin_repair_liga_jornada_career"("p_jornada_id" "uuid", "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_repair_liga_jornada_career"("p_jornada_id" "uuid", "p_dry_run" boolean) IS 'Backfill participaciones liga_jornada (+50 ganador, +0 resto). p_dry_run=true solo preview.';



CREATE OR REPLACE FUNCTION "public"."admin_repair_liga_podio_career"("p_liga_id" "uuid", "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_liga record;
  v_club text;
  v_row record;
  v_part_id uuid;
  v_ledger jsonb;
  v_inserted integer := 0;
  v_skipped integer := 0;
  v_unresolved integer := 0;
  v_preview jsonb := '[]'::jsonb;
BEGIN
  IF p_liga_id IS NULL THEN
    RAISE EXCEPTION 'p_liga_id requerido';
  END IF;

  SELECT id, nombre, organizador_id, modalidad, estado
  INTO v_liga
  FROM public.ligas
  WHERE id = p_liga_id;

  IF v_liga.id IS NULL THEN
    RAISE EXCEPTION 'Liga no encontrada: %', p_liga_id;
  END IF;
  IF v_liga.modalidad IS DISTINCT FROM 'parejas_fijas_playoffs' THEN
    RAISE EXCEPTION 'Solo parejas_fijas_playoffs. Modalidad: %', v_liga.modalidad;
  END IF;
  IF v_liga.estado IS DISTINCT FROM 'completed' THEN
    RAISE EXCEPTION 'La liga no está finalizada.';
  END IF;

  SELECT coalesce(u.name, u.email, 'Club')
  INTO v_club
  FROM public.users u
  WHERE u.id = v_liga.organizador_id;

  FOR v_row IN
    WITH sets AS (
      SELECT
        p.id AS partido_id,
        p.bracket_slot,
        p.pareja1_id,
        p.pareja2_id,
        COALESCE((
          SELECT COUNT(*)::integer
          FROM jsonb_array_elements(p.set_scores->'sets') s
          WHERE (s->>'p1')::integer > (s->>'p2')::integer
        ), 0) AS sets_p1,
        COALESCE((
          SELECT COUNT(*)::integer
          FROM jsonb_array_elements(p.set_scores->'sets') s
          WHERE (s->>'p2')::integer > (s->>'p1')::integer
        ), 0) AS sets_p2
      FROM public.liga_partidos p
      JOIN public.liga_jornadas j ON j.id = p.jornada_id
      WHERE j.liga_id = p_liga_id
        AND p.estado = 'completed'
        AND p.bracket_slot IN ('FINAL', 'THIRD')
    ),
    winners AS (
      SELECT 1 AS posicion,
        CASE WHEN sets_p1 > sets_p2 THEN pareja1_id
             WHEN sets_p2 > sets_p1 THEN pareja2_id
        END AS pareja_id
      FROM sets
      WHERE bracket_slot = 'FINAL' AND sets_p1 <> sets_p2
      UNION ALL
      SELECT 2,
        CASE WHEN sets_p1 > sets_p2 THEN pareja2_id
             WHEN sets_p2 > sets_p1 THEN pareja1_id
        END
      FROM sets
      WHERE bracket_slot = 'FINAL' AND sets_p1 <> sets_p2
      UNION ALL
      SELECT 3,
        CASE WHEN sets_p1 > sets_p2 THEN pareja1_id
             WHEN sets_p2 > sets_p1 THEN pareja2_id
        END
      FROM sets
      WHERE bracket_slot = 'THIRD' AND sets_p1 <> sets_p2
    ),
    players AS (
      SELECT w.posicion, jp.jugador1_id AS legacy_id, 1 AS lado
      FROM winners w
      JOIN public.liga_jornada_parejas jp ON jp.id = w.pareja_id
      WHERE w.posicion IS NOT NULL
      UNION ALL
      SELECT w.posicion, jp.jugador2_id, 2
      FROM winners w
      JOIN public.liga_jornada_parejas jp ON jp.id = w.pareja_id
      WHERE w.posicion IS NOT NULL
    )
    SELECT
      pl.posicion,
      pl.legacy_id,
      lj.nombre AS liga_nombre,
      rj.id AS riviera_jugador_id,
      ident.riviera_id,
      COALESCE(rj.suma_ranking, true) AS suma_ranking,
      CASE pl.posicion WHEN 1 THEN 500 WHEN 2 THEN 250 WHEN 3 THEN 100 END AS puntos,
      CASE pl.posicion
        WHEN 1 THEN 'victoria'
        WHEN 2 THEN 'derrota'
        ELSE 'empate'
      END AS resultado,
      CASE pl.posicion
        WHEN 1 THEN 'Campeón'
        WHEN 2 THEN 'Subcampeón'
        ELSE '3er lugar'
      END AS lugar,
      CASE pl.posicion
        WHEN 1 THEN 'campeon'
        WHEN 2 THEN 'subcampeon'
        ELSE 'tercer'
      END AS placement,
      (
        SELECT lj2.nombre
        FROM players mate
        JOIN public.liga_jugadores lj2 ON lj2.id = mate.legacy_id
        WHERE mate.posicion = pl.posicion
          AND mate.legacy_id IS DISTINCT FROM pl.legacy_id
        LIMIT 1
      ) AS pareja_con
    FROM players pl
    LEFT JOIN public.liga_jugadores lj ON lj.id = pl.legacy_id
    LEFT JOIN public.riviera_jugadores rj
      ON rj.legacy_liga_jugador_id = pl.legacy_id
     AND rj.organizador_id = v_liga.organizador_id
    LEFT JOIN public.riviera_official_player_profile_link link
      ON link.riviera_jugador_id = rj.id
    LEFT JOIN public.riviera_official_player_identity ident
      ON ident.official_player_key = link.official_player_key
    ORDER BY pl.posicion, pl.lado
  LOOP
    IF v_row.riviera_jugador_id IS NULL OR v_row.riviera_id IS NULL THEN
      v_unresolved := v_unresolved + 1;
      v_preview := v_preview || jsonb_build_array(jsonb_build_object(
        'posicion', v_row.posicion,
        'nombre', v_row.liga_nombre,
        'legacy_id', v_row.legacy_id,
        'status', 'sin_riviera_id'
      ));
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.jugador_participaciones jp
      WHERE jp.jugador_id = v_row.riviera_jugador_id
        AND jp.tipo_evento = 'liga'
        AND jp.evento_id = p_liga_id
        AND jp.metadata->>'subtipo' = 'liga_podio_final'
    ) THEN
      v_skipped := v_skipped + 1;
      v_preview := v_preview || jsonb_build_array(jsonb_build_object(
        'posicion', v_row.posicion,
        'nombre', v_row.liga_nombre,
        'riviera_id', v_row.riviera_id,
        'status', 'ya_existia'
      ));
      CONTINUE;
    END IF;

    v_preview := v_preview || jsonb_build_array(jsonb_build_object(
      'posicion', v_row.posicion,
      'nombre', v_row.liga_nombre,
      'riviera_id', v_row.riviera_id,
      'riviera_jugador_id', v_row.riviera_jugador_id,
      'puntos', CASE WHEN v_row.suma_ranking THEN v_row.puntos ELSE 0 END,
      'lugar', v_row.lugar,
      'status', CASE WHEN p_dry_run THEN 'pendiente' ELSE 'insertado' END
    ));

    IF p_dry_run THEN
      v_inserted := v_inserted + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.jugador_participaciones (
      jugador_id,
      tipo_evento,
      evento_id,
      evento_nombre,
      fecha,
      resultado,
      sets_favor,
      sets_contra,
      puntos_obtenidos,
      pareja_con,
      metadata
    ) VALUES (
      v_row.riviera_jugador_id,
      'liga',
      p_liga_id,
      'Liga ' || v_liga.nombre || ' — Podio final',
      CURRENT_DATE,
      v_row.resultado::public.jugador_resultado,
      0,
      0,
      CASE WHEN v_row.suma_ranking THEN v_row.puntos ELSE 0 END,
      v_row.pareja_con,
      jsonb_build_object(
        'subtipo', 'liga_podio_final',
        'organizador_id', v_liga.organizador_id::text,
        'club_name', COALESCE(v_club, 'Club'),
        'liga_id', p_liga_id::text,
        'liga_nombre', v_liga.nombre,
        'posicion_final', v_row.posicion,
        'placement', v_row.placement,
        'campeon_torneo', v_row.posicion = 1,
        'subcampeon_torneo', v_row.posicion = 2,
        'partidos_ganados', 0,
        'partidos_perdidos', 0,
        'partidos_empatados', 0,
        'modalidad', 'liga',
        'modalidad_label', 'Liga',
        'lugar', v_row.lugar,
        'podio_source', 'playoff',
        'puntos_aplicados', true,
        'puntos_evento', CASE WHEN v_row.suma_ranking THEN v_row.puntos ELSE 0 END,
        'puntos_desglose', CASE v_row.posicion
          WHEN 1 THEN jsonb_build_object('liga_podio_1', 500)
          WHEN 2 THEN jsonb_build_object('liga_podio_2', 250)
          ELSE jsonb_build_object('liga_podio_3', 100)
        END,
        'ranking_puntos_esquema', 'riviera_open_v1'
      )
    )
    RETURNING id INTO v_part_id;

    v_inserted := v_inserted + 1;

    v_ledger := public.try_write_riviera_official_ledger(v_part_id);
    PERFORM public.refresh_jugador_stats(v_row.riviera_jugador_id);

    v_preview := v_preview || jsonb_build_array(jsonb_build_object(
      'riviera_id', v_row.riviera_id,
      'ledger', v_ledger
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'liga_id', p_liga_id,
    'liga_nombre', v_liga.nombre,
    'club', v_club,
    'would_insert_or_inserted', v_inserted,
    'skipped_existing', v_skipped,
    'unresolved', v_unresolved,
    'players', v_preview
  );
END;
$$;


ALTER FUNCTION "public"."admin_repair_liga_podio_career"("p_liga_id" "uuid", "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_repair_liga_podio_career"("p_liga_id" "uuid", "p_dry_run" boolean) IS 'Backfill idempotente del podio de liga por parejas (playoffs). No altera resultados deportivos.';



CREATE OR REPLACE FUNCTION "public"."admin_revoke_organizer_player_access"("p_access_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_local_id uuid;
  v_grantee_id uuid;
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede quitar acceso';
  END IF;

  UPDATE public.organizer_player_access
  SET is_active = false,
      updated_at = now()
  WHERE id = p_access_id
  RETURNING local_jugador_id, grantee_organizer_id
  INTO v_local_id, v_grantee_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Acceso no encontrado';
  END IF;

  IF v_local_id IS NOT NULL AND v_grantee_id IS NOT NULL THEN
    UPDATE public.riviera_jugadores rj
    SET estado = 'archivado',
        suma_ranking = false,
        visible_publico = false,
        updated_at = now()
    WHERE rj.id = v_local_id
      AND rj.organizador_id = v_grantee_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."admin_revoke_organizer_player_access"("p_access_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_official_ranking_emitter"("p_organizador_id" "uuid", "p_active" boolean DEFAULT true, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin uuid := auth.uid();
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede configurar emisores oficiales';
  END IF;

  IF p_organizador_id IS NULL THEN
    RAISE EXCEPTION 'organizador_id requerido';
  END IF;

  INSERT INTO public.riviera_official_ranking_emitters (
    organizador_id,
    is_active,
    notes,
    created_by,
    updated_at
  ) VALUES (
    p_organizador_id,
    COALESCE(p_active, true),
    NULLIF(trim(p_notes), ''),
    v_admin,
    now()
  )
  ON CONFLICT (organizador_id) DO UPDATE
  SET
    is_active = COALESCE(p_active, true),
    notes = COALESCE(NULLIF(trim(p_notes), ''), riviera_official_ranking_emitters.notes),
    updated_at = now();

  RETURN jsonb_build_object(
    'organizador_id', p_organizador_id,
    'is_active', COALESCE(p_active, true)
  );
END;
$$;


ALTER FUNCTION "public"."admin_set_official_ranking_emitter"("p_organizador_id" "uuid", "p_active" boolean, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_sync_auth_email_identity"("p_user_id" "uuid", "p_new_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'public'
    AS $$
DECLARE
  v_old_email text;
  v_identities_updated integer := 0;
  v_normalized text := lower(trim(p_new_email));
BEGIN
  IF p_user_id IS NULL OR v_normalized IS NULL OR v_normalized = '' THEN
    RAISE EXCEPTION 'Parámetros inválidos';
  END IF;

  SELECT email INTO v_old_email
  FROM auth.users
  WHERE id = p_user_id;

  IF v_old_email IS NULL THEN
    RAISE EXCEPTION 'Usuario de acceso no encontrado';
  END IF;

  UPDATE auth.users
  SET
    email = v_normalized,
    email_confirmed_at = COALESCE(email_confirmed_at, now()),
    updated_at = now(),
    role = CASE WHEN role = 'anonymous' THEN 'authenticated' ELSE role END,
    aud = CASE WHEN aud = 'anonymous' THEN 'authenticated' ELSE aud END,
    is_anonymous = false
  WHERE id = p_user_id;

  UPDATE auth.identities
  SET
    provider_id = v_normalized,
    email = v_normalized,
    identity_data = jsonb_set(
      jsonb_set(
        COALESCE(identity_data, '{}'::jsonb),
        '{email}',
        to_jsonb(v_normalized),
        true
      ),
      '{email_verified}',
      'true'::jsonb,
      true
    ),
    updated_at = now()
  WHERE user_id = p_user_id
    AND provider = 'email';

  GET DIAGNOSTICS v_identities_updated = ROW_COUNT;

  IF v_identities_updated = 0 THEN
    INSERT INTO auth.identities (
      id,
      provider_id,
      user_id,
      identity_data,
      provider,
      email,
      created_at,
      updated_at
    )
    VALUES (
      gen_random_uuid(),
      v_normalized,
      p_user_id,
      jsonb_build_object(
        'email', v_normalized,
        'email_verified', true,
        'sub', p_user_id::text
      ),
      'email',
      v_normalized,
      now(),
      now()
    );
    v_identities_updated := 1;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'user_id', p_user_id,
    'old_email', v_old_email,
    'new_email', v_normalized,
    'identities_updated', v_identities_updated
  );
END;
$$;


ALTER FUNCTION "public"."admin_sync_auth_email_identity"("p_user_id" "uuid", "p_new_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_unlink_official_player_profile"("p_profile_link_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede desvincular perfiles oficiales';
  END IF;

  SELECT
    l.id,
    l.official_player_key,
    l.riviera_jugador_id,
    l.link_source,
    i.canonical_riviera_jugador_id
  INTO v_row
  FROM public.riviera_official_player_profile_link l
  JOIN public.riviera_official_player_identity i
    ON i.official_player_key = l.official_player_key
  WHERE l.id = p_profile_link_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo no encontrado';
  END IF;

  IF v_row.riviera_jugador_id = v_row.canonical_riviera_jugador_id THEN
    RAISE EXCEPTION
      'No se puede desvincular el perfil canonical. Cree otra identidad o vincule otro canonical antes.';
  END IF;

  DELETE FROM public.riviera_official_player_profile_link
  WHERE id = p_profile_link_id;

  RETURN jsonb_build_object(
    'unlinked', true,
    'profile_link_id', p_profile_link_id,
    'riviera_jugador_id', v_row.riviera_jugador_id,
    'official_player_key', v_row.official_player_key
  );
END;
$$;


ALTER FUNCTION "public"."admin_unlink_official_player_profile"("p_profile_link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_organizador_name"("p_user_id" "uuid", "p_new_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_name text := trim(p_new_name);
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede cambiar el nombre';
  END IF;

  IF p_user_id IS NULL OR v_name IS NULL OR v_name = '' THEN
    RAISE EXCEPTION 'Nombre inválido';
  END IF;

  IF char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'El nombre es demasiado largo';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_user_id) THEN
    RAISE EXCEPTION 'Usuario no encontrado';
  END IF;

  UPDATE public.users
  SET
    name = v_name,
    updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET
    raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb)
      || jsonb_build_object('name', v_name),
    updated_at = now()
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'ok', true,
    'user_id', p_user_id,
    'name', v_name
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_organizador_name"("p_user_id" "uuid", "p_new_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aplicar_programacion_torneo_express_grupo"("p_grupo_id" "uuid", "p_expected_version" integer, "p_mode" "text", "p_now" timestamp with time zone, "p_assignments" "jsonb", "p_courts" "text"[], "p_slots" "jsonb", "p_occupied" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_torneo_id uuid;
  v_guard jsonb;
  v_version_guard jsonb;
  v_version integer;
  v_item jsonb;
  v_match_id uuid;
  v_cancha text;
  v_programado timestamptz;
  v_orden integer;
  v_time_key text;
  v_court_key text;
  v_now_key text;
  v_estado text;
  v_old_cancha text;
  v_old_programado timestamptz;
  v_old_orden integer;
  v_local uuid;
  v_visit uuid;
  v_slot_local uuid;
  v_slot_visit uuid;
  v_historial boolean;
  v_changed integer := 0;
BEGIN
  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;
  IF p_mode IS DISTINCT FROM 'faltantes' AND p_mode IS DISTINCT FROM 'reorganizar' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MODE');
  END IF;
  IF p_now IS NULL
     OR jsonb_typeof(coalesce(p_assignments, '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(p_slots, '[]'::jsonb)) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_SLOT');
  END IF;

  SELECT torneo_id INTO v_torneo_id
  FROM public.torneo_express_grupos WHERE id = p_grupo_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  v_guard := public.te_lock_categoria_editable(v_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    IF (v_guard ->> 'error') IN ('TOURNAMENT_NOT_EDITABLE', 'ELIMINATORIA_EXISTS') THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'GROUP_NOT_EDITABLE', 'reason', v_guard ->> 'error'
      );
    END IF;
    RETURN v_guard;
  END IF;

  PERFORM 1 FROM public.torneo_express_grupos WHERE id = p_grupo_id FOR UPDATE;
  v_version_guard := public.te_grupo_version_ok(p_grupo_id, p_expected_version);
  IF NOT (v_version_guard ->> 'ok')::boolean THEN
    RETURN v_version_guard;
  END IF;
  v_version := (v_version_guard ->> 'version')::integer;

  PERFORM 1
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = p_grupo_id
  ORDER BY pareja_id
  FOR UPDATE;

  PERFORM 1
  FROM public.torneo_express_partidos
  WHERE grupo_id = p_grupo_id
  ORDER BY id
  FOR UPDATE;

  v_now_key := public.te_mexico_slot_key(p_now);

  DROP TABLE IF EXISTS te_sched_assign;
  DROP TABLE IF EXISTS te_sched_open;
  DROP TABLE IF EXISTS te_sched_courts;
  DROP TABLE IF EXISTS te_sched_presence;
  CREATE TEMP TABLE te_sched_assign (
    match_id uuid PRIMARY KEY,
    cancha text NOT NULL,
    programado_en timestamptz NOT NULL,
    orden integer NOT NULL,
    time_key text NOT NULL,
    court_key text NOT NULL
  ) ON COMMIT DROP;
  CREATE TEMP TABLE te_sched_open (
    time_key text NOT NULL,
    court_key text NOT NULL,
    PRIMARY KEY (time_key, court_key)
  ) ON COMMIT DROP;
  CREATE TEMP TABLE te_sched_courts (
    time_key text NOT NULL,
    court_key text NOT NULL,
    source text NOT NULL
  ) ON COMMIT DROP;
  CREATE TEMP TABLE te_sched_presence (
    time_key text NOT NULL,
    slot_id uuid NOT NULL,
    match_id uuid NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO te_sched_open (time_key, court_key)
  SELECT DISTINCT
    public.te_mexico_slot_key((value ->> 'programado_en')::timestamptz),
    public.te_court_key(value ->> 'cancha')
  FROM jsonb_array_elements(coalesce(p_slots, '[]'::jsonb)) AS value
  WHERE public.te_court_key(value ->> 'cancha') <> ''
    AND value ->> 'programado_en' IS NOT NULL
  ON CONFLICT DO NOTHING;

  FOR v_item IN
    SELECT value
    FROM jsonb_array_elements(coalesce(p_assignments, '[]'::jsonb)) AS value
    ORDER BY value ->> 'match_id'
  LOOP
    BEGIN
      v_match_id := (v_item ->> 'match_id')::uuid;
      v_cancha := v_item ->> 'cancha';
      v_programado := (v_item ->> 'programado_en')::timestamptz;
      v_orden := (v_item ->> 'orden')::integer;
    EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR invalid_datetime_format THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_SLOT', 'version', v_version);
    END;

    v_time_key := public.te_mexico_slot_key(v_programado);
    v_court_key := public.te_court_key(v_cancha);
    IF v_match_id IS NULL OR v_programado IS NULL OR v_orden IS NULL OR v_orden < 1
       OR v_court_key = '' OR v_time_key IS NULL OR v_time_key < v_now_key THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_SLOT', 'version', v_version);
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM unnest(coalesce(p_courts, ARRAY[]::text[])) AS court
      WHERE public.te_court_key(court) = v_court_key
    ) OR NOT EXISTS (
      SELECT 1 FROM te_sched_open open
      WHERE open.time_key = v_time_key AND open.court_key = v_court_key
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_SLOT', 'version', v_version);
    END IF;
    IF EXISTS (SELECT 1 FROM te_sched_assign WHERE match_id = v_match_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_SLOT', 'version', v_version);
    END IF;

    SELECT
      p.estado, p.cancha, p.programado_en, p.orden,
      p.pareja_local_id, p.pareja_visitante_id,
      public.te_partido_tiene_historial(
        p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
      ),
      public.te_slot_pareja_actual(p_grupo_id, p.pareja_local_id),
      public.te_slot_pareja_actual(p_grupo_id, p.pareja_visitante_id)
    INTO
      v_estado, v_old_cancha, v_old_programado, v_old_orden,
      v_local, v_visit, v_historial, v_slot_local, v_slot_visit
    FROM public.torneo_express_partidos p
    WHERE p.id = v_match_id AND p.grupo_id = p_grupo_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'MATCH_NOT_IN_GROUP', 'version', v_version);
    END IF;
    IF v_historial OR v_estado IS DISTINCT FROM 'pendiente' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'PLAYED_MATCH_LOCKED', 'version', v_version);
    END IF;
    IF v_slot_local IS NULL OR v_slot_visit IS NULL OR v_slot_local = v_slot_visit THEN
      RETURN jsonb_build_object('ok', false, 'error', 'OBSOLETE_MATCH', 'version', v_version);
    END IF;
    IF p_mode = 'faltantes'
       AND v_old_programado IS NOT NULL
       AND public.te_court_key(v_old_cancha) <> ''
       AND (
         public.te_court_key(v_old_cancha) IS DISTINCT FROM v_court_key
         OR public.te_mexico_slot_key(v_old_programado) IS DISTINCT FROM v_time_key
         OR v_old_orden IS DISTINCT FROM v_orden
       ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'PENDING_ALREADY_SCHEDULED', 'version', v_version);
    END IF;

    INSERT INTO te_sched_assign (match_id, cancha, programado_en, orden, time_key, court_key)
    VALUES (v_match_id, btrim(v_cancha), v_programado, v_orden, v_time_key, v_court_key);
  END LOOP;

  IF p_mode = 'reorganizar' AND EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    WHERE p.grupo_id = p_grupo_id
      AND p.estado = 'pendiente'
      AND NOT public.te_partido_tiene_historial(
        p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
      )
      AND public.te_slot_pareja_actual(p_grupo_id, p.pareja_local_id) IS NOT NULL
      AND public.te_slot_pareja_actual(p_grupo_id, p.pareja_visitante_id) IS NOT NULL
      AND public.te_slot_pareja_actual(p_grupo_id, p.pareja_local_id)
          IS DISTINCT FROM public.te_slot_pareja_actual(p_grupo_id, p.pareja_visitante_id)
      AND NOT EXISTS (SELECT 1 FROM te_sched_assign a WHERE a.match_id = p.id)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INCOMPLETE_PROPOSAL', 'version', v_version);
  END IF;

  IF p_mode = 'faltantes' AND EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    WHERE p.grupo_id = p_grupo_id
      AND p.estado = 'pendiente'
      AND NOT public.te_partido_tiene_historial(
        p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
      )
      AND public.te_slot_pareja_actual(p_grupo_id, p.pareja_local_id) IS NOT NULL
      AND public.te_slot_pareja_actual(p_grupo_id, p.pareja_visitante_id) IS NOT NULL
      AND (
        p.programado_en IS NULL OR public.te_court_key(p.cancha) = ''
      )
      AND NOT EXISTS (SELECT 1 FROM te_sched_assign a WHERE a.match_id = p.id)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INCOMPLETE_PROPOSAL', 'version', v_version);
  END IF;

  INSERT INTO te_sched_courts (time_key, court_key, source)
  SELECT time_key, court_key, 'proposal' FROM te_sched_assign;

  INSERT INTO te_sched_courts (time_key, court_key, source)
  SELECT public.te_mexico_slot_key(p.programado_en), public.te_court_key(p.cancha), 'blocked'
  FROM public.torneo_express_partidos p
  JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
  WHERE g.torneo_id = v_torneo_id
    AND p.programado_en IS NOT NULL
    AND public.te_court_key(p.cancha) <> ''
    AND NOT EXISTS (SELECT 1 FROM te_sched_assign a WHERE a.match_id = p.id);

  INSERT INTO te_sched_courts (time_key, court_key, source)
  SELECT public.te_mexico_slot_key(e.programado_en), public.te_court_key(e.cancha), 'blocked'
  FROM public.torneo_express_eliminatoria_partidos e
  WHERE e.torneo_id = v_torneo_id
    AND e.programado_en IS NOT NULL
    AND public.te_court_key(e.cancha) <> '';

  INSERT INTO te_sched_courts (time_key, court_key, source)
  SELECT public.te_mexico_slot_key((value ->> 'programado_en')::timestamptz),
         public.te_court_key(value ->> 'cancha'),
         'blocked'
  FROM jsonb_array_elements(coalesce(p_occupied, '[]'::jsonb)) AS value
  WHERE value ->> 'programado_en' IS NOT NULL
    AND public.te_court_key(value ->> 'cancha') <> '';

  IF EXISTS (
    SELECT 1
    FROM te_sched_courts proposal
    WHERE proposal.source = 'proposal'
      AND (
        EXISTS (
          SELECT 1 FROM te_sched_courts other
          WHERE other.source = 'blocked'
            AND other.time_key = proposal.time_key
            AND other.court_key = proposal.court_key
        )
        OR (
          SELECT count(*) FROM te_sched_courts twin
          WHERE twin.source = 'proposal'
            AND twin.time_key = proposal.time_key
            AND twin.court_key = proposal.court_key
        ) > 1
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'COURT_SLOT_CONFLICT', 'version', v_version);
  END IF;

  INSERT INTO te_sched_presence (time_key, slot_id, match_id)
  SELECT a.time_key, public.te_slot_pareja_actual(p_grupo_id, p.pareja_local_id), a.match_id
  FROM te_sched_assign a
  JOIN public.torneo_express_partidos p ON p.id = a.match_id
  UNION ALL
  SELECT a.time_key, public.te_slot_pareja_actual(p_grupo_id, p.pareja_visitante_id), a.match_id
  FROM te_sched_assign a
  JOIN public.torneo_express_partidos p ON p.id = a.match_id;

  INSERT INTO te_sched_presence (time_key, slot_id, match_id)
  SELECT
    public.te_mexico_slot_key(p.programado_en),
    coalesce(public.te_slot_pareja_actual(p.grupo_id, p.pareja_local_id), p.pareja_local_id),
    p.id
  FROM public.torneo_express_partidos p
  WHERE p.grupo_id = p_grupo_id
    AND p.programado_en IS NOT NULL
    AND public.te_court_key(p.cancha) <> ''
    AND NOT EXISTS (SELECT 1 FROM te_sched_assign a WHERE a.match_id = p.id)
  UNION ALL
  SELECT
    public.te_mexico_slot_key(p.programado_en),
    coalesce(public.te_slot_pareja_actual(p.grupo_id, p.pareja_visitante_id), p.pareja_visitante_id),
    p.id
  FROM public.torneo_express_partidos p
  WHERE p.grupo_id = p_grupo_id
    AND p.programado_en IS NOT NULL
    AND public.te_court_key(p.cancha) <> ''
    AND NOT EXISTS (SELECT 1 FROM te_sched_assign a WHERE a.match_id = p.id);

  IF EXISTS (
    SELECT 1
    FROM te_sched_presence proposal
    JOIN te_sched_presence other
      ON other.time_key = proposal.time_key
     AND other.slot_id = proposal.slot_id
     AND other.match_id <> proposal.match_id
    WHERE EXISTS (SELECT 1 FROM te_sched_assign a WHERE a.match_id = proposal.match_id)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_SLOT_CONFLICT', 'version', v_version);
  END IF;

  UPDATE public.torneo_express_partidos p
  SET cancha = a.cancha,
      programado_en = a.programado_en,
      orden = a.orden
  FROM te_sched_assign a
  WHERE p.id = a.match_id
    AND p.grupo_id = p_grupo_id
    AND p.estado = 'pendiente'
    AND (
      p.cancha IS DISTINCT FROM a.cancha
      OR p.programado_en IS DISTINCT FROM a.programado_en
      OR p.orden IS DISTINCT FROM a.orden
    );
  GET DIAGNOSTICS v_changed = ROW_COUNT;

  IF EXISTS (
    SELECT 1
    FROM te_sched_assign a
    JOIN public.torneo_express_partidos p ON p.id = a.match_id
    WHERE p.grupo_id IS DISTINCT FROM p_grupo_id
       OR p.estado IS DISTINCT FROM 'pendiente'
       OR public.te_mexico_slot_key(p.programado_en) IS DISTINCT FROM a.time_key
       OR public.te_court_key(p.cancha) IS DISTINCT FROM a.court_key
  ) THEN
    RAISE EXCEPTION 'SCHEDULE_INVARIANT';
  END IF;

  IF v_changed = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'changed', 0,
      'version', v_version
    );
  END IF;

  v_version := public.te_grupo_bump_version(p_grupo_id);
  RETURN jsonb_build_object(
    'ok', true,
    'changed', v_changed,
    'version', v_version
  );
END;
$$;


ALTER FUNCTION "public"."aplicar_programacion_torneo_express_grupo"("p_grupo_id" "uuid", "p_expected_version" integer, "p_mode" "text", "p_now" timestamp with time zone, "p_assignments" "jsonb", "p_courts" "text"[], "p_slots" "jsonb", "p_occupied" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aplicar_rating_partido"("p_j1" "uuid", "p_j2" "uuid", "p_j3" "uuid", "p_j4" "uuid", "p_ganador" "text", "p_modo_juego" "text", "p_partido_ref" "text" DEFAULT NULL::"text", "p_descripcion" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  ids uuid[] := ARRAY[p_j1, p_j2, p_j3, p_j4];
  v_org uuid;
  r record;
  ra numeric;
  rb numeric;
  ea numeric;
  eb numeric;
  sa numeric;
  sb numeric;
  k numeric;
  delta_a numeric;
  delta_b numeric;
  antes numeric;
  despues numeric;
  partidos int;
  fiab numeric;
  d numeric := 0.4;
  v_prev_delta_j1 numeric;
  v_prev_ganador text;
BEGIN
  -- ── Fase 1: autorización (sin cambios) ──
  PERFORM public._assert_rating_rpc_authenticated();

  IF EXISTS (SELECT 1 FROM unnest(ids) u(id) WHERE id IS NULL) THEN
    RAISE EXCEPTION 'Los cuatro jugador_id son obligatorios';
  END IF;

  FOR v_org IN
    SELECT DISTINCT organizador_id
    FROM public.riviera_jugadores
    WHERE id = ANY(ids)
  LOOP
    PERFORM public._assert_rating_rpc_organizador_caller(v_org);
  END LOOP;

  IF p_ganador IS NULL OR p_ganador NOT IN ('a', 'b') THEN
    RAISE EXCEPTION 'p_ganador debe ser ''a'' o ''b''';
  END IF;

  -- ── Reconciliación (nuevo, RANK-001) ──
  -- Antes: "si ya existe cualquier fila para este partido_ref, RETURN".
  -- Ahora: comparar el resultado registrado contra el nuevo; solo hacer
  -- no-op si de verdad es el mismo resultado.
  IF p_partido_ref IS NOT NULL THEN
    SELECT delta INTO v_prev_delta_j1
    FROM rating_historial
    WHERE partido_ref = p_partido_ref AND jugador_id = p_j1
    LIMIT 1;

    IF v_prev_delta_j1 IS NOT NULL THEN
      v_prev_ganador := CASE WHEN v_prev_delta_j1 > 0 THEN 'a' ELSE 'b' END;

      IF v_prev_ganador = p_ganador THEN
        RETURN; -- idempotencia real: mismo resultado ya aplicado.
      END IF;

      -- Resultado cambió: revertir el efecto de ESTE partido_ref para los
      -- jugadores que tengan historial aquí (ver limitación documentada
      -- arriba sobre partidos intermedios no re-encadenados).
      FOR r IN
        SELECT rh.jugador_id, rh.rating_antes
        FROM rating_historial rh
        WHERE rh.partido_ref = p_partido_ref
      LOOP
        UPDATE riviera_jugadores
        SET
          rating = r.rating_antes,
          rating_partidos = GREATEST(0, COALESCE(rating_partidos, 1) - 1),
          rating_fiabilidad = LEAST(1.0, 0.2 + GREATEST(0, COALESCE(rating_partidos, 1) - 1) * 0.04),
          updated_at = now()
        WHERE id = r.jugador_id;
      END LOOP;

      DELETE FROM rating_historial WHERE partido_ref = p_partido_ref;
    END IF;
  END IF;

  -- ── Cálculo del resultado (nuevo o recién revertido) -- sin cambios de
  --    lógica respecto al original ──
  SELECT
    COALESCE(AVG(CASE WHEN id IN (p_j1, p_j2) THEN rating END), 3.0),
    COALESCE(AVG(CASE WHEN id IN (p_j3, p_j4) THEN rating END), 3.0)
  INTO ra, rb
  FROM riviera_jugadores
  WHERE id = ANY(ids);

  ea := 1.0 / (1.0 + power(10.0, (rb - ra) / d));
  eb := 1.0 - ea;

  IF p_ganador = 'a' THEN
    sa := 1.0;
    sb := 0.0;
  ELSE
    sa := 0.0;
    sb := 1.0;
  END IF;

  k := 0.10;

  delta_a := k * (sa - ea);
  delta_b := k * (sb - eb);

  FOR r IN
    SELECT id,
      COALESCE(rating, 3.0) AS rating,
      COALESCE(rating_partidos, 0) AS rating_partidos,
      COALESCE(rating_fiabilidad, 0.2) AS rating_fiabilidad
    FROM riviera_jugadores
    WHERE id = ANY(ids)
  LOOP
    antes := r.rating;
    IF r.id IN (p_j1, p_j2) THEN
      despues := GREATEST(1.0, LEAST(7.0, antes + delta_a));
    ELSE
      despues := GREATEST(1.0, LEAST(7.0, antes + delta_b));
    END IF;

    partidos := r.rating_partidos + 1;
    fiab := LEAST(1.0, 0.2 + partidos * 0.04);

    UPDATE riviera_jugadores
    SET
      rating = ROUND(despues::numeric, 2),
      rating_partidos = partidos,
      rating_fiabilidad = ROUND(fiab::numeric, 2),
      updated_at = now()
    WHERE id = r.id;

    INSERT INTO rating_historial (
      jugador_id, fecha, rating_antes, rating_despues, delta,
      modo_juego, descripcion, partido_ref
    ) VALUES (
      r.id,
      now(),
      ROUND(antes::numeric, 2),
      ROUND(despues::numeric, 2),
      ROUND((despues - antes)::numeric, 2),
      p_modo_juego,
      p_descripcion,
      p_partido_ref
    )
    ON CONFLICT (jugador_id, partido_ref) WHERE partido_ref IS NOT NULL DO NOTHING;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."aplicar_rating_partido"("p_j1" "uuid", "p_j2" "uuid", "p_j3" "uuid", "p_j4" "uuid", "p_ganador" "text", "p_modo_juego" "text", "p_partido_ref" "text", "p_descripcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."append_torneo_express_pareja_grupo"("p_torneo_id" "uuid", "p_grupo_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_partidos" "jsonb", "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_guard jsonb;
  v_grupo_id uuid;
  v_version integer;
  v_name1 text;
  v_name2 text;
  v_tournament_id uuid;
  v_tournament_count integer;
  v_null_tournament integer;
  v_pareja_id uuid;
  v_group_count integer;
  v_payload_count integer;
  v_max_ronda integer;
  v_max_orden integer;
  v_scheduled_count integer;
  v_category_count integer;
  v_category_incomplete integer;
  v_last_slot text;
  elem jsonb;
  v_rival uuid;
  v_ronda integer;
  v_orden integer;
  v_cancha text;
  v_programado timestamptz;
  v_created integer := 0;
BEGIN
  v_guard := public.te_lock_categoria_editable(p_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    RETURN v_guard;
  END IF;

  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
  END IF;

  -- lock-order: grupo
  SELECT g.id, g.version
    INTO v_grupo_id, v_version
  FROM public.torneo_express_grupos g
  WHERE g.id = p_grupo_id
    AND g.torneo_id = p_torneo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
  END IF;

  IF p_expected_version IS NULL OR p_expected_version IS DISTINCT FROM v_version THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'STALE_GROUP_VERSION',
      'version', v_version
    );
  END IF;

  -- lock-order: partidos. Después del grupo, como apply y reset.
  BEGIN
    PERFORM 1
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
    ORDER BY p.id
    FOR UPDATE OF p NOWAIT;
  EXCEPTION
    WHEN lock_not_available THEN
      RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
  END;

  IF p_player1_id IS NULL OR p_player2_id IS NULL OR p_player1_id = p_player2_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
  END IF;

  SELECT btrim(name) INTO v_name1 FROM public.players WHERE id = p_player1_id;
  SELECT btrim(name) INTO v_name2 FROM public.players WHERE id = p_player2_id;
  IF v_name1 IS NULL OR v_name1 = '' OR v_name2 IS NULL OR v_name2 = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_NOT_FOUND');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.pairs pr ON pr.id = gp.pareja_id
    WHERE gp.grupo_id = v_grupo_id
      AND gp.activa
      AND (
        (pr.player1_id = p_player1_id AND pr.player2_id = p_player2_id)
        OR (pr.player1_id = p_player2_id AND pr.player2_id = p_player1_id)
      )
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'PAIR_ALREADY_IN_GROUP',
      'version', v_version
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    JOIN public.pairs pr ON pr.id = gp.pareja_id
    WHERE g.torneo_id = p_torneo_id
      AND (
        pr.player1_id IN (p_player1_id, p_player2_id)
        OR pr.player2_id IN (p_player1_id, p_player2_id)
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_ALREADY_REGISTERED');
  END IF;

  SELECT count(DISTINCT pr.tournament_id) FILTER (WHERE pr.tournament_id IS NOT NULL),
         count(*) FILTER (WHERE pr.tournament_id IS NULL)
    INTO v_tournament_count, v_null_tournament
  FROM public.torneo_express_grupo_parejas gp
  JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
  JOIN public.pairs pr ON pr.id = gp.pareja_id
  WHERE g.torneo_id = p_torneo_id;

  IF v_null_tournament > 0 OR v_tournament_count <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_TOURNAMENT_UNRESOLVED');
  END IF;

  SELECT DISTINCT pr.tournament_id INTO v_tournament_id
  FROM public.torneo_express_grupo_parejas gp
  JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
  JOIN public.pairs pr ON pr.id = gp.pareja_id
  WHERE g.torneo_id = p_torneo_id
    AND pr.tournament_id IS NOT NULL;

  IF p_partidos IS NULL OR jsonb_typeof(p_partidos) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
  END IF;

  DROP TABLE IF EXISTS te_append_partidos;

  SELECT count(*) INTO v_group_count
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = v_grupo_id
    AND activa;

  v_payload_count := jsonb_array_length(p_partidos);
  IF v_payload_count <> v_group_count THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
  END IF;

  SELECT coalesce(max(CASE WHEN p.ronda > 0 THEN p.ronda ELSE 0 END), 0),
         coalesce(max(CASE WHEN p.orden > 0 THEN p.orden ELSE 0 END), 0)
    INTO v_max_ronda, v_max_orden
  FROM public.torneo_express_partidos p
  WHERE p.grupo_id = v_grupo_id;

  CREATE TEMP TABLE te_append_partidos (
    rival_id uuid PRIMARY KEY,
    ronda integer NOT NULL,
    orden integer NOT NULL,
    cancha text,
    programado_en timestamptz,
    scheduled boolean NOT NULL
  ) ON COMMIT DROP;

  FOR elem IN SELECT value FROM jsonb_array_elements(p_partidos) LOOP
    BEGIN
      v_rival := (elem ->> 'rival_id')::uuid;
      v_ronda := (elem ->> 'ronda')::integer;
      v_orden := (elem ->> 'orden')::integer;
    EXCEPTION
      WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
    END;

    IF v_rival IS NULL OR v_ronda IS NULL OR v_orden IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.torneo_express_grupo_parejas
      WHERE grupo_id = v_grupo_id AND pareja_id = v_rival AND activa
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
    END IF;

    IF v_ronda <> v_max_ronda + 1
       OR v_orden <= v_max_orden
       OR v_orden > v_max_orden + v_group_count THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
    END IF;

    v_cancha := nullif(btrim(elem ->> 'cancha'), '');
    BEGIN
      IF nullif(btrim(elem ->> 'programado_en'), '') IS NULL THEN
        v_programado := NULL;
      ELSE
        v_programado := (elem ->> 'programado_en')::timestamptz;
      END IF;
    EXCEPTION
      WHEN invalid_text_representation OR datetime_field_overflow THEN
        RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
    END;

    BEGIN
      INSERT INTO te_append_partidos (rival_id, ronda, orden, cancha, programado_en, scheduled)
      VALUES (
        v_rival, v_ronda, v_orden, v_cancha, v_programado,
        v_cancha IS NOT NULL AND v_programado IS NOT NULL
      );
    EXCEPTION
      WHEN unique_violation THEN
        RETURN jsonb_build_object('ok', false, 'error', 'DUPLICATE_MATCH');
    END;
  END LOOP;

  IF (SELECT count(*) FROM te_append_partidos) <> v_group_count
     OR (SELECT count(DISTINCT orden) FROM te_append_partidos) <> v_group_count THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    WHERE gp.grupo_id = v_grupo_id
      AND gp.activa
      AND NOT EXISTS (
        SELECT 1 FROM te_append_partidos a WHERE a.rival_id = gp.pareja_id
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
  END IF;

  SELECT count(*) FILTER (WHERE scheduled),
         count(*) FILTER (WHERE NOT scheduled)
    INTO v_scheduled_count, v_payload_count
  FROM te_append_partidos;

  IF v_scheduled_count <> 0 AND v_payload_count <> 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
  END IF;

  SELECT count(*) INTO v_category_count
  FROM public.torneo_express_partidos p
  JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
  WHERE g.torneo_id = p_torneo_id;

  SELECT count(*) INTO v_category_incomplete
  FROM public.torneo_express_partidos p
  JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
  WHERE g.torneo_id = p_torneo_id
    AND (p.programado_en IS NULL OR p.cancha IS NULL OR btrim(p.cancha) = '');

  IF v_scheduled_count = 0 THEN
    IF v_category_count > 0 AND v_category_incomplete = 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
    END IF;
  ELSE
    IF v_category_count = 0 OR v_category_incomplete > 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
    END IF;

    SELECT max(public.te_mexico_slot_key(p.programado_en))
      INTO v_last_slot
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND p.programado_en IS NOT NULL;

    IF EXISTS (
      SELECT 1 FROM te_append_partidos a
      WHERE public.te_mexico_slot_key(a.programado_en) <= v_last_slot
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM te_append_partidos a
      JOIN te_append_partidos b
        ON a.rival_id <> b.rival_id
       AND public.te_mexico_slot_key(a.programado_en) = public.te_mexico_slot_key(b.programado_en)
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM te_append_partidos a
      JOIN public.torneo_express_partidos p ON true
      JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
      WHERE g.torneo_id = p_torneo_id
        AND public.te_mexico_slot_key(p.programado_en) = public.te_mexico_slot_key(a.programado_en)
        AND (
          btrim(p.cancha) = a.cancha
          OR p.pareja_local_id = a.rival_id
          OR p.pareja_visitante_id = a.rival_id
        )
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
    END IF;
  END IF;

  INSERT INTO public.pairs (
    id, tournament_id, player1_id, player2_id, player1_name, player2_name, is_virtual, virtual_label
  ) VALUES (
    gen_random_uuid(), v_tournament_id, p_player1_id, p_player2_id, v_name1, v_name2, false, NULL
  )
  RETURNING id INTO v_pareja_id;

  INSERT INTO public.torneo_express_grupo_parejas (grupo_id, pareja_id)
  VALUES (v_grupo_id, v_pareja_id);

  INSERT INTO public.torneo_express_partidos (
    id, grupo_id, pareja_local_id, pareja_visitante_id, estado, ronda, orden, cancha, programado_en
  )
  SELECT
    gen_random_uuid(), v_grupo_id, v_pareja_id, a.rival_id, 'pendiente', a.ronda, a.orden, a.cancha, a.programado_en
  FROM te_append_partidos a;

  GET DIAGNOSTICS v_created = ROW_COUNT;
  v_version := public.te_grupo_bump_version(v_grupo_id);

  RETURN jsonb_build_object(
    'ok', true,
    'pareja_id', v_pareja_id,
    'partidos_creados', v_created,
    'version', v_version
  );
END;
$$;


ALTER FUNCTION "public"."append_torneo_express_pareja_grupo"("p_torneo_id" "uuid", "p_grupo_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_partidos" "jsonb", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_americano_live_match_score"("p_tournament_id" "uuid", "p_match_id" "text", "p_score_a" integer, "p_score_b" integer, "p_ranking" "jsonb", "p_phase" "text", "p_total_rounds" integer, "p_roster" "jsonb", "p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_organizador uuid;
  v_snapshot jsonb;
  v_rounds jsonb;
  v_i int;
  v_j int;
  v_round_idx int;
  v_match_idx int;
  v_found boolean := false;
  v_existing_a jsonb;
  v_existing_b jsonb;
  v_new_rounds jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_match_id IS NULL OR length(trim(p_match_id)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_match');
  END IF;

  IF p_score_a IS NULL OR p_score_b IS NULL OR p_score_a < 0 OR p_score_b < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
  END IF;

  SELECT user_id INTO v_organizador
  FROM public.tournaments
  WHERE id = p_tournament_id;

  IF v_organizador IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  SELECT americano_live INTO v_snapshot
  FROM public.tournament_public_config
  WHERE tournament_id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND OR v_snapshot IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  v_rounds := coalesce(v_snapshot -> 'rounds', '[]'::jsonb);

  -- NOTA: no se reutilizan v_round_idx/v_match_idx como variables de control
  -- del FOR -- PL/pgSQL crea una variable entera implícita propia del loop
  -- que ignora/sombrea cualquier variable ya declarada con el mismo nombre
  -- (documentado en la referencia de PL/pgSQL), dejando v_round_idx/
  -- v_match_idx en NULL fuera del loop si se reutilizan así. Se usan v_i/v_j
  -- como contadores del loop y se asignan explícitamente a v_round_idx/
  -- v_match_idx solo al encontrar el partido (confirmado con prueba real
  -- contra Postgres en Fase A: sin este fix, jsonb_set fallaba con
  -- "path element at position 1 is null").
  <<search>>
  FOR v_i IN 0 .. jsonb_array_length(v_rounds) - 1 LOOP
    FOR v_j IN 0 .. jsonb_array_length(v_rounds -> v_i -> 'matches') - 1 LOOP
      IF (v_rounds -> v_i -> 'matches' -> v_j ->> 'id') = p_match_id THEN
        v_found := true;
        v_round_idx := v_i;
        v_match_idx := v_j;
        EXIT search;
      END IF;
    END LOOP;
  END LOOP search;

  IF NOT v_found THEN
    RETURN jsonb_build_object('ok', false, 'error', 'match_not_found');
  END IF;

  v_existing_a := v_rounds -> v_round_idx -> 'matches' -> v_match_idx -> 'scoreA';
  v_existing_b := v_rounds -> v_round_idx -> 'matches' -> v_match_idx -> 'scoreB';

  -- Idempotente: mismo resultado ya guardado para este partido.
  IF v_existing_a IS NOT NULL AND v_existing_b IS NOT NULL
     AND (v_existing_a)::text::int = p_score_a
     AND (v_existing_b)::text::int = p_score_b
  THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'unchanged',
      'match_id', p_match_id,
      'snapshot', v_snapshot
    );
  END IF;

  -- Conflicto explícito: el MISMO partido ya tiene otro resultado guardado
  -- (por otro dispositivo) y no se pidió forzar la sobrescritura.
  IF v_existing_a IS NOT NULL AND v_existing_b IS NOT NULL AND NOT p_force THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'conflict',
      'match_id', p_match_id,
      'score_a', (v_existing_a)::text::int,
      'score_b', (v_existing_b)::text::int
    );
  END IF;

  v_new_rounds := jsonb_set(
    jsonb_set(
      v_rounds,
      ARRAY[v_round_idx::text, 'matches', v_match_idx::text, 'scoreA'],
      to_jsonb(p_score_a)
    ),
    ARRAY[v_round_idx::text, 'matches', v_match_idx::text, 'scoreB'],
    to_jsonb(p_score_b)
  );

  v_snapshot := jsonb_set(v_snapshot, ARRAY['rounds'], v_new_rounds);

  IF p_ranking IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['ranking'], p_ranking);
  END IF;
  IF p_phase IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['tournamentPhase'], to_jsonb(p_phase));
  END IF;
  IF p_total_rounds IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['totalRounds'], to_jsonb(p_total_rounds));
  END IF;
  IF p_roster IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['roster'], p_roster);
  END IF;
  -- Timestamp del SERVIDOR, nunca confiado al reloj del cliente.
  v_snapshot := jsonb_set(
    v_snapshot,
    ARRAY['savedAt'],
    to_jsonb(to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
  );

  UPDATE public.tournament_public_config
  SET americano_live = v_snapshot
  WHERE tournament_id = p_tournament_id;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'updated',
    'match_id', p_match_id,
    'snapshot', v_snapshot
  );
END;
$$;


ALTER FUNCTION "public"."apply_americano_live_match_score"("p_tournament_id" "uuid", "p_match_id" "text", "p_score_a" integer, "p_score_b" integer, "p_ranking" "jsonb", "p_phase" "text", "p_total_rounds" integer, "p_roster" "jsonb", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_americano_live_metadata"("p_tournament_id" "uuid", "p_ranking" "jsonb", "p_phase" "text", "p_total_rounds" integer, "p_roster" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_organizador uuid;
  v_snapshot jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT user_id INTO v_organizador
  FROM public.tournaments
  WHERE id = p_tournament_id;

  IF v_organizador IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  SELECT americano_live INTO v_snapshot
  FROM public.tournament_public_config
  WHERE tournament_id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND OR v_snapshot IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF p_ranking IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['ranking'], p_ranking);
  END IF;
  IF p_phase IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['tournamentPhase'], to_jsonb(p_phase));
  END IF;
  IF p_total_rounds IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['totalRounds'], to_jsonb(p_total_rounds));
  END IF;
  IF p_roster IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['roster'], p_roster);
  END IF;
  v_snapshot := jsonb_set(
    v_snapshot,
    ARRAY['savedAt'],
    to_jsonb(to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
  );

  UPDATE public.tournament_public_config
  SET americano_live = v_snapshot
  WHERE tournament_id = p_tournament_id;

  RETURN jsonb_build_object('ok', true, 'snapshot', v_snapshot);
END;
$$;


ALTER FUNCTION "public"."apply_americano_live_metadata"("p_tournament_id" "uuid", "p_ranking" "jsonb", "p_phase" "text", "p_total_rounds" integer, "p_roster" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_americano_new_round"("p_tournament_id" "uuid", "p_round_number" integer, "p_idempotency_key" "text", "p_round_data" "jsonb", "p_ranking" "jsonb", "p_phase" "text", "p_total_rounds" integer, "p_roster" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_organizador uuid;
  v_snapshot jsonb;
  v_rounds jsonb;
  v_i int;
  v_existing_round jsonb;
  v_round_with_key jsonb;
  v_new_rounds jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_round_number IS NULL OR p_round_number < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_round_number');
  END IF;

  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_idempotency_key');
  END IF;

  IF p_round_data IS NULL OR jsonb_typeof(p_round_data -> 'matches') <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_round_data');
  END IF;

  SELECT user_id INTO v_organizador
  FROM public.tournaments
  WHERE id = p_tournament_id;

  IF v_organizador IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  SELECT americano_live INTO v_snapshot
  FROM public.tournament_public_config
  WHERE tournament_id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    -- Aún no existe fila (carrera con el guardado debounced de "registration")
    -- -- la creamos aquí mismo en vez de depender de ese timing.
    INSERT INTO public.tournament_public_config (tournament_id, format, americano_live)
    VALUES (
      p_tournament_id,
      'americano_dinamico',
      jsonb_build_object('version', 1, 'rounds', '[]'::jsonb, 'ranking', '[]'::jsonb)
    )
    ON CONFLICT (tournament_id) DO NOTHING;

    SELECT americano_live INTO v_snapshot
    FROM public.tournament_public_config
    WHERE tournament_id = p_tournament_id
    FOR UPDATE;

    IF NOT FOUND OR v_snapshot IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_found');
    END IF;
  END IF;

  v_rounds := coalesce(v_snapshot -> 'rounds', '[]'::jsonb);

  -- Idempotencia por key: si ya existe una ronda con esta key, se devuelve
  -- tal cual (la autoritativa del servidor), sin duplicar ni pisar nada.
  FOR v_i IN 0 .. jsonb_array_length(v_rounds) - 1 LOOP
    IF (v_rounds -> v_i ->> 'idempotencyKey') = p_idempotency_key THEN
      v_existing_round := v_rounds -> v_i;
      EXIT;
    END IF;
  END LOOP;

  IF v_existing_round IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'exists',
      'round', v_existing_round,
      'snapshot', v_snapshot
    );
  END IF;

  -- Debe ser exactamente la siguiente ronda esperada -- rechaza huecos o
  -- rondas fuera de orden de un cliente desincronizado.
  IF p_round_number <> jsonb_array_length(v_rounds) + 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'out_of_order',
      'expected_round_number', jsonb_array_length(v_rounds) + 1,
      'rounds', v_rounds
    );
  END IF;

  v_round_with_key := p_round_data || jsonb_build_object('idempotencyKey', p_idempotency_key);
  v_new_rounds := v_rounds || jsonb_build_array(v_round_with_key);

  v_snapshot := jsonb_set(v_snapshot, ARRAY['rounds'], v_new_rounds);

  IF p_ranking IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['ranking'], p_ranking);
  END IF;
  IF p_phase IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['tournamentPhase'], to_jsonb(p_phase));
  END IF;
  IF p_total_rounds IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['totalRounds'], to_jsonb(p_total_rounds));
  END IF;
  IF p_roster IS NOT NULL THEN
    v_snapshot := jsonb_set(v_snapshot, ARRAY['roster'], p_roster);
  END IF;
  v_snapshot := jsonb_set(
    v_snapshot,
    ARRAY['savedAt'],
    to_jsonb(to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
  );

  UPDATE public.tournament_public_config
  SET americano_live = v_snapshot
  WHERE tournament_id = p_tournament_id;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'created',
    'round', v_round_with_key,
    'snapshot', v_snapshot
  );
END;
$$;


ALTER FUNCTION "public"."apply_americano_new_round"("p_tournament_id" "uuid", "p_round_number" integer, "p_idempotency_key" "text", "p_round_data" "jsonb", "p_ranking" "jsonb", "p_phase" "text", "p_total_rounds" integer, "p_roster" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_reta_match_update"("p_match_id" "uuid", "p_court" integer DEFAULT NULL::integer, "p_round" integer DEFAULT NULL::integer, "p_sets" "jsonb" DEFAULT NULL::"jsonb", "p_force" boolean DEFAULT false, "p_admin_override" boolean DEFAULT false, "p_admin_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match record;
  v_tournament_owner uuid;
  v_tournament_closed boolean;
  v_is_admin boolean := false;
  v_i int;
  v_set jsonb;
  v_pair1_score int;
  v_pair2_score int;
  v_existing_sets jsonb;
  v_new_sets jsonb := '[]'::jsonb;
  v_dynamic_lineups_enabled boolean;
  v_dynamic_block_locked boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT m.*, t.user_id AS tournament_owner, coalesce(t.is_finished, false) AS tournament_closed
  INTO v_match
  FROM public.matches m
  JOIN public.tournaments t ON t.id = m.tournament_id
  WHERE m.id = p_match_id
  FOR UPDATE OF m;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  v_tournament_owner := v_match.tournament_owner;
  v_tournament_closed := v_match.tournament_closed;

  IF p_admin_override THEN
    SELECT public.is_master_admin() INTO v_is_admin;
    IF NOT v_is_admin THEN
      RAISE EXCEPTION 'Solo un Admin Maestro puede usar corrección administrativa';
    END IF;
  ELSIF v_tournament_owner IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este partido';
  END IF;

  -- FC-05: edición normal bloqueada tras el cierre del torneo (mismo
  -- criterio que Torneo Express) -- p_admin_override (ya validado arriba
  -- como exclusivo de Admin Maestro) es la única vía para saltarlo.
  IF v_tournament_closed AND NOT p_admin_override THEN
    RETURN jsonb_build_object('ok', false, 'error', 'tournament_closed');
  END IF;

  -- ── Reasignación de cancha/ronda (metadata, no toca marcador) ──
  IF p_court IS NOT NULL OR p_round IS NOT NULL THEN
    UPDATE public.matches
    SET
      court = coalesce(p_court, court),
      round = coalesce(p_round, round)
    WHERE id = p_match_id;
  END IF;

  -- ── Resultado (sets) ──
  IF p_sets IS NOT NULL THEN
    IF jsonb_typeof(p_sets) <> 'array' OR jsonb_array_length(p_sets) = 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_sets');
    END IF;

    v_pair1_score := 0;
    v_pair2_score := 0;
    FOR v_i IN 0 .. jsonb_array_length(p_sets) - 1 LOOP
      v_set := p_sets -> v_i;
      IF NOT (v_set ? 'pair1_games') OR NOT (v_set ? 'pair2_games') THEN
        RETURN jsonb_build_object('ok', false, 'error', 'invalid_sets');
      END IF;
      IF (v_set->>'pair1_games')::int >= 6 THEN
        v_pair1_score := v_pair1_score + 1;
      END IF;
      IF (v_set->>'pair2_games')::int >= 6 THEN
        v_pair2_score := v_pair2_score + 1;
      END IF;
      v_new_sets := v_new_sets || jsonb_build_array(jsonb_build_object(
        'game_number', v_i + 1,
        'pair1_games', (v_set->>'pair1_games')::int,
        'pair2_games', (v_set->>'pair2_games')::int,
        'is_tie_break', coalesce((v_set->>'is_tie_break')::boolean, false),
        'tie_break_pair1_points', coalesce((v_set->>'tie_break_pair1_points')::int, 0),
        'tie_break_pair2_points', coalesce((v_set->>'tie_break_pair2_points')::int, 0)
      ));
    END LOOP;

    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'game_number', g.game_number,
             'pair1_games', g.pair1_games,
             'pair2_games', g.pair2_games,
             'is_tie_break', g.is_tie_break,
             'tie_break_pair1_points', g.tie_break_pair1_points,
             'tie_break_pair2_points', g.tie_break_pair2_points
           ) ORDER BY g.game_number), '[]'::jsonb)
    INTO v_existing_sets
    FROM public.games g
    WHERE g.match_id = p_match_id;

    -- Idempotente: mismo resultado ya guardado (mismos sets y mismo status).
    -- v_existing_sets viene ordenado por game_number ascendente (igual que
    -- v_new_sets, construido en el mismo orden 1..N) -- comparación directa.
    IF v_match.status = 'finished'
       AND v_match.pair1_score = v_pair1_score
       AND v_match.pair2_score = v_pair2_score
       AND v_existing_sets = v_new_sets
    THEN
      RETURN jsonb_build_object(
        'ok', true, 'status', 'unchanged',
        'pair1_score', v_pair1_score, 'pair2_score', v_pair2_score, 'sets', v_existing_sets
      );
    END IF;

    -- Alineación dinámica: bloquear un CAMBIO real de resultado en una ronda
    -- que ya se usó para generar un bloque posterior (ver comentario arriba
    -- de esta función). Solo si dynamicLineups.enabled -- Equipos clásico y
    -- el resto de modalidades no se ven afectados.
    IF v_match.status = 'finished' AND NOT p_admin_override THEN
      SELECT coalesce((t.team_config -> 'dynamicLineups' ->> 'enabled')::boolean, false)
      INTO v_dynamic_lineups_enabled
      FROM public.tournaments t
      WHERE t.id = v_match.tournament_id;

      IF v_dynamic_lineups_enabled THEN
        SELECT EXISTS (
          SELECT 1
          FROM public.reta_dynamic_blocks owner_block
          WHERE owner_block.tournament_id = v_match.tournament_id
            AND v_match.round BETWEEN owner_block.round_start AND owner_block.round_end
            AND EXISTS (
              SELECT 1 FROM public.reta_dynamic_blocks later_block
              WHERE later_block.tournament_id = owner_block.tournament_id
                AND later_block.block_number > owner_block.block_number
            )
        ) INTO v_dynamic_block_locked;

        IF v_dynamic_block_locked THEN
          RETURN jsonb_build_object('ok', false, 'error', 'dynamic_block_locked');
        END IF;
      END IF;
    END IF;

    -- Conflicto explícito: el partido ya estaba finalizado con OTRO
    -- resultado y no se pidió forzar ni es corrección administrativa.
    IF v_match.status = 'finished' AND NOT p_force AND NOT p_admin_override THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'conflict',
        'pair1_score', v_match.pair1_score, 'pair2_score', v_match.pair2_score, 'sets', v_existing_sets
      );
    END IF;

    IF p_admin_override THEN
      INSERT INTO public.reta_match_admin_corrections (
        match_id, admin_user_id, previous_status, previous_pair1_score,
        previous_pair2_score, previous_sets, new_pair1_score, new_pair2_score,
        new_sets, reason
      ) VALUES (
        p_match_id, auth.uid(), v_match.status, v_match.pair1_score,
        v_match.pair2_score, v_existing_sets, v_pair1_score, v_pair2_score,
        v_new_sets, p_admin_reason
      );
    END IF;

    DELETE FROM public.games WHERE match_id = p_match_id;

    FOR v_i IN 0 .. jsonb_array_length(v_new_sets) - 1 LOOP
      v_set := v_new_sets -> v_i;
      INSERT INTO public.games (
        match_id, game_number, pair1_games, pair2_games,
        is_tie_break, tie_break_pair1_points, tie_break_pair2_points
      ) VALUES (
        p_match_id, (v_set->>'game_number')::int,
        (v_set->>'pair1_games')::int, (v_set->>'pair2_games')::int,
        (v_set->>'is_tie_break')::boolean,
        (v_set->>'tie_break_pair1_points')::int, (v_set->>'tie_break_pair2_points')::int
      );
    END LOOP;

    UPDATE public.matches
    SET status = 'finished', pair1_score = v_pair1_score, pair2_score = v_pair2_score
    WHERE id = p_match_id;

    RETURN jsonb_build_object(
      'ok', true, 'status', 'updated',
      'pair1_score', v_pair1_score, 'pair2_score', v_pair2_score, 'sets', v_new_sets
    );
  END IF;

  RETURN jsonb_build_object('ok', true, 'status', 'updated_metadata');
END;
$$;


ALTER FUNCTION "public"."apply_reta_match_update"("p_match_id" "uuid", "p_court" integer, "p_round" integer, "p_sets" "jsonb", "p_force" boolean, "p_admin_override" boolean, "p_admin_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_torneo_express_eliminatoria_writes"("p_torneo_id" "uuid", "p_updates" "jsonb" DEFAULT '[]'::"jsonb", "p_inserts" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_organizador uuid;
  v_torneo record;
  v_update jsonb;
  v_insert jsonb;
  v_id uuid;
  v_keys text[];
  v_allowed_update_keys text[] := ARRAY[
    'id','pareja_local_id','pareja_visitante_id','puntos_local',
    'puntos_visitante','ganador_id','estado','sets_resultado'
  ];
  -- torneo_id llega del FE (builders) pero el valor escrito es siempre p_torneo_id.
  -- sets_resultado/cancha/programado_en: tolerados si el payload los trae.
  v_allowed_insert_keys text[] := ARRAY[
    'torneo_id','ronda','orden','cruce_index','pareja_local_id','pareja_visitante_id',
    'puntos_local','puntos_visitante','ganador_id','estado','es_bye','sets_resultado',
    'cancha','programado_en'
  ];
  v_seen_ids uuid[] := ARRAY[]::uuid[];
  v_valid_parejas uuid[];
  v_applied_updates int := 0;
  v_applied_inserts int := 0;
  v_inserted_ids uuid[] := ARRAY[]::uuid[];
  v_skipped_duplicate_inserts int := 0;
  v_new_id uuid;
  v_ronda int;
  v_cruce int;
  v_estado text;
  v_pareja_local uuid;
  v_pareja_visitante uuid;
  v_ganador uuid;
  v_row record;
BEGIN
  -- (1) usuario autenticado
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_torneo_id IS NULL THEN
    RAISE EXCEPTION 'torneo_id requerido';
  END IF;

  -- (12) lock del bracket completo — serializa cualquier escritura
  -- concurrente sobre este torneo antes de leer/validar nada más.
  PERFORM 1
  FROM public.torneo_express_eliminatoria_partidos
  WHERE torneo_id = p_torneo_id
  FOR UPDATE;

  SELECT * INTO v_torneo
  FROM public.torneo_express
  WHERE id = p_torneo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Torneo no encontrado';
  END IF;

  -- (2) ownership — SECURITY DEFINER bypasea RLS, se valida a mano.
  v_organizador := v_torneo.organizador_id;
  IF v_organizador IS NULL OR v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  -- (3) torneo no cerrado
  IF v_torneo.fase_torneo = 'cerrado' OR v_torneo.estado = 'finalizado' THEN
    RAISE EXCEPTION 'Este torneo ya fue cerrado. Para modificar resultados primero debe reabrirse.';
  END IF;

  -- Parejas conocidas de este torneo (de partidos ya existentes) — base
  -- para validar (9) sin reimplementar reglas de bracket.
  SELECT array_agg(DISTINCT x) INTO v_valid_parejas
  FROM (
    SELECT pareja_local_id AS x
    FROM public.torneo_express_eliminatoria_partidos
    WHERE torneo_id = p_torneo_id AND pareja_local_id IS NOT NULL
    UNION
    SELECT pareja_visitante_id
    FROM public.torneo_express_eliminatoria_partidos
    WHERE torneo_id = p_torneo_id AND pareja_visitante_id IS NOT NULL
    UNION
    SELECT ganador_id
    FROM public.torneo_express_eliminatoria_partidos
    WHERE torneo_id = p_torneo_id AND ganador_id IS NOT NULL
  ) s;

  -- ── UPDATES ──
  FOR v_update IN SELECT * FROM jsonb_array_elements(coalesce(p_updates, '[]'::jsonb))
  LOOP
    -- (6/10) solo columnas autorizadas
    SELECT array_agg(k) INTO v_keys FROM jsonb_object_keys(v_update) AS k;
    IF EXISTS (
      SELECT 1 FROM unnest(coalesce(v_keys, ARRAY[]::text[])) k
      WHERE NOT (k = ANY(v_allowed_update_keys))
    ) THEN
      RAISE EXCEPTION 'Columna no autorizada en UPDATE';
    END IF;

    IF NOT (v_update ? 'id') OR v_update->>'id' IS NULL THEN
      RAISE EXCEPTION 'UPDATE sin id';
    END IF;
    v_id := (v_update->>'id')::uuid;

    -- (5) ningún id repetido en el payload
    IF v_id = ANY(v_seen_ids) THEN
      RAISE EXCEPTION 'id repetido en el payload de UPDATE: %', v_id;
    END IF;
    v_seen_ids := array_append(v_seen_ids, v_id);

    -- (4) el id pertenece a este torneo (contra la fila real, ya bajo lock)
    SELECT * INTO v_row
    FROM public.torneo_express_eliminatoria_partidos
    WHERE id = v_id AND torneo_id = p_torneo_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Partido % no pertenece a este torneo', v_id;
    END IF;

    IF v_update ? 'estado' AND NOT (v_update->>'estado' IN ('pendiente', 'jugado')) THEN
      RAISE EXCEPTION 'estado inválido en UPDATE: %', v_update->>'estado';
    END IF;

    -- (9) parejas referenciadas deben pertenecer al torneo
    IF v_update ? 'pareja_local_id' AND v_update->>'pareja_local_id' IS NOT NULL THEN
      IF NOT ((v_update->>'pareja_local_id')::uuid = ANY(coalesce(v_valid_parejas, ARRAY[]::uuid[]))) THEN
        RAISE EXCEPTION 'pareja_local_id no pertenece a este torneo';
      END IF;
    END IF;
    IF v_update ? 'pareja_visitante_id' AND v_update->>'pareja_visitante_id' IS NOT NULL THEN
      IF NOT ((v_update->>'pareja_visitante_id')::uuid = ANY(coalesce(v_valid_parejas, ARRAY[]::uuid[]))) THEN
        RAISE EXCEPTION 'pareja_visitante_id no pertenece a este torneo';
      END IF;
    END IF;

    -- (9) ganador_id, si se manda, debe corresponder a una de las 2 parejas
    -- del propio partido (considerando el patch de esta misma llamada).
    IF v_update ? 'ganador_id' AND v_update->>'ganador_id' IS NOT NULL THEN
      v_ganador := (v_update->>'ganador_id')::uuid;
      v_pareja_local := CASE
        WHEN v_update ? 'pareja_local_id' THEN NULLIF(v_update->>'pareja_local_id', '')::uuid
        ELSE v_row.pareja_local_id
      END;
      v_pareja_visitante := CASE
        WHEN v_update ? 'pareja_visitante_id' THEN NULLIF(v_update->>'pareja_visitante_id', '')::uuid
        ELSE v_row.pareja_visitante_id
      END;
      IF v_ganador IS DISTINCT FROM v_pareja_local AND v_ganador IS DISTINCT FROM v_pareja_visitante THEN
        RAISE EXCEPTION 'ganador_id no corresponde a ninguna pareja del partido %', v_id;
      END IF;
    END IF;

    UPDATE public.torneo_express_eliminatoria_partidos SET
      pareja_local_id = CASE WHEN v_update ? 'pareja_local_id' THEN NULLIF(v_update->>'pareja_local_id', '')::uuid ELSE pareja_local_id END,
      pareja_visitante_id = CASE WHEN v_update ? 'pareja_visitante_id' THEN NULLIF(v_update->>'pareja_visitante_id', '')::uuid ELSE pareja_visitante_id END,
      puntos_local = CASE WHEN v_update ? 'puntos_local' THEN NULLIF(v_update->>'puntos_local', '')::int ELSE puntos_local END,
      puntos_visitante = CASE WHEN v_update ? 'puntos_visitante' THEN NULLIF(v_update->>'puntos_visitante', '')::int ELSE puntos_visitante END,
      ganador_id = CASE WHEN v_update ? 'ganador_id' THEN NULLIF(v_update->>'ganador_id', '')::uuid ELSE ganador_id END,
      estado = CASE WHEN v_update ? 'estado' THEN (v_update->>'estado') ELSE estado END,
      sets_resultado = CASE WHEN v_update ? 'sets_resultado' THEN (v_update->'sets_resultado') ELSE sets_resultado END
    WHERE id = v_id;

    v_applied_updates := v_applied_updates + 1;
  END LOOP;

  -- ── INSERTS ──
  FOR v_insert IN SELECT * FROM jsonb_array_elements(coalesce(p_inserts, '[]'::jsonb))
  LOOP
    SELECT array_agg(k) INTO v_keys FROM jsonb_object_keys(v_insert) AS k;
    IF EXISTS (
      SELECT 1 FROM unnest(coalesce(v_keys, ARRAY[]::text[])) k
      WHERE NOT (k = ANY(v_allowed_insert_keys))
    ) THEN
      RAISE EXCEPTION 'Columna no autorizada en INSERT';
    END IF;

    IF NOT (v_insert ? 'ronda') OR NOT (v_insert ? 'cruce_index') THEN
      RAISE EXCEPTION 'INSERT requiere ronda y cruce_index';
    END IF;
    v_ronda := (v_insert->>'ronda')::int;
    v_cruce := (v_insert->>'cruce_index')::int;

    -- (8) ronda/cruce_index válidos (90 = ronda especial de 3.er lugar)
    IF v_ronda IS NULL OR (v_ronda <= 0 AND v_ronda <> 90) THEN
      RAISE EXCEPTION 'ronda inválida en INSERT: %', v_ronda;
    END IF;
    IF v_cruce IS NULL OR v_cruce < 0 THEN
      RAISE EXCEPTION 'cruce_index inválido en INSERT: %', v_cruce;
    END IF;

    v_estado := COALESCE(v_insert->>'estado', 'pendiente');
    IF NOT (v_estado IN ('pendiente', 'jugado')) THEN
      RAISE EXCEPTION 'estado inválido en INSERT: %', v_estado;
    END IF;

    v_pareja_local := NULLIF(v_insert->>'pareja_local_id', '')::uuid;
    v_pareja_visitante := NULLIF(v_insert->>'pareja_visitante_id', '')::uuid;

    -- (9) parejas referenciadas deben pertenecer al torneo
    IF v_pareja_local IS NOT NULL AND NOT (v_pareja_local = ANY(coalesce(v_valid_parejas, ARRAY[]::uuid[]))) THEN
      RAISE EXCEPTION 'pareja_local_id de INSERT no pertenece a este torneo';
    END IF;
    IF v_pareja_visitante IS NOT NULL AND NOT (v_pareja_visitante = ANY(coalesce(v_valid_parejas, ARRAY[]::uuid[]))) THEN
      RAISE EXCEPTION 'pareja_visitante_id de INSERT no pertenece a este torneo';
    END IF;

    -- (11) no duplicar (ronda, cruce_index) — ya bajo el lock de (12), esto
    -- es lo que hace que "dos intentos de generar la misma siguiente ronda"
    -- nunca produzca dos filas: se salta en silencio, no es un error.
    IF EXISTS (
      SELECT 1 FROM public.torneo_express_eliminatoria_partidos
      WHERE torneo_id = p_torneo_id AND ronda = v_ronda AND cruce_index = v_cruce
    ) THEN
      v_skipped_duplicate_inserts := v_skipped_duplicate_inserts + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.torneo_express_eliminatoria_partidos (
      torneo_id, ronda, orden, cruce_index, pareja_local_id, pareja_visitante_id,
      puntos_local, puntos_visitante, ganador_id, estado, es_bye, sets_resultado
    ) VALUES (
      p_torneo_id, -- (7/10) torneo_id SIEMPRE del parámetro, nunca del payload
      v_ronda,
      COALESCE((v_insert->>'orden')::int, 1),
      v_cruce,
      v_pareja_local,
      v_pareja_visitante,
      NULLIF(v_insert->>'puntos_local', '')::int,
      NULLIF(v_insert->>'puntos_visitante', '')::int,
      NULLIF(v_insert->>'ganador_id', '')::uuid,
      v_estado,
      COALESCE((v_insert->>'es_bye')::boolean, false),
      CASE WHEN v_insert ? 'sets_resultado' THEN (v_insert->'sets_resultado') ELSE NULL END
    )
    RETURNING id INTO v_new_id;

    v_inserted_ids := array_append(v_inserted_ids, v_new_id);
    v_applied_inserts := v_applied_inserts + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'updated_count', v_applied_updates,
    'inserted_count', v_applied_inserts,
    'inserted_ids', to_jsonb(v_inserted_ids),
    'skipped_duplicate_inserts', v_skipped_duplicate_inserts
  );
END;
$$;


ALTER FUNCTION "public"."apply_torneo_express_eliminatoria_writes"("p_torneo_id" "uuid", "p_updates" "jsonb", "p_inserts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_torneo_express_grupo_resultado"("p_partido_id" "uuid", "p_puntos_local" integer, "p_puntos_visitante" integer, "p_ganador_side" "text", "p_sets_resultado" "jsonb", "p_force" boolean DEFAULT false, "p_expected_pairs" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_partido record;
  v_torneo record;
  v_grupo_torneo uuid;
  v_ganador_id uuid;
  v_tiene_sets boolean;
  v_side text;
  v_lock_torneo uuid;
  v_after_local_p1 uuid;
  v_after_local_p2 uuid;
  v_after_local_virtual boolean;
  v_after_visit_p1 uuid;
  v_after_visit_p2 uuid;
  v_after_visit_virtual boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  v_side := NULLIF(trim(lower(coalesce(p_ganador_side, ''))), '');
  IF v_side IS NOT NULL AND v_side NOT IN ('local', 'visitante', 'empate') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
  END IF;
  IF v_side = 'empate' THEN
    v_side := NULL;
  END IF;

  IF p_puntos_local IS NULL OR p_puntos_visitante IS NULL
     OR p_puntos_local < 0 OR p_puntos_visitante < 0
     OR p_puntos_local > 99 OR p_puntos_visitante > 99 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
  END IF;

  v_tiene_sets := p_sets_resultado IS NOT NULL
    AND jsonb_typeof(p_sets_resultado) = 'array'
    AND jsonb_array_length(p_sets_resultado) > 0;

  IF v_tiene_sets THEN
    IF NOT public._are_legal_padel_sets(p_sets_resultado) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
    END IF;
  ELSIF NOT public._is_legal_padel_set(p_puntos_local, p_puntos_visitante) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
  END IF;

  SELECT g.torneo_id INTO v_lock_torneo
  FROM public.torneo_express_partidos p
  JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
  WHERE p.id = p_partido_id;

  IF v_lock_torneo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  -- lock-order: torneo
  SELECT id, organizador_id, fase_torneo, estado
    INTO v_torneo
  FROM public.torneo_express
  WHERE id = v_lock_torneo
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_torneo.organizador_id IS NULL OR v_torneo.organizador_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  IF v_torneo.fase_torneo = 'cerrado' OR v_torneo.estado = 'finalizado' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'torneo_cerrado');
  END IF;

  -- lock-order: partido
  SELECT id, grupo_id, pareja_local_id, pareja_visitante_id, estado,
         puntos_local, puntos_visitante, ganador_id, sets_resultado
    INTO v_partido
  FROM public.torneo_express_partidos
  WHERE id = p_partido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT g.torneo_id INTO v_grupo_torneo
  FROM public.torneo_express_grupos g
  WHERE g.id = v_partido.grupo_id;

  IF v_grupo_torneo IS DISTINCT FROM v_torneo.id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  -- lock-order: pairs, siempre por id para no invertir el orden entre parejas.
  PERFORM 1
  FROM public.pairs
  WHERE id IN (v_partido.pareja_local_id, v_partido.pareja_visitante_id)
  ORDER BY id
  FOR UPDATE;

  SELECT player1_id, player2_id, is_virtual
    INTO v_after_local_p1, v_after_local_p2, v_after_local_virtual
  FROM public.te_pair_player_ids(v_partido.pareja_local_id);
  SELECT player1_id, player2_id, is_virtual
    INTO v_after_visit_p1, v_after_visit_p2, v_after_visit_virtual
  FROM public.te_pair_player_ids(v_partido.pareja_visitante_id);

  -- p_force no interviene: un formulario viejo no se sobrescribe.
  -- NULL en un jugador no rechaza solo: virtual es null/null e is_virtual true.
  -- virtual → real (o cualquier mezcla) es PAIR_COMPOSITION_CHANGED.
  IF p_expected_pairs IS NULL
     OR jsonb_typeof(p_expected_pairs) <> 'object'
     OR jsonb_typeof(p_expected_pairs -> 'local') <> 'object'
     OR jsonb_typeof(p_expected_pairs -> 'visitante') <> 'object'
     OR NOT public.te_side_composition_matches(
       p_expected_pairs -> 'local',
       v_partido.pareja_local_id,
       v_after_local_p1,
       v_after_local_p2,
       v_after_local_virtual
     )
     OR NOT public.te_side_composition_matches(
       p_expected_pairs -> 'visitante',
       v_partido.pareja_visitante_id,
       v_after_visit_p1,
       v_after_visit_p2,
       v_after_visit_virtual
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_COMPOSITION_CHANGED');
  END IF;

  IF v_side IS NULL THEN
    v_ganador_id := NULL;
  ELSIF v_side = 'local' THEN
    v_ganador_id := v_partido.pareja_local_id;
  ELSE
    v_ganador_id := v_partido.pareja_visitante_id;
  END IF;

  IF v_side IS NOT NULL AND v_ganador_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
  END IF;

  IF v_partido.estado = 'jugado'
     AND v_partido.puntos_local = p_puntos_local
     AND v_partido.puntos_visitante = p_puntos_visitante
     AND v_partido.ganador_id IS NOT DISTINCT FROM v_ganador_id
     AND v_partido.sets_resultado IS NOT DISTINCT FROM p_sets_resultado
  THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'unchanged',
      'partido_id', p_partido_id,
      'grupo_id', v_partido.grupo_id,
      'torneo_id', v_torneo.id
    );
  END IF;

  IF v_partido.estado = 'jugado' AND NOT p_force THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'conflict',
      'puntos_local', v_partido.puntos_local,
      'puntos_visitante', v_partido.puntos_visitante,
      'sets_resultado', v_partido.sets_resultado
    );
  END IF;

  UPDATE public.torneo_express_partidos
  SET puntos_local = p_puntos_local,
      puntos_visitante = p_puntos_visitante,
      ganador_id = v_ganador_id,
      estado = 'jugado',
      sets_resultado = p_sets_resultado
  WHERE id = p_partido_id;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'updated',
    'partido_id', p_partido_id,
    'grupo_id', v_partido.grupo_id,
    'torneo_id', v_torneo.id
  );
END;
$$;


ALTER FUNCTION "public"."apply_torneo_express_grupo_resultado"("p_partido_id" "uuid", "p_puntos_local" integer, "p_puntos_visitante" integer, "p_ganador_side" "text", "p_sets_resultado" "jsonb", "p_force" boolean, "p_expected_pairs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_coach_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_membership record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes permisos para administrar este club.');
  END IF;

  SELECT id, status INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se encontró la membresía del entrenador.');
  END IF;

  IF v_membership.status = 'ACTIVE' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Primero debes desvincular al entrenador antes de archivarlo.');
  END IF;

  UPDATE public.coach_club_memberships
  SET
    status = 'ARCHIVED',
    archived_at = now(),
    last_edited_by = v_caller,
    last_edited_at = now(),
    updated_at = now()
  WHERE id = v_membership.id;

  INSERT INTO public.coach_club_membership_audit_log (
    membership_id, coach_id, organizador_id, action, performed_by,
    previous_status, new_status, details
  ) VALUES (
    v_membership.id, p_coach_id, p_organizador_id, 'ARCHIVE_COACH', v_caller,
    v_membership.status, 'ARCHIVED', jsonb_build_object('archived_at', now())
  );

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'ARCHIVED',
    'message', 'Entrenador archivado. Oculto de la lista principal.'
  );
END;
$$;


ALTER FUNCTION "public"."archive_coach_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_coach_classes"("p_relationship_id" "uuid", "p_class_count" integer, "p_notas" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_rel record;
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_new_balance integer;
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_trimmed_notas text := NULLIF(btrim(COALESCE(p_notas, '')), '');
  v_existing_op record;
  v_ledger_id uuid;
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  IF p_class_count <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La cantidad de clases debe ser mayor a 0');
  END IF;

  -- Bloquear y validar relación
  SELECT * INTO v_rel
  FROM public.coach_player_relationships
  WHERE id = p_relationship_id
  FOR UPDATE;

  IF v_rel.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Relación coach-alumno no encontrada');
  END IF;

  IF v_caller <> v_rel.organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo el club puede asignar clases');
  END IF;

  -- GUARDA CRÍTICA DE BACKEND: La relación debe estar estrictamente ACTIVE
  IF v_rel.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No se pueden asignar clases a una relación en pausa o terminada. El estado actual es: ' || COALESCE(v_rel.status, 'DESCONOCIDO') || '.'
    );
  END IF;

  -- Comprobar que el coach mantiene membresía activa en este club
  IF NOT EXISTS (
    SELECT 1 FROM public.coach_club_memberships
    WHERE organizador_id = v_rel.organizador_id
      AND coach_id = v_rel.coach_id
      AND status = 'ACTIVE'
  ) AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El coach ya no tiene una membresía activa en este club.');
  END IF;

  -- Comprobar que el club tiene coaching habilitado
  IF NOT EXISTS (
    SELECT 1 FROM public.organizador_game_modes
    WHERE organizador_id = v_rel.organizador_id AND coaching_enabled = true
  ) AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El club no tiene habilitado el módulo Riviera Coaching.');
  END IF;

  -- Idempotencia estricta
  IF v_trimmed_key IS NOT NULL THEN
    SELECT id, relationship_id, delta INTO v_existing_op
    FROM public.coach_class_ledger
    WHERE idempotency_key = v_trimmed_key
    LIMIT 1;

    IF v_existing_op.id IS NOT NULL THEN
      SELECT balance_classes INTO v_new_balance
      FROM public.coach_player_class_balances
      WHERE relationship_id = p_relationship_id;

      RETURN jsonb_build_object(
        'ok', true,
        'relationship_id', p_relationship_id,
        'balance_classes', v_new_balance,
        'delta', v_existing_op.delta,
        'idempotent', true,
        'message', 'Operación completada previamente (idempotente)'
      );
    END IF;
  END IF;

  -- Upsert de balance
  INSERT INTO public.coach_player_class_balances (
    relationship_id,
    organizador_id,
    coach_id,
    jugador_id,
    balance_classes,
    total_classes_given,
    updated_at
  ) VALUES (
    v_rel.id,
    v_rel.organizador_id,
    v_rel.coach_id,
    v_rel.jugador_id,
    p_class_count,
    0,
    v_now
  ) ON CONFLICT (relationship_id) DO UPDATE
  SET balance_classes = public.coach_player_class_balances.balance_classes + p_class_count,
      updated_at = v_now
  RETURNING balance_classes INTO v_new_balance;

  -- Registrar en ledger inmutable
  INSERT INTO public.coach_class_ledger (
    relationship_id,
    organizador_id,
    coach_id,
    jugador_id,
    delta,
    tipo,
    notas,
    idempotency_key,
    recorded_by,
    created_at
  ) VALUES (
    v_rel.id,
    v_rel.organizador_id,
    v_rel.coach_id,
    v_rel.jugador_id,
    p_class_count,
    'PACKAGE_CREDIT',
    v_trimmed_notas,
    v_trimmed_key,
    v_caller,
    v_now
  ) RETURNING id INTO v_ledger_id;

  -- Auditoría
  INSERT INTO public.coach_audit_log (
    actor_auth_user_id,
    action,
    entity_type,
    entity_id,
    payload,
    created_at
  ) VALUES (
    v_caller,
    'CLASSES_ASSIGNED',
    'coach_player_relationships',
    v_rel.id,
    jsonb_build_object(
      'delta', p_class_count,
      'new_balance', v_new_balance,
      'ledger_id', v_ledger_id,
      'idempotency_key', v_trimmed_key,
      'organizador_id', v_rel.organizador_id,
      'coach_id', v_rel.coach_id,
      'jugador_id', v_rel.jugador_id
    ),
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'relationship_id', v_rel.id,
    'balance_classes', v_new_balance,
    'delta', p_class_count,
    'ledger_id', v_ledger_id,
    'message', 'Se asignaron +' || p_class_count || ' clases exitosamente.'
  );
END;
$$;


ALTER FUNCTION "public"."assign_coach_classes"("p_relationship_id" "uuid", "p_class_count" integer, "p_notas" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_student_to_club_coach"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_riviera_id" "text", "p_initial_classes" integer DEFAULT 0, "p_idempotency_key" "text" DEFAULT NULL::"text", "p_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_membership record;
  v_norm_riviera_id text;
  v_jugador record;
  v_relationship_id uuid;
  v_initial_classes integer := COALESCE(p_initial_classes, 0);
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_existing_ledger record;
  v_new_balance integer := 0;
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  -- PROTECCIÓN: Cuentas STUDENT_ONLY no pueden administrar asignaciones
  PERFORM public.check_student_only_restriction();

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autorizado: solo el club propietario puede asignar alumnos a sus entrenadores');
  END IF;

  SELECT * INTO v_membership
  FROM public.coach_club_memberships
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_coach_id;

  IF v_membership.coach_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El entrenador no pertenece a este club');
  END IF;

  IF v_membership.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se pueden asignar alumnos a un entrenador con estatus ' || v_membership.status);
  END IF;

  v_norm_riviera_id := upper(btrim(COALESCE(p_riviera_id, '')));
  IF v_norm_riviera_id = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El Riviera ID del alumno es obligatorio');
  END IF;

  SELECT rj.id, rj.nombre, idn.riviera_id INTO v_jugador
  FROM public.riviera_official_player_identity idn
  JOIN public.riviera_jugadores rj ON rj.id = idn.canonical_riviera_jugador_id
  WHERE idn.riviera_id = v_norm_riviera_id
  LIMIT 1;

  IF v_jugador.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se encontró ningún alumno con el Riviera ID ' || v_norm_riviera_id);
  END IF;

  IF v_initial_classes < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La cantidad inicial de clases no puede ser negativa');
  END IF;

  IF v_trimmed_key IS NOT NULL THEN
    SELECT l.*, b.balance_classes AS current_balance INTO v_existing_ledger
    FROM public.coach_class_ledger l
    LEFT JOIN public.coach_player_class_balances b ON b.relationship_id = l.relationship_id
    WHERE l.idempotency_key = v_trimmed_key
    LIMIT 1;

    IF v_existing_ledger.id IS NOT NULL THEN
      IF v_existing_ledger.organizador_id <> p_organizador_id
         OR v_existing_ledger.coach_id <> p_coach_id
         OR v_existing_ledger.jugador_id <> v_jugador.id
         OR v_existing_ledger.delta <> v_initial_classes THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de clave de idempotencia: los parámetros no coinciden con la operación original.',
          'code', 'IDEMPOTENCY_MISMATCH'
        );
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'relationship_id', v_existing_ledger.relationship_id,
        'coach_id', p_coach_id,
        'jugador_id', v_jugador.id,
        'jugador_nombre', v_jugador.nombre,
        'riviera_id', v_norm_riviera_id,
        'balance_classes', COALESCE(v_existing_ledger.current_balance, v_initial_classes),
        'ledger_id', v_existing_ledger.id,
        'idempotent', true,
        'message', 'Operación completada previamente (idempotente)'
      );
    END IF;
  END IF;

  INSERT INTO public.coach_player_relationships (
    organizador_id,
    coach_id,
    jugador_id,
    status,
    is_primary,
    created_at,
    updated_at
  ) VALUES (
    p_organizador_id,
    p_coach_id,
    v_jugador.id,
    'ACTIVE',
    true,
    v_now,
    v_now
  )
  ON CONFLICT (organizador_id, coach_id, jugador_id)
  DO UPDATE SET
    status = 'ACTIVE',
    ended_at = NULL,
    updated_at = v_now
  RETURNING id INTO v_relationship_id;

  INSERT INTO public.coach_player_class_balances (
    relationship_id,
    organizador_id,
    coach_id,
    jugador_id,
    balance_classes,
    total_classes_given,
    updated_at
  ) VALUES (
    v_relationship_id,
    p_organizador_id,
    p_coach_id,
    v_jugador.id,
    v_initial_classes,
    0,
    v_now
  )
  ON CONFLICT (relationship_id)
  DO UPDATE SET
    balance_classes = public.coach_player_class_balances.balance_classes + v_initial_classes,
    updated_at = v_now
  RETURNING balance_classes INTO v_new_balance;

  IF v_initial_classes > 0 THEN
    INSERT INTO public.coach_class_ledger (
      relationship_id,
      organizador_id,
      coach_id,
      jugador_id,
      delta,
      tipo,
      notas,
      idempotency_key,
      recorded_by,
      created_at
    ) VALUES (
      v_relationship_id,
      p_organizador_id,
      p_coach_id,
      v_jugador.id,
      v_initial_classes,
      'PACKAGE_CREDIT',
      COALESCE(p_reference, 'Asignación inicial de ' || v_initial_classes || ' clases contratadas'),
      v_trimmed_key,
      v_caller,
      v_now
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'relationship_id', v_relationship_id,
    'coach_id', p_coach_id,
    'jugador_id', v_jugador.id,
    'jugador_nombre', v_jugador.nombre,
    'riviera_id', v_norm_riviera_id,
    'balance_classes', v_new_balance,
    'idempotent', false,
    'message', 'Alumno asignado exitosamente con ' || v_initial_classes || ' clases'
  );
END;
$$;


ALTER FUNCTION "public"."assign_student_to_club_coach"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_riviera_id" "text", "p_initial_classes" integer, "p_idempotency_key" "text", "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auth_uid"() RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$ SELECT auth.uid() $$;


ALTER FUNCTION "public"."auth_uid"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_dynamic_team_block"("p_tournament_id" "uuid", "p_block_number" integer, "p_round_start" integer, "p_round_end" integer, "p_stage" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tournament record;
  v_new_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT id, user_id, coalesce(is_finished, false) AS is_finished
  INTO v_tournament
  FROM public.tournaments
  WHERE id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_tournament.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre esta reta';
  END IF;

  IF v_tournament.is_finished THEN
    RETURN jsonb_build_object('ok', false, 'error', 'tournament_finished');
  END IF;

  IF p_block_number > 1 AND NOT EXISTS (
    SELECT 1 FROM public.reta_dynamic_blocks
    WHERE tournament_id = p_tournament_id
      AND block_number = p_block_number - 1
      AND status = 'completed'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'previous_block_not_completed');
  END IF;

  INSERT INTO public.reta_dynamic_blocks (
    tournament_id, block_number, round_start, round_end, stage
  ) VALUES (
    p_tournament_id, p_block_number, p_round_start, p_round_end, p_stage
  )
  ON CONFLICT (tournament_id, block_number) DO NOTHING
  RETURNING id INTO v_new_id;

  IF v_new_id IS NULL THEN
    -- Ya reclamado (en curso o completado) por otro clic/pestaña/poll --
    -- no-op idempotente, el cliente debe releer el estado actual.
    RETURN jsonb_build_object('ok', false, 'error', 'already_claimed');
  END IF;

  RETURN jsonb_build_object('ok', true, 'block_id', v_new_id);
END;
$$;


ALTER FUNCTION "public"."begin_dynamic_team_block"("p_tournament_id" "uuid", "p_block_number" integer, "p_round_start" integer, "p_round_end" integer, "p_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cambiar_torneo_express_jugador_grupo"("p_grupo_id" "uuid", "p_pareja_id" "uuid", "p_jugador_saliente_id" "uuid", "p_jugador_nuevo_id" "uuid", "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_torneo_id uuid;
  v_guard jsonb;
  v_version_guard jsonb;
  v_player1 uuid;
  v_player2 uuid;
  v_is_virtual boolean;
  v_tournament uuid;
  v_name text;
  v_slot text;
  v_partner uuid;
  v_has_history boolean;
  v_shared boolean;
  v_new_pair uuid;
  v_version integer;
BEGIN
  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  SELECT torneo_id INTO v_torneo_id
  FROM public.torneo_express_grupos
  WHERE id = p_grupo_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  v_guard := public.te_lock_categoria_editable(v_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    IF (v_guard ->> 'error') IN ('TOURNAMENT_NOT_EDITABLE', 'ELIMINATORIA_EXISTS') THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'GROUP_NOT_EDITABLE', 'reason', v_guard ->> 'error'
      );
    END IF;
    RETURN v_guard;
  END IF;

  -- lock-order: grupo
  PERFORM 1 FROM public.torneo_express_grupos WHERE id = p_grupo_id FOR UPDATE;
  v_version_guard := public.te_grupo_version_ok(p_grupo_id, p_expected_version);
  IF NOT (v_version_guard ->> 'ok')::boolean THEN
    RETURN v_version_guard;
  END IF;

  -- lock-order: grupo_parejas
  PERFORM 1
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = p_grupo_id
  ORDER BY pareja_id
  FOR UPDATE;

  IF NOT EXISTS (
    SELECT 1 FROM public.torneo_express_grupo_parejas
    WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_IN_GROUP');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.torneo_express_grupo_parejas
    WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id AND NOT activa
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_ALREADY_WITHDRAWN');
  END IF;

  -- lock-order: partidos
  PERFORM 1
  FROM public.torneo_express_partidos
  WHERE grupo_id = p_grupo_id
    AND (pareja_local_id = p_pareja_id OR pareja_visitante_id = p_pareja_id)
  ORDER BY id
  FOR UPDATE;

  -- lock-order: pairs
  SELECT player1_id, player2_id, is_virtual, tournament_id
    INTO v_player1, v_player2, v_is_virtual, v_tournament
  FROM public.pairs
  WHERE id = p_pareja_id
  ORDER BY id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_PAIR');
  END IF;
  IF v_is_virtual THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_IS_VIRTUAL');
  END IF;
  IF p_jugador_saliente_id IS NULL OR p_jugador_nuevo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_PAIR');
  END IF;

  IF v_player1 = p_jugador_saliente_id THEN
    v_slot := 'player1';
    v_partner := v_player2;
  ELSIF v_player2 = p_jugador_saliente_id THEN
    v_slot := 'player2';
    v_partner := v_player1;
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'OUTGOING_NOT_IN_PAIR');
  END IF;

  IF p_jugador_nuevo_id = v_partner OR p_jugador_nuevo_id = p_jugador_saliente_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_ALREADY_IN_PAIR');
  END IF;

  SELECT btrim(name) INTO v_name FROM public.players WHERE id = p_jugador_nuevo_id;
  IF v_name IS NULL OR v_name = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_NOT_FOUND');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    JOIN public.pairs pr ON pr.id = gp.pareja_id
    WHERE g.torneo_id = v_torneo_id
      AND gp.pareja_id <> p_pareja_id
      AND (pr.player1_id = p_jugador_nuevo_id OR pr.player2_id = p_jugador_nuevo_id)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_ALREADY_REGISTERED');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    WHERE p.grupo_id = p_grupo_id
      AND (p.pareja_local_id = p_pareja_id OR p.pareja_visitante_id = p_pareja_id)
      AND public.te_partido_tiene_historial(
        p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
      )
  ) INTO v_has_history;

  v_shared := public.te_pareja_referenciada_fuera(p_pareja_id, p_grupo_id);

  IF NOT v_has_history AND NOT v_shared THEN
    IF v_slot = 'player1' THEN
      UPDATE public.pairs
      SET player1_id = p_jugador_nuevo_id, player1_name = v_name
      WHERE id = p_pareja_id;
    ELSE
      UPDATE public.pairs
      SET player2_id = p_jugador_nuevo_id, player2_name = v_name
      WHERE id = p_pareja_id;
    END IF;
    v_version := public.te_grupo_bump_version(p_grupo_id);
    RETURN jsonb_build_object(
      'ok', true,
      'mode', 'in_place',
      'pareja_id', p_pareja_id,
      'version', v_version
    );
  END IF;

  INSERT INTO public.pairs (
    id, tournament_id, player1_id, player2_id, player1_name, player2_name, is_virtual, virtual_label
  )
  SELECT
    gen_random_uuid(),
    v_tournament,
    CASE WHEN v_slot = 'player1' THEN p_jugador_nuevo_id ELSE v_player1 END,
    CASE WHEN v_slot = 'player2' THEN p_jugador_nuevo_id ELSE v_player2 END,
    CASE WHEN v_slot = 'player1' THEN v_name ELSE player1_name END,
    CASE WHEN v_slot = 'player2' THEN v_name ELSE player2_name END,
    false,
    NULL
  FROM public.pairs
  WHERE id = p_pareja_id
  RETURNING id INTO v_new_pair;

  UPDATE public.torneo_express_grupo_parejas
  SET pareja_previa_ids = pareja_previa_ids || ARRAY[p_pareja_id],
      pareja_id = v_new_pair
  WHERE grupo_id = p_grupo_id
    AND pareja_id = p_pareja_id;

  UPDATE public.torneo_express_partidos
  SET pareja_local_id = CASE WHEN pareja_local_id = p_pareja_id THEN v_new_pair ELSE pareja_local_id END,
      pareja_visitante_id = CASE WHEN pareja_visitante_id = p_pareja_id THEN v_new_pair ELSE pareja_visitante_id END
  WHERE grupo_id = p_grupo_id
    AND (pareja_local_id = p_pareja_id OR pareja_visitante_id = p_pareja_id)
    AND NOT public.te_partido_tiene_historial(
      estado, ganador_id, puntos_local, puntos_visitante, sets_resultado
    );

  v_version := public.te_grupo_bump_version(p_grupo_id);
  RETURN jsonb_build_object(
    'ok', true,
    'mode', 'desde_ahora',
    'pareja_id', v_new_pair,
    'pareja_anterior_id', p_pareja_id,
    'version', v_version
  );
END;
$$;


ALTER FUNCTION "public"."cambiar_torneo_express_jugador_grupo"("p_grupo_id" "uuid", "p_pareja_id" "uuid", "p_jugador_saliente_id" "uuid", "p_jugador_nuevo_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


