CREATE OR REPLACE FUNCTION "public"."cancel_coach_class"("p_organizador_id" "uuid", "p_session_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_sess record;
  v_trimmed_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo el club puede cancelar clases.');
  END IF;

  IF v_trimmed_reason IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El motivo de cancelación es obligatorio.');
  END IF;

  SELECT *
  INTO v_sess
  FROM public.coach_sessions
  WHERE id = p_session_id AND organizador_id = p_organizador_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sesión no encontrada o no pertenece a este club.');
  END IF;

  IF v_sess.status <> 'SCHEDULED' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo se pueden cancelar clases en estado programada (SCHEDULED). Estado actual: ' || v_sess.status || '.');
  END IF;

  UPDATE public.coach_sessions
  SET status = 'CANCELLED',
      cancellation_reason = v_trimmed_reason,
      updated_at = v_now
  WHERE id = p_session_id;

  INSERT INTO public.coach_audit_log (
    actor_auth_user_id,
    action,
    entity_type,
    entity_id,
    payload,
    created_at
  )
  VALUES (
    v_caller,
    'CLASS_CANCELLED',
    'coach_sessions',
    p_session_id,
    jsonb_build_object(
      'coach_id', v_sess.coach_id,
      'student_id', v_sess.jugador_id,
      'starts_at', v_sess.starts_at,
      'court', v_sess.court,
      'reason', v_trimmed_reason
    ),
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id,
    'status', 'CANCELLED',
    'message', 'Clase cancelada exitosamente. El cupo de reserva ha sido liberado.'
  );
END;
$$;


ALTER FUNCTION "public"."cancel_coach_class"("p_organizador_id" "uuid", "p_session_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_coach_club_invitation"("p_organizador_id" "uuid", "p_coach_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_membership record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes permisos para administrar este club.');
  END IF;

  SELECT id, status INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se encontró la invitación para este entrenador en tu club.');
  END IF;

  IF v_membership.status <> 'PENDING' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo las invitaciones en estado PENDING pueden ser canceladas.');
  END IF;

  UPDATE public.coach_club_memberships
  SET
    status = 'CANCELLED',
    cancelled_at = now(),
    last_edited_by = v_caller,
    last_edited_at = now(),
    updated_at = now()
  WHERE id = v_membership.id;

  INSERT INTO public.coach_club_membership_audit_log (
    membership_id, coach_id, organizador_id, action, performed_by,
    previous_status, new_status, details
  ) VALUES (
    v_membership.id, p_coach_id, p_organizador_id, 'CANCEL_INVITATION', v_caller,
    'PENDING', 'CANCELLED', jsonb_build_object('cancelled_at', now())
  );

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'CANCELLED',
    'message', 'Invitación cancelada correctamente. El coach no podrá activarse con esta invitación.'
  );
END;
$$;


ALTER FUNCTION "public"."cancel_coach_club_invitation"("p_organizador_id" "uuid", "p_coach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_tournament_open_registration"("p_slug" "text", "p_cancellation_token" "text" DEFAULT NULL::"text", "p_riviera_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_cfg public.tournament_open_registration;
  v_hash text;
  v_entry public.tournament_open_registration_entries%ROWTYPE;
  v_norm text;
  v_token text := nullif(trim(coalesce(p_cancellation_token, '')), '');
  v_promoted int := 0;
BEGIN
  SELECT * INTO v_cfg
  FROM public.tournament_open_registration
  WHERE public_slug = trim(coalesce(p_slug, ''))
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_token IS NOT NULL AND length(v_token) >= 16 THEN
    v_hash := encode(extensions.digest(v_token, 'sha256'), 'hex');

    SELECT * INTO v_entry
    FROM public.tournament_open_registration_entries e
    WHERE e.registration_id = v_cfg.id
      AND e.cancellation_token_hash = v_hash
      AND e.status IN ('confirmed', 'waitlist', 'pending_approval')
    FOR UPDATE;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
    END IF;
  ELSE
    v_norm := public._normalize_riviera_id_loose(p_riviera_id);
    IF v_norm IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_riviera_id');
    END IF;

    SELECT * INTO v_entry
    FROM public.tournament_open_registration_entries e
    WHERE e.registration_id = v_cfg.id
      AND upper(trim(e.riviera_id)) = v_norm
      AND e.status IN ('confirmed', 'waitlist', 'pending_approval')
    FOR UPDATE;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_registered');
    END IF;
  END IF;

  UPDATE public.tournament_open_registration_entries
  SET
    status = 'cancelled',
    cancelled_at = now(),
    updated_at = now(),
    cancellation_token_hash = NULL
  WHERE id = v_entry.id;

  IF v_entry.status = 'confirmed' THEN
    -- Promover automáticamente al primer jugador en reserva/waitlist
    v_promoted := public._open_reg_auto_promote_waitlist(v_cfg.id);

    -- Sincronizar rosters/slots siempre que salió un confirmado
    IF v_cfg.mode_type = 'americano' THEN
      PERFORM public._open_reg_sync_americano_roster(v_cfg.entity_id);
    ELSIF v_cfg.mode_type = 'duelo_2v2' THEN
      PERFORM public._open_reg_sync_duelo_slots(v_cfg.entity_id);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'entry_id', v_entry.id,
    'previous_status', v_entry.status,
    'promoted_count', v_promoted,
    'message', 'Inscripción cancelada.'
  );
END;
$$;


ALTER FUNCTION "public"."cancel_tournament_open_registration"("p_slug" "text", "p_cancellation_token" "text", "p_riviera_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_bucket_key" "text", "p_max_requests" integer, "p_window_seconds" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_window_start timestamptz;
  v_count integer;
  v_reset_at timestamptz;
BEGIN
  IF p_bucket_key IS NULL OR length(trim(p_bucket_key)) = 0 THEN
    RAISE EXCEPTION 'bucket_key requerido';
  END IF;
  IF p_max_requests IS NULL OR p_max_requests <= 0 THEN
    RAISE EXCEPTION 'max_requests debe ser positivo';
  END IF;
  IF p_window_seconds IS NULL OR p_window_seconds <= 0 THEN
    RAISE EXCEPTION 'window_seconds debe ser positivo';
  END IF;

  INSERT INTO public._edge_rate_limits (bucket_key, window_start, count, updated_at)
  VALUES (p_bucket_key, v_now, 1, v_now)
  ON CONFLICT (bucket_key) DO UPDATE SET
    window_start = CASE
      WHEN public._edge_rate_limits.window_start <= v_now - make_interval(secs => p_window_seconds)
        THEN v_now
      ELSE public._edge_rate_limits.window_start
    END,
    count = CASE
      WHEN public._edge_rate_limits.window_start <= v_now - make_interval(secs => p_window_seconds)
        THEN 1
      ELSE public._edge_rate_limits.count + 1
    END,
    updated_at = v_now
  RETURNING window_start, count INTO v_window_start, v_count;

  v_reset_at := v_window_start + make_interval(secs => p_window_seconds);

  -- Limpieza probabilística (1%) de buckets viejos, sin depender de pg_cron.
  IF random() < 0.01 THEN
    DELETE FROM public._edge_rate_limits
    WHERE updated_at < v_now - interval '1 day'
      AND bucket_key IN (
        SELECT bucket_key FROM public._edge_rate_limits
        WHERE updated_at < v_now - interval '1 day'
        LIMIT 500
      );
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_count <= p_max_requests,
    'count', v_count,
    'limit', p_max_requests,
    'remaining', GREATEST(0, p_max_requests - v_count),
    'reset_at', v_reset_at,
    'retry_after_seconds', GREATEST(0, CEIL(EXTRACT(EPOCH FROM (v_reset_at - v_now)))::integer)
  );
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_bucket_key" "text", "p_max_requests" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_student_invitation_account"("p_email" "text", "p_target_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_clean_email text := lower(btrim(COALESCE(p_email, '')));
  v_user record;
  v_is_admin boolean := false;
  v_is_coach boolean := false;
  v_linked_link record;
  v_account_type text;
BEGIN
  IF v_clean_email = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Correo electrónico requerido');
  END IF;

  -- 1. Búsqueda exhaustiva por índice en auth.users
  SELECT u.id, u.email, u.email_confirmed_at, u.raw_app_meta_data, u.raw_user_meta_data
  INTO v_user
  FROM auth.users u
  WHERE lower(btrim(u.email)) = v_clean_email
  LIMIT 1;

  IF v_user.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'exists', false,
      'can_invite', true,
      'can_invite_as_new', true
    );
  END IF;

  -- 2. Comprobar si la cuenta es administrativa de club o master admin
  IF EXISTS (
    SELECT 1 FROM public.admin_users WHERE user_id = v_user.id
  ) OR EXISTS (
    SELECT 1 FROM public.organizador_game_modes WHERE organizador_id = v_user.id
  ) OR COALESCE(v_user.raw_app_meta_data->>'account_type', '') = 'CLUB_ADMIN'
    OR COALESCE(v_user.raw_user_meta_data->>'account_type', '') = 'CLUB_ADMIN' THEN
    v_is_admin := true;
  END IF;

  -- 3. Comprobar si la cuenta es de entrenador
  IF EXISTS (
    SELECT 1 FROM public.riviera_coaches WHERE auth_user_id = v_user.id
  ) OR COALESCE(v_user.raw_app_meta_data->>'account_type', '') = 'COACH_ONLY'
    OR COALESCE(v_user.raw_user_meta_data->>'account_type', '') = 'COACH_ONLY' THEN
    v_is_coach := true;
  END IF;

  -- Si es cuenta administrativa o de entrenador, rechazar terminantemente
  IF v_is_admin OR v_is_coach THEN
    RETURN jsonb_build_object(
      'ok', true,
      'exists', true,
      'is_privileged', true,
      'is_admin', v_is_admin,
      'is_coach', v_is_coach,
      'can_invite', false,
      'error', 'El correo ' || v_clean_email || ' pertenece a una cuenta administrativa o de entrenador. No puede utilizarse para un acceso exclusivo de alumno. Solicita al alumno un correo particular alternativo.'
    );
  END IF;

  -- 4. Comprobar si la cuenta ya está vinculada a otro alumno con Riviera ID distinto
  SELECT al.jugador_id, i.riviera_id INTO v_linked_link
  FROM public.coach_student_account_links al
  LEFT JOIN public.riviera_official_player_identity i ON i.canonical_riviera_jugador_id = al.jugador_id
  WHERE al.auth_user_id = v_user.id
  LIMIT 1;

  IF v_linked_link.jugador_id IS NOT NULL AND v_linked_link.jugador_id <> p_target_jugador_id THEN
    RETURN jsonb_build_object(
      'ok', true,
      'exists', true,
      'is_other_student', true,
      'can_invite', false,
      'error', 'El correo ya está vinculado a otro alumno con Riviera ID ' || COALESCE(v_linked_link.riviera_id, 'distinto') || '. Bloqueado por seguridad.'
    );
  END IF;

  -- 5. Cuenta STUDENT_ONLY legítima del mismo alumno
  v_account_type := COALESCE(
    v_user.raw_app_meta_data->>'account_type',
    v_user.raw_user_meta_data->>'account_type',
    'STUDENT_ONLY'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'exists', true,
    'user_id', v_user.id,
    'email_confirmed', (v_user.email_confirmed_at IS NOT NULL),
    'account_type', v_account_type,
    'is_same_student', (v_linked_link.jugador_id = p_target_jugador_id),
    'can_invite', true
  );
END;
$$;


ALTER FUNCTION "public"."check_student_invitation_account"("p_email" "text", "p_target_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_student_invitation_account"("p_email" "text", "p_target_jugador_id" "uuid") IS 'Comprobación autorizada de cuentas para invitaciones de alumno. Restringida exclusivamente a service_role para prevenir exposición de cuentas a usuarios autenticados o anónimos.';



CREATE OR REPLACE FUNCTION "public"."check_student_only_restriction"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF public.is_student_only_account(auth.uid()) THEN
    RAISE EXCEPTION 'Unauthorized: Las cuentas de alumno únicamente tienen acceso de consulta personal y no pueden realizar operaciones administrativas.';
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_student_only_restriction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_student_invitation"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_caller_email text;
  v_email_confirmed_at timestamptz;
  v_clean_token text := btrim(COALESCE(p_token, ''));
  v_hash text;
  v_invitation record;
  v_jugador record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Debes iniciar sesión con tu cuenta para vincular tu perfil.');
  END IF;

  SELECT lower(btrim(email)), email_confirmed_at INTO v_caller_email, v_email_confirmed_at
  FROM auth.users
  WHERE id = v_caller;

  IF v_email_confirmed_at IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Tu correo electrónico debe estar verificado antes de vincular tu perfil.'
    );
  END IF;

  -- Bloquear cuentas administrativas o de entrenador
  IF EXISTS (
    SELECT 1 FROM public.admin_users WHERE user_id = v_caller
  ) OR EXISTS (
    SELECT 1 FROM public.organizador_game_modes WHERE organizador_id = v_caller
  ) OR EXISTS (
    SELECT 1 FROM public.riviera_coaches WHERE auth_user_id = v_caller
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Esta cuenta es administrativa o de entrenador. El acceso de alumno requiere una cuenta exclusiva de alumno.'
    );
  END IF;

  IF v_clean_token = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Token de invitación no proporcionado.');
  END IF;

  v_hash := encode(extensions.digest(v_clean_token::bytea, 'sha256'), 'hex');

  SELECT * INTO v_invitation
  FROM public.coach_student_invitations
  WHERE (token_hash = v_hash OR invitation_token = v_clean_token)
  FOR UPDATE;

  IF v_invitation.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Invitación no encontrada.');
  END IF;

  IF v_invitation.status <> 'PENDING' OR v_invitation.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Esta invitación ya no está activa o ha expirado.');
  END IF;

  -- Comprobar que el usuario autenticado coincide con el correo invitado
  IF lower(btrim(v_invitation.email)) <> v_caller_email THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'La cuenta autenticada (' || v_caller_email || ') no coincide con el correo de la invitación (' || v_invitation.email || ').'
    );
  END IF;

  -- Bloquear si el usuario ya está vinculado a otro alumno con Riviera ID distinto
  IF EXISTS (
    SELECT 1 FROM public.coach_student_account_links
    WHERE auth_user_id = v_caller AND jugador_id <> v_invitation.jugador_id
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Esta cuenta ya está vinculada a otro perfil deportivo de alumno con un Riviera ID diferente.'
    );
  END IF;

  -- Comprobar que el club mantiene relación con el alumno
  IF NOT EXISTS (
    SELECT 1 FROM public.coach_player_relationships
    WHERE organizador_id = v_invitation.organizador_id
      AND jugador_id = v_invitation.jugador_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El club no administra este perfil deportivo.');
  END IF;

  -- Vincular multiclub de forma segura
  INSERT INTO public.coach_student_account_links (
    organizador_id,
    jugador_id,
    auth_user_id,
    verification_method,
    is_active,
    student_email
  ) VALUES (
    v_invitation.organizador_id,
    v_invitation.jugador_id,
    v_caller,
    'STUDENT_AUTH_VERIFIED',
    true,
    v_caller_email
  ) ON CONFLICT (organizador_id, jugador_id) DO UPDATE
  SET auth_user_id = v_caller,
      is_active = true,
      student_email = v_caller_email,
      verification_method = 'STUDENT_AUTH_VERIFIED',
      deactivated_at = NULL,
      deactivated_by = NULL,
      updated_at = now();

  -- Asegurar metadatos STUDENT_ONLY de forma segura en auth.users
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || '{"account_type": "STUDENT_ONLY", "role": "student"}'::jsonb,
      raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) || '{"account_type": "STUDENT_ONLY"}'::jsonb
  WHERE id = v_caller
    AND COALESCE(raw_app_meta_data->>'account_type', '') <> 'STUDENT_ONLY';

  -- Marcar invitación como aceptada
  UPDATE public.coach_student_invitations
  SET status = 'ACCEPTED',
      accepted_at = now(),
      accepted_by = v_caller,
      updated_at = now()
  WHERE id = v_invitation.id;

  SELECT rj.nombre, i.riviera_id INTO v_jugador
  FROM public.riviera_jugadores rj
  LEFT JOIN public.riviera_official_player_identity i ON i.canonical_riviera_jugador_id = rj.id
  WHERE rj.id = v_invitation.jugador_id;

  RETURN jsonb_build_object(
    'ok', true,
    'student_name', v_jugador.nombre,
    'riviera_id', v_jugador.riviera_id,
    'message', '¡Perfil deportivo vinculado exitosamente a tu cuenta de alumno!'
  );
END;
$$;


ALTER FUNCTION "public"."claim_student_invitation"("p_token" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."tournament_open_registration" (
    "tournament_id" "uuid",
    "public_slug" "text" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "capacity" integer DEFAULT 4 NOT NULL,
    "waitlist_enabled" boolean DEFAULT true NOT NULL,
    "approval_required" boolean DEFAULT false NOT NULL,
    "registration_deadline" timestamp with time zone,
    "scheduled_at" timestamp with time zone,
    "duration_minutes" integer,
    "category_label" "text",
    "location_label" "text",
    "display_rating" boolean DEFAULT true NOT NULL,
    "display_photo" boolean DEFAULT true NOT NULL,
    "display_full_name" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "mode_type" "text" DEFAULT 'reta'::"text" NOT NULL,
    "entity_id" "uuid",
    "title_public" "text",
    "rama_label" "text",
    CONSTRAINT "tournament_open_registration_capacity_check" CHECK ((("capacity" > 0) AND ("capacity" <= 64))),
    CONSTRAINT "tournament_open_registration_duration_minutes_check" CHECK ((("duration_minutes" IS NULL) OR ("duration_minutes" > 0))),
    CONSTRAINT "tournament_open_registration_mode_check" CHECK (("mode_type" = ANY (ARRAY['reta'::"text", 'americano'::"text", 'duelo_2v2'::"text"]))),
    CONSTRAINT "tournament_open_registration_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'open'::"text", 'paused'::"text", 'closed'::"text", 'cancelled'::"text"])))
);


