CREATE OR REPLACE FUNCTION "public"."close_open_game_registration"("p_mode_type" "text", "p_entity_id" "uuid") RETURNS "public"."tournament_open_registration"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mode text;
  v_org uuid;
  v_row public.tournament_open_registration;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticación requerida'; END IF;
  v_mode := public._assert_convocatoria_mode_allowed(p_mode_type);
  IF p_entity_id IS NULL THEN RAISE EXCEPTION 'entity_id requerido'; END IF;

  v_org := public._open_reg_organizer_id(v_mode, p_entity_id);
  IF v_org IS NULL OR v_org <> v_uid THEN
    RAISE EXCEPTION 'Evento no encontrado o sin permiso';
  END IF;

  UPDATE public.tournament_open_registration
  SET status = 'closed',
      enabled = true,
      updated_at = now()
  WHERE mode_type = v_mode AND entity_id = p_entity_id
  RETURNING * INTO v_row;

  RETURN v_row; -- NULL si no había convocatoria (ok)
END;
$$;


ALTER FUNCTION "public"."close_open_game_registration"("p_mode_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."coach_audit_write"("p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_coach_id uuid;
BEGIN
  SELECT c.id INTO v_coach_id
  FROM public.riviera_coaches c
  WHERE c.auth_user_id = auth.uid();

  INSERT INTO public.coach_audit_log (
    actor_coach_id, actor_auth_user_id, action, entity_type, entity_id, payload
  ) VALUES (
    v_coach_id,
    auth.uid(),
    p_action,
    p_entity_type,
    p_entity_id,
    coalesce(p_payload, '{}'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."coach_audit_write"("p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."coach_content_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.coach_audit_write(
      'insert',
      TG_TABLE_NAME,
      NEW.id,
      jsonb_build_object(
        'coach_id', NEW.coach_id,
        'relationship_id', NEW.relationship_id,
        'body', NEW.body
      )
    );
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    PERFORM public.coach_audit_write(
      'update',
      TG_TABLE_NAME,
      NEW.id,
      jsonb_build_object(
        'coach_id', NEW.coach_id,
        'relationship_id', NEW.relationship_id,
        'old_body', OLD.body,
        'new_body', NEW.body,
        'deleted_at', NEW.deleted_at
      )
    );
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.coach_audit_write(
      'delete',
      TG_TABLE_NAME,
      OLD.id,
      jsonb_build_object(
        'coach_id', OLD.coach_id,
        'relationship_id', OLD.relationship_id,
        'body', OLD.body
      )
    );
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."coach_content_audit"() OWNER TO "postgres";


