CREATE OR REPLACE FUNCTION "public"."coach_player_relationships_set_primary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();

  -- PAUSED y ENDED nunca son primary (Performance Fase B lee primary ACTIVE).
  IF NEW.status IN ('ENDED', 'PAUSED') THEN
    NEW.is_primary := false;
    IF NEW.status = 'ENDED' AND NEW.ended_at IS NULL THEN
      NEW.ended_at := now();
    END IF;
  ELSIF TG_OP = 'INSERT' AND NEW.status = 'ACTIVE' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.coach_player_relationships r
      WHERE r.jugador_id = NEW.jugador_id
        AND r.status = 'ACTIVE'
        AND r.is_primary = true
        AND r.id IS DISTINCT FROM NEW.id
    ) THEN
      NEW.is_primary := true;
    END IF;
  ELSIF TG_OP = 'UPDATE'
    AND NEW.status = 'ACTIVE'
    AND OLD.status IS DISTINCT FROM 'ACTIVE' THEN
    -- Reanudar desde PAUSED/ENDED: re-promover si no hay otro primary ACTIVE.
    IF NOT EXISTS (
      SELECT 1 FROM public.coach_player_relationships r
      WHERE r.jugador_id = NEW.jugador_id
        AND r.status = 'ACTIVE'
        AND r.is_primary = true
        AND r.id IS DISTINCT FROM NEW.id
    ) THEN
      NEW.is_primary := true;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."coach_player_relationships_set_primary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_dynamic_team_block"("p_block_id" "uuid", "p_teams" "jsonb", "p_pair_to_team_delta" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_block record;
  v_tournament record;
  v_key text;
  v_value jsonb;
  v_merged jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT * INTO v_block
  FROM public.reta_dynamic_blocks
  WHERE id = p_block_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT id, user_id, coalesce(team_config, '{}'::jsonb) AS team_config
  INTO v_tournament
  FROM public.tournaments
  WHERE id = v_block.tournament_id
  FOR UPDATE;

  IF v_tournament.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre esta reta';
  END IF;

  IF v_block.status = 'completed' THEN
    -- Idempotente: reintento tras un timeout de red del primer commit --
    -- no vuelve a mergear pairToTeam (evitaría corromper ediciones
    -- manuales posteriores del organizador, aunque hoy no existen).
    RETURN jsonb_build_object('ok', true, 'status', 'unchanged');
  END IF;

  v_merged := coalesce(v_tournament.team_config -> 'pairToTeam', '{}'::jsonb);
  FOR v_key, v_value IN SELECT key, value FROM jsonb_each(p_pair_to_team_delta) LOOP
    v_merged := jsonb_set(v_merged, ARRAY[v_key], v_value, true);
  END LOOP;

  UPDATE public.tournaments
  SET team_config = jsonb_set(
    coalesce(team_config, '{}'::jsonb),
    ARRAY['pairToTeam'],
    v_merged,
    true
  )
  WHERE id = v_block.tournament_id;

  UPDATE public.reta_dynamic_blocks
  SET status = 'completed', teams = p_teams, generated_at = now()
  WHERE id = p_block_id;

  RETURN jsonb_build_object('ok', true, 'status', 'completed');
END;
$$;


ALTER FUNCTION "public"."commit_dynamic_team_block"("p_block_id" "uuid", "p_teams" "jsonb", "p_pair_to_team_delta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirmar_torneo_express_fase_eliminatoria_transicion"("p_torneo_id" "uuid", "p_fase_eliminacion" "text", "p_bracket_slots" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_organizador uuid;
  v_rows int;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT organizador_id INTO v_organizador
  FROM public.torneo_express
  WHERE id = p_torneo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_organizador IS NULL OR v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  IF public.te_torneo_fase_grupos_incompleta(p_torneo_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_PHASE_INCOMPLETE');
  END IF;

  UPDATE public.torneo_express
  SET fase_torneo = 'eliminatoria',
      fase_eliminacion = p_fase_eliminacion,
      bracket_slots = p_bracket_slots,
      fase_grupos_finalizada_at = now(),
      estado = 'en_curso'
  WHERE id = p_torneo_id
    AND fase_torneo = 'grupos';

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ya_en_eliminatoria');
  END IF;

  RETURN jsonb_build_object('ok', true, 'torneo_id', p_torneo_id);
END;
$$;


ALTER FUNCTION "public"."confirmar_torneo_express_fase_eliminatoria_transicion"("p_torneo_id" "uuid", "p_fase_eliminacion" "text", "p_bracket_slots" "jsonb") OWNER TO "postgres";


