CREATE OR REPLACE FUNCTION "public"."deactivate_coach_from_club"("p_coach_id" "uuid", "p_organizador_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_target_org_id uuid;
  v_has_access boolean;
  v_membership record;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Autenticación requerida');
  END IF;

  v_target_org_id := COALESCE(p_organizador_id, v_caller_id);

  -- Comprobación: debe ser el dueño del club o Master Admin
  v_has_access := public.is_master_admin() OR (
    v_caller_id = v_target_org_id
    AND EXISTS (
      SELECT 1 FROM public.organizador_game_modes ogm
      WHERE ogm.organizador_id = v_caller_id
        AND ogm.coaching_enabled = true
    )
  );

  IF NOT v_has_access THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No autorizado: no tienes permisos para administrar este club.'
    );
  END IF;

  -- Buscar membresía
  SELECT id, status INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id
    AND organizador_id = v_target_org_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El coach no tiene registro de membresía en este club.'
    );
  END IF;

  IF v_membership.status = 'INACTIVE' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'membership_id', v_membership.id,
      'status', 'INACTIVE',
      'message', 'El coach ya se encuentra inactivo en tu club.'
    );
  END IF;

  -- Transición controlada a INACTIVE (preservando historial)
  UPDATE public.coach_club_memberships
  SET
    status = 'INACTIVE',
    deactivated_at = now(),
    updated_at = now()
  WHERE id = v_membership.id;

  RETURN jsonb_build_object(
    'ok', true,
    'membership_id', v_membership.id,
    'status', 'INACTIVE',
    'message', 'Coach desactivado del club correctamente.'
  );
END;
$$;


ALTER FUNCTION "public"."deactivate_coach_from_club"("p_coach_id" "uuid", "p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_student_access"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_authorized boolean;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  v_is_authorized := public.is_master_admin() OR (p_organizador_id = v_caller);
  IF NOT v_is_authorized THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autorizado');
  END IF;

  -- Desactivar únicamente el vínculo de ESTE club
  UPDATE public.coach_student_account_links
  SET is_active = false,
      deactivated_at = now(),
      deactivated_by = v_caller,
      updated_at = now()
  WHERE organizador_id = p_organizador_id
    AND jugador_id = p_jugador_id;

  -- Revocar invitaciones pendientes de ESTE club
  UPDATE public.coach_student_invitations
  SET status = 'REVOKED', revoked_at = now(), revoked_by = v_caller, updated_at = now()
  WHERE organizador_id = p_organizador_id
    AND jugador_id = p_jugador_id
    AND status = 'PENDING';

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'DEACTIVATED',
    'message', 'El acceso en este club ha sido pausado. El Riviera ID, saldos y accesos a otros clubes permanecen intactos.'
  );
END;
$$;


ALTER FUNCTION "public"."deactivate_student_access"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_jugador_participacion_linked"("p_organizador_id" "uuid", "p_view_jugador_id" "uuid", "p_participacion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_part record;
  v_official_key uuid;
  v_home_org uuid;
  v_deleted_count integer := 0;
  v_jid uuid;
  v_pid uuid;
  v_rebuilt uuid[] := ARRAY[]::uuid[];
  v_ids_to_reverse uuid[];
BEGIN
  IF p_organizador_id IS NULL OR p_view_jugador_id IS NULL OR p_participacion_id IS NULL THEN
    RAISE EXCEPTION 'Parámetros incompletos';
  END IF;

  IF auth.uid() IS DISTINCT FROM p_organizador_id THEN
    RAISE EXCEPTION 'Sin permiso para gestionar este registro';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.riviera_jugadores rj
    WHERE rj.id = p_view_jugador_id
      AND rj.organizador_id = p_organizador_id
  ) THEN
    RAISE EXCEPTION 'Jugador no encontrado o sin permiso';
  END IF;

  v_home_org := public._resolve_home_organizador_for_jugador(p_view_jugador_id);

  IF NOT public.is_master_admin()
     AND (v_home_org IS NULL OR v_home_org IS DISTINCT FROM p_organizador_id) THEN
    RAISE EXCEPTION 'Solo el club de registro puede eliminar eventos del historial';
  END IF;

  SELECT
    jp.id,
    jp.jugador_id,
    jp.evento_nombre,
    jp.tipo_evento::text AS tipo_evento,
    jp.evento_id
  INTO v_part
  FROM public.jugador_participaciones jp
  WHERE jp.id = p_participacion_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Registro de historial no encontrado';
  END IF;

  v_official_key := public.resolve_official_player_key_for_jugador(p_view_jugador_id);

  IF v_official_key IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public._riviera_official_jugador_ids_for_key(v_official_key) linked
      WHERE linked.riviera_jugador_id = v_part.jugador_id
    ) THEN
      RAISE EXCEPTION 'La participación no pertenece a este jugador enlazado';
    END IF;

    INSERT INTO public.jugador_participacion_exclusiones (
      official_player_key,
      tipo_evento,
      evento_id,
      evento_nombre,
      deleted_by_organizador_id
    ) VALUES (
      v_official_key,
      v_part.tipo_evento,
      v_part.evento_id,
      v_part.evento_nombre,
      p_organizador_id
    )
    ON CONFLICT DO NOTHING;

    SELECT array_agg(jp.id) INTO v_ids_to_reverse
    FROM public.jugador_participaciones jp
    WHERE jp.tipo_evento::text = v_part.tipo_evento
      AND jp.evento_id = v_part.evento_id
      AND jp.jugador_id IN (
        SELECT linked.riviera_jugador_id
        FROM public._riviera_official_jugador_ids_for_key(v_official_key) linked
      );

    IF v_ids_to_reverse IS NOT NULL THEN
      FOREACH v_pid IN ARRAY v_ids_to_reverse LOOP
        PERFORM public._reverse_ledger_for_participacion_safe(v_pid);
      END LOOP;
    END IF;

    DELETE FROM public.jugador_participaciones jp
    WHERE jp.id = ANY(coalesce(v_ids_to_reverse, ARRAY[]::uuid[]));

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    FOR v_jid IN
      SELECT linked.riviera_jugador_id
      FROM public._riviera_official_jugador_ids_for_key(v_official_key) linked
    LOOP
      PERFORM public.refresh_jugador_stats(v_jid);
      v_rebuilt := array_append(v_rebuilt, v_jid);
    END LOOP;
  ELSE
    IF v_part.jugador_id IS DISTINCT FROM p_view_jugador_id THEN
      RAISE EXCEPTION 'La participación no pertenece a este jugador';
    END IF;

    INSERT INTO public.jugador_participacion_exclusiones (
      scope_jugador_id,
      tipo_evento,
      evento_id,
      evento_nombre,
      deleted_by_organizador_id
    ) VALUES (
      p_view_jugador_id,
      v_part.tipo_evento,
      v_part.evento_id,
      v_part.evento_nombre,
      p_organizador_id
    )
    ON CONFLICT DO NOTHING;

    PERFORM public._reverse_ledger_for_participacion_safe(p_participacion_id);

    DELETE FROM public.jugador_participaciones
    WHERE id = p_participacion_id;

    v_deleted_count := 1;

    PERFORM public.refresh_jugador_stats(v_part.jugador_id);
    v_rebuilt := array_append(v_rebuilt, v_part.jugador_id);
  END IF;

  RETURN jsonb_build_object(
    'status', 'deleted',
    'participacion_id', p_participacion_id,
    'source_jugador_id', v_part.jugador_id,
    'view_jugador_id', p_view_jugador_id,
    'evento_nombre', v_part.evento_nombre,
    'tipo_evento', v_part.tipo_evento,
    'evento_id', v_part.evento_id,
    'deleted_count', v_deleted_count,
    'rebuilt_jugador_ids', to_jsonb(v_rebuilt)
  );
END;
$$;


ALTER FUNCTION "public"."delete_jugador_participacion_linked"("p_organizador_id" "uuid", "p_view_jugador_id" "uuid", "p_participacion_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_jugador_participacion_linked"("p_organizador_id" "uuid", "p_view_jugador_id" "uuid", "p_participacion_id" "uuid") IS 'Elimina evento del historial (ROMC). Solo club de registro. Revierte ledger y recalcula stats.';



CREATE OR REPLACE FUNCTION "public"."delete_riviera_jugador"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row record;
  v_official_key uuid;
  v_backup_suffix text;
  v_grant record;
  v_purge jsonb;
  v_details jsonb := '[]'::jsonb;
  v_locals_purged integer := 0;
  v_locals_skipped integer := 0;
  v_origin_purge jsonb;
BEGIN
  IF p_organizador_id IS NULL OR p_jugador_id IS NULL THEN
    RAISE EXCEPTION 'Parámetros incompletos';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION
      'Sin sesión autenticada. Reintenta tras iniciar sesión.';
  END IF;

  IF auth.uid() IS DISTINCT FROM p_organizador_id THEN
    RAISE EXCEPTION 'Sin permiso para eliminar este jugador';
  END IF;

  SELECT
    rj.id,
    rj.nombre,
    rj.legacy_player_id,
    rj.legacy_liga_jugador_id,
    rj.organizador_id
  INTO v_row
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_jugador_id
    AND rj.organizador_id = p_organizador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jugador no encontrado o sin permiso para eliminarlo';
  END IF;

  -- ── FIX RAISE: solo bloquea si ESTE club es receptor de un CLON cedido ──
  -- access_type='owner' o jugador_id = local (source) → PERMITIR (es origen).
  -- granted_by_admin O local ≠ source → BLOQUEAR (usar Quitar de mi club).
  IF EXISTS (
    SELECT 1
    FROM public.organizer_player_access opa
    WHERE opa.grantee_organizer_id = p_organizador_id
      AND opa.local_jugador_id = p_jugador_id
      AND opa.is_active = true
      AND (
        opa.access_type = 'granted_by_admin'
        OR opa.jugador_id IS DISTINCT FROM p_jugador_id
      )
  ) THEN
    RAISE EXCEPTION
      'No eres el club de origen; usa «Quitar de mi club»';
  END IF;

  v_backup_suffix := to_char(now() AT TIME ZONE 'utc', 'YYYYMMDD_HH24MISS');
  -- Postgres ident ≤ 63 chars: el prefijo + suffix caben.
  v_official_key := public._safe_resolve_official_player_key(p_jugador_id);

  RAISE NOTICE
    'delete_riviera_jugador: backup_suffix=% origin=% org=% key=%',
    v_backup_suffix, p_jugador_id, p_organizador_id, v_official_key;

  -- 1) Primero clones cedidos (OPA donde este id es el SOURCE)
  IF to_regclass('public.organizer_player_access') IS NOT NULL THEN
    FOR v_grant IN
      SELECT
        opa.id AS access_id,
        opa.local_jugador_id,
        opa.grantee_organizer_id,
        opa.is_active
      FROM public.organizer_player_access opa
      WHERE opa.jugador_id = p_jugador_id
        AND opa.local_jugador_id IS NOT NULL
        AND opa.local_jugador_id IS DISTINCT FROM p_jugador_id
      ORDER BY opa.grantee_organizer_id
    LOOP
      v_purge := public._purge_riviera_jugador_scoped(
        v_grant.local_jugador_id,
        v_grant.grantee_organizer_id,
        v_backup_suffix
      );
      IF coalesce(v_purge->>'status', '') = 'purged' THEN
        v_locals_purged := v_locals_purged + 1;
      ELSE
        v_locals_skipped := v_locals_skipped + 1;
      END IF;
      v_details := v_details || jsonb_build_array(v_purge);

      DELETE FROM public.organizer_player_access WHERE id = v_grant.access_id;
    END LOOP;

    -- Grants sin clon / residuales hacia este source
    DELETE FROM public.organizer_player_access
    WHERE jugador_id = p_jugador_id
       OR local_jugador_id = p_jugador_id;
  END IF;

  -- 2) Otros perfiles enlazados al mismo official_player_key (misma identidad)
  IF v_official_key IS NOT NULL
     AND to_regclass('public.riviera_official_player_profile_link') IS NOT NULL THEN
    FOR v_grant IN
      SELECT pl.riviera_jugador_id AS local_jugador_id, rj.organizador_id AS grantee_organizer_id
      FROM public.riviera_official_player_profile_link pl
      JOIN public.riviera_jugadores rj ON rj.id = pl.riviera_jugador_id
      WHERE pl.official_player_key = v_official_key
        AND pl.riviera_jugador_id IS DISTINCT FROM p_jugador_id
    LOOP
      v_purge := public._purge_riviera_jugador_scoped(
        v_grant.local_jugador_id,
        v_grant.grantee_organizer_id,
        v_backup_suffix
      );
      IF coalesce(v_purge->>'status', '') = 'purged' THEN
        v_locals_purged := v_locals_purged + 1;
      ELSE
        v_locals_skipped := v_locals_skipped + 1;
      END IF;
      v_details := v_details || jsonb_build_array(v_purge);
    END LOOP;
  END IF;

  -- 3) Purgar origen
  v_origin_purge := public._purge_riviera_jugador_scoped(
    p_jugador_id,
    p_organizador_id,
    v_backup_suffix
  );

  IF coalesce(v_origin_purge->>'status', '') IS DISTINCT FROM 'purged' THEN
    RAISE EXCEPTION 'No se pudo purgar el origen: %', v_origin_purge;
  END IF;

  -- 4) Limpiar identity/totals/ledger restantes del key si ya no hay links
  IF v_official_key IS NOT NULL THEN
    IF to_regclass('public.riviera_official_player_profile_link') IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.riviera_official_player_profile_link l
         WHERE l.official_player_key = v_official_key
       ) THEN
      IF to_regclass('public.riviera_official_player_totals') IS NOT NULL THEN
        DELETE FROM public.riviera_official_player_totals
        WHERE official_player_key = v_official_key;
      END IF;
      IF to_regclass('public.riviera_official_points_ledger') IS NOT NULL THEN
        DELETE FROM public.riviera_official_points_ledger
        WHERE official_player_key = v_official_key;
      END IF;
      IF to_regclass('public.riviera_official_player_identity') IS NOT NULL THEN
        DELETE FROM public.riviera_official_player_identity
        WHERE official_player_key = v_official_key;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'status', 'deleted',
    'jugador_id', p_jugador_id,
    'organizador_id', p_organizador_id,
    'official_player_key', v_official_key,
    'backup_suffix', v_backup_suffix,
    'locals_purged', v_locals_purged,
    'locals_skipped', v_locals_skipped,
    'origin', v_origin_purge,
    'details', v_details
  );
END;
$$;


ALTER FUNCTION "public"."delete_riviera_jugador"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_riviera_jugador"("p_organizador_id" "uuid", "p_jugador_id" "uuid") IS 'Borrado global Opción X: solo club origen. Propaga a clones cedidos y carrera scoped al jugador. No toca tournaments/pairs/matches/gameses/players. Duelos: null FK, conserva fila. Backup permanente jugador_delete_backup_*_<ts>.';



CREATE OR REPLACE FUNCTION "public"."diag_players_aislamiento_completo"() RETURNS TABLE("seccion" "text", "item" "text", "valor" "text", "detalle" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  RETURN QUERY
  SELECT 'META'::text, 'tabla_players_existe'::text,
    CASE WHEN to_regclass('public.players') IS NOT NULL THEN 'si' ELSE 'no' END,
    NULL::text;

  RETURN QUERY
  SELECT 'META'::text, 'tabla_tournaments_existe'::text,
    CASE WHEN to_regclass('public.tournaments') IS NOT NULL THEN 'si' ELSE 'no' END,
    NULL::text;

  RETURN QUERY
  SELECT 'CONTEO'::text, r.diagnostico,
    COALESCE(r.valor::text, '—'),
    COALESCE(r.nota, '')
  FROM public.diag_players_aislamiento_resumen() r;

  RETURN QUERY
  SELECT 'COLUMNA'::text, c.column_name::text,
    c.data_type::text,
    ('nullable=' || c.is_nullable::text || ' | pos=' || c.ordinal_position::text)::text
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
    AND c.table_name = 'players'
  ORDER BY c.ordinal_position;

  RETURN QUERY
  SELECT 'RLS'::text, p.policyname::text,
    p.cmd::text,
    ('USING: ' || COALESCE(p.qual::text, '(null)')
      || ' | CHECK: ' || COALESCE(p.with_check::text, '(null)'))::text
  FROM pg_policies p
  WHERE p.schemaname = 'public'
    AND p.tablename = 'players'
  ORDER BY p.policyname, p.cmd;

  RETURN QUERY
  SELECT 'RLS'::text, 'players_rls_habilitado'::text,
    CASE WHEN c.relrowsecurity THEN 'si' ELSE 'no' END,
    'forzado=' || CASE WHEN c.relforcerowsecurity THEN 'si' ELSE 'no' END
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relname = 'players';

  RETURN QUERY
  SELECT 'FUNCION'::text, 'can_access_player'::text,
    CASE WHEN EXISTS (
      SELECT 1 FROM pg_proc fp
      JOIN pg_namespace fn ON fn.oid = fp.pronamespace
      WHERE fn.nspname = 'public' AND fp.proname = 'can_access_player'
    ) THEN 'existe' ELSE 'no existe' END,
    COALESCE((
      SELECT pg_get_functiondef(fp.oid)
      FROM pg_proc fp
      JOIN pg_namespace fn ON fn.oid = fp.pronamespace
      WHERE fn.nspname = 'public' AND fp.proname = 'can_access_player'
      LIMIT 1
    ), '');

  RETURN QUERY
  SELECT 'USER_DIST'::text, d.user_id,
    d.filas::text,
    NULL::text
  FROM public.diag_players_aislamiento_user_dist() d;

  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'players' AND column_name = 'tournament_id'
  ) THEN
    RETURN QUERY EXECUTE $q$
      SELECT 'HUERFANA'::text, p.id::text, p.name::text,
        (COALESCE(p.email, '') || ' | tid=' || COALESCE(p.tournament_id::text, 'null'))::text
      FROM public.players p
      WHERE p.tournament_id IS NOT NULL
        AND p.tournament_id <> '00000000-0000-0000-0000-000000000000'::uuid
        AND NOT EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id = p.tournament_id)
      ORDER BY p.created_at DESC NULLS LAST
      LIMIT 20
    $q$;
  END IF;
END;
$_$;


ALTER FUNCTION "public"."diag_players_aislamiento_completo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diag_players_aislamiento_resumen"() RETURNS TABLE("diagnostico" "text", "valor" bigint, "nota" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  has_user_id boolean;
  has_tournament_id boolean;
  cnt bigint;
BEGIN
  IF to_regclass('public.players') IS NULL THEN
    RETURN QUERY SELECT 'ERROR'::text, NULL::bigint, 'tabla public.players no existe'::text;
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'players' AND column_name = 'user_id'
  ) INTO has_user_id;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'players' AND column_name = 'tournament_id'
  ) INTO has_tournament_id;

  EXECUTE 'SELECT count(*) FROM public.players' INTO cnt;
  RETURN QUERY SELECT '1_total_players'::text, cnt, NULL::text;

  IF has_user_id THEN
    EXECUTE 'SELECT count(*) FROM public.players WHERE user_id IS NULL' INTO cnt;
    RETURN QUERY SELECT '2_user_id_null'::text, cnt, NULL::text;
    RETURN QUERY SELECT '2_user_id_columna_existe'::text, 1::bigint, NULL::text;
  ELSE
    RETURN QUERY SELECT '2_user_id_null'::text, NULL::bigint, 'columna user_id NO existe'::text;
    RETURN QUERY SELECT '2_user_id_columna_existe'::text, 0::bigint, NULL::text;
  END IF;

  IF has_tournament_id THEN
    EXECUTE 'SELECT count(*) FROM public.players WHERE tournament_id IS NULL' INTO cnt;
    RETURN QUERY SELECT '2_tournament_id_null'::text, cnt, NULL::text;

    EXECUTE $q$
      SELECT count(*) FROM public.players
      WHERE tournament_id = '00000000-0000-0000-0000-000000000000'::uuid
    $q$ INTO cnt;
    RETURN QUERY SELECT '4_pool_global_tournament_id_cero'::text, cnt, NULL::text;

    IF has_user_id THEN
      EXECUTE $q$
        SELECT count(*) FROM public.players
        WHERE tournament_id = '00000000-0000-0000-0000-000000000000'::uuid
          AND user_id IS NULL
      $q$ INTO cnt;
      RETURN QUERY SELECT '4_pool_global_sin_user_id'::text, cnt, NULL::text;

      EXECUTE $q$
        SELECT count(*) FROM public.players
        WHERE user_id IS NULL AND tournament_id IS NULL
      $q$ INTO cnt;
      RETURN QUERY SELECT '2_ambos_null'::text, cnt, NULL::text;

      EXECUTE $q$
        SELECT count(*) FROM public.players p
        JOIN public.tournaments t ON t.id = p.tournament_id
        WHERE p.user_id IS NULL
      $q$ INTO cnt;
      RETURN QUERY SELECT 'extra_backfill_potencial'::text, cnt, NULL::text;
    ELSE
      RETURN QUERY SELECT '4_pool_global_sin_user_id'::text, NULL::bigint, 'requiere columna user_id'::text;
      RETURN QUERY SELECT '2_ambos_null'::text, NULL::bigint, 'requiere columna user_id'::text;
      RETURN QUERY SELECT 'extra_backfill_potencial'::text, NULL::bigint, 'requiere columna user_id'::text;
    END IF;

    EXECUTE $q$
      SELECT count(*) FROM public.players p
      WHERE p.tournament_id IS NOT NULL
        AND p.tournament_id <> '00000000-0000-0000-0000-000000000000'::uuid
        AND NOT EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id = p.tournament_id)
    $q$ INTO cnt;
    RETURN QUERY SELECT '3_huerfanas_tournament_id'::text, cnt, NULL::text;
  ELSE
    RETURN QUERY SELECT '2_tournament_id_null'::text, NULL::bigint, 'columna tournament_id NO existe'::text;
    RETURN QUERY SELECT '4_pool_global_tournament_id_cero'::text, NULL::bigint, 'columna tournament_id NO existe'::text;
    RETURN QUERY SELECT '4_pool_global_sin_user_id'::text, NULL::bigint, 'columna tournament_id NO existe'::text;
    RETURN QUERY SELECT '2_ambos_null'::text, NULL::bigint, 'columna tournament_id NO existe'::text;
    RETURN QUERY SELECT '3_huerfanas_tournament_id'::text, NULL::bigint, 'columna tournament_id NO existe'::text;
    RETURN QUERY SELECT 'extra_backfill_potencial'::text, NULL::bigint, 'columna tournament_id NO existe'::text;
  END IF;

  IF to_regclass('public.riviera_jugadores') IS NOT NULL THEN
    EXECUTE $q$
      SELECT count(*) FROM public.riviera_jugadores WHERE legacy_player_id IS NOT NULL
    $q$ INTO cnt;
    RETURN QUERY SELECT 'extra_riviera_con_legacy_player_id'::text, cnt, NULL::text;

    EXECUTE $q$
      SELECT count(*) FROM public.players p
      WHERE NOT EXISTS (
        SELECT 1 FROM public.riviera_jugadores r WHERE r.legacy_player_id = p.id
      )
    $q$ INTO cnt;
    RETURN QUERY SELECT 'extra_players_sin_enlace_riviera'::text, cnt, NULL::text;
  ELSE
    RETURN QUERY SELECT 'extra_riviera_con_legacy_player_id'::text, NULL::bigint, 'tabla riviera_jugadores no existe'::text;
    RETURN QUERY SELECT 'extra_players_sin_enlace_riviera'::text, NULL::bigint, 'tabla riviera_jugadores no existe'::text;
  END IF;

  RETURN QUERY SELECT
    '7_can_access_player_existe'::text,
    CASE WHEN EXISTS (
      SELECT 1 FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public' AND p.proname = 'can_access_player'
    ) THEN 1::bigint ELSE 0::bigint END,
    NULL::text;
END;
$_$;


ALTER FUNCTION "public"."diag_players_aislamiento_resumen"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diag_players_aislamiento_user_dist"() RETURNS TABLE("user_id" "text", "filas" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'players' AND column_name = 'user_id'
  ) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT COALESCE(p.user_id::text, '(NULL)'), count(*)::bigint
  FROM public.players p
  GROUP BY p.user_id
  ORDER BY count(*) DESC
  LIMIT 30;
END;
$$;


ALTER FUNCTION "public"."diag_players_aislamiento_user_dist"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_notificaciones_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'vault', 'net', 'public'
    AS $$
DECLARE
  v_api_key text;
  v_webhook text;
  v_payload text;
  v_role text;
BEGIN
  SELECT decrypted_secret INTO v_api_key
  FROM vault.decrypted_secrets
  WHERE name = 'notificaciones_publishable_key'
  LIMIT 1;

  SELECT decrypted_secret INTO v_webhook
  FROM vault.decrypted_secrets
  WHERE name = 'notificaciones_webhook_secret'
  LIMIT 1;

  IF v_api_key IS NULL OR v_webhook IS NULL
     OR length(btrim(v_api_key)) = 0 OR length(btrim(v_webhook)) = 0 THEN
    RAISE WARNING 'notificaciones webhook: faltan secretos de Vault; la fila queda pendiente';
    RETURN NEW;
  END IF;

  IF v_api_key LIKE 'sb_secret_%' THEN
    RAISE WARNING 'notificaciones webhook: la clave de Vault es privilegiada y no se envía';
    RETURN NEW;
  END IF;

  IF v_api_key LIKE 'eyJ%' THEN
    BEGIN
      v_payload := convert_from(
        decode(
          rpad(
            replace(replace(split_part(v_api_key, '.', 2), '-', '+'), '_', '/'),
            ((length(replace(replace(split_part(v_api_key, '.', 2), '-', '+'), '_', '/')) + 3) / 4) * 4,
            '='
          ),
          'base64'
        ),
        'utf8'
      );
      v_role := substring(v_payload FROM '"role"[[:space:]]*:[[:space:]]*"([^"]+)"');
    EXCEPTION WHEN OTHERS THEN
      v_role := NULL;
    END;
    IF v_role IS DISTINCT FROM 'anon' THEN
      RAISE WARNING 'notificaciones webhook: el JWT de Vault no es anon y no se envía';
      RETURN NEW;
    END IF;
  ELSIF v_api_key NOT LIKE 'sb_publishable_%' THEN
    RAISE WARNING 'notificaciones webhook: la clave de Vault no es publishable y no se envía';
    RETURN NEW;
  END IF;

  PERFORM net.http_post(
    url := 'https://giswxhmjgjepoobdoljb.supabase.co/functions/v1/procesar-notificaciones-evento',
    body := jsonb_build_object('record', jsonb_build_object('id', NEW.id)),
    params := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_api_key,
      'x-notificaciones-secret', v_webhook
    ),
    timeout_milliseconds := 5000
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dispatch_notificaciones_webhook"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."encolar_bienvenida_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT public.encolar_bienvenida_liga(p_liga_id, p_liga_jugador_id, 'accion_admin');
$$;


ALTER FUNCTION "public"."encolar_bienvenida_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."encolar_bienvenida_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid", "p_origen" "text" DEFAULT 'accion_admin'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_org uuid;
  v_inscripcion uuid;
  v_en_equipo boolean := false;
  v_pausada boolean;
  v_modo text := 'manual';
  v_elegible text;
  v_key text;
  v_existing public.liga_notificaciones_queue%ROWTYPE;
  v_origen text := lower(btrim(coalesce(p_origen, 'accion_admin')));
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'anon');
  END IF;

  IF v_origen NOT IN ('accion_admin', 'inscripcion_confirmada') THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'origen_no_permitido');
  END IF;

  SELECT organizador_id INTO v_org FROM public.ligas WHERE id = p_liga_id;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'liga_no_encontrada');
  END IF;
  IF v_org IS DISTINCT FROM v_caller AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'sin_permiso');
  END IF;

  SELECT
    coalesce(c.bienvenida_pausada, true),
    coalesce(to_jsonb(c)->>'modo_operacion', 'manual')
    INTO v_pausada, v_modo
  FROM public.liga_notificaciones_config c
  WHERE c.liga_id = p_liga_id;

  -- Automático permanece apagado salvo modo_operacion=automatico.
  IF v_origen = 'inscripcion_confirmada'
     AND coalesce(v_modo, 'manual') IS DISTINCT FROM 'automatico' THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'modo_manual');
  END IF;

  -- La pausa solo bloquea automatismos; el envío manual confirmado sigue.
  IF v_origen = 'inscripcion_confirmada' AND (v_pausada IS NULL OR v_pausada) THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'liga_pausada');
  END IF;

  SELECT id INTO v_inscripcion
  FROM public.liga_inscripciones
  WHERE liga_id = p_liga_id AND jugador_id = p_liga_jugador_id
  LIMIT 1;

  IF v_inscripcion IS NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.liga_equipos e
      WHERE e.liga_id = p_liga_id
        AND (e.jugador1_id = p_liga_jugador_id OR e.jugador2_id = p_liga_jugador_id)
    ) INTO v_en_equipo;
  END IF;

  IF v_inscripcion IS NULL AND NOT v_en_equipo THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'ya_no_inscrito');
  END IF;

  v_elegible := public.liga_notificacion_elegible_manual(p_liga_id, p_liga_jugador_id);
  IF v_elegible IS DISTINCT FROM 'ok' THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', v_elegible);
  END IF;

  v_key := 'bienvenida:' || p_liga_id::text || ':'
    || COALESCE(v_inscripcion::text, 'sin-inscripcion') || ':'
    || p_liga_jugador_id::text;

  SELECT * INTO v_existing
  FROM public.liga_notificaciones_queue
  WHERE idempotency_key = v_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.estado = 'enviado' THEN
      RETURN jsonb_build_object('ok', true, 'encolado', false, 'motivo', 'ya_enviado');
    END IF;
    IF v_existing.estado IN ('pendiente', 'procesando') THEN
      RETURN jsonb_build_object('ok', true, 'encolado', false, 'motivo', 'ya_encolado');
    END IF;
    UPDATE public.liga_notificaciones_queue
      SET estado = 'pendiente',
          attempts = 0,
          motivo = NULL,
          updated_at = now(),
          processed_at = NULL
      WHERE id = v_existing.id;
    RETURN jsonb_build_object('ok', true, 'encolado', true, 'motivo', NULL);
  END IF;

  BEGIN
    INSERT INTO public.liga_notificaciones_queue (
      liga_id, liga_jugador_id, inscripcion_id, tipo, idempotency_key, estado
    ) VALUES (
      p_liga_id, p_liga_jugador_id, v_inscripcion, 'bienvenida', v_key, 'pendiente'
    );
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', true, 'encolado', false, 'motivo', 'ya_encolado');
  END;

  RETURN jsonb_build_object('ok', true, 'encolado', true, 'motivo', NULL);
END;
$$;


ALTER FUNCTION "public"."encolar_bienvenida_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid", "p_origen" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."encolar_comunicacion_manual_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid", "p_tipo" "text", "p_asunto" "text", "p_cuerpo" "text", "p_lote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_org uuid;
  v_inscripcion uuid;
  v_en_equipo boolean := false;
  v_elegible text;
  v_tipo text := lower(btrim(coalesce(p_tipo, '')));
  v_asunto text := left(btrim(coalesce(p_asunto, '')), 180);
  v_cuerpo text := left(btrim(coalesce(p_cuerpo, '')), 8000);
  v_key text;
  v_existing public.liga_notificaciones_queue%ROWTYPE;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'anon');
  END IF;

  IF v_tipo NOT IN (
    'bienvenida', 'aviso_general', 'jornada',
    'cambio_horario', 'felicitacion', 'personalizado'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'tipo_no_soportado');
  END IF;

  IF p_lote_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'lote_requerido');
  END IF;

  IF v_asunto = '' OR v_cuerpo = '' THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'mensaje_incompleto');
  END IF;

  SELECT organizador_id INTO v_org FROM public.ligas WHERE id = p_liga_id;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'liga_no_encontrada');
  END IF;
  IF v_org IS DISTINCT FROM v_caller AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'sin_permiso');
  END IF;

  SELECT id INTO v_inscripcion
  FROM public.liga_inscripciones
  WHERE liga_id = p_liga_id AND jugador_id = p_liga_jugador_id
  LIMIT 1;

  IF v_inscripcion IS NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.liga_equipos e
      WHERE e.liga_id = p_liga_id
        AND (e.jugador1_id = p_liga_jugador_id OR e.jugador2_id = p_liga_jugador_id)
    ) INTO v_en_equipo;
  END IF;

  IF v_inscripcion IS NULL AND NOT v_en_equipo THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', 'ya_no_inscrito');
  END IF;

  v_elegible := public.liga_notificacion_elegible_manual(p_liga_id, p_liga_jugador_id);
  IF v_elegible IS DISTINCT FROM 'ok' THEN
    RETURN jsonb_build_object('ok', false, 'encolado', false, 'motivo', v_elegible);
  END IF;

  v_key := 'manual:' || v_tipo || ':' || p_liga_id::text || ':'
    || p_lote_id::text || ':' || p_liga_jugador_id::text;

  SELECT * INTO v_existing
  FROM public.liga_notificaciones_queue
  WHERE idempotency_key = v_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.estado = 'enviado' THEN
      RETURN jsonb_build_object('ok', true, 'encolado', false, 'motivo', 'ya_enviado');
    END IF;
    IF v_existing.estado IN ('pendiente', 'procesando') THEN
      RETURN jsonb_build_object('ok', true, 'encolado', false, 'motivo', 'ya_encolado');
    END IF;
    UPDATE public.liga_notificaciones_queue
      SET estado = 'pendiente',
          attempts = 0,
          motivo = NULL,
          asunto = v_asunto,
          cuerpo_texto = v_cuerpo,
          lote_id = p_lote_id,
          updated_at = now(),
          processed_at = NULL
      WHERE id = v_existing.id;
    RETURN jsonb_build_object('ok', true, 'encolado', true, 'motivo', NULL);
  END IF;

  BEGIN
    INSERT INTO public.liga_notificaciones_queue (
      liga_id, liga_jugador_id, inscripcion_id, tipo,
      idempotency_key, estado, asunto, cuerpo_texto, lote_id
    ) VALUES (
      p_liga_id, p_liga_jugador_id, v_inscripcion, v_tipo,
      v_key, 'pendiente', v_asunto, v_cuerpo, p_lote_id
    );
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', true, 'encolado', false, 'motivo', 'ya_encolado');
  END;

  RETURN jsonb_build_object('ok', true, 'encolado', true, 'motivo', NULL);
END;
$$;


ALTER FUNCTION "public"."encolar_comunicacion_manual_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid", "p_tipo" "text", "p_asunto" "text", "p_cuerpo" "text", "p_lote_id" "uuid") OWNER TO "postgres";


