CREATE OR REPLACE FUNCTION "public"."ensure_granted_player_local"("p_source_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_grantee uuid := auth.uid();
  v_access public.organizer_player_access%ROWTYPE;
  v_source public.riviera_jugadores%ROWTYPE;
  v_local_id uuid;
  v_nombre text;
  v_categoria text;
  v_slug text;
BEGIN
  IF v_grantee IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  SELECT *
  INTO v_access
  FROM public.organizer_player_access opa
  WHERE opa.jugador_id = p_source_jugador_id
    AND opa.grantee_organizer_id = v_grantee
    AND opa.is_active = true
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sin acceso concedido para este jugador';
  END IF;

  SELECT *
  INTO v_source
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_source_jugador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jugador origen no encontrado';
  END IF;

  IF v_access.local_jugador_id IS NOT NULL THEN
    PERFORM public._apply_granted_local_identity_sync(v_access, v_source);
    RETURN v_access.local_jugador_id;
  END IF;

  v_nombre := coalesce(nullif(trim(v_access.local_display_name), ''), v_source.nombre);
  v_categoria := coalesce(nullif(trim(v_access.local_category), ''), v_source.categoria::text);

  v_slug := public._ensure_unique_jugador_slug(
    v_grantee,
    public._slugify_jugador_nombre(v_nombre),
    coalesce(v_source.genero, 'M')
  );

  INSERT INTO public.riviera_jugadores (
    nombre,
    slug,
    email,
    telefono,
    whatsapp,
    nivel,
    categoria,
    edad,
    mano_dominante,
    en_cancha,
    pais_codigo,
    genero,
    club,
    foto_url,
    instagram_url,
    facebook_url,
    tiktok_url,
    visible_publico,
    suma_ranking,
    organizador_id,
    estado,
    legacy_player_id,
    rating,
    rating_partidos,
    rating_fiabilidad
  )
  VALUES (
    v_nombre,
    v_slug,
    NULL,
    NULL,
    NULL,
    v_source.nivel,
    v_categoria,
    v_source.edad,
    v_source.mano_dominante,
    v_source.en_cancha,
    v_source.pais_codigo,
    v_source.genero,
    NULL,
    v_source.foto_url,
    NULL,
    NULL,
    NULL,
    CASE WHEN v_access.is_public_ranking THEN true ELSE false END,
    true,
    v_grantee,
    'activo',
    v_source.legacy_player_id,
    COALESCE(v_source.rating, 3),
    COALESCE(v_source.rating_partidos, 0),
    COALESCE(v_source.rating_fiabilidad, 0.2)
  )
  RETURNING id INTO v_local_id;

  PERFORM public._create_empty_jugador_stats(v_local_id);

  UPDATE public.organizer_player_access
  SET local_jugador_id = v_local_id,
      updated_at = now()
  WHERE id = v_access.id;

  RETURN v_local_id;
END;
$$;


ALTER FUNCTION "public"."ensure_granted_player_local"("p_source_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_official_profile_link_for_participacion"("p_jugador_id" "uuid", "p_organizador_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_link_id uuid;
  v_role text := COALESCE(auth.role(), '');
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN jsonb_build_object(
      'linked', false, 'confidence', 'LOW', 'reason', 'missing_jugador_id',
      'action_sugerida', 'INSUFFICIENT_EVIDENCE'
    );
  END IF;

  SELECT * INTO v_row
  FROM public._riviera_profile_link_resolution(p_jugador_id);

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'linked', false, 'confidence', 'LOW', 'reason', 'jugador_no_encontrado',
      'action_sugerida', 'INSUFFICIENT_EVIDENCE', 'jugador_id', p_jugador_id
    );
  END IF;

  IF v_row.has_profile_link THEN
    RETURN jsonb_build_object(
      'linked', true, 'already_linked', true, 'confidence', 'OK',
      'reason', v_row.reason, 'action_sugerida', 'NONE',
      'official_player_key', v_row.existing_official_player_key,
      'riviera_id', v_row.existing_riviera_id, 'jugador_id', p_jugador_id
    );
  END IF;

  IF v_row.confidence IS DISTINCT FROM 'HIGH'
     OR v_row.candidate_official_player_key IS NULL THEN
    RETURN jsonb_build_object(
      'linked', false, 'confidence', v_row.confidence,
      'reason', v_row.reason, 'action_sugerida', v_row.action_sugerida,
      'jugador_id', p_jugador_id, 'jugador_nombre', v_row.jugador_nombre,
      'candidate_count', v_row.candidate_count,
      'candidate_riviera_id', v_row.candidate_riviera_id,
      'candidate_official_player_key', v_row.candidate_official_player_key,
      'grant_to_canonical', v_row.grant_to_canonical,
      'grant_to_identity', v_row.grant_to_identity,
      'same_legacy', v_row.same_legacy,
      'host_club_overlap', v_row.host_club_overlap,
      'cross_club_profile', v_row.cross_club_profile
    );
  END IF;

  -- P0: anon nunca escribe links (aunque tenga EXECUTE residual).
  IF v_role = 'anon' THEN
    RETURN jsonb_build_object(
      'linked', false, 'confidence', 'LOW', 'reason', 'permission_denied',
      'action_sugerida', 'INSUFFICIENT_EVIDENCE', 'jugador_id', p_jugador_id
    );
  END IF;

  -- P0: authenticated (no master) siempre autoriza el INSERT.
  -- p_organizador_id NULL ya NO salta el check: exige ownership del jugador.
  IF v_role = 'authenticated' AND NOT public.is_master_admin() THEN
    IF v_actor IS NULL THEN
      RETURN jsonb_build_object(
        'linked', false, 'confidence', 'LOW', 'reason', 'permission_denied',
        'action_sugerida', 'INSUFFICIENT_EVIDENCE', 'jugador_id', p_jugador_id
      );
    END IF;

    IF p_organizador_id IS NOT NULL THEN
      IF v_actor IS DISTINCT FROM p_organizador_id THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.riviera_jugadores rj
          WHERE rj.id = p_jugador_id AND rj.organizador_id = p_organizador_id
        ) THEN
          RETURN jsonb_build_object(
            'linked', false, 'confidence', 'LOW', 'reason', 'permission_denied',
            'action_sugerida', 'INSUFFICIENT_EVIDENCE', 'jugador_id', p_jugador_id
          );
        END IF;
      END IF;
    ELSE
      IF NOT EXISTS (
        SELECT 1 FROM public.riviera_jugadores rj
        WHERE rj.id = p_jugador_id AND rj.organizador_id = v_actor
      ) THEN
        RETURN jsonb_build_object(
          'linked', false, 'confidence', 'LOW', 'reason', 'permission_denied',
          'action_sugerida', 'INSUFFICIENT_EVIDENCE', 'jugador_id', p_jugador_id
        );
      END IF;
    END IF;
  END IF;

  INSERT INTO public.riviera_official_player_profile_link (
    official_player_key, riviera_jugador_id, organizer_id, link_source, created_by
  ) VALUES (
    v_row.candidate_official_player_key, p_jugador_id,
    v_row.jugador_organizador_id, 'manual_admin', v_actor
  )
  ON CONFLICT (riviera_jugador_id) DO NOTHING
  RETURNING id INTO v_link_id;

  RETURN jsonb_build_object(
    'linked', v_link_id IS NOT NULL OR v_row.has_profile_link,
    'link_created', v_link_id IS NOT NULL, 'confidence', 'HIGH',
    'reason', v_row.reason, 'action_sugerida', 'LINK_TO_OFFICIAL',
    'official_player_key', v_row.candidate_official_player_key,
    'riviera_id', v_row.candidate_riviera_id, 'jugador_id', p_jugador_id
  );
END;
$$;


ALTER FUNCTION "public"."ensure_official_profile_link_for_participacion"("p_jugador_id" "uuid", "p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_riviera_identity"("p_riviera_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_jugador record;
  v_key uuid;
  v_link record;
  v_grant record;
  v_origin record;
  v_canonical_id uuid;
  v_link_id uuid;
  v_link_source text;
  v_identity_created boolean := false;
  v_link_created boolean := false;
  v_assign record;
  v_debut_set boolean := false;
  v_identity record;
BEGIN
  IF p_riviera_jugador_id IS NULL THEN
    RAISE EXCEPTION 'riviera_jugador_id requerido';
  END IF;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  -- Lock transaccional por jugador (anti-carrera)
  PERFORM pg_advisory_xact_lock(200202, hashtext(p_riviera_jugador_id::text));

  SELECT rj.id, rj.organizador_id, rj.nombre, rj.created_at
  INTO v_jugador
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_riviera_jugador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jugador no encontrado';
  END IF;

  IF NOT public.is_master_admin()
     AND v_jugador.organizador_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Sin permiso para asegurar identidad de este jugador';
  END IF;

  -- ── A) Perfil ya vinculado ──
  SELECT l.id, l.official_player_key, l.link_source
  INTO v_link
  FROM public.riviera_official_player_profile_link l
  WHERE l.riviera_jugador_id = p_riviera_jugador_id;

  IF FOUND THEN
    v_key := v_link.official_player_key;
    v_link_source := v_link.link_source;

    SELECT * INTO v_assign
    FROM public._assign_riviera_id_to_identity(v_key);

    v_debut_set := public._ensure_debut_riviera_if_missing(
      v_key,
      (SELECT i.canonical_riviera_jugador_id
       FROM public.riviera_official_player_identity i
       WHERE i.official_player_key = v_key),
      NULL
    );

    SELECT
      i.official_player_key,
      i.riviera_id,
      i.riviera_id_serial,
      i.canonical_riviera_jugador_id,
      i.debut_organizer_id,
      i.debut_at,
      i.created_at
    INTO v_identity
    FROM public.riviera_official_player_identity i
    WHERE i.official_player_key = v_key;

    RETURN jsonb_build_object(
      'official_player_key', v_identity.official_player_key,
      'riviera_id', v_identity.riviera_id,
      'riviera_id_serial', v_identity.riviera_id_serial,
      'riviera_jugador_id', p_riviera_jugador_id,
      'registration_jugador_id', v_identity.canonical_riviera_jugador_id,
      'debut_organizer_id', v_identity.debut_organizer_id,
      'debut_at', v_identity.debut_at,
      'link_source', v_link_source,
      'identity_created', false,
      'link_created', false,
      'riviera_id_assigned', coalesce(v_assign.assigned, false),
      'debut_assigned', v_debut_set
    );
  END IF;

  -- ── B) Identidad resoluble vía grant (origen ya tiene carrera) ──
  v_key := public._resolve_official_player_key(p_riviera_jugador_id);

  IF v_key IS NOT NULL THEN
    SELECT opa.id, opa.jugador_id
    INTO v_grant
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND opa.local_jugador_id = p_riviera_jugador_id
    LIMIT 1;

    v_link_source := CASE
      WHEN v_grant.jugador_id IS NOT NULL THEN 'granted_local'
      ELSE 'owner'
    END;

    INSERT INTO public.riviera_official_player_profile_link (
      official_player_key,
      riviera_jugador_id,
      organizer_id,
      link_source,
      organizer_player_access_id,
      created_by
    )
    VALUES (
      v_key,
      p_riviera_jugador_id,
      v_jugador.organizador_id,
      v_link_source,
      v_grant.id,
      v_actor
    )
    ON CONFLICT (riviera_jugador_id) DO NOTHING
    RETURNING id INTO v_link_id;

    v_link_created := v_link_id IS NOT NULL;

    IF NOT v_link_created THEN
      SELECT l.link_source INTO v_link_source
      FROM public.riviera_official_player_profile_link l
      WHERE l.riviera_jugador_id = p_riviera_jugador_id;
    END IF;

    SELECT * INTO v_assign
    FROM public._assign_riviera_id_to_identity(v_key);

    v_debut_set := public._ensure_debut_riviera_if_missing(
      v_key,
      (SELECT i.canonical_riviera_jugador_id
       FROM public.riviera_official_player_identity i
       WHERE i.official_player_key = v_key),
      NULL
    );

    SELECT
      i.official_player_key,
      i.riviera_id,
      i.riviera_id_serial,
      i.canonical_riviera_jugador_id,
      i.debut_organizer_id,
      i.debut_at
    INTO v_identity
    FROM public.riviera_official_player_identity i
    WHERE i.official_player_key = v_key;

    RETURN jsonb_build_object(
      'official_player_key', v_identity.official_player_key,
      'riviera_id', v_identity.riviera_id,
      'riviera_id_serial', v_identity.riviera_id_serial,
      'riviera_jugador_id', p_riviera_jugador_id,
      'registration_jugador_id', v_identity.canonical_riviera_jugador_id,
      'debut_organizer_id', v_identity.debut_organizer_id,
      'debut_at', v_identity.debut_at,
      'link_source', v_link_source,
      'identity_created', false,
      'link_created', v_link_created,
      'riviera_id_assigned', coalesce(v_assign.assigned, false),
      'debut_assigned', v_debut_set
    );
  END IF;

  -- ── C) Grant activo: crear carrera en origen (Organizador de Registro) ──
  SELECT
    opa.id AS access_id,
    opa.jugador_id AS origin_jugador_id
  INTO v_grant
  FROM public.organizer_player_access opa
  WHERE opa.is_active = true
    AND opa.local_jugador_id = p_riviera_jugador_id
  LIMIT 1;

  IF v_grant.origin_jugador_id IS NOT NULL THEN
    SELECT rj.id, rj.organizador_id, rj.nombre, rj.created_at
    INTO v_origin
    FROM public.riviera_jugadores rj
    WHERE rj.id = v_grant.origin_jugador_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Jugador origen del grant no encontrado';
    END IF;

    v_canonical_id := v_origin.id;

    INSERT INTO public.riviera_official_player_identity (
      canonical_riviera_jugador_id,
      created_by
    )
    VALUES (v_canonical_id, v_actor)
    ON CONFLICT ON CONSTRAINT ropi_canonical_jugador_unique DO NOTHING
    RETURNING official_player_key INTO v_key;

    IF v_key IS NULL THEN
      SELECT i.official_player_key
      INTO v_key
      FROM public.riviera_official_player_identity i
      WHERE i.canonical_riviera_jugador_id = v_canonical_id;
      v_identity_created := false;
    ELSE
      v_identity_created := true;
    END IF;

    INSERT INTO public.riviera_official_player_profile_link (
      official_player_key,
      riviera_jugador_id,
      organizer_id,
      link_source,
      created_by
    )
    VALUES (
      v_key,
      v_origin.id,
      v_origin.organizador_id,
      'owner',
      v_actor
    )
    ON CONFLICT (riviera_jugador_id) DO NOTHING;

    INSERT INTO public.riviera_official_player_profile_link (
      official_player_key,
      riviera_jugador_id,
      organizer_id,
      link_source,
      organizer_player_access_id,
      created_by
    )
    VALUES (
      v_key,
      p_riviera_jugador_id,
      v_jugador.organizador_id,
      'granted_local',
      v_grant.access_id,
      v_actor
    )
    ON CONFLICT (riviera_jugador_id) DO NOTHING
    RETURNING id INTO v_link_id;

    v_link_created := v_link_id IS NOT NULL;
    v_link_source := 'granted_local';

    INSERT INTO public.riviera_official_player_totals (official_player_key, points_total)
    VALUES (v_key, 0)
    ON CONFLICT (official_player_key) DO NOTHING;

    PERFORM public._ensure_debut_riviera_if_missing(
      v_key,
      v_canonical_id,
      coalesce(v_origin.created_at, now())
    );

    SELECT * INTO v_assign
    FROM public._assign_riviera_id_to_identity(v_key);

    SELECT
      i.official_player_key,
      i.riviera_id,
      i.riviera_id_serial,
      i.canonical_riviera_jugador_id,
      i.debut_organizer_id,
      i.debut_at
    INTO v_identity
    FROM public.riviera_official_player_identity i
    WHERE i.official_player_key = v_key;

    RETURN jsonb_build_object(
      'official_player_key', v_identity.official_player_key,
      'riviera_id', v_identity.riviera_id,
      'riviera_id_serial', v_identity.riviera_id_serial,
      'riviera_jugador_id', p_riviera_jugador_id,
      'registration_jugador_id', v_identity.canonical_riviera_jugador_id,
      'debut_organizer_id', v_identity.debut_organizer_id,
      'debut_at', v_identity.debut_at,
      'link_source', v_link_source,
      'identity_created', v_identity_created,
      'link_created', v_link_created,
      'riviera_id_assigned', coalesce(v_assign.assigned, false),
      'debut_assigned', true
    );
  END IF;

  -- ── D) Nueva Carrera Deportiva (registro inicial en este organizador) ──
  v_canonical_id := p_riviera_jugador_id;

  INSERT INTO public.riviera_official_player_identity (
    canonical_riviera_jugador_id,
    created_by
  )
  VALUES (v_canonical_id, v_actor)
  ON CONFLICT ON CONSTRAINT ropi_canonical_jugador_unique DO NOTHING
  RETURNING official_player_key INTO v_key;

  IF v_key IS NULL THEN
    SELECT i.official_player_key
    INTO v_key
    FROM public.riviera_official_player_identity i
    WHERE i.canonical_riviera_jugador_id = v_canonical_id;

    IF v_key IS NULL THEN
      RAISE EXCEPTION 'No se pudo crear ni resolver identidad para jugador %', p_riviera_jugador_id;
    END IF;

    v_identity_created := false;

    INSERT INTO public.riviera_official_player_profile_link (
      official_player_key,
      riviera_jugador_id,
      organizer_id,
      link_source,
      created_by
    )
    VALUES (
      v_key,
      p_riviera_jugador_id,
      v_jugador.organizador_id,
      'owner',
      v_actor
    )
    ON CONFLICT (riviera_jugador_id) DO NOTHING
    RETURNING id INTO v_link_id;

    v_link_created := v_link_id IS NOT NULL;
    v_link_source := 'owner';

    SELECT * INTO v_assign
    FROM public._assign_riviera_id_to_identity(v_key);

    v_debut_set := public._ensure_debut_riviera_if_missing(v_key, v_canonical_id, NULL);

    SELECT
      i.official_player_key,
      i.riviera_id,
      i.riviera_id_serial,
      i.canonical_riviera_jugador_id,
      i.debut_organizer_id,
      i.debut_at
    INTO v_identity
    FROM public.riviera_official_player_identity i
    WHERE i.official_player_key = v_key;

    RETURN jsonb_build_object(
      'official_player_key', v_identity.official_player_key,
      'riviera_id', v_identity.riviera_id,
      'riviera_id_serial', v_identity.riviera_id_serial,
      'riviera_jugador_id', p_riviera_jugador_id,
      'registration_jugador_id', v_identity.canonical_riviera_jugador_id,
      'debut_organizer_id', v_identity.debut_organizer_id,
      'debut_at', v_identity.debut_at,
      'link_source', v_link_source,
      'identity_created', v_identity_created,
      'link_created', v_link_created,
      'riviera_id_assigned', coalesce(v_assign.assigned, false),
      'debut_assigned', v_debut_set
    );
  END IF;

  v_identity_created := true;
  v_link_source := 'owner';

  INSERT INTO public.riviera_official_player_profile_link (
    official_player_key,
    riviera_jugador_id,
    organizer_id,
    link_source,
    created_by
  )
  VALUES (
    v_key,
    p_riviera_jugador_id,
    v_jugador.organizador_id,
    'owner',
    v_actor
  )
  RETURNING id INTO v_link_id;

  v_link_created := true;

  INSERT INTO public.riviera_official_player_totals (official_player_key, points_total)
  VALUES (v_key, 0);

  PERFORM public._ensure_debut_riviera_if_missing(
    v_key,
    v_canonical_id,
    coalesce(v_jugador.created_at, now())
  );

  SELECT * INTO v_assign
  FROM public._assign_riviera_id_to_identity(v_key);

  SELECT
    i.official_player_key,
    i.riviera_id,
    i.riviera_id_serial,
    i.canonical_riviera_jugador_id,
    i.debut_organizer_id,
    i.debut_at
  INTO v_identity
  FROM public.riviera_official_player_identity i
  WHERE i.official_player_key = v_key;

  RETURN jsonb_build_object(
    'official_player_key', v_identity.official_player_key,
    'riviera_id', v_identity.riviera_id,
    'riviera_id_serial', v_identity.riviera_id_serial,
    'riviera_jugador_id', p_riviera_jugador_id,
    'registration_jugador_id', v_identity.canonical_riviera_jugador_id,
    'debut_organizer_id', v_identity.debut_organizer_id,
    'debut_at', v_identity.debut_at,
    'link_source', v_link_source,
    'identity_created', v_identity_created,
    'link_created', v_link_created,
    'riviera_id_assigned', coalesce(v_assign.assigned, false),
    'debut_assigned', true
  );
END;
$$;


ALTER FUNCTION "public"."ensure_riviera_identity"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_riviera_identity"("p_riviera_jugador_id" "uuid") IS 'Sprint 2.0.2 — Asegura Carrera Deportiva + Riviera ID para un riviera_jugador_id. Idempotente; reutiliza identidad existente; grant-aware. Auth: organizador dueño del perfil o Admin Maestro. No expuesto en UI aún.';



CREATE OR REPLACE FUNCTION "public"."fetch_club_coaching_agenda"("p_organizador_id" "uuid", "p_coach_id" "uuid" DEFAULT NULL::"uuid", "p_from_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_status_filter" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_caller_coach_id uuid := public.current_riviera_coach_id();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_from timestamptz := COALESCE(p_from_date, now() - interval '30 days');
  v_to timestamptz := COALESCE(p_to_date, now() + interval '90 days');
  v_sessions jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_caller <> p_organizador_id
     AND NOT v_is_master
     AND NOT (v_caller_coach_id IS NOT NULL AND (p_coach_id = v_caller_coach_id OR p_coach_id IS NULL)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes autorización para consultar la agenda de este club.');
  END IF;

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    p_coach_id := v_caller_coach_id;
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'coach_id', s.coach_id,
      'coach_nombre', rc.nombre,
      'coach_code', rc.coach_code,
      'coach_foto', rc.foto_url,
      'jugador_id', s.jugador_id,
      'jugador_nombre', rj.nombre,
      'jugador_foto', rj.foto_url,
      'riviera_id', COALESCE(
        (SELECT i.riviera_id FROM public.riviera_official_player_identity i WHERE i.canonical_riviera_jugador_id = rj.id LIMIT 1),
        ''
      ),
      'relationship_id', s.relationship_id,
      'starts_at', s.starts_at,
      'ends_at', s.ends_at,
      'duration_minutes', s.duration_minutes,
      'court', s.court,
      'focus', s.focus,
      'notes_summary', s.notes_summary,
      'prep_message_to_student', s.prep_message_to_student,
      'status', s.status,
      'worked_on', s.worked_on,
      'cancellation_reason', s.cancellation_reason,
      'reverted_at', s.reverted_at,
      'balance_classes', COALESCE(b.balance_classes, 0),
      'created_at', s.created_at
    ) ORDER BY s.starts_at ASC
  ), '[]'::jsonb)
  INTO v_sessions
  FROM public.coach_sessions s
  JOIN public.riviera_coaches rc ON rc.id = s.coach_id
  LEFT JOIN public.riviera_jugadores rj ON rj.id = s.jugador_id
  LEFT JOIN public.coach_player_class_balances b ON b.relationship_id = s.relationship_id
  WHERE s.organizador_id = p_organizador_id
    AND (p_coach_id IS NULL OR s.coach_id = p_coach_id)
    AND (p_status_filter IS NULL OR s.status = p_status_filter)
    AND s.starts_at >= v_from
    AND s.starts_at <= v_to;

  RETURN jsonb_build_object(
    'ok', true,
    'sessions', v_sessions
  );
END;
$$;


ALTER FUNCTION "public"."fetch_club_coaching_agenda"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_from_date" timestamp with time zone, "p_to_date" timestamp with time zone, "p_status_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_coach_agenda"("p_organizador_id" "uuid" DEFAULT NULL::"uuid", "p_status_filter" "text" DEFAULT NULL::"text", "p_from_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_coach_id uuid;
  v_from timestamptz := COALESCE(p_from_date, now() - interval '24 hours');
  v_to timestamptz := COALESCE(p_to_date, now() + interval '90 days');
  v_sessions jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  v_coach_id := public.current_riviera_coach_id();
  IF v_coach_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El usuario no tiene credencial de entrenador activa.');
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'coach_id', s.coach_id,
      'coach_nombre', rc.nombre,
      'coach_code', rc.coach_code,
      'coach_foto', rc.foto_url,
      'jugador_id', s.jugador_id,
      'jugador_nombre', rj.nombre,
      'jugador_foto', rj.foto_url,
      'riviera_id', COALESCE(
        (SELECT i.riviera_id FROM public.riviera_official_player_identity i WHERE i.canonical_riviera_jugador_id = rj.id LIMIT 1),
        ''
      ),
      'relationship_id', s.relationship_id,
      'organizador_id', s.organizador_id,
      'club_nombre', COALESCE(u.name, ogm.branding_key, 'Club Riviera'),
      'starts_at', s.starts_at,
      'ends_at', s.ends_at,
      'duration_minutes', s.duration_minutes,
      'court', s.court,
      'focus', s.focus,
      'notes_summary', s.notes_summary,
      'prep_message_to_student', s.prep_message_to_student,
      'status', s.status,
      'worked_on', s.worked_on,
      'cancellation_reason', s.cancellation_reason,
      'reverted_at', s.reverted_at,
      'balance_classes', COALESCE(b.balance_classes, 0),
      'created_at', s.created_at
    ) ORDER BY s.starts_at ASC
  ), '[]'::jsonb)
  INTO v_sessions
  FROM public.coach_sessions s
  JOIN public.riviera_coaches rc ON rc.id = s.coach_id
  LEFT JOIN public.riviera_jugadores rj ON rj.id = s.jugador_id
  LEFT JOIN public.coach_player_class_balances b ON b.relationship_id = s.relationship_id
  LEFT JOIN public.users u ON u.id = s.organizador_id
  LEFT JOIN public.organizador_game_modes ogm ON ogm.organizador_id = s.organizador_id
  WHERE s.coach_id = v_coach_id
    AND (p_organizador_id IS NULL OR s.organizador_id = p_organizador_id)
    AND (p_status_filter IS NULL OR s.status = p_status_filter)
    AND s.starts_at >= v_from
    AND s.starts_at <= v_to;

  RETURN jsonb_build_object(
    'ok', true,
    'sessions', v_sessions
  );
END;
$$;


ALTER FUNCTION "public"."fetch_coach_agenda"("p_organizador_id" "uuid", "p_status_filter" "text", "p_from_date" timestamp with time zone, "p_to_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_coach_removal_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_membership record;
  v_now timestamptz := now();
  v_pending_balance integer := 0;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  -- 1. Autorización administrativa
  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No tienes permisos para eliminar entrenadores de este club.'
    );
  END IF;

  -- 2. Localizar y bloquear la membresía
  SELECT id, status, organizador_id, coach_id
  INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id
  FOR UPDATE;

  -- 3. Idempotencia: si ya no existe, devolver éxito
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'message', 'El entrenador ya no está registrado en este club.'
    );
  END IF;

  -- 4. Exigir que la membresía esté previamente en estado 'REMOVED'
  IF v_membership.status <> 'REMOVED' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Solo se pueden eliminar definitivamente entrenadores dados de baja previamente (estado REMOVED). Realiza primero la baja del entrenador.'
    );
  END IF;

  -- 5. Comprobar si existen saldos activos pendientes
  SELECT COALESCE(SUM(balance_classes), 0)
  INTO v_pending_balance
  FROM public.coach_player_class_balances
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_coach_id;

  IF v_pending_balance > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El entrenador aún tiene ' || v_pending_balance || ' clases asignadas pendientes con alumnos. Reasigna los saldos a otro entrenador antes de eliminarlo definitivamente.'
    );
  END IF;

  -- 6. Registrar en la bitácora de auditoría inmutable
  INSERT INTO public.coach_club_membership_audit_log (
    membership_id,
    coach_id,
    organizador_id,
    action,
    performed_by,
    previous_status,
    new_status,
    details
  ) VALUES (
    NULL,
    p_coach_id,
    p_organizador_id,
    'FINALIZE_REMOVAL',
    v_caller,
    v_membership.status,
    'PURGED',
    jsonb_build_object(
      'motivo', NULLIF(trim(p_motivo), ''),
      'previous_membership_id', v_membership.id,
      'finalized_at', v_now
    )
  );

  -- 7. Finalizar cualquier relación restante en este club
  UPDATE public.coach_player_relationships
  SET
    status = 'ENDED',
    updated_at = v_now
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_coach_id;

  -- 8. Eliminar notas privadas del club sobre este coach
  DELETE FROM public.coach_club_private_notes
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_coach_id;

  -- 9. Eliminar la membresía del club
  DELETE FROM public.coach_club_memberships
  WHERE id = v_membership.id;

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'message', 'Entrenador eliminado definitivamente de tu club. Se ha conservado todo el historial de auditoría y registros deportivos.'
  );
END;
$$;


ALTER FUNCTION "public"."finalize_coach_removal_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_aplicar_jornada"("p_jornada_id" "uuid", "p_filas" "jsonb", "p_nota" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_liga uuid;
  v_estado text;
  v_liga_estado text;
  v_orden uuid[];
  v_rank jsonb;
BEGIN
  SELECT j.liga_id, j.estado, l.estado
    INTO v_liga, v_estado, v_liga_estado
  FROM public.liga_jornadas j
  JOIN public.ligas l ON l.id = j.liga_id
  WHERE j.id = p_jornada_id
  FOR UPDATE OF j;

  IF v_liga IS NULL OR NOT public.flex_league_can_write(v_liga) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para cerrar esta jornada.');
  END IF;
  IF v_liga_estado = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La temporada está cerrada. Reábrela antes de corregir.');
  END IF;
  IF v_estado = 'completed' AND EXISTS (
    SELECT 1 FROM public.liga_flex_posiciones WHERE jornada_id = p_jornada_id
  ) THEN
    RETURN jsonb_build_object('ok', true, 'idempotent', true);
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('flex-jornada'), hashtext(p_jornada_id::text));
  DROP TABLE IF EXISTS pg_temp.flex_score_override;

  SELECT COALESCE(array_agg((value->>'jugador_id')::uuid), ARRAY[]::uuid[])
    INTO v_orden
  FROM jsonb_array_elements(COALESCE(p_filas, '[]'::jsonb));

  v_rank := public.flex_rank_scores(p_jornada_id, NULLIF(v_orden, ARRAY[]::uuid[]));
  IF COALESCE((v_rank->>'ok')::boolean, false) IS NOT TRUE THEN
    RETURN v_rank;
  END IF;

  PERFORM public.flex_escribir_posiciones(p_jornada_id, v_rank->'rows');

  INSERT INTO public.liga_flex_auditoria (liga_id, jornada_id, actor_id, accion, detalle)
  VALUES (
    v_liga, p_jornada_id, auth.uid(), 'aplicar_jornada',
    jsonb_build_object('nota', NULLIF(btrim(COALESCE(p_nota, '')), ''), 'origen', 'servidor')
  );

  RETURN jsonb_build_object('ok', true, 'idempotent', false);
END;
$$;


ALTER FUNCTION "public"."flex_aplicar_jornada"("p_jornada_id" "uuid", "p_filas" "jsonb", "p_nota" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_cerrar_liga"("p_liga_id" "uuid", "p_orden" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_final uuid;
  v_max int;
  v_num int;
  v_planeadas int;
  v_total int;
  v_row record;
  v_prev jsonb;
  v_place int := 0;
  v_ids uuid[] := ARRAY[]::uuid[];
  v_campeon uuid;
  v_sub uuid;
  v_tercer uuid;
  v_existing public.liga_flex_honores%ROWTYPE;
BEGIN
  IF NOT public.flex_league_can_write(p_liga_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para cerrar esta liga.');
  END IF;

  SELECT h.* INTO v_existing FROM public.liga_flex_honores h WHERE h.liga_id = p_liga_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'campeon_id', v_existing.campeon_id,
      'subcampeon_id', v_existing.subcampeon_id,
      'tercer_id', v_existing.tercer_id
    );
  END IF;

  SELECT c.jornadas_planeadas INTO v_planeadas
  FROM public.liga_flex_config c WHERE c.liga_id = p_liga_id;
  SELECT COUNT(*), MAX(numero) INTO v_total, v_max
  FROM public.liga_jornadas WHERE liga_id = p_liga_id;

  IF COALESCE(v_planeadas, 0) <> 12 OR COALESCE(v_total, 0) <> 12 OR COALESCE(v_max, 0) <> 12 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La temporada oficial es de 12 jornadas. No se cierra una temporada incompleta.');
  END IF;
  IF EXISTS (
    SELECT 1 FROM generate_series(1, 12) n
    WHERE NOT EXISTS (
      SELECT 1 FROM public.liga_jornadas j
      WHERE j.liga_id = p_liga_id AND j.numero = n
    )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Falta una jornada del 1 al 12.');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.liga_jornadas j
    WHERE j.liga_id = p_liga_id
      AND (
        j.estado IS DISTINCT FROM 'completed'
        OR NOT EXISTS (
          SELECT 1 FROM public.liga_flex_posiciones p WHERE p.jornada_id = j.id
        )
        OR (
          SELECT COUNT(*) FROM public.liga_flex_posiciones p WHERE p.jornada_id = j.id
        ) IS DISTINCT FROM (
          SELECT COUNT(*) FROM public.liga_jornada_participantes part WHERE part.jornada_id = j.id
        )
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Termina las 12 jornadas y asigna sus puntos antes de cerrar la temporada.');
  END IF;

  SELECT j.id, j.numero INTO v_final, v_num
  FROM public.liga_jornadas j
  WHERE j.liga_id = p_liga_id AND j.numero = 12;

  UPDATE public.liga_jornada_flex
     SET es_final = (jornada_id = v_final), updated_at = now()
   WHERE liga_id = p_liga_id;
  UPDATE public.liga_flex_config
     SET jornada_final_id = v_final, updated_at = now()
   WHERE liga_id = p_liga_id;

  CREATE TEMP TABLE IF NOT EXISTS flex_board_close (
    jugador_id uuid PRIMARY KEY,
    puntos int NOT NULL,
    jj int NOT NULL,
    keys int[] NOT NULL,
    picked boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;
  DELETE FROM flex_board_close;

  INSERT INTO flex_board_close (jugador_id, puntos, jj, keys)
  SELECT
    p.jugador_id,
    SUM(p.puntos)::int,
    COUNT(*)::int,
    ARRAY[
      COUNT(*) FILTER (WHERE p.posicion = 1),
      COUNT(*) FILTER (WHERE p.posicion = 2),
      COUNT(*) FILTER (WHERE p.posicion = 3),
      COUNT(*) FILTER (WHERE p.posicion = 4),
      COUNT(*) FILTER (WHERE p.posicion = 5),
      COUNT(*) FILTER (WHERE p.posicion = 6),
      COUNT(*) FILTER (WHERE p.posicion = 7),
      COUNT(*) FILTER (WHERE p.posicion = 8),
      COUNT(*) FILTER (WHERE p.posicion = 9),
      COUNT(*) FILTER (WHERE p.posicion = 10),
      COUNT(*) FILTER (WHERE p.posicion = 11),
      COUNT(*) FILTER (WHERE p.posicion = 12),
      COUNT(*) FILTER (WHERE p.posicion = 13),
      COUNT(*) FILTER (WHERE p.posicion = 14),
      COUNT(*) FILTER (WHERE p.posicion = 15),
      COUNT(*) FILTER (WHERE p.posicion = 16)
    ]::int[]
  FROM public.liga_flex_posiciones p
  JOIN public.liga_jornadas j ON j.id = p.jornada_id
  WHERE j.liga_id = p_liga_id AND j.estado = 'completed'
  GROUP BY p.jugador_id;

  IF (SELECT COUNT(*) FROM flex_board_close) < 3 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Hacen falta al menos tres jugadores con puntos para el podio.');
  END IF;

  FOR v_place IN 1..3 LOOP
    SELECT b.jugador_id, b.puntos, b.jj, b.keys
      INTO v_row
    FROM flex_board_close b
    WHERE NOT b.picked
    ORDER BY b.puntos DESC, b.keys DESC, b.jj DESC
    LIMIT 1;

    SELECT COALESCE(jsonb_agg(b.jugador_id), '[]'::jsonb)
      INTO v_prev
    FROM flex_board_close b
    WHERE NOT b.picked
      AND b.puntos = v_row.puntos
      AND b.keys = v_row.keys
      AND b.jj = v_row.jj;

    IF jsonb_array_length(v_prev) > 1 THEN
      IF p_orden IS NULL OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(v_prev) t(id)
        WHERE array_position(p_orden, t.id::uuid) IS NULL
      ) THEN
        RETURN jsonb_build_object(
          'ok', false,
          'needs_resolution', true,
          'error', 'El podio sigue empatado. Ordena a esos jugadores antes de cerrar.',
          'tied', v_prev
        );
      END IF;
      SELECT t.id::uuid INTO v_campeon
      FROM jsonb_array_elements_text(v_prev) t(id)
      ORDER BY array_position(p_orden, t.id::uuid)
      LIMIT 1;
    ELSE
      v_campeon := v_row.jugador_id;
    END IF;

    v_ids := array_append(v_ids, v_campeon);
    UPDATE flex_board_close SET picked = true WHERE jugador_id = v_campeon;
  END LOOP;

  v_campeon := v_ids[1];
  v_sub := v_ids[2];
  v_tercer := v_ids[3];

  INSERT INTO public.liga_flex_honores (
    liga_id, campeon_id, subcampeon_id, tercer_id, jornada_final_id
  ) VALUES (
    p_liga_id, v_campeon, v_sub, v_tercer, v_final
  );

  UPDATE public.ligas SET estado = 'completed' WHERE id = p_liga_id;
  UPDATE public.liga_flex_config SET cerrado_at = now(), updated_at = now() WHERE liga_id = p_liga_id;

  INSERT INTO public.liga_flex_auditoria (liga_id, jornada_id, actor_id, accion, detalle)
  VALUES (
    p_liga_id, v_final, auth.uid(), 'cerrar_liga',
    jsonb_build_object('campeon_id', v_campeon, 'subcampeon_id', v_sub, 'tercer_id', v_tercer)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'campeon_id', v_campeon,
    'subcampeon_id', v_sub,
    'tercer_id', v_tercer
  );
END;
$$;


ALTER FUNCTION "public"."flex_cerrar_liga"("p_liga_id" "uuid", "p_orden" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_corregir_jornada"("p_jornada_id" "uuid", "p_marcadores" "jsonb", "p_motivo" "text", "p_orden" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_liga uuid;
  v_estado text;
  v_liga_estado text;
  v_rank jsonb;
  v_row jsonb;
BEGIN
  IF NULLIF(btrim(COALESCE(p_motivo, '')), '') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Escribe el motivo de la corrección.');
  END IF;

  SELECT j.liga_id, j.estado, l.estado
    INTO v_liga, v_estado, v_liga_estado
  FROM public.liga_jornadas j
  JOIN public.ligas l ON l.id = j.liga_id
  WHERE j.id = p_jornada_id
  FOR UPDATE OF j;

  IF v_liga IS NULL OR NOT public.flex_league_can_write(v_liga) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para corregir esta jornada.');
  END IF;
  IF v_liga_estado = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La temporada ya tiene campeón. Reábrela con motivo antes de corregir.');
  END IF;
  IF v_estado IS DISTINCT FROM 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La corrección es para una jornada ya finalizada. Mientras sigue abierta, edita el marcador directo.');
  END IF;
  IF jsonb_typeof(p_marcadores) IS DISTINCT FROM 'array' OR jsonb_array_length(p_marcadores) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Faltan los marcadores corregidos.');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('flex-jornada'), hashtext(p_jornada_id::text));

  DROP TABLE IF EXISTS pg_temp.flex_score_override;
  CREATE TEMP TABLE flex_score_override (
    partido_id uuid PRIMARY KEY,
    score_a integer,
    score_b integer
  ) ON COMMIT DROP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_marcadores) LOOP
    IF (v_row->>'score_a')::int < 0 OR (v_row->>'score_a')::int > 99
       OR (v_row->>'score_b')::int < 0 OR (v_row->>'score_b')::int > 99 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'El marcador tiene que ser un entero entre 0 y 99.');
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.liga_partidos
      WHERE id = (v_row->>'partido_id')::uuid AND jornada_id = p_jornada_id
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Un marcador no pertenece a esta jornada.');
    END IF;
    INSERT INTO flex_score_override (partido_id, score_a, score_b)
    VALUES ((v_row->>'partido_id')::uuid, (v_row->>'score_a')::int, (v_row->>'score_b')::int);
  END LOOP;

  v_rank := public.flex_rank_scores(p_jornada_id, p_orden);
  IF COALESCE((v_rank->>'ok')::boolean, false) IS NOT TRUE THEN
    DROP TABLE IF EXISTS pg_temp.flex_score_override;
    RETURN v_rank;
  END IF;

  UPDATE public.liga_partidos p
     SET score_pareja1 = o.score_a,
         score_pareja2 = o.score_b,
         estado = 'completed'
    FROM flex_score_override o
   WHERE p.id = o.partido_id;

  PERFORM public.flex_escribir_posiciones(p_jornada_id, v_rank->'rows');

  INSERT INTO public.liga_flex_auditoria (liga_id, jornada_id, actor_id, accion, detalle)
  VALUES (
    v_liga, p_jornada_id, auth.uid(), 'corregir_jornada',
    jsonb_build_object('motivo', btrim(p_motivo))
  );

  DROP TABLE IF EXISTS pg_temp.flex_score_override;
  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."flex_corregir_jornada"("p_jornada_id" "uuid", "p_marcadores" "jsonb", "p_motivo" "text", "p_orden" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_escribir_posiciones"("p_jornada_id" "uuid", "p_rows" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row jsonb;
  v_liga uuid;
BEGIN
  SELECT liga_id INTO v_liga FROM public.liga_jornadas WHERE id = p_jornada_id;
  DELETE FROM public.liga_flex_posiciones WHERE jornada_id = p_jornada_id;
  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    INSERT INTO public.liga_flex_posiciones (
      jornada_id, jugador_id, posicion, puntos, partidos,
      games_favor, games_contra, promedio_gf, promedio_dif
    ) VALUES (
      p_jornada_id,
      (v_row->>'jugador_id')::uuid,
      (v_row->>'posicion')::int,
      (v_row->>'puntos')::int,
      (v_row->>'partidos')::int,
      (v_row->>'games_favor')::int,
      (v_row->>'games_contra')::int,
      (v_row->>'promedio_gf')::numeric,
      (v_row->>'promedio_dif')::numeric
    );
  END LOOP;
  UPDATE public.liga_jornadas
     SET estado = 'completed', puntos_aplicados = true
   WHERE id = p_jornada_id;
  UPDATE public.ligas
     SET estado = 'in_progress'
   WHERE id = v_liga AND estado = 'upcoming';
  PERFORM public.flex_recalcular_puntos_inscripcion(v_liga);
END;
$$;


ALTER FUNCTION "public"."flex_escribir_posiciones"("p_jornada_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_guardar_marcador"("p_partido_id" "uuid", "p_score_a" integer, "p_score_b" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jornada uuid;
  v_liga uuid;
  v_estado text;
  v_liga_estado text;
BEGIN
  SELECT p.jornada_id, j.liga_id, j.estado, l.estado
    INTO v_jornada, v_liga, v_estado, v_liga_estado
  FROM public.liga_partidos p
  JOIN public.liga_jornadas j ON j.id = p.jornada_id
  JOIN public.ligas l ON l.id = j.liga_id
  WHERE p.id = p_partido_id
  FOR UPDATE OF j;

  IF v_liga IS NULL OR NOT public.flex_league_can_write(v_liga) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para este marcador.');
  END IF;
  IF v_liga_estado = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La temporada está cerrada. Reábrela para una corrección.');
  END IF;
  IF v_estado = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La jornada ya tiene puntos oficiales. Usa la corrección con motivo.');
  END IF;
  IF p_score_a IS NULL OR p_score_b IS NULL OR p_score_a < 0 OR p_score_b < 0 OR p_score_a > 99 OR p_score_b > 99 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El marcador tiene que ser un entero entre 0 y 99.');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('flex-jornada'), hashtext(v_jornada::text));

  UPDATE public.liga_partidos
     SET score_pareja1 = p_score_a,
         score_pareja2 = p_score_b,
         estado = 'completed'
   WHERE id = p_partido_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."flex_guardar_marcador"("p_partido_id" "uuid", "p_score_a" integer, "p_score_b" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_guardar_programacion"("p_jornada_id" "uuid", "p_seed" bigint, "p_partidos" "jsonb", "p_calidad" "jsonb", "p_advertencia" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_liga uuid;
  v_row jsonb;
  v_ronda int;
  v_cancha int;
  v_ids uuid[];
  v_p1 uuid;
  v_p2 uuid;
  v_n int;
  v_ronda_check int;
  v_cubiertos int;
  v_partidos_ronda int;
BEGIN
  SELECT j.liga_id INTO v_liga FROM public.liga_jornadas j WHERE j.id = p_jornada_id;
  IF v_liga IS NULL OR NOT public.flex_league_can_write(v_liga) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para esta jornada.');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.liga_partidos
    WHERE jornada_id = p_jornada_id
      AND (score_pareja1 IS NOT NULL OR score_pareja2 IS NOT NULL)
  ) OR EXISTS (
    SELECT 1 FROM public.liga_jornadas
    WHERE id = p_jornada_id AND estado <> 'upcoming'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La jornada ya tiene resultados o empezó. No se reescribe el calendario.');
  END IF;
  IF jsonb_typeof(p_partidos) IS DISTINCT FROM 'array' OR jsonb_array_length(p_partidos) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No hay partidos para confirmar.');
  END IF;

  SELECT COUNT(*) INTO v_n
  FROM public.liga_jornada_participantes
  WHERE jornada_id = p_jornada_id;
  IF v_n NOT IN (12, 16) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'La jornada oficial se juega con 12 o 16 jugadores. Ajusta la lista; no se retira a nadie.'
    );
  END IF;

  DELETE FROM public.liga_partidos WHERE jornada_id = p_jornada_id;
  DELETE FROM public.liga_jornada_parejas WHERE jornada_id = p_jornada_id;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_partidos)
  LOOP
    v_ronda := (v_row->>'ronda')::int;
    v_cancha := (v_row->>'cancha')::int;
    v_ids := ARRAY[
      (v_row->>'a1')::uuid,
      (v_row->>'a2')::uuid,
      (v_row->>'b1')::uuid,
      (v_row->>'b2')::uuid
    ];
    IF v_ids[1] IS NULL OR v_ids[2] IS NULL OR v_ids[3] IS NULL OR v_ids[4] IS NULL
       OR (SELECT COUNT(DISTINCT x) FROM unnest(v_ids) x) <> 4 THEN
      RAISE EXCEPTION 'Partido inválido en la ronda %', v_ronda;
    END IF;
    IF v_cancha < 1 OR v_cancha > (v_n / 4) THEN
      RAISE EXCEPTION 'La cancha % no se usa: con % jugadores bastan % canchas.', v_cancha, v_n, v_n / 4;
    END IF;
    IF EXISTS (
      SELECT 1 FROM unnest(v_ids) x
      WHERE NOT EXISTS (
        SELECT 1 FROM public.liga_jornada_participantes p
        WHERE p.jornada_id = p_jornada_id AND p.jugador_id = x
      )
    ) THEN
      RAISE EXCEPTION 'Un partido incluye a alguien que no está en la jornada.';
    END IF;

    INSERT INTO public.liga_jornada_parejas (jornada_id, jugador1_id, jugador2_id)
    VALUES (p_jornada_id, v_ids[1], v_ids[2])
    RETURNING id INTO v_p1;
    INSERT INTO public.liga_jornada_parejas (jornada_id, jugador1_id, jugador2_id)
    VALUES (p_jornada_id, v_ids[3], v_ids[4])
    RETURNING id INTO v_p2;
    INSERT INTO public.liga_partidos (
      jornada_id, pareja1_id, pareja2_id, cancha, ronda, estado
    ) VALUES (
      p_jornada_id, v_p1, v_p2, v_cancha, v_ronda, 'upcoming'
    );
  END LOOP;

  FOR v_ronda_check IN
    SELECT DISTINCT ronda FROM public.liga_partidos WHERE jornada_id = p_jornada_id
  LOOP
    SELECT COUNT(*) INTO v_partidos_ronda
    FROM public.liga_partidos
    WHERE jornada_id = p_jornada_id AND ronda = v_ronda_check;

    SELECT COUNT(*) INTO v_cubiertos
    FROM (
      SELECT par.jugador1_id AS jugador_id
      FROM public.liga_partidos p
      JOIN public.liga_jornada_parejas par ON par.id IN (p.pareja1_id, p.pareja2_id)
      WHERE p.jornada_id = p_jornada_id AND p.ronda = v_ronda_check
      UNION
      SELECT par.jugador2_id
      FROM public.liga_partidos p
      JOIN public.liga_jornada_parejas par ON par.id IN (p.pareja1_id, p.pareja2_id)
      WHERE p.jornada_id = p_jornada_id AND p.ronda = v_ronda_check
    ) jugadores;
    IF v_partidos_ronda IS DISTINCT FROM (v_n / 4) OR v_cubiertos IS DISTINCT FROM v_n THEN
      RAISE EXCEPTION 'La ronda % no tiene a todos los jugadores exactamente una vez.', v_ronda_check;
    END IF;
  END LOOP;

  UPDATE public.liga_jornada_flex
     SET seed = p_seed,
         programacion_estado = 'confirmada',
         calidad = p_calidad,
         advertencia = NULLIF(btrim(COALESCE(p_advertencia, '')), ''),
         canchas = v_n / 4,
         updated_at = now()
   WHERE jornada_id = p_jornada_id;

  INSERT INTO public.liga_flex_auditoria (liga_id, jornada_id, actor_id, accion, detalle)
  VALUES (
    v_liga,
    p_jornada_id,
    auth.uid(),
    'confirmar_programacion',
    jsonb_build_object('seed', p_seed, 'algoritmo', p_calidad->>'algorithmVersion', 'jugadores', v_n)
  );

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."flex_guardar_programacion"("p_jornada_id" "uuid", "p_seed" bigint, "p_partidos" "jsonb", "p_calidad" "jsonb", "p_advertencia" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_league_can_write"("p_liga_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    auth.uid() IS NOT NULL
    AND COALESCE(public.is_restricted_sub_account(auth.uid()), false) = false
    AND EXISTS (
      SELECT 1
      FROM public.ligas l
      WHERE l.id = p_liga_id
        AND l.modalidad = 'flex_league'
        AND (l.organizador_id = auth.uid() OR COALESCE(public.is_master_admin(), false))
    );
$$;


ALTER FUNCTION "public"."flex_league_can_write"("p_liga_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_programar_jornada"("p_jornada_id" "uuid", "p_fecha" "date", "p_inicio" time without time zone, "p_fin" time without time zone, "p_canchas" integer, "p_rondas" integer, "p_duracion" integer, "p_descanso" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_liga uuid;
  v_estado text;
BEGIN
  SELECT j.liga_id, j.estado INTO v_liga, v_estado
  FROM public.liga_jornadas j WHERE j.id = p_jornada_id;
  IF v_liga IS NULL OR NOT public.flex_league_can_write(v_liga) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para programar esta jornada.');
  END IF;
  IF v_estado = 'completed' OR EXISTS (
    SELECT 1 FROM public.ligas WHERE id = v_liga AND estado = 'completed'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se reprograma una jornada ya finalizada.');
  END IF;
  IF p_inicio IS NOT NULL AND p_fin IS NOT NULL AND p_fin <= p_inicio THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La hora de fin tiene que ser posterior a la de inicio.');
  END IF;
  IF p_canchas < 1 OR p_canchas > 12 OR p_rondas < 1 OR p_rondas > 24 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Canchas o rondas fuera del rango de la jornada.');
  END IF;

  UPDATE public.liga_jornadas SET fecha = p_fecha WHERE id = p_jornada_id;
  UPDATE public.liga_jornada_flex
     SET hora_inicio = p_inicio,
         hora_fin = p_fin,
         canchas = p_canchas,
         rondas = p_rondas,
         duracion_ronda_min = p_duracion,
         descanso_min = p_descanso,
         updated_at = now()
   WHERE jornada_id = p_jornada_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."flex_programar_jornada"("p_jornada_id" "uuid", "p_fecha" "date", "p_inicio" time without time zone, "p_fin" time without time zone, "p_canchas" integer, "p_rondas" integer, "p_duracion" integer, "p_descanso" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_puntos_por_posicion"("p_posicion" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_posicion
    WHEN 1 THEN 100 WHEN 2 THEN 90 WHEN 3 THEN 80 WHEN 4 THEN 70
    WHEN 5 THEN 65 WHEN 6 THEN 60 WHEN 7 THEN 55 WHEN 8 THEN 50
    WHEN 9 THEN 45 WHEN 10 THEN 40 WHEN 11 THEN 35 WHEN 12 THEN 30
    WHEN 13 THEN 25 WHEN 14 THEN 20 WHEN 15 THEN 15 WHEN 16 THEN 10
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."flex_puntos_por_posicion"("p_posicion" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_rank_scores"("p_jornada_id" "uuid", "p_orden" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_best uuid;
  v_a record;
  v_b record;
  v_better boolean;
  v_group uuid[];
  v_member uuid;
  v_place int := 0;
  v_rows jsonb := '[]'::jsonb;
  v_ties jsonb := '[]'::jsonb;
  v_gf int;
  v_gc int;
  v_pts int;
  v_partidos int;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS flex_score_override (
    partido_id uuid PRIMARY KEY,
    score_a integer,
    score_b integer
  ) ON COMMIT DROP;

  CREATE TEMP TABLE IF NOT EXISTS flex_rank_acc (
    jugador_id uuid PRIMARY KEY,
    gf integer NOT NULL,
    gc integer NOT NULL,
    partidos integer NOT NULL,
    placed boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS flex_rank_h2h (
    a uuid NOT NULL,
    b uuid NOT NULL,
    gf integer NOT NULL,
    gc integer NOT NULL,
    PRIMARY KEY (a, b)
  ) ON COMMIT DROP;
  DELETE FROM flex_rank_acc;
  DELETE FROM flex_rank_h2h;

  INSERT INTO flex_rank_acc (jugador_id, gf, gc, partidos)
  SELECT jugador_id, 0, 0, 0
  FROM public.liga_jornada_participantes
  WHERE jornada_id = p_jornada_id;

  IF (SELECT COUNT(*) FROM flex_rank_acc) NOT IN (12, 16) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La jornada oficial se cierra con 12 o 16 jugadores.');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.liga_partidos p
    LEFT JOIN flex_score_override o ON o.partido_id = p.id
    WHERE p.jornada_id = p_jornada_id
      AND (
        COALESCE(o.score_a, p.score_pareja1) IS NULL
        OR COALESCE(o.score_b, p.score_pareja2) IS NULL
        OR COALESCE(o.score_a, p.score_pareja1) < 0
        OR COALESCE(o.score_b, p.score_pareja2) < 0
        OR COALESCE(o.score_a, p.score_pareja1) > 99
        OR COALESCE(o.score_b, p.score_pareja2) > 99
      )
  ) OR NOT EXISTS (
    SELECT 1 FROM public.liga_partidos WHERE jornada_id = p_jornada_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Completa marcadores válidos, de 0 a 99, antes de asignar puntos.');
  END IF;

  FOR v_a IN
    SELECT
      p.id,
      par1.jugador1_id AS a1,
      par1.jugador2_id AS a2,
      par2.jugador1_id AS b1,
      par2.jugador2_id AS b2,
      COALESCE(o.score_a, p.score_pareja1) AS score_a,
      COALESCE(o.score_b, p.score_pareja2) AS score_b
    FROM public.liga_partidos p
    JOIN public.liga_jornada_parejas par1 ON par1.id = p.pareja1_id
    JOIN public.liga_jornada_parejas par2 ON par2.id = p.pareja2_id
    LEFT JOIN flex_score_override o ON o.partido_id = p.id
    WHERE p.jornada_id = p_jornada_id
  LOOP
    IF (SELECT COUNT(DISTINCT x) FROM unnest(ARRAY[v_a.a1, v_a.a2, v_a.b1, v_a.b2]) x) <> 4 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Hay un partido sin cuatro jugadores distintos.');
    END IF;
    FOREACH v_id IN ARRAY (ARRAY[v_a.a1, v_a.a2, v_a.b1, v_a.b2])
    LOOP
      IF NOT EXISTS (SELECT 1 FROM flex_rank_acc WHERE jugador_id = v_id) THEN
        RETURN jsonb_build_object('ok', false, 'error', 'Un partido incluye a alguien que no está en la jornada.');
      END IF;
    END LOOP;
    UPDATE flex_rank_acc
       SET gf = gf + v_a.score_a, gc = gc + v_a.score_b, partidos = partidos + 1
     WHERE jugador_id IN (v_a.a1, v_a.a2);
    UPDATE flex_rank_acc
       SET gf = gf + v_a.score_b, gc = gc + v_a.score_a, partidos = partidos + 1
     WHERE jugador_id IN (v_a.b1, v_a.b2);
    FOREACH v_id IN ARRAY (ARRAY[v_a.a1, v_a.a2])
    LOOP
      INSERT INTO flex_rank_h2h (a, b, gf, gc)
      SELECT v_id, rival, v_a.score_a, v_a.score_b
      FROM unnest(ARRAY[v_a.b1, v_a.b2]) rival
      ON CONFLICT (a, b) DO UPDATE
        SET gf = flex_rank_h2h.gf + EXCLUDED.gf,
            gc = flex_rank_h2h.gc + EXCLUDED.gc;
    END LOOP;
    FOREACH v_id IN ARRAY (ARRAY[v_a.b1, v_a.b2])
    LOOP
      INSERT INTO flex_rank_h2h (a, b, gf, gc)
      SELECT v_id, rival, v_a.score_b, v_a.score_a
      FROM unnest(ARRAY[v_a.a1, v_a.a2]) rival
      ON CONFLICT (a, b) DO UPDATE
        SET gf = flex_rank_h2h.gf + EXCLUDED.gf,
            gc = flex_rank_h2h.gc + EXCLUDED.gc;
    END LOOP;
  END LOOP;

  IF EXISTS (SELECT 1 FROM flex_rank_acc WHERE partidos < 1) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Hay un participante sin partidos. No se asignan puntos ficticios.');
  END IF;

  WHILE EXISTS (SELECT 1 FROM flex_rank_acc WHERE NOT placed) LOOP
    v_best := NULL;
    FOR v_id IN SELECT jugador_id FROM flex_rank_acc WHERE NOT placed LOOP
      IF v_best IS NULL THEN
        v_best := v_id;
      ELSE
        SELECT * INTO v_a FROM flex_rank_acc WHERE jugador_id = v_id;
        SELECT * INTO v_b FROM flex_rank_acc WHERE jugador_id = v_best;
        v_better := false;
        IF v_a.gf <> v_b.gf THEN
          v_better := v_a.gf > v_b.gf;
        ELSIF (v_a.gf - v_a.gc) <> (v_b.gf - v_b.gc) THEN
          v_better := (v_a.gf - v_a.gc) > (v_b.gf - v_b.gc);
        ELSE
          SELECT COALESCE(SUM(gf), 0), COALESCE(SUM(gc), 0)
            INTO v_gf, v_gc
          FROM flex_rank_h2h
          WHERE a = v_id AND b = v_best;
          IF v_gf + v_gc > 0 THEN
            v_better := (v_gf - v_gc) > 0;
          END IF;
        END IF;
        IF v_better THEN
          v_best := v_id;
        END IF;
      END IF;
    END LOOP;

    v_group := ARRAY[]::uuid[];
    FOR v_id IN SELECT jugador_id FROM flex_rank_acc WHERE NOT placed LOOP
      SELECT * INTO v_a FROM flex_rank_acc WHERE jugador_id = v_id;
      SELECT * INTO v_b FROM flex_rank_acc WHERE jugador_id = v_best;
      v_better := false;
      IF v_a.gf <> v_b.gf OR (v_a.gf - v_a.gc) <> (v_b.gf - v_b.gc) THEN
        v_better := true;
      ELSE
        SELECT COALESCE(SUM(gf), 0), COALESCE(SUM(gc), 0)
          INTO v_gf, v_gc
        FROM flex_rank_h2h
        WHERE (a = v_id AND b = v_best) OR (a = v_best AND b = v_id);
        IF v_gf + v_gc > 0 THEN
          SELECT COALESCE(SUM(gf - gc), 0) INTO v_gf
          FROM flex_rank_h2h WHERE a = v_id AND b = v_best;
          SELECT COALESCE(SUM(gf - gc), 0) INTO v_gc
          FROM flex_rank_h2h WHERE a = v_best AND b = v_id;
          v_better := v_gf <> v_gc;
        END IF;
      END IF;
      IF NOT v_better THEN
        v_group := array_append(v_group, v_id);
      END IF;
    END LOOP;

    IF COALESCE(array_length(v_group, 1), 0) > 1 THEN
      IF p_orden IS NULL OR EXISTS (
        SELECT 1 FROM unnest(v_group) g(id)
        WHERE array_position(p_orden, g.id) IS NULL
      ) THEN
        v_ties := v_ties || jsonb_build_array(
          (SELECT COALESCE(jsonb_agg(g.id ORDER BY g.id::text), '[]'::jsonb) FROM unnest(v_group) g(id))
        );
        RETURN jsonb_build_object(
          'ok', false,
          'needs_resolution', true,
          'error', 'Hay un empate que cambia los puntos. Define el orden de esos jugadores antes de cerrar la jornada.',
          'ties', v_ties
        );
      END IF;
      SELECT COALESCE(array_agg(g.id ORDER BY array_position(p_orden, g.id)), ARRAY[]::uuid[])
        INTO v_group
      FROM unnest(v_group) g(id);
    END IF;

    FOREACH v_member IN ARRAY v_group LOOP
      v_place := v_place + 1;
      v_pts := public.flex_puntos_por_posicion(v_place);
      SELECT gf, gc, partidos INTO v_gf, v_gc, v_partidos
      FROM flex_rank_acc WHERE jugador_id = v_member;
      v_rows := v_rows || jsonb_build_array(jsonb_build_object(
        'jugador_id', v_member,
        'posicion', v_place,
        'puntos', v_pts,
        'partidos', v_partidos,
        'games_favor', v_gf,
        'games_contra', v_gc,
        'promedio_gf', ROUND(v_gf::numeric / v_partidos, 4),
        'promedio_dif', ROUND((v_gf - v_gc)::numeric / v_partidos, 4)
      ));
      UPDATE flex_rank_acc SET placed = true WHERE jugador_id = v_member;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'rows', v_rows);
END;
$$;


ALTER FUNCTION "public"."flex_rank_scores"("p_jornada_id" "uuid", "p_orden" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_reabrir_liga"("p_liga_id" "uuid", "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.flex_league_can_write(p_liga_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para reabrir esta liga.');
  END IF;
  IF NULLIF(btrim(COALESCE(p_motivo, '')), '') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Escribe el motivo de la reapertura.');
  END IF;
  DELETE FROM public.liga_flex_honores WHERE liga_id = p_liga_id;
  UPDATE public.liga_flex_config
     SET cerrado_at = NULL, updated_at = now()
   WHERE liga_id = p_liga_id;
  UPDATE public.ligas SET estado = 'in_progress' WHERE id = p_liga_id;
  INSERT INTO public.liga_flex_auditoria (liga_id, actor_id, accion, detalle)
  VALUES (p_liga_id, auth.uid(), 'reabrir_liga', jsonb_build_object('motivo', btrim(p_motivo)));
  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."flex_reabrir_liga"("p_liga_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_recalcular_puntos_inscripcion"("p_liga_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.liga_inscripciones i
     SET puntos = COALESCE((
       SELECT SUM(p.puntos)::int
       FROM public.liga_flex_posiciones p
       JOIN public.liga_jornadas j ON j.id = p.jornada_id
       WHERE j.liga_id = p_liga_id
         AND j.estado = 'completed'
         AND p.jugador_id = i.jugador_id
     ), 0)
   WHERE i.liga_id = p_liga_id;
END;
$$;


ALTER FUNCTION "public"."flex_recalcular_puntos_inscripcion"("p_liga_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_set_participantes"("p_jornada_id" "uuid", "p_jugadores" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_liga uuid;
  v_estado text;
  v_org uuid;
  v_max int;
  v_id uuid;
BEGIN
  SELECT j.liga_id, j.estado, l.organizador_id
    INTO v_liga, v_estado, v_org
  FROM public.liga_jornadas j
  JOIN public.ligas l ON l.id = j.liga_id
  WHERE j.id = p_jornada_id;
  IF v_liga IS NULL OR NOT public.flex_league_can_write(v_liga) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso para esta jornada.');
  END IF;
  IF v_estado <> 'upcoming' OR EXISTS (
    SELECT 1 FROM public.liga_partidos
    WHERE jornada_id = p_jornada_id
      AND (score_pareja1 IS NOT NULL OR score_pareja2 IS NOT NULL)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se cambia el roster de una jornada con resultados.');
  END IF;

  SELECT COALESCE(jugadores_max, 16) INTO v_max
  FROM public.liga_flex_config WHERE liga_id = v_liga;
  IF COALESCE(array_length(p_jugadores, 1), 0) > COALESCE(v_max, 16) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Hay más jugadores que el máximo de la jornada.');
  END IF;
  IF (
    SELECT COUNT(DISTINCT x) FROM unnest(COALESCE(p_jugadores, ARRAY[]::uuid[])) x
  ) IS DISTINCT FROM COALESCE(array_length(p_jugadores, 1), 0) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Un jugador está repetido en la jornada.');
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_jugadores, ARRAY[]::uuid[])) x(id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.liga_jugadores lj
      WHERE lj.id = x.id
        AND lj.organizador_id IS NOT DISTINCT FROM v_org
    )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Un jugador no pertenece a este club.');
  END IF;

  DELETE FROM public.liga_partidos WHERE jornada_id = p_jornada_id;
  DELETE FROM public.liga_jornada_parejas WHERE jornada_id = p_jornada_id;
  DELETE FROM public.liga_jornada_participantes WHERE jornada_id = p_jornada_id;

  FOREACH v_id IN ARRAY COALESCE(p_jugadores, ARRAY[]::uuid[])
  LOOP
    INSERT INTO public.liga_jornada_participantes (jornada_id, jugador_id)
    VALUES (p_jornada_id, v_id);
    INSERT INTO public.liga_inscripciones (liga_id, jugador_id, puntos)
    SELECT v_liga, v_id, 0
    WHERE NOT EXISTS (
      SELECT 1 FROM public.liga_inscripciones
      WHERE liga_id = v_liga AND jugador_id = v_id
    );
  END LOOP;

  UPDATE public.liga_jornada_flex
     SET programacion_estado = 'vacia',
         seed = NULL,
         calidad = NULL,
         advertencia = NULL,
         updated_at = now()
   WHERE jornada_id = p_jornada_id;

  RETURN jsonb_build_object('ok', true, 'participantes', COALESCE(array_length(p_jugadores, 1), 0));
END;
$$;


ALTER FUNCTION "public"."flex_set_participantes"("p_jornada_id" "uuid", "p_jugadores" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_club_coach_detail"("p_organizador_id" "uuid", "p_coach_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_coach record;
  v_membership record;
  v_private_notes record;
  v_club record;
  v_students jsonb;
  v_sessions jsonb;
  v_ledger jsonb;
  v_audit jsonb;
  v_total_assigned integer := 0;
  v_total_given integer := 0;
  v_current_balance integer := 0;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes permisos para consultar la actividad de este club.');
  END IF;

  -- 1. Consultar perfil global del coach
  SELECT
    c.id, c.coach_code, c.nombre, c.foto_url, c.bio, c.filosofia,
    c.especialidades, c.fuerzas, c.certificaciones, c.experiencia,
    c.created_at, u.email
  INTO v_coach
  FROM public.riviera_coaches c
  LEFT JOIN auth.users u ON u.id = c.auth_user_id
  WHERE c.id = p_coach_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Coach no encontrado.');
  END IF;

  -- 2. Consultar membresía del coach en este club
  SELECT
    m.id, m.status, m.invited_at, m.activated_at, m.deactivated_at,
    m.cancelled_at, m.archived_at, m.removed_at, m.removal_reason,
    m.club_fuerzas, m.club_especialidades, m.last_edited_at, m.created_at
  INTO v_membership
  FROM public.coach_club_memberships m
  WHERE m.coach_id = p_coach_id AND m.organizador_id = p_organizador_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El coach no tiene registro de membresía en este club.');
  END IF;

  -- 3. Consultar notas privadas aisladas (exclusivas del club)
  SELECT club_notas, club_disponibilidad
  INTO v_private_notes
  FROM public.coach_club_private_notes
  WHERE organizador_id = p_organizador_id AND coach_id = p_coach_id;

  -- 4. Consultar datos del club
  SELECT u.id, COALESCE(u.name, ogm.branding_key, 'Club Riviera') as nombre, ogm.branding_key
  INTO v_club
  FROM public.users u
  LEFT JOIN public.organizador_game_modes ogm ON ogm.organizador_id = u.id
  WHERE u.id = p_organizador_id;

  -- 5. Consultar alumnos vinculados en este club
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'relationship_id', r.id,
      'jugador_id', r.jugador_id,
      'nombre', rj.nombre,
      'foto_url', rj.foto_url,
      'categoria', rj.categoria,
      'rama', rj.genero,
      'genero', rj.genero,
      'riviera_id', COALESCE(
        (SELECT i.riviera_id FROM public.riviera_official_player_identity i WHERE i.canonical_riviera_jugador_id = r.jugador_id LIMIT 1),
        ''
      ),
      'is_primary', r.is_primary,
      'status', r.status,
      'started_at', r.started_at,
      'balance_classes', COALESCE(b.balance_classes, 0),
      'total_classes_given', COALESCE(b.total_classes_given, 0),
      'updated_at', b.updated_at
    ) ORDER BY r.status ASC, r.created_at DESC
  ), '[]'::jsonb)
  INTO v_students
  FROM public.coach_player_relationships r
  JOIN public.riviera_jugadores rj ON rj.id = r.jugador_id
  LEFT JOIN public.coach_player_class_balances b ON b.relationship_id = r.id
  WHERE r.coach_id = p_coach_id AND r.organizador_id = p_organizador_id;

  -- 6. Sesiones impartidas por este coach en este club con detalle de seguimiento
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'relationship_id', s.relationship_id,
      'jugador_nombre', COALESCE(rj.nombre, 'Alumno'),
      'starts_at', s.starts_at,
      'ends_at', s.ends_at,
      'duration_minutes', s.duration_minutes,
      'focus', s.focus,
      'worked_on', s.worked_on,
      'notes_summary', s.notes_summary,
      'improvements', s.improvements,
      'next_goals', s.next_goals,
      'motivational_message', s.motivational_message,
      'status', s.status,
      'created_at', s.created_at
    ) ORDER BY s.starts_at DESC
  ), '[]'::jsonb)
  INTO v_sessions
  FROM public.coach_sessions s
  LEFT JOIN public.coach_player_relationships r ON r.id = s.relationship_id
  LEFT JOIN public.riviera_jugadores rj ON rj.id = r.jugador_id
  WHERE s.coach_id = p_coach_id AND s.organizador_id = p_organizador_id;

  -- 7. Historial de movimientos (Ledger de clases en este club)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', l.id,
      'relationship_id', l.relationship_id,
      'jugador_id', l.jugador_id,
      'jugador_nombre', COALESCE(rj.nombre, 'Alumno'),
      'delta', l.delta,
      'tipo', l.tipo,
      'notas', l.notas,
      'recorded_by', l.recorded_by,
      'created_at', l.created_at
    ) ORDER BY l.created_at DESC
  ), '[]'::jsonb)
  INTO v_ledger
  FROM public.coach_class_ledger l
  LEFT JOIN public.riviera_jugadores rj ON rj.id = l.jugador_id
  WHERE l.coach_id = p_coach_id AND l.organizador_id = p_organizador_id;

  -- 8. Bitácora de auditoría confidencial del club
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', a.id,
      'action', a.action,
      'previous_status', a.previous_status,
      'new_status', a.new_status,
      'details', a.details,
      'created_at', a.created_at
    ) ORDER BY a.created_at DESC
  ), '[]'::jsonb)
  INTO v_audit
  FROM public.coach_club_membership_audit_log a
  WHERE a.coach_id = p_coach_id AND a.organizador_id = p_organizador_id;

  -- 9. Métricas agregadas
  SELECT
    COALESCE(SUM(CASE WHEN delta > 0 THEN delta ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN delta < 0 THEN ABS(delta) ELSE 0 END), 0)
  INTO v_total_assigned, v_total_given
  FROM public.coach_class_ledger
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id;

  SELECT COALESCE(SUM(balance_classes), 0)
  INTO v_current_balance
  FROM public.coach_player_class_balances
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id;

  RETURN jsonb_build_object(
    'ok', true,
    'coach', jsonb_build_object(
      'id', v_coach.id,
      'coach_code', v_coach.coach_code,
      'nombre', v_coach.nombre,
      'email', v_coach.email,
      'foto_url', v_coach.foto_url,
      'bio', v_coach.bio,
      'filosofia', v_coach.filosofia,
      'especialidades', v_coach.especialidades,
      'fuerzas', v_coach.fuerzas,
      'certificaciones', v_coach.certificaciones,
      'experiencia', v_coach.experiencia,
      'created_at', v_coach.created_at
    ),
    'membership', jsonb_build_object(
      'id', v_membership.id,
      'status', v_membership.status,
      'invited_at', v_membership.invited_at,
      'activated_at', v_membership.activated_at,
      'deactivated_at', v_membership.deactivated_at,
      'cancelled_at', v_membership.cancelled_at,
      'archived_at', v_membership.archived_at,
      'removed_at', v_membership.removed_at,
      'removal_reason', v_membership.removal_reason,
      'club_fuerzas', v_membership.club_fuerzas,
      'club_especialidades', v_membership.club_especialidades,
      'club_notas', v_private_notes.club_notas,
      'club_disponibilidad', v_private_notes.club_disponibilidad,
      'last_edited_at', v_membership.last_edited_at,
      'created_at', v_membership.created_at
    ),
    'club', jsonb_build_object(
      'id', v_club.id,
      'nombre', v_club.nombre,
      'branding_key', v_club.branding_key
    ),
    'students', v_students,
    'sessions', v_sessions,
    'ledger', v_ledger,
    'audit_log', v_audit,
    'stats', jsonb_build_object(
      'total_students', jsonb_array_length(v_students),
      'active_students', (
        SELECT COUNT(*) FROM public.coach_player_relationships
        WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id AND status = 'ACTIVE'
      ),
      'total_classes_assigned', v_total_assigned,
      'total_classes_given', v_total_given,
      'current_balance', v_current_balance
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_club_coach_detail"("p_organizador_id" "uuid", "p_coach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_club_student_access_status"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_authorized boolean;
  v_has_relationship boolean;
  v_link record;
  v_invitation record;
  v_jugador record;
  v_has_password boolean := false;
  v_auth_email text;
  v_confirmed_at timestamptz;
  v_activated_at timestamptz;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  v_is_authorized := public.is_master_admin() OR (p_organizador_id = v_caller);
  IF NOT v_is_authorized THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autorizado para consultar este club');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.coach_player_relationships
    WHERE organizador_id = p_organizador_id
      AND jugador_id = p_jugador_id
      AND status IN ('ACTIVE', 'PAUSED')
  ) INTO v_has_relationship;

  IF NOT v_has_relationship AND NOT public.is_master_admin() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El club no administra este perfil deportivo.');
  END IF;

  SELECT id, nombre, email INTO v_jugador
  FROM public.riviera_jugadores
  WHERE id = p_jugador_id;

  IF v_jugador.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Alumno no encontrado');
  END IF;

  SELECT * INTO v_link
  FROM public.coach_student_account_links
  WHERE organizador_id = p_organizador_id
    AND jugador_id = p_jugador_id;

  IF v_link.id IS NOT NULL AND v_link.auth_user_id IS NOT NULL THEN
    SELECT
      (encrypted_password IS NOT NULL AND length(encrypted_password) > 0),
      email,
      email_confirmed_at
    INTO v_has_password, v_auth_email, v_confirmed_at
    FROM auth.users
    WHERE id = v_link.auth_user_id;
  END IF;

  SELECT accepted_at INTO v_activated_at
  FROM public.coach_student_invitations
  WHERE organizador_id = p_organizador_id
    AND jugador_id = p_jugador_id
    AND status = 'ACCEPTED'
    AND accepted_at IS NOT NULL
  ORDER BY accepted_at DESC
  LIMIT 1;

  IF v_activated_at IS NULL AND v_has_password THEN
    v_activated_at := COALESCE(v_confirmed_at, v_link.created_at);
  END IF;

  SELECT * INTO v_invitation
  FROM public.coach_student_invitations
  WHERE organizador_id = p_organizador_id
    AND jugador_id = p_jugador_id
    AND status = 'PENDING'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_link.id IS NOT NULL AND NOT v_link.is_active THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'DEACTIVATED',
      'email', COALESCE(v_link.student_email, v_auth_email, v_jugador.email),
      'auth_user_id', v_link.auth_user_id,
      'is_active', false,
      'password_configured', v_has_password,
      'deactivated_at', v_link.deactivated_at,
      'activated_at', CASE WHEN v_has_password THEN v_activated_at ELSE NULL END,
      'created_at', v_link.created_at,
      'verification_method', v_link.verification_method
    );
  END IF;

  IF v_link.id IS NOT NULL AND v_link.is_active AND v_has_password THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'ACTIVE',
      'email', COALESCE(v_link.student_email, v_auth_email, v_jugador.email),
      'auth_user_id', v_link.auth_user_id,
      'is_active', true,
      'password_configured', true,
      'activated_at', v_activated_at,
      'created_at', v_link.created_at,
      'verification_method', v_link.verification_method
    );
  END IF;

  IF v_invitation.id IS NOT NULL OR (v_link.id IS NOT NULL AND NOT v_has_password) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'INVITATION_PENDING',
      'email', COALESCE(v_invitation.email, v_link.student_email, v_auth_email, v_jugador.email),
      'password_configured', false,
      'invited_at', v_invitation.invited_at,
      'expires_at', v_invitation.expires_at,
      'invitation_expired', v_invitation.id IS NOT NULL AND v_invitation.expires_at <= now(),
      'attempts_count', v_invitation.attempts_count
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'NO_ACCESS',
    'email', v_jugador.email,
    'password_configured', false
  );
END;
$$;


ALTER FUNCTION "public"."get_club_student_access_status"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_coach_class_followup"("p_relationship_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_rel record;
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  SELECT r.id, r.coach_id, r.organizador_id, r.jugador_id, r.status
  INTO v_rel
  FROM public.coach_player_relationships r
  WHERE r.id = p_relationship_id;

  IF NOT FOUND OR v_rel.status NOT IN ('ACTIVE', 'PAUSED') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Relación no disponible.');
  END IF;

  IF v_rel.coach_id IS DISTINCT FROM public.current_riviera_coach_id()
     AND v_rel.organizador_id IS DISTINCT FROM v_caller
     AND v_is_master IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes autorización para consultar este seguimiento.');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'sessions', COALESCE((
      SELECT jsonb_agg(row_to_json(x) ORDER BY x.starts_at DESC)
      FROM (
        SELECT
          s.id,
          s.starts_at,
          s.duration_minutes,
          s.status,
          s.worked_on,
          s.improvements,
          s.areas_to_improve,
          s.recommendations,
          s.next_goals,
          s.motivational_message,
          s.followup_updated_at,
          pn.body AS private_notes
        FROM public.coach_sessions s
        LEFT JOIN public.coach_session_private_notes pn ON pn.session_id = s.id
        WHERE s.relationship_id = v_rel.id
          AND s.status = 'COMPLETED'
          AND s.reverted_at IS NULL
        ORDER BY s.starts_at DESC
        LIMIT 40
      ) x
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_coach_class_followup"("p_relationship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_coach_followup_digest"("p_organizador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_coach_id uuid := public.current_riviera_coach_id();
BEGIN
  IF v_caller IS NULL OR v_coach_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado como coach.');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.coach_club_memberships m
    WHERE m.coach_id = v_coach_id
      AND m.organizador_id = p_organizador_id
      AND m.status = 'ACTIVE'
  ) AND NOT COALESCE(public.is_master_admin(), false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin asociación activa en este club.');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'students', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'relationship_id', r.id,
        'foto_url', j.foto_url,
        'categoria', j.categoria,
        'last_session_at', (
          SELECT s.starts_at FROM public.coach_sessions s
          WHERE s.relationship_id = r.id AND s.status = 'COMPLETED' AND s.reverted_at IS NULL
          ORDER BY s.starts_at DESC LIMIT 1
        ),
        'last_goal', (
          SELECT s.next_goals FROM public.coach_sessions s
          WHERE s.relationship_id = r.id AND s.status = 'COMPLETED' AND s.reverted_at IS NULL
            AND NULLIF(btrim(COALESCE(s.next_goals, '')), '') IS NOT NULL
          ORDER BY s.starts_at DESC LIMIT 1
        ),
        'next_session_at', (
          SELECT s.starts_at FROM public.coach_sessions s
          WHERE s.relationship_id = r.id AND s.status = 'SCHEDULED' AND s.starts_at >= now() - interval '2 hours'
          ORDER BY s.starts_at ASC LIMIT 1
        )
      ))
      FROM public.coach_player_relationships r
      JOIN public.riviera_jugadores j ON j.id = r.jugador_id
      WHERE r.coach_id = v_coach_id
        AND r.organizador_id = p_organizador_id
        AND r.status IN ('ACTIVE', 'PAUSED')
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_coach_followup_digest"("p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_coach_public_profile"("p_coach_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_coach public.riviera_coaches%ROWTYPE;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.coach_player_relationships r
    JOIN public.coach_student_account_links al
      ON al.jugador_id = r.jugador_id
     AND al.organizador_id = r.organizador_id
     AND al.auth_user_id = v_caller
     AND al.is_active = true
    WHERE r.coach_id = p_coach_id
      AND r.status IN ('ACTIVE', 'PAUSED')
  ) AND NOT EXISTS (
    SELECT 1 FROM public.riviera_coaches c
    WHERE c.id = p_coach_id AND c.auth_user_id = v_caller
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No puedes consultar este perfil.');
  END IF;

  SELECT * INTO v_coach FROM public.riviera_coaches WHERE id = p_coach_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Entrenador no encontrado.');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_coach.id,
    'nombre', v_coach.nombre,
    'coach_code', v_coach.coach_code,
    'foto_url', v_coach.foto_url,
    'bio', v_coach.bio,
    'edad', v_coach.edad,
    'anos_experiencia', v_coach.anos_experiencia,
    'posicion_juego', v_coach.posicion_juego,
    'instagram_url', v_coach.instagram_url,
    'facebook_url', v_coach.facebook_url,
    'tiktok_url', v_coach.tiktok_url,
    'especialidades', to_jsonb(COALESCE(v_coach.especialidades, '{}'::text[])),
    'areas_entrenamiento', to_jsonb(COALESCE(v_coach.areas_entrenamiento, '{}'::text[])),
    'fortalezas', to_jsonb(COALESCE(v_coach.fortalezas, '{}'::text[])),
    'certificaciones', v_coach.certificaciones,
    'metodologia_ensenanza', v_coach.metodologia_ensenanza,
    'enfoque_tecnico', v_coach.enfoque_tecnico,
    'objetivos_alumnos', v_coach.objetivos_alumnos,
    'estructura_entrenamientos', v_coach.estructura_entrenamientos,
    'habilidades_principales', to_jsonb(COALESCE(v_coach.habilidades_principales, '{}'::text[])),
    'fuerzas', to_jsonb(COALESCE(v_coach.fuerzas, '{}'::text[]))
  );
END;
$$;


ALTER FUNCTION "public"."get_coach_public_profile"("p_coach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_open_game_registration"("p_mode_type" "text", "p_entity_id" "uuid") RETURNS "public"."tournament_open_registration"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mode text;
  v_org uuid;
  v_row public.tournament_open_registration;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticación requerida'; END IF;
  v_mode := public._assert_convocatoria_mode_allowed(p_mode_type);
  IF p_entity_id IS NULL THEN RAISE EXCEPTION 'entity_id requerido'; END IF;

  -- Ownership server-side (no confiar en el cliente)
  v_org := public._open_reg_organizer_id(v_mode, p_entity_id);
  IF v_org IS NULL OR v_org <> v_uid THEN
    RAISE EXCEPTION 'Evento no encontrado o sin permiso';
  END IF;

  SELECT * INTO v_row
  FROM public.tournament_open_registration
  WHERE mode_type = v_mode AND entity_id = p_entity_id;

  -- NULL si no hay convocatoria (no crea fila)
  -- La fila de config no incluye cancellation_token_hash / teléfono / email.
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."get_open_game_registration"("p_mode_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organizador_branding_public"("p_org_id" "uuid") RETURNS TABLE("premium_branding_enabled" boolean, "branding_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(ogm.premium_branding_enabled, false),
    NULLIF(TRIM(ogm.branding_key), '')
  FROM public.organizador_game_modes ogm
  WHERE ogm.organizador_id = p_org_id;
$$;


ALTER FUNCTION "public"."get_organizador_branding_public"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organizador_display_name"("p_organizador_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_branding_key text;
  v_user_name text;
BEGIN
  IF p_organizador_id IS NULL THEN
    RETURN 'Club Deportivo Riviera';
  END IF;

  -- 1. Consultar branding_key en organizador_game_modes
  SELECT lower(btrim(branding_key)) INTO v_branding_key
  FROM public.organizador_game_modes
  WHERE organizador_id = p_organizador_id;

  IF v_branding_key = 'hack-padel' THEN
    RETURN 'Hack Pádel';
  ELSIF v_branding_key = 'padelito-warehouse' THEN
    RETURN 'Padelito Warehouse';
  ELSIF v_branding_key = 'padel-court-series' THEN
    RETURN 'Padel Court Series';
  ELSIF v_branding_key = 'valvidub-sports' THEN
    RETURN 'Valvidub Sports';
  ELSIF v_branding_key = 'acapulco-padel-tour' THEN
    RETURN 'Acapulco Padel Tour';
  END IF;

  -- 2. Consultar nombre en users (solo si no es correo electrónico)
  SELECT btrim(name) INTO v_user_name
  FROM public.users
  WHERE id = p_organizador_id;

  IF v_user_name IS NOT NULL AND v_user_name <> '' AND v_user_name NOT LIKE '%@%' THEN
    RETURN v_user_name;
  END IF;

  RETURN 'Club Deportivo Riviera';
END;
$$;


ALTER FUNCTION "public"."get_organizador_display_name"("p_organizador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_organizador_display_name"("p_organizador_id" "uuid") IS 'Nombre comercial visible del club organizador. Nunca devuelve correos electrónicos.';



CREATE OR REPLACE FUNCTION "public"."get_public_career_jugador_ids"("p_jugador_id" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH RECURSIVE ctx AS (
    SELECT public._resolve_official_player_key(p_jugador_id) AS official_key
  ),
  career_seed AS (
    SELECT p_jugador_id AS jugador_id
    UNION
    SELECT l.riviera_jugador_id
    FROM ctx
    JOIN public.riviera_official_player_profile_link l
      ON l.official_player_key = ctx.official_key
    WHERE ctx.official_key IS NOT NULL
    UNION
    SELECT i.canonical_riviera_jugador_id
    FROM ctx
    JOIN public.riviera_official_player_identity i
      ON i.official_player_key = ctx.official_key
    WHERE ctx.official_key IS NOT NULL
      AND i.canonical_riviera_jugador_id IS NOT NULL
    UNION
    SELECT opa.local_jugador_id
    FROM ctx
    JOIN public.riviera_official_player_identity i
      ON i.official_player_key = ctx.official_key
    JOIN public.organizer_player_access opa
      ON opa.jugador_id = i.canonical_riviera_jugador_id
     AND opa.is_active = true
    WHERE ctx.official_key IS NOT NULL
      AND opa.local_jugador_id IS NOT NULL
    UNION
    SELECT opa.jugador_id
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND opa.local_jugador_id = p_jugador_id
      AND opa.jugador_id IS NOT NULL
    UNION
    SELECT opa.local_jugador_id
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND opa.jugador_id = p_jugador_id
      AND opa.local_jugador_id IS NOT NULL
  ),
  career AS (
    SELECT DISTINCT cs.jugador_id
    FROM career_seed cs
    WHERE cs.jugador_id IS NOT NULL
  )
  SELECT DISTINCT c.jugador_id
  FROM career c
  JOIN public.riviera_jugadores rj ON rj.id = c.jugador_id
  WHERE rj.estado = 'activo';
$$;


ALTER FUNCTION "public"."get_public_career_jugador_ids"("p_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_public_career_jugador_ids"("p_jugador_id" "uuid") IS 'IDs de perfiles de la misma carrera global (sin gate visible_publico; grants bidireccionales).';



CREATE OR REPLACE FUNCTION "public"."get_public_career_jugador_ids_batch"("p_jugador_ids" "uuid"[]) RETURNS TABLE("anchor_jugador_id" "uuid", "jugador_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH anchors AS (
    SELECT DISTINCT unnest(COALESCE(p_jugador_ids, ARRAY[]::uuid[])) AS anchor_id
  ),
  ctx AS (
    SELECT a.anchor_id, public._resolve_official_player_key(a.anchor_id) AS official_key
    FROM anchors a
  ),
  career_seed AS (
    SELECT a.anchor_id, a.anchor_id AS jugador_id
    FROM anchors a
    UNION
    SELECT c.anchor_id, l.riviera_jugador_id
    FROM ctx c
    JOIN public.riviera_official_player_profile_link l
      ON l.official_player_key = c.official_key
    WHERE c.official_key IS NOT NULL
    UNION
    SELECT c.anchor_id, i.canonical_riviera_jugador_id
    FROM ctx c
    JOIN public.riviera_official_player_identity i
      ON i.official_player_key = c.official_key
    WHERE c.official_key IS NOT NULL
      AND i.canonical_riviera_jugador_id IS NOT NULL
    UNION
    SELECT c.anchor_id, opa.local_jugador_id
    FROM ctx c
    JOIN public.riviera_official_player_identity i
      ON i.official_player_key = c.official_key
    JOIN public.organizer_player_access opa
      ON opa.jugador_id = i.canonical_riviera_jugador_id
     AND opa.is_active = true
    WHERE c.official_key IS NOT NULL
      AND opa.local_jugador_id IS NOT NULL
    UNION
    SELECT a.anchor_id, opa.jugador_id
    FROM anchors a
    JOIN public.organizer_player_access opa
      ON opa.is_active = true
     AND opa.local_jugador_id = a.anchor_id
    WHERE opa.jugador_id IS NOT NULL
    UNION
    SELECT a.anchor_id, opa.local_jugador_id
    FROM anchors a
    JOIN public.organizer_player_access opa
      ON opa.is_active = true
     AND opa.jugador_id = a.anchor_id
    WHERE opa.local_jugador_id IS NOT NULL
  ),
  career AS (
    SELECT DISTINCT cs.anchor_id, cs.jugador_id
    FROM career_seed cs
    WHERE cs.jugador_id IS NOT NULL
  )
  SELECT DISTINCT c.anchor_id AS anchor_jugador_id, c.jugador_id
  FROM career c
  JOIN public.riviera_jugadores rj ON rj.id = c.jugador_id
  WHERE rj.estado = 'activo';
$$;


