CREATE OR REPLACE FUNCTION "public"."get_public_duelo2v2_rating_moves"("p_duelo_id" "uuid") RETURNS TABLE("jugador_id" "uuid", "rating_antes" numeric, "rating_despues" numeric, "delta" numeric)
