ALTER FUNCTION "public"."get_public_riviera_id_for_jugador"("p_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_public_riviera_id_for_jugador"("p_jugador_id" "uuid") IS 'Sprint 2.1.3B — Devuelve Riviera ID legible para perfiles públicos (sin auth).';



CREATE OR REPLACE FUNCTION "public"."get_public_riviera_ids_for_jugadores"("p_jugador_ids" "uuid"[]) RETURNS TABLE("jugador_id" "uuid", "riviera_id" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (
    SELECT DISTINCT unnest(COALESCE(p_jugador_ids, ARRAY[]::uuid[])) AS jugador_id
  ),
  via_link AS (
    SELECT
      i.jugador_id,
      ident.riviera_id::text AS riviera_id
    FROM ids i
    JOIN public.riviera_jugadores rj
      ON rj.id = i.jugador_id
     AND rj.estado = 'activo'
    JOIN public.riviera_official_player_profile_link pl
      ON pl.riviera_jugador_id = i.jugador_id
    JOIN public.riviera_official_player_identity ident
      ON ident.official_player_key = pl.official_player_key
    WHERE ident.riviera_id IS NOT NULL
  ),
  via_canonical AS (
    SELECT
      i.jugador_id,
      ident.riviera_id::text AS riviera_id
    FROM ids i
    JOIN public.riviera_jugadores rj
      ON rj.id = i.jugador_id
     AND rj.estado = 'activo'
    JOIN public.riviera_official_player_identity ident
      ON ident.canonical_riviera_jugador_id = i.jugador_id
    WHERE ident.riviera_id IS NOT NULL
  )
  SELECT DISTINCT ON (jugador_id) jugador_id, riviera_id
  FROM (
    SELECT * FROM via_link
    UNION ALL
    SELECT * FROM via_canonical
  ) merged
  ORDER BY jugador_id, riviera_id;
$$;


ALTER FUNCTION "public"."get_public_riviera_ids_for_jugadores"("p_jugador_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_public_riviera_ids_for_jugadores"("p_jugador_ids" "uuid"[]) IS 'Riviera ID para jugadores del ranking público (carrera deportiva, sin visible_publico).';



CREATE OR REPLACE FUNCTION "public"."get_riviera_oficial_jugador_public_profile"("p_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_jugador record;
  v_puntos integer;
  v_pos integer;
  v_historial jsonb;
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF NOT public.is_jugador_visible_sitio_oficial(p_jugador_id) THEN
    RETURN NULL;
  END IF;

  SELECT rj.*
  INTO v_jugador
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_jugador_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_puntos := public.riviera_official_display_puntos_for_jugador(p_jugador_id);
  v_pos := public.riviera_official_ranking_posicion_for_jugador(
    p_jugador_id,
    v_jugador.organizador_id,
    v_jugador.categoria,
    COALESCE(v_jugador.genero, 'M')
  );

  SELECT COALESCE(
    (
      SELECT jsonb_agg(entry ORDER BY sort_at DESC)
      FROM (
        SELECT jsonb_build_object(
          'participacion_id', row.participacion_id,
          'event_type', row.event_type,
          'event_id', row.event_id,
          'event_name', row.event_name,
          'points', row.points,
          'source_club_name', public.riviera_public_club_label(
            ARRAY[
              row.source_club_name,
              jp.metadata->>'club_name',
              jp.metadata->>'source_club_name'
            ],
            COALESCE(
              row.source_organizador_id::text,
              jp.metadata->>'organizador_id'
            )
          ),
          'activity_at', row.activity_at,
          'metadata', CASE
            WHEN jp.metadata IS NULL THEN row.metadata
            ELSE (
              COALESCE(jp.metadata, '{}'::jsonb)
              || COALESCE(row.metadata, '{}'::jsonb)
            ) || CASE
              WHEN jsonb_typeof(jp.metadata->'partidos_detalle') = 'array'
               AND jsonb_array_length(jp.metadata->'partidos_detalle') > 0
               AND (
                 jsonb_typeof(COALESCE(row.metadata->'partidos_detalle', 'null'::jsonb))
                   IS DISTINCT FROM 'array'
                 OR jsonb_array_length(
                   COALESCE(row.metadata->'partidos_detalle', '[]'::jsonb)
                 ) = 0
               )
              THEN jsonb_build_object(
                'partidos_detalle',
                jp.metadata->'partidos_detalle'
              )
              ELSE '{}'::jsonb
            END
          END
        ) AS entry,
        row.activity_at AS sort_at
        FROM public.list_riviera_official_player_activity(p_jugador_id, 5000) row
        LEFT JOIN public.jugador_participaciones jp
          ON jp.id = row.participacion_id
        UNION ALL
        SELECT jsonb_build_object(
          'participacion_id', jp.id,
          'event_type', jp.tipo_evento::text,
          'event_id', jp.evento_id,
          'event_name', jp.evento_nombre,
          'points', jp.puntos_obtenidos,
          'source_club_name', public.riviera_public_club_label(
            ARRAY[
              jp.metadata->>'club_name',
              jp.metadata->>'source_club_name'
            ],
            COALESCE(
              jp.metadata->>'organizador_id',
              (
                SELECT rj.organizador_id::text
                FROM public.riviera_jugadores rj
                WHERE rj.id = jp.jugador_id
              )
            )
          ),
          'activity_at', COALESCE(jp.fecha::timestamptz, jp.created_at),
          'metadata', jp.metadata
        ) AS entry,
        COALESCE(jp.fecha::timestamptz, jp.created_at) AS sort_at
        FROM public.list_riviera_official_legacy_participaciones(p_jugador_id, 5000) jp
      ) combined
    ),
    '[]'::jsonb
  )
  INTO v_historial;

  RETURN jsonb_build_object(
    'jugador_id', p_jugador_id,
    'organizador_id', v_jugador.organizador_id,
    'puntos_totales', v_puntos,
    'ranking_posicion', v_pos,
    'historial', v_historial
  );
END;
$$;


ALTER FUNCTION "public"."get_riviera_oficial_jugador_public_profile"("p_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_riviera_oficial_jugador_public_profile"("p_jugador_id" "uuid") IS 'Perfil público oficial. El ledger aporta puntos; los rivales salen de jugador_participaciones.partidos_detalle en cualquier club.';



CREATE OR REPLACE FUNCTION "public"."get_student_coaching_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_user_riviera_id text;
  v_results jsonb;
  v_student_profile jsonb;
  v_authorized_count integer;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Usuario no autenticado.');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.coach_student_account_links
    WHERE auth_user_id = v_caller AND is_active = false
  ) AND NOT EXISTS (
    SELECT 1 FROM public.coach_student_account_links
    WHERE auth_user_id = v_caller AND is_active = true
  ) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'linked', false,
      'is_deactivated', true,
      'message', 'Tu acceso a Riviera Coaching ha sido desactivado temporalmente por tu club. Consulta con la administración de tu club.'
    );
  END IF;

  SELECT count(*)
  INTO v_authorized_count
  FROM public.coach_student_account_links
  WHERE auth_user_id = v_caller AND is_active = true;

  IF v_authorized_count = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'linked', false,
      'message', 'Tu cuenta no tiene una credencial oficial de alumno vinculada a ningún club.',
      'relationships', '[]'::jsonb
    );
  END IF;

  SELECT i.riviera_id
  INTO v_user_riviera_id
  FROM public.coach_student_account_links al
  JOIN public.riviera_official_player_identity i ON i.canonical_riviera_jugador_id = al.jugador_id
  WHERE al.auth_user_id = v_caller AND al.is_active = true
  LIMIT 1;

  SELECT jsonb_build_object(
    'id', rj.id,
    'organizador_id', rj.organizador_id,
    'nombre', rj.nombre,
    'foto_url', rj.foto_url,
    'riviera_id', COALESCE(i.riviera_id, v_user_riviera_id),
    'edad', rj.edad,
    'en_cancha', rj.en_cancha,
    'instagram_url', rj.instagram_url,
    'facebook_url', rj.facebook_url,
    'tiktok_url', rj.tiktok_url,
    'coaching_sobre_mi', rj.coaching_sobre_mi
  )
  INTO v_student_profile
  FROM public.coach_student_account_links al
  JOIN public.riviera_jugadores rj ON rj.id = al.jugador_id
  LEFT JOIN public.riviera_official_player_identity i ON i.canonical_riviera_jugador_id = rj.id
  WHERE al.auth_user_id = v_caller AND al.is_active = true
  ORDER BY (rj.foto_url IS NOT NULL) DESC, al.updated_at DESC NULLS LAST, rj.id
  LIMIT 1;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'relationship_id', r.id,
      'status', r.status,
      'is_primary', (r.status = 'ACTIVE' AND r.is_primary),
      'started_at', r.started_at,
      'ended_at', r.ended_at,
      'club', jsonb_build_object(
        'organizador_id', r.organizador_id,
        'nombre', public.get_organizador_display_name(r.organizador_id),
        'branding_key', ogm.branding_key
      ),
      'coach', jsonb_build_object(
        'id', c.id,
        'nombre', c.nombre,
        'coach_code', c.coach_code,
        'foto_url', c.foto_url,
        'especialidades', c.especialidades
      ),
      'player', jsonb_build_object(
        'id', rj.id,
        'nombre', rj.nombre,
        'foto_url', rj.foto_url,
        'riviera_id', COALESCE(
          (SELECT i.riviera_id FROM public.riviera_official_player_identity i
           WHERE i.canonical_riviera_jugador_id = rj.id LIMIT 1),
          v_user_riviera_id
        ),
        'rivieraId', COALESCE(
          (SELECT i.riviera_id FROM public.riviera_official_player_identity i
           WHERE i.canonical_riviera_jugador_id = rj.id LIMIT 1),
          v_user_riviera_id
        )
      ),
      'balance', jsonb_build_object(
        'balance_classes', COALESCE(b.balance_classes, 0),
        'total_classes_given', COALESCE(b.total_classes_given, 0),
        'updated_at', b.updated_at
      ),
      'upcoming_sessions', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', sch.id,
            'starts_at', sch.starts_at,
            'ends_at', sch.ends_at,
            'duration_minutes', sch.duration_minutes,
            'court', sch.court,
            'focus', sch.focus,
            'prep_message_to_student', sch.prep_message_to_student,
            'status', sch.status
          ) ORDER BY sch.starts_at ASC
        )
        FROM public.coach_sessions sch
        WHERE sch.relationship_id = r.id
          AND sch.status = 'SCHEDULED'
          AND sch.starts_at >= now() - interval '2 hours'
      ), '[]'::jsonb),
      'ledger', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', l.id,
            'delta', l.delta,
            'tipo', l.tipo,
            'created_at', l.created_at,
            'session', CASE WHEN s.id IS NOT NULL THEN jsonb_build_object(
              'id', s.id,
              'starts_at', s.starts_at,
              'duration_minutes', s.duration_minutes,
              'court', s.court,
              'focus', s.focus,
              'worked_on', s.worked_on,
              'improvements', s.improvements,
              'next_goals', s.next_goals,
              'motivational_message', s.motivational_message
            ) ELSE NULL END
          ) ORDER BY l.created_at DESC
        )
        FROM (
          SELECT id, delta, tipo, created_at, session_id
          FROM public.coach_class_ledger
          WHERE relationship_id = r.id
          ORDER BY created_at DESC
          LIMIT 50
        ) l
        LEFT JOIN public.coach_sessions s ON s.id = l.session_id
      ), '[]'::jsonb)
    ) ORDER BY (CASE WHEN r.status = 'ACTIVE' THEN 0 WHEN r.status = 'PAUSED' THEN 1 ELSE 2 END), r.is_primary DESC, r.created_at DESC
  ), '[]'::jsonb)
  INTO v_results
  FROM public.coach_player_relationships r
  JOIN public.riviera_coaches c ON c.id = r.coach_id
  JOIN public.riviera_jugadores rj ON rj.id = r.jugador_id
  LEFT JOIN public.organizador_game_modes ogm ON ogm.organizador_id = r.organizador_id
  LEFT JOIN public.coach_player_class_balances b ON b.relationship_id = r.id
  JOIN public.coach_student_account_links al
    ON al.organizador_id = r.organizador_id
   AND al.jugador_id = r.jugador_id
   AND al.auth_user_id = v_caller
   AND al.is_active = true
  WHERE r.status IN ('ACTIVE', 'PAUSED', 'ENDED');

  RETURN jsonb_build_object(
    'ok', true,
    'linked', true,
    'riviera_id', v_user_riviera_id,
    'rivieraId', v_user_riviera_id,
    'student_profile', v_student_profile,
    'relationships', COALESCE(v_results, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_student_coaching_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_training_timeline"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'sessions', COALESCE((
      SELECT jsonb_agg(row_to_json(x) ORDER BY x.starts_at DESC)
      FROM (
        SELECT
          s.id,
          s.relationship_id,
          s.organizador_id,
          s.starts_at,
          s.duration_minutes,
          s.worked_on,
          s.improvements,
          s.areas_to_improve,
          s.recommendations,
          s.next_goals,
          s.motivational_message,
          s.followup_updated_at,
          c.nombre AS coach_nombre,
          public.get_organizador_display_name(s.organizador_id) AS club_nombre,
          nxt.starts_at AS next_scheduled_at
        FROM public.coach_sessions s
        JOIN public.coach_player_relationships r ON r.id = s.relationship_id
        JOIN public.riviera_coaches c ON c.id = s.coach_id
        JOIN public.coach_student_account_links al
          ON al.organizador_id = s.organizador_id
         AND al.jugador_id = s.jugador_id
         AND al.auth_user_id = v_caller
         AND al.is_active = true
        LEFT JOIN LATERAL (
          SELECT sch.starts_at
          FROM public.coach_sessions sch
          WHERE sch.relationship_id = r.id
            AND sch.status = 'SCHEDULED'
            AND sch.starts_at >= now() - interval '2 hours'
          ORDER BY sch.starts_at ASC
          LIMIT 1
        ) nxt ON true
        WHERE s.status = 'COMPLETED'
          AND s.reverted_at IS NULL
          AND s.relationship_id IS NOT NULL
          AND r.status IN ('ACTIVE', 'PAUSED', 'ENDED')
        ORDER BY s.starts_at DESC
        LIMIT 40
      ) x
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_student_training_timeline"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tournament_open_registration_public"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cfg public.tournament_open_registration;
  v_org uuid;
  v_title text;
  v_desc text;
  v_confirmed int;
  v_waitlist int;
  v_entries jsonb;
  v_finished boolean := false;
  v_started boolean := false;
  v_location text;
  v_cancha text;
  v_mostrar_lugar boolean := true;
  v_scheduled_at timestamptz;
  v_scheduled_until timestamptz;
  v_duration int;
  v_tournament_format text := null;
  v_championship_enabled boolean := false;
  v_costo text := null;
  v_mostrar_costo boolean := false;
  v_premio text := null;
  v_mostrar_premio boolean := false;
BEGIN
  SELECT * INTO v_cfg
  FROM public.tournament_open_registration
  WHERE public_slug = trim(coalesce(p_slug, ''))
    AND enabled = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  v_org := public._open_reg_organizer_id(v_cfg.mode_type, v_cfg.entity_id);

  IF v_cfg.mode_type = 'duelo_2v2' THEN
    SELECT
      nullif(trim(d.nombre), ''),
      d.descripcion,
      d.estado IN ('en_juego', 'finalizado'),
      d.estado = 'finalizado',
      nullif(trim(coalesce(d.lugar, '')), ''),
      coalesce(d.mostrar_lugar, true),
      nullif(trim(coalesce(d.cancha, '')), ''),
      d.programado_en,
      d.programado_hasta
    INTO
      v_title,
      v_desc,
      v_started,
      v_finished,
      v_location,
      v_mostrar_lugar,
      v_cancha,
      v_scheduled_at,
      v_scheduled_until
    FROM public.duelos_2v2 d
    WHERE d.id = v_cfg.entity_id;
  ELSE
    SELECT
      nullif(trim(t.name), ''),
      t.description,
      coalesce(t.is_started, false),
      coalesce(t.is_finished, false),
      nullif(trim(coalesce(t.lugar, '')), ''),
      coalesce(t.mostrar_lugar, true),
      nullif(trim(coalesce(t.cancha, '')), ''),
      t.programado_en,
      t.programado_hasta
    INTO
      v_title,
      v_desc,
      v_started,
      v_finished,
      v_location,
      v_mostrar_lugar,
      v_cancha,
      v_scheduled_at,
      v_scheduled_until
    FROM public.tournaments t
    WHERE t.id = v_cfg.entity_id;

    BEGIN
      SELECT
        nullif(trim(coalesce(t.costo, '')), ''),
        coalesce(t.mostrar_costo, false),
        nullif(trim(coalesce(t.premio, '')), ''),
        coalesce(t.mostrar_premio, false)
      INTO
        v_costo,
        v_mostrar_costo,
        v_premio,
        v_mostrar_premio
      FROM public.tournaments t
      WHERE t.id = v_cfg.entity_id;
    EXCEPTION
      WHEN undefined_column THEN
        v_costo := NULL;
        v_mostrar_costo := false;
        v_premio := NULL;
        v_mostrar_premio := false;
    END;

    BEGIN
      SELECT
        nullif(trim(coalesce(tpc.format::text, '')), ''),
        coalesce(
          lower(coalesce(tpc.championship_config->>'championshipEnabled', 'false'))
            IN ('true', 't', '1'),
          false
        )
      INTO
        v_tournament_format,
        v_championship_enabled
      FROM public.tournament_public_config tpc
      WHERE tpc.tournament_id = v_cfg.entity_id;
    EXCEPTION
      WHEN undefined_table OR undefined_column OR invalid_text_representation THEN
        v_tournament_format := null;
        v_championship_enabled := false;
    END;
  END IF;

  IF v_mostrar_lugar IS FALSE THEN
    v_location := NULL;
  END IF;

  IF v_mostrar_costo IS NOT TRUE THEN
    v_costo := NULL;
  END IF;

  IF v_mostrar_premio IS NOT TRUE THEN
    v_premio := NULL;
  END IF;

  v_title := coalesce(v_title, 'Convocatoria');

  IF v_scheduled_at IS NOT NULL AND v_scheduled_until IS NOT NULL
     AND v_scheduled_until > v_scheduled_at THEN
    v_duration := greatest(
      1,
      round(extract(epoch FROM (v_scheduled_until - v_scheduled_at)) / 60.0)::int
    );
  ELSE
    v_duration := NULL;
  END IF;

  SELECT count(*)::int INTO v_confirmed
  FROM public.tournament_open_registration_entries e
  WHERE e.registration_id = v_cfg.id AND e.status = 'confirmed';

  SELECT count(*)::int INTO v_waitlist
  FROM public.tournament_open_registration_entries e
  WHERE e.registration_id = v_cfg.id AND e.status = 'waitlist';

  SELECT coalesce(jsonb_agg(x.obj ORDER BY x.sort_ts), '[]'::jsonb)
  INTO v_entries
  FROM (
    SELECT
      jsonb_build_object(
        'id', e.id,
        'status', e.status,
        'riviera_id', e.riviera_id,
        'riviera_jugador_id', e.riviera_jugador_id,
        'nombre', CASE
          WHEN v_cfg.display_full_name THEN coalesce(e.display_name_snapshot, rj.nombre)
          ELSE split_part(coalesce(e.display_name_snapshot, rj.nombre), ' ', 1)
            || CASE
              WHEN array_length(regexp_split_to_array(trim(coalesce(e.display_name_snapshot, rj.nombre)), '\s+'), 1) > 1
              THEN ' ' || left(split_part(coalesce(e.display_name_snapshot, rj.nombre), ' ', 2), 1) || '.'
              ELSE ''
            END
        END,
        'foto_url', CASE
          WHEN NOT v_cfg.display_photo THEN NULL
          ELSE coalesce(
            nullif(trim(rj.foto_url), ''),
            (
              SELECT nullif(trim(src.foto_url), '')
              FROM public.organizer_player_access opa
              JOIN public.riviera_jugadores src
                ON src.id = opa.jugador_id
               AND src.estado = 'activo'
              WHERE opa.grantee_organizer_id = v_org
                AND opa.is_active = true
                AND (
                  opa.local_jugador_id = rj.id
                  OR opa.jugador_id = rj.id
                )
              ORDER BY opa.updated_at DESC NULLS LAST
              LIMIT 1
            ),
            (
              SELECT nullif(trim(c.foto_url), '')
              FROM public.riviera_jugadores c
              WHERE c.estado = 'activo'
                AND rj.legacy_player_id IS NOT NULL
                AND c.legacy_player_id = rj.legacy_player_id
                AND nullif(trim(c.foto_url), '') IS NOT NULL
              ORDER BY coalesce(c.rating_partidos, 0) DESC NULLS LAST
              LIMIT 1
            )
          )
        END,
        'rating', CASE WHEN v_cfg.display_rating THEN rj.rating ELSE NULL END,
        'categoria', rj.categoria,
        'preferred_side', e.preferred_side
      ) AS obj,
      coalesce(e.confirmed_at, e.created_at) AS sort_ts
    FROM public.tournament_open_registration_entries e
    JOIN public.riviera_jugadores rj ON rj.id = e.riviera_jugador_id
    WHERE e.registration_id = v_cfg.id
      AND e.status IN ('confirmed', 'waitlist')
  ) x;

  RETURN jsonb_build_object(
    'ok', true,
    'slug', v_cfg.public_slug,
    'mode_type', v_cfg.mode_type,
    'entity_id', v_cfg.entity_id,
    'registration_id', v_cfg.id,
    'tournament_id', v_cfg.tournament_id,
    'organizador_id', v_org,
    'name', v_title,
    'description', v_desc,
    'status', v_cfg.status,
    'capacity', v_cfg.capacity,
    'confirmed_count', v_confirmed,
    'waitlist_count', v_waitlist,
    'spots_left', greatest(v_cfg.capacity - v_confirmed, 0),
    'waitlist_enabled', v_cfg.waitlist_enabled,
    'approval_required', v_cfg.approval_required,
    'registration_deadline', v_cfg.registration_deadline,
    'scheduled_at', v_scheduled_at,
    'scheduled_until', v_scheduled_until,
    'duration_minutes', v_duration,
    'category_label', v_cfg.category_label,
    'rama_label', v_cfg.rama_label,
    'location_label', v_location,
    'cancha_label', v_cancha,
    'costo', v_costo,
    'premio', v_premio,
    'tournament_format', v_tournament_format,
    'championship_enabled', coalesce(v_championship_enabled, false),
    'display_rating', v_cfg.display_rating,
    'display_photo', v_cfg.display_photo,
    'entries', v_entries,
    'is_finished', coalesce(v_finished, false),
    'is_started', coalesce(v_started, false)
  );
END;
$$;


ALTER FUNCTION "public"."get_tournament_open_registration_public"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_organizador_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Si el usuario es exclusivamente alumno o coach, NO crear configuración de organizador
  IF public.is_restricted_sub_account(NEW.id) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.organizador_game_modes (organizador_id)
  VALUES (NEW.id)
  ON CONFLICT (organizador_id) DO NOTHING;

  INSERT INTO public.riviera_official_ranking_emitters (
    organizador_id,
    is_active,
    notes
  )
  VALUES (NEW.id, true, 'Auto: registro organizador')
  ON CONFLICT (organizador_id) DO UPDATE
  SET is_active = true, updated_at = now();

  RETURN NEW;
END;
$$;


