    AS $$
  SELECT
    p_duelo_id IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.duelos_2v2 d
      WHERE d.id = p_duelo_id
        AND COALESCE(d.es_publico, true) = true
        AND d.estado IN ('en_juego', 'finalizado')
    );
