CREATE OR REPLACE FUNCTION "public"."is_jugador_import_blocked"("p_organizador_id" "uuid", "p_nombre" "text" DEFAULT NULL::"text", "p_legacy_player_id" "uuid" DEFAULT NULL::"uuid", "p_legacy_liga_jugador_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.riviera_jugador_import_blocklist b
    WHERE b.organizador_id = p_organizador_id
      AND (
        (p_legacy_player_id IS NOT NULL AND b.legacy_player_id = p_legacy_player_id)
        OR (p_legacy_liga_jugador_id IS NOT NULL AND b.legacy_liga_jugador_id = p_legacy_liga_jugador_id)
        OR (
          coalesce(public._riviera_jugador_nombre_key(p_nombre), '') <> ''
          AND b.nombre_key = public._riviera_jugador_nombre_key(p_nombre)
        )
      )
  );
$$;


ALTER FUNCTION "public"."is_jugador_import_blocked"("p_organizador_id" "uuid", "p_nombre" "text", "p_legacy_player_id" "uuid", "p_legacy_liga_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_jugador_participacion_excluded"("p_jugador_id" "uuid", "p_tipo_evento" "text", "p_evento_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ctx AS (
    SELECT public._resolve_official_player_key(p_jugador_id) AS official_key
  )
  SELECT EXISTS (
    SELECT 1
    FROM public.jugador_participacion_exclusiones e, ctx
    WHERE e.tipo_evento = p_tipo_evento
      AND e.evento_id = p_evento_id
      AND (
        (ctx.official_key IS NOT NULL AND e.official_player_key = ctx.official_key)
        OR (ctx.official_key IS NULL AND e.scope_jugador_id = p_jugador_id)
      )
  );
$$;


ALTER FUNCTION "public"."is_jugador_participacion_excluded"("p_jugador_id" "uuid", "p_tipo_evento" "text", "p_evento_id" "uuid") OWNER TO "postgres";


