CREATE OR REPLACE FUNCTION "public"."is_tournament_publicly_readable"("p_tournament_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_tournament_id IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.tournaments t
      WHERE t.id = p_tournament_id
        AND (
          EXISTS (
            SELECT 1
            FROM public.tournament_public_config tpc
            WHERE tpc.tournament_id = t.id
          )
          OR COALESCE(t.is_public, true) = true
        )
    );
$$;


