CREATE OR REPLACE FUNCTION "public"."join_tournament_open_registration"("p_slug" "text", "p_riviera_id" "text", "p_preferred_side" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_cfg public.tournament_open_registration;
  v_norm text;
  v_identity record;
  v_confirmed int;
  v_status text;
  v_token text;
  v_token_hash text;
  v_entry_id uuid;
  v_existing public.tournament_open_registration_entries%ROWTYPE;
  v_host uuid;
  v_owner uuid;
  v_access_id uuid;
  v_local_id uuid;
  v_finished boolean := false;
  v_side text;
BEGIN
  -- Umbral ajustado de 5 a 20 intentos/10min: mismo motivo que preview — un
  -- grupo real inscribiéndose desde la misma IP/WiFi (ej. varios jugadores
  -- del mismo club) puede generar varios "join" en pocos minutos sin ser
  -- abuso.
  IF public._riviera_id_lookup_rate_limited('join', 20, interval '10 minutes') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rate_limited');
  END IF;

  SELECT * INTO v_cfg
  FROM public.tournament_open_registration
  WHERE public_slug = trim(coalesce(p_slug, ''))
  FOR UPDATE;

  IF NOT FOUND OR v_cfg.enabled IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_cfg.status IN ('closed', 'cancelled', 'paused', 'draft') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'registration_' || v_cfg.status);
  END IF;

  IF v_cfg.registration_deadline IS NOT NULL AND now() > v_cfg.registration_deadline THEN
    RETURN jsonb_build_object('ok', false, 'error', 'deadline_passed');
  END IF;

  v_host := public._open_reg_organizer_id(v_cfg.mode_type, v_cfg.entity_id);
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'tournament_unavailable');
  END IF;

  IF v_cfg.mode_type = 'duelo_2v2' THEN
    SELECT estado IN ('en_juego', 'finalizado') INTO v_finished
    FROM public.duelos_2v2 WHERE id = v_cfg.entity_id;
  ELSE
    SELECT coalesce(is_started, false) OR coalesce(is_finished, false)
      INTO v_finished
    FROM public.tournaments WHERE id = v_cfg.entity_id;
  END IF;
  IF coalesce(v_finished, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'registration_closed');
  END IF;

  v_norm := public._normalize_riviera_id_loose(p_riviera_id);
  IF v_norm IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_riviera_id');
  END IF;

  SELECT * INTO v_identity FROM public._resolve_identity_by_riviera_id(v_norm);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'riviera_id_not_found', 'riviera_id', v_norm);
  END IF;

  v_side := upper(nullif(trim(p_preferred_side), ''));
  IF v_side IS NOT NULL AND v_side NOT IN ('A', 'B') THEN
    v_side := NULL;
  END IF;
  IF v_cfg.mode_type <> 'duelo_2v2' THEN
    v_side := NULL;
  END IF;

  PERFORM pg_advisory_xact_lock(
    250715,
    hashtext(v_cfg.id::text || ':' || v_identity.canonical_riviera_jugador_id::text)
  );

  SELECT * INTO v_existing
  FROM public.tournament_open_registration_entries e
  WHERE e.registration_id = v_cfg.id
    AND e.riviera_jugador_id = v_identity.canonical_riviera_jugador_id
    AND e.status IN ('confirmed', 'waitlist', 'pending_approval')
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'already_registered',
      'status', v_existing.status, 'entry_id', v_existing.id
    );
  END IF;

  SELECT count(*)::int INTO v_confirmed
  FROM public.tournament_open_registration_entries e
  WHERE e.registration_id = v_cfg.id AND e.status = 'confirmed';

  IF v_cfg.approval_required THEN
    v_status := 'pending_approval';
  ELSIF v_confirmed < v_cfg.capacity THEN
    v_status := 'confirmed';
  ELSIF v_cfg.waitlist_enabled THEN
    v_status := 'waitlist';
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'full');
  END IF;

  v_owner := v_identity.registration_organizer_id;
  IF v_owner IS NOT NULL AND v_owner <> v_host THEN
    PERFORM pg_advisory_xact_lock(
      212012,
      hashtext(v_host::text || ':' || v_identity.canonical_riviera_jugador_id::text)
    );

    INSERT INTO public.organizer_player_access (
      jugador_id, owner_organizador_id, grantee_organizer_id, access_type,
      granted_by_admin_id, is_active, is_public_ranking, joined_at, joined_via
    ) VALUES (
      v_identity.canonical_riviera_jugador_id, v_owner, v_host, 'granted_by_admin',
      NULL, true, false, now(), 'registration'
    )
    ON CONFLICT (grantee_organizer_id, jugador_id) DO UPDATE SET
      is_active = true,
      left_at = NULL,
      joined_at = coalesce(public.organizer_player_access.joined_at, now()),
      joined_via = coalesce(public.organizer_player_access.joined_via, 'registration'),
      updated_at = now()
    RETURNING id INTO v_access_id;

    v_local_id := public._ensure_granted_player_local_as(
      v_identity.canonical_riviera_jugador_id, v_host
    );
  END IF;

  v_token := encode(extensions.gen_random_bytes(24), 'hex');
  v_token_hash := encode(extensions.digest(v_token, 'sha256'), 'hex');

  INSERT INTO public.tournament_open_registration_entries (
    registration_id, tournament_id, riviera_jugador_id, official_player_key,
    riviera_id, status, source, cancellation_token_hash, display_name_snapshot,
    confirmed_at, preferred_side
  ) VALUES (
    v_cfg.id,
    v_cfg.tournament_id,
    v_identity.canonical_riviera_jugador_id,
    v_identity.official_player_key,
    v_identity.riviera_id,
    v_status,
    'public_riviera_id',
    v_token_hash,
    v_identity.display_name,
    CASE WHEN v_status = 'confirmed' THEN now() ELSE NULL END,
    v_side
  ) RETURNING id INTO v_entry_id;

  IF v_status = 'confirmed' THEN
    IF v_cfg.mode_type = 'americano' THEN
      PERFORM public._open_reg_sync_americano_roster(v_cfg.entity_id);
    ELSIF v_cfg.mode_type = 'duelo_2v2' THEN
      PERFORM public._open_reg_sync_duelo_slots(v_cfg.entity_id);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'entry_id', v_entry_id,
    'status', v_status,
    'riviera_id', v_identity.riviera_id,
    'nombre', v_identity.display_name,
    'cancellation_token', v_token,
    'preferred_side', v_side,
    'message', CASE v_status
      WHEN 'confirmed' THEN 'Asistencia confirmada. Ya estás dentro.'
      WHEN 'waitlist' THEN 'Cupo lleno. Quedaste en lista de espera.'
      WHEN 'pending_approval' THEN 'Solicitud enviada. El club debe aprobarte.'
      ELSE 'Registrado.'
    END
  );
END;
$$;


ALTER FUNCTION "public"."join_tournament_open_registration"("p_slug" "text", "p_riviera_id" "text", "p_preferred_side" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_organizer_membership"("p_local_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_grantee uuid := auth.uid();
  v_access public.organizer_player_access%ROWTYPE;
  v_left_at timestamptz := now();
BEGIN
  IF v_grantee IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  IF p_local_jugador_id IS NULL THEN
    RAISE EXCEPTION 'local_jugador_id requerido';
  END IF;

  SELECT *
  INTO v_access
  FROM public.organizer_player_access opa
  WHERE opa.grantee_organizer_id = v_grantee
    AND opa.is_active = true
    AND (
      opa.local_jugador_id = p_local_jugador_id
      OR (
        opa.local_jugador_id IS NULL
        AND opa.jugador_id = p_local_jugador_id
      )
    )
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membresía activa no encontrada para este jugador';
  END IF;

  IF v_access.owner_organizador_id = v_grantee
     AND v_access.access_type = 'owner' THEN
    RAISE EXCEPTION 'No puedes abandonar la membresía de registro del jugador';
  END IF;

  UPDATE public.organizer_player_access
  SET
    is_active = false,
    left_at = v_left_at,
    updated_at = v_left_at
  WHERE id = v_access.id;

  IF v_access.local_jugador_id IS NOT NULL THEN
    UPDATE public.riviera_jugadores rj
    SET
      estado = 'archivado',
      suma_ranking = false,
      visible_publico = false,
      updated_at = v_left_at
    WHERE rj.id = v_access.local_jugador_id
      AND rj.organizador_id = v_grantee;
  END IF;

  RETURN jsonb_build_object(
    'membership_id', v_access.id,
    'local_jugador_id', v_access.local_jugador_id,
    'source_jugador_id', v_access.jugador_id,
    'left_at', v_left_at,
    'joined_via', v_access.joined_via
  );
END;
$$;


ALTER FUNCTION "public"."leave_organizer_membership"("p_local_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."leave_organizer_membership"("p_local_jugador_id" "uuid") IS 'Sprint 2.1.2 — Baja de membresía del organizador actual (soft). Archiva clon local; conserva Carrera, profile_link e historial.';



CREATE OR REPLACE FUNCTION "public"."liga_fnv1a_u32"("p_text" "text") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    AS $$
DECLARE
  h bigint := 2166136261; -- 0x811c9dc5
  i integer;
  c integer;
BEGIN
  FOR i IN 1 .. char_length(p_text) LOOP
    c := ascii(substr(p_text, i, 1));
    h := ((h # c) & 4294967295);
    h := ((h * 16777619) & 4294967295); -- 0x01000193, 32-bit como Math.imul
  END LOOP;
  RETURN h;
END;
$$;


ALTER FUNCTION "public"."liga_fnv1a_u32"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_inscritos_contacto_autorizado"("p_liga_id" "uuid") RETURNS TABLE("liga_jugador_id" "uuid", "email" "text", "telefono" "text", "riviera_jugador_id" "uuid", "identidad_global_id" "uuid", "origen" "text", "registro_autorizado_at" timestamp with time zone, "eval_correo" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_org uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'anon' USING ERRCODE = '42501';
  END IF;

  SELECT organizador_id INTO v_org FROM public.ligas WHERE id = p_liga_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'liga_no_encontrada' USING ERRCODE = 'P0002';
  END IF;
  IF v_org IS DISTINCT FROM v_caller AND NOT COALESCE(public.is_master_admin(), false) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    c.liga_jugador_id,
    c.email,
    c.telefono,
    c.riviera_jugador_id,
    c.identidad_global_id,
    c.origen,
    CASE
      WHEN c.origen IN ('global_source', 'global_local') THEN (
        SELECT rj.created_at
        FROM public.riviera_jugadores rj
        WHERE rj.id = COALESCE(c.identidad_global_id, c.riviera_jugador_id)
          AND rj.estado IS DISTINCT FROM 'archivado'
      )
      ELSE NULL
    END,
    public.liga_notificacion_evaluar_correo(insc.jid) AS eval_correo
  FROM (
    SELECT DISTINCT i.jugador_id AS jid
    FROM public.liga_inscripciones i
    WHERE i.liga_id = p_liga_id
    UNION
    SELECT e.jugador1_id
    FROM public.liga_equipos e
    WHERE e.liga_id = p_liga_id
    UNION
    SELECT e.jugador2_id
    FROM public.liga_equipos e
    WHERE e.liga_id = p_liga_id
  ) insc
  CROSS JOIN LATERAL public.liga_jugador_resolver_contacto(insc.jid) c;
END;
$$;


ALTER FUNCTION "public"."liga_inscritos_contacto_autorizado"("p_liga_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."liga_inscritos_contacto_autorizado"("p_liga_id" "uuid") IS 'Contacto de inscritos para el organizador, con evaluación canónica de correo.';



CREATE OR REPLACE FUNCTION "public"."liga_jugador_resolver_contacto"("p_liga_jugador_id" "uuid") RETURNS TABLE("liga_jugador_id" "uuid", "email" "text", "telefono" "text", "riviera_jugador_id" "uuid", "identidad_global_id" "uuid", "origen" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_lj public.liga_jugadores%ROWTYPE;
  v_local public.riviera_jugadores%ROWTYPE;
  v_source public.riviera_jugadores%ROWTYPE;
  v_source_id uuid;
  v_email text;
  v_tel text;
  v_origen text := 'ninguno';
  v_identidad uuid;
BEGIN
  IF p_liga_jugador_id IS NULL THEN
    RETURN;
  END IF;

  SELECT * INTO v_lj
  FROM public.liga_jugadores
  WHERE id = p_liga_jugador_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Ficha Riviera local del club (clon o propia) ligada a este roster.
  SELECT * INTO v_local
  FROM public.riviera_jugadores rj
  WHERE rj.legacy_liga_jugador_id = p_liga_jugador_id
    AND rj.estado IS DISTINCT FROM 'archivado'
  ORDER BY
    CASE WHEN rj.organizador_id IS NOT DISTINCT FROM v_lj.organizador_id THEN 0 ELSE 1 END,
    rj.created_at
  LIMIT 1;

  -- Si es clon cedido, el contacto canónico está en el origen.
  IF FOUND THEN
    SELECT opa.jugador_id INTO v_source_id
    FROM public.organizer_player_access opa
    WHERE opa.local_jugador_id = v_local.id
      AND opa.is_active IS TRUE
    ORDER BY opa.updated_at DESC NULLS LAST
    LIMIT 1;

    IF v_source_id IS NOT NULL THEN
      SELECT * INTO v_source
      FROM public.riviera_jugadores rj
      WHERE rj.id = v_source_id
        AND rj.estado IS DISTINCT FROM 'archivado';
    END IF;
  END IF;

  v_identidad := COALESCE(v_source.id, v_local.id);

  -- Preferencia: global origen → global local → roster. Nunca inventa.
  IF v_source.id IS NOT NULL
     AND NULLIF(btrim(v_source.email), '') IS NOT NULL
     AND lower(btrim(v_source.email)) NOT LIKE '%@padel.local' THEN
    v_email := NULLIF(btrim(v_source.email), '');
    v_tel := NULLIF(btrim(COALESCE(v_source.telefono, v_source.whatsapp)), '');
    v_origen := 'global_source';
  ELSIF v_local.id IS NOT NULL
     AND NULLIF(btrim(v_local.email), '') IS NOT NULL
     AND lower(btrim(v_local.email)) NOT LIKE '%@padel.local' THEN
    v_email := NULLIF(btrim(v_local.email), '');
    v_tel := NULLIF(btrim(COALESCE(v_local.telefono, v_local.whatsapp, v_lj.telefono)), '');
    v_origen := 'global_local';
  ELSIF NULLIF(btrim(v_lj.email), '') IS NOT NULL
     AND lower(btrim(v_lj.email)) NOT LIKE '%@padel.local' THEN
    v_email := NULLIF(btrim(v_lj.email), '');
    v_tel := NULLIF(btrim(v_lj.telefono), '');
    v_origen := 'liga';
  ELSE
    v_email := NULL;
    v_tel := NULLIF(btrim(COALESCE(
      v_source.telefono,
      v_source.whatsapp,
      v_local.telefono,
      v_local.whatsapp,
      v_lj.telefono
    )), '');
    v_origen := 'ninguno';
  END IF;

  liga_jugador_id := p_liga_jugador_id;
  email := CASE WHEN v_email IS NULL THEN NULL ELSE lower(btrim(v_email)) END;
  telefono := v_tel;
  riviera_jugador_id := COALESCE(v_source.id, v_local.id);
  identidad_global_id := v_identidad;
  origen := v_origen;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."liga_jugador_resolver_contacto"("p_liga_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."liga_jugador_resolver_contacto"("p_liga_jugador_id" "uuid") IS 'Contacto canónico de un roster de liga vía Riviera ID / cesión. Sin GRANT a clientes.';



CREATE OR REPLACE FUNCTION "public"."liga_mensaje_motivante_recordatorio"("p_jugador_id" "text", "p_liga_id" "text", "p_jornada_numero" integer, "p_jornada_id" "text" DEFAULT ''::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_msgs text[] := ARRAY[
    'Una nueva jornada, una nueva oportunidad para demostrar tu juego. Entra con confianza, pelea cada punto y disfruta la competencia en la cancha.',
    'Cada partido es una oportunidad para mejorar. Confía en tu juego, apoya a tu pareja y deja que el esfuerzo hable en la cancha.',
    'Los grandes partidos se construyen punto a punto. Mantén la concentración, lee cada jugada con calma y disfruta cada intercambio.',
    'Tu mejor versión se construye jugando. Hoy tienes una nueva oportunidad de demostrarlo con actitud firme, foco y juego limpio.',
    'La diferencia está en los detalles: actitud, concentración y ganas de competir. Llega listo, comunica bien y disfruta la cancha.',
    'Cada punto cuenta, pero también cada experiencia. Juega con inteligencia, compite con pasión y sigue creciendo partido tras partido en la cancha.',
    'Llega con la mente clara y las piernas listas. Hoy se trata de competir limpio, comunicar bien y disfrutar el pádel.',
    'La constancia se nota en cada partido. Confía en tu preparación, disputa cada punto con intención y mantén el ritmo.',
    'No hace falta forzar el resultado: juega con calma, lee la cancha y mantén tu nivel de principio a fin del partido.',
    'El pádel premia a quien insiste. Mantén la actitud, comunica con tu pareja, pelea los balls difíciles y disfruta el duelo.',
    'Hoy vuelve la competencia. Enfócate en tu primer saque, en el siguiente volley y en cada decisión dentro de la cancha.',
    'Entrena la cabeza tanto como el brazo. Concentración, paciencia y juego limpio te llevan lejos en cada jornada bien disputada.',
    'Una jornada más para medir tu progreso. Compite con respeto, exige tu nivel y sal de la cancha mejor que llegaste.',
    'Cuando llega el momento, lo importante es estar presente. Respira, confía en tu juego y disfruta cada rally con atención.',
    'La superación se construye partido a partido. Hoy es otra chance de demostrar tu compromiso y tu lectura de juego.',
    'Juega con carácter sin perder la cabeza. El control emocional también forma parte del buen pádel competitivo de alto nivel.',
    'Confía en tu pareja y en tu lectura de juego. Juntos suman más en cada punto disputado y en cada transición.',
    'El ritmo lo marcas tú. Empieza sólido, mantén la intensidad en los momentos clave y cierra el partido con inteligencia.',
    'Hoy no se trata de impresionar: se trata de competir bien, punto a punto, con orden y hasta el final del cruce.',
    'La cancha espera tu mejor actitud. Disfruta el cruce, pelea los balls difíciles y sigue creciendo con cada partido jugado.',
    'Cada jornada deja una lección. Entra con ganas de aprender, de competir al máximo y de disfrutar el juego limpio.',
    'El buen pádel combina precisión y garra. Busca ese equilibrio hoy en cada intercambio y en cada decisión importante en la cancha.',
    'Mantén la energía alta y el ego bajo. El juego limpio también es una forma clara de ganar respeto en la cancha.',
    'Si el punto se complica, vuelve a lo básico: buena posición, comunicación clara y una decisión firme en la cancha.',
    'Hoy tienes espacio para mejorar un detalle. Elige uno, concéntrate en él y compite con intención de principio a fin.',
    'La rivalidad sana empuja hacia arriba. Respeta al rival, exige tu mejor versión y disfruta cada cruce con buena cabeza.',
    'No subestimes un partido corto ni te apures en uno largo. Juega el punto que tienes delante con cabeza fría.',
    'La constancia vence a la prisa. Llega enfocado, mantén el plan de juego y cierra cada set con claridad total.',
    'Tu progreso se nota cuando compites con propósito. Hoy es otro paso firme en tu camino dentro de la liga.',
    'Disfruta el sonido de la pelota y el reto de cada jugada. Estás aquí para competir limpio y seguir creciendo.',
    'Actitud firme y manos suaves. Ese equilibrio define partidos difíciles, jornadas largas y duelos bien jugados durante toda la competencia.',
    'Que la presión no te robe el gusto por jugar. Compite en serio, respira entre puntos y disfruta el pádel de verdad.'
  ];
  v_n integer := array_length(v_msgs, 1);
  v_seed text;
  v_seed_prev text;
  v_idx integer;
  v_idx_prev integer;
  v_num integer := GREATEST(0, COALESCE(p_jornada_numero, 0));
BEGIN
  IF v_n IS NULL OR v_n < 1 THEN
    RETURN 'Cada partido cuenta. Compite con actitud y disfruta la cancha.';
  END IF;
  v_seed := lower(btrim(COALESCE(p_jugador_id, ''))) || '|' ||
            lower(btrim(COALESCE(p_liga_id, ''))) || '|' ||
            v_num::text || '|' ||
            lower(btrim(COALESCE(p_jornada_id, '')));
  v_idx := (public.liga_fnv1a_u32(v_seed) % v_n)::integer;
  IF v_n = 1 THEN
    RETURN v_msgs[1];
  END IF;
  v_seed_prev := lower(btrim(COALESCE(p_jugador_id, ''))) || '|' ||
                 lower(btrim(COALESCE(p_liga_id, ''))) || '|' ||
                 GREATEST(0, v_num - 1)::text || '|' ||
                 lower(btrim(COALESCE(p_jornada_id, '')));
  v_idx_prev := (public.liga_fnv1a_u32(v_seed_prev) % v_n)::integer;
  IF v_idx = v_idx_prev THEN
    v_idx := (v_idx + 1) % v_n;
  END IF;
  RETURN v_msgs[v_idx + 1]; -- arrays 1-based
END;
$$;


ALTER FUNCTION "public"."liga_mensaje_motivante_recordatorio"("p_jugador_id" "text", "p_liga_id" "text", "p_jornada_numero" integer, "p_jornada_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificacion_elegible_manual"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pref public.liga_notificaciones_preferencias%ROWTYPE;
  v_correo text;
BEGIN
  SELECT * INTO v_pref
  FROM public.liga_notificaciones_preferencias
  WHERE liga_id = p_liga_id AND liga_jugador_id = p_liga_jugador_id;

  IF FOUND AND v_pref.consentimiento_estado = 'revocado' THEN
    RETURN 'excluido';
  END IF;

  IF NOT FOUND OR NOT v_pref.admin_habilitado THEN
    RETURN 'deshabilitado';
  END IF;

  IF v_pref.consentimiento_estado IS DISTINCT FROM 'autorizado'
     OR v_pref.consentimiento_registrado_at IS NULL
     OR v_pref.consentimiento_origen IS NULL
     OR lower(btrim(v_pref.consentimiento_origen)) IN (
       'inscripcion', 'confirmacion_inscripcion', 'tiene_correo', 'email'
     ) THEN
    RETURN 'sin_autorizacion';
  END IF;

  v_correo := public.liga_notificacion_evaluar_correo(p_liga_jugador_id);
  IF v_correo IS DISTINCT FROM 'ok' THEN
    RETURN v_correo;
  END IF;

  RETURN 'ok';
END;
$$;


ALTER FUNCTION "public"."liga_notificacion_elegible_manual"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificacion_evaluar_correo"("p_liga_jugador_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_contact record;
  v_norm text;
  v_org uuid;
  v_dup integer;
  v_globals integer;
  v_roster integer;
BEGIN
  SELECT * INTO v_contact
  FROM public.liga_jugador_resolver_contacto(p_liga_jugador_id)
  LIMIT 1;

  IF v_contact.email IS NULL OR btrim(v_contact.email) = '' THEN
    RETURN 'sin_correo';
  END IF;

  v_norm := lower(btrim(v_contact.email));
  IF v_norm !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     OR v_norm LIKE '%@padel.local' THEN
    RETURN 'correo_invalido';
  END IF;

  SELECT organizador_id INTO v_org
  FROM public.liga_jugadores
  WHERE id = p_liga_jugador_id;

  -- Ambigüedad real: el mismo correo en DOS identidades globales distintas.
  -- Clones cedidos cuentan como su origen (no como identidad extra).
  SELECT count(*)::integer INTO v_dup
  FROM (
    SELECT DISTINCT COALESCE(
      (
        SELECT opa.jugador_id
        FROM public.organizer_player_access opa
        WHERE opa.local_jugador_id = rj.id
          AND opa.is_active IS TRUE
        LIMIT 1
      ),
      rj.id
    ) AS identidad
    FROM public.riviera_jugadores rj
    WHERE rj.estado IS DISTINCT FROM 'archivado'
      AND lower(btrim(coalesce(rj.email, ''))) = v_norm
  ) identities;

  IF v_dup > 1 THEN
    RETURN 'correo_ambiguo';
  END IF;

  -- Roster del mismo club: no inventar una segunda identidad con el id local
  -- cuando el correo ya resuelve a una sola identidad global.
  SELECT
    count(DISTINCT c.identidad_global_id)
      FILTER (WHERE c.identidad_global_id IS NOT NULL),
    count(DISTINCT c.liga_jugador_id)
  INTO v_globals, v_roster
  FROM public.liga_jugadores lj
  CROSS JOIN LATERAL public.liga_jugador_resolver_contacto(lj.id) c
  WHERE lj.organizador_id IS NOT DISTINCT FROM v_org
    AND c.email IS NOT NULL
    AND c.email = v_norm;

  IF v_globals > 1 THEN
    RETURN 'correo_ambiguo';
  END IF;
  IF v_globals = 0 AND v_roster > 1 THEN
    RETURN 'correo_ambiguo';
  END IF;

  RETURN 'ok';
END;
$_$;


ALTER FUNCTION "public"."liga_notificacion_evaluar_correo"("p_liga_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."liga_notificacion_evaluar_correo"("p_liga_jugador_id" "uuid") IS 'Evalúa el correo canónico del roster. Ambigüedad solo entre identidades globales distintas o entre varios rosters sin identidad.';



