CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_guardar_automatizacion"("p_liga_id" "uuid", "p_modo_operacion" "text", "p_resultados_auto" boolean, "p_resultados_espera_minutos" integer, "p_recordatorio_auto" boolean, "p_recordatorio_horas" integer, "p_bienvenida_auto" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_modo text := CASE
    WHEN lower(btrim(COALESCE(p_modo_operacion, ''))) = 'automatico' THEN 'automatico'
    ELSE 'manual'
  END;
  v_espera integer := CASE
    WHEN p_resultados_espera_minutos IN (0, 5, 15) THEN p_resultados_espera_minutos
    ELSE 5
  END;
  v_horas integer := CASE
    WHEN p_recordatorio_horas IN (24, 12, 6, 2) THEN p_recordatorio_horas
    ELSE 24
  END;
  v_jornada uuid;
  v_reprogramados integer := 0;
  v_procesando integer := 0;
  v_antes_horas integer;
  v_despues_horas integer;
  v_recordatorio_auto boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.liga_notificaciones_actor_puede(p_liga_id, v_actor) THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'sin_permiso');
  END IF;

  SELECT recordatorio_horas
    INTO v_antes_horas
  FROM public.liga_notificaciones_config
  WHERE liga_id = p_liga_id
  FOR UPDATE;

  INSERT INTO public.liga_notificaciones_config (
    liga_id,
    modo_operacion,
    resultados_auto,
    resultados_espera_minutos,
    recordatorio_auto,
    recordatorio_horas,
    bienvenida_auto,
    updated_at
  ) VALUES (
    p_liga_id,
    v_modo,
    COALESCE(p_resultados_auto, false),
    v_espera,
    COALESCE(p_recordatorio_auto, false),
    v_horas,
    COALESCE(p_bienvenida_auto, false),
    now()
  )
  ON CONFLICT (liga_id) DO UPDATE
    SET modo_operacion = EXCLUDED.modo_operacion,
        resultados_auto = EXCLUDED.resultados_auto,
        resultados_espera_minutos = EXCLUDED.resultados_espera_minutos,
        recordatorio_auto = EXCLUDED.recordatorio_auto,
        recordatorio_horas = EXCLUDED.recordatorio_horas,
        bienvenida_auto = EXCLUDED.bienvenida_auto,
        updated_at = now();

  SELECT recordatorio_horas, recordatorio_auto
    INTO v_despues_horas, v_recordatorio_auto
  FROM public.liga_notificaciones_config
  WHERE liga_id = p_liga_id;

  IF v_despues_horas IS DISTINCT FROM v_horas THEN
    RETURN jsonb_build_object(
      'ok', false,
      'motivo', 'no_persistido',
      'recordatorio_horas', v_despues_horas
    );
  END IF;

  SELECT count(*)::integer
    INTO v_procesando
  FROM public.liga_notificaciones_queue
  WHERE liga_id = p_liga_id
    AND tipo = 'recordatorio_jornada'
    AND origen = 'automatico'
    AND estado = 'procesando';

  IF v_recordatorio_auto THEN
    FOR v_jornada IN
      SELECT id
      FROM public.liga_jornadas
      WHERE liga_id = p_liga_id
        AND estado IS DISTINCT FROM 'completed'
        AND fecha IS NOT NULL
        AND fecha >= CURRENT_DATE
    LOOP
      PERFORM public.liga_notificaciones_sync_recordatorio(v_jornada);
    END LOOP;
  END IF;

  SELECT count(*)::integer
    INTO v_reprogramados
  FROM public.liga_notificaciones_queue
  WHERE liga_id = p_liga_id
    AND tipo = 'recordatorio_jornada'
    AND origen = 'automatico'
    AND estado = 'pendiente';

  RETURN jsonb_build_object(
    'ok', true,
    'motivo', NULL,
    'modo_operacion', v_modo,
    'resultados_auto', COALESCE(p_resultados_auto, false),
    'resultados_espera_minutos', v_espera,
    'recordatorio_auto', v_recordatorio_auto,
    'recordatorio_horas', v_despues_horas,
    'bienvenida_auto', COALESCE(p_bienvenida_auto, false),
    'horas_anteriores', v_antes_horas,
    'pendientes_recordatorio', v_reprogramados,
    'procesando_recordatorio', v_procesando
  );
END;
$$;


ALTER FUNCTION "public"."liga_notificaciones_guardar_automatizacion"("p_liga_id" "uuid", "p_modo_operacion" "text", "p_resultados_auto" boolean, "p_resultados_espera_minutos" integer, "p_recordatorio_auto" boolean, "p_recordatorio_horas" integer, "p_bienvenida_auto" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_guardar_supervision"("p_liga_id" "uuid", "p_email" "text", "p_activa" boolean, "p_alcance" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_email text := NULLIF(lower(btrim(coalesce(p_email, ''))), '');
  v_alcance text := CASE WHEN p_alcance = 'todas' THEN 'todas' ELSE 'resultados' END;
  v_activa boolean := COALESCE(p_activa, false) AND v_email IS NOT NULL;
  v_anterior text;
  v_conteo integer;
  v_ventana timestamptz;
BEGIN
  IF v_actor IS NULL OR NOT public.liga_notificaciones_actor_puede(p_liga_id, v_actor) THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'sin_permiso');
  END IF;
  IF v_email IS NOT NULL AND (
    char_length(v_email) > 180
    OR v_email LIKE '%@padel.local'
    OR v_email !~ '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'correo_invalido');
  END IF;

  SELECT NULLIF(lower(btrim(coalesce(supervision_email, ''))), ''),
         supervision_solicitudes,
         supervision_solicitud_ventana
    INTO v_anterior, v_conteo, v_ventana
  FROM public.liga_notificaciones_config
  WHERE liga_id = p_liga_id
  FOR UPDATE;

  IF v_email IS DISTINCT FROM v_anterior
     AND v_ventana IS NOT NULL
     AND v_ventana > now() - interval '1 hour'
     AND COALESCE(v_conteo, 0) >= 3 THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'limite_alcanzado');
  END IF;

  INSERT INTO public.liga_notificaciones_config (
    liga_id, supervision_email, supervision_activa, supervision_alcance,
    supervision_solicitudes, supervision_solicitud_ventana, updated_at
  ) VALUES (
    p_liga_id,
    v_email,
    v_activa,
    v_alcance,
    CASE WHEN v_email IS NULL THEN 0 ELSE 1 END,
    CASE WHEN v_email IS NULL THEN NULL ELSE now() END,
    now()
  )
  ON CONFLICT (liga_id) DO UPDATE
    SET supervision_email = EXCLUDED.supervision_email,
        supervision_activa = EXCLUDED.supervision_activa,
        supervision_alcance = EXCLUDED.supervision_alcance,
        supervision_email_verificado = CASE
          WHEN public.liga_notificaciones_config.supervision_email
               IS DISTINCT FROM EXCLUDED.supervision_email THEN NULL
          ELSE public.liga_notificaciones_config.supervision_email_verificado
        END,
        supervision_verificado_at = CASE
          WHEN public.liga_notificaciones_config.supervision_email
               IS DISTINCT FROM EXCLUDED.supervision_email THEN NULL
          ELSE public.liga_notificaciones_config.supervision_verificado_at
        END,
        supervision_token_hash = CASE
          WHEN public.liga_notificaciones_config.supervision_email
               IS DISTINCT FROM EXCLUDED.supervision_email THEN NULL
          ELSE public.liga_notificaciones_config.supervision_token_hash
        END,
        supervision_token_expira = CASE
          WHEN public.liga_notificaciones_config.supervision_email
               IS DISTINCT FROM EXCLUDED.supervision_email THEN NULL
          ELSE public.liga_notificaciones_config.supervision_token_expira
        END,
        supervision_intentos = CASE
          WHEN public.liga_notificaciones_config.supervision_email
               IS DISTINCT FROM EXCLUDED.supervision_email THEN 0
          ELSE public.liga_notificaciones_config.supervision_intentos
        END,
        supervision_solicitudes = CASE
          WHEN public.liga_notificaciones_config.supervision_email
               IS NOT DISTINCT FROM EXCLUDED.supervision_email
            THEN public.liga_notificaciones_config.supervision_solicitudes
          WHEN public.liga_notificaciones_config.supervision_solicitud_ventana IS NULL
            OR public.liga_notificaciones_config.supervision_solicitud_ventana
               <= now() - interval '1 hour' THEN 1
          ELSE COALESCE(public.liga_notificaciones_config.supervision_solicitudes, 0) + 1
        END,
        supervision_solicitud_ventana = CASE
          WHEN public.liga_notificaciones_config.supervision_email
               IS NOT DISTINCT FROM EXCLUDED.supervision_email
            THEN public.liga_notificaciones_config.supervision_solicitud_ventana
          WHEN public.liga_notificaciones_config.supervision_solicitud_ventana IS NULL
            OR public.liga_notificaciones_config.supervision_solicitud_ventana
               <= now() - interval '1 hour' THEN now()
          ELSE public.liga_notificaciones_config.supervision_solicitud_ventana
        END,
        updated_at = now();

  RETURN jsonb_build_object('ok', true, 'motivo', NULL);
END;
$_$;


ALTER FUNCTION "public"."liga_notificaciones_guardar_supervision"("p_liga_id" "uuid", "p_email" "text", "p_activa" boolean, "p_alcance" "text") OWNER TO "postgres";


