    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.inscrito_at IS NULL THEN
    NEW.inscrito_at := now();
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."liga_notificaciones_marcar_alta"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_preferencias_guardar"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at := now();

  IF NEW.consentimiento_estado = 'autorizado' THEN
    IF NEW.consentimiento_origen IS NULL
       OR btrim(NEW.consentimiento_origen) = ''
       OR lower(btrim(NEW.consentimiento_origen)) IN (
         'inscripcion', 'confirmacion_inscripcion', 'tiene_correo', 'email'
       ) THEN
      RAISE EXCEPTION 'consentimiento_sin_evidencia'
        USING ERRCODE = '23514';
    END IF;

    IF TG_OP = 'INSERT' THEN
      NEW.consentimiento_registrado_at := now();
      NEW.consentimiento_registrado_por := auth.uid();
    ELSIF OLD.consentimiento_estado IS DISTINCT FROM 'autorizado'
       OR OLD.consentimiento_origen IS DISTINCT FROM NEW.consentimiento_origen THEN
      NEW.consentimiento_registrado_at := now();
      NEW.consentimiento_registrado_por := auth.uid();
    END IF;
  END IF;

  -- Un interruptor del administrador no acredita titularidad del correo.
  IF TG_OP = 'INSERT' AND NEW.correo_verificado THEN
    RAISE EXCEPTION 'correo_sin_verificacion'
      USING ERRCODE = '23514';
  ELSIF TG_OP = 'UPDATE'
     AND NEW.correo_verificado
     AND NOT COALESCE(OLD.correo_verificado, false) THEN
    RAISE EXCEPTION 'correo_sin_verificacion'
      USING ERRCODE = '23514';
  END IF;

  IF NOT NEW.correo_verificado THEN
    NEW.correo_verificado_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."liga_notificaciones_preferencias_guardar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_programar_bienvenida"("p_liga_id" "uuid", "p_jugador_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_desde timestamptz;
  v_activa boolean;
  v_inscripcion uuid;
  v_alta timestamptz;
  v_elegible text;
BEGIN
  SELECT bienvenida_auto, bienvenida_auto_desde
    INTO v_activa, v_desde
  FROM public.liga_notificaciones_config
  WHERE liga_id = p_liga_id;
  IF NOT COALESCE(v_activa, false) OR v_desde IS NULL THEN
    RETURN;
  END IF;

  SELECT id, inscrito_at
    INTO v_inscripcion, v_alta
  FROM public.liga_inscripciones
  WHERE liga_id = p_liga_id AND jugador_id = p_jugador_id
  ORDER BY inscrito_at DESC NULLS LAST
  LIMIT 1;
  IF v_inscripcion IS NULL OR v_alta IS NULL OR v_alta < v_desde THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.liga_notificaciones_queue
    WHERE liga_id = p_liga_id
      AND liga_jugador_id = p_jugador_id
      AND tipo = 'bienvenida'
      AND estado IN ('pendiente', 'procesando', 'enviado')
  ) THEN
    RETURN;
  END IF;

  v_elegible := public.liga_notificacion_elegible_manual(p_liga_id, p_jugador_id);
  IF v_elegible IS DISTINCT FROM 'ok' THEN
    RETURN;
  END IF;

  INSERT INTO public.liga_notificaciones_queue (
    liga_id, liga_jugador_id, inscripcion_id, tipo, idempotency_key,
    estado, origen, programado_para
  ) VALUES (
    p_liga_id,
    p_jugador_id,
    v_inscripcion,
    'bienvenida',
    'auto:bienvenida:' || p_liga_id::text || ':' || v_inscripcion::text || ':' || p_jugador_id::text,
    'pendiente',
    'automatico',
    now()
  )
  ON CONFLICT (idempotency_key) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."liga_notificaciones_programar_bienvenida"("p_liga_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_programar_resultados"("p_jornada_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jornada public.liga_jornadas%ROWTYPE;
  v_liga_nombre text;
  v_espera integer;
  v_activa boolean;
  v_ruta text;
  v_fecha text;
  v_jugador record;
  v_elegible text;
  v_nombre text;
  v_cuerpo text;
  v_asunto text;
BEGIN
  SELECT * INTO v_jornada FROM public.liga_jornadas WHERE id = p_jornada_id;
  IF NOT FOUND OR v_jornada.estado IS DISTINCT FROM 'completed' THEN
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.liga_partidos WHERE jornada_id = v_jornada.id
  ) OR EXISTS (
    SELECT 1 FROM public.liga_partidos
    WHERE jornada_id = v_jornada.id AND estado IS DISTINCT FROM 'completed'
  ) THEN
    RETURN;
  END IF;

  SELECT COALESCE(resultados_auto, false),
         COALESCE(resultados_espera_minutos, 5)
    INTO v_activa, v_espera
  FROM public.liga_notificaciones_config
  WHERE liga_id = v_jornada.liga_id;
  IF NOT COALESCE(v_activa, false) THEN
    RETURN;
  END IF;
  IF v_espera NOT IN (0, 5, 15) THEN
    v_espera := 5;
  END IF;
  IF v_jornada.numero IS NULL OR v_jornada.numero < 1 THEN
    RETURN;
  END IF;

  SELECT nombre INTO v_liga_nombre FROM public.ligas WHERE id = v_jornada.liga_id;
  v_liga_nombre := COALESCE(NULLIF(btrim(v_liga_nombre), ''), 'tu liga');
  v_fecha := COALESCE(to_char(v_jornada.fecha, 'DD/MM/YYYY'), 'Por definir');
  v_ruta := '/public/liga/' || v_jornada.liga_id::text || '/jornada/' || v_jornada.numero::text;
  v_asunto := left('Resultados oficiales — ' || v_liga_nombre || ' | Jornada ' || v_jornada.numero::text, 180);

  FOR v_jugador IN
    SELECT DISTINCT i.jugador_id
    FROM public.liga_inscripciones i
    WHERE i.liga_id = v_jornada.liga_id
  LOOP
    v_elegible := public.liga_notificacion_elegible_manual(v_jornada.liga_id, v_jugador.jugador_id);
    IF v_elegible IS DISTINCT FROM 'ok' THEN
      CONTINUE;
    END IF;

    SELECT nombre INTO v_nombre
    FROM public.liga_jugadores
    WHERE id = v_jugador.jugador_id;
    v_nombre := COALESCE(NULLIF(btrim(v_nombre), ''), 'jugador');
    v_cuerpo :=
      'Hola ' || v_nombre || E',\n\n'
      || 'Una jornada más de ' || v_liga_nombre || E' ha llegado a su fin.\n\n'
      || E'Cada game ganado, cada punto disputado y cada partido jugado forman parte de tu crecimiento deportivo.\n\n'
      || 'Los resultados oficiales de la Jornada ' || v_jornada.numero::text || E' ya están disponibles.\n\n'
      || 'Fecha: ' || v_fecha || E'\n'
      || E'Sede: {{club}}\n\n'
      || 'RESULTADOS_URL:' || v_ruta;

    INSERT INTO public.liga_notificaciones_queue (
      liga_id, liga_jugador_id, tipo, idempotency_key, estado, motivo,
      asunto, cuerpo_texto, origen, programado_para, jornada_id, jornada_numero
    ) VALUES (
      v_jornada.liga_id,
      v_jugador.jugador_id,
      'resultados_jornada',
      'auto:resultados:' || v_jornada.liga_id::text || ':' || v_jornada.id::text || ':' || v_jugador.jugador_id::text,
      'pendiente',
      NULL,
      v_asunto,
      v_cuerpo,
      'automatico',
      now() + make_interval(mins => v_espera),
      v_jornada.id,
      v_jornada.numero
    )
    ON CONFLICT (idempotency_key) DO NOTHING;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."liga_notificaciones_programar_resultados"("p_jornada_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_proteger_supervision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_anterior text := NULLIF(lower(btrim(coalesce(OLD.supervision_email, ''))), '');
  v_nuevo text := NULLIF(lower(btrim(coalesce(NEW.supervision_email, ''))), '');
BEGIN
  IF current_user IN ('authenticated', 'anon', 'authenticator') THEN
    NEW.supervision_email := v_nuevo;
    IF v_nuevo IS NOT NULL AND (
      char_length(v_nuevo) > 180
      OR v_nuevo LIKE '%@padel.local'
      OR v_nuevo !~ '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$'
    ) THEN
      RAISE EXCEPTION 'correo_invalido' USING ERRCODE = '22023';
    END IF;
    IF NEW.supervision_activa IS TRUE AND v_nuevo IS NULL THEN
      NEW.supervision_activa := false;
    END IF;
    IF v_nuevo IS DISTINCT FROM v_anterior THEN
      IF OLD.supervision_solicitud_ventana IS NOT NULL
         AND OLD.supervision_solicitud_ventana > now() - interval '1 hour'
         AND OLD.supervision_solicitudes >= 3 THEN
        RAISE EXCEPTION 'limite_alcanzado' USING ERRCODE = 'P0001';
      END IF;
      NEW.supervision_email_verificado := NULL;
      NEW.supervision_verificado_at := NULL;
      NEW.supervision_token_hash := NULL;
      NEW.supervision_token_expira := NULL;
      NEW.supervision_intentos := 0;
      NEW.supervision_solicitudes := CASE
        WHEN OLD.supervision_solicitud_ventana IS NULL
          OR OLD.supervision_solicitud_ventana <= now() - interval '1 hour' THEN 1
        ELSE COALESCE(OLD.supervision_solicitudes, 0) + 1
      END;
      NEW.supervision_solicitud_ventana := CASE
        WHEN OLD.supervision_solicitud_ventana IS NULL
          OR OLD.supervision_solicitud_ventana <= now() - interval '1 hour' THEN now()
        ELSE OLD.supervision_solicitud_ventana
      END;
      NEW.supervision_prueba_conteo := OLD.supervision_prueba_conteo;
      NEW.supervision_prueba_ventana := OLD.supervision_prueba_ventana;
    ELSE
      NEW.supervision_email_verificado := OLD.supervision_email_verificado;
      NEW.supervision_verificado_at := OLD.supervision_verificado_at;
      NEW.supervision_token_hash := OLD.supervision_token_hash;
      NEW.supervision_token_expira := OLD.supervision_token_expira;
      NEW.supervision_intentos := OLD.supervision_intentos;
      NEW.supervision_solicitudes := OLD.supervision_solicitudes;
      NEW.supervision_solicitud_ventana := OLD.supervision_solicitud_ventana;
      NEW.supervision_prueba_conteo := OLD.supervision_prueba_conteo;
      NEW.supervision_prueba_ventana := OLD.supervision_prueba_ventana;
    END IF;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."liga_notificaciones_proteger_supervision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_reservar_prueba_supervision"("p_liga_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_email text;
BEGIN
  IF coalesce(auth.role(), '') IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'sin_permiso');
  END IF;
  IF NOT public.liga_notificaciones_actor_puede(p_liga_id, p_actor) THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'sin_permiso');
  END IF;

  UPDATE public.liga_notificaciones_config
     SET supervision_prueba_conteo = CASE
           WHEN supervision_prueba_ventana IS NULL
                OR supervision_prueba_ventana <= now() - interval '1 hour' THEN 1
           ELSE supervision_prueba_conteo + 1
         END,
         supervision_prueba_ventana = CASE
           WHEN supervision_prueba_ventana IS NULL
                OR supervision_prueba_ventana <= now() - interval '1 hour' THEN now()
           ELSE supervision_prueba_ventana
         END
   WHERE liga_id = p_liga_id
     AND supervision_email IS NOT NULL
     AND char_length(supervision_email) <= 180
     AND supervision_email NOT LIKE '%@padel.local'
     AND supervision_email ~ '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$'
     AND (
       supervision_prueba_ventana IS NULL
       OR supervision_prueba_ventana <= now() - interval '1 hour'
       OR supervision_prueba_conteo < 3
     )
  RETURNING supervision_email INTO v_email;

  IF v_email IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.liga_notificaciones_config
      WHERE liga_id = p_liga_id
        AND supervision_email IS NOT NULL
        AND char_length(supervision_email) <= 180
        AND supervision_email NOT LIKE '%@padel.local'
        AND supervision_email ~ '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$'
        AND supervision_prueba_ventana > now() - interval '1 hour'
        AND supervision_prueba_conteo >= 3
    ) THEN
      RETURN jsonb_build_object('ok', false, 'motivo', 'limite_alcanzado');
    END IF;
    RETURN jsonb_build_object('ok', false, 'motivo', 'correo_invalido');
  END IF;
  RETURN jsonb_build_object('ok', true, 'motivo', NULL, 'email', v_email);
END;
$_$;


ALTER FUNCTION "public"."liga_notificaciones_reservar_prueba_supervision"("p_liga_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_sync_recordatorio"("p_jornada_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jornada public.liga_jornadas%ROWTYPE;
  v_activa boolean;
  v_horas integer;
  v_hora time;
  v_distintas integer;
  v_inicio timestamptz;
  v_cuando timestamptz;
  v_liga_nombre text;
  v_fecha text;
  v_hora_txt text;
  v_ruta text;
  v_jugador record;
  v_elegible text;
  v_cuerpo text;
  v_clave text;
  v_mensaje text;
BEGIN
  SELECT * INTO v_jornada FROM public.liga_jornadas WHERE id = p_jornada_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_jornada.estado = 'completed' OR v_jornada.fecha IS NULL THEN
    UPDATE public.liga_notificaciones_queue
       SET estado = 'omitido', motivo = 'cancelado', updated_at = now()
     WHERE jornada_id = v_jornada.id
       AND tipo = 'recordatorio_jornada'
       AND origen = 'automatico'
       AND estado = 'pendiente';
    RETURN;
  END IF;

  SELECT COALESCE(recordatorio_auto, false), COALESCE(recordatorio_horas, 24)
    INTO v_activa, v_horas
  FROM public.liga_notificaciones_config
  WHERE liga_id = v_jornada.liga_id;

  IF NOT COALESCE(v_activa, false) THEN
    UPDATE public.liga_notificaciones_queue
       SET estado = 'omitido', motivo = 'automatizacion_apagada', updated_at = now()
     WHERE jornada_id = v_jornada.id
       AND tipo = 'recordatorio_jornada'
       AND origen = 'automatico'
       AND estado = 'pendiente';
    RETURN;
  END IF;
  IF v_horas NOT IN (24, 12, 6, 2) THEN
    v_horas := 24;
  END IF;

  SELECT count(DISTINCT hora_inicio)
    INTO v_distintas
  FROM public.liga_partidos
  WHERE jornada_id = v_jornada.id
    AND COALESCE(ronda, 1) = 1
    AND hora_inicio IS NOT NULL;

  IF v_distintas IS DISTINCT FROM 1 THEN
    UPDATE public.liga_notificaciones_queue
       SET estado = 'omitido',
           motivo = CASE WHEN COALESCE(v_distintas, 0) = 0
                         THEN 'jornada_sin_horario'
                         ELSE 'horarios_distintos' END,
           programado_para = NULL,
           updated_at = now()
     WHERE jornada_id = v_jornada.id
       AND tipo = 'recordatorio_jornada'
       AND origen = 'automatico'
       AND estado = 'pendiente';
    RETURN;
  END IF;

  SELECT min(hora_inicio)
    INTO v_hora
  FROM public.liga_partidos
  WHERE jornada_id = v_jornada.id
    AND COALESCE(ronda, 1) = 1
    AND hora_inicio IS NOT NULL;

  v_inicio := (v_jornada.fecha + v_hora) AT TIME ZONE 'America/Mexico_City';
  v_cuando := v_inicio - make_interval(hours => v_horas);
  IF v_cuando <= now() OR v_inicio <= now() THEN
    UPDATE public.liga_notificaciones_queue
       SET estado = 'omitido', motivo = 'recordatorio_vencido', updated_at = now()
     WHERE jornada_id = v_jornada.id
       AND tipo = 'recordatorio_jornada'
       AND origen = 'automatico'
       AND estado = 'pendiente';
    RETURN;
  END IF;

  SELECT nombre INTO v_liga_nombre FROM public.ligas WHERE id = v_jornada.liga_id;
  v_liga_nombre := COALESCE(NULLIF(btrim(v_liga_nombre), ''), 'tu liga');
  v_fecha := to_char(v_jornada.fecha, 'DD/MM/YYYY');
  v_hora_txt := to_char(v_hora, 'HH24:MI');
  v_ruta := '/public/liga/' || v_jornada.liga_id::text || '/jornada/' || v_jornada.numero::text;

  FOR v_jugador IN
    SELECT DISTINCT jugador_id
    FROM public.liga_inscripciones
    WHERE liga_id = v_jornada.liga_id
  LOOP
    v_clave :=
      'auto:recordatorio:'
      || v_jornada.liga_id::text || ':'
      || v_jornada.id::text || ':'
      || v_jugador.jugador_id::text;
    v_elegible := public.liga_notificacion_elegible_manual(v_jornada.liga_id, v_jugador.jugador_id);

    IF v_elegible IS DISTINCT FROM 'ok' THEN
      UPDATE public.liga_notificaciones_queue
         SET estado = 'omitido',
             motivo = left(v_elegible, 80),
             programado_para = NULL,
             updated_at = now()
       WHERE idempotency_key = v_clave
         AND origen = 'automatico'
         AND estado = 'pendiente';
      CONTINUE;
    END IF;

    v_mensaje := public.liga_mensaje_motivante_recordatorio(
      v_jugador.jugador_id::text,
      v_jornada.liga_id::text,
      v_jornada.numero,
      v_jornada.id::text
    );
    v_cuerpo :=
      'Hola {{nombre}},' || E'\n\n'
      || v_mensaje || E'\n\n'
      || 'Fecha: ' || v_fecha || E'\n'
      || 'Horario: ' || v_hora_txt || ' hrs' || E'\n'
      || 'Sede: {{club}}' || E'\n\n'
      || 'RESULTADOS_URL:' || v_ruta;

    INSERT INTO public.liga_notificaciones_queue (
      liga_id, liga_jugador_id, tipo, idempotency_key, estado, motivo,
      asunto, cuerpo_texto, origen, programado_para, jornada_id, jornada_numero
    ) VALUES (
      v_jornada.liga_id,
      v_jugador.jugador_id,
      'recordatorio_jornada',
      v_clave,
      'pendiente',
      NULL,
      left('Recordatorio — ' || v_liga_nombre || ' | Jornada ' || v_jornada.numero::text, 180),
      v_cuerpo,
      'automatico',
      v_cuando,
      v_jornada.id,
      v_jornada.numero
    )
    ON CONFLICT (idempotency_key) DO UPDATE
      SET programado_para = EXCLUDED.programado_para,
          asunto = EXCLUDED.asunto,
          cuerpo_texto = EXCLUDED.cuerpo_texto,
          estado = 'pendiente',
          motivo = NULL,
          updated_at = now()
      WHERE public.liga_notificaciones_queue.origen = 'automatico'
        AND (
          public.liga_notificaciones_queue.estado = 'pendiente'
          OR (
            public.liga_notificaciones_queue.estado = 'omitido'
            AND public.liga_notificacion_motivo_es_elegibilidad(
              public.liga_notificaciones_queue.motivo
            )
          )
        );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."liga_notificaciones_sync_recordatorio"("p_jornada_id" "uuid") OWNER TO "postgres";


