    AS $$
BEGIN
  UPDATE public.liga_notificaciones_queue
     SET estado = 'omitido', motivo = 'cancelado', updated_at = now()
   WHERE jornada_id = OLD.id
     AND origen = 'automatico'
     AND estado = 'pendiente';
  RETURN OLD;
EXCEPTION WHEN OTHERS THEN
