CREATE OR REPLACE FUNCTION "public"."liga_notificaciones_trg_preferencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_jornada uuid;
  v_motivo text;
BEGIN
  IF NEW.consentimiento_estado IS DISTINCT FROM 'autorizado'
     OR NEW.admin_habilitado IS DISTINCT FROM true THEN
    v_motivo := CASE
      WHEN NEW.admin_habilitado IS DISTINCT FROM true THEN 'deshabilitado'
      ELSE 'sin_autorizacion'
    END;
    UPDATE public.liga_notificaciones_queue
       SET estado = 'omitido',
           motivo = v_motivo,
           programado_para = NULL,
           updated_at = now()
     WHERE liga_id = NEW.liga_id
       AND liga_jugador_id = NEW.liga_jugador_id
       AND origen = 'automatico'
       AND estado = 'pendiente';
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.consentimiento_estado = 'autorizado'
     AND OLD.admin_habilitado IS TRUE THEN
    RETURN NEW;
  END IF;

  PERFORM public.liga_notificaciones_programar_bienvenida(NEW.liga_id, NEW.liga_jugador_id);

  FOR v_jornada IN
    SELECT id FROM public.liga_jornadas
    WHERE liga_id = NEW.liga_id
      AND estado IS DISTINCT FROM 'completed'
      AND fecha IS NOT NULL
      AND fecha >= CURRENT_DATE
  LOOP
    PERFORM public.liga_notificaciones_sync_recordatorio(v_jornada);
  END LOOP;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."liga_notificaciones_trg_preferencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."liga_playoffs_freeze_and_generate_jornada9"("p_liga_id" "uuid", "p_seeds" "jsonb", "p_sf1_p1" "uuid", "p_sf1_p2" "uuid", "p_sf2_p1" "uuid", "p_sf2_p2" "uuid", "p_cl1_p1" "uuid", "p_cl1_p2" "uuid", "p_cl2_p1" "uuid", "p_cl2_p2" "uuid", "p_canchas" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_organizador uuid;
  v_modalidad text;
  v_seeds jsonb;
  v_jornada_id uuid;
  v_canchas integer;
  v_equipo_id uuid;
  v_jugador1_id uuid;
  v_jugador2_id uuid;
  v_pareja_id uuid;
  v_map jsonb := '{}'::jsonb;
  v_eq1 uuid;
  v_eq2 uuid;
  v_p1 uuid;
  v_p2 uuid;
  v_existing integer;
  v_regular_done integer;
  v_regular_total integer;
  v_calendar_n integer;
  v_n integer;
  v_expected integer;
  v_last_regular integer;
  v_playoff_jornada integer;
  v_i integer;
  v_low integer;
  v_high integer;
  v_cl integer;
  v_slot text;
  v_fase text;
  v_seed_home text;
  v_seed_away text;
  v_bye_seed integer;
  v_key text;
  v_seen jsonb := '{}'::jsonb;
BEGIN
  -- Params de pareja del cliente se ignoran (firma estable / compat).
  PERFORM p_sf1_p1, p_sf1_p2, p_sf2_p1, p_sf2_p2,
          p_cl1_p1, p_cl1_p2, p_cl2_p1, p_cl2_p2;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT organizador_id, modalidad, playoff_seeds
    INTO v_organizador, v_modalidad, v_seeds
  FROM public.ligas
  WHERE id = p_liga_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Liga no encontrada';
  END IF;

  IF v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre esta liga';
  END IF;

  IF v_modalidad IS DISTINCT FROM 'parejas_fijas_playoffs' THEN
    RAISE EXCEPTION 'Modalidad incorrecta para playoffs';
  END IF;

  v_canchas := GREATEST(1, COALESCE(p_canchas, 3));

  SELECT COUNT(*)::integer INTO v_regular_done
  FROM public.liga_partidos
  WHERE liga_id = p_liga_id
    AND fase = 'regular'
    AND estado = 'completed';

  SELECT COUNT(*)::integer INTO v_regular_total
  FROM public.liga_partidos
  WHERE liga_id = p_liga_id
    AND fase = 'regular';

  -- N del calendario: equipos distintos en partidos regulares (no SF/CL/FINAL).
  SELECT COUNT(*)::integer INTO v_calendar_n
  FROM (
    SELECT DISTINCT jp.equipo_id
    FROM public.liga_partidos p
    JOIN public.liga_jornada_parejas jp ON jp.id = p.pareja1_id
    WHERE p.liga_id = p_liga_id AND p.fase = 'regular'
    UNION
    SELECT DISTINCT jp.equipo_id
    FROM public.liga_partidos p
    JOIN public.liga_jornada_parejas jp ON jp.id = p.pareja2_id
    WHERE p.liga_id = p_liga_id AND p.fase = 'regular'
  ) calendar_teams;

  IF v_seeds IS NULL THEN
    IF p_seeds IS NULL OR jsonb_typeof(p_seeds) <> 'object' THEN
      RAISE EXCEPTION 'Seeds inválidos';
    END IF;

    -- Contar seeds numéricos consecutivos 1..N (ignora classification_bye)
    v_n := 0;
    LOOP
      v_i := v_n + 1;
      IF p_seeds ? v_i::text
         AND NULLIF(trim(p_seeds ->> v_i::text), '') IS NOT NULL THEN
        v_n := v_i;
      ELSE
        EXIT;
      END IF;
    END LOOP;

    IF v_n < 4 THEN
      RAISE EXCEPTION 'Seeds incompletos (se requieren claves 1..N con N>=4)';
    END IF;

    -- Sin huecos ni duplicados
    FOR v_i IN 1..v_n LOOP
      v_key := trim(p_seeds ->> v_i::text);
      IF v_key IS NULL OR v_key = '' THEN
        RAISE EXCEPTION 'Seed faltante: %', v_i;
      END IF;
      IF v_seen ? v_key THEN
        RAISE EXCEPTION 'Seed duplicado: %', v_key;
      END IF;
      v_seen := v_seen || jsonb_build_object(v_key, true);
    END LOOP;

    IF v_n IS DISTINCT FROM v_calendar_n THEN
      RAISE EXCEPTION
        'Seeds N (%) no coincide con parejas del calendario regular (%)',
        v_n, v_calendar_n;
    END IF;

    v_expected := v_n * (v_n - 1);
    IF v_regular_total IS DISTINCT FROM v_expected THEN
      RAISE EXCEPTION
        'Total regulares (%/%) no cuadra con N(N-1)',
        v_regular_total, v_expected;
    END IF;
    IF v_regular_done IS DISTINCT FROM v_expected THEN
      RAISE EXCEPTION 'Fase regular incompleta (%/%)', v_regular_done, v_expected;
    END IF;

    v_seeds := p_seeds;

    -- Classification BYE si (N-4) impar → seed central
    IF ((v_n - 4) % 2) = 1 THEN
      v_bye_seed := 5 + ((v_n - 4) / 2);
      v_seeds := v_seeds || jsonb_build_object(
        'classification_bye',
        v_seeds ->> v_bye_seed::text
      );
    END IF;

    UPDATE public.ligas
    SET playoff_seeds = v_seeds,
        playoff_seeded_at = now()
    WHERE id = p_liga_id
      AND playoff_seeds IS NULL;

    SELECT playoff_seeds INTO v_seeds
    FROM public.ligas
    WHERE id = p_liga_id;

    IF v_seeds IS NULL THEN
      RAISE EXCEPTION 'No se pudieron congelar seeds';
    END IF;
  ELSE
    -- Seeds ya congelados: contar N desde la fotografía (solo claves 1..N)
    v_n := 0;
    LOOP
      v_i := v_n + 1;
      IF v_seeds ? v_i::text
         AND NULLIF(trim(v_seeds ->> v_i::text), '') IS NOT NULL THEN
        v_n := v_i;
      ELSE
        EXIT;
      END IF;
    END LOOP;
    IF v_n < 4 THEN
      RAISE EXCEPTION 'playoff_seeds congelados inválidos';
    END IF;
  END IF;

  SELECT COALESCE(MAX(j.numero), 0)::integer INTO v_last_regular
  FROM public.liga_jornadas j
  WHERE j.liga_id = p_liga_id
    AND EXISTS (
      SELECT 1
      FROM public.liga_partidos p
      WHERE p.jornada_id = j.id
        AND p.fase = 'regular'
    );

  IF v_last_regular < 1 THEN
    RAISE EXCEPTION 'No hay jornadas regulares';
  END IF;

  v_playoff_jornada := v_last_regular + 1;

  SELECT id INTO v_jornada_id
  FROM public.liga_jornadas
  WHERE liga_id = p_liga_id AND numero = v_playoff_jornada
  LIMIT 1;

  IF v_jornada_id IS NULL THEN
    INSERT INTO public.liga_jornadas (liga_id, numero, estado)
    VALUES (p_liga_id, v_playoff_jornada, 'upcoming')
    RETURNING id INTO v_jornada_id;
  END IF;

  -- Parejas de jornada para todos los seeds 1..N (BYE no juega partido; se registra)
  FOR v_i IN 1..v_n LOOP
    SELECT e.id, e.jugador1_id, e.jugador2_id
      INTO v_equipo_id, v_jugador1_id, v_jugador2_id
    FROM public.liga_equipos e
    WHERE e.liga_id = p_liga_id
      AND e.id::text = (v_seeds ->> v_i::text)
    LIMIT 1;

    IF v_equipo_id IS NULL THEN
      RAISE EXCEPTION 'Equipo seed % no encontrado', v_i;
    END IF;

    SELECT id INTO v_pareja_id
    FROM public.liga_jornada_parejas
    WHERE jornada_id = v_jornada_id AND equipo_id = v_equipo_id
    LIMIT 1;

    IF v_pareja_id IS NULL THEN
      INSERT INTO public.liga_jornada_parejas (
        jornada_id, equipo_id, jugador1_id, jugador2_id
      ) VALUES (
        v_jornada_id, v_equipo_id, v_jugador1_id, v_jugador2_id
      )
      RETURNING id INTO v_pareja_id;
    END IF;

    v_map := v_map || jsonb_build_object(v_equipo_id::text, v_pareja_id::text);
  END LOOP;

  -- Helper inline: insertar partido si slot libre
  -- SF1 = 1v4, SF2 = 2v3
  FOR v_i IN 1..2 LOOP
    IF v_i = 1 THEN
      v_slot := 'SF1'; v_fase := 'semifinal';
      v_seed_home := '1'; v_seed_away := '4';
    ELSE
      v_slot := 'SF2'; v_fase := 'semifinal';
      v_seed_home := '2'; v_seed_away := '3';
    END IF;

    SELECT COUNT(*)::integer INTO v_existing
    FROM public.liga_partidos
    WHERE liga_id = p_liga_id AND bracket_slot = v_slot;

    IF v_existing = 0 THEN
      v_eq1 := (v_seeds ->> v_seed_home)::uuid;
      v_eq2 := (v_seeds ->> v_seed_away)::uuid;
      v_p1 := (v_map ->> v_eq1::text)::uuid;
      v_p2 := (v_map ->> v_eq2::text)::uuid;
      IF v_p1 IS NULL OR v_p2 IS NULL THEN
        RAISE EXCEPTION 'Falta pareja de jornada para slot %', v_slot;
      END IF;
      INSERT INTO public.liga_partidos (
        jornada_id, pareja1_id, pareja2_id, ronda, cancha, estado,
        score_pareja1, score_pareja2, fase, bracket_slot, liga_id
      ) VALUES (
        v_jornada_id, v_p1, v_p2, 1, ((v_i - 1) % v_canchas) + 1, 'upcoming',
        NULL, NULL, v_fase, v_slot, p_liga_id
      );
    END IF;
  END LOOP;

  -- CL extremos: low=5, high=N
  v_low := 5;
  v_high := v_n;
  v_cl := 1;
  WHILE v_low < v_high LOOP
    v_slot := 'CL' || v_cl::text;
    v_fase := 'classification';
    v_seed_home := v_low::text;
    v_seed_away := v_high::text;

    SELECT COUNT(*)::integer INTO v_existing
    FROM public.liga_partidos
    WHERE liga_id = p_liga_id AND bracket_slot = v_slot;

    IF v_existing = 0 THEN
      v_eq1 := (v_seeds ->> v_seed_home)::uuid;
      v_eq2 := (v_seeds ->> v_seed_away)::uuid;
      v_p1 := (v_map ->> v_eq1::text)::uuid;
      v_p2 := (v_map ->> v_eq2::text)::uuid;
      IF v_p1 IS NULL OR v_p2 IS NULL THEN
        RAISE EXCEPTION 'Falta pareja de jornada para slot %', v_slot;
      END IF;
      INSERT INTO public.liga_partidos (
        jornada_id, pareja1_id, pareja2_id, ronda, cancha, estado,
        score_pareja1, score_pareja2, fase, bracket_slot, liga_id
      ) VALUES (
        v_jornada_id, v_p1, v_p2, 1,
        ((1 + v_cl) % v_canchas) + 1, 'upcoming',
        NULL, NULL, v_fase, v_slot, p_liga_id
      );
    END IF;

    v_cl := v_cl + 1;
    v_low := v_low + 1;
    v_high := v_high - 1;
  END LOOP;
  -- Si v_low = v_high: classification BYE (sin partido)

  RETURN jsonb_build_object(
    'ok', true,
    'jornada_id', v_jornada_id,
    'jornada_numero', v_playoff_jornada,
    'team_count', v_n,
    'seeds', v_seeds
  );
END;
$$;


ALTER FUNCTION "public"."liga_playoffs_freeze_and_generate_jornada9"("p_liga_id" "uuid", "p_seeds" "jsonb", "p_sf1_p1" "uuid", "p_sf1_p2" "uuid", "p_sf2_p1" "uuid", "p_sf2_p2" "uuid", "p_cl1_p1" "uuid", "p_cl1_p2" "uuid", "p_cl2_p1" "uuid", "p_cl2_p2" "uuid", "p_canchas" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_coach_student_by_club"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_student_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_target_user record;
  v_jugador record;
  v_existing_link record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo el administrador del club puede autorizar la vinculación de alumnos.');
  END IF;

  -- Verificar que el jugador pertenezca al club
  SELECT id, nombre, email, organizador_id INTO v_jugador
  FROM public.riviera_jugadores
  WHERE id = p_jugador_id AND organizador_id = p_organizador_id;

  IF v_jugador.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El alumno no pertenece a este club.');
  END IF;

  -- Buscar cuenta de usuario por correo verificado
  SELECT id, email, email_confirmed_at INTO v_target_user
  FROM auth.users
  WHERE lower(btrim(email)) = lower(btrim(p_student_email));

  IF v_target_user.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No existe una cuenta registrada con ese correo electrónico.');
  END IF;

  IF v_target_user.email_confirmed_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La cuenta del alumno no ha confirmado su correo electrónico.');
  END IF;

  -- Comprobar si el jugador ya está vinculado a otra cuenta en Coaching
  SELECT auth_user_id, organizador_id INTO v_existing_link
  FROM public.coach_student_account_links
  WHERE jugador_id = p_jugador_id;

  IF v_existing_link.auth_user_id IS NOT NULL THEN
    IF v_existing_link.auth_user_id = v_target_user.id THEN
      RETURN jsonb_build_object('ok', true, 'message', 'Alumno ya vinculado previamente.', 'jugador_id', p_jugador_id, 'nombre', v_jugador.nombre);
    ELSE
      RETURN jsonb_build_object('ok', false, 'error', 'Este perfil deportivo ya se encuentra vinculado a otra cuenta de usuario.');
    END IF;
  END IF;

  -- Comprobar si el jugador ya está asociado a otra cuenta en Rewards
  SELECT auth_user_id INTO v_existing_link
  FROM public.rewards_player_links
  WHERE jugador_id = p_jugador_id;

  IF v_existing_link.auth_user_id IS NOT NULL AND v_existing_link.auth_user_id <> v_target_user.id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Este perfil deportivo ya se encuentra asociado a otra cuenta en el sistema.');
  END IF;

  -- Insertar vínculo con verificación autorizada de club
  INSERT INTO public.coach_student_account_links (
    jugador_id,
    auth_user_id,
    organizador_id,
    verification_method
  ) VALUES (
    p_jugador_id,
    v_target_user.id,
    p_organizador_id,
    'CLUB_ADMIN'
  )
  ON CONFLICT (jugador_id) DO NOTHING;

  RETURN jsonb_build_object(
    'ok', true,
    'jugador_id', p_jugador_id,
    'auth_user_id', v_target_user.id,
    'nombre', v_jugador.nombre,
    'message', 'Alumno vinculado exitosamente por el club.'
  );
END;
$$;


ALTER FUNCTION "public"."link_coach_student_by_club"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_student_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_existing_coach_to_club"("p_coach_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org_id uuid := auth.uid();
  v_membership_id uuid;
  v_status text;
  v_coach record;
  v_has_access boolean;
  v_existing record;
  v_previous text;
BEGIN
  IF v_org_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Autenticación requerida');
  END IF;

  v_has_access := public.is_master_admin() OR EXISTS (
    SELECT 1 FROM public.organizador_game_modes ogm
    WHERE ogm.organizador_id = v_org_id
      AND ogm.coaching_enabled = true
  );

  IF NOT v_has_access THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No autorizado: el club no tiene habilitado Riviera Coaching o carece de permisos de organizador.'
    );
  END IF;

  SELECT id, auth_user_id, coach_code, nombre, foto_url, bio, especialidades, fuerzas
  INTO v_coach
  FROM public.riviera_coaches
  WHERE id = p_coach_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Coach no encontrado');
  END IF;

  IF v_coach.auth_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'status', 'PENDING',
      'error', 'Este coach todavía no tiene credenciales. Configúralas desde el club para habilitarlo.'
    );
  END IF;

  SELECT id, status INTO v_existing
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id
    AND organizador_id = v_org_id;

  IF FOUND AND v_existing.status = 'ACTIVE' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_member', true,
      'membership_id', v_existing.id,
      'status', 'ACTIVE',
      'message', 'El coach ya es miembro activo de tu club.'
    );
  END IF;

  v_previous := CASE WHEN FOUND THEN v_existing.status ELSE NULL END;

  INSERT INTO public.coach_club_memberships (
    coach_id,
    organizador_id,
    status,
    invited_by,
    invited_at,
    activated_at,
    deactivated_at,
    cancelled_at,
    updated_at
  )
  VALUES (
    p_coach_id,
    v_org_id,
    'ACTIVE',
    v_org_id,
    now(),
    now(),
    NULL,
    NULL,
    now()
  )
  ON CONFLICT (coach_id, organizador_id) DO UPDATE
  SET
    status = 'ACTIVE',
    activated_at = COALESCE(public.coach_club_memberships.activated_at, now()),
    deactivated_at = NULL,
    cancelled_at = NULL,
    removed_at = NULL,
    updated_at = now()
  RETURNING id, status INTO v_membership_id, v_status;

  INSERT INTO public.coach_club_membership_audit_log (
    membership_id, coach_id, organizador_id, action, performed_by,
    previous_status, new_status, details
  ) VALUES (
    v_membership_id, p_coach_id, v_org_id,
    CASE WHEN v_previous IS NULL THEN 'CLUB_REGISTER' ELSE 'CLUB_ACTIVATE' END,
    v_org_id,
    v_previous, 'ACTIVE',
    jsonb_build_object('access', 'club_controlled')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'already_member', false,
    'membership_id', v_membership_id,
    'status', 'ACTIVE',
    'message', 'Coach activo en tu club. Puede iniciar sesión con sus credenciales.',
    'coach', jsonb_build_object(
      'id', v_coach.id,
      'coach_code', v_coach.coach_code,
      'nombre', v_coach.nombre,
      'foto_url', v_coach.foto_url,
      'bio', v_coach.bio,
      'especialidades', v_coach.especialidades,
      'fuerzas', v_coach.fuerzas
    )
  );
END;
$$;


ALTER FUNCTION "public"."link_existing_coach_to_club"("p_coach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_player_to_coach_by_riviera_id"("p_coach_id" "uuid", "p_riviera_id" "text", "p_organizador_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'ok', false,
    'error', 'La asignación de alumnos es responsabilidad exclusiva de la administración del club. Contacta al administrador del club para asignar alumnos y paquetes de clases.'
  );
