ALTER FUNCTION "public"."link_player_to_coach_by_riviera_id"("p_coach_id" "uuid", "p_riviera_id" "text", "p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_student_by_riviera_id"("p_riviera_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_caller uuid := auth.uid();
  v_caller_email text;
  v_email_confirmed_at timestamptz;
  v_norm_id text := upper(btrim(COALESCE(p_riviera_id, '')));
  v_jugador record;
  v_existing_auth uuid;
  v_email_collision_count integer := 0;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_norm_id = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El Riviera ID es requerido.');
  END IF;

  IF v_norm_id !~ '^RIV-[0-9]{5,8}$' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Formato de Riviera ID inválido. Debe tener la estructura RIV-########'
    );
  END IF;

  -- Obtener correo confirmado del usuario llamante
  SELECT lower(btrim(email)), email_confirmed_at
  INTO v_caller_email, v_email_confirmed_at
  FROM auth.users
  WHERE id = v_caller;

  IF v_caller_email IS NULL OR v_caller_email = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Tu cuenta no tiene un correo electrónico válido registrado.');
  END IF;

  IF v_email_confirmed_at IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Tu cuenta de correo no ha sido verificada. Confirma tu correo antes de vincular tu credencial.'
    );
  END IF;

  -- Buscar perfil deportivo canónico por Riviera ID
  SELECT rj.id, rj.nombre, rj.email, rj.organizador_id, i.riviera_id
  INTO v_jugador
  FROM public.riviera_official_player_identity i
  JOIN public.riviera_jugadores rj ON rj.id = i.canonical_riviera_jugador_id
  WHERE upper(btrim(i.riviera_id)) = v_norm_id
  LIMIT 1;

  IF v_jugador.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No se encontró un perfil deportivo oficial con ese Riviera ID.'
    );
  END IF;

  -- REGLA DE SEGURIDAD 1: Si ya está vinculado a otro usuario, NUNCA reemplazar propietario (Anti-hijack)
  SELECT auth_user_id INTO v_existing_auth
  FROM public.coach_student_account_links
  WHERE jugador_id = v_jugador.id;

  IF v_existing_auth IS NOT NULL THEN
    IF v_existing_auth = v_caller THEN
      RETURN jsonb_build_object(
        'ok', true,
        'jugador_id', v_jugador.id,
        'nombre', v_jugador.nombre,
        'riviera_id', v_jugador.riviera_id,
        'message', 'Perfil ya vinculado previamente.'
      );
    ELSE
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Este perfil ya se encuentra vinculado a otra cuenta de usuario. No se puede transferir sin autorización del club.'
      );
    END IF;
  END IF;

  -- Comprobar si está asociado a otro usuario en Rewards
  SELECT auth_user_id INTO v_existing_auth
  FROM public.rewards_player_links
  WHERE jugador_id = v_jugador.id;

  IF v_existing_auth IS NOT NULL AND v_existing_auth <> v_caller THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Este perfil ya se encuentra asociado a otra cuenta en el sistema.'
    );
  END IF;

  -- REGLA DE SEGURIDAD 2: Si el perfil deportivo NO tiene correo registrado en el club,
  -- NO se puede reclamar por el cliente; exige vinculación autorizada del club.
  IF v_jugador.email IS NULL OR btrim(v_jugador.email) = '' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Este perfil no cuenta con correo registrado por el club. Por seguridad, solicita a la administración de tu club la vinculación autorizada de tu cuenta.'
    );
  END IF;

  -- REGLA DE SEGURIDAD 3: El correo registrado en el club DEBE coincidir con el correo verificado del usuario
  IF lower(btrim(v_jugador.email)) <> v_caller_email THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El correo de tu cuenta no coincide con el registrado en el club para este Riviera ID.'
    );
  END IF;

  -- REGLA DE SEGURIDAD 4: Colisión de correos en el mismo club (dos personas con mismo correo)
  SELECT count(*) INTO v_email_collision_count
  FROM public.riviera_jugadores
  WHERE organizador_id = v_jugador.organizador_id
    AND lower(btrim(email)) = v_caller_email
    AND estado = 'activo';

  IF v_email_collision_count > 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Existen múltiples perfiles con este correo en el club. Solicita a tu club una vinculación autorizada individual para evitar ambigüedades.'
    );
  END IF;

  -- Registrar vínculo EXCLUSIVAMENTE en coach_student_account_links (sin tocar rewards_player_links)
  INSERT INTO public.coach_student_account_links (
    jugador_id, auth_user_id, organizador_id, verification_method
  ) VALUES (
    v_jugador.id, v_caller, v_jugador.organizador_id, 'VERIFIED_EMAIL_MATCH'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'jugador_id', v_jugador.id,
    'nombre', v_jugador.nombre,
    'riviera_id', v_jugador.riviera_id,
    'message', 'Perfil deportivo vinculado exitosamente.'
  );
END;
$_$;


ALTER FUNCTION "public"."link_student_by_riviera_id"("p_riviera_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_liga_sustituciones_publicas"("p_liga_id" "uuid") RETURNS TABLE("from_jugador_id" "uuid", "to_jugador_id" "uuid", "from_nombre" "text", "to_nombre" "text", "jornada_efectiva_numero" integer, "puntos_heredados" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_allowed boolean := false;
BEGIN
  IF p_liga_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COALESCE(l.es_publica, false) = true
    OR COALESCE(public.is_master_admin(), false)
    OR (v_caller IS NOT NULL AND l.organizador_id = v_caller)
  INTO v_allowed
  FROM public.ligas l
  WHERE l.id = p_liga_id;

  IF NOT COALESCE(v_allowed, false) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    s.from_jugador_id,
    s.to_jugador_id,
    fj.nombre::text AS from_nombre,
    tj.nombre::text AS to_nombre,
    s.jornada_efectiva_numero,
    s.puntos_heredados
  FROM public.liga_sustituciones s
  LEFT JOIN public.liga_jugadores fj ON fj.id = s.from_jugador_id
  LEFT JOIN public.liga_jugadores tj ON tj.id = s.to_jugador_id
  WHERE s.liga_id = p_liga_id
    AND s.reverted_at IS NULL
  ORDER BY s.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."list_liga_sustituciones_publicas"("p_liga_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_liga_sustituciones_publicas"("p_liga_id" "uuid") IS 'Sustituciones visibles en ranking/público: jugadores, jornada de ingreso y puntos heredados. Sin motivos ni actor_id/idempotency_key.';



CREATE OR REPLACE FUNCTION "public"."list_open_game_registration_entries"("p_mode_type" "text", "p_entity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mode text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticación requerida'; END IF;
  v_mode := public._assert_convocatoria_mode_allowed(p_mode_type);
  IF public._open_reg_organizer_id(v_mode, p_entity_id) <> v_uid THEN
    RAISE EXCEPTION 'Sin permiso';
  END IF;

  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
      'id', e.id, 'status', e.status, 'riviera_id', e.riviera_id,
      'riviera_jugador_id', e.riviera_jugador_id,
      'nombre', coalesce(e.display_name_snapshot, rj.nombre),
      'foto_url', rj.foto_url, 'categoria', rj.categoria, 'rating', rj.rating,
      'created_at', e.created_at, 'confirmed_at', e.confirmed_at, 'cancelled_at', e.cancelled_at
    ) ORDER BY e.created_at)
    FROM public.tournament_open_registration_entries e
    JOIN public.tournament_open_registration r ON r.id = e.registration_id
    JOIN public.riviera_jugadores rj ON rj.id = e.riviera_jugador_id
    WHERE r.mode_type = v_mode AND r.entity_id = p_entity_id
  ), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."list_open_game_registration_entries"("p_mode_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_organizer_memberships"() RETURNS TABLE("membership_id" "uuid", "source_jugador_id" "uuid", "local_jugador_id" "uuid", "riviera_id" "text", "display_name" "text", "registration_organizer_id" "uuid", "joined_at" timestamp with time zone, "joined_via" "text", "access_type" "text", "is_public_ranking" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_grantee uuid := auth.uid();
BEGIN
  IF v_grantee IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  RETURN QUERY
  SELECT
    opa.id AS membership_id,
    opa.jugador_id AS source_jugador_id,
    opa.local_jugador_id,
    i.riviera_id,
    coalesce(rj_local.nombre, rj_source.nombre)::text AS display_name,
    opa.owner_organizador_id AS registration_organizer_id,
    opa.joined_at,
    opa.joined_via,
    opa.access_type,
    opa.is_public_ranking
  FROM public.organizer_player_access opa
  JOIN public.riviera_jugadores rj_source
    ON rj_source.id = opa.jugador_id
  LEFT JOIN public.riviera_jugadores rj_local
    ON rj_local.id = opa.local_jugador_id
  LEFT JOIN public.riviera_official_player_identity i
    ON i.canonical_riviera_jugador_id = opa.jugador_id
  WHERE opa.grantee_organizer_id = v_grantee
    AND opa.is_active = true
  ORDER BY opa.joined_at DESC NULLS LAST, opa.created_at DESC;
END;
$$;


