      SELECT 1
      FROM public.riviera_official_points_ledger l
      WHERE l.participacion_id = jp.id
    )
  ORDER BY jp.fecha DESC, jp.created_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 5000), 5000));
