CREATE OR REPLACE FUNCTION "public"."log_atleta_skill_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO atleta_skill_historial (skill_id, usuario_id, estado_anterior, estado_nuevo, notas)
    VALUES (NEW.id, NEW.usuario_id, NULL, NEW.estado, NEW.notas);
    RETURN NEW;
  END IF;

  IF OLD.estado IS DISTINCT FROM NEW.estado OR OLD.notas IS DISTINCT FROM NEW.notas THEN
    NEW.updated_at := now();
    INSERT INTO atleta_skill_historial (skill_id, usuario_id, estado_anterior, estado_nuevo, notas)
    VALUES (NEW.id, NEW.usuario_id, OLD.estado, NEW.estado, NEW.notas);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_atleta_skill_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lookup_coach_for_invitation"("p_query" "text") RETURNS TABLE("coach_id" "uuid", "coach_code" "text", "nombre" "text", "foto_url" "text", "bio" "text", "especialidades" "text"[], "fuerzas" "text"[], "already_member" boolean, "membership_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := auth.uid();
  v_normalized text := lower(btrim(COALESCE(p_query, '')));
  v_has_access boolean;
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  v_has_access := public.is_master_admin() OR EXISTS (
    SELECT 1 FROM public.organizador_game_modes ogm
    WHERE ogm.organizador_id = v_org_id
      AND ogm.coaching_enabled = true
  );

  IF NOT v_has_access THEN
    RAISE EXCEPTION 'No autorizado: el club no tiene habilitado Riviera Coaching o carece de permisos de organizador.';
  END IF;

  IF v_normalized = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    c.id AS coach_id,
    c.coach_code,
    c.nombre,
    c.foto_url,
    c.bio,
    c.especialidades,
    c.fuerzas,
    EXISTS (
      SELECT 1 FROM public.coach_club_memberships m
      WHERE m.coach_id = c.id
        AND m.organizador_id = v_org_id
        AND m.status = 'ACTIVE'
    ) AS already_member,
    (
      SELECT m.status FROM public.coach_club_memberships m
      WHERE m.coach_id = c.id
        AND m.organizador_id = v_org_id
      LIMIT 1
    ) AS membership_status
  FROM public.riviera_coaches c
  LEFT JOIN auth.users u ON u.id = c.auth_user_id
  WHERE lower(c.coach_code) = v_normalized
     OR lower(u.email) = v_normalized
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."lookup_coach_for_invitation"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lookup_student_by_riviera_id"("p_organizador_id" "uuid", "p_riviera_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_norm_id text := upper(btrim(COALESCE(p_riviera_id, '')));
  v_student record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  -- 1. Comprobar que el solicitante sea administrador autorizado del club o Master Admin
  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No tienes permisos para buscar alumnos en este club.'
    );
  END IF;

  -- 2. Comprobar que el club tiene el servicio de Coaching habilitado
  IF NOT EXISTS (
    SELECT 1 FROM public.organizador_game_modes
    WHERE organizador_id = p_organizador_id AND coaching_enabled = true
  ) AND NOT v_is_master THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El club no tiene habilitado el módulo de Coaching.'
    );
  END IF;

  -- 3. Validar formato canónico de Riviera ID
  IF v_norm_id !~ '^RIV-[0-9]{5,8}$' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Formato de Riviera ID inválido. Debe tener la estructura RIV-######## (ej. RIV-00000278).'
    );
  END IF;

  -- 4. Búsqueda canónica del jugador oficial
  SELECT
    rj.id,
    rj.nombre,
    rj.foto_url,
    rj.categoria,
    rj.genero,
    rj.club as club_nombre,
    i.riviera_id
  INTO v_student
  FROM public.riviera_official_player_identity i
  JOIN public.riviera_jugadores rj ON rj.id = i.canonical_riviera_jugador_id
  WHERE upper(btrim(i.riviera_id)) = v_norm_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No se encontró ningún jugador registrado con el Riviera ID ' || v_norm_id || '.'
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'student', jsonb_build_object(
      'id', v_student.id,
      'nombre', v_student.nombre,
      'fotoUrl', v_student.foto_url,
      'categoria', v_student.categoria,
      'genero', v_student.genero,
      'clubNombre', v_student.club_nombre,
      'rivieraId', v_student.riviera_id
    )
  );
END;
$_$;


ALTER FUNCTION "public"."lookup_student_by_riviera_id"("p_organizador_id" "uuid", "p_riviera_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pausar_bienvenida_pendiente_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_org uuid;
  v_count integer := 0;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'anon');
  END IF;

  SELECT organizador_id INTO v_org FROM public.ligas WHERE id = p_liga_id;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'liga_no_encontrada');
  END IF;
  IF v_org IS DISTINCT FROM v_caller AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'sin_permiso');
  END IF;

  UPDATE public.liga_notificaciones_queue
    SET estado = 'pausado',
        motivo = 'deshabilitado',
        updated_at = now()
    WHERE liga_id = p_liga_id
      AND liga_jugador_id = p_liga_jugador_id
      AND tipo = 'bienvenida'
      AND estado = 'pendiente';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'pausadas', v_count);
END;
$$;


ALTER FUNCTION "public"."pausar_bienvenida_pendiente_liga"("p_liga_id" "uuid", "p_liga_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_riviera_id_for_open_registration"("p_slug" "text", "p_riviera_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cfg public.tournament_open_registration;
  v_norm text;
  v_identity record;
  v_rj public.riviera_jugadores%ROWTYPE;
BEGIN
  IF public._riviera_id_lookup_rate_limited('preview', 30, interval '10 minutes') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rate_limited');
  END IF;

  SELECT * INTO v_cfg FROM public.tournament_open_registration
  WHERE public_slug = trim(coalesce(p_slug, '')) AND enabled = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  v_norm := public._normalize_riviera_id_loose(p_riviera_id);
  IF v_norm IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_riviera_id');
  END IF;

  SELECT * INTO v_identity FROM public._resolve_identity_by_riviera_id(v_norm);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'riviera_id_not_found', 'riviera_id', v_norm);
  END IF;

  SELECT * INTO v_rj FROM public.riviera_jugadores WHERE id = v_identity.canonical_riviera_jugador_id;

  RETURN jsonb_build_object(
    'ok', true,
    'riviera_id', v_identity.riviera_id,
    'jugador_id', v_identity.canonical_riviera_jugador_id,
    'nombre', v_identity.display_name,
    'foto_url', CASE WHEN v_cfg.display_photo THEN v_rj.foto_url ELSE NULL END,
    'rating', CASE WHEN v_cfg.display_rating THEN v_rj.rating ELSE NULL END,
    'categoria', v_rj.categoria,
    'club_origen_id', v_identity.registration_organizer_id
  );
END;
$$;


ALTER FUNCTION "public"."preview_riviera_id_for_open_registration"("p_slug" "text", "p_riviera_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."probe_delete_riviera_jugador_auth"("p_organizador_id" "uuid", "p_jugador_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_raw uuid := auth.uid();
  v_jwt_sub text := current_setting('request.jwt.claim.sub', true);
  v_claims_sub text :=
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub';
  v_auth uuid := COALESCE(
    v_auth_raw,
    NULLIF(v_jwt_sub, '')::uuid,
    NULLIF(v_claims_sub, '')::uuid
  );
  v_row_org uuid;
BEGIN
  IF p_jugador_id IS NOT NULL THEN
    SELECT rj.organizador_id INTO v_row_org
    FROM public.riviera_jugadores rj
    WHERE rj.id = p_jugador_id;
  END IF;

  RETURN jsonb_build_object(
    'auth_uid_visto', v_auth,
    'auth_uid_raw', v_auth_raw,
    'jwt_claim_sub', NULLIF(v_jwt_sub, ''),
    'jwt_claims_sub', NULLIF(v_claims_sub, ''),
    'p_organizador_recibido', p_organizador_id,
    'coinciden', (v_auth IS NOT NULL AND v_auth = p_organizador_id),
    'jugador_id', p_jugador_id,
    'jugador_organizador_id', v_row_org,
    'jugador_org_coincide_auth',
      (v_auth IS NOT NULL AND v_row_org IS NOT NULL AND v_auth = v_row_org),
    'role', NULLIF(current_setting('request.jwt.claim.role', true), ''),
    'nota',
      'Si auth_uid_visto es null desde la app, el Authorization Bearer no llega al PostgREST. '
      'Si SQL Editor da null, es normal.'
  );
END;
$$;


ALTER FUNCTION "public"."probe_delete_riviera_jugador_auth"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_tournament_open_registration_entry"("p_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_entry public.tournament_open_registration_entries%ROWTYPE;
  v_cfg public.tournament_open_registration;
  v_confirmed int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticación requerida'; END IF;

  SELECT * INTO v_entry FROM public.tournament_open_registration_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;

  SELECT * INTO v_cfg FROM public.tournament_open_registration WHERE id = v_entry.registration_id FOR UPDATE;
  IF public._open_reg_organizer_id(v_cfg.mode_type, v_cfg.entity_id) IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'Sin permiso';
  END IF;

  IF v_entry.status NOT IN ('waitlist', 'pending_approval') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_status');
  END IF;

  SELECT count(*)::int INTO v_confirmed
  FROM public.tournament_open_registration_entries
  WHERE registration_id = v_cfg.id AND status = 'confirmed';

  IF v_confirmed >= v_cfg.capacity THEN
    RETURN jsonb_build_object('ok', false, 'error', 'full');
  END IF;

  UPDATE public.tournament_open_registration_entries
  SET status = 'confirmed', confirmed_at = now(), updated_at = now()
  WHERE id = v_entry.id;

  IF v_cfg.mode_type = 'americano' THEN
    PERFORM public._open_reg_sync_americano_roster(v_cfg.entity_id);
  ELSIF v_cfg.mode_type = 'duelo_2v2' THEN
    PERFORM public._open_reg_sync_duelo_slots(v_cfg.entity_id);
  END IF;

  RETURN jsonb_build_object('ok', true, 'entry_id', v_entry.id, 'status', 'confirmed');
END;
$$;


ALTER FUNCTION "public"."promote_tournament_open_registration_entry"("p_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reactivate_student_access"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_authorized boolean;
  v_updated integer := 0;
  v_exists boolean := false;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  v_is_authorized := public.is_master_admin() OR (p_organizador_id = v_caller);
  IF NOT v_is_authorized THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autorizado');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.coach_student_account_links
    WHERE organizador_id = p_organizador_id
      AND jugador_id = p_jugador_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Este alumno todavía no tiene una cuenta que reactivar. Envíale la invitación.'
    );
  END IF;

  UPDATE public.coach_student_account_links AS al
  SET is_active = true,
      deactivated_at = NULL,
      deactivated_by = NULL,
      updated_at = now()
  WHERE al.organizador_id = p_organizador_id
    AND al.jugador_id = p_jugador_id
    AND EXISTS (
      SELECT 1
      FROM auth.users u
      WHERE u.id = al.auth_user_id
        AND u.encrypted_password IS NOT NULL
        AND length(u.encrypted_password) > 0
    );

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated = 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El alumno todavía no creó su contraseña. Reenvía la invitación para que active su cuenta.'
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'ACTIVE',
    'message', 'Acceso de alumno reactivado en este club.'
  );
END;
$$;


ALTER FUNCTION "public"."reactivate_student_access"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reassign_student_coach"("p_organizador_id" "uuid", "p_student_id" "uuid", "p_from_coach_id" "uuid", "p_to_coach_id" "uuid", "p_transfer_balance" boolean DEFAULT true, "p_reason" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_expected_balance" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_existing_op record;
  v_to_membership record;
  v_source_rel record;
  v_source_bal record;
  v_target_rel record;
  v_transfer_amount integer := 0;
  v_target_new_balance integer := 0;
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autorizado: solo el club puede reasignar alumnos');
  END IF;

  IF p_from_coach_id = p_to_coach_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El coach destino debe ser diferente al actual');
  END IF;

  IF v_trimmed_key IS NOT NULL THEN
    SELECT * INTO v_existing_op
    FROM public.coach_reassignment_operations
    WHERE idempotency_key = v_trimmed_key
    LIMIT 1;

    IF v_existing_op.id IS NOT NULL THEN
      IF v_existing_op.organizador_id <> p_organizador_id
         OR v_existing_op.student_id <> p_student_id
         OR v_existing_op.from_coach_id <> p_from_coach_id
         OR v_existing_op.to_coach_id <> p_to_coach_id
         OR v_existing_op.authorized_by <> v_caller THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de clave de idempotencia: los parámetros no coinciden con la operación original.',
          'code', 'IDEMPOTENCY_MISMATCH'
        );
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'from_coach_id', p_from_coach_id,
        'to_coach_id', p_to_coach_id,
        'student_id', p_student_id,
        'target_relationship_id', v_existing_op.target_relationship_id,
        'transferred_classes', v_existing_op.transferred_classes,
        'target_new_balance', v_existing_op.target_new_balance,
        'idempotent', true,
        'message', 'Reasignación completada previamente (idempotente)'
      );
    END IF;
  END IF;

  SELECT * INTO v_to_membership
  FROM public.coach_club_memberships
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_to_coach_id;

  IF v_to_membership.coach_id IS NULL OR v_to_membership.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El coach de destino no tiene una membresía activa en este club');
  END IF;

  SELECT * INTO v_source_rel
  FROM public.coach_player_relationships
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_from_coach_id
    AND jugador_id = p_student_id
  FOR UPDATE;

  IF v_source_rel.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No existe relación activa con el coach de origen');
  END IF;

  SELECT * INTO v_source_bal
  FROM public.coach_player_class_balances
  WHERE relationship_id = v_source_rel.id
  FOR UPDATE;

  IF p_transfer_balance AND v_source_bal.relationship_id IS NOT NULL THEN
    v_transfer_amount := GREATEST(0, COALESCE(v_source_bal.balance_classes, 0));
  END IF;

  UPDATE public.coach_player_relationships
  SET status = 'ENDED', ended_at = v_now, updated_at = v_now, is_primary = false
  WHERE id = v_source_rel.id;

  IF v_transfer_amount > 0 THEN
    UPDATE public.coach_player_class_balances
    SET balance_classes = 0, updated_at = v_now
    WHERE relationship_id = v_source_rel.id;

    INSERT INTO public.coach_class_ledger (
      relationship_id, organizador_id, coach_id, jugador_id, delta, tipo, notas, idempotency_key, recorded_by, created_at
    ) VALUES (
      v_source_rel.id, p_organizador_id, p_from_coach_id, p_student_id, -v_transfer_amount, 'TRANSFER_OUT',
      'Transferencia por cambio de coach', v_trimmed_key, v_caller, v_now
    );
  END IF;

  INSERT INTO public.coach_player_relationships (
    organizador_id, coach_id, jugador_id, status, is_primary, created_at, updated_at
  ) VALUES (
    p_organizador_id, p_to_coach_id, p_student_id, 'ACTIVE', true, v_now, v_now
  ) ON CONFLICT (organizador_id, coach_id, jugador_id) DO UPDATE
  SET status = 'ACTIVE', ended_at = NULL, is_primary = true, updated_at = v_now
  RETURNING * INTO v_target_rel;

  INSERT INTO public.coach_player_class_balances (
    relationship_id, organizador_id, coach_id, jugador_id, balance_classes, total_classes_given, updated_at
  ) VALUES (
    v_target_rel.id, p_organizador_id, p_to_coach_id, p_student_id, v_transfer_amount, 0, v_now
  ) ON CONFLICT (relationship_id) DO UPDATE
  SET balance_classes = public.coach_player_class_balances.balance_classes + v_transfer_amount, updated_at = v_now
  RETURNING balance_classes INTO v_target_new_balance;

  IF v_transfer_amount > 0 THEN
    INSERT INTO public.coach_class_ledger (
      relationship_id, organizador_id, coach_id, jugador_id, delta, tipo, notas, idempotency_key, recorded_by, created_at
    ) VALUES (
      v_target_rel.id, p_organizador_id, p_to_coach_id, p_student_id, v_transfer_amount, 'TRANSFER_IN',
      'Recepción de saldo por cambio de coach', v_trimmed_key, v_caller, v_now
    );
  END IF;

  IF v_trimmed_key IS NOT NULL THEN
    INSERT INTO public.coach_reassignment_operations (
      idempotency_key, organizador_id, student_id, from_coach_id, to_coach_id, authorized_by,
      source_relationship_id, target_relationship_id, transferred_classes, target_new_balance, created_at
    ) VALUES (
      v_trimmed_key, p_organizador_id, p_student_id, p_from_coach_id, p_to_coach_id, v_caller,
      v_source_rel.id, v_target_rel.id, v_transfer_amount, v_target_new_balance, v_now
    ) ON CONFLICT DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'from_coach_id', p_from_coach_id,
    'to_coach_id', p_to_coach_id,
    'student_id', p_student_id,
    'target_relationship_id', v_target_rel.id,
    'transferred_classes', v_transfer_amount,
    'target_new_balance', v_target_new_balance,
    'idempotent', false,
    'message', 'Alumno reasignado exitosamente con transferencia de ' || v_transfer_amount || ' clases'
  );
END;
$$;


ALTER FUNCTION "public"."reassign_student_coach"("p_organizador_id" "uuid", "p_student_id" "uuid", "p_from_coach_id" "uuid", "p_to_coach_id" "uuid", "p_transfer_balance" boolean, "p_reason" "text", "p_idempotency_key" "text", "p_expected_balance" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reassign_tournament_match_rounds_if_unscored"("p_tournament_id" "uuid", "p_patches" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_scored_matches int := 0;
  v_games_count int := 0;
  v_existing int := 0;
  v_updated int := 0;
  v_row jsonb;
  v_match_id uuid;
  v_round int;
  v_court int;
  v_found int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'auth_required',
      'message', 'Debes iniciar sesión para reasignar rondas.'
    );
  END IF;

  SELECT t.user_id INTO v_owner
  FROM public.tournaments t
  WHERE t.id = p_tournament_id
  FOR UPDATE;

  IF v_owner IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'tournament_not_found',
      'message', 'Reta no encontrada.'
    );
  END IF;

  IF v_owner IS DISTINCT FROM v_uid AND NOT public.is_master_admin() THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'forbidden',
      'message', 'Solo el organizador (o admin maestro) puede reasignar rondas.'
    );
  END IF;

  IF p_patches IS NULL OR jsonb_typeof(p_patches) <> 'array' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_payload',
      'message', 'p_patches debe ser un arreglo JSON.'
    );
  END IF;

  -- Lock concurrente de todos los partidos del torneo.
  PERFORM 1
  FROM public.matches m
  WHERE m.tournament_id = p_tournament_id
  FOR UPDATE;

  SELECT count(*)::int INTO v_existing
  FROM public.matches m
  WHERE m.tournament_id = p_tournament_id;

  IF v_existing = 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'no_matches',
      'message', 'La reta no tiene partidos para reasignar.'
    );
  END IF;

  IF jsonb_array_length(p_patches) <> v_existing THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'patch_count_mismatch',
      'message', format(
        'Se esperaban %s patches (uno por partido); llegaron %s.',
        v_existing,
        jsonb_array_length(p_patches)
      ),
      'existing_matches', v_existing
    );
  END IF;

  SELECT count(*)::int INTO v_scored_matches
  FROM public.matches m
  WHERE m.tournament_id = p_tournament_id
    AND (
      m.status = 'finished'
      OR m.pair1_score IS NOT NULL
      OR m.pair2_score IS NOT NULL
    );

  SELECT count(*)::int INTO v_games_count
  FROM public.games g
  WHERE g.match_id IN (
    SELECT m.id FROM public.matches m WHERE m.tournament_id = p_tournament_id
  );

  IF v_scored_matches > 0 OR v_games_count > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'has_results',
      'message', format(
        'Hay resultados (matches=%s, games=%s). No se reasignaron rondas.',
        v_scored_matches,
        v_games_count
      ),
      'scored_matches', v_scored_matches,
      'games_count', v_games_count
    );
  END IF;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_patches)
  LOOP
    v_match_id := (v_row->>'id')::uuid;
    v_round := (v_row->>'round')::int;
    v_court := (v_row->>'court')::int;

    IF v_match_id IS NULL OR v_round IS NULL OR v_court IS NULL THEN
      RAISE EXCEPTION 'patch_invalid: id/round/court requeridos';
    END IF;

    IF v_round < 1 OR v_court < 1 THEN
      RAISE EXCEPTION 'patch_invalid: round/court deben ser >= 1';
    END IF;

    UPDATE public.matches m
    SET round = v_round,
        court = v_court
    WHERE m.id = v_match_id
      AND m.tournament_id = p_tournament_id;

    GET DIAGNOSTICS v_found = ROW_COUNT;
    IF v_found <> 1 THEN
      RAISE EXCEPTION 'patch_orphan: match % no pertenece al torneo', v_match_id;
    END IF;

    v_updated := v_updated + 1;
  END LOOP;

  IF v_updated <> v_existing THEN
    RAISE EXCEPTION 'update_incomplete: updated=% existing=%', v_updated, v_existing;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'updated', v_updated,
    'tournament_id', p_tournament_id
  );
END;
$$;


ALTER FUNCTION "public"."reassign_tournament_match_rounds_if_unscored"("p_tournament_id" "uuid", "p_patches" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reassign_tournament_match_rounds_if_unscored"("p_tournament_id" "uuid", "p_patches" "jsonb") IS 'Reasigna round/court de matches existentes sin borrar IDs; aborta si hay marcadores o games.';



CREATE OR REPLACE FUNCTION "public"."reconciliar_torneo_express_grupo"("p_grupo_id" "uuid", "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_torneo_id uuid;
  v_guard jsonb;
  v_version_guard jsonb;
  v_created integer := 0;
  v_dropped integer := 0;
  v_version integer;
  v_max_orden integer;
  v_max_ronda integer;
BEGIN
  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;
  SELECT torneo_id INTO v_torneo_id
  FROM public.torneo_express_grupos WHERE id = p_grupo_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  v_guard := public.te_lock_categoria_editable(v_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    IF (v_guard ->> 'error') IN ('TOURNAMENT_NOT_EDITABLE', 'ELIMINATORIA_EXISTS') THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'GROUP_NOT_EDITABLE', 'reason', v_guard ->> 'error'
      );
    END IF;
    RETURN v_guard;
  END IF;

  PERFORM 1 FROM public.torneo_express_grupos WHERE id = p_grupo_id FOR UPDATE;
  v_version_guard := public.te_grupo_version_ok(p_grupo_id, p_expected_version);
  IF NOT (v_version_guard ->> 'ok')::boolean THEN
    RETURN v_version_guard;
  END IF;

  PERFORM 1
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = p_grupo_id
  ORDER BY pareja_id
  FOR UPDATE;

  PERFORM 1
  FROM public.torneo_express_partidos
  WHERE grupo_id = p_grupo_id
  ORDER BY id
  FOR UPDATE;

  DROP TABLE IF EXISTS te_reconcile_slots;
  DROP TABLE IF EXISTS te_reconcile_required;
  CREATE TEMP TABLE te_reconcile_slots (
    pareja_id uuid PRIMARY KEY,
    lineage uuid[] NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO te_reconcile_slots (pareja_id, lineage)
  SELECT pareja_id, pareja_previa_ids || ARRAY[pareja_id]
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = p_grupo_id AND activa;

  CREATE TEMP TABLE te_reconcile_required (
    left_id uuid NOT NULL,
    right_id uuid NOT NULL,
    matchup text NOT NULL,
    PRIMARY KEY (left_id, right_id)
  ) ON COMMIT DROP;

  INSERT INTO te_reconcile_required (left_id, right_id, matchup)
  SELECT a.pareja_id, b.pareja_id, public.te_matchup_key(a.pareja_id, b.pareja_id)
  FROM te_reconcile_slots a
  JOIN te_reconcile_slots b ON a.pareja_id < b.pareja_id
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    JOIN te_reconcile_slots sa
      ON p.pareja_local_id = ANY (sa.lineage)
    JOIN te_reconcile_slots sb
      ON p.pareja_visitante_id = ANY (sb.lineage)
    WHERE p.grupo_id = p_grupo_id
      AND sa.pareja_id <> sb.pareja_id
      AND (
        (sa.pareja_id = a.pareja_id AND sb.pareja_id = b.pareja_id)
        OR (sa.pareja_id = b.pareja_id AND sb.pareja_id = a.pareja_id)
      )
      AND public.te_partido_tiene_historial(
        p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
      )
  );

  DELETE FROM public.torneo_express_partidos p
  WHERE p.grupo_id = p_grupo_id
    AND NOT public.te_partido_tiene_historial(
      p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
    )
    AND NOT EXISTS (
      SELECT 1 FROM te_reconcile_required r
      WHERE r.matchup = public.te_matchup_key(p.pareja_local_id, p.pareja_visitante_id)
        AND p.pareja_local_id IN (r.left_id, r.right_id)
        AND p.pareja_visitante_id IN (r.left_id, r.right_id)
    );
  GET DIAGNOSTICS v_dropped = ROW_COUNT;

  SELECT coalesce(max(orden), 0), coalesce(max(ronda), 0)
    INTO v_max_orden, v_max_ronda
  FROM public.torneo_express_partidos
  WHERE grupo_id = p_grupo_id;

  INSERT INTO public.torneo_express_partidos (
    id, grupo_id, pareja_local_id, pareja_visitante_id, estado, ronda, orden
  )
  SELECT
    gen_random_uuid(),
    p_grupo_id,
    r.left_id,
    r.right_id,
    'pendiente',
    v_max_ronda + 1,
    v_max_orden + row_number() OVER (ORDER BY r.left_id, r.right_id)
  FROM te_reconcile_required r
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    WHERE p.grupo_id = p_grupo_id
      AND public.te_matchup_key(p.pareja_local_id, p.pareja_visitante_id) = r.matchup
  );
  GET DIAGNOSTICS v_created = ROW_COUNT;

  IF v_created = 0 AND v_dropped = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'creados', 0,
      'retirados', 0,
      'version', (v_version_guard ->> 'version')::integer
    );
  END IF;

  v_version := public.te_grupo_bump_version(p_grupo_id);
  RETURN jsonb_build_object(
    'ok', true,
    'creados', v_created,
    'retirados', v_dropped,
    'version', v_version
  );
END;
$$;


ALTER FUNCTION "public"."reconciliar_torneo_express_grupo"("p_grupo_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_coach_class_session"("p_relationship_id" "uuid", "p_notas" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_session_id" "uuid" DEFAULT NULL::"uuid", "p_worked_on" "text"[] DEFAULT '{}'::"text"[], "p_improvements" "text" DEFAULT NULL::"text", "p_next_goals" "text" DEFAULT NULL::"text", "p_motivational_message" "text" DEFAULT NULL::"text", "p_duration_minutes" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_rel record;
  v_coach record;
  v_membership record;
  v_sess record;
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_balance record;
  v_new_balance integer;
  v_new_total integer;
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_session_id uuid := p_session_id;
  v_existing_op record;
  v_effective_duration integer := COALESCE(p_duration_minutes, 60);
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_trimmed_key IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Clave de idempotencia requerida para registrar la clase impartida.');
  END IF;

  -- 1. Obtener relación coach-alumno
  SELECT r.id, r.organizador_id, r.coach_id, r.jugador_id, r.status
  INTO v_rel
  FROM public.coach_player_relationships r
  WHERE r.id = p_relationship_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Relación coach-alumno no encontrada.');
  END IF;

  IF v_rel.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se puede registrar una clase en una relación inactiva o finalizada.');
  END IF;

  -- 2. Obtener datos del coach asignado
  SELECT id, auth_user_id, nombre INTO v_coach
  FROM public.riviera_coaches
  WHERE id = v_rel.coach_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Perfil de coach no encontrado.');
  END IF;

  -- 3. Autorización: El coach que imparte la clase, el organizador del club o Master Admin
  IF v_coach.auth_user_id <> v_caller AND v_rel.organizador_id <> v_caller AND v_is_master IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes autorización para registrar clases para este alumno.');
  END IF;

  -- 4. Comprobar que el coach tiene membresía ACTIVE en el club
  SELECT id, status INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = v_rel.coach_id AND organizador_id = v_rel.organizador_id;

  IF NOT FOUND OR v_membership.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El coach no cuenta con una asociación activa con el club correspondiente.'
    );
  END IF;

  -- 5. Comprobar que el club tiene coaching habilitado
  IF NOT EXISTS (
    SELECT 1 FROM public.organizador_game_modes
    WHERE organizador_id = v_rel.organizador_id AND coaching_enabled = true
  ) AND v_is_master IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El club no tiene el servicio de Coaching habilitado.'
    );
  END IF;

  -- 6. Validar Idempotencia estricta
  SELECT id, tipo, relationship_id, organizador_id, recorded_by, delta, session_id
  INTO v_existing_op
  FROM public.coach_class_ledger
  WHERE idempotency_key = v_trimmed_key;

  IF FOUND THEN
    IF v_existing_op.recorded_by <> v_caller
       OR v_existing_op.relationship_id <> p_relationship_id
       OR v_existing_op.tipo <> 'CLASS_DEBIT'
       OR v_existing_op.delta <> -1 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Conflicto de idempotencia: la clave ya fue utilizada en otra operación o con parámetros distintos.'
      );
    END IF;

    SELECT balance_classes, total_classes_given INTO v_balance
    FROM public.coach_player_class_balances
    WHERE relationship_id = p_relationship_id;

    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'session_id', v_existing_op.session_id,
      'remaining_balance', COALESCE(v_balance.balance_classes, 0),
      'total_classes_given', COALESCE(v_balance.total_classes_given, 0),
      'message', 'Operación idempotente: esta clase ya había sido registrada previamente.'
    );
  END IF;

  -- 7. Bloquear y verificar saldo disponible
  SELECT id, balance_classes, total_classes_given
  INTO v_balance
  FROM public.coach_player_class_balances
  WHERE relationship_id = v_rel.id
  FOR UPDATE;

  IF NOT FOUND OR v_balance.balance_classes < 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El alumno no tiene clases disponibles. Solicita al club asignar nuevas clases.'
    );
  END IF;

  -- 8. Validación rigurosa de la sesión existente (si se especificó p_session_id)
  IF v_session_id IS NOT NULL THEN
    SELECT id, coach_id, organizador_id, jugador_id, relationship_id, status, duration_minutes
    INTO v_sess
    FROM public.coach_sessions
    WHERE id = v_session_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Sesión de coaching no encontrada.');
    END IF;

    IF v_sess.coach_id <> v_rel.coach_id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'La sesión programada pertenece a otro entrenador.');
    END IF;

    IF v_sess.organizador_id <> v_rel.organizador_id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'La sesión programada pertenece a otro club.');
    END IF;

    IF v_sess.jugador_id <> v_rel.jugador_id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'La sesión programada está asignada a otro alumno.');
    END IF;

    IF v_sess.relationship_id IS NOT NULL AND v_sess.relationship_id <> v_rel.id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'La sesión programada no coincide con la relación técnica coach-alumno.');
    END IF;

    IF v_sess.status = 'CANCELLED' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Esta clase fue cancelada y no puede ser marcada como impartida.');
    END IF;

    IF v_sess.status = 'COMPLETED' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Esta clase ya fue impartida y registrada previamente.');
    END IF;

    IF v_sess.status <> 'SCHEDULED' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Solo se pueden finalizar sesiones en estado programada (SCHEDULED). Estado actual: ' || v_sess.status || '.');
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.coach_class_ledger WHERE session_id = v_session_id
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Esta sesión ya generó un descuento de clase previamente en el historial.'
      );
    END IF;

    -- Actualizar la sesión programada a COMPLETED
    UPDATE public.coach_sessions
    SET status = 'COMPLETED',
        relationship_id = v_rel.id,
        duration_minutes = COALESCE(v_effective_duration, v_sess.duration_minutes, 60),
        worked_on = COALESCE(p_worked_on, worked_on),
        improvements = COALESCE(p_improvements, improvements),
        next_goals = COALESCE(p_next_goals, next_goals),
        motivational_message = COALESCE(p_motivational_message, motivational_message),
        notes_summary = COALESCE(p_notas, notes_summary),
        updated_at = v_now
    WHERE id = v_session_id;
  ELSE
    -- Crear sesión completada ad-hoc
    INSERT INTO public.coach_sessions (
      coach_id,
      relationship_id,
      organizador_id,
      jugador_id,
      starts_at,
      ends_at,
      duration_minutes,
      status,
      worked_on,
      improvements,
      next_goals,
      motivational_message,
      notes_summary,
      created_at,
      updated_at
    )
    VALUES (
      v_rel.coach_id,
      v_rel.id,
      v_rel.organizador_id,
      v_rel.jugador_id,
      v_now - (v_effective_duration || ' minutes')::interval,
      v_now,
      v_effective_duration,
      'COMPLETED',
      COALESCE(p_worked_on, '{}'::text[]),
      p_improvements,
      p_next_goals,
      p_motivational_message,
      p_notas,
      v_now,
      v_now
    )
    RETURNING id INTO v_session_id;
  END IF;

  -- 9. Descontar exactamente 1 clase e incrementar total impartidas
  UPDATE public.coach_player_class_balances
  SET balance_classes = balance_classes - 1,
      total_classes_given = total_classes_given + 1,
      updated_at = v_now
  WHERE id = v_balance.id
  RETURNING balance_classes, total_classes_given INTO v_new_balance, v_new_total;

  -- 10. Registrar CLASS_DEBIT inmutable en el ledger vinculado a la sesión
  INSERT INTO public.coach_class_ledger (
    relationship_id,
    organizador_id,
    coach_id,
    jugador_id,
    session_id,
    delta,
    tipo,
    notas,
    idempotency_key,
    recorded_by,
    created_at
  )
  VALUES (
    v_rel.id,
    v_rel.organizador_id,
    v_rel.coach_id,
    v_rel.jugador_id,
    v_session_id,
    -1,
    'CLASS_DEBIT',
    COALESCE(p_motivational_message, p_notas),
    v_trimmed_key,
    v_caller,
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'session_id', v_session_id,
    'remaining_balance', v_new_balance,
    'total_classes_given', v_new_total
  );
END;
$$;


ALTER FUNCTION "public"."record_coach_class_session"("p_relationship_id" "uuid", "p_notas" "text", "p_idempotency_key" "text", "p_session_id" "uuid", "p_worked_on" "text"[], "p_improvements" "text", "p_next_goals" "text", "p_motivational_message" "text", "p_duration_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_coach_class_session_with_followup"("p_relationship_id" "uuid", "p_notas" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_session_id" "uuid" DEFAULT NULL::"uuid", "p_worked_on" "text"[] DEFAULT '{}'::"text"[], "p_improvements" "text" DEFAULT NULL::"text", "p_next_goals" "text" DEFAULT NULL::"text", "p_motivational_message" "text" DEFAULT NULL::"text", "p_duration_minutes" integer DEFAULT 60, "p_areas_to_improve" "text" DEFAULT NULL::"text", "p_recommendations" "text" DEFAULT NULL::"text", "p_private_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_record jsonb;
  v_followup jsonb;
  v_session_id uuid;
  v_ok boolean;
  v_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_constraint text;
  v_existing record;
  v_balance record;
BEGIN
  v_record := public.record_coach_class_session(
    p_relationship_id,
    p_notas,
    p_idempotency_key,
    p_session_id,
    COALESCE(p_worked_on, '{}'::text[]),
    p_improvements,
    p_next_goals,
    p_motivational_message,
    p_duration_minutes
  );

  v_ok := COALESCE((v_record->>'ok')::boolean, false);
  IF NOT v_ok THEN
    RETURN v_record;
  END IF;

  -- La clave ya confirmó clase y seguimiento en una transacción anterior.
  -- No se vuelve a descontar ni se reescribe el seguimiento, aunque el
  -- reintento traiga recomendaciones o notas distintas.
  IF COALESCE((v_record->>'idempotent')::boolean, false) THEN
    RETURN v_record || jsonb_build_object(
      'followup_ok', true,
      'followup_preserved', true
    );
  END IF;

  v_session_id := NULLIF(v_record->>'session_id', '')::uuid;
  IF v_session_id IS NULL THEN
    RAISE EXCEPTION 'Registro de clase sin session_id; se revierte la operación.';
  END IF;

  -- Misma unidad de trabajo: cualquier fallo aquí revierte el CLASS_DEBIT.
  v_followup := public.update_coach_class_followup(
    v_session_id,
    COALESCE(p_worked_on, '{}'::text[]),
    p_improvements,
    p_areas_to_improve,
    p_recommendations,
    p_next_goals,
    p_motivational_message,
    p_private_notes
  );

  IF NOT COALESCE((v_followup->>'ok')::boolean, false) THEN
    RAISE EXCEPTION '%',
      COALESCE(
        NULLIF(btrim(v_followup->>'error'), ''),
        'No se pudo guardar el seguimiento de la clase; se revierte el registro.'
      );
  END IF;

  RETURN v_record || jsonb_build_object(
    'followup_ok', true,
    'followup_updated_at', v_followup->'followup_updated_at'
  );
EXCEPTION
  WHEN unique_violation THEN
    -- Dos peticiones simultáneas con la misma clave: el índice único
    -- idx_ccl_idempotency aborta la perdedora. No hay segundo descuento
    -- ni se reescribe el seguimiento que ya confirmó la ganadora.
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint IS DISTINCT FROM 'idx_ccl_idempotency' OR v_key IS NULL THEN
      RAISE;
    END IF;

    SELECT id, tipo, relationship_id, recorded_by, delta, session_id
    INTO v_existing
    FROM public.coach_class_ledger
    WHERE idempotency_key = v_key;

    IF NOT FOUND
       OR v_existing.recorded_by IS DISTINCT FROM auth.uid()
       OR v_existing.relationship_id IS DISTINCT FROM p_relationship_id
       OR v_existing.tipo IS DISTINCT FROM 'CLASS_DEBIT'
       OR v_existing.delta IS DISTINCT FROM -1
       OR v_existing.session_id IS NULL THEN
      RAISE EXCEPTION 'Conflicto de idempotencia: la clave ya fue utilizada en otra operación o con parámetros distintos.';
    END IF;

    -- La transacción ganadora ya confirmó clase y seguimiento. No se reescribe.
    SELECT balance_classes, total_classes_given
    INTO v_balance
    FROM public.coach_player_class_balances
    WHERE relationship_id = p_relationship_id;

    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'followup_ok', true,
      'followup_preserved', true,
      'session_id', v_existing.session_id,
      'remaining_balance', COALESCE(v_balance.balance_classes, 0),
      'total_classes_given', COALESCE(v_balance.total_classes_given, 0),
      'message', 'Operación idempotente: esta clase ya había sido registrada previamente.'
    );
END;
$$;


ALTER FUNCTION "public"."record_coach_class_session_with_followup"("p_relationship_id" "uuid", "p_notas" "text", "p_idempotency_key" "text", "p_session_id" "uuid", "p_worked_on" "text"[], "p_improvements" "text", "p_next_goals" "text", "p_motivational_message" "text", "p_duration_minutes" integer, "p_areas_to_improve" "text", "p_recommendations" "text", "p_private_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_coach_class_session_with_followup"("p_relationship_id" "uuid", "p_notas" "text", "p_idempotency_key" "text", "p_session_id" "uuid", "p_worked_on" "text"[], "p_improvements" "text", "p_next_goals" "text", "p_motivational_message" "text", "p_duration_minutes" integer, "p_areas_to_improve" "text", "p_recommendations" "text", "p_private_notes" "text") IS 'Registra clase impartida + seguimiento (incl. notas privadas) en una sola transacción. Si el seguimiento falla, revierte el descuento.';



CREATE OR REPLACE FUNCTION "public"."reemplazar_torneo_express_pareja_grupo"("p_grupo_id" "uuid", "p_pareja_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_torneo_id uuid;
  v_guard jsonb;
  v_version_guard jsonb;
  v_player1 uuid;
  v_player2 uuid;
  v_is_virtual boolean;
  v_tournament uuid;
  v_name1 text;
  v_name2 text;
  v_has_history boolean;
  v_shared boolean;
  v_new_pair uuid;
  v_version integer;
BEGIN
  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;
  SELECT torneo_id INTO v_torneo_id
  FROM public.torneo_express_grupos WHERE id = p_grupo_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  v_guard := public.te_lock_categoria_editable(v_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    IF (v_guard ->> 'error') IN ('TOURNAMENT_NOT_EDITABLE', 'ELIMINATORIA_EXISTS') THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'GROUP_NOT_EDITABLE', 'reason', v_guard ->> 'error'
      );
    END IF;
    RETURN v_guard;
  END IF;

  PERFORM 1 FROM public.torneo_express_grupos WHERE id = p_grupo_id FOR UPDATE;
  v_version_guard := public.te_grupo_version_ok(p_grupo_id, p_expected_version);
  IF NOT (v_version_guard ->> 'ok')::boolean THEN
    RETURN v_version_guard;
  END IF;

  PERFORM 1
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = p_grupo_id
  ORDER BY pareja_id
  FOR UPDATE;

  IF NOT EXISTS (
    SELECT 1 FROM public.torneo_express_grupo_parejas
    WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_IN_GROUP');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.torneo_express_grupo_parejas
    WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id AND NOT activa
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_ALREADY_WITHDRAWN');
  END IF;

  PERFORM 1
  FROM public.torneo_express_partidos
  WHERE grupo_id = p_grupo_id
    AND (pareja_local_id = p_pareja_id OR pareja_visitante_id = p_pareja_id)
  ORDER BY id
  FOR UPDATE;

  SELECT player1_id, player2_id, is_virtual, tournament_id
    INTO v_player1, v_player2, v_is_virtual, v_tournament
  FROM public.pairs
  WHERE id = p_pareja_id
  FOR UPDATE;

  IF NOT FOUND OR v_is_virtual THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', CASE WHEN v_is_virtual THEN 'PAIR_IS_VIRTUAL' ELSE 'INVALID_PAIR' END
    );
  END IF;
  IF p_player1_id IS NULL OR p_player2_id IS NULL OR p_player1_id = p_player2_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_PAIR');
  END IF;

  IF (p_player1_id = v_player1 AND p_player2_id = v_player2)
     OR (p_player1_id = v_player2 AND p_player2_id = v_player1) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'unchanged', true,
      'pareja_id', p_pareja_id,
      'version', (v_version_guard ->> 'version')::integer
    );
  END IF;

  SELECT btrim(name) INTO v_name1 FROM public.players WHERE id = p_player1_id;
  SELECT btrim(name) INTO v_name2 FROM public.players WHERE id = p_player2_id;
  IF v_name1 IS NULL OR v_name1 = '' OR v_name2 IS NULL OR v_name2 = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_NOT_FOUND');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    JOIN public.pairs pr ON pr.id = gp.pareja_id
    WHERE g.torneo_id = v_torneo_id
      AND gp.pareja_id <> p_pareja_id
      AND (
        pr.player1_id IN (p_player1_id, p_player2_id)
        OR pr.player2_id IN (p_player1_id, p_player2_id)
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_ALREADY_REGISTERED');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    WHERE p.grupo_id = p_grupo_id
      AND (p.pareja_local_id = p_pareja_id OR p.pareja_visitante_id = p_pareja_id)
      AND public.te_partido_tiene_historial(
        p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
      )
  ) INTO v_has_history;
  v_shared := public.te_pareja_referenciada_fuera(p_pareja_id, p_grupo_id);

  IF NOT v_has_history AND NOT v_shared THEN
    UPDATE public.pairs
    SET player1_id = p_player1_id,
        player2_id = p_player2_id,
        player1_name = v_name1,
        player2_name = v_name2,
        is_virtual = false,
        virtual_label = NULL
    WHERE id = p_pareja_id;
    v_version := public.te_grupo_bump_version(p_grupo_id);
    RETURN jsonb_build_object(
      'ok', true, 'mode', 'in_place', 'pareja_id', p_pareja_id, 'version', v_version
    );
  END IF;

  INSERT INTO public.pairs (
    id, tournament_id, player1_id, player2_id, player1_name, player2_name, is_virtual, virtual_label
  ) VALUES (
    gen_random_uuid(), v_tournament, p_player1_id, p_player2_id, v_name1, v_name2, false, NULL
  )
  RETURNING id INTO v_new_pair;

  UPDATE public.torneo_express_grupo_parejas
  SET pareja_previa_ids = pareja_previa_ids || ARRAY[p_pareja_id],
      pareja_id = v_new_pair
  WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id;

  UPDATE public.torneo_express_partidos
  SET pareja_local_id = CASE WHEN pareja_local_id = p_pareja_id THEN v_new_pair ELSE pareja_local_id END,
      pareja_visitante_id = CASE WHEN pareja_visitante_id = p_pareja_id THEN v_new_pair ELSE pareja_visitante_id END
  WHERE grupo_id = p_grupo_id
    AND (pareja_local_id = p_pareja_id OR pareja_visitante_id = p_pareja_id)
    AND NOT public.te_partido_tiene_historial(
      estado, ganador_id, puntos_local, puntos_visitante, sets_resultado
    );

  v_version := public.te_grupo_bump_version(p_grupo_id);
  RETURN jsonb_build_object(
    'ok', true,
    'mode', 'desde_ahora',
    'pareja_id', v_new_pair,
    'pareja_anterior_id', p_pareja_id,
    'version', v_version
  );
END;
$$;


ALTER FUNCTION "public"."reemplazar_torneo_express_pareja_grupo"("p_grupo_id" "uuid", "p_pareja_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_jugador_stats"("p_jugador_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stats record;
  v_role text := COALESCE(auth.role(), '');
  v_player_org uuid;
  v_home_org uuid;
BEGIN
  IF p_jugador_id IS NULL THEN
    RETURN;
  END IF;

  IF v_role = 'anon' THEN
    RAISE EXCEPTION 'No autorizado para refrescar estadísticas de este jugador';
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT rj.organizador_id INTO v_player_org
    FROM public.riviera_jugadores rj
    WHERE rj.id = p_jugador_id;

    v_home_org := public._resolve_home_organizador_for_jugador(p_jugador_id);

    IF auth.uid() IS NULL
       OR (
         NOT public.is_master_admin()
         AND (v_player_org IS NULL OR v_player_org IS DISTINCT FROM auth.uid())
         AND (v_home_org IS NULL OR v_home_org IS DISTINCT FROM auth.uid())
       ) THEN
      RAISE EXCEPTION 'No autorizado para refrescar estadísticas de este jugador';
    END IF;
  END IF;

  SELECT
    COALESCE(SUM(jp.puntos_obtenidos), 0)::integer AS puntos_totales,
    COALESCE(SUM(jp.sets_favor), 0)::integer AS sets_favor_total,
    COALESCE(SUM(jp.sets_contra), 0)::integer AS sets_contra_total,
    COUNT(*) FILTER (
      WHERE COALESCE(jp.metadata->>'subtipo', '') <> 'liga_inscripcion'
        AND COALESCE(jp.metadata->>'subtipo', '') <> 'ajuste_manual'
    )::integer AS participaciones_solo,
    COUNT(*) FILTER (WHERE jp.tipo_evento::text = 'reta')::integer AS total_retas,
    COUNT(*) FILTER (WHERE jp.tipo_evento::text = 'torneo_express')::integer AS total_torneos_express,
    COUNT(*) FILTER (WHERE jp.tipo_evento::text = 'liga')::integer AS total_ligas,
    COUNT(*) FILTER (WHERE jp.tipo_evento::text = 'americano')::integer AS total_americanos,
    COALESCE(SUM(
      CASE
        WHEN COALESCE(jp.metadata->>'subtipo', '') IN ('liga_inscripcion', 'ajuste_manual') THEN 0
        ELSE COALESCE(
          NULLIF(jp.metadata->>'partidos_ganados', '')::integer,
          CASE WHEN jp.resultado::text = 'victoria' THEN 1 ELSE 0 END
        )
      END
    ), 0)::integer AS victorias,
    COALESCE(SUM(
      CASE
        WHEN COALESCE(jp.metadata->>'subtipo', '') IN ('liga_inscripcion', 'ajuste_manual') THEN 0
        ELSE COALESCE(
          NULLIF(jp.metadata->>'partidos_perdidos', '')::integer,
          CASE WHEN jp.resultado::text = 'derrota' THEN 1 ELSE 0 END
        )
      END
    ), 0)::integer AS derrotas,
    COALESCE(SUM(
      CASE
        WHEN COALESCE(jp.metadata->>'subtipo', '') IN ('liga_inscripcion', 'ajuste_manual') THEN 0
        ELSE COALESCE(
          NULLIF(jp.metadata->>'partidos_empatados', '')::integer,
          CASE WHEN jp.resultado::text = 'empate' THEN 1 ELSE 0 END
        )
      END
    ), 0)::integer AS empates,
    MAX(jp.fecha) FILTER (
      WHERE COALESCE(jp.metadata->>'subtipo', '') NOT IN ('liga_inscripcion', 'ajuste_manual')
    ) AS ultima_actividad
  INTO v_stats
  FROM public.jugador_participaciones jp
  WHERE jp.jugador_id = p_jugador_id;

  INSERT INTO public.jugador_stats (
    jugador_id,
    total_partidos,
    victorias,
    derrotas,
    empates,
    participaciones_solo,
    pct_victorias,
    total_retas,
    total_torneos_express,
    total_ligas,
    total_americanos,
    sets_favor_total,
    sets_contra_total,
    racha_actual,
    ultima_actividad,
    puntos_totales,
    updated_at
  )
  VALUES (
    p_jugador_id,
    GREATEST(0, COALESCE(v_stats.victorias, 0) + COALESCE(v_stats.derrotas, 0)),
    COALESCE(v_stats.victorias, 0),
    COALESCE(v_stats.derrotas, 0),
    COALESCE(v_stats.empates, 0),
    COALESCE(v_stats.participaciones_solo, 0),
    CASE
      WHEN COALESCE(v_stats.victorias, 0) + COALESCE(v_stats.derrotas, 0) > 0 THEN
        ROUND(
          (v_stats.victorias::numeric /
            (v_stats.victorias + v_stats.derrotas)::numeric) * 10000
        ) / 100
      ELSE 0
    END,
    COALESCE(v_stats.total_retas, 0),
    COALESCE(v_stats.total_torneos_express, 0),
    COALESCE(v_stats.total_ligas, 0),
    COALESCE(v_stats.total_americanos, 0),
    COALESCE(v_stats.sets_favor_total, 0),
    COALESCE(v_stats.sets_contra_total, 0),
    '',
    v_stats.ultima_actividad,
    COALESCE(v_stats.puntos_totales, 0),
    now()
  )
  ON CONFLICT (jugador_id) DO UPDATE SET
    total_partidos = EXCLUDED.total_partidos,
    victorias = EXCLUDED.victorias,
    derrotas = EXCLUDED.derrotas,
    empates = EXCLUDED.empates,
    participaciones_solo = EXCLUDED.participaciones_solo,
    pct_victorias = EXCLUDED.pct_victorias,
    total_retas = EXCLUDED.total_retas,
    total_torneos_express = EXCLUDED.total_torneos_express,
    total_ligas = EXCLUDED.total_ligas,
    total_americanos = EXCLUDED.total_americanos,
    sets_favor_total = EXCLUDED.sets_favor_total,
    sets_contra_total = EXCLUDED.sets_contra_total,
    ultima_actividad = EXCLUDED.ultima_actividad,
    puntos_totales = EXCLUDED.puntos_totales,
    updated_at = now();
END;
$$;


ALTER FUNCTION "public"."refresh_jugador_stats"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_riviera_jugador_import_blocklist"("p_organizador_id" "uuid", "p_nombre" "text", "p_legacy_player_id" "uuid" DEFAULT NULL::"uuid", "p_legacy_liga_jugador_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key text;
BEGIN
  IF p_organizador_id IS NULL THEN
    RETURN;
  END IF;

  v_key := public._riviera_jugador_nombre_key(p_nombre);
  IF v_key = '' THEN
    RETURN;
  END IF;

  IF auth.uid() IS DISTINCT FROM p_organizador_id
     AND NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Sin permiso';
  END IF;

  INSERT INTO public.riviera_jugador_import_blocklist (
    organizador_id,
    nombre,
    nombre_key,
    legacy_player_id,
    legacy_liga_jugador_id
  )
  VALUES (
    p_organizador_id,
    trim(p_nombre),
    v_key,
    p_legacy_player_id,
    p_legacy_liga_jugador_id
  )
  ON CONFLICT (organizador_id, nombre_key) DO UPDATE
  SET nombre = EXCLUDED.nombre,
      legacy_player_id = coalesce(EXCLUDED.legacy_player_id, riviera_jugador_import_blocklist.legacy_player_id),
      legacy_liga_jugador_id = coalesce(EXCLUDED.legacy_liga_jugador_id, riviera_jugador_import_blocklist.legacy_liga_jugador_id),
      deleted_at = now();
END;
$$;


ALTER FUNCTION "public"."register_riviera_jugador_import_blocklist"("p_organizador_id" "uuid", "p_nombre" "text", "p_legacy_player_id" "uuid", "p_legacy_liga_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registrar_participacion_jugador"("p_jugador_id" "uuid", "p_tipo_evento" "public"."jugador_tipo_evento", "p_evento_id" "uuid", "p_evento_nombre" "text", "p_pareja_con" "text" DEFAULT NULL::"text", "p_resultado" "public"."jugador_resultado" DEFAULT 'participación'::"public"."jugador_resultado", "p_sets_favor" integer DEFAULT 0, "p_sets_contra" integer DEFAULT 0, "p_puntos_obtenidos" integer DEFAULT 0, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_fecha" "date" DEFAULT CURRENT_DATE) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_org uuid;
BEGIN
  SELECT organizador_id INTO v_org
  FROM public.riviera_jugadores
  WHERE id = p_jugador_id;

  IF v_org IS NULL OR auth.uid() IS NULL OR v_org IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'No autorizado para registrar participación de este jugador';
  END IF;

  INSERT INTO public.jugador_participaciones (
    jugador_id,
    tipo_evento,
    evento_id,
    evento_nombre,
    fecha,
    pareja_con,
    resultado,
    sets_favor,
    sets_contra,
    puntos_obtenidos,
    metadata
  )
  VALUES (
    p_jugador_id,
    p_tipo_evento,
    p_evento_id,
    p_evento_nombre,
    p_fecha,
    NULLIF(trim(p_pareja_con), ''),
    p_resultado,
    COALESCE(p_sets_favor, 0),
    COALESCE(p_sets_contra, 0),
    COALESCE(p_puntos_obtenidos, 0),
    COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (jugador_id, tipo_evento, evento_id, resultado)
  DO UPDATE SET
    evento_nombre = EXCLUDED.evento_nombre,
    fecha = EXCLUDED.fecha,
    sets_favor = EXCLUDED.sets_favor,
    sets_contra = EXCLUDED.sets_contra,
    puntos_obtenidos = EXCLUDED.puntos_obtenidos,
    metadata = EXCLUDED.metadata
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."registrar_participacion_jugador"("p_jugador_id" "uuid", "p_tipo_evento" "public"."jugador_tipo_evento", "p_evento_id" "uuid", "p_evento_nombre" "text", "p_pareja_con" "text", "p_resultado" "public"."jugador_resultado", "p_sets_favor" integer, "p_sets_contra" integer, "p_puntos_obtenidos" integer, "p_metadata" "jsonb", "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registrar_participacion_jugador_con_ledger"("p_jugador_id" "uuid", "p_tipo_evento" "public"."jugador_tipo_evento", "p_evento_id" "uuid", "p_evento_nombre" "text", "p_pareja_con" "text" DEFAULT NULL::"text", "p_resultado" "public"."jugador_resultado" DEFAULT 'participación'::"public"."jugador_resultado", "p_sets_favor" integer DEFAULT 0, "p_sets_contra" integer DEFAULT 0, "p_puntos_obtenidos" integer DEFAULT 0, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_fecha" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_participacion_id uuid;
  v_ledger_result jsonb;
BEGIN
  -- Ownership/auth ya validados dentro de registrar_participacion_jugador.
  v_participacion_id := public.registrar_participacion_jugador(
    p_jugador_id, p_tipo_evento, p_evento_id, p_evento_nombre,
    p_pareja_con, p_resultado, p_sets_favor, p_sets_contra,
    p_puntos_obtenidos, p_metadata, p_fecha
  );

  -- try_write es idempotente por participacion_id; si el org no es emisor
  -- oficial, status 'skipped' (no error).
  v_ledger_result := public.try_write_riviera_official_ledger(v_participacion_id);

  RETURN jsonb_build_object(
    'ok', true,
    'participacion_id', v_participacion_id,
    'ledger', v_ledger_result
  );
END;
$$;


ALTER FUNCTION "public"."registrar_participacion_jugador_con_ledger"("p_jugador_id" "uuid", "p_tipo_evento" "public"."jugador_tipo_evento", "p_evento_id" "uuid", "p_evento_nombre" "text", "p_pareja_con" "text", "p_resultado" "public"."jugador_resultado", "p_sets_favor" integer, "p_sets_contra" integer, "p_puntos_obtenidos" integer, "p_metadata" "jsonb", "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_coach_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_membership record;
  v_now timestamptz := now();
BEGIN
  -- 1. Validar autenticación
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  -- 2. Validar que el solicitante es dueño autorizado del club o Administrador Maestro
  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No tienes permisos para eliminar entrenadores de este club.'
    );
  END IF;

  -- 3. Bloquear la membresía correspondiente para evitar carreras de estado
  SELECT id, status, organizador_id, coach_id
  INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El entrenador no tiene asociación registrada en este club.'
    );
  END IF;

  -- 4. Idempotencia: si ya estaba eliminado, devolver éxito sin efectos adicionales
  IF v_membership.status = 'REMOVED' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'status', 'REMOVED',
      'message', 'El entrenador ya había sido eliminado de este club previamente.'
    );
  END IF;

  -- 5. Revocar inmediatamente los permisos operativos en este club y marcar como REMOVED
  UPDATE public.coach_club_memberships
  SET
    status = 'REMOVED',
    removed_at = v_now,
    removal_reason = NULLIF(trim(p_motivo), ''),
    removed_by = v_caller,
    deactivated_at = COALESCE(deactivated_at, v_now),
    archived_at = COALESCE(archived_at, v_now),
    last_edited_by = v_caller,
    last_edited_at = v_now,
    updated_at = v_now
  WHERE id = v_membership.id;

  -- 6. Suspender relaciones activas de alumnos en este club para este coach
  -- Conserva saldos, historial y relaciones; previene nuevas clases hasta reasignar
  UPDATE public.coach_player_relationships
  SET
    status = 'PAUSED',
    updated_at = v_now
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_coach_id
    AND status = 'ACTIVE';

  -- 7. Registrar en la bitácora de auditoría inmutable
  INSERT INTO public.coach_club_membership_audit_log (
    membership_id,
    coach_id,
    organizador_id,
    action,
    performed_by,
    previous_status,
    new_status,
    details
  ) VALUES (
    v_membership.id,
    p_coach_id,
    p_organizador_id,
    'REMOVE_COACH',
    v_caller,
    v_membership.status,
    'REMOVED',
    jsonb_build_object(
      'motivo', NULLIF(trim(p_motivo), ''),
      'removed_at', v_now
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'status', 'REMOVED',
    'message', 'Entrenador eliminado de tu club exitosamente. Se ha conservado todo el historial de actividades.'
  );
END;
$$;


ALTER FUNCTION "public"."remove_coach_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_open_game_registration_entry"("p_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_entry public.tournament_open_registration_entries%ROWTYPE;
  v_cfg public.tournament_open_registration;
  v_started boolean := false;
  v_promoted int := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticación requerida'; END IF;
  IF p_entry_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'entry_id_required');
  END IF;

  SELECT * INTO v_entry
  FROM public.tournament_open_registration_entries
  WHERE id = p_entry_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT * INTO v_cfg
  FROM public.tournament_open_registration
  WHERE id = v_entry.registration_id
  FOR UPDATE;

  IF NOT FOUND
     OR public._open_reg_organizer_id(v_cfg.mode_type, v_cfg.entity_id) <> v_uid THEN
    RAISE EXCEPTION 'Sin permiso';
  END IF;

  -- No alterar roster/slots después de iniciar el juego
  IF v_cfg.mode_type = 'duelo_2v2' THEN
    SELECT estado IN ('en_juego', 'finalizado') INTO v_started
    FROM public.duelos_2v2 WHERE id = v_cfg.entity_id;
  ELSE
    SELECT coalesce(is_started, false) OR coalesce(is_finished, false)
      INTO v_started
    FROM public.tournaments WHERE id = v_cfg.entity_id;
  END IF;

  IF coalesce(v_started, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'registration_closed');
  END IF;

  IF v_cfg.status IN ('closed', 'cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'registration_closed');
  END IF;

  -- Soft-remove (auditoría): no DELETE físico
  UPDATE public.tournament_open_registration_entries
  SET status = 'removed',
      cancelled_at = now(),
      updated_at = now(),
      cancellation_token_hash = null
  WHERE id = v_entry.id;

  IF v_entry.status = 'confirmed' THEN
    -- Promover automáticamente al primer jugador en reserva/waitlist
    v_promoted := public._open_reg_auto_promote_waitlist(v_cfg.id);
  END IF;

  IF v_cfg.mode_type = 'americano' THEN
    PERFORM public._open_reg_sync_americano_roster(v_cfg.entity_id);
  ELSIF v_cfg.mode_type = 'duelo_2v2' THEN
    PERFORM public._open_reg_sync_duelo_slots(v_cfg.entity_id);
  END IF;

  -- Respuesta sin token hash ni PII
  RETURN jsonb_build_object(
    'ok', true,
    'entry_id', v_entry.id,
    'status', 'removed',
    'previous_status', v_entry.status,
    'promoted_count', v_promoted
  );
END;
$$;


ALTER FUNCTION "public"."remove_open_game_registration_entry"("p_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorganize_torneo_express_grupos"("p_torneo_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_guard jsonb;
  v_grupos jsonb;
  v_partidos jsonb;
  elem jsonb;
  v_nombre text;
  v_orden integer;
  v_ids uuid[];
  v_id uuid;
  v_local uuid;
  v_visit uuid;
  v_ronda integer;
  v_match_orden integer;
  v_cancha text;
  v_programado timestamptz;
  v_grupo_id uuid;
  v_inserted integer := 0;
  pareja_json jsonb;
BEGIN
  v_guard := public.te_lock_categoria_editable(p_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    RETURN v_guard;
  END IF;

  BEGIN
    PERFORM 1
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
    FOR UPDATE OF p NOWAIT;
  EXCEPTION
    WHEN lock_not_available THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_REORGANIZATION');
  END;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND public.te_partido_tiene_historial(
        p.estado,
        p.ganador_id,
        p.puntos_local,
        p.puntos_visitante,
        p.sets_resultado
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_REORGANIZATION');
  END IF;

  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_REORGANIZATION');
  END IF;

  DROP TABLE IF EXISTS te_reorg_asignacion;
  DROP TABLE IF EXISTS te_reorg_partidos;
  DROP TABLE IF EXISTS te_reorg_grupos;

  v_grupos := p_payload -> 'grupos';
  v_partidos := p_payload -> 'partidos';
  IF jsonb_typeof(v_grupos) IS DISTINCT FROM 'array'
     OR jsonb_typeof(v_partidos) IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_grupos) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_REORGANIZATION');
  END IF;

  CREATE TEMP TABLE te_reorg_grupos (
    orden integer PRIMARY KEY,
    nombre text NOT NULL,
    pareja_ids uuid[] NOT NULL,
    grupo_id uuid NOT NULL
  ) ON COMMIT DROP;

  CREATE TEMP TABLE te_reorg_partidos (
    grupo_orden integer NOT NULL,
    local_id uuid NOT NULL,
    visitante_id uuid NOT NULL,
    ronda integer NOT NULL,
    orden integer NOT NULL,
    cancha text NOT NULL,
    programado_en timestamptz NOT NULL,
    matchup text NOT NULL
  ) ON COMMIT DROP;

  FOR elem IN SELECT value FROM jsonb_array_elements(v_grupos) LOOP
    v_nombre := btrim(elem ->> 'nombre');
    BEGIN
      v_orden := (elem ->> 'orden')::integer;
    EXCEPTION
      WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
    END;

    IF v_nombre IS NULL OR v_nombre = '' OR v_orden IS NULL OR v_orden < 1 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
    END IF;

    IF jsonb_typeof(elem -> 'pareja_ids') IS DISTINCT FROM 'array'
       OR jsonb_array_length(elem -> 'pareja_ids') < 2 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
    END IF;

    v_ids := ARRAY[]::uuid[];
    FOR pareja_json IN
      SELECT value FROM jsonb_array_elements(elem -> 'pareja_ids')
    LOOP
      BEGIN
        v_id := (pareja_json #>> '{}')::uuid;
      EXCEPTION
        WHEN invalid_text_representation THEN
          RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
      END;
      IF v_id IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
      END IF;
      v_ids := v_ids || v_id;
    END LOOP;

    BEGIN
      INSERT INTO te_reorg_grupos (orden, nombre, pareja_ids, grupo_id)
      VALUES (v_orden, v_nombre, v_ids, gen_random_uuid());
    EXCEPTION
      WHEN unique_violation THEN
        RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
      WHEN invalid_text_representation THEN
        RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
    END;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM te_reorg_grupos a
    JOIN te_reorg_grupos b
      ON a.orden <> b.orden
     AND lower(a.nombre) = lower(b.nombre)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_GROUP');
  END IF;

  CREATE TEMP TABLE te_reorg_asignacion (
    pareja_id uuid PRIMARY KEY,
    orden integer NOT NULL
  ) ON COMMIT DROP;

  BEGIN
    INSERT INTO te_reorg_asignacion (pareja_id, orden)
    SELECT pareja_id, g.orden
    FROM te_reorg_grupos g
    CROSS JOIN LATERAL unnest(g.pareja_ids) AS pareja_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object('ok', false, 'error', 'PAIR_DUPLICATED');
  END;

  IF EXISTS (
    SELECT 1 FROM te_reorg_grupos g
    WHERE coalesce(array_length(g.pareja_ids, 1), 0) <> (
      SELECT count(*) FROM unnest(g.pareja_ids) AS u
    )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_DUPLICATED');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM te_reorg_asignacion a
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.torneo_express_grupo_parejas gp
      JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
      WHERE g.torneo_id = p_torneo_id
        AND gp.pareja_id = a.pareja_id
    )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_IN_TOURNAMENT');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND NOT EXISTS (
        SELECT 1 FROM te_reorg_asignacion a WHERE a.pareja_id = gp.pareja_id
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_WITHOUT_GROUP');
  END IF;

  FOR elem IN SELECT value FROM jsonb_array_elements(v_partidos) LOOP
    BEGIN
      v_orden := (elem ->> 'grupo_orden')::integer;
      v_local := (elem ->> 'pareja_local_id')::uuid;
      v_visit := (elem ->> 'pareja_visitante_id')::uuid;
      v_ronda := (elem ->> 'ronda')::integer;
      v_match_orden := (elem ->> 'orden')::integer;
      v_programado := (elem ->> 'programado_en')::timestamptz;
    EXCEPTION
      WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
        RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
    END;

    v_cancha := btrim(elem ->> 'cancha');
    IF v_orden IS NULL OR v_local IS NULL OR v_visit IS NULL
       OR v_ronda IS NULL OR v_match_orden IS NULL
       OR v_programado IS NULL OR v_cancha IS NULL OR v_cancha = ''
       OR v_local = v_visit THEN
      RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
    END IF;

    BEGIN
      INSERT INTO te_reorg_partidos (
        grupo_orden, local_id, visitante_id, ronda, orden, cancha, programado_en, matchup
      ) VALUES (
        v_orden,
        v_local,
        v_visit,
        v_ronda,
        v_match_orden,
        v_cancha,
        v_programado,
        public.te_matchup_key(v_local, v_visit)
      );
    EXCEPTION
      WHEN unique_violation THEN
        RETURN jsonb_build_object('ok', false, 'error', 'DUPLICATE_MATCH');
    END;
  END LOOP;

  IF EXISTS (
    SELECT matchup
    FROM te_reorg_partidos
    GROUP BY matchup, grupo_orden
    HAVING count(*) > 1
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'DUPLICATE_MATCH');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM te_reorg_grupos g
    WHERE EXISTS (
      SELECT 1
      FROM public.te_balanced_round_robin(g.pareja_ids) expected
      WHERE NOT EXISTS (
        SELECT 1
        FROM te_reorg_partidos p
        WHERE p.grupo_orden = g.orden
          AND p.matchup = public.te_matchup_key(expected.local_id, expected.visitante_id)
          AND p.ronda = expected.ronda
          AND p.orden = expected.orden
      )
    )
    OR (
      SELECT count(*) FROM te_reorg_partidos p WHERE p.grupo_orden = g.orden
    ) <> (
      SELECT count(*) FROM public.te_balanced_round_robin(g.pareja_ids)
    )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ROUND_ROBIN_MISMATCH');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM te_reorg_partidos a
    JOIN te_reorg_partidos b
      ON a.ctid <> b.ctid
     AND public.te_mexico_slot_key(a.programado_en)
       = public.te_mexico_slot_key(b.programado_en)
     AND (
       a.cancha = b.cancha
       OR a.local_id IN (b.local_id, b.visitante_id)
       OR a.visitante_id IN (b.local_id, b.visitante_id)
     )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'STALE_SCHEDULE');
  END IF;

  -- Partidos primero, luego vínculos y grupos. pairs no se toca.
  -- Una plaza virtual entra igual que una real: el vínculo es pair.id.
  DELETE FROM public.torneo_express_partidos p
  USING public.torneo_express_grupos g
  WHERE p.grupo_id = g.id
    AND g.torneo_id = p_torneo_id;

  DELETE FROM public.torneo_express_grupo_parejas gp
  USING public.torneo_express_grupos g
  WHERE gp.grupo_id = g.id
    AND g.torneo_id = p_torneo_id;

  DELETE FROM public.torneo_express_grupos
  WHERE torneo_id = p_torneo_id;

  INSERT INTO public.torneo_express_grupos (id, torneo_id, nombre, orden)
  SELECT grupo_id, p_torneo_id, nombre, orden
  FROM te_reorg_grupos;

  INSERT INTO public.torneo_express_grupo_parejas (grupo_id, pareja_id)
  SELECT g.grupo_id, pareja_id
  FROM te_reorg_grupos g
  CROSS JOIN LATERAL unnest(g.pareja_ids) AS pareja_id;

  INSERT INTO public.torneo_express_partidos (
    grupo_id,
    pareja_local_id,
    pareja_visitante_id,
    estado,
    ronda,
    orden,
    cancha,
    programado_en
  )
  SELECT
    g.grupo_id,
    p.local_id,
    p.visitante_id,
    'pendiente',
    p.ronda,
    p.orden,
    p.cancha,
    p.programado_en
  FROM te_reorg_partidos p
  JOIN te_reorg_grupos g ON g.orden = p.grupo_orden;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'torneo_id', p_torneo_id,
    'grupos', (SELECT count(*) FROM te_reorg_grupos),
    'partidos', v_inserted
  );
END;
$$;


ALTER FUNCTION "public"."reorganize_torneo_express_grupos"("p_torneo_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_torneo_express_pair_player"("p_torneo_id" "uuid", "p_pareja_id" "uuid", "p_jugador_saliente_id" "uuid", "p_jugador_nuevo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_guard jsonb;
  v_player1 uuid;
  v_player2 uuid;
  v_is_virtual boolean;
  v_name text;
  v_slot text;
BEGIN
  v_guard := public.te_lock_categoria_editable(p_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    RETURN v_guard;
  END IF;

  IF p_pareja_id IS NULL OR p_jugador_saliente_id IS NULL OR p_jugador_nuevo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND gp.pareja_id = p_pareja_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_IN_TOURNAMENT');
  END IF;

  BEGIN
    PERFORM 1
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND (p.pareja_local_id = p_pareja_id OR p.pareja_visitante_id = p_pareja_id)
    FOR UPDATE OF p NOWAIT;
  EXCEPTION
    WHEN lock_not_available THEN
      RETURN jsonb_build_object('ok', false, 'error', 'PAIR_HAS_HISTORY');
  END;

  SELECT player1_id, player2_id, is_virtual
    INTO v_player1, v_player2, v_is_virtual
  FROM public.pairs
  WHERE id = p_pareja_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_FOUND');
  END IF;

  -- Una plaza virtual se resuelve con asignar jugadores, no con cambiar uno.
  IF v_is_virtual THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_IS_VIRTUAL');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND (p.pareja_local_id = p_pareja_id OR p.pareja_visitante_id = p_pareja_id)
      AND public.te_partido_tiene_historial(
        p.estado,
        p.ganador_id,
        p.puntos_local,
        p.puntos_visitante,
        p.sets_resultado
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_HAS_HISTORY');
  END IF;

  IF v_player1 = p_jugador_saliente_id THEN
    v_slot := 'player1';
  ELSIF v_player2 = p_jugador_saliente_id THEN
    v_slot := 'player2';
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'OUTGOING_NOT_IN_PAIR');
  END IF;

  IF (v_slot = 'player1' AND p_jugador_nuevo_id = v_player2)
     OR (v_slot = 'player2' AND p_jugador_nuevo_id = v_player1)
     OR p_jugador_nuevo_id = p_jugador_saliente_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NEW_IS_PARTNER');
  END IF;

  SELECT btrim(name) INTO v_name
  FROM public.players
  WHERE id = p_jugador_nuevo_id;

  IF v_name IS NULL OR v_name = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_NOT_FOUND');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    JOIN public.pairs pr ON pr.id = gp.pareja_id
    WHERE g.torneo_id = p_torneo_id
      AND gp.pareja_id <> p_pareja_id
      AND (pr.player1_id = p_jugador_nuevo_id OR pr.player2_id = p_jugador_nuevo_id)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_ALREADY_REGISTERED');
  END IF;

  -- Revalidar historial con los locks ya tomados, antes de escribir.
  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND (p.pareja_local_id = p_pareja_id OR p.pareja_visitante_id = p_pareja_id)
      AND public.te_partido_tiene_historial(
        p.estado,
        p.ganador_id,
        p.puntos_local,
        p.puntos_visitante,
        p.sets_resultado
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_HAS_HISTORY');
  END IF;

  IF v_slot = 'player1' THEN
    UPDATE public.pairs
    SET player1_id = p_jugador_nuevo_id,
        player1_name = v_name
    WHERE id = p_pareja_id;
  ELSE
    UPDATE public.pairs
    SET player2_id = p_jugador_nuevo_id,
        player2_name = v_name
    WHERE id = p_pareja_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pareja_id', p_pareja_id,
    'jugador_saliente_id', p_jugador_saliente_id,
    'jugador_nuevo_id', p_jugador_nuevo_id
  );
END;
$$;


ALTER FUNCTION "public"."replace_torneo_express_pair_player"("p_torneo_id" "uuid", "p_pareja_id" "uuid", "p_jugador_saliente_id" "uuid", "p_jugador_nuevo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_tournament_matches_if_unscored"("p_tournament_id" "uuid", "p_matches" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_scored_matches int := 0;
  v_games_count int := 0;
  v_existing int := 0;
  v_inserted int := 0;
  v_row jsonb;
  v_p1 uuid;
  v_p2 uuid;
  v_pair_ok int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'auth_required',
      'message', 'Debes iniciar sesión para reprogramar la reta.'
    );
  END IF;

  SELECT t.user_id INTO v_owner
  FROM public.tournaments t
  WHERE t.id = p_tournament_id
  FOR UPDATE;

  IF v_owner IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'tournament_not_found',
      'message', 'Reta no encontrada.'
    );
  END IF;

  IF v_owner IS DISTINCT FROM v_uid AND NOT public.is_master_admin() THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'forbidden',
      'message', 'Solo el organizador (o admin maestro) puede reprogramar.'
    );
  END IF;

  IF p_matches IS NULL OR jsonb_typeof(p_matches) <> 'array' OR jsonb_array_length(p_matches) = 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_payload',
      'message', 'p_matches debe ser un arreglo JSON no vacío.'
    );
  END IF;

  PERFORM 1 FROM public.matches m WHERE m.tournament_id = p_tournament_id FOR UPDATE;

  SELECT count(*)::int INTO v_existing
  FROM public.matches m WHERE m.tournament_id = p_tournament_id;

  SELECT count(*)::int INTO v_scored_matches
  FROM public.matches m
  WHERE m.tournament_id = p_tournament_id
    AND (
      m.status = 'finished'
      OR m.pair1_score IS NOT NULL
      OR m.pair2_score IS NOT NULL
    );

  SELECT count(*)::int INTO v_games_count
  FROM public.games g
  WHERE g.match_id IN (
    SELECT m.id FROM public.matches m WHERE m.tournament_id = p_tournament_id
  );

  IF v_scored_matches > 0 OR v_games_count > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'has_results',
      'message', format(
        'Hay resultados (matches=%s, games=%s). No se regeneró el calendario.',
        v_scored_matches,
        v_games_count
      ),
      'scored_matches', v_scored_matches,
      'games_count', v_games_count,
      'existing_matches', v_existing
    );
  END IF;

  -- Validar pertenencia de parejas al torneo antes de borrar.
  FOR v_row IN SELECT * FROM jsonb_array_elements(p_matches)
  LOOP
    v_p1 := (v_row->>'pair1_id')::uuid;
    v_p2 := (v_row->>'pair2_id')::uuid;
    IF v_p1 IS NULL OR v_p2 IS NULL OR v_p1 = v_p2 THEN
      RAISE EXCEPTION 'invalid_pair_ids';
    END IF;
    SELECT count(*)::int INTO v_pair_ok
    FROM public.pairs p
    WHERE p.tournament_id = p_tournament_id
      AND p.id IN (v_p1, v_p2);
    IF v_pair_ok <> 2 THEN
      RAISE EXCEPTION 'pair_not_in_tournament: % / %', v_p1, v_p2;
    END IF;
  END LOOP;

  DELETE FROM public.matches WHERE tournament_id = p_tournament_id;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_matches)
  LOOP
    INSERT INTO public.matches (
      tournament_id, pair1_id, pair2_id, pair1_name, pair2_name, court, round, status
    ) VALUES (
      p_tournament_id,
      (v_row->>'pair1_id')::uuid,
      (v_row->>'pair2_id')::uuid,
      coalesce(v_row->>'pair1_name', ''),
      coalesce(v_row->>'pair2_name', ''),
      CASE WHEN nullif(v_row->>'court', '') IS NOT NULL THEN (v_row->>'court')::int ELSE NULL END,
      CASE WHEN nullif(v_row->>'round', '') IS NOT NULL THEN (v_row->>'round')::int ELSE 1 END,
      coalesce(nullif(v_row->>'status', ''), 'pending')
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'inserted', v_inserted,
    'replaced_existing', v_existing
  );
END;
$$;


ALTER FUNCTION "public"."replace_tournament_matches_if_unscored"("p_tournament_id" "uuid", "p_matches" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_tournament_matches_if_unscored"("p_tournament_id" "uuid", "p_matches" "jsonb") IS 'Reemplaza el calendario de una reta en una sola transacción solo si no hay marcadores en matches ni filas en games.';



CREATE OR REPLACE FUNCTION "public"."reschedule_coach_class"("p_organizador_id" "uuid", "p_session_id" "uuid", "p_new_starts_at" timestamp with time zone, "p_duration_minutes" integer DEFAULT NULL::integer, "p_court" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_sess record;
  v_duration integer;
  v_new_ends_at timestamptz;
  v_effective_court text;
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo el club puede reprogramar clases.');
  END IF;

  IF p_new_starts_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La nueva fecha y hora son requeridas.');
  END IF;

  SELECT *
  INTO v_sess
  FROM public.coach_sessions
  WHERE id = p_session_id AND organizador_id = p_organizador_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sesión no encontrada o no pertenece a este club.');
  END IF;

  IF v_sess.status <> 'SCHEDULED' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo se pueden reprogramar clases en estado programada (SCHEDULED). Estado actual: ' || v_sess.status || '.');
  END IF;

  -- GUARDA DE BACKEND: No reprogramar sesiones si la relación deportiva fue pausada o terminada
  IF v_sess.relationship_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.coach_player_relationships
      WHERE id = v_sess.relationship_id AND status <> 'ACTIVE'
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'No se puede reprogramar una clase de un alumno con relación deportiva en pausa o terminada.'
      );
    END IF;
  END IF;

  v_duration := COALESCE(p_duration_minutes, v_sess.duration_minutes, 60);
  v_new_ends_at := p_new_starts_at + (v_duration || ' minutes')::interval;
  v_effective_court := COALESCE(NULLIF(btrim(COALESCE(p_court, '')), ''), v_sess.court);

  PERFORM pg_advisory_xact_lock(hashtext('coach_schedule:' || v_sess.coach_id::text)::bigint);
  PERFORM pg_advisory_xact_lock(hashtext('student_schedule:' || v_sess.jugador_id::text)::bigint);
  IF v_effective_court IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('court_schedule:' || p_organizador_id::text || ':' || lower(v_effective_court))::bigint);
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.coach_sessions
    WHERE coach_id = v_sess.coach_id
      AND id <> p_session_id
      AND status = 'SCHEDULED'
      AND tstzrange(starts_at, ends_at) && tstzrange(p_new_starts_at, v_new_ends_at)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El entrenador ya tiene otra clase agendada en ese horario.');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.coach_sessions
    WHERE jugador_id = v_sess.jugador_id
      AND id <> p_session_id
      AND status = 'SCHEDULED'
      AND tstzrange(starts_at, ends_at) && tstzrange(p_new_starts_at, v_new_ends_at)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El alumno ya tiene otra clase agendada en ese horario.');
  END IF;

  IF v_effective_court IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.coach_sessions
      WHERE organizador_id = p_organizador_id
        AND id <> p_session_id
        AND lower(btrim(court)) = lower(v_effective_court)
        AND status = 'SCHEDULED'
        AND tstzrange(starts_at, ends_at) && tstzrange(p_new_starts_at, v_new_ends_at)
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'La cancha "' || v_effective_court || '" ya está reservada en ese horario.');
    END IF;
  END IF;

  UPDATE public.coach_sessions
  SET starts_at = p_new_starts_at,
      ends_at = v_new_ends_at,
      duration_minutes = v_duration,
      court = v_effective_court,
      notes_summary = CASE
        WHEN p_reason IS NOT NULL AND btrim(p_reason) <> ''
        THEN COALESCE(notes_summary || ' | ', '') || 'Reprogramada: ' || btrim(p_reason)
        ELSE notes_summary
      END,
      updated_at = v_now
  WHERE id = p_session_id;

  INSERT INTO public.coach_audit_log (
    actor_auth_user_id,
    action,
    entity_type,
    entity_id,
    payload,
    created_at
  ) VALUES (
    v_caller,
    'CLASS_RESCHEDULED',
    'coach_sessions',
    p_session_id,
    jsonb_build_object(
      'previous_starts_at', v_sess.starts_at,
      'new_starts_at', p_new_starts_at,
      'previous_court', v_sess.court,
      'new_court', v_effective_court,
      'reason', p_reason
    ),
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id,
    'starts_at', p_new_starts_at,
    'ends_at', v_new_ends_at,
    'duration_minutes', v_duration,
    'court', v_effective_court,
    'message', 'Clase reprogramada exitosamente.'
  );
END;
$$;


ALTER FUNCTION "public"."reschedule_coach_class"("p_organizador_id" "uuid", "p_session_id" "uuid", "p_new_starts_at" timestamp with time zone, "p_duration_minutes" integer, "p_court" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_torneo_express_grupo"("p_grupo_id" "uuid", "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_torneo_id uuid;
  v_version integer;
  v_guard jsonb;
  v_partido record;
  v_ref text;
  v_rating_rows integer;
  v_matches_reset integer := 0;
  v_ratings_reverted integer := 0;
  v_local uuid;
  v_visit uuid;
BEGIN
  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  SELECT torneo_id INTO v_torneo_id
  FROM public.torneo_express_grupos
  WHERE id = p_grupo_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  v_guard := public.te_lock_categoria_editable(v_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    IF (v_guard ->> 'error') IN ('TOURNAMENT_NOT_EDITABLE', 'ELIMINATORIA_EXISTS') THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'GROUP_NOT_EDITABLE', 'reason', v_guard ->> 'error'
      );
    END IF;
    RETURN v_guard;
  END IF;

  SELECT version INTO v_version
  FROM public.torneo_express_grupos
  WHERE id = p_grupo_id
  FOR UPDATE;

  IF p_expected_version IS NULL OR p_expected_version IS DISTINCT FROM v_version THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'STALE_GROUP_VERSION', 'version', v_version
    );
  END IF;

  PERFORM 1
  FROM public.torneo_express_partidos
  WHERE grupo_id = p_grupo_id
  ORDER BY id
  FOR UPDATE;

  FOR v_partido IN
    SELECT id, estado, puntos_local, puntos_visitante, ganador_id, sets_resultado,
           pareja_local_id, pareja_visitante_id
    FROM public.torneo_express_partidos
    WHERE grupo_id = p_grupo_id
    ORDER BY id
  LOOP
    v_ref := 'te-grupo:' || v_partido.id::text;
    SELECT count(*) INTO v_rating_rows
    FROM public.rating_historial
    WHERE partido_ref = v_ref;
    PERFORM public._revert_rating_for_partido_ref(v_ref);
    IF v_rating_rows > 0 THEN
      v_ratings_reverted := v_ratings_reverted + 1;
    END IF;

    v_local := public.te_slot_pareja_actual(p_grupo_id, v_partido.pareja_local_id);
    v_visit := public.te_slot_pareja_actual(p_grupo_id, v_partido.pareja_visitante_id);

    IF v_local IS NULL OR v_visit IS NULL THEN
      DELETE FROM public.torneo_express_partidos WHERE id = v_partido.id;
      v_matches_reset := v_matches_reset + 1;
    ELSIF v_partido.estado IS DISTINCT FROM 'pendiente'
       OR v_partido.puntos_local IS NOT NULL
       OR v_partido.puntos_visitante IS NOT NULL
       OR v_partido.ganador_id IS NOT NULL
       OR v_partido.sets_resultado IS NOT NULL
       OR v_partido.pareja_local_id IS DISTINCT FROM v_local
       OR v_partido.pareja_visitante_id IS DISTINCT FROM v_visit THEN
      UPDATE public.torneo_express_partidos
      SET puntos_local = NULL,
          puntos_visitante = NULL,
          sets_resultado = NULL,
          ganador_id = NULL,
          estado = 'pendiente',
          pareja_local_id = v_local,
          pareja_visitante_id = v_visit
      WHERE id = v_partido.id;
      v_matches_reset := v_matches_reset + 1;
    END IF;
  END LOOP;

  UPDATE public.torneo_express_grupos
  SET version = version + 1
  WHERE id = p_grupo_id;

  RETURN jsonb_build_object(
    'ok', true,
    'group_id', p_grupo_id,
    'matches_reset', v_matches_reset,
    'ratings_reverted', v_ratings_reverted,
    'version', v_version + 1
  );
END;
$$;


ALTER FUNCTION "public"."reset_torneo_express_grupo"("p_grupo_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_torneo_express_grupo_partido"("p_partido_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_partido record;
  v_torneo record;
  v_lock_torneo uuid;
  v_lock_grupo uuid;
  v_ref text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_partido_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT g.torneo_id, p.grupo_id
    INTO v_lock_torneo, v_lock_grupo
  FROM public.torneo_express_partidos p
  JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
  WHERE p.id = p_partido_id;

  IF v_lock_torneo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT id, organizador_id, fase_torneo, estado
    INTO v_torneo
  FROM public.torneo_express
  WHERE id = v_lock_torneo
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_torneo.organizador_id IS NULL
     OR v_torneo.organizador_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  IF v_torneo.fase_torneo = 'cerrado' OR v_torneo.estado = 'finalizado' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'torneo_cerrado');
  END IF;

  IF v_torneo.fase_torneo IS DISTINCT FROM 'grupos' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'group_not_editable');
  END IF;

  PERFORM 1
  FROM public.torneo_express_grupos
  WHERE id = v_lock_grupo
  FOR UPDATE;

  SELECT id, grupo_id, estado, puntos_local, puntos_visitante,
         ganador_id, sets_resultado
    INTO v_partido
  FROM public.torneo_express_partidos
  WHERE id = p_partido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_partido.estado IS NOT DISTINCT FROM 'pendiente'
     AND v_partido.puntos_local IS NULL
     AND v_partido.puntos_visitante IS NULL
     AND v_partido.ganador_id IS NULL
     AND v_partido.sets_resultado IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'unchanged',
      'partido_id', p_partido_id
    );
  END IF;

  v_ref := 'te-grupo:' || p_partido_id::text;
  BEGIN
    PERFORM public._revert_rating_for_partido_ref(v_ref);
  EXCEPTION
    WHEN undefined_function THEN
      NULL;
  END;

  UPDATE public.torneo_express_partidos
  SET puntos_local = NULL,
      puntos_visitante = NULL,
      sets_resultado = NULL,
      ganador_id = NULL,
      estado = 'pendiente'
  WHERE id = p_partido_id;

  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'torneo_express_grupos'
      AND column_name = 'version'
  ) THEN
    UPDATE public.torneo_express_grupos
    SET version = version + 1
    WHERE id = v_lock_grupo;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'updated',
    'partido_id', p_partido_id,
    'grupo_id', v_lock_grupo,
    'torneo_id', v_lock_torneo
  );
END;
$$;


ALTER FUNCTION "public"."reset_torneo_express_grupo_partido"("p_partido_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reset_torneo_express_grupo_partido"("p_partido_id" "uuid") IS 'Borra el marcador de un partido de grupos y revierte su rating. Solo en fase de grupos.';



CREATE OR REPLACE FUNCTION "public"."resolve_official_player_key_for_jugador"("p_riviera_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key uuid;
BEGIN
  IF p_riviera_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_key := public._resolve_official_player_key(p_riviera_jugador_id);

  IF v_key IS NOT NULL THEN
    RETURN v_key;
  END IF;

  RETURN public._ensure_official_identity_for_participation_jugador(p_riviera_jugador_id);
END;
$$;


ALTER FUNCTION "public"."resolve_official_player_key_for_jugador"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_player_by_riviera_id"("p_riviera_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_grantee uuid := auth.uid();
  v_identity record;
  v_existing record;
  v_already_member boolean := false;
BEGIN
  IF v_grantee IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  SELECT *
  INTO v_identity
  FROM public._resolve_identity_by_riviera_id(p_riviera_id);

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'found', false,
      'riviera_id', public._normalize_riviera_id_exact(p_riviera_id)
    );
  END IF;

  SELECT opa.id, opa.local_jugador_id
  INTO v_existing
  FROM public.organizer_player_access opa
  WHERE opa.grantee_organizer_id = v_grantee
    AND opa.jugador_id = v_identity.canonical_riviera_jugador_id
    AND opa.is_active = true
  LIMIT 1;

  IF FOUND THEN
    v_already_member := true;
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'riviera_id', v_identity.riviera_id,
    'display_name', v_identity.display_name,
    'registration_organizer_id', v_identity.registration_organizer_id,
    'already_member', v_already_member,
    'local_jugador_id', v_existing.local_jugador_id,
    'membership_id', v_existing.id
  );
END;
$$;


ALTER FUNCTION "public"."resolve_player_by_riviera_id"("p_riviera_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_player_by_riviera_id"("p_riviera_id" "text") IS 'Sprint 2.1.2 — Resuelve jugador por Riviera ID exacto (RIV-00000001). Solo nombre público + estado de membresía del organizador actual. No busca por nombre/correo/teléfono. No crea identidad.';



CREATE OR REPLACE FUNCTION "public"."resolve_public_club_player_context"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS TABLE("id" "uuid", "organizador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "email" "text", "telefono" "text", "whatsapp" "text", "nivel" "text", "categoria" "text", "edad" integer, "mano_dominante" "text", "en_cancha" "text", "pais_codigo" "text", "instagram_url" "text", "facebook_url" "text", "tiktok_url" "text", "visible_publico" boolean, "suma_ranking" boolean, "genero" "text", "fecha_nacimiento" "date", "club" "text", "estado" "text", "legacy_player_id" "uuid", "legacy_liga_jugador_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "rating" numeric, "rating_partidos" integer, "rating_fiabilidad" numeric, "puntos_totales" integer, "total_partidos" integer, "victorias" integer, "derrotas" integer, "empates" integer, "participaciones_solo" integer, "pct_victorias" numeric, "total_retas" integer, "total_torneos_express" integer, "total_ligas" integer, "total_americanos" integer, "sets_favor_total" integer, "sets_contra_total" integer, "racha_actual" "text", "ultima_actividad" timestamp with time zone, "stats_updated_at" timestamp with time zone, "concedido" boolean, "source_jugador_id" "uuid", "owner_organizador_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_roster_id uuid;
  v_concedido boolean := false;
  v_source_id uuid := null;
  v_owner_org uuid := null;
  v_display_name text := null;
  v_display_cat text := null;
BEGIN
  -- Revocado: no resoluble en ranking público.
  IF EXISTS (
    SELECT 1
    FROM public.organizer_player_access opa
    WHERE opa.grantee_organizer_id = p_organizador_id
      AND opa.is_active = false
      AND opa.local_jugador_id = p_jugador_id
  ) THEN
    RETURN;
  END IF;

  -- 1) Nativo activo del club (incluye visible_publico=false).
  SELECT rj.id
  INTO v_roster_id
  FROM public.riviera_jugadores rj
  WHERE rj.organizador_id = p_organizador_id
    AND rj.id = p_jugador_id
    AND rj.estado = 'activo'
  LIMIT 1;

  IF v_roster_id IS NOT NULL THEN
    SELECT
      true,
      opa.jugador_id,
      opa.owner_organizador_id,
      opa.local_display_name,
      opa.local_category
    INTO v_concedido, v_source_id, v_owner_org, v_display_name, v_display_cat
    FROM public.organizer_player_access opa
    WHERE opa.grantee_organizer_id = p_organizador_id
      AND opa.is_active = true
      AND opa.local_jugador_id = v_roster_id
    LIMIT 1;
    IF NOT FOUND THEN
      v_concedido := false;
      v_source_id := null;
      v_owner_org := null;
    END IF;
  END IF;

  -- 2) Lookup por source → clon local.
  IF v_roster_id IS NULL THEN
    SELECT
      opa.local_jugador_id,
      true,
      opa.jugador_id,
      opa.owner_organizador_id,
      opa.local_display_name,
      opa.local_category
    INTO v_roster_id, v_concedido, v_source_id, v_owner_org, v_display_name, v_display_cat
    FROM public.organizer_player_access opa
    JOIN public.riviera_jugadores local_rj
      ON local_rj.id = opa.local_jugador_id
     AND local_rj.organizador_id = p_organizador_id
     AND local_rj.estado = 'activo'
    WHERE opa.grantee_organizer_id = p_organizador_id
      AND opa.is_active = true
      AND opa.jugador_id = p_jugador_id
      AND opa.local_jugador_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.organizer_player_access rev
        WHERE rev.grantee_organizer_id = p_organizador_id
          AND rev.is_active = false
          AND rev.local_jugador_id = opa.local_jugador_id
      )
    LIMIT 1;
  END IF;

  -- 3) Grant sintético (sin clon): roster = source.
  IF v_roster_id IS NULL THEN
    SELECT
      opa.jugador_id,
      true,
      opa.jugador_id,
      opa.owner_organizador_id,
      opa.local_display_name,
      opa.local_category
    INTO v_roster_id, v_concedido, v_source_id, v_owner_org, v_display_name, v_display_cat
    FROM public.organizer_player_access opa
    JOIN public.riviera_jugadores src
      ON src.id = opa.jugador_id
     AND src.estado = 'activo'
    WHERE opa.grantee_organizer_id = p_organizador_id
      AND opa.is_active = true
      AND opa.local_jugador_id IS NULL
      AND opa.jugador_id = p_jugador_id
    LIMIT 1;
  END IF;

  IF v_roster_id IS NULL THEN
    RETURN;
  END IF;

  -- Fila local del club si existe; si no, source (sintético).
  RETURN QUERY
  SELECT
    COALESCE(local_rj.id, src.id) AS id,
    p_organizador_id AS organizador_id,
    COALESCE(
      NULLIF(TRIM(v_display_name), ''),
      local_rj.nombre,
      src.nombre,
      'Jugador'
    ) AS nombre,
    COALESCE(local_rj.slug, src.slug) AS slug,
    COALESCE(local_rj.foto_url, src.foto_url) AS foto_url,
    NULL::text AS email,
    NULL::text AS telefono,
    NULL::text AS whatsapp,
    COALESCE(local_rj.nivel::text, src.nivel::text) AS nivel,
    COALESCE(
      NULLIF(TRIM(v_display_cat), ''),
      local_rj.categoria,
      src.categoria
    ) AS categoria,
    COALESCE(local_rj.edad, src.edad)::integer AS edad,
    COALESCE(local_rj.mano_dominante, src.mano_dominante) AS mano_dominante,
    COALESCE(local_rj.en_cancha, src.en_cancha) AS en_cancha,
    COALESCE(local_rj.pais_codigo::text, src.pais_codigo::text) AS pais_codigo,
    COALESCE(local_rj.instagram_url, src.instagram_url) AS instagram_url,
    COALESCE(local_rj.facebook_url, src.facebook_url) AS facebook_url,
    COALESCE(local_rj.tiktok_url, src.tiktok_url) AS tiktok_url,
    COALESCE(local_rj.visible_publico, src.visible_publico) AS visible_publico,
    COALESCE(local_rj.suma_ranking, src.suma_ranking) AS suma_ranking,
    COALESCE(local_rj.genero, src.genero) AS genero,
    NULL::date AS fecha_nacimiento,
    COALESCE(local_rj.club, src.club) AS club,
    COALESCE(local_rj.estado::text, src.estado::text) AS estado,
    COALESCE(local_rj.legacy_player_id, src.legacy_player_id) AS legacy_player_id,
    COALESCE(local_rj.legacy_liga_jugador_id, src.legacy_liga_jugador_id) AS legacy_liga_jugador_id,
    COALESCE(local_rj.created_at, src.created_at) AS created_at,
    COALESCE(local_rj.updated_at, src.updated_at) AS updated_at,
    COALESCE(local_rj.rating, src.rating) AS rating,
    COALESCE(local_rj.rating_partidos, src.rating_partidos) AS rating_partidos,
    COALESCE(local_rj.rating_fiabilidad, src.rating_fiabilidad) AS rating_fiabilidad,
    COALESCE(js.puntos_totales, 0)::integer AS puntos_totales,
    COALESCE(js.total_partidos, 0)::integer AS total_partidos,
    COALESCE(js.victorias, 0)::integer AS victorias,
    COALESCE(js.derrotas, 0)::integer AS derrotas,
    COALESCE(js.empates, 0)::integer AS empates,
    COALESCE(js.participaciones_solo, 0)::integer AS participaciones_solo,
    COALESCE(js.pct_victorias, 0)::numeric AS pct_victorias,
    COALESCE(js.total_retas, 0)::integer AS total_retas,
    COALESCE(js.total_torneos_express, 0)::integer AS total_torneos_express,
    COALESCE(js.total_ligas, 0)::integer AS total_ligas,
    COALESCE(js.total_americanos, 0)::integer AS total_americanos,
    COALESCE(js.sets_favor_total, 0)::integer AS sets_favor_total,
    COALESCE(js.sets_contra_total, 0)::integer AS sets_contra_total,
    COALESCE(js.racha_actual, '')::text AS racha_actual,
    js.ultima_actividad::timestamptz AS ultima_actividad,
    js.updated_at AS stats_updated_at,
    COALESCE(v_concedido, false) AS concedido,
    v_source_id AS source_jugador_id,
    v_owner_org AS owner_organizador_id
  FROM (SELECT v_roster_id AS rid) r
  LEFT JOIN public.riviera_jugadores local_rj
    ON local_rj.id = r.rid
   AND local_rj.organizador_id = p_organizador_id
  LEFT JOIN public.riviera_jugadores src
    ON src.id = r.rid
   AND local_rj.id IS NULL
  LEFT JOIN public.jugador_stats js
    ON js.jugador_id = COALESCE(local_rj.id, src.id)
  WHERE COALESCE(local_rj.id, src.id) IS NOT NULL
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."resolve_public_club_player_context"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_public_club_player_context"("p_organizador_id" "uuid", "p_jugador_id" "uuid") IS 'Ficha pública contextual del ranking del club. PII siempre NULL. No exige visible_publico=true.';



CREATE OR REPLACE FUNCTION "public"."resolve_public_player_identity"("p_jugador_id" "uuid" DEFAULT NULL::"uuid", "p_riviera_id" "text" DEFAULT NULL::"text") RETURNS TABLE("anchor_jugador_id" "uuid", "canonical_jugador_id" "uuid", "riviera_id" "text", "official_player_key" "text", "home_organizador_id" "uuid", "linked_jugador_id" "uuid", "linked_organizador_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH anchor AS (
    SELECT COALESCE(
      p_jugador_id,
      (
        SELECT i.canonical_riviera_jugador_id
        FROM public.riviera_official_player_identity i
        WHERE i.riviera_id = NULLIF(TRIM(p_riviera_id), '')
        LIMIT 1
      )
    ) AS jugador_id
  ),
  official AS (
    SELECT public._resolve_official_player_key(a.jugador_id) AS official_key
    FROM anchor a
    WHERE a.jugador_id IS NOT NULL
  ),
  career AS (
    SELECT g.jugador_id
    FROM anchor a
    CROSS JOIN LATERAL public.get_public_career_jugador_ids(a.jugador_id) AS g(jugador_id)
    WHERE a.jugador_id IS NOT NULL
  ),
  linked AS (
    SELECT DISTINCT c.jugador_id
    FROM career c
    WHERE c.jugador_id IS NOT NULL
  ),
  identity_row AS (
    SELECT
      i.riviera_id::text AS riviera_id,
      i.official_player_key::text AS official_player_key,
      i.canonical_riviera_jugador_id AS canonical_jugador_id
    FROM official o
    JOIN public.riviera_official_player_identity i
      ON i.official_player_key = o.official_key
    WHERE o.official_key IS NOT NULL
    LIMIT 1
  ),
  home AS (
    SELECT rj.organizador_id
    FROM anchor a
    JOIN public.riviera_jugadores rj ON rj.id = a.jugador_id
    WHERE rj.estado = 'activo'
    LIMIT 1
  )
  SELECT
    a.jugador_id AS anchor_jugador_id,
    COALESCE(ir.canonical_jugador_id, a.jugador_id) AS canonical_jugador_id,
    ir.riviera_id,
    ir.official_player_key,
    h.organizador_id AS home_organizador_id,
    l.jugador_id AS linked_jugador_id,
    rj.organizador_id AS linked_organizador_id
  FROM anchor a
  CROSS JOIN linked l
  LEFT JOIN identity_row ir ON true
  LEFT JOIN home h ON true
  LEFT JOIN public.riviera_jugadores rj
    ON rj.id = l.jugador_id
   AND rj.estado = 'activo'
  WHERE a.jugador_id IS NOT NULL;
$$;


ALTER FUNCTION "public"."resolve_public_player_identity"("p_jugador_id" "uuid", "p_riviera_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_public_player_identity"("p_jugador_id" "uuid", "p_riviera_id" "text") IS 'Identidad global pública: Riviera ID, official_player_key y perfiles enlazados (cross-org).';



CREATE OR REPLACE FUNCTION "public"."resolve_public_player_identity_batch"("p_jugador_ids" "uuid"[]) RETURNS TABLE("anchor_jugador_id" "uuid", "canonical_jugador_id" "uuid", "riviera_id" "text", "official_player_key" "text", "home_organizador_id" "uuid", "linked_jugador_id" "uuid", "linked_organizador_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH anchor AS (
    SELECT DISTINCT unnest(COALESCE(p_jugador_ids, ARRAY[]::uuid[])) AS jugador_id
  ),
  official AS (
    SELECT
      a.jugador_id AS anchor_jugador_id,
      public._resolve_official_player_key(a.jugador_id) AS official_key
    FROM anchor a
  ),
  linked AS (
    SELECT DISTINCT g.anchor_jugador_id, g.jugador_id
    FROM public.get_public_career_jugador_ids_batch(p_jugador_ids) g
    WHERE g.jugador_id IS NOT NULL
  ),
  identity_row AS (
    SELECT DISTINCT ON (o.anchor_jugador_id)
      o.anchor_jugador_id,
      i.riviera_id::text AS riviera_id,
      i.official_player_key::text AS official_player_key,
      i.canonical_riviera_jugador_id AS canonical_jugador_id
    FROM official o
    JOIN public.riviera_official_player_identity i
      ON i.official_player_key = o.official_key
    WHERE o.official_key IS NOT NULL
    ORDER BY o.anchor_jugador_id
  ),
  home AS (
    SELECT DISTINCT ON (a.jugador_id)
      a.jugador_id AS anchor_jugador_id,
      rj.organizador_id
    FROM anchor a
    JOIN public.riviera_jugadores rj ON rj.id = a.jugador_id
    WHERE rj.estado = 'activo'
    ORDER BY a.jugador_id
  )
  SELECT
    a.jugador_id AS anchor_jugador_id,
    COALESCE(ir.canonical_jugador_id, a.jugador_id) AS canonical_jugador_id,
    ir.riviera_id,
    ir.official_player_key,
    h.organizador_id AS home_organizador_id,
    l.jugador_id AS linked_jugador_id,
    rj.organizador_id AS linked_organizador_id
  FROM anchor a
  JOIN linked l ON l.anchor_jugador_id = a.jugador_id
  LEFT JOIN identity_row ir ON ir.anchor_jugador_id = a.jugador_id
  LEFT JOIN home h ON h.anchor_jugador_id = a.jugador_id
  LEFT JOIN public.riviera_jugadores rj
    ON rj.id = l.jugador_id
   AND rj.estado = 'activo';
$$;


ALTER FUNCTION "public"."resolve_public_player_identity_batch"("p_jugador_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_student_login_identifier"("p_identifier" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $_$
DECLARE
  v_clean text := upper(btrim(COALESCE(p_identifier, '')));
  v_email text;
BEGIN
  IF v_clean = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Identificador no proporcionado.');
  END IF;

  IF position('@' in v_clean) > 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'email', lower(btrim(p_identifier)),
      'resolved_from', 'email'
    );
  END IF;

  IF NOT (v_clean ~ '^RIV-[0-9A-Z]{3,16}$') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Identificador no válido.');
  END IF;

  SELECT COALESCE(NULLIF(btrim(al.student_email), ''), u.email)
  INTO v_email
  FROM public.riviera_official_player_identity i
  JOIN public.coach_student_account_links al
    ON al.jugador_id = i.canonical_riviera_jugador_id
  LEFT JOIN auth.users u
    ON u.id = al.auth_user_id
  WHERE upper(btrim(i.riviera_id)) = v_clean
  ORDER BY al.is_active DESC, al.updated_at DESC
  LIMIT 1;

  IF v_email IS NULL THEN
    SELECT COALESCE(NULLIF(btrim(inv.email), ''), u.email)
    INTO v_email
    FROM public.riviera_official_player_identity i
    JOIN public.coach_student_invitations inv
      ON inv.jugador_id = i.canonical_riviera_jugador_id
    LEFT JOIN auth.users u
      ON u.id = inv.auth_user_id
    WHERE upper(btrim(i.riviera_id)) = v_clean
      AND inv.status IN ('ACCEPTED', 'PENDING')
    ORDER BY inv.created_at DESC
    LIMIT 1;
  END IF;

  IF v_email IS NULL OR btrim(v_email) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Identificador no válido.');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'email', lower(btrim(v_email)),
    'riviera_id', v_clean,
    'resolved_from', 'riviera_id'
  );
END;
$_$;


ALTER FUNCTION "public"."resolve_student_login_identifier"("p_identifier" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_student_login_identifier"("p_identifier" "text") IS 'Resuelve el correo de un alumno desde su Riviera ID. Solo service_role. No indica si la cuenta existe al cliente.';



CREATE OR REPLACE FUNCTION "public"."resolve_torneo_express_virtual_pair"("p_torneo_id" "uuid", "p_pareja_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_accept_existing_history" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner uuid;
  v_fase text;
  v_estado text;
  v_is_virtual boolean;
  v_name1 text;
  v_name2 text;
  v_played integer := 0;
  v_updated integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_torneo_id IS NULL OR p_pareja_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_IN_TOURNAMENT');
  END IF;

  IF p_player1_id IS NULL OR p_player2_id IS NULL OR p_player1_id = p_player2_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_MATCH_PAYLOAD');
  END IF;

  -- lock-order: torneo
  SELECT organizador_id, fase_torneo, estado
    INTO v_owner, v_fase, v_estado
  FROM public.torneo_express
  WHERE id = p_torneo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOURNAMENT_NOT_FOUND');
  END IF;

  IF v_owner IS NULL OR v_owner IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  IF v_fase = 'cerrado' OR v_estado = 'finalizado' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOURNAMENT_CLOSED');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND gp.pareja_id = p_pareja_id
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.torneo_express_eliminatoria_partidos e
    WHERE e.torneo_id = p_torneo_id
      AND (
        e.pareja_local_id = p_pareja_id
        OR e.pareja_visitante_id = p_pareja_id
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_IN_TOURNAMENT');
  END IF;

  -- lock-order: partidos de grupo, luego eliminatoria, luego la pareja.
  PERFORM 1
  FROM public.torneo_express_partidos p
  JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
  WHERE g.torneo_id = p_torneo_id
    AND (p.pareja_local_id = p_pareja_id OR p.pareja_visitante_id = p_pareja_id)
  ORDER BY p.id
  FOR UPDATE OF p;

  PERFORM 1
  FROM public.torneo_express_eliminatoria_partidos e
  WHERE e.torneo_id = p_torneo_id
    AND (e.pareja_local_id = p_pareja_id OR e.pareja_visitante_id = p_pareja_id)
  ORDER BY e.id
  FOR UPDATE;

  SELECT is_virtual
    INTO v_is_virtual
  FROM public.pairs
  WHERE id = p_pareja_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_FOUND');
  END IF;

  IF NOT v_is_virtual THEN
    RETURN jsonb_build_object('ok', false, 'error', 'VIRTUAL_PAIR_ALREADY_RESOLVED');
  END IF;

  SELECT btrim(name) INTO v_name1 FROM public.players WHERE id = p_player1_id;
  SELECT btrim(name) INTO v_name2 FROM public.players WHERE id = p_player2_id;
  IF v_name1 IS NULL OR v_name1 = '' OR v_name2 IS NULL OR v_name2 = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_NOT_FOUND');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_grupo_parejas gp
    JOIN public.torneo_express_grupos g ON g.id = gp.grupo_id
    JOIN public.pairs pr ON pr.id = gp.pareja_id
    WHERE g.torneo_id = p_torneo_id
      AND gp.pareja_id <> p_pareja_id
      AND (
        pr.player1_id IN (p_player1_id, p_player2_id)
        OR pr.player2_id IN (p_player1_id, p_player2_id)
      )
  ) OR EXISTS (
    SELECT 1
    FROM public.torneo_express_eliminatoria_partidos e
    JOIN public.pairs pr
      ON pr.id = e.pareja_local_id OR pr.id = e.pareja_visitante_id
    WHERE e.torneo_id = p_torneo_id
      AND pr.id <> p_pareja_id
      AND (
        pr.player1_id IN (p_player1_id, p_player2_id)
        OR pr.player2_id IN (p_player1_id, p_player2_id)
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PLAYER_ALREADY_REGISTERED');
  END IF;

  SELECT count(*) INTO v_played
  FROM (
    SELECT p.id
    FROM public.torneo_express_partidos p
    JOIN public.torneo_express_grupos g ON g.id = p.grupo_id
    WHERE g.torneo_id = p_torneo_id
      AND (p.pareja_local_id = p_pareja_id OR p.pareja_visitante_id = p_pareja_id)
      AND public.te_partido_tiene_historial(
        p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
      )
    UNION ALL
    SELECT e.id
    FROM public.torneo_express_eliminatoria_partidos e
    WHERE e.torneo_id = p_torneo_id
      AND coalesce(e.es_bye, false) = false
      AND (e.pareja_local_id = p_pareja_id OR e.pareja_visitante_id = p_pareja_id)
      AND public.te_partido_tiene_historial(
        e.estado, e.ganador_id, e.puntos_local, e.puntos_visitante, e.sets_resultado
      )
  ) played;

  IF v_played > 0 AND NOT coalesce(p_accept_existing_history, false) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'VIRTUAL_PAIR_HAS_HISTORY',
      'played_count', v_played
    );
  END IF;

  UPDATE public.pairs
  SET is_virtual = false,
      virtual_label = NULL,
      player1_id = p_player1_id,
      player1_name = v_name1,
      player2_id = p_player2_id,
      player2_name = v_name2
  WHERE id = p_pareja_id
    AND is_virtual = true;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'VIRTUAL_PAIR_ALREADY_RESOLVED');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pareja_id', p_pareja_id,
    'player1_id', p_player1_id,
    'player2_id', p_player2_id,
    'played_count', v_played
  );
END;
$$;


ALTER FUNCTION "public"."resolve_torneo_express_virtual_pair"("p_torneo_id" "uuid", "p_pareja_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_accept_existing_history" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retirar_torneo_express_pareja_grupo"("p_grupo_id" "uuid", "p_pareja_id" "uuid", "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_torneo_id uuid;
  v_guard jsonb;
  v_version_guard jsonb;
  v_dropped integer := 0;
  v_version integer;
  v_ids uuid[];
BEGIN
  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;
  SELECT torneo_id INTO v_torneo_id
  FROM public.torneo_express_grupos WHERE id = p_grupo_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GROUP_NOT_FOUND');
  END IF;

  v_guard := public.te_lock_categoria_editable(v_torneo_id);
  IF NOT (v_guard ->> 'ok')::boolean THEN
    IF (v_guard ->> 'error') IN ('TOURNAMENT_NOT_EDITABLE', 'ELIMINATORIA_EXISTS') THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'GROUP_NOT_EDITABLE', 'reason', v_guard ->> 'error'
      );
    END IF;
    RETURN v_guard;
  END IF;

  PERFORM 1 FROM public.torneo_express_grupos WHERE id = p_grupo_id FOR UPDATE;
  v_version_guard := public.te_grupo_version_ok(p_grupo_id, p_expected_version);
  IF NOT (v_version_guard ->> 'ok')::boolean THEN
    RETURN v_version_guard;
  END IF;

  PERFORM 1
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = p_grupo_id
  ORDER BY pareja_id
  FOR UPDATE;

  IF NOT EXISTS (
    SELECT 1 FROM public.torneo_express_grupo_parejas
    WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PAIR_NOT_IN_GROUP');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.torneo_express_grupo_parejas
    WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id AND NOT activa
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'PAIR_ALREADY_WITHDRAWN',
      'version', (v_version_guard ->> 'version')::integer
    );
  END IF;

  SELECT pareja_previa_ids || ARRAY[pareja_id]
    INTO v_ids
  FROM public.torneo_express_grupo_parejas
  WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id;

  PERFORM 1
  FROM public.torneo_express_partidos
  WHERE grupo_id = p_grupo_id
    AND (pareja_local_id = ANY (v_ids) OR pareja_visitante_id = ANY (v_ids))
  ORDER BY id
  FOR UPDATE;

  UPDATE public.torneo_express_grupo_parejas
  SET activa = false, retirada_at = now()
  WHERE grupo_id = p_grupo_id AND pareja_id = p_pareja_id;

  DELETE FROM public.torneo_express_partidos p
  WHERE p.grupo_id = p_grupo_id
    AND (p.pareja_local_id = ANY (v_ids) OR p.pareja_visitante_id = ANY (v_ids))
    AND NOT public.te_partido_tiene_historial(
      p.estado, p.ganador_id, p.puntos_local, p.puntos_visitante, p.sets_resultado
    );
  GET DIAGNOSTICS v_dropped = ROW_COUNT;

  v_version := public.te_grupo_bump_version(p_grupo_id);
  RETURN jsonb_build_object(
    'ok', true,
    'pareja_id', p_pareja_id,
    'pendientes_retirados', v_dropped,
    'version', v_version
  );
END;
$$;


ALTER FUNCTION "public"."retirar_torneo_express_pareja_grupo"("p_grupo_id" "uuid", "p_pareja_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_dynamic_team_block"("p_tournament_id" "uuid", "p_block_number" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tournament record;
  v_block record;
  v_match_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  SELECT id, user_id INTO v_tournament
  FROM public.tournaments
  WHERE id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND OR v_tournament.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre esta reta';
  END IF;

  SELECT * INTO v_block
  FROM public.reta_dynamic_blocks
  WHERE tournament_id = p_tournament_id AND block_number = p_block_number
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT count(*) INTO v_match_count
  FROM public.matches
  WHERE tournament_id = p_tournament_id
    AND round BETWEEN v_block.round_start AND v_block.round_end;

  IF v_match_count > 0 THEN
    IF v_block.status = 'completed' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'already_completed');
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'matches_exist');
  END IF;

  -- Sin partidos en el rango: liberar tanto generating como completed huérfano
  DELETE FROM public.reta_dynamic_blocks WHERE id = v_block.id;

  RETURN jsonb_build_object('ok', true, 'status', 'released');
END;
$$;


ALTER FUNCTION "public"."retry_dynamic_team_block"("p_tournament_id" "uuid", "p_block_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_official_ledger_for_organizer"("p_organizador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_result jsonb;
  v_inserted int := 0;
  v_already int := 0;
  v_skipped int := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF p_organizador_id IS NULL THEN
    RAISE EXCEPTION 'organizador_id requerido';
  END IF;

  IF auth.uid() IS NULL OR NOT (public.is_master_admin() OR auth.uid() = p_organizador_id) THEN
    RAISE EXCEPTION 'Sin permiso para reintentar el ledger de este organizador';
  END IF;

  IF NOT public._is_official_ranking_emitter(p_organizador_id) THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'organizer_not_authorized',
      'organizador_id', p_organizador_id
    );
  END IF;

  FOR v_row IN
    SELECT jp.id
    FROM public.jugador_participaciones jp
    JOIN public.riviera_jugadores rj ON rj.id = jp.jugador_id
    WHERE rj.organizador_id = p_organizador_id
      AND COALESCE(jp.puntos_obtenidos, 0) > 0
      AND coalesce(jp.metadata->>'subtipo', '') <> 'ajuste_manual'
      AND NOT EXISTS (
        SELECT 1
        FROM public.riviera_official_points_ledger l
        WHERE l.participacion_id = jp.id
      )
    ORDER BY jp.created_at ASC
  LOOP
    v_result := public.try_write_riviera_official_ledger(v_row.id);
    v_results := v_results || jsonb_build_array(v_result);

    IF v_result->>'status' = 'inserted' THEN
      v_inserted := v_inserted + 1;
    ELSIF v_result->>'status' = 'already_exists' THEN
      v_already := v_already + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'organizador_id', p_organizador_id,
    'inserted', v_inserted,
    'already_exists', v_already,
    'skipped', v_skipped,
    'results', v_results
  );
END;
$$;


ALTER FUNCTION "public"."retry_official_ledger_for_organizer"("p_organizador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."retry_official_ledger_for_organizer"("p_organizador_id" "uuid") IS 'ROMC 2.2: reintenta ledger oficial para participaciones con puntos>0 sin fila en ledger. Idempotente.';



CREATE OR REPLACE FUNCTION "public"."reverse_riviera_official_ledger_for_participacion"("p_participacion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ledger record;
  v_owner uuid;
  v_part_jugador_id uuid;
  v_home_org uuid;
BEGIN
  IF p_participacion_id IS NULL THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'null_participacion_id');
  END IF;

  SELECT rj.organizador_id, jp.jugador_id
  INTO v_owner, v_part_jugador_id
  FROM public.jugador_participaciones jp
  JOIN public.riviera_jugadores rj ON rj.id = jp.jugador_id
  WHERE jp.id = p_participacion_id;

  IF v_owner IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'no_participation',
      'participacion_id', p_participacion_id
    );
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sin permiso para revertir esta participación';
  END IF;

  v_home_org := public._resolve_home_organizador_for_jugador(v_part_jugador_id);

  IF NOT public.is_master_admin()
     AND v_owner IS DISTINCT FROM auth.uid()
     AND (v_home_org IS NULL OR v_home_org IS DISTINCT FROM auth.uid()) THEN
    RAISE EXCEPTION 'Sin permiso para revertir esta participación';
  END IF;

  SELECT
    l.id,
    l.official_player_key,
    l.points,
    l.counts_for_official_ranking
  INTO v_ledger
  FROM public.riviera_official_points_ledger l
  WHERE l.participacion_id = p_participacion_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'no_ledger',
      'participacion_id', p_participacion_id
    );
  END IF;

  DELETE FROM public.riviera_official_points_ledger
  WHERE id = v_ledger.id;

  PERFORM public._recalc_official_player_totals(v_ledger.official_player_key);

  RETURN jsonb_build_object(
    'status', 'reversed',
    'participacion_id', p_participacion_id,
    'official_player_key', v_ledger.official_player_key,
    'points_reversed', v_ledger.points
  );
END;
$$;


ALTER FUNCTION "public"."reverse_riviera_official_ledger_for_participacion"("p_participacion_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_riviera_official_ledger_for_participacion"("p_participacion_id" "uuid") IS 'Revierte ledger oficial. Dueño del perfil local o club de registro (canonical).';



CREATE OR REPLACE FUNCTION "public"."revert_coach_class_session"("p_organizador_id" "uuid", "p_session_id" "uuid", "p_motivo" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_sess record;
  v_debit_ledger record;
  v_existing_adj record;
  v_bal record;
  v_new_balance integer;
  v_new_given integer;
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_trimmed_motivo text := NULLIF(btrim(COALESCE(p_motivo, '')), '');
  v_adj_id uuid;
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo el club puede revertir clases registradas por error.');
  END IF;

  IF v_trimmed_motivo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El motivo de la reversión es obligatorio.');
  END IF;

  SELECT *
  INTO v_sess
  FROM public.coach_sessions
  WHERE id = p_session_id AND organizador_id = p_organizador_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sesión no encontrada o no pertenece a este club.');
  END IF;

  IF v_sess.status <> 'COMPLETED' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo se pueden revertir sesiones que hayan sido marcadas como impartidas (COMPLETED).');
  END IF;

  SELECT *
  INTO v_debit_ledger
  FROM public.coach_class_ledger
  WHERE session_id = p_session_id AND tipo = 'CLASS_DEBIT'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se encontró el descuento de clase asociado a esta sesión en el ledger.');
  END IF;

  IF v_trimmed_key IS NOT NULL THEN
    SELECT *
    INTO v_existing_adj
    FROM public.coach_class_ledger
    WHERE idempotency_key = v_trimmed_key;

    IF FOUND THEN
      IF v_existing_adj.recorded_by <> v_caller
         OR v_existing_adj.organizador_id <> p_organizador_id
         OR v_existing_adj.relationship_id <> v_sess.relationship_id
         OR v_existing_adj.reference_ledger_id <> v_debit_ledger.id
         OR v_existing_adj.tipo <> 'ADJUSTMENT'
         OR v_existing_adj.delta <> 1 THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de idempotencia: la clave ya fue utilizada en otra operación o con parámetros distintos.'
        );
      END IF;

      SELECT balance_classes, total_classes_given
      INTO v_bal
      FROM public.coach_player_class_balances
      WHERE relationship_id = v_sess.relationship_id;

      RETURN jsonb_build_object(
        'ok', true,
        'idempotent', true,
        'adjustment_id', v_existing_adj.id,
        'new_balance', COALESCE(v_bal.balance_classes, 0),
        'total_classes_given', COALESCE(v_bal.total_classes_given, 0),
        'message', 'Operación idempotente: la clase ya fue revertida previamente.'
      );
    END IF;
  END IF;

  IF v_sess.reverted_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Esta clase ya fue revertida previamente el ' || to_char(v_sess.reverted_at, 'DD/MM/YYYY HH24:MI') || '. No se puede revertir dos veces.');
  END IF;

  SELECT *
  INTO v_bal
  FROM public.coach_player_class_balances
  WHERE relationship_id = v_sess.relationship_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Saldo de clases no encontrado para esta relación.');
  END IF;

  v_new_balance := COALESCE(v_bal.balance_classes, 0) + 1;
  v_new_given := GREATEST(0, COALESCE(v_bal.total_classes_given, 0) - 1);

  UPDATE public.coach_player_class_balances
  SET balance_classes = v_new_balance,
      total_classes_given = v_new_given,
      updated_at = v_now
  WHERE id = v_bal.id;

  INSERT INTO public.coach_class_ledger (
    relationship_id,
    organizador_id,
    coach_id,
    jugador_id,
    delta,
    tipo,
    notas,
    reference_ledger_id,
    idempotency_key,
    recorded_by,
    created_at
  )
  VALUES (
    v_sess.relationship_id,
    p_organizador_id,
    v_sess.coach_id,
    v_sess.jugador_id,
    1,
    'ADJUSTMENT',
    'Reversión de clase impartida: ' || v_trimmed_motivo,
    v_debit_ledger.id,
    v_trimmed_key,
    v_caller,
    v_now
  )
  RETURNING id INTO v_adj_id;

  UPDATE public.coach_sessions
  SET reverted_at = v_now,
      cancellation_reason = 'Revertida: ' || v_trimmed_motivo,
      updated_at = v_now
  WHERE id = p_session_id;

  INSERT INTO public.coach_audit_log (
    actor_auth_user_id,
    action,
    entity_type,
    entity_id,
    payload,
    created_at
  )
  VALUES (
    v_caller,
    'CLASS_SESSION_REVERTED',
    'coach_sessions',
    p_session_id,
    jsonb_build_object(
      'debit_ledger_id', v_debit_ledger.id,
      'adjustment_ledger_id', v_adj_id,
      'previous_balance', v_bal.balance_classes,
      'new_balance', v_new_balance,
      'previous_given', v_bal.total_classes_given,
      'new_given', v_new_given,
      'reason', v_trimmed_motivo
    ),
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'adjustment_id', v_adj_id,
    'new_balance', v_new_balance,
    'total_classes_given', v_new_given,
    'message', 'Clase impartida revertida correctamente. Se restauró 1 clase disponible al alumno.'
  );
END;
$$;


ALTER FUNCTION "public"."revert_coach_class_session"("p_organizador_id" "uuid", "p_session_id" "uuid", "p_motivo" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_accrue_one"("p_queue_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_q public.rewards_accrual_queue%ROWTYPE;
  v_c public.rewards_campaigns%ROWTYPE;
  v_lot uuid;
  v_closed timestamptz;
BEGIN
  -- 1) Bloquear exclusivamente la fila de la cola
  SELECT * INTO v_q
  FROM public.rewards_accrual_queue
  WHERE id = p_queue_id
  FOR UPDATE;

  IF NOT FOUND OR v_q.estado IN ('acreditada', 'omitida') THEN
    RETURN;
  END IF;

  -- 2) Leer closed_at de la review
  SELECT r.closed_at INTO v_closed
  FROM public.rewards_participation_reviews r
  WHERE r.id = v_q.review_id;

  -- 3) Si fue rechazada manualmente, omitir
  IF EXISTS (
    SELECT 1 FROM public.rewards_participation_reviews r
    WHERE r.id = v_q.review_id AND r.estado = 'rechazada'
  ) THEN
    UPDATE public.rewards_accrual_queue
    SET estado = 'omitida',
        last_error = 'Revisión rechazada manualmente',
        processed_at = now(),
        locked_at = NULL,
        worker_id = NULL
    WHERE id = v_q.id;
    RETURN;
  END IF;

  -- 4) Bloqueo de serialización de campaña: FOR NO KEY UPDATE
  -- REGLA: Permite serializar múltiples workers de Rewards sin bloquear ni
  -- ser bloqueado por los cerrojos FOR KEY SHARE del trigger deportivo.
  SELECT * INTO v_c
  FROM public.rewards_campaigns
  WHERE id = v_q.campaign_id
  FOR NO KEY UPDATE;

  IF NOT FOUND OR v_c.estado <> 'activa' THEN
    RAISE EXCEPTION 'Campaña no activa (id=%, estado=%)', v_q.campaign_id, COALESCE(v_c.estado, 'no_encontrada');
  END IF;

  -- 5) Verificar si usó beneficio de canje
  IF EXISTS (
    SELECT 1 FROM public.rewards_benefit_uses b
    WHERE b.participacion_id = v_q.participacion_id
  ) THEN
    UPDATE public.rewards_accrual_queue
    SET estado = 'omitida',
        last_error = 'Reta gratuita de Rewards',
        processed_at = now(),
        locked_at = NULL,
        worker_id = NULL
    WHERE id = v_q.id;
    RETURN;
  END IF;

  -- 6) Creación idempotente del lote de puntos
  SELECT id INTO v_lot
  FROM public.rewards_lots
  WHERE idempotency_key = v_q.idempotency_key;

  IF v_lot IS NULL THEN
    INSERT INTO public.rewards_lots (
      organizador_id, campaign_id, jugador_id, participacion_id, queue_id,
      tipo_evento, evento_id, idempotency_key, puntos_originales, puntos_restantes,
      earned_at, expires_at
    )
    VALUES (
      v_q.organizador_id, v_c.id, v_q.jugador_id, v_q.participacion_id, v_q.id,
      v_q.tipo_evento, v_q.evento_id, v_q.idempotency_key, v_c.puntos_por_participacion,
      v_c.puntos_por_participacion, COALESCE(v_closed, now()), v_c.canje_hasta
    )
    RETURNING id INTO v_lot;

    -- Movimiento en ledger
    INSERT INTO public.rewards_ledger (
      organizador_id, jugador_id, campaign_id, lot_id, tipo, puntos, idempotency_key, actor_id
    )
    VALUES (
      v_q.organizador_id, v_q.jugador_id, v_c.id, v_lot, 'acreditacion',
      v_c.puntos_por_participacion, 'acreditacion:' || v_q.idempotency_key, auth.uid()
    )
    ON CONFLICT (idempotency_key) DO NOTHING;

    -- Compensar obligaciones previas si existen
    PERFORM public.rewards_compensate_lot(v_lot);

    -- Si la ventana ya había cerrado, caducar remanente
    IF v_c.canje_hasta <= now() THEN
      INSERT INTO public.rewards_ledger (
        organizador_id, jugador_id, campaign_id, lot_id, tipo, puntos, idempotency_key, motivo
      )
      SELECT v_q.organizador_id, v_q.jugador_id, v_c.id, l.id,
             'cierre', -l.puntos_restantes, 'cierre:' || l.id::text,
             'La ventana de canje ya había cerrado'
      FROM public.rewards_lots l
      WHERE l.id = v_lot
        AND l.puntos_restantes > 0
      ON CONFLICT (idempotency_key) DO NOTHING;

      UPDATE public.rewards_lots
      SET puntos_restantes = 0
      WHERE id = v_lot
        AND puntos_restantes > 0;
    END IF;
  END IF;

  -- 7) Transición definitiva de cola
  UPDATE public.rewards_accrual_queue
  SET estado = 'acreditada',
      last_error = NULL,
      processed_at = now(),
      locked_at = NULL,
      worker_id = NULL,
      attempts = attempts + 1
  WHERE id = v_q.id;
END;
$$;


ALTER FUNCTION "public"."rewards_accrue_one"("p_queue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_adjust"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_campaign_id" "uuid", "p_puntos" integer, "p_motivo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_key text;
  v_event uuid;
  v_part uuid;
  v_campaign public.rewards_campaigns%ROWTYPE;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN
    RAISE EXCEPTION 'El ajuste necesita un motivo';
  END IF;
  IF p_puntos = 0 THEN
    RAISE EXCEPTION 'El ajuste no puede ser cero';
  END IF;
  SELECT * INTO v_campaign
  FROM public.rewards_campaigns
  WHERE id = p_campaign_id AND organizador_id = p_organizador_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaña no encontrada en este club';
  END IF;

  IF p_puntos > 0 THEN
    v_key := 'ajuste:' || gen_random_uuid()::text;
    v_event := gen_random_uuid();
    v_part := gen_random_uuid();
    INSERT INTO public.rewards_lots (
      organizador_id, campaign_id, jugador_id, participacion_id, tipo_evento, evento_id,
      idempotency_key, puntos_originales, puntos_restantes, earned_at
    )
    VALUES (
      p_organizador_id, p_campaign_id, p_jugador_id, v_part, 'ajuste', v_event,
      v_key,
      p_puntos, p_puntos, now()
    )
    RETURNING id INTO v_id;
  ELSE
    RAISE EXCEPTION 'El descuento administrativo se hace por reversión de un lote, no con saldo negativo';
  END IF;

  INSERT INTO public.rewards_ledger (
    organizador_id, jugador_id, campaign_id, lot_id, tipo, puntos, idempotency_key, motivo, actor_id
  )
  VALUES (
    p_organizador_id, p_jugador_id, p_campaign_id, v_id, 'ajuste', p_puntos,
    'ajuste:' || v_id::text, trim(p_motivo), auth.uid()
  );
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."rewards_adjust"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_campaign_id" "uuid", "p_puntos" integer, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_admin_incidents_list"("p_organizador_id" "uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_page int := GREATEST(COALESCE(p_page, 1), 1);
  v_limit int := GREATEST(COALESCE(p_page_size, 50), 1);
  v_offset int := (v_page - 1) * v_limit;
  v_total int := 0;
  v_error_count int := 0;
  v_pending_count int := 0;
  v_incidents jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);

  WITH raw_incidents AS (
    SELECT 
      q.id AS incident_id,
      'acreditacion_error' AS tipo_incidencia,
      q.participacion_id,
      q.jugador_id,
      q.tipo_evento,
      q.evento_id,
      q.campaign_id,
      c.nombre AS campaign_nombre,
      c.puntos_por_participacion AS puntos_esperados,
      q.last_error AS error_mensaje,
      q.attempts,
      q.created_at
    FROM public.rewards_accrual_queue q
    LEFT JOIN public.rewards_campaigns c ON c.id = q.campaign_id
    WHERE q.organizador_id = p_organizador_id
      AND q.estado = 'error'

    UNION ALL

    SELECT 
      r.id AS incident_id,
      'revision_pendiente' AS tipo_incidencia,
      r.participacion_id,
      r.jugador_id,
      r.tipo_evento,
      r.evento_id,
      r.campaign_id,
      c.nombre AS campaign_nombre,
      COALESCE(c.puntos_por_participacion, 10) AS puntos_esperados,
      COALESCE(r.motivo, 'Participación en revisión / pendiente de acreditación automática') AS error_mensaje,
      1 AS attempts,
      r.created_at
    FROM public.rewards_participation_reviews r
    LEFT JOIN public.rewards_campaigns c ON c.id = r.campaign_id
    WHERE r.organizador_id = p_organizador_id
      AND r.estado = 'pendiente'
      AND NOT EXISTS (
        SELECT 1 FROM public.rewards_accrual_queue q
        WHERE q.participacion_id = r.participacion_id
          AND q.organizador_id = p_organizador_id
          AND q.estado = 'error'
      )

    UNION ALL

    SELECT 
      ef.id AS incident_id,
      'fallo_inicial' AS tipo_incidencia,
      ef.participacion_id,
      jp.jugador_id,
      jp.tipo_evento::text,
      jp.evento_id,
      NULL::uuid AS campaign_id,
      'Sin asignar' AS campaign_nombre,
      10 AS puntos_esperados,
      ef.error AS error_mensaje,
      ef.attempts,
      ef.created_at
    FROM public.rewards_enqueue_failures ef
    JOIN public.jugador_participaciones jp ON jp.id = ef.participacion_id
    WHERE ef.resolved_at IS NULL
      AND COALESCE(
        NULLIF(trim(jp.metadata->>'organizador_id'), '')::uuid,
        public.riviera_participacion_expected_host_org(jp.tipo_evento::text, jp.evento_id::text)
      ) = p_organizador_id
      AND NOT EXISTS (
        SELECT 1 FROM public.rewards_accrual_queue q WHERE q.participacion_id = ef.participacion_id
      )
  ),
  enriched AS (
    SELECT 
      ri.*,
      rj.nombre AS jugador_nombre,
      COALESCE(rj.categoria, '') AS codigo_riviera
    FROM raw_incidents ri
    LEFT JOIN public.riviera_jugadores rj ON rj.id = ri.jugador_id
  ),
  counts AS (
    SELECT 
      COUNT(*)::int AS total_cnt,
      COUNT(*) FILTER (WHERE tipo_incidencia IN ('acreditacion_error', 'fallo_inicial'))::int AS err_cnt,
      COUNT(*) FILTER (WHERE tipo_incidencia = 'revision_pendiente')::int AS pend_cnt
    FROM enriched
  ),
  paged AS (
    SELECT * FROM enriched
    ORDER BY created_at DESC
    LIMIT v_limit OFFSET v_offset
  )
  SELECT 
    COALESCE((SELECT total_cnt FROM counts), 0),
    COALESCE((SELECT err_cnt FROM counts), 0),
    COALESCE((SELECT pend_cnt FROM counts), 0),
    COALESCE(jsonb_agg(jsonb_build_object(
      'id', p.incident_id,
      'tipo_incidencia', p.tipo_incidencia,
      'participacion_id', p.participacion_id,
      'jugador_id', p.jugador_id,
      'jugador_nombre', p.jugador_nombre,
      'codigo_riviera', p.codigo_riviera,
      'tipo_evento', p.tipo_evento,
      'evento_id', p.evento_id,
      'campaign_id', p.campaign_id,
      'campaign_nombre', p.campaign_nombre,
      'puntos_esperados', p.puntos_esperados,
      'error_mensaje', p.error_mensaje,
      'attempts', p.attempts,
      'created_at', p.created_at
    )), '[]'::jsonb)
  INTO v_total, v_error_count, v_pending_count, v_incidents
  FROM paged p;

  RETURN jsonb_build_object(
    'total_count', v_total,
    'error_count', v_error_count,
    'pending_count', v_pending_count,
    'page', v_page,
    'page_size', v_limit,
    'total_pages', CEIL(v_total::numeric / GREATEST(v_limit, 1)::numeric)::int,
    'incidents', v_incidents
  );
END;
$$;


ALTER FUNCTION "public"."rewards_admin_incidents_list"("p_organizador_id" "uuid", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_admin_players_list"("p_organizador_id" "uuid", "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_query" "text" DEFAULT NULL::"text", "p_sort_by" "text" DEFAULT 'acumulado'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_page int := GREATEST(COALESCE(p_page, 1), 1);
  v_limit int := GREATEST(COALESCE(p_page_size, 25), 1);
  v_offset int := (v_page - 1) * v_limit;
  v_query text := NULLIF(trim(p_query), '');
  v_total int := 0;
  v_players jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);

  WITH player_campaign_stats AS (
    SELECT 
      l.jugador_id,
      c.id AS campaign_id,
      c.nombre AS campaign_nombre,
      CASE 
        WHEN now() < c.acumula_hasta THEN 'acumulacion'
        WHEN now() >= c.canje_desde AND now() < c.canje_hasta THEN 'canje'
        ELSE 'cerrada'
      END AS campaign_fase,
      c.canje_desde,
      c.canje_hasta,
      SUM(l.puntos_originales)::int AS puntos_acumulados,
      SUM(l.puntos_restantes)::int AS puntos_restantes,
      COALESCE((
        SELECT SUM(r.costo_puntos)::int
        FROM public.rewards_redemptions r
        WHERE r.organizador_id = p_organizador_id
          AND r.jugador_id = l.jugador_id
          AND r.campaign_id = c.id
          AND r.estado = 'reservado'
      ), 0) AS puntos_reservados,
      COUNT(DISTINCT l.participacion_id)::int AS participaciones_count,
      MAX(l.earned_at) AS ultima_participacion
    FROM public.rewards_lots l
    JOIN public.rewards_campaigns c ON c.id = l.campaign_id
    WHERE l.organizador_id = p_organizador_id
      AND NOT l.anulado
      AND (p_campaign_id IS NULL OR c.id = p_campaign_id)
    GROUP BY l.jugador_id, c.id, c.nombre, c.acumula_hasta, c.canje_desde, c.canje_hasta
  ),
  aggregated_players AS (
    SELECT 
      pcs.jugador_id,
      rj.nombre AS jugador_nombre,
      COALESCE(
        NULLIF(trim(rj.categoria), ''),
        ''
      ) AS codigo_riviera,
      (ARRAY_AGG(pcs.campaign_id ORDER BY (pcs.campaign_fase IN ('canje', 'acumulacion')) DESC, pcs.puntos_acumulados DESC))[1] AS primary_campaign_id,
      (ARRAY_AGG(pcs.campaign_nombre ORDER BY (pcs.campaign_fase IN ('canje', 'acumulacion')) DESC, pcs.puntos_acumulados DESC))[1] AS primary_campaign_nombre,
      (ARRAY_AGG(pcs.campaign_fase ORDER BY (pcs.campaign_fase IN ('canje', 'acumulacion')) DESC, pcs.puntos_acumulados DESC))[1] AS primary_campaign_fase,
      (ARRAY_AGG(pcs.canje_desde ORDER BY (pcs.campaign_fase IN ('canje', 'acumulacion')) DESC, pcs.puntos_acumulados DESC))[1] AS primary_canje_desde,
      (ARRAY_AGG(pcs.canje_hasta ORDER BY (pcs.campaign_fase IN ('canje', 'acumulacion')) DESC, pcs.puntos_acumulados DESC))[1] AS primary_canje_hasta,
      SUM(pcs.puntos_acumulados)::int AS total_acumulado,
      SUM(GREATEST(pcs.puntos_restantes - pcs.puntos_reservados, 0))::int AS total_disponible,
      SUM(pcs.puntos_reservados)::int AS total_reservado,
      SUM(pcs.participaciones_count)::int AS total_participaciones,
      MAX(pcs.ultima_participacion) AS ultima_participacion,
      jsonb_agg(jsonb_build_object(
        'campaign_id', pcs.campaign_id,
        'campaign_nombre', pcs.campaign_nombre,
        'fase', pcs.campaign_fase,
        'puntos_acumulados', pcs.puntos_acumulados,
        'puntos_disponibles', GREATEST(pcs.puntos_restantes - pcs.puntos_reservados, 0),
        'puntos_reservados', pcs.puntos_reservados,
        'participaciones_count', pcs.participaciones_count,
        'ultima_participacion', pcs.ultima_participacion,
        'canje_desde', pcs.canje_desde,
        'canje_hasta', pcs.canje_hasta
      ) ORDER BY pcs.puntos_acumulados DESC) AS campanas_detalle
    FROM player_campaign_stats pcs
    JOIN public.riviera_jugadores rj ON rj.id = pcs.jugador_id
    WHERE (pcs.puntos_acumulados > 0 OR pcs.puntos_restantes > 0)
      AND (
        v_query IS NULL 
        OR rj.nombre ILIKE '%' || v_query || '%'
        OR COALESCE(rj.categoria, '') ILIKE '%' || v_query || '%'
      )
    GROUP BY pcs.jugador_id, rj.nombre, rj.categoria
  ),
  counted AS (
    SELECT COUNT(*)::int AS cnt FROM aggregated_players
  ),
  sorted_players AS (
    SELECT ap.*
    FROM aggregated_players ap
    ORDER BY
      CASE WHEN p_sort_by = 'acumulado' AND p_sort_dir = 'asc' THEN ap.total_acumulado END ASC,
      CASE WHEN p_sort_by = 'acumulado' AND (p_sort_dir = 'desc' OR p_sort_dir IS NULL) THEN ap.total_acumulado END DESC,
      CASE WHEN p_sort_by = 'disponible' AND p_sort_dir = 'asc' THEN ap.total_disponible END ASC,
      CASE WHEN p_sort_by = 'disponible' AND (p_sort_dir = 'desc' OR p_sort_dir IS NULL) THEN ap.total_disponible END DESC,
      CASE WHEN p_sort_by = 'nombre' AND p_sort_dir = 'desc' THEN ap.jugador_nombre END DESC,
      CASE WHEN p_sort_by = 'nombre' AND (p_sort_dir = 'asc' OR p_sort_dir IS NULL) THEN ap.jugador_nombre END ASC,
      CASE WHEN p_sort_by = 'reciente' AND p_sort_dir = 'asc' THEN ap.ultima_participacion END ASC,
      CASE WHEN p_sort_by = 'reciente' AND (p_sort_dir = 'desc' OR p_sort_dir IS NULL) THEN ap.ultima_participacion END DESC,
      ap.total_acumulado DESC,
      ap.jugador_nombre ASC
    LIMIT v_limit
    OFFSET v_offset
  )
  SELECT 
    COALESCE((SELECT cnt FROM counted), 0),
    COALESCE(jsonb_agg(jsonb_build_object(
      'jugador_id', sp.jugador_id,
      'nombre', sp.jugador_nombre,
      'codigo_riviera', sp.codigo_riviera,
      'campaign_id', sp.primary_campaign_id,
      'campaign_nombre', sp.primary_campaign_nombre,
      'campaign_fase', sp.primary_campaign_fase,
      'canje_desde', sp.primary_canje_desde,
      'canje_hasta', sp.primary_canje_hasta,
      'puntos_acumulados', sp.total_acumulado,
      'puntos_disponibles', sp.total_disponible,
      'puntos_reservados', sp.total_reservado,
      'participaciones_acreditadas', sp.total_participaciones,
      'ultima_participacion', sp.ultima_participacion,
      'campanas', sp.campanas_detalle
    )), '[]'::jsonb)
  INTO v_total, v_players
  FROM sorted_players sp;

  RETURN jsonb_build_object(
    'total_count', v_total,
    'page', v_page,
    'page_size', v_limit,
    'total_pages', CEIL(v_total::numeric / GREATEST(v_limit, 1)::numeric)::int,
    'players', v_players
  );
END;
$$;


ALTER FUNCTION "public"."rewards_admin_players_list"("p_organizador_id" "uuid", "p_campaign_id" "uuid", "p_query" "text", "p_sort_by" "text", "p_sort_dir" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_assert_can_request"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sin sesión';
  END IF;
  IF public.is_master_admin() OR p_organizador_id = auth.uid() THEN
    RETURN;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.rewards_player_links l
    WHERE l.organizador_id = p_organizador_id
      AND l.jugador_id = p_jugador_id
      AND l.auth_user_id = auth.uid()
  ) THEN
    RETURN;
  END IF;
  RAISE EXCEPTION 'Sin permiso para solicitar este canje';
END;
$$;


ALTER FUNCTION "public"."rewards_assert_can_request"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_assert_club_admin"("p_organizador_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sin sesión';
  END IF;
  IF public.is_master_admin() THEN
    RETURN;
  END IF;
  IF p_organizador_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este club';
  END IF;
END;
$$;


ALTER FUNCTION "public"."rewards_assert_club_admin"("p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_assign_benefit_use"("p_benefit_id" "uuid", "p_evento_id" "uuid", "p_tipo_evento" "text", "p_participacion_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_benefit public.rewards_benefit_uses%ROWTYPE;
BEGIN
  SELECT * INTO v_benefit FROM public.rewards_benefit_uses WHERE id = p_benefit_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Beneficio no encontrado';
  END IF;
  PERFORM public.rewards_assert_club_admin(v_benefit.organizador_id);
  IF p_participacion_id IS NULL OR p_evento_id IS NULL THEN
    RAISE EXCEPTION 'Indica la reta y la participación';
  END IF;

  UPDATE public.rewards_benefit_uses
  SET evento_id = p_evento_id,
      tipo_evento = p_tipo_evento,
      participacion_id = p_participacion_id,
      estado = 'asignada',
      assigned_by = auth.uid(),
      assigned_at = now()
  WHERE id = v_benefit.id;

  UPDATE public.rewards_accrual_queue
  SET estado = 'omitida',
      last_error = 'Reta gratuita de Rewards',
      processed_at = now()
  WHERE participacion_id = p_participacion_id
    AND estado IN ('pendiente', 'error');

  UPDATE public.rewards_participation_reviews
  SET estado = 'rechazada',
      motivo = 'Reta gratuita de Rewards',
      decided_at = now(),
      decided_by = auth.uid()
  WHERE participacion_id = p_participacion_id
    AND estado = 'pendiente';

  PERFORM public.rewards_settle_invalid_lot(
    p_participacion_id,
    'Reta gratuita de Rewards'
  );
END;
$$;


ALTER FUNCTION "public"."rewards_assign_benefit_use"("p_benefit_id" "uuid", "p_evento_id" "uuid", "p_tipo_evento" "text", "p_participacion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_balance"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sin sesión';
  END IF;
  IF NOT (public.is_master_admin() OR p_organizador_id = auth.uid()) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.rewards_player_links l
      WHERE l.organizador_id = p_organizador_id
        AND l.jugador_id = p_jugador_id
        AND l.auth_user_id = auth.uid()
    ) THEN
      RAISE EXCEPTION 'Sin permiso sobre este club';
    END IF;
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(to_jsonb(s) ORDER BY s.acumula_desde)
    FROM (
      SELECT
        c.id AS campaign_id,
        c.nombre,
        c.acumula_desde,
        c.acumula_hasta,
        c.canje_desde,
        c.canje_hasta,
        CASE
          WHEN now() >= c.canje_hasta THEN 'cerrada'
          WHEN now() >= c.canje_desde THEN 'canje'
          ELSE 'acumulacion'
        END AS fase,
        COALESCE(SUM(l.puntos_restantes) FILTER (
          WHERE NOT l.anulado AND now() < c.canje_desde
        ), 0)::integer AS acumulando,
        COALESCE(SUM(l.puntos_restantes) FILTER (
          WHERE NOT l.anulado AND now() >= c.canje_desde AND now() < c.canje_hasta
        ), 0)::integer AS disponible,
        COALESCE((
          SELECT SUM(h.puntos)
          FROM public.rewards_lot_holds h
          JOIN public.rewards_redemptions r ON r.id = h.redemption_id
          WHERE r.campaign_id = c.id
            AND r.jugador_id = p_jugador_id
            AND r.estado = 'reservado'
        ), 0)::integer AS reservado,
        COALESCE((
          SELECT SUM(-g.puntos)
          FROM public.rewards_ledger g
          WHERE g.campaign_id = c.id
            AND g.jugador_id = p_jugador_id
            AND g.tipo = 'canje'
        ), 0)::integer AS utilizado,
        COALESCE((
          SELECT SUM(-g.puntos)
          FROM public.rewards_ledger g
          WHERE g.campaign_id = c.id
            AND g.jugador_id = p_jugador_id
            AND g.tipo = 'cierre'
        ), 0)::integer AS cerrado
      FROM public.rewards_campaigns c
      LEFT JOIN public.rewards_lots l
        ON l.campaign_id = c.id
       AND l.jugador_id = p_jugador_id
       AND l.organizador_id = p_organizador_id
      WHERE c.organizador_id = p_organizador_id
      GROUP BY c.id
    ) s
  ), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."rewards_balance"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_cancel_redemption"("p_redemption_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_red public.rewards_redemptions%ROWTYPE;
BEGIN
  SELECT * INTO v_red FROM public.rewards_redemptions WHERE id = p_redemption_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Canje no encontrado';
  END IF;
  PERFORM public.rewards_assert_club_admin(v_red.organizador_id);
  IF v_red.estado = 'solicitado' THEN
    UPDATE public.rewards_redemptions
    SET estado = 'cancelado', updated_at = now()
    WHERE id = v_red.id;
    RETURN;
  END IF;
  IF v_red.estado <> 'reservado' THEN
    RAISE EXCEPTION 'Este canje ya no se puede cancelar';
  END IF;
  PERFORM public.rewards_release_hold(v_red.id, 'cancelado');
  UPDATE public.rewards_rewards
  SET inventario_restante = inventario_restante + 1, updated_at = now()
  WHERE id = v_red.reward_id
    AND inventario IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."rewards_cancel_redemption"("p_redemption_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_close_campaigns"("p_organizador_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lot public.rewards_lots%ROWTYPE;
  v_count integer := 0;
  v_red public.rewards_redemptions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    IF session_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
      RAISE EXCEPTION 'Sin sesión';
    END IF;
  ELSE
    PERFORM public.rewards_assert_club_admin(p_organizador_id);
  END IF;

  FOR v_lot IN
    SELECT l.*
    FROM public.rewards_lots l
    JOIN public.rewards_campaigns c ON c.id = l.campaign_id
    WHERE l.organizador_id = p_organizador_id
      AND c.canje_hasta <= now()
      AND l.puntos_restantes > 0
      AND NOT l.anulado
    FOR UPDATE OF l SKIP LOCKED
  LOOP
    INSERT INTO public.rewards_ledger (
      organizador_id, jugador_id, campaign_id, lot_id, tipo, puntos, idempotency_key, motivo
    )
    VALUES (
      v_lot.organizador_id, v_lot.jugador_id, v_lot.campaign_id, v_lot.id,
      'cierre', -v_lot.puntos_restantes,
      'cierre:' || v_lot.id::text,
      'Cierre de la ventana de canje'
    )
    ON CONFLICT (idempotency_key) DO NOTHING;

    UPDATE public.rewards_lots
    SET puntos_restantes = 0
    WHERE id = v_lot.id;
    v_count := v_count + 1;
  END LOOP;

  UPDATE public.rewards_redemptions r
  SET estado = 'vencido', updated_at = now()
  FROM public.rewards_campaigns c
  WHERE r.campaign_id = c.id
    AND r.organizador_id = p_organizador_id
    AND r.estado = 'solicitado'
    AND c.canje_hasta <= now();

  FOR v_red IN
    SELECT *
    FROM public.rewards_redemptions
    WHERE organizador_id = p_organizador_id
      AND estado = 'reservado'
      AND reserva_hasta IS NOT NULL
      AND reserva_hasta <= now()
    FOR UPDATE
  LOOP
    PERFORM public.rewards_release_hold(v_red.id, 'vencido');
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."rewards_close_campaigns"("p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_compensate_lot"("p_lot_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lot public.rewards_lots%ROWTYPE;
  v_obl public.rewards_obligations%ROWTYPE;
  v_left integer;
  v_take integer;
  v_done integer := 0;
BEGIN
  SELECT * INTO v_lot FROM public.rewards_lots WHERE id = p_lot_id FOR UPDATE;
  IF NOT FOUND OR v_lot.anulado OR v_lot.puntos_restantes <= 0 THEN
    RETURN 0;
  END IF;
  v_left := v_lot.puntos_restantes;
  FOR v_obl IN
    SELECT *
    FROM public.rewards_obligations
    WHERE organizador_id = v_lot.organizador_id
      AND jugador_id = v_lot.jugador_id
      AND puntos_pendientes > 0
    ORDER BY created_at, id
    FOR UPDATE
  LOOP
    EXIT WHEN v_left = 0;
    v_take := LEAST(v_obl.puntos_pendientes, v_left);
    UPDATE public.rewards_obligations
    SET puntos_pendientes = puntos_pendientes - v_take
    WHERE id = v_obl.id;
    v_left := v_left - v_take;
    v_done := v_done + v_take;
  END LOOP;
  IF v_done = 0 THEN
    RETURN 0;
  END IF;
  UPDATE public.rewards_lots
  SET puntos_restantes = puntos_restantes - v_done
  WHERE id = v_lot.id;
  INSERT INTO public.rewards_ledger (
    organizador_id, jugador_id, campaign_id, lot_id, tipo, puntos, idempotency_key, motivo
  )
  VALUES (
    v_lot.organizador_id, v_lot.jugador_id, v_lot.campaign_id, v_lot.id,
    'compensacion', -v_done, 'compensacion:' || v_lot.id::text,
    'Compensación de obligación por puntos ya utilizados'
  );
  RETURN v_done;
END;
$$;


ALTER FUNCTION "public"."rewards_compensate_lot"("p_lot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_confirm_redemption"("p_redemption_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_red public.rewards_redemptions%ROWTYPE;
  v_hold public.rewards_lot_holds%ROWTYPE;
BEGIN
  SELECT * INTO v_red FROM public.rewards_redemptions WHERE id = p_redemption_id FOR UPDATE;
  IF NOT FOUND OR v_red.estado <> 'reservado' THEN
    RAISE EXCEPTION 'El canje no está reservado';
  END IF;
  PERFORM public.rewards_assert_club_admin(v_red.organizador_id);
  IF v_red.reserva_hasta IS NOT NULL AND v_red.reserva_hasta <= now() THEN
    RAISE EXCEPTION 'La reserva ya venció';
  END IF;

  FOR v_hold IN
    SELECT * FROM public.rewards_lot_holds WHERE redemption_id = v_red.id FOR UPDATE
  LOOP
    INSERT INTO public.rewards_ledger (
      organizador_id, jugador_id, campaign_id, lot_id, redemption_id,
      tipo, puntos, idempotency_key, actor_id
    )
    VALUES (
      v_red.organizador_id, v_red.jugador_id, v_red.campaign_id, v_hold.lot_id, v_red.id,
      'canje', -v_hold.puntos,
      'canje:' || v_red.id::text || ':' || v_hold.lot_id::text,
      auth.uid()
    );
  END LOOP;

  DELETE FROM public.rewards_lot_holds WHERE redemption_id = v_red.id;

  UPDATE public.rewards_redemptions
  SET estado = 'entregado', confirmed_by = auth.uid(), updated_at = now()
  WHERE id = v_red.id;

  INSERT INTO public.rewards_obligations (
    organizador_id, jugador_id, campaign_id, lot_id, participacion_id,
    puntos_originales, puntos_pendientes, motivo
  )
  SELECT v_red.organizador_id, v_red.jugador_id, l.campaign_id, l.id, l.participacion_id,
         SUM(-h.puntos), SUM(-h.puntos), 'Puntos ya entregados de un lote anulado'
  FROM public.rewards_lots l
  JOIN (
    SELECT lot_id, puntos FROM public.rewards_ledger
    WHERE redemption_id = v_red.id AND tipo = 'canje'
  ) h ON h.lot_id = l.id
  WHERE l.anulado
  GROUP BY l.campaign_id, l.id, l.participacion_id
  ON CONFLICT (lot_id) DO UPDATE
  SET puntos_originales = public.rewards_obligations.puntos_originales + EXCLUDED.puntos_originales,
      puntos_pendientes = public.rewards_obligations.puntos_pendientes + EXCLUDED.puntos_pendientes;

  IF (v_red.snapshot->>'tipo') IN ('reta_gratis', 'paquete') THEN
    INSERT INTO public.rewards_benefit_uses (
      organizador_id, redemption_id, jugador_id, tipo_beneficio
    )
    VALUES (
      v_red.organizador_id,
      v_red.id,
      v_red.jugador_id,
      COALESCE(v_red.snapshot->>'tipo', 'reta_gratis')
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."rewards_confirm_redemption"("p_redemption_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_duplicate_campaign"("p_source_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_src public.rewards_campaigns%ROWTYPE;
  v_reward public.rewards_rewards%ROWTYPE;
  v_new uuid;
BEGIN
  SELECT * INTO v_src FROM public.rewards_campaigns WHERE id = p_source_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaña no encontrada';
  END IF;
  PERFORM public.rewards_assert_club_admin(v_src.organizador_id);

  v_new := public.rewards_save_campaign(jsonb_build_object(
    'organizador_id', v_src.organizador_id,
    'nombre', COALESCE(NULLIF(p_payload->>'nombre', ''), v_src.nombre || ' (copia)'),
    'descripcion', COALESCE(p_payload->>'descripcion', v_src.descripcion),
    'timezone', COALESCE(NULLIF(p_payload->>'timezone', ''), v_src.timezone),
    'acumula_desde', p_payload->>'acumula_desde',
    'acumula_hasta', p_payload->>'acumula_hasta',
    'canje_desde', p_payload->>'canje_desde',
    'canje_hasta', p_payload->>'canje_hasta',
    'puntos_por_participacion', COALESCE(
      (p_payload->>'puntos_por_participacion')::integer,
      v_src.puntos_por_participacion
    ),
    'modalidades', to_jsonb(v_src.modalidades),
    'estado', COALESCE(NULLIF(p_payload->>'estado', ''), 'borrador'),
    'visible_jugadores', COALESCE((p_payload->>'visible_jugadores')::boolean, v_src.visible_jugadores),
    'condiciones', COALESCE(p_payload->>'condiciones', v_src.condiciones),
    'validation_mode', v_src.validation_mode,
    'reserva_dias', COALESCE((p_payload->>'reserva_dias')::integer, v_src.reserva_dias)
  ));

  UPDATE public.rewards_campaigns
  SET origen_campaign_id = v_src.id
  WHERE id = v_new;

  FOR v_reward IN
    SELECT * FROM public.rewards_rewards WHERE campaign_id = v_src.id
  LOOP
    INSERT INTO public.rewards_rewards (
      campaign_id, organizador_id, nombre, descripcion, imagen_url,
      costo_puntos, tipo, cantidad, inventario, inventario_restante,
      limite_por_jugador, disponible_desde, disponible_hasta, condiciones, estado
    )
    VALUES (
      v_new, v_src.organizador_id, v_reward.nombre, v_reward.descripcion, v_reward.imagen_url,
      v_reward.costo_puntos, v_reward.tipo, v_reward.cantidad,
      v_reward.inventario, v_reward.inventario,
      v_reward.limite_por_jugador, NULL, NULL, v_reward.condiciones, 'borrador'
    );
  END LOOP;

  RETURN v_new;
END;
$$;


ALTER FUNCTION "public"."rewards_duplicate_campaign"("p_source_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_enqueue_candidate"("p_participacion_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_part public.jugador_participaciones%ROWTYPE;
  v_partidos integer;
  v_elegible boolean;
  v_mod text;
  v_org uuid;
  v_closed timestamptz;
  v_campaign public.rewards_campaigns%ROWTYPE;
  v_review_id uuid;
  v_queue_id uuid;
  v_key text;
BEGIN
  -- 1) Leer participación deportiva
  SELECT * INTO v_part
  FROM public.jugador_participaciones
  WHERE id = p_participacion_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- 2) Partidos disputados
  BEGIN
    v_partidos := COALESCE(
      (v_part.metadata->>'partidos')::integer,
      (v_part.metadata->>'partidos_jugados')::integer,
      (COALESCE((v_part.metadata->>'partidos_ganados')::integer, 0) +
       COALESCE((v_part.metadata->>'partidos_perdidos')::integer, 0) +
       COALESCE((v_part.metadata->>'partidos_empatados')::integer, 0)),
      0
    );
  EXCEPTION WHEN OTHERS THEN
    v_partidos := 0;
  END;

  -- 3) Elegibilidad deportiva (evidencia de juego comprobado)
  v_elegible := (
    COALESCE(v_part.metadata->>'subtipo' IN (
      'americano_cierre', 'reta_cierre', 'reta_resultado',
      'duelo_2v2_cierre', 'torneo_express_cierre', 'liga_jornada_cierre'
    ), false)
    OR COALESCE(v_partidos > 0, false)
    OR COALESCE(v_part.sets_favor, 0) > 0
    OR COALESCE(v_part.sets_contra, 0) > 0
    OR COALESCE(v_part.puntos_obtenidos, 0) > 0
    OR COALESCE(v_part.resultado IN ('victoria', 'derrota', 'empate'), false)
    OR (COALESCE(v_part.resultado = 'participación', false) AND (
      COALESCE((v_part.metadata->>'posicion')::int, 0) > 0
      OR COALESCE((v_part.metadata->>'posicion_final')::int, 0) > 0
      OR COALESCE((v_part.metadata->>'puntos_en_contra')::int, 0) > 0
      OR COALESCE((v_part.metadata->>'puntos_a_favor')::int, 0) > 0
    ))
    OR (v_part.metadata->'partidos_detalle' IS NOT NULL AND jsonb_array_length(v_part.metadata->'partidos_detalle') > 0)
  );

  IF v_elegible IS NOT TRUE THEN
    RETURN;
  END IF;

  -- 4) Modalidad Rewards
  v_mod := public.rewards_modalidad(v_part.tipo_evento::text, v_part.evento_id);
  IF v_mod IS NULL THEN
    RETURN;
  END IF;

  -- 5) Club anfitrión del evento
  BEGIN
    v_org := NULLIF(trim(v_part.metadata->>'organizador_id'), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_org := NULL;
  END;

  IF v_org IS NULL THEN
    v_org := public.riviera_participacion_expected_host_org(v_part.tipo_evento::text, v_part.evento_id::text);
  END IF;

  IF v_org IS NULL THEN
    SELECT rj.organizador_id INTO v_org
    FROM public.riviera_jugadores rj
    WHERE rj.id = v_part.jugador_id;
  END IF;

  IF v_org IS NULL THEN
    RETURN;
  END IF;

  -- 6) Momento de cierre deportivo
  v_closed := COALESCE(v_part.created_at, v_part.fecha::timestamptz, now());

  -- 7) Campaña activa
  SELECT * INTO v_campaign
  FROM public.rewards_campaigns c
  WHERE c.organizador_id = v_org
    AND c.estado = 'activa'
    AND v_mod = ANY (c.modalidades)
    AND v_closed >= c.acumula_desde
    AND v_closed < c.acumula_hasta
  ORDER BY c.created_at DESC
  LIMIT 1;

  -- 8) Si usó beneficio de canje
  IF EXISTS (
    SELECT 1 FROM public.rewards_benefit_uses b
    WHERE b.participacion_id = v_part.id
  ) THEN
    INSERT INTO public.rewards_participation_reviews (
      organizador_id, participacion_id, jugador_id, tipo_evento, evento_id,
      modalidad, closed_at, estado, campaign_id, validation_source, motivo, decided_at
    )
    VALUES (
      v_org, v_part.id, v_part.jugador_id, v_part.tipo_evento::text, v_part.evento_id,
      v_mod, v_closed, 'aprobada', v_campaign.id, 'automatic', 'Reta gratuita de Rewards', now()
    )
    ON CONFLICT (participacion_id) DO UPDATE
    SET organizador_id = EXCLUDED.organizador_id,
        estado = 'aprobada',
        motivo = 'Reta gratuita de Rewards',
        decided_at = now();

    v_key := v_org::text || ':' || v_part.jugador_id::text || ':' || v_part.tipo_evento::text || ':' || v_part.evento_id::text;

    INSERT INTO public.rewards_accrual_queue (
      organizador_id, review_id, campaign_id, participacion_id, jugador_id,
      tipo_evento, evento_id, idempotency_key, estado, validation_source, last_error, processed_at
    )
    SELECT v_org, r.id, v_campaign.id, v_part.id, v_part.jugador_id,
           v_part.tipo_evento::text, v_part.evento_id, v_key, 'omitida', 'automatic', 'Reta gratuita de Rewards', now()
    FROM public.rewards_participation_reviews r
    WHERE r.participacion_id = v_part.id
    ON CONFLICT (idempotency_key) DO NOTHING;

    RETURN;
  END IF;

  -- 9) Sin campaña activa: registrar como pendiente
  IF v_campaign.id IS NULL THEN
    INSERT INTO public.rewards_participation_reviews (
      organizador_id, participacion_id, jugador_id, tipo_evento, evento_id,
      modalidad, closed_at, estado
    )
    VALUES (
      v_org, v_part.id, v_part.jugador_id, v_part.tipo_evento::text, v_part.evento_id,
      v_mod, v_closed, 'pendiente'
    )
    ON CONFLICT (participacion_id) DO UPDATE
    SET organizador_id = EXCLUDED.organizador_id,
        closed_at = EXCLUDED.closed_at
    WHERE rewards_participation_reviews.estado = 'pendiente';
    RETURN;
  END IF;

  -- 10) Campaña activa: crear review 'aprobada'
  INSERT INTO public.rewards_participation_reviews (
    organizador_id, participacion_id, jugador_id, tipo_evento, evento_id,
    modalidad, closed_at, estado, campaign_id, validation_source, decided_at
  )
  VALUES (
    v_org, v_part.id, v_part.jugador_id, v_part.tipo_evento::text, v_part.evento_id,
    v_mod, v_closed, 'aprobada', v_campaign.id, 'automatic', now()
  )
  ON CONFLICT (participacion_id) DO UPDATE
  SET organizador_id = EXCLUDED.organizador_id,
      estado = 'aprobada',
      campaign_id = EXCLUDED.campaign_id,
      validation_source = 'automatic',
      decided_at = COALESCE(rewards_participation_reviews.decided_at, now())
  WHERE rewards_participation_reviews.estado <> 'rechazada'
  RETURNING id INTO v_review_id;

  IF v_review_id IS NULL THEN
    RETURN;
  END IF;

  -- 11) Encolar candidatura como 'pendiente'
  v_key := v_org::text || ':' || v_part.jugador_id::text || ':' || v_part.tipo_evento::text || ':' || v_part.evento_id::text;

  INSERT INTO public.rewards_accrual_queue (
    organizador_id, review_id, campaign_id, participacion_id, jugador_id,
    tipo_evento, evento_id, idempotency_key, estado, validation_source
  )
  VALUES (
    v_org, v_review_id, v_campaign.id, v_part.id, v_part.jugador_id,
    v_part.tipo_evento::text, v_part.evento_id, v_key, 'pendiente', 'automatic'
  )
  ON CONFLICT (idempotency_key) DO UPDATE
  SET campaign_id = EXCLUDED.campaign_id,
      review_id = EXCLUDED.review_id
  WHERE rewards_accrual_queue.estado NOT IN ('acreditada', 'omitida');

  -- DESACOPLAMIENTO DEFINITIVO:
  -- Ya NO se invoca rewards_accrue_one() síncronamente.
  -- La transacción deportiva termina de forma inmediata y segura.
END;
$$;


ALTER FUNCTION "public"."rewards_enqueue_candidate"("p_participacion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_expire_lots"("p_organizador_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lot public.rewards_lots%ROWTYPE;
  v_count integer := 0;
  v_red public.rewards_redemptions%ROWTYPE;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);

  FOR v_lot IN
    SELECT *
    FROM public.rewards_lots
    WHERE organizador_id = p_organizador_id
      AND expires_at <= now()
      AND puntos_restantes > 0
      AND NOT anulado
    FOR UPDATE
  LOOP
    INSERT INTO public.rewards_ledger (
      organizador_id, jugador_id, campaign_id, lot_id, tipo, puntos, idempotency_key
    )
    VALUES (
      v_lot.organizador_id, v_lot.jugador_id, v_lot.campaign_id, v_lot.id,
      'expiracion', -v_lot.puntos_restantes,
      'expiracion:' || v_lot.id::text || ':' || v_lot.puntos_restantes::text
    )
    ON CONFLICT (idempotency_key) DO NOTHING;

    UPDATE public.rewards_lots
    SET puntos_restantes = 0
    WHERE id = v_lot.id;
    v_count := v_count + 1;
  END LOOP;

  FOR v_red IN
    SELECT *
    FROM public.rewards_redemptions
    WHERE organizador_id = p_organizador_id
      AND estado = 'reservado'
      AND reserva_hasta IS NOT NULL
      AND reserva_hasta <= now()
    FOR UPDATE
  LOOP
    PERFORM public.rewards_release_hold(v_red.id, 'vencido');
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."rewards_expire_lots"("p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_expires_at"("p_earned" timestamp with time zone, "p_days" integer, "p_tz" "text") RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT ((p_earned AT TIME ZONE p_tz) + make_interval(days => p_days)) AT TIME ZONE p_tz;
$$;


ALTER FUNCTION "public"."rewards_expires_at"("p_earned" timestamp with time zone, "p_days" integer, "p_tz" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_invalidate_participation"("p_organizador_id" "uuid", "p_participacion_id" "uuid", "p_motivo" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN
    RAISE EXCEPTION 'La invalidación necesita un motivo';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.rewards_participation_reviews
    WHERE participacion_id = p_participacion_id
      AND organizador_id = p_organizador_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.rewards_lots
    WHERE participacion_id = p_participacion_id
      AND organizador_id = p_organizador_id
  ) THEN
    RAISE EXCEPTION 'Participación no encontrada en este club';
  END IF;

  UPDATE public.rewards_accrual_queue
  SET estado = 'omitida', last_error = trim(p_motivo), processed_at = now()
  WHERE participacion_id = p_participacion_id
    AND organizador_id = p_organizador_id
    AND estado IN ('pendiente', 'error');

  -- Actualizar estado a 'rechazada' tanto si estaba pendiente como aprobada
  UPDATE public.rewards_participation_reviews
  SET estado = 'rechazada', motivo = trim(p_motivo), decided_at = now(), decided_by = auth.uid()
  WHERE participacion_id = p_participacion_id
    AND organizador_id = p_organizador_id;

  PERFORM public.rewards_settle_invalid_lot(p_participacion_id, trim(p_motivo));
END;
$$;


ALTER FUNCTION "public"."rewards_invalidate_participation"("p_organizador_id" "uuid", "p_participacion_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_link_player"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_auth uuid;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);
  IF NOT EXISTS (
    SELECT 1 FROM public.riviera_jugadores j
    WHERE j.id = p_jugador_id AND j.organizador_id = p_organizador_id
  ) THEN
    RAISE EXCEPTION 'El jugador no pertenece a este club';
  END IF;
  SELECT u.id INTO v_auth
  FROM auth.users u
  WHERE lower(u.email) = lower(trim(p_email))
  LIMIT 1;
  IF v_auth IS NULL THEN
    RAISE EXCEPTION 'No hay una cuenta con ese correo';
  END IF;
  INSERT INTO public.rewards_player_links (jugador_id, organizador_id, auth_user_id)
  VALUES (p_jugador_id, p_organizador_id, v_auth)
  ON CONFLICT (jugador_id) DO UPDATE
  SET auth_user_id = EXCLUDED.auth_user_id,
      organizador_id = EXCLUDED.organizador_id;
  RETURN v_auth;
END;
$$;


ALTER FUNCTION "public"."rewards_link_player"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_list_players"("p_organizador_id" "uuid") RETURNS TABLE("id" "uuid", "nombre" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Aislamiento por club
  PERFORM public.rewards_assert_club_admin(p_organizador_id);

  RETURN QUERY
  SELECT DISTINCT rj.id, rj.nombre
  FROM public.riviera_jugadores rj
  WHERE rj.organizador_id = p_organizador_id
     OR EXISTS (
       SELECT 1 FROM public.rewards_participation_reviews r
       WHERE r.organizador_id = p_organizador_id
         AND r.jugador_id = rj.id
     )
     OR EXISTS (
       SELECT 1 FROM public.rewards_lots l
       WHERE l.organizador_id = p_organizador_id
         AND l.jugador_id = rj.id
     )
     OR EXISTS (
       SELECT 1 FROM public.jugador_participaciones jp
       WHERE (
         NULLIF(trim(jp.metadata->>'organizador_id'), '')::uuid = p_organizador_id
         OR public.riviera_participacion_expected_host_org(jp.tipo_evento::text, jp.evento_id::text) = p_organizador_id
       )
       AND jp.jugador_id = rj.id
     )
  ORDER BY rj.nombre ASC;
END;
$$;


ALTER FUNCTION "public"."rewards_list_players"("p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_lots_set_expires_at"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.expires_at IS NULL THEN
    SELECT c.canje_hasta INTO NEW.expires_at
    FROM public.rewards_campaigns c
    WHERE c.id = NEW.campaign_id;
  END IF;
  IF NEW.expires_at IS NULL THEN
    RAISE EXCEPTION 'No se puede emitir lote sin fecha de vencimiento válida (canje_hasta no encontrado en campaña %)', NEW.campaign_id;
  END IF;

  BEGIN
    IF NEW.timezone IS NULL THEN
      SELECT COALESCE(c.timezone, 'America/Mexico_City') INTO NEW.timezone
      FROM public.rewards_campaigns c
      WHERE c.id = NEW.campaign_id;
      IF NEW.timezone IS NULL THEN
        NEW.timezone := 'America/Mexico_City';
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."rewards_lots_set_expires_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_modalidad"("p_tipo_evento" "text", "p_evento_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_format text;
BEGIN
  IF p_tipo_evento = 'americano' THEN
    RETURN 'americano';
  END IF;
  IF p_tipo_evento = 'duelo_2v2' THEN
    RETURN 'duelo_2v2';
  END IF;
  IF p_tipo_evento = 'reta' THEN
    SELECT t.format INTO v_format
    FROM public.tournaments t
    WHERE t.id = p_evento_id;
    IF v_format = 'teams' THEN
      RETURN 'reta_equipos';
    END IF;
    IF v_format = 'round_robin' THEN
      RETURN 'round_robin';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."rewards_modalidad"("p_tipo_evento" "text", "p_evento_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_on_participacion_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_err_msg text;
  v_err_state text;
  v_err_ctx text;
BEGIN
  BEGIN
    PERFORM public.rewards_enqueue_candidate(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_err_msg = MESSAGE_TEXT,
      v_err_state = RETURNED_SQLSTATE,
      v_err_ctx = PG_EXCEPTION_CONTEXT;

    BEGIN
      INSERT INTO public.rewards_enqueue_failures (
        participacion_id, error, sqlstate, context, created_at, attempts
      )
      VALUES (
        NEW.id, v_err_msg, v_err_state, v_err_ctx, now(), 1
      )
      ON CONFLICT (participacion_id) DO UPDATE
      SET error = EXCLUDED.error,
          sqlstate = EXCLUDED.sqlstate,
          context = EXCLUDED.context,
          created_at = now(),
          attempts = public.rewards_enqueue_failures.attempts + 1,
          resolved_at = NULL;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'rewards_on_participacion_insert: fallo al registrar encolamiento para participacion %: % (%)',
        NEW.id, v_err_msg, v_err_state;
    END;
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."rewards_on_participacion_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_player_public_summary"("p_jugador_id" "uuid", "p_organizador_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_res jsonb;
BEGIN
  WITH target_players AS (
    SELECT DISTINCT p_jugador_id AS id
    UNION
    SELECT DISTINCT l.jugador_id AS id
    FROM public.rewards_player_links l
    WHERE public.rewards_same_player(l.jugador_id, p_jugador_id)
  ),
  player_lots AS (
    SELECT 
      l.organizador_id,
      l.campaign_id,
      SUM(l.puntos_originales)::int AS acumulados,
      SUM(l.puntos_restantes)::int AS restantes,
      COUNT(DISTINCT l.participacion_id)::int AS part_count,
      MAX(l.earned_at) AS last_earned
    FROM public.rewards_lots l
    JOIN target_players tp ON tp.id = l.jugador_id
    WHERE NOT l.anulado
      AND (p_organizador_id IS NULL OR l.organizador_id = p_organizador_id)
    GROUP BY l.organizador_id, l.campaign_id
  ),
  active_camps AS (
    SELECT 
      c.id AS campaign_id,
      c.organizador_id,
      c.nombre AS campaign_nombre,
      c.acumula_desde,
      c.acumula_hasta,
      c.canje_desde,
      c.canje_hasta,
      c.visible_jugadores,
      CASE 
        WHEN now() < c.acumula_hasta THEN 'acumulacion'
        WHEN now() >= c.canje_desde AND now() < c.canje_hasta THEN 'canje'
        ELSE 'cerrada'
      END AS fase,
      COALESCE(pl.acumulados, 0) AS puntos_acumulados,
      COALESCE(pl.restantes, 0) AS puntos_restantes,
      COALESCE((
        SELECT SUM(r.costo_puntos)::int
        FROM public.rewards_redemptions r
        JOIN target_players tp ON tp.id = r.jugador_id
        WHERE r.organizador_id = c.organizador_id
          AND r.campaign_id = c.id
          AND r.estado = 'reservado'
      ), 0) AS puntos_reservados,
      COALESCE(pl.part_count, 0) AS participaciones_count,
      pl.last_earned
    FROM public.rewards_campaigns c
    LEFT JOIN player_lots pl ON pl.campaign_id = c.id AND pl.organizador_id = c.organizador_id
    WHERE (p_organizador_id IS NULL OR c.organizador_id = p_organizador_id)
      AND c.estado IN ('activa', 'programada', 'pausada')
      AND (c.visible_jugadores OR COALESCE(pl.acumulados, 0) > 0)
      AND (
        COALESCE(pl.acumulados, 0) > 0 
        OR c.organizador_id = p_organizador_id
      )
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'organizador_id', ac.organizador_id,
    'campaign_id', ac.campaign_id,
    'campaign_nombre', ac.campaign_nombre,
    'fase', ac.fase,
    'puntos_acumulados', ac.puntos_acumulados,
    'puntos_disponibles', GREATEST(ac.puntos_restantes - ac.puntos_reservados, 0),
    'puntos_reservados', ac.puntos_reservados,
    'participaciones_count', ac.participaciones_count,
    'acumula_desde', ac.acumula_desde,
    'acumula_hasta', ac.acumula_hasta,
    'canje_desde', ac.canje_desde,
    'canje_hasta', ac.canje_hasta,
    'is_canje_open', (now() >= ac.canje_desde AND now() < ac.canje_hasta)
  ) ORDER BY (ac.organizador_id = p_organizador_id) DESC, ac.puntos_acumulados DESC), '[]'::jsonb)
  INTO v_res
  FROM active_camps ac;

  RETURN v_res;
END;
$$;


ALTER FUNCTION "public"."rewards_player_public_summary"("p_jugador_id" "uuid", "p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_player_snapshot"("p_jugador_id" "uuid", "p_organizador_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_local uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sin sesión';
  END IF;

  -- Vínculo PROPIO de quien llama, en un club, hacia la misma persona.
  SELECT l.organizador_id, l.jugador_id
  INTO v_org, v_local
  FROM public.rewards_player_links l
  WHERE l.auth_user_id = v_uid
    AND (p_organizador_id IS NULL OR l.organizador_id = p_organizador_id)
    AND public.rewards_same_player(l.jugador_id, p_jugador_id)
  ORDER BY (l.jugador_id = p_jugador_id) DESC, l.created_at ASC, l.organizador_id ASC
  LIMIT 1;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Esta cuenta no está vinculada a este jugador';
  END IF;

  RETURN jsonb_build_object(
    'organizador_id', v_org,
    'jugador_id', v_local,
    'clubes_autorizados', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object('organizador_id', l.organizador_id, 'jugador_id', l.jugador_id)
        ORDER BY l.created_at, l.organizador_id
      )
      FROM public.rewards_player_links l
      WHERE l.auth_user_id = v_uid
        AND public.rewards_same_player(l.jugador_id, p_jugador_id)
    ), '[]'::jsonb),
    -- rewards_balance exige a su vez el vínculo exacto (club, jugador local, auth.uid()).
    'saldos', public.rewards_balance(v_org, v_local),
    'premios', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', w.id,
        'nombre', w.nombre,
        'descripcion', w.descripcion,
        'costo_puntos', w.costo_puntos,
        'tipo', w.tipo,
        'condiciones', w.condiciones,
        'inventario_restante', w.inventario_restante,
        'limite_por_jugador', w.limite_por_jugador,
        'campaign_id', c.id,
        'campana', c.nombre,
        'canje_hasta', c.canje_hasta
      ) ORDER BY w.costo_puntos)
      FROM public.rewards_rewards w
      JOIN public.rewards_campaigns c ON c.id = w.campaign_id
      WHERE w.organizador_id = v_org
        AND w.estado = 'activo'
        AND c.estado = 'activa'
        AND c.visible_jugadores
        AND now() >= c.canje_desde
        AND now() < c.canje_hasta
    ), '[]'::jsonb),
    'canjes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id,
        'estado', r.estado,
        'costo_puntos', r.costo_puntos,
        'nombre', r.snapshot->>'nombre',
        'created_at', r.created_at,
        'reserva_hasta', r.reserva_hasta
      ) ORDER BY r.created_at DESC)
      FROM public.rewards_redemptions r
      WHERE r.organizador_id = v_org AND r.jugador_id = v_local
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."rewards_player_snapshot"("p_jugador_id" "uuid", "p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_process_accrual_queue"("p_organizador_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_done integer := 0;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);
  FOR v_id IN
    SELECT q.id
    FROM public.rewards_accrual_queue q
    WHERE q.organizador_id = p_organizador_id
      AND (
        q.estado = 'pendiente'
        OR (q.estado = 'error' AND q.attempts < 20)
      )
    ORDER BY q.created_at
    LIMIT GREATEST(COALESCE(p_limit, 50), 1)
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      PERFORM public.rewards_accrue_one(v_id);
      v_done := v_done + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.rewards_accrual_queue
      SET estado = 'error',
          attempts = attempts + 1,
          last_error = SQLERRM
      WHERE id = v_id;
    END;
  END LOOP;
  RETURN v_done;
END;
$$;


ALTER FUNCTION "public"."rewards_process_accrual_queue"("p_organizador_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_process_queue"("p_limit" integer DEFAULT 50, "p_worker_id" "text" DEFAULT 'worker-default'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rec record;
  v_processed integer := 0;
  v_succeeded integer := 0;
  v_failed integer := 0;
  v_err_msg text;
  v_err_state text;
BEGIN
  -- Reclamar filas elegibles concurrentemente sin bloquear otros workers
  FOR v_rec IN
    SELECT q.id, q.attempts
    FROM public.rewards_accrual_queue q
    WHERE q.estado = 'pendiente'
       OR (
         q.estado = 'error'
         AND q.attempts < 10
         AND COALESCE(q.processed_at, q.created_at) < now() - (LEAST(q.attempts, 8) * interval '5 seconds')
       )
       OR (
         q.estado = 'procesando'
         AND q.locked_at < now() - interval '2 minutes'
       )
    ORDER BY q.created_at ASC
    LIMIT GREATEST(COALESCE(p_limit, 50), 1)
    FOR UPDATE SKIP LOCKED
  LOOP
    v_processed := v_processed + 1;

    UPDATE public.rewards_accrual_queue
    SET estado = 'procesando',
        worker_id = p_worker_id,
        locked_at = now()
    WHERE id = v_rec.id;

    BEGIN
      PERFORM public.rewards_accrue_one(v_rec.id);
      v_succeeded := v_succeeded + 1;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS
        v_err_msg = MESSAGE_TEXT,
        v_err_state = RETURNED_SQLSTATE;

      v_failed := v_failed + 1;

      UPDATE public.rewards_accrual_queue
      SET estado = 'error',
          attempts = attempts + 1,
          last_error = CASE
            WHEN attempts + 1 >= 10 THEN '[MAX_INTENTOS_AGOTADOS] (' || v_err_state || ') ' || v_err_msg
            ELSE '(' || v_err_state || ') ' || v_err_msg
          END,
          processed_at = now(),
          locked_at = NULL,
          worker_id = NULL
      WHERE id = v_rec.id;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed,
    'succeeded', v_succeeded,
    'failed', v_failed,
    'worker_id', p_worker_id
  );
END;
$$;


ALTER FUNCTION "public"."rewards_process_queue"("p_limit" integer, "p_worker_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_reconcile_missing_candidates"("p_organizador_id" "uuid" DEFAULT NULL::"uuid", "p_evento_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rec record;
  v_reconciled integer := 0;
  v_errors integer := 0;
BEGIN
  FOR v_rec IN
    SELECT jp.id
    FROM public.jugador_participaciones jp
    JOIN public.rewards_campaigns c ON c.organizador_id = COALESCE(
      NULLIF(trim(jp.metadata->>'organizador_id'), '')::uuid,
      public.riviera_participacion_expected_host_org(jp.tipo_evento::text, jp.evento_id::text)
    )
    WHERE (p_organizador_id IS NULL OR c.organizador_id = p_organizador_id)
      AND (p_evento_id IS NULL OR jp.evento_id = p_evento_id)
      AND c.estado = 'activa'
      AND COALESCE(jp.created_at, jp.fecha::timestamptz, now()) >= c.acumula_desde
      AND COALESCE(jp.created_at, jp.fecha::timestamptz, now()) < c.acumula_hasta
      AND jp.tipo_evento::text IN ('reta', 'americano', 'duelo_2v2')
      -- Evidencia de juego comprobado (igual a la regla del trigger)
      AND (
        COALESCE(jp.metadata->>'subtipo' IN (
          'americano_cierre', 'reta_cierre', 'reta_resultado',
          'duelo_2v2_cierre', 'torneo_express_cierre', 'liga_jornada_cierre'
        ), false)
        OR COALESCE(jp.sets_favor, 0) > 0
        OR COALESCE(jp.sets_contra, 0) > 0
        OR COALESCE(jp.puntos_obtenidos, 0) > 0
        OR COALESCE(jp.resultado IN ('victoria', 'derrota', 'empate'), false)
        OR (jp.metadata->'partidos_detalle' IS NOT NULL AND jsonb_array_length(jp.metadata->'partidos_detalle') > 0)
      )
      -- Participaciones que NO estén ya en cola o con review rechazada
      AND NOT EXISTS (
        SELECT 1 FROM public.rewards_accrual_queue q
        WHERE q.participacion_id = jp.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.rewards_participation_reviews r
        WHERE r.participacion_id = jp.id
          AND r.estado = 'rechazada'
      )
  LOOP
    BEGIN
      PERFORM public.rewards_enqueue_candidate(v_rec.id);
      v_reconciled := v_reconciled + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'reconciled', v_reconciled,
    'errors', v_errors
  );
END;
$$;


ALTER FUNCTION "public"."rewards_reconcile_missing_candidates"("p_organizador_id" "uuid", "p_evento_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_recover_participaciones"("p_organizador_id" "uuid" DEFAULT NULL::"uuid", "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_evento_id" "uuid" DEFAULT NULL::"uuid", "p_participacion_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rec record;
  v_recovered_queue int := 0;
  v_recovered_pending int := 0;
  v_recovered_missing int := 0;
  v_errors int := 0;
BEGIN
  -- Aislamiento de permisos: club admin solo puede su club; NULL solo master admin o service_role
  IF p_organizador_id IS NOT NULL THEN
    PERFORM public.rewards_assert_club_admin(p_organizador_id);
  ELSE
    IF auth.uid() IS NOT NULL AND NOT public.is_master_admin() THEN
      RAISE EXCEPTION 'Sin permiso para recuperación global de todos los clubes';
    END IF;
    IF auth.uid() IS NULL AND session_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
      RAISE EXCEPTION 'Sin permiso para recuperación global de todos los clubes';
    END IF;
  END IF;

  -- A. Reintentar las acreditaciones que quedaron en 'error' en rewards_accrual_queue
  FOR v_rec IN
    SELECT q.id, q.organizador_id
    FROM public.rewards_accrual_queue q
    WHERE (p_organizador_id IS NULL OR q.organizador_id = p_organizador_id)
      AND (p_campaign_id IS NULL OR q.campaign_id = p_campaign_id)
      AND (p_evento_id IS NULL OR q.evento_id = p_evento_id)
      AND (p_participacion_ids IS NULL OR q.participacion_id = ANY(p_participacion_ids))
      AND q.estado = 'error'
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      PERFORM public.rewards_accrue_one(v_rec.id);
      v_recovered_queue := v_recovered_queue + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- B. Procesar participaciones en rewards_participation_reviews que quedaron en 'pendiente'
  FOR v_rec IN
    SELECT r.participacion_id
    FROM public.rewards_participation_reviews r
    WHERE (p_organizador_id IS NULL OR r.organizador_id = p_organizador_id)
      AND (p_campaign_id IS NULL OR r.campaign_id = p_campaign_id)
      AND (p_evento_id IS NULL OR r.evento_id = p_evento_id)
      AND (p_participacion_ids IS NULL OR r.participacion_id = ANY(p_participacion_ids))
      AND r.estado = 'pendiente'
  LOOP
    BEGIN
      PERFORM public.rewards_enqueue_candidate(v_rec.participacion_id);
      v_recovered_pending := v_recovered_pending + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- C. Encontrar participaciones reales en jugador_participaciones que no estaban en reviews
  -- o fueron asignadas al organizador incorrecto, restringidas estrictamente a campañas activas.
  FOR v_rec IN
    SELECT jp.id
    FROM public.jugador_participaciones jp
    JOIN public.rewards_campaigns c ON c.organizador_id = COALESCE(
      NULLIF(trim(jp.metadata->>'organizador_id'), '')::uuid,
      public.riviera_participacion_expected_host_org(jp.tipo_evento::text, jp.evento_id::text)
    )
    WHERE (p_organizador_id IS NULL OR c.organizador_id = p_organizador_id)
      AND (p_campaign_id IS NULL OR c.id = p_campaign_id)
      AND (p_evento_id IS NULL OR jp.evento_id = p_evento_id)
      AND (p_participacion_ids IS NULL OR jp.id = ANY(p_participacion_ids))
      AND c.estado = 'activa'
      AND COALESCE(jp.created_at, jp.fecha::timestamptz, now()) >= c.acumula_desde
      AND COALESCE(jp.created_at, jp.fecha::timestamptz, now()) < c.acumula_hasta
      AND jp.tipo_evento::text IN ('reta', 'americano', 'duelo_2v2')
      AND NOT EXISTS (
        SELECT 1 FROM public.rewards_participation_reviews r
        WHERE r.participacion_id = jp.id
          AND r.estado IN ('aprobada', 'rechazada')
      )
  LOOP
    BEGIN
      PERFORM public.rewards_enqueue_candidate(v_rec.id);
      v_recovered_missing := v_recovered_missing + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'recovered_queue_errors', v_recovered_queue,
    'recovered_pending_reviews', v_recovered_pending,
    'recovered_missing_participations', v_recovered_missing,
    'errors', v_errors
  );
END;
$$;


ALTER FUNCTION "public"."rewards_recover_participaciones"("p_organizador_id" "uuid", "p_campaign_id" "uuid", "p_evento_id" "uuid", "p_participacion_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_release_hold"("p_redemption_id" "uuid", "p_estado" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_hold public.rewards_lot_holds%ROWTYPE;
  v_lot public.rewards_lots%ROWTYPE;
  v_canje_hasta timestamptz;
  v_abierta boolean;
BEGIN
  FOR v_hold IN
    SELECT * FROM public.rewards_lot_holds WHERE redemption_id = p_redemption_id FOR UPDATE
  LOOP
    SELECT * INTO v_lot FROM public.rewards_lots WHERE id = v_hold.lot_id FOR UPDATE;
    SELECT c.canje_hasta INTO v_canje_hasta
    FROM public.rewards_campaigns c
    WHERE c.id = v_lot.campaign_id;
    v_abierta := v_canje_hasta > now() AND NOT v_lot.anulado;

    IF v_abierta THEN
      UPDATE public.rewards_lots
      SET puntos_restantes = puntos_restantes + v_hold.puntos
      WHERE id = v_lot.id;
    END IF;

    INSERT INTO public.rewards_ledger (
      organizador_id, jugador_id, campaign_id, lot_id, redemption_id,
      tipo, puntos, idempotency_key, motivo
    )
    SELECT v_lot.organizador_id, v_lot.jugador_id, v_lot.campaign_id, v_lot.id, p_redemption_id,
           CASE
             WHEN v_lot.anulado THEN 'reversion'
             WHEN v_abierta THEN 'liberacion'
             ELSE 'cierre'
           END,
           CASE
             WHEN v_lot.anulado THEN -v_hold.puntos
             WHEN v_abierta THEN v_hold.puntos
             ELSE -v_hold.puntos
           END,
           CASE
             WHEN v_lot.anulado THEN 'reversion-hold:'
             WHEN v_abierta THEN 'liberacion:'
             ELSE 'cierre-hold:'
           END
             || p_redemption_id::text || ':' || v_lot.id::text,
           CASE
             WHEN v_abierta THEN NULL
             ELSE 'La ventana de canje ya cerró; la reserva no regresa al saldo'
           END
    ON CONFLICT (idempotency_key) DO NOTHING;
  END LOOP;

  DELETE FROM public.rewards_lot_holds WHERE redemption_id = p_redemption_id;

  UPDATE public.rewards_redemptions
  SET estado = p_estado, updated_at = now()
  WHERE id = p_redemption_id
    AND estado = 'reservado';
END;
$$;


ALTER FUNCTION "public"."rewards_release_hold"("p_redemption_id" "uuid", "p_estado" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_request_redemption"("p_organizador_id" "uuid", "p_reward_id" "uuid", "p_jugador_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reward public.rewards_rewards%ROWTYPE;
  v_campaign public.rewards_campaigns%ROWTYPE;
  v_id uuid;
  v_used integer;
  v_available integer;
BEGIN
  PERFORM public.rewards_assert_can_request(p_organizador_id, p_jugador_id);
  SELECT * INTO v_reward
  FROM public.rewards_rewards
  WHERE id = p_reward_id AND organizador_id = p_organizador_id
  FOR UPDATE;
  IF NOT FOUND OR v_reward.estado <> 'activo' THEN
    RAISE EXCEPTION 'Premio no disponible';
  END IF;
  SELECT * INTO v_campaign FROM public.rewards_campaigns WHERE id = v_reward.campaign_id;
  IF v_campaign.estado <> 'activa' OR now() < v_campaign.canje_desde OR now() >= v_campaign.canje_hasta THEN
    RAISE EXCEPTION 'La ventana de canje está cerrada';
  END IF;
  IF v_reward.limite_por_jugador IS NOT NULL THEN
    SELECT COUNT(*) INTO v_used
    FROM public.rewards_redemptions
    WHERE reward_id = v_reward.id
      AND jugador_id = p_jugador_id
      AND estado IN ('solicitado', 'reservado', 'entregado');
    IF v_used >= v_reward.limite_por_jugador THEN
      RAISE EXCEPTION 'Este jugador ya alcanzó el límite del premio';
    END IF;
  END IF;

  SELECT COALESCE(SUM(puntos_restantes), 0) INTO v_available
  FROM public.rewards_lots
  WHERE campaign_id = v_campaign.id
    AND jugador_id = p_jugador_id
    AND NOT anulado;
  IF v_available < v_reward.costo_puntos THEN
    RAISE EXCEPTION 'Saldo insuficiente para solicitar este premio';
  END IF;

  INSERT INTO public.rewards_redemptions (
    organizador_id, campaign_id, reward_id, jugador_id, costo_puntos, snapshot, requested_by
  )
  VALUES (
    p_organizador_id,
    v_campaign.id,
    v_reward.id,
    p_jugador_id,
    v_reward.costo_puntos,
    jsonb_build_object(
      'nombre', v_reward.nombre,
      'descripcion', v_reward.descripcion,
      'tipo', v_reward.tipo,
      'costo_puntos', v_reward.costo_puntos,
      'cantidad', v_reward.cantidad,
      'condiciones', v_reward.condiciones
    ),
    auth.uid()
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."rewards_request_redemption"("p_organizador_id" "uuid", "p_reward_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_reserve_redemption"("p_redemption_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_red public.rewards_redemptions%ROWTYPE;
  v_reward public.rewards_rewards%ROWTYPE;
  v_campaign public.rewards_campaigns%ROWTYPE;
  v_lot public.rewards_lots%ROWTYPE;
  v_left integer;
  v_take integer;
BEGIN
  SELECT * INTO v_red FROM public.rewards_redemptions WHERE id = p_redemption_id FOR UPDATE;
  IF NOT FOUND OR v_red.estado <> 'solicitado' THEN
    RAISE EXCEPTION 'El canje no está pendiente de reserva';
  END IF;
  PERFORM public.rewards_assert_club_admin(v_red.organizador_id);
  PERFORM public.rewards_close_campaigns(v_red.organizador_id);

  SELECT * INTO v_red FROM public.rewards_redemptions WHERE id = p_redemption_id FOR UPDATE;
  SELECT * INTO v_reward FROM public.rewards_rewards WHERE id = v_red.reward_id FOR UPDATE;
  SELECT * INTO v_campaign FROM public.rewards_campaigns WHERE id = v_red.campaign_id;

  IF now() < v_campaign.canje_desde OR now() >= v_campaign.canje_hasta THEN
    RAISE EXCEPTION 'La ventana de canje está cerrada';
  END IF;
  IF v_reward.inventario_restante IS NOT NULL AND v_reward.inventario_restante <= 0 THEN
    RAISE EXCEPTION 'Sin inventario';
  END IF;

  v_left := v_red.costo_puntos;
  FOR v_lot IN
    SELECT *
    FROM public.rewards_lots
    WHERE organizador_id = v_red.organizador_id
      AND jugador_id = v_red.jugador_id
      AND campaign_id = v_red.campaign_id
      AND puntos_restantes > 0
      AND NOT anulado
    ORDER BY earned_at, id
    FOR UPDATE
  LOOP
    EXIT WHEN v_left = 0;
    v_take := LEAST(v_lot.puntos_restantes, v_left);
    UPDATE public.rewards_lots
    SET puntos_restantes = puntos_restantes - v_take
    WHERE id = v_lot.id;
    INSERT INTO public.rewards_lot_holds (redemption_id, lot_id, puntos)
    VALUES (v_red.id, v_lot.id, v_take);
    INSERT INTO public.rewards_ledger (
      organizador_id, jugador_id, campaign_id, lot_id, redemption_id,
      tipo, puntos, idempotency_key, actor_id
    )
    VALUES (
      v_red.organizador_id, v_red.jugador_id, v_red.campaign_id, v_lot.id, v_red.id,
      'reserva', -v_take, 'reserva:' || v_red.id::text || ':' || v_lot.id::text, auth.uid()
    );
    v_left := v_left - v_take;
  END LOOP;

  IF v_left > 0 THEN
    RAISE EXCEPTION 'Saldo insuficiente';
  END IF;

  IF v_reward.inventario_restante IS NOT NULL THEN
    UPDATE public.rewards_rewards
    SET inventario_restante = inventario_restante - 1, updated_at = now()
    WHERE id = v_reward.id;
  END IF;

  UPDATE public.rewards_redemptions
  SET estado = 'reservado',
      reserva_hasta = LEAST(
        COALESCE(v_reward.disponible_hasta, now() + make_interval(days => v_campaign.reserva_dias)),
        now() + make_interval(days => v_campaign.reserva_dias)
      ),
      updated_at = now()
  WHERE id = v_red.id;
END;
$$;


ALTER FUNCTION "public"."rewards_reserve_redemption"("p_redemption_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_retry_accruals"("p_limit" integer DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_res jsonb;
BEGIN
  v_res := public.rewards_process_queue(p_limit, 'retry-accruals-compat');
  RETURN COALESCE((v_res->>'processed')::integer, 0);
END;
$$;


ALTER FUNCTION "public"."rewards_retry_accruals"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_review_participations"("p_organizador_id" "uuid", "p_participacion_ids" "uuid"[], "p_decision" "text", "p_campaign_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign public.rewards_campaigns%ROWTYPE;
  v_id uuid;
  v_review public.rewards_participation_reviews%ROWTYPE;
  v_count integer := 0;
  v_key text;
  v_queue uuid;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);
  IF p_decision NOT IN ('aprobada', 'rechazada') THEN
    RAISE EXCEPTION 'Decisión inválida';
  END IF;

  IF p_decision = 'aprobada' THEN
    SELECT * INTO v_campaign FROM public.rewards_campaigns WHERE id = p_campaign_id;
    IF NOT FOUND OR v_campaign.organizador_id IS DISTINCT FROM p_organizador_id THEN
      RAISE EXCEPTION 'Campaña no encontrada en este club';
    END IF;
    IF v_campaign.estado <> 'activa' THEN
      RAISE EXCEPTION 'La campaña no está activa';
    END IF;
    IF v_campaign.validation_mode = 'payment' THEN
      RAISE EXCEPTION 'payment_validation_not_available';
    END IF;
  END IF;

  FOREACH v_id IN ARRAY COALESCE(p_participacion_ids, ARRAY[]::uuid[])
  LOOP
    SELECT * INTO v_review
    FROM public.rewards_participation_reviews
    WHERE participacion_id = v_id
      AND organizador_id = p_organizador_id
    FOR UPDATE;
    IF NOT FOUND OR v_review.estado <> 'pendiente' THEN
      CONTINUE;
    END IF;

    IF p_decision = 'rechazada' THEN
      UPDATE public.rewards_participation_reviews
      SET estado = 'rechazada',
          motivo = p_motivo,
          decided_by = auth.uid(),
          decided_at = now()
      WHERE id = v_review.id;
      v_count := v_count + 1;
      CONTINUE;
    END IF;

    IF NOT (v_review.modalidad = ANY (v_campaign.modalidades)) THEN
      CONTINUE;
    END IF;
    IF v_review.closed_at < v_campaign.acumula_desde
       OR v_review.closed_at >= v_campaign.acumula_hasta THEN
      CONTINUE;
    END IF;

    UPDATE public.rewards_participation_reviews
    SET estado = 'aprobada',
        campaign_id = v_campaign.id,
        validation_source = 'admin',
        motivo = p_motivo,
        decided_by = auth.uid(),
        decided_at = now()
    WHERE id = v_review.id;

    v_key := v_review.organizador_id::text || ':' || v_review.jugador_id::text
      || ':' || v_review.tipo_evento || ':' || v_review.evento_id::text;

    INSERT INTO public.rewards_accrual_queue (
      organizador_id, review_id, campaign_id, participacion_id, jugador_id,
      tipo_evento, evento_id, idempotency_key, validation_source
    )
    VALUES (
      v_review.organizador_id, v_review.id, v_campaign.id, v_review.participacion_id,
      v_review.jugador_id, v_review.tipo_evento, v_review.evento_id, v_key, 'admin'
    )
    ON CONFLICT (idempotency_key) DO NOTHING;

    SELECT q.id INTO v_queue
    FROM public.rewards_accrual_queue q
    WHERE q.idempotency_key = v_key;

    IF v_queue IS NOT NULL THEN
      BEGIN
        PERFORM public.rewards_accrue_one(v_queue);
      EXCEPTION WHEN OTHERS THEN
        UPDATE public.rewards_accrual_queue
        SET estado = 'error',
            attempts = attempts + 1,
            last_error = SQLERRM
        WHERE id = v_queue
          AND estado NOT IN ('acreditada', 'omitida');
      END;
    END IF;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."rewards_review_participations"("p_organizador_id" "uuid", "p_participacion_ids" "uuid"[], "p_decision" "text", "p_campaign_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_same_player"("p_a" "uuid", "p_b" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_key_a uuid;
  v_key_b uuid;
BEGIN
  IF p_a IS NULL OR p_b IS NULL THEN
    RETURN false;
  END IF;
  IF p_a = p_b THEN
    RETURN true;
  END IF;

  -- Misma identidad oficial global (Riviera ID / official_player_key).
  v_key_a := public._resolve_official_player_key(p_a);
  IF v_key_a IS NOT NULL THEN
    v_key_b := public._resolve_official_player_key(p_b);
    IF v_key_b IS NOT NULL AND v_key_a = v_key_b THEN
      RETURN true;
    END IF;
  END IF;

  -- Par origen/clon de un acceso cedido activo.
  RETURN EXISTS (
    SELECT 1
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND (
        (opa.jugador_id = p_a AND opa.local_jugador_id = p_b)
        OR (opa.jugador_id = p_b AND opa.local_jugador_id = p_a)
      )
  );
END;
$$;


ALTER FUNCTION "public"."rewards_same_player"("p_a" "uuid", "p_b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_save_campaign"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid := NULLIF(p_payload->>'id', '')::uuid;
  v_org uuid := (p_payload->>'organizador_id')::uuid;
  v_estado text := COALESCE(p_payload->>'estado', 'borrador');
  v_desde timestamptz := (p_payload->>'acumula_desde')::timestamptz;
  v_hasta timestamptz := (p_payload->>'acumula_hasta')::timestamptz;
  v_mods text[] := ARRAY(SELECT jsonb_array_elements_text(p_payload->'modalidades'));
  v_existing public.rewards_campaigns%ROWTYPE;
  v_conflict uuid;
BEGIN
  PERFORM public.rewards_assert_club_admin(v_org);
  IF v_desde >= v_hasta THEN
    RAISE EXCEPTION 'La ventana de acumulación es inválida';
  END IF;
  IF (p_payload->>'canje_desde')::timestamptz >= (p_payload->>'canje_hasta')::timestamptz THEN
    RAISE EXCEPTION 'La ventana de canje es inválida';
  END IF;
  IF COALESCE(array_length(v_mods, 1), 0) = 0 THEN
    RAISE EXCEPTION 'Elige al menos una modalidad de reta';
  END IF;

  IF v_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.rewards_campaigns WHERE id = v_id;
    IF NOT FOUND OR v_existing.organizador_id IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'Campaña no encontrada en este club';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.rewards_lots l WHERE l.campaign_id = v_id
    ) OR EXISTS (
      SELECT 1 FROM public.rewards_redemptions r WHERE r.campaign_id = v_id
    ) THEN
      IF v_existing.acumula_desde IS DISTINCT FROM v_desde
         OR v_existing.acumula_hasta IS DISTINCT FROM v_hasta
         OR v_existing.canje_desde IS DISTINCT FROM (p_payload->>'canje_desde')::timestamptz
         OR v_existing.canje_hasta IS DISTINCT FROM (p_payload->>'canje_hasta')::timestamptz
         OR v_existing.puntos_por_participacion IS DISTINCT FROM (p_payload->>'puntos_por_participacion')::integer
      THEN
        RAISE EXCEPTION 'Esta campaña ya tiene puntos o canjes; no se reescriben sus reglas';
      END IF;
    END IF;
  END IF;

  IF v_estado IN ('programada', 'activa', 'pausada') THEN
    SELECT c.id INTO v_conflict
    FROM public.rewards_campaigns c
    WHERE c.organizador_id = v_org
      AND c.id IS DISTINCT FROM v_id
      AND c.estado IN ('programada', 'activa', 'pausada')
      AND c.acumula_desde < v_hasta
      AND v_desde < c.acumula_hasta
      AND c.modalidades && v_mods
    LIMIT 1;
    IF v_conflict IS NOT NULL THEN
      RAISE EXCEPTION 'Ya hay una campaña de este club que cubre esas modalidades en las mismas fechas';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_timezone_names
    WHERE name = COALESCE(NULLIF(p_payload->>'timezone', ''), 'America/Mexico_City')
  ) THEN
    RAISE EXCEPTION 'Zona horaria inválida';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.rewards_campaigns (
      organizador_id, nombre, descripcion, timezone,
      acumula_desde, acumula_hasta, canje_desde, canje_hasta,
      puntos_por_participacion, modalidades, estado,
      visible_jugadores, condiciones, validation_mode, reserva_dias, created_by
    )
    VALUES (
      v_org,
      p_payload->>'nombre',
      NULLIF(p_payload->>'descripcion', ''),
      COALESCE(NULLIF(p_payload->>'timezone', ''), 'America/Mexico_City'),
      v_desde,
      v_hasta,
      (p_payload->>'canje_desde')::timestamptz,
      (p_payload->>'canje_hasta')::timestamptz,
      (p_payload->>'puntos_por_participacion')::integer,
      v_mods,
      v_estado,
      COALESCE((p_payload->>'visible_jugadores')::boolean, false),
      NULLIF(p_payload->>'condiciones', ''),
      COALESCE(NULLIF(p_payload->>'validation_mode', ''), 'admin'),
      COALESCE((p_payload->>'reserva_dias')::integer, 7),
      auth.uid()
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.rewards_campaigns
    SET nombre = p_payload->>'nombre',
        descripcion = NULLIF(p_payload->>'descripcion', ''),
        timezone = COALESCE(NULLIF(p_payload->>'timezone', ''), timezone),
        acumula_desde = v_desde,
        acumula_hasta = v_hasta,
        canje_desde = (p_payload->>'canje_desde')::timestamptz,
        canje_hasta = (p_payload->>'canje_hasta')::timestamptz,
        puntos_por_participacion = (p_payload->>'puntos_por_participacion')::integer,
        modalidades = v_mods,
        estado = v_estado,
        visible_jugadores = COALESCE((p_payload->>'visible_jugadores')::boolean, false),
        condiciones = NULLIF(p_payload->>'condiciones', ''),
        validation_mode = COALESCE(NULLIF(p_payload->>'validation_mode', ''), 'admin'),
        reserva_dias = COALESCE((p_payload->>'reserva_dias')::integer, 7),
        updated_at = now()
    WHERE id = v_id;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."rewards_save_campaign"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_save_reward"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid := NULLIF(p_payload->>'id', '')::uuid;
  v_campaign public.rewards_campaigns%ROWTYPE;
  v_org uuid;
BEGIN
  SELECT * INTO v_campaign
  FROM public.rewards_campaigns
  WHERE id = (p_payload->>'campaign_id')::uuid;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaña no encontrada';
  END IF;
  v_org := v_campaign.organizador_id;
  PERFORM public.rewards_assert_club_admin(v_org);

  IF v_id IS NULL THEN
    INSERT INTO public.rewards_rewards (
      campaign_id, organizador_id, nombre, descripcion, imagen_url,
      costo_puntos, tipo, cantidad, inventario, inventario_restante,
      limite_por_jugador, disponible_desde, disponible_hasta, condiciones, estado
    )
    VALUES (
      v_campaign.id,
      v_org,
      p_payload->>'nombre',
      NULLIF(p_payload->>'descripcion', ''),
      NULLIF(p_payload->>'imagen_url', ''),
      (p_payload->>'costo_puntos')::integer,
      p_payload->>'tipo',
      NULLIF(p_payload->>'cantidad', '')::integer,
      NULLIF(p_payload->>'inventario', '')::integer,
      NULLIF(p_payload->>'inventario', '')::integer,
      NULLIF(p_payload->>'limite_por_jugador', '')::integer,
      NULLIF(p_payload->>'disponible_desde', '')::timestamptz,
      NULLIF(p_payload->>'disponible_hasta', '')::timestamptz,
      NULLIF(p_payload->>'condiciones', ''),
      COALESCE(NULLIF(p_payload->>'estado', ''), 'borrador')
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.rewards_rewards
    SET nombre = p_payload->>'nombre',
        descripcion = NULLIF(p_payload->>'descripcion', ''),
        imagen_url = NULLIF(p_payload->>'imagen_url', ''),
        costo_puntos = (p_payload->>'costo_puntos')::integer,
        tipo = p_payload->>'tipo',
        cantidad = NULLIF(p_payload->>'cantidad', '')::integer,
        inventario_restante = CASE
          WHEN NULLIF(p_payload->>'inventario', '') IS NULL THEN NULL
          WHEN inventario IS NULL THEN NULLIF(p_payload->>'inventario', '')::integer
          ELSE GREATEST(
            0,
            COALESCE(inventario_restante, 0)
              + (NULLIF(p_payload->>'inventario', '')::integer - inventario)
          )
        END,
        inventario = NULLIF(p_payload->>'inventario', '')::integer,
        limite_por_jugador = NULLIF(p_payload->>'limite_por_jugador', '')::integer,
        disponible_desde = NULLIF(p_payload->>'disponible_desde', '')::timestamptz,
        disponible_hasta = NULLIF(p_payload->>'disponible_hasta', '')::timestamptz,
        condiciones = NULLIF(p_payload->>'condiciones', ''),
        estado = COALESCE(NULLIF(p_payload->>'estado', ''), estado),
        updated_at = now()
    WHERE id = v_id
      AND organizador_id = v_org;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Premio no encontrado en este club';
    END IF;
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."rewards_save_reward"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_settle_invalid_lot"("p_participacion_id" "uuid", "p_motivo" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lot public.rewards_lots%ROWTYPE;
  v_canje integer;
BEGIN
  SELECT * INTO v_lot
  FROM public.rewards_lots
  WHERE participacion_id = p_participacion_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_lot.puntos_restantes > 0 THEN
    INSERT INTO public.rewards_ledger (
      organizador_id, jugador_id, campaign_id, lot_id, tipo, puntos, idempotency_key, motivo, actor_id
    )
    VALUES (
      v_lot.organizador_id, v_lot.jugador_id, v_lot.campaign_id, v_lot.id,
      'reversion', -v_lot.puntos_restantes,
      'reversion-invalida:' || v_lot.id::text,
      p_motivo, auth.uid()
    )
    ON CONFLICT (idempotency_key) DO NOTHING;
    UPDATE public.rewards_lots
    SET puntos_restantes = 0, anulado = true
    WHERE id = v_lot.id;
  ELSE
    UPDATE public.rewards_lots SET anulado = true WHERE id = v_lot.id;
  END IF;

  SELECT COALESCE(SUM(-puntos), 0) INTO v_canje
  FROM public.rewards_ledger
  WHERE lot_id = v_lot.id
    AND tipo = 'canje';

  IF v_canje > 0 THEN
    INSERT INTO public.rewards_obligations (
      organizador_id, jugador_id, campaign_id, lot_id, participacion_id,
      puntos_originales, puntos_pendientes, motivo
    )
    VALUES (
      v_lot.organizador_id, v_lot.jugador_id, v_lot.campaign_id, v_lot.id,
      v_lot.participacion_id, v_canje, v_canje, p_motivo
    )
    ON CONFLICT (lot_id) DO UPDATE
    SET puntos_originales = GREATEST(public.rewards_obligations.puntos_originales, EXCLUDED.puntos_originales),
        puntos_pendientes = GREATEST(public.rewards_obligations.puntos_pendientes, EXCLUDED.puntos_pendientes),
        motivo = EXCLUDED.motivo;
  END IF;
END;
$$;


ALTER FUNCTION "public"."rewards_settle_invalid_lot"("p_participacion_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_sync_candidates"("p_organizador_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_count integer := 0;
  v_desde timestamptz;
BEGIN
  PERFORM public.rewards_assert_club_admin(p_organizador_id);
  SELECT MIN(c.acumula_desde) INTO v_desde
  FROM public.rewards_campaigns c
  WHERE c.organizador_id = p_organizador_id
    AND c.estado IN ('programada', 'activa', 'pausada');
  IF v_desde IS NULL THEN
    RETURN 0;
  END IF;

  FOR v_id IN
    SELECT jp.id
    FROM public.jugador_participaciones jp
    LEFT JOIN public.riviera_jugadores rj ON rj.id = jp.jugador_id
    WHERE COALESCE(
      NULLIF(trim(jp.metadata->>'organizador_id'), '')::uuid,
      public.riviera_participacion_expected_host_org(jp.tipo_evento::text, jp.evento_id::text),
      rj.organizador_id
    ) = p_organizador_id
      AND COALESCE(jp.created_at, jp.fecha::timestamptz) >= v_desde
      AND jp.tipo_evento::text IN ('reta', 'americano', 'duelo_2v2')
      AND NOT EXISTS (
        SELECT 1 FROM public.rewards_participation_reviews r
        WHERE r.participacion_id = jp.id
          AND r.estado = 'aprobada'
      )
  LOOP
    PERFORM public.rewards_enqueue_candidate(v_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."rewards_sync_candidates"("p_organizador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rewards_sync_historical_participations"("p_organizador_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
