CREATE OR REPLACE FUNCTION "public"."riviera_career_event_host_manual_override"("p_tipo_evento" "text", "p_evento_id" "text") RETURNS TABLE("override_id" "uuid", "organizador_id" "uuid", "club_name" "text", "evento_nombre" "text", "approved_by" "uuid", "approved_at" timestamp with time zone, "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF to_regclass('public.career_event_host_manual_overrides') IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    o.id,
    o.organizador_id,
    o.club_name,
    o.evento_nombre,
    o.approved_by,
    o.approved_at,
    o.reason
  FROM public.career_event_host_manual_overrides o
  WHERE o.tipo_evento = trim(p_tipo_evento)
    AND o.evento_id = trim(p_evento_id)
  LIMIT 1;
END;
$$;


