CREATE OR REPLACE FUNCTION "public"."riviera_jugador_interno_por_slug"("p_organizador_id" "uuid", "p_slug" "text") RETURNS TABLE("id" "uuid", "organizador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "email" "text", "telefono" "text", "whatsapp" "text", "nivel" "text", "categoria" "text", "edad" integer, "mano_dominante" "text", "en_cancha" "text", "pais_codigo" "text", "instagram_url" "text", "facebook_url" "text", "tiktok_url" "text", "visible_publico" boolean, "suma_ranking" boolean, "genero" "text", "fecha_nacimiento" "date", "club" "text", "estado" "text", "legacy_player_id" "uuid", "legacy_liga_jugador_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "rating" numeric, "rating_partidos" integer, "rating_fiabilidad" numeric, "puntos_totales" integer, "total_partidos" integer, "victorias" integer, "derrotas" integer, "empates" integer, "participaciones_solo" integer, "pct_victorias" numeric, "total_retas" integer, "total_torneos_express" integer, "total_ligas" integer, "total_americanos" integer, "sets_favor_total" integer, "sets_contra_total" integer, "racha_actual" "text", "ultima_actividad" timestamp with time zone, "stats_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_owner_or_admin boolean;
BEGIN
  v_is_owner_or_admin :=
    auth.uid() IS NOT NULL
    AND (auth.uid() = p_organizador_id OR public.is_master_admin());

  RETURN QUERY
  SELECT
    rj.id,
