CREATE OR REPLACE FUNCTION "public"."riviera_jugador_privado_por_id"("p_jugador_id" "uuid") RETURNS TABLE("id" "uuid", "organizador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "email" "text", "telefono" "text", "whatsapp" "text", "nivel" "text", "categoria" "text", "edad" integer, "mano_dominante" "text", "en_cancha" "text", "pais_codigo" "text", "instagram_url" "text", "facebook_url" "text", "tiktok_url" "text", "visible_publico" boolean, "suma_ranking" boolean, "genero" "text", "fecha_nacimiento" "date", "club" "text", "estado" "text", "legacy_player_id" "uuid", "legacy_liga_jugador_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "rating" numeric, "rating_partidos" integer, "rating_fiabilidad" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  RETURN QUERY
  SELECT
    rj.id, rj.organizador_id, rj.nombre, rj.slug, rj.foto_url,
    rj.email, rj.telefono, rj.whatsapp, rj.nivel::text, rj.categoria,
    rj.edad::integer, rj.mano_dominante, rj.en_cancha, rj.pais_codigo::text,
    rj.instagram_url, rj.facebook_url, rj.tiktok_url,
    rj.visible_publico, rj.suma_ranking, rj.genero, rj.fecha_nacimiento,
    rj.club, rj.estado::text, rj.legacy_player_id, rj.legacy_liga_jugador_id,
    rj.created_at, rj.updated_at, rj.rating, rj.rating_partidos, rj.rating_fiabilidad
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_jugador_id
    AND (rj.organizador_id = auth.uid() OR public.is_master_admin());
END;
$$;


ALTER FUNCTION "public"."riviera_jugador_privado_por_id"("p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_jugadores_privados_listar"("p_organizador_id" "uuid", "p_genero" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_nivel" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "organizador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "email" "text", "telefono" "text", "whatsapp" "text", "nivel" "text", "categoria" "text", "edad" integer, "mano_dominante" "text", "en_cancha" "text", "pais_codigo" "text", "instagram_url" "text", "facebook_url" "text", "tiktok_url" "text", "visible_publico" boolean, "suma_ranking" boolean, "genero" "text", "fecha_nacimiento" "date", "club" "text", "estado" "text", "legacy_player_id" "uuid", "legacy_liga_jugador_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "rating" numeric, "rating_partidos" integer, "rating_fiabilidad" numeric, "stats" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  IF p_organizador_id IS DISTINCT FROM auth.uid() AND NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Sin permiso';
  END IF;

  RETURN QUERY
  SELECT
    rj.id, rj.organizador_id, rj.nombre, rj.slug, rj.foto_url,
    rj.email, rj.telefono, rj.whatsapp, rj.nivel::text, rj.categoria,
    rj.edad::integer, rj.mano_dominante, rj.en_cancha, rj.pais_codigo::text,
    rj.instagram_url, rj.facebook_url, rj.tiktok_url,
    rj.visible_publico, rj.suma_ranking, rj.genero, rj.fecha_nacimiento,
    rj.club, rj.estado::text, rj.legacy_player_id, rj.legacy_liga_jugador_id,
    rj.created_at, rj.updated_at, rj.rating, rj.rating_partidos, rj.rating_fiabilidad,
    CASE WHEN js.jugador_id IS NULL THEN NULL ELSE jsonb_build_object(
      'jugador_id', js.jugador_id,
      'total_partidos', js.total_partidos,
      'victorias', js.victorias,
      'derrotas', js.derrotas,
      'empates', js.empates,
      'participaciones_solo', js.participaciones_solo,
      'pct_victorias', js.pct_victorias,
      'total_retas', js.total_retas,
      'total_torneos_express', js.total_torneos_express,
      'total_ligas', js.total_ligas,
      'total_americanos', js.total_americanos,
      'sets_favor_total', js.sets_favor_total,
      'sets_contra_total', js.sets_contra_total,
      'racha_actual', js.racha_actual,
      'ultima_actividad', js.ultima_actividad,
      'puntos_totales', js.puntos_totales,
      'updated_at', js.updated_at
    ) END AS stats
  FROM public.riviera_jugadores rj
  LEFT JOIN public.jugador_stats js ON js.jugador_id = rj.id
  WHERE rj.organizador_id = p_organizador_id
    AND rj.estado <> 'archivado'
    AND (
      p_genero IS NULL OR p_genero = ''
      OR (p_genero = 'F' AND rj.genero = 'F')
      OR (p_genero = 'M' AND (rj.genero = 'M' OR rj.genero IS NULL))
    )
    AND (p_search IS NULL OR p_search = '' OR rj.nombre ILIKE '%' || p_search || '%')
    AND (p_nivel IS NULL OR p_nivel = '' OR rj.categoria = p_nivel)
  ORDER BY rj.nombre;
END;
$$;


