ALTER FUNCTION "public"."riviera_list_career_participaciones_public"("p_jugador_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_list_career_participaciones_public"("p_jugador_id" "uuid", "p_limit" integer) IS 'Historial global por Carrera Deportiva para ficha pública (multiclub / cedidos).';



CREATE OR REPLACE FUNCTION "public"."riviera_list_participaciones_enriched"("p_jugador_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS SETOF "public"."jugador_participaciones"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    jp.id,
    jp.jugador_id,
    jp.tipo_evento,
    jp.evento_id,
    jp.evento_nombre,
    jp.fecha,
    jp.pareja_con,
    jp.resultado,
    jp.sets_favor,
    jp.sets_contra,
    jp.puntos_obtenidos,
    CASE
      WHEN COALESCE(jp.metadata->>'organizador_id', '') <> '' THEN jp.metadata
      WHEN d.id IS NOT NULL THEN COALESCE(jp.metadata, '{}'::jsonb)
        || jsonb_build_object('organizador_id', d.organizador_id::text)
      WHEN t.id IS NOT NULL THEN COALESCE(jp.metadata, '{}'::jsonb)
        || jsonb_build_object('organizador_id', t.organizador_id::text)
      ELSE COALESCE(jp.metadata, '{}'::jsonb)
    END AS metadata,
    jp.created_at
  FROM public.jugador_participaciones jp
  LEFT JOIN public.duelos_2v2 d
    ON jp.tipo_evento = 'duelo_2v2'
   AND jp.evento_id::uuid = d.id
  LEFT JOIN public.torneo_express t
    ON jp.tipo_evento = 'torneo_express'
   AND jp.evento_id::uuid = t.id
  WHERE jp.jugador_id = p_jugador_id
  ORDER BY jp.fecha DESC NULLS LAST, jp.created_at DESC NULLS LAST
  LIMIT GREATEST(COALESCE(p_limit, 100), 1);
$$;


ALTER FUNCTION "public"."riviera_list_participaciones_enriched"("p_jugador_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_list_participaciones_enriched"("p_jugador_id" "uuid", "p_limit" integer) IS 'Historial del jugador con metadata.organizador_id inferido desde duelo/torneo (multiclub).';



CREATE OR REPLACE FUNCTION "public"."riviera_list_participaciones_for_jugador_ids"("p_jugador_ids" "uuid"[], "p_limit" integer DEFAULT 500) RETURNS SETOF "public"."jugador_participaciones"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    jp.id,
    jp.jugador_id,
    jp.tipo_evento,
    jp.evento_id,
    jp.evento_nombre,
    jp.fecha,
    jp.pareja_con,
    jp.resultado,
    jp.sets_favor,
    jp.sets_contra,
    jp.puntos_obtenidos,
    CASE
      WHEN COALESCE(jp.metadata->>'organizador_id', '') <> '' THEN jp.metadata
      WHEN d.id IS NOT NULL THEN COALESCE(jp.metadata, '{}'::jsonb)
        || jsonb_build_object('organizador_id', d.organizador_id::text)
      WHEN t.id IS NOT NULL THEN COALESCE(jp.metadata, '{}'::jsonb)
        || jsonb_build_object('organizador_id', t.organizador_id::text)
      ELSE COALESCE(jp.metadata, '{}'::jsonb)
    END AS metadata,
    jp.created_at
  FROM public.jugador_participaciones jp
  INNER JOIN public.riviera_jugadores rj ON rj.id = jp.jugador_id
  LEFT JOIN public.duelos_2v2 d
    ON jp.tipo_evento = 'duelo_2v2'
   AND jp.evento_id::uuid = d.id
  LEFT JOIN public.torneo_express t
    ON jp.tipo_evento = 'torneo_express'
   AND jp.evento_id::uuid = t.id
  WHERE jp.jugador_id = ANY(p_jugador_ids)
    AND rj.estado = 'activo'
    AND NOT public.is_jugador_participacion_excluded(
      jp.jugador_id,
      jp.tipo_evento::text,
      jp.evento_id
    )
  ORDER BY jp.fecha DESC NULLS LAST, jp.created_at DESC NULLS LAST
  LIMIT GREATEST(COALESCE(p_limit, 500), 1);
$$;


ALTER FUNCTION "public"."riviera_list_participaciones_for_jugador_ids"("p_jugador_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_list_participaciones_for_jugador_ids"("p_jugador_ids" "uuid"[], "p_limit" integer) IS 'Participaciones globales por lista explícita de jugador_id (motor de carrera unificado).';



CREATE OR REPLACE FUNCTION "public"."riviera_official_display_puntos_for_jugador"("p_riviera_jugador_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_key uuid;
  v_pts integer;
BEGIN
  IF p_riviera_jugador_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_key := public._resolve_official_player_key(p_riviera_jugador_id);
  IF v_key IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(t.points_total, 0)::integer
  INTO v_pts
  FROM public.riviera_official_player_totals t
  WHERE t.official_player_key = v_key;

  RETURN COALESCE(v_pts, 0);
END;
$$;


ALTER FUNCTION "public"."riviera_official_display_puntos_for_jugador"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_official_display_puntos_for_jugador"("p_riviera_jugador_id" "uuid") IS 'Puntos acumulados Ranking Global Riviera Open (ROMC) para un perfil. NULL si no hay official_player_key.';



CREATE OR REPLACE FUNCTION "public"."riviera_official_display_puntos_for_jugador_batch"("p_riviera_jugador_ids" "uuid"[]) RETURNS TABLE("jugador_id" "uuid", "puntos" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (
    SELECT DISTINCT unnest(COALESCE(p_riviera_jugador_ids, ARRAY[]::uuid[])) AS jugador_id
  ),
  keyed AS (
    SELECT i.jugador_id, public._resolve_official_player_key(i.jugador_id) AS official_key
    FROM ids i
  )
  SELECT
    k.jugador_id,
    COALESCE(t.points_total, 0)::integer AS puntos
  FROM keyed k
  LEFT JOIN public.riviera_official_player_totals t
    ON t.official_player_key = k.official_key
  WHERE k.official_key IS NOT NULL;
$$;


ALTER FUNCTION "public"."riviera_official_display_puntos_for_jugador_batch"("p_riviera_jugador_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_official_ledger_points_for_jugador"("p_riviera_jugador_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT SUM(l.points)::integer
      FROM public.riviera_official_points_ledger l
      WHERE l.official_player_key = public.resolve_official_player_key_for_jugador(p_riviera_jugador_id)
        AND l.points > 0
    ),
    0
  );
$$;


ALTER FUNCTION "public"."riviera_official_ledger_points_for_jugador"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_official_legacy_points_for_jugador"("p_riviera_jugador_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT SUM(jp.puntos_obtenidos)::integer
      FROM public.jugador_participaciones jp
      WHERE jp.jugador_id IN (
        SELECT ids.riviera_jugador_id
        FROM public._riviera_official_jugador_ids_for_key(
          public.resolve_official_player_key_for_jugador(p_riviera_jugador_id)
        ) ids
      )
        AND COALESCE(jp.puntos_obtenidos, 0) > 0
        AND COALESCE(jp.metadata->>'subtipo', '') <> 'ajuste_manual'
        AND NOT EXISTS (
          SELECT 1
          FROM public.riviera_official_points_ledger l
          WHERE l.participacion_id = jp.id
        )
    ),
    0
  );
$$;


ALTER FUNCTION "public"."riviera_official_legacy_points_for_jugador"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_official_points_by_club_for_jugador"("p_riviera_jugador_id" "uuid") RETURNS TABLE("organizador_id" "uuid", "points" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    l.source_organizer_id AS organizador_id,
    SUM(l.points)::integer AS points
  FROM public.riviera_official_points_ledger l
  WHERE p_riviera_jugador_id IS NOT NULL
    AND l.counts_for_official_ranking
    AND l.official_player_key = public._resolve_official_player_key(p_riviera_jugador_id)
    AND l.source_organizer_id IS NOT NULL
  GROUP BY l.source_organizer_id
  HAVING SUM(l.points) > 0
  ORDER BY SUM(l.points) DESC, l.source_organizer_id;
$$;


ALTER FUNCTION "public"."riviera_official_points_by_club_for_jugador"("p_riviera_jugador_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_official_points_by_club_for_jugador"("p_riviera_jugador_id" "uuid") IS 'Puntos del ranking oficial Riviera Open por club emisor. Suma el ledger ROMC; no incluye ajustes manuales de carrera.';



CREATE OR REPLACE FUNCTION "public"."riviera_official_ranking_posicion_for_jugador"("p_jugador_id" "uuid", "p_organizador_id" "uuid" DEFAULT NULL::"uuid", "p_categoria" "text" DEFAULT NULL::"text", "p_genero" "text" DEFAULT 'M'::"text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH scoped AS (
    SELECT
      v.id,
      v.nombre,
      public.riviera_official_display_puntos_for_jugador(v.id) AS pts
    FROM public.riviera_jugadores_sitio_oficial v
    WHERE v.organizador_id = COALESCE(
      p_organizador_id,
      (SELECT rj.organizador_id FROM public.riviera_jugadores rj WHERE rj.id = p_jugador_id)
    )
      AND (p_categoria IS NULL OR v.categoria = p_categoria)
      AND (
        p_genero IS NULL
        OR (upper(p_genero) IN ('F', 'FEMENIL') AND v.genero = 'F')
        OR (
          upper(p_genero) IN ('M', 'VARONIL')
          AND (v.genero = 'M' OR v.genero IS NULL)
        )
      )
  ),
  ranked AS (
    SELECT
      id,
      RANK() OVER (ORDER BY pts DESC, nombre ASC) AS pos
    FROM scoped
  )
  SELECT pos::integer FROM ranked WHERE id = p_jugador_id;
$$;


ALTER FUNCTION "public"."riviera_official_ranking_posicion_for_jugador"("p_jugador_id" "uuid", "p_organizador_id" "uuid", "p_categoria" "text", "p_genero" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_organizadores_ranking_oficial"() RETURNS TABLE("organizador_id" "uuid", "nombre" "text", "email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT
    u.id AS organizador_id,
    u.name AS nombre,
    u.email AS email
  FROM public.users u
  INNER JOIN public.riviera_jugadores rj
    ON rj.organizador_id = u.id
  WHERE rj.estado = 'activo'
    AND rj.visible_publico IS TRUE
    AND COALESCE(rj.suma_ranking, true) = true
  ORDER BY u.name ASC, u.email ASC;
$$;


ALTER FUNCTION "public"."riviera_organizadores_ranking_oficial"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_organizadores_ranking_oficial"() IS 'Organizadores con al menos un jugador publicado en sitio oficial.';



CREATE OR REPLACE FUNCTION "public"."riviera_participacion_expected_host_org"("p_tipo_evento" "text", "p_evento_id" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE p_tipo_evento
    WHEN 'reta' THEN (
      SELECT t.user_id
      FROM public.tournaments t
      WHERE t.id = NULLIF(trim(p_evento_id), '')::uuid
      LIMIT 1
    )
    WHEN 'americano' THEN (
      SELECT t.user_id
      FROM public.tournaments t
      WHERE t.id = NULLIF(trim(p_evento_id), '')::uuid
      LIMIT 1
    )
    WHEN 'duelo_2v2' THEN (
      SELECT d.organizador_id
      FROM public.duelos_2v2 d
      WHERE d.id = NULLIF(trim(p_evento_id), '')::uuid
      LIMIT 1
    )
    WHEN 'torneo_express' THEN (
      SELECT t.organizador_id
      FROM public.torneo_express t
      WHERE t.id = NULLIF(trim(p_evento_id), '')::uuid
      LIMIT 1
    )
    WHEN 'liga' THEN COALESCE(
      (
        SELECT l.organizador_id
        FROM public.liga_jornadas lj
        INNER JOIN public.ligas l ON l.id = lj.liga_id
        WHERE lj.id = NULLIF(trim(p_evento_id), '')::uuid
        LIMIT 1
      ),
      (
        SELECT l.organizador_id
        FROM public.ligas l
        WHERE l.id = NULLIF(trim(p_evento_id), '')::uuid
        LIMIT 1
      )
    )
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."riviera_participacion_expected_host_org"("p_tipo_evento" "text", "p_evento_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_participacion_expected_host_org"("p_tipo_evento" "text", "p_evento_id" "text") IS 'Club anfitrión esperado según evento padre (reta/americano/duelo/torneo/liga).';



CREATE OR REPLACE FUNCTION "public"."riviera_participacion_parent_exists"("p_tipo_evento" "text", "p_evento_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.riviera_participacion_expected_host_org(p_tipo_evento, p_evento_id) IS NOT NULL;
$$;


ALTER FUNCTION "public"."riviera_participacion_parent_exists"("p_tipo_evento" "text", "p_evento_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_participaciones_interno"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS SETOF "public"."jugador_participaciones"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH linked AS (
    SELECT p_jugador_id AS jugador_id
    UNION
    SELECT g.jugador_id
    FROM public.get_public_career_jugador_ids(p_jugador_id) AS g(jugador_id)
    UNION
    SELECT opa.local_jugador_id
    FROM public.organizer_player_access opa
    WHERE opa.is_active = true
      AND opa.grantee_organizer_id = p_organizador_id
      AND opa.local_jugador_id IS NOT NULL
      AND (
        opa.jugador_id = p_jugador_id
        OR opa.local_jugador_id = p_jugador_id
      )
  )
  SELECT
    jp.id,
    jp.jugador_id,
    jp.tipo_evento,
    jp.evento_id,
    jp.evento_nombre,
    jp.fecha,
    jp.pareja_con,
    jp.resultado,
    jp.sets_favor,
    jp.sets_contra,
    jp.puntos_obtenidos,
    CASE
      WHEN COALESCE(jp.metadata->>'organizador_id', '') <> '' THEN jp.metadata
      WHEN d.id IS NOT NULL THEN COALESCE(jp.metadata, '{}'::jsonb)
        || jsonb_build_object('organizador_id', d.organizador_id::text)
      WHEN t.id IS NOT NULL THEN COALESCE(jp.metadata, '{}'::jsonb)
        || jsonb_build_object('organizador_id', t.organizador_id::text)
      ELSE COALESCE(jp.metadata, '{}'::jsonb)
    END AS metadata,
    jp.created_at
  FROM public.jugador_participaciones jp
  INNER JOIN public.riviera_jugadores rj ON rj.id = jp.jugador_id
  INNER JOIN linked l ON l.jugador_id = jp.jugador_id
  LEFT JOIN public.duelos_2v2 d
    ON jp.tipo_evento = 'duelo_2v2'
   AND jp.evento_id::uuid = d.id
  LEFT JOIN public.torneo_express t
    ON jp.tipo_evento = 'torneo_express'
   AND jp.evento_id::uuid = t.id
  WHERE rj.estado = 'activo'
    AND (
      COALESCE(jp.metadata->>'organizador_id', '') = p_organizador_id::text
      OR (
        COALESCE(jp.metadata->>'organizador_id', '') = ''
        AND rj.organizador_id = p_organizador_id
      )
    )
    AND NOT public.is_jugador_participacion_excluded(
      jp.jugador_id,
      jp.tipo_evento::text,
      jp.evento_id
    )
  ORDER BY jp.fecha DESC NULLS LAST, jp.created_at DESC NULLS LAST
  LIMIT GREATEST(COALESCE(p_limit, 100), 1);
$$;


ALTER FUNCTION "public"."riviera_participaciones_interno"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_participaciones_interno"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_limit" integer) IS 'Participaciones en el club anfitrión: perfiles locales + metadata.organizador_id (cedidos/importados).';



CREATE OR REPLACE FUNCTION "public"."riviera_participaciones_mensual_detalle_public"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_year" integer, "p_month" integer) RETURNS TABLE("participacion_id" "uuid", "fecha" "date", "evento_nombre" "text", "tipo_evento" "text", "resultado" "text", "puntos_obtenidos" integer, "club_name" "text", "lugar" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Misma función interna que la RPC de ranking -- por construcción,
  -- COUNT(*) y SUM(puntos_obtenidos) de este resultado SIEMPRE coinciden
  -- exactamente con total_participaciones/puntos_mes de ese jugador en
  -- riviera_ranking_participaciones_mensual_public para el mismo mes.
  SELECT
    c.participacion_id,
    c.fecha,
    c.evento_nombre,
    c.tipo_evento,
    c.resultado,
    c.puntos_obtenidos,
    -- Whitelist explícita: solo club_name/lugar de metadata, nunca el jsonb
    -- completo (evita exponer cualquier campo interno futuro sin revisar).
    c.metadata->>'club_name' AS club_name,
    c.metadata->>'lugar' AS lugar
  FROM public._riviera_participaciones_canonicas_mensual(p_organizador_id, p_year, p_month) c
  WHERE c.jugador_id = p_jugador_id
  ORDER BY c.fecha DESC, c.created_at DESC;
$$;


ALTER FUNCTION "public"."riviera_participaciones_mensual_detalle_public"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_year" integer, "p_month" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_participaciones_mensual_detalle_public"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_year" integer, "p_month" integer) IS 'Detalle cronológico público de UN jugador en un mes para "Ranking -> Participaciones" (2026-08-08). Consume la MISMA función interna que la RPC de ranking agregado -- garantiza la invariante total_participaciones=COUNT(detalle) y puntos_mes=SUM(detalle). Whitelist de columnas, sin PII, sin metadata completo.';



CREATE OR REPLACE FUNCTION "public"."riviera_public_club_label"("p_names" "text"[], "p_organizer_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_name text;
  v_org uuid;
BEGIN
  BEGIN
    v_org := NULLIF(btrim(COALESCE(p_organizer_id, '')), '')::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      v_org := NULL;
  END;

  IF v_org IS NOT NULL THEN
    v_name := NULLIF(btrim(public.get_organizador_display_name(v_org)), '');
    IF v_name IS NOT NULL
       AND lower(v_name) <> 'club'
       AND lower(v_name) <> 'club deportivo riviera' THEN
      RETURN v_name;
    END IF;
  END IF;

  SELECT btrim(candidate)
  INTO v_name
  FROM unnest(COALESCE(p_names, ARRAY[]::text[])) AS candidate
  WHERE btrim(COALESCE(candidate, '')) <> ''
    AND lower(btrim(candidate)) NOT IN ('club', 'club deportivo riviera')
  LIMIT 1;

  RETURN v_name;
END;
$$;


ALTER FUNCTION "public"."riviera_public_club_label"("p_names" "text"[], "p_organizer_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_public_event_legacy_player_identity"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) RETURNS TABLE("legacy_player_id" "uuid", "riviera_jugador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "rating" numeric, "nivel" "text", "categoria" "text", "mano_dominante" "text", "en_cancha" "text", "pais_codigo" "text", "edad" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (
    SELECT DISTINCT unnest(p_legacy_player_ids) AS lid
  ),
  local AS (
    SELECT DISTINCT ON (i.lid)
      i.lid,
      rj.id AS rj_id,
      rj.nombre AS local_nombre,
      rj.slug AS local_slug,
      rj.foto_url AS local_foto,
      COALESCE(rj.rating, 3)::numeric AS local_rating,
      COALESCE(rj.rating_partidos, 0) AS local_partidos,
      rj.nivel::text AS local_nivel,
      rj.categoria AS local_categoria,
      rj.mano_dominante AS local_mano,
      rj.en_cancha AS local_en_cancha,
      rj.pais_codigo::text AS local_pais,
      rj.edad AS local_edad
    FROM ids i
    LEFT JOIN public.riviera_jugadores rj
      ON rj.estado = 'activo'
      AND rj.organizador_id = p_organizador_id
      AND (rj.legacy_player_id = i.lid OR rj.id = i.lid)
    ORDER BY i.lid, COALESCE(rj.rating_partidos, 0) DESC NULLS LAST
  ),
  access AS (
    SELECT DISTINCT ON (lid)
      lid,
      source_id
    FROM (
      SELECT
        i.lid,
        opa.jugador_id AS source_id,
        opa.updated_at
      FROM ids i
      LEFT JOIN local l ON l.lid = i.lid
      JOIN public.organizer_player_access opa
        ON opa.grantee_organizer_id = p_organizador_id
        AND opa.is_active = true
        AND (
          (l.rj_id IS NOT NULL AND opa.local_jugador_id = l.rj_id)
          OR (l.rj_id IS NOT NULL AND opa.jugador_id = l.rj_id)
        )
      UNION ALL
      SELECT
        i.lid,
        opa.jugador_id AS source_id,
        opa.updated_at
      FROM ids i
      JOIN public.organizer_player_access opa
        ON opa.grantee_organizer_id = p_organizador_id
        AND opa.is_active = true
      JOIN public.riviera_jugadores src_match
        ON src_match.id = opa.jugador_id
        AND src_match.estado = 'activo'
        AND src_match.legacy_player_id = i.lid
    ) grants
    ORDER BY lid, updated_at DESC NULLS LAST
  ),
  source AS (
    SELECT
      a.lid,
      src.id AS source_rj_id,
      src.nombre AS source_nombre,
      src.slug AS source_slug,
      src.foto_url AS source_foto,
      COALESCE(src.rating, 3)::numeric AS source_rating,
      COALESCE(src.rating_partidos, 0) AS source_partidos,
      src.nivel::text AS source_nivel,
      src.categoria AS source_categoria,
      src.mano_dominante AS source_mano,
      src.en_cancha AS source_en_cancha,
      src.pais_codigo::text AS source_pais,
      src.edad AS source_edad
    FROM access a
    JOIN public.riviera_jugadores src
      ON src.id = a.source_id
      AND src.estado = 'activo'
  ),
  canon AS (
    SELECT DISTINCT ON (i.lid)
      i.lid,
      rj.id AS canon_rj_id,
      rj.nombre AS canon_nombre,
      rj.slug AS canon_slug,
      rj.foto_url AS canon_foto,
      COALESCE(rj.rating, 3)::numeric AS canon_rating,
      COALESCE(rj.rating_partidos, 0) AS canon_partidos,
      rj.nivel::text AS canon_nivel,
      rj.categoria AS canon_categoria,
      rj.mano_dominante AS canon_mano,
      rj.en_cancha AS canon_en_cancha,
      rj.pais_codigo::text AS canon_pais,
      rj.edad AS canon_edad
    FROM ids i
    JOIN public.riviera_jugadores rj
      ON rj.estado = 'activo'
      AND rj.legacy_player_id = i.lid
    ORDER BY
      i.lid,
      COALESCE(rj.rating_partidos, 0) DESC NULLS LAST,
      CASE WHEN COALESCE(rj.rating, 3) = 3 THEN 1 ELSE 0 END,
      CASE WHEN rj.organizador_id = p_organizador_id THEN 1 ELSE 0 END DESC,
      COALESCE(rj.rating, 3) DESC
  )
  SELECT
    i.lid AS legacy_player_id,
    COALESCE(l.rj_id, s.source_rj_id, c.canon_rj_id) AS riviera_jugador_id,
    COALESCE(l.local_nombre, s.source_nombre, c.canon_nombre) AS nombre,
    COALESCE(l.local_slug, s.source_slug, c.canon_slug) AS slug,
    COALESCE(l.local_foto, s.source_foto, c.canon_foto) AS foto_url,
    CASE
      WHEN s.source_partidos > 0 AND s.source_rating <> 3 THEN s.source_rating
      WHEN c.canon_partidos > 0 AND c.canon_rating <> 3 THEN c.canon_rating
      WHEN l.local_partidos > 0 AND l.local_rating <> 3 THEN l.local_rating
      WHEN s.source_rating IS NOT NULL AND s.source_rating <> 3 THEN s.source_rating
      WHEN c.canon_rating IS NOT NULL AND c.canon_rating <> 3 THEN c.canon_rating
      ELSE COALESCE(l.local_rating, s.source_rating, c.canon_rating, 3)
    END AS rating,
    COALESCE(l.local_nivel, s.source_nivel, c.canon_nivel) AS nivel,
    COALESCE(l.local_categoria, s.source_categoria, c.canon_categoria) AS categoria,
    COALESCE(l.local_mano, s.source_mano, c.canon_mano) AS mano_dominante,
    COALESCE(l.local_en_cancha, s.source_en_cancha, c.canon_en_cancha) AS en_cancha,
    COALESCE(l.local_pais, s.source_pais, c.canon_pais) AS pais_codigo,
    COALESCE(l.local_edad, s.source_edad, c.canon_edad)::integer AS edad
  FROM ids i
  LEFT JOIN local l ON l.lid = i.lid
  LEFT JOIN source s ON s.lid = i.lid
  LEFT JOIN canon c ON c.lid = i.lid;
$$;


ALTER FUNCTION "public"."riviera_public_event_legacy_player_identity"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_public_event_legacy_player_identity"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) IS 'Vista pública anon: identidad (Drive/Revés, país, mano, edad) por legacy players.id, incluye cedidos.';



CREATE OR REPLACE FUNCTION "public"."riviera_public_event_legacy_player_profiles"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) RETURNS TABLE("legacy_player_id" "uuid", "foto_url" "text", "rating" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (
    SELECT DISTINCT unnest(p_legacy_player_ids) AS lid
  ),
  local AS (
    SELECT DISTINCT ON (i.lid)
      i.lid,
      rj.id AS rj_id,
      rj.foto_url AS local_foto,
      COALESCE(rj.rating, 3)::numeric AS local_rating,
      COALESCE(rj.rating_partidos, 0) AS local_partidos
    FROM ids i
    LEFT JOIN public.riviera_jugadores rj
      ON rj.estado = 'activo'
      AND rj.organizador_id = p_organizador_id
      AND (rj.legacy_player_id = i.lid OR rj.id = i.lid)
    ORDER BY i.lid, COALESCE(rj.rating_partidos, 0) DESC NULLS LAST
  ),
  access AS (
    SELECT DISTINCT ON (lid)
      lid,
      source_id
    FROM (
      SELECT
        i.lid,
        opa.jugador_id AS source_id,
        opa.updated_at
      FROM ids i
      LEFT JOIN local l ON l.lid = i.lid
      JOIN public.organizer_player_access opa
        ON opa.grantee_organizer_id = p_organizador_id
        AND opa.is_active = true
        AND (
          (l.rj_id IS NOT NULL AND opa.local_jugador_id = l.rj_id)
          OR (l.rj_id IS NOT NULL AND opa.jugador_id = l.rj_id)
        )
      UNION ALL
      SELECT
        i.lid,
        opa.jugador_id AS source_id,
        opa.updated_at
      FROM ids i
      JOIN public.organizer_player_access opa
        ON opa.grantee_organizer_id = p_organizador_id
        AND opa.is_active = true
      JOIN public.riviera_jugadores src_match
        ON src_match.id = opa.jugador_id
        AND src_match.estado = 'activo'
        AND src_match.legacy_player_id = i.lid
    ) grants
    ORDER BY lid, updated_at DESC NULLS LAST
  ),
  source AS (
    SELECT
      a.lid,
      src.foto_url AS source_foto,
      COALESCE(src.rating, 3)::numeric AS source_rating,
      COALESCE(src.rating_partidos, 0) AS source_partidos
    FROM access a
    JOIN public.riviera_jugadores src
      ON src.id = a.source_id
      AND src.estado = 'activo'
  ),
  canon AS (
    SELECT DISTINCT ON (i.lid)
      i.lid,
      rj.foto_url AS canon_foto,
      COALESCE(rj.rating, 3)::numeric AS canon_rating,
      COALESCE(rj.rating_partidos, 0) AS canon_partidos
    FROM ids i
    JOIN public.riviera_jugadores rj
      ON rj.estado = 'activo'
      AND rj.legacy_player_id = i.lid
    ORDER BY
      i.lid,
      COALESCE(rj.rating_partidos, 0) DESC NULLS LAST,
      CASE WHEN COALESCE(rj.rating, 3) = 3 THEN 1 ELSE 0 END,
      CASE WHEN rj.organizador_id = p_organizador_id THEN 1 ELSE 0 END DESC,
      COALESCE(rj.rating, 3) DESC
  )
  SELECT
    i.lid AS legacy_player_id,
    COALESCE(l.local_foto, s.source_foto, c.canon_foto) AS foto_url,
    CASE
      WHEN s.source_partidos > 0 AND s.source_rating <> 3 THEN s.source_rating
      WHEN c.canon_partidos > 0 AND c.canon_rating <> 3 THEN c.canon_rating
      WHEN l.local_partidos > 0 AND l.local_rating <> 3 THEN l.local_rating
      WHEN s.source_rating IS NOT NULL AND s.source_rating <> 3 THEN s.source_rating
      WHEN c.canon_rating IS NOT NULL AND c.canon_rating <> 3 THEN c.canon_rating
      ELSE COALESCE(l.local_rating, s.source_rating, c.canon_rating, 3)
    END AS rating
  FROM ids i
  LEFT JOIN local l ON l.lid = i.lid
  LEFT JOIN source s ON s.lid = i.lid
  LEFT JOIN canon c ON c.lid = i.lid;
$$;


ALTER FUNCTION "public"."riviera_public_event_legacy_player_profiles"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_public_event_legacy_player_profiles"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) IS 'Vista pública anon: foto y rating por legacy players.id, incluye cedidos (organizer_player_access).';



CREATE OR REPLACE FUNCTION "public"."riviera_public_event_player_names"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) RETURNS TABLE("legacy_player_id" "uuid", "nombre" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (
    SELECT DISTINCT unnest(p_legacy_player_ids) AS lid
  )
  SELECT DISTINCT ON (i.lid)
    i.lid AS legacy_player_id,
    NULLIF(btrim(rj.nombre), '') AS nombre
  FROM ids i
  JOIN public.riviera_jugadores rj
    ON rj.estado = 'activo'
   AND rj.organizador_id = p_organizador_id
   AND (rj.legacy_player_id = i.lid OR rj.id = i.lid)
  ORDER BY i.lid, rj.updated_at DESC NULLS LAST;
$$;


ALTER FUNCTION "public"."riviera_public_event_player_names"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_public_event_player_names"("p_organizador_id" "uuid", "p_legacy_player_ids" "uuid"[]) IS 'Vista pública: nombre vigente de la ficha para jugadores de un evento publicado.';



CREATE OR REPLACE FUNCTION "public"."riviera_public_liga_jugador_profiles"("p_organizador_id" "uuid", "p_liga_jugador_ids" "uuid"[]) RETURNS TABLE("liga_jugador_id" "uuid", "foto_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (
    SELECT DISTINCT unnest(p_liga_jugador_ids) AS lid
  ),
  linked AS (
    SELECT DISTINCT ON (i.lid)
      i.lid,
      rj.foto_url
    FROM ids i
    JOIN public.riviera_jugadores rj
      ON rj.organizador_id = p_organizador_id
      AND rj.estado = 'activo'
      AND rj.legacy_liga_jugador_id = i.lid
      AND rj.foto_url IS NOT NULL
      AND trim(rj.foto_url) <> ''
    ORDER BY i.lid, COALESCE(rj.rating_partidos, 0) DESC NULLS LAST
  ),
  by_name AS (
    SELECT DISTINCT ON (i.lid)
      i.lid,
      rj.foto_url
    FROM ids i
    JOIN public.liga_jugadores lj ON lj.id = i.lid
    JOIN public.riviera_jugadores rj
      ON rj.organizador_id = p_organizador_id
      AND rj.estado = 'activo'
      AND lower(trim(rj.nombre)) = lower(trim(lj.nombre))
      AND rj.foto_url IS NOT NULL
      AND trim(rj.foto_url) <> ''
    LEFT JOIN linked l ON l.lid = i.lid
    WHERE l.lid IS NULL
    ORDER BY i.lid, COALESCE(rj.rating_partidos, 0) DESC NULLS LAST
  )
  SELECT lid AS liga_jugador_id, foto_url FROM linked
  UNION ALL
  SELECT lid AS liga_jugador_id, foto_url FROM by_name;
$$;


ALTER FUNCTION "public"."riviera_public_liga_jugador_profiles"("p_organizador_id" "uuid", "p_liga_jugador_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_public_liga_jugador_profiles"("p_organizador_id" "uuid", "p_liga_jugador_ids" "uuid"[]) IS 'Vista pública anon: foto_url por liga_jugadores.id (enlace legacy o nombre).';



CREATE OR REPLACE FUNCTION "public"."riviera_public_reta_event_players"("p_organizador_id" "uuid", "p_tournament_id" "uuid") RETURNS TABLE("jugador_id" "uuid", "legacy_player_id" "uuid", "nombre" "text", "foto_url" "text", "rating" numeric, "pair_id" "uuid", "pair_slot" integer, "canonical_legacy_player_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT ON (jp.jugador_id)
    jp.jugador_id,
    rj.legacy_player_id,
    rj.nombre,
    rj.foto_url,
    COALESCE(rj.rating, 3)::numeric AS rating,
    NULLIF(jp.metadata->>'pair_id', '')::uuid AS pair_id,
    NULLIF(jp.metadata->>'pair_slot', '')::integer AS pair_slot,
    NULLIF(jp.metadata->>'canonical_legacy_player_id', '')::uuid
      AS canonical_legacy_player_id
  FROM public.jugador_participaciones jp
  INNER JOIN public.riviera_jugadores rj
    ON rj.id = jp.jugador_id
  WHERE jp.evento_id = p_tournament_id
    AND jp.tipo_evento = 'reta'
    AND rj.organizador_id = p_organizador_id
    AND rj.estado = 'activo'
  ORDER BY jp.jugador_id, jp.fecha DESC NULLS LAST, jp.created_at DESC NULLS LAST;
$$;


ALTER FUNCTION "public"."riviera_public_reta_event_players"("p_organizador_id" "uuid", "p_tournament_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_public_reta_event_players"("p_organizador_id" "uuid", "p_tournament_id" "uuid") IS 'Vista pública anon: jugadores que participaron en una reta (por riviera_jugador_id).';



CREATE OR REPLACE FUNCTION "public"."riviera_public_riviera_jugador_profiles"("p_organizador_id" "uuid", "p_jugador_ids" "uuid"[]) RETURNS TABLE("jugador_id" "uuid", "foto_url" "text", "rating" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ids AS (
    SELECT DISTINCT unnest(p_jugador_ids) AS jid
  ),
  local AS (
    SELECT
      i.jid,
      rj.id AS rj_id,
      rj.legacy_player_id,
      rj.foto_url AS local_foto,
      COALESCE(rj.rating, 3)::numeric AS local_rating
    FROM ids i
    LEFT JOIN public.riviera_jugadores rj
      ON rj.id = i.jid
      AND rj.estado = 'activo'
  ),
  lookup AS (
    SELECT
      jid,
      COALESCE(legacy_player_id, rj_id, jid) AS lookup_id,
      local_foto,
      local_rating
    FROM local
  ),
  distinct_lookups AS (
    SELECT DISTINCT lookup_id FROM lookup
  ),
  canon AS (
    SELECT p.legacy_player_id, p.foto_url, p.rating
    FROM distinct_lookups dl
    CROSS JOIN LATERAL (
      SELECT *
      FROM public.riviera_public_event_legacy_player_profiles(
        p_organizador_id,
        ARRAY[dl.lookup_id]
      )
    ) p
  )
  SELECT
    l.jid AS jugador_id,
    COALESCE(l.local_foto, c.foto_url) AS foto_url,
    COALESCE(c.rating, l.local_rating, 3)::numeric AS rating
  FROM lookup l
  LEFT JOIN canon c ON c.legacy_player_id = l.lookup_id;
$$;


ALTER FUNCTION "public"."riviera_public_riviera_jugador_profiles"("p_organizador_id" "uuid", "p_jugador_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_public_riviera_jugador_profiles"("p_organizador_id" "uuid", "p_jugador_ids" "uuid"[]) IS 'Vista pública anon: foto y rating canónico por riviera_jugadores.id (duelos, eventos).';



CREATE OR REPLACE FUNCTION "public"."riviera_ranking_interno_por_organizador"("p_organizador_id" "uuid", "p_categoria" "text" DEFAULT NULL::"text", "p_genero" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "organizador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "categoria" "text", "genero" "text", "pais_codigo" "text", "club" "text", "estado" "text", "visible_publico" boolean, "suma_ranking" boolean, "rating" numeric, "rating_partidos" integer, "rating_fiabilidad" numeric, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "puntos_totales" integer, "total_partidos" integer, "victorias" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    rj.id,
    rj.organizador_id,
    rj.nombre,
    rj.slug,
    rj.foto_url,
    rj.categoria,
    rj.genero,
    rj.pais_codigo,
    rj.club,
    rj.estado,
    rj.visible_publico,
    rj.suma_ranking,
    rj.rating,
    rj.rating_partidos,
    rj.rating_fiabilidad,
    rj.created_at,
    rj.updated_at,
    COALESCE(js.puntos_totales, 0)::integer,
    COALESCE(js.total_partidos, 0)::integer,
    COALESCE(js.victorias, 0)::integer
  FROM public.riviera_jugadores rj
  LEFT JOIN public.jugador_stats js ON js.jugador_id = rj.id
  WHERE rj.organizador_id = p_organizador_id
    AND rj.estado = 'activo'
    AND (p_categoria IS NULL OR rj.categoria = p_categoria)
    AND (
      p_genero IS NULL
      OR (upper(p_genero) IN ('F', 'FEMENIL') AND rj.genero = 'F')
      OR (
        upper(p_genero) IN ('M', 'VARONIL')
        AND (rj.genero = 'M' OR rj.genero IS NULL)
      )
    )
  ORDER BY puntos_totales DESC, rj.nombre ASC;
$$;


ALTER FUNCTION "public"."riviera_ranking_interno_por_organizador"("p_organizador_id" "uuid", "p_categoria" "text", "p_genero" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_ranking_participaciones_mensual_public"("p_organizador_id" "uuid", "p_year" integer, "p_month" integer, "p_categoria" "text" DEFAULT NULL::"text", "p_genero" "text" DEFAULT NULL::"text") RETURNS TABLE("jugador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "riviera_id" "text", "categoria" "text", "genero" "text", "total_participaciones" integer, "puntos_mes" integer, "ultima_participacion" "date", "posicion_competitiva" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH canon AS (
    SELECT *
    FROM public._riviera_participaciones_canonicas_mensual(p_organizador_id, p_year, p_month)
  ),
  agregado AS (
    -- COUNT/SUM se calculan DESPUÉS de la deduplicación canónica (canon ya
    -- viene deduplicada por la función interna) -- nunca sobre filas crudas.
    SELECT
      c.jugador_id,
      COUNT(*)::integer AS total_participaciones,
      SUM(c.puntos_obtenidos)::integer AS puntos_mes,
      MAX(c.fecha) AS ultima_participacion
    FROM canon c
    GROUP BY c.jugador_id
  ),
  -- riviera_jugadores NO tiene columna riviera_id (era una suposición
  -- incorrecta -- error real de producción 2026-08-09: 42703 column
  -- rj.riviera_id does not exist). El Riviera ID vive en
  -- riviera_official_player_identity.riviera_id, resuelto vía
  -- riviera_official_player_profile_link (perfil local -> official_player_key)
  -- o directamente cuando el jugador ES el canonical_riviera_jugador_id --
  -- mismo patrón dual-path ya usado por la RPC pública existente
  -- get_public_riviera_ids_for_jugadores (supabase/riviera-public-ranking-read.sql).
  -- Se reimplementa aquí en vez de LLAMAR a esa RPC porque esa RPC exige
  -- rj.estado = 'activo', lo cual apagaría el Riviera ID de un jugador
  -- archivado que sigue apareciendo en un mes histórico -- decisión de
  -- producto cerrada 2026-08-08: esta pantalla nunca filtra por estado.
  -- Acotado a los jugadores de "agregado" (ya filtrados por organizador+mes+
  -- allowlist) -- una sola pasada, sin N+1.
  riviera_ids AS (
    SELECT DISTINCT ON (jugador_id) jugador_id, riviera_id
    FROM (
      SELECT
        pl.riviera_jugador_id AS jugador_id,
        ident.riviera_id::text AS riviera_id
      FROM public.riviera_official_player_profile_link pl
      JOIN public.riviera_official_player_identity ident
        ON ident.official_player_key = pl.official_player_key
      WHERE ident.riviera_id IS NOT NULL
        AND pl.riviera_jugador_id IN (SELECT jugador_id FROM agregado)
      UNION ALL
      SELECT
        ident.canonical_riviera_jugador_id AS jugador_id,
        ident.riviera_id::text AS riviera_id
      FROM public.riviera_official_player_identity ident
      WHERE ident.riviera_id IS NOT NULL
        AND ident.canonical_riviera_jugador_id IN (SELECT jugador_id FROM agregado)
    ) merged
    ORDER BY jugador_id, riviera_id
  ),
  enriquecido AS (
    -- Solo entran jugadores con >= 1 participación canónica (INNER JOIN, no
    -- LEFT JOIN contra el roster completo) -- la clasificación pública nunca
    -- muestra "0 participaciones". Sin filtro de estado: un jugador
    -- archivado después de jugar sigue apareciendo. riviera_ids es LEFT JOIN
    -- a propósito -- un jugador sin identidad oficial vinculada todavía debe
    -- seguir apareciendo en el ranking, solo sin badge de Riviera ID.
    SELECT
      a.jugador_id,
      rj.nombre,
      rj.slug,
      rj.foto_url,
      ri.riviera_id,
      rj.categoria,
      rj.genero,
      a.total_participaciones,
      a.puntos_mes,
      a.ultima_participacion
    FROM agregado a
    INNER JOIN public.riviera_jugadores rj ON rj.id = a.jugador_id
    LEFT JOIN riviera_ids ri ON ri.jugador_id = a.jugador_id
    WHERE (p_categoria IS NULL OR rj.categoria = p_categoria)
      AND (
        p_genero IS NULL
        OR (upper(p_genero) IN ('F', 'FEMENIL') AND rj.genero = 'F')
        OR (
          upper(p_genero) IN ('M', 'VARONIL')
          AND (rj.genero = 'M' OR rj.genero IS NULL)
        )
      )
  )
  SELECT
    jugador_id,
    nombre,
    slug,
    foto_url,
    riviera_id,
    categoria,
    genero,
    total_participaciones,
    puntos_mes,
    ultima_participacion,
    -- Posición COMPETITIVA real: empates deportivos comparten el mismo
    -- número. Nunca se usa nombre/jugador_id para romper este empate.
    RANK() OVER (ORDER BY total_participaciones DESC, puntos_mes DESC)::integer
      AS posicion_competitiva
  FROM enriquecido
  -- Orden de PRESENTACIÓN (para que el render no salte entre refrescos) --
  -- nombre/jugador_id son desempate puramente visual, nunca deportivo.
  ORDER BY total_participaciones DESC, puntos_mes DESC, nombre ASC, jugador_id ASC;
$$;


ALTER FUNCTION "public"."riviera_ranking_participaciones_mensual_public"("p_organizador_id" "uuid", "p_year" integer, "p_month" integer, "p_categoria" "text", "p_genero" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_ranking_participaciones_mensual_public"("p_organizador_id" "uuid", "p_year" integer, "p_month" integer, "p_categoria" "text", "p_genero" "text") IS 'Clasificación pública mensual de "Ranking -> Participaciones" (2026-08-08). Fuente: _riviera_participaciones_canonicas_mensual. posicion_competitiva = RANK() real (empates comparten posición); el ORDER BY final es solo orden de presentación estable, nunca decide un empate. Sin PII, sin metadata completo.';



CREATE OR REPLACE FUNCTION "public"."riviera_ranking_posicion_jugador_por_organizador"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_categoria" "text" DEFAULT NULL::"text", "p_genero" "text" DEFAULT 'M'::"text") RETURNS TABLE("jugador_id" "uuid", "posicion" integer, "puntos" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH scored AS (
    SELECT *
    FROM public._riviera_ranking_interno_scored_roster(
      p_organizador_id,
      p_categoria,
      p_genero
    )
  ),
  -- Deep-link puede traer id local O id origen del grant.
  resolved AS (
    SELECT x.roster_id
    FROM (
      SELECT s.jugador_id AS roster_id
      FROM scored s
      WHERE s.jugador_id = p_jugador_id
      UNION
      SELECT opa.local_jugador_id
      FROM public.organizer_player_access opa
      JOIN scored s ON s.jugador_id = opa.local_jugador_id
      WHERE opa.grantee_organizer_id = p_organizador_id
        AND opa.is_active = true
        AND opa.jugador_id = p_jugador_id
        AND opa.local_jugador_id IS NOT NULL
      UNION
      SELECT opa.jugador_id
      FROM public.organizer_player_access opa
      JOIN scored s ON s.jugador_id = opa.jugador_id
      WHERE opa.grantee_organizer_id = p_organizador_id
        AND opa.is_active = true
        AND opa.local_jugador_id = p_jugador_id
    ) x
    LIMIT 1
  ),
  ranked AS (
    SELECT
      s.jugador_id,
      s.puntos,
      RANK() OVER (ORDER BY s.puntos DESC)::integer AS posicion
    FROM scored s
  )
  SELECT
    r.jugador_id,
    r.posicion,
    r.puntos
  FROM ranked r
  JOIN resolved x ON x.roster_id = r.jugador_id;
$$;


ALTER FUNCTION "public"."riviera_ranking_posicion_jugador_por_organizador"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_categoria" "text", "p_genero" "text") OWNER TO "postgres";


