CREATE OR REPLACE FUNCTION "public"."riviera_ranking_sitio_oficial_global"("p_categoria" "text" DEFAULT NULL::"text", "p_genero" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "organizador_id" "uuid", "nombre" "text", "slug" "text", "foto_url" "text", "categoria" "text", "genero" "text", "pais_codigo" "text", "club" "text", "estado" "text", "visible_publico" boolean, "suma_ranking" boolean, "rating" numeric, "rating_partidos" integer, "rating_fiabilidad" numeric, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "puntos_totales" integer, "total_partidos" integer, "victorias" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    v.id,
    v.organizador_id,
    v.nombre,
    v.slug,
    v.foto_url,
    v.categoria,
    v.genero,
    v.pais_codigo,
    v.club,
    v.estado,
    v.visible_publico,
    v.suma_ranking,
    v.rating,
    v.rating_partidos,
    v.rating_fiabilidad,
    v.created_at,
    v.updated_at,
    v.puntos_totales,
    v.total_partidos,
    v.victorias
  FROM public.riviera_jugadores_sitio_oficial v
  WHERE (p_categoria IS NULL OR v.categoria = p_categoria)
    AND (
      p_genero IS NULL
      OR (upper(p_genero) IN ('F', 'FEMENIL') AND v.genero = 'F')
      OR (
        upper(p_genero) IN ('M', 'VARONIL')
        AND (v.genero = 'M' OR v.genero IS NULL)
      )
    )
  ORDER BY v.puntos_totales DESC NULLS LAST, v.nombre ASC;
$$;


