CREATE OR REPLACE FUNCTION "public"."riviera_rating_canonico_para_jugador"("p_organizador_id" "uuid", "p_jugador_id" "uuid") RETURNS TABLE("rating" numeric, "rating_partidos" integer, "rating_fiabilidad" numeric, "source_jugador_id" "uuid", "local_jugador_id" "uuid", "owner_organizador_id" "uuid", "origen_puntos_totales" integer, "local_puntos_totales" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_source uuid;
  v_local uuid;
  v_canon record;
BEGIN
  IF p_jugador_id IS NULL THEN
    RAISE EXCEPTION 'jugador_id requerido'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public._assert_rating_rpc_organizador_caller(p_organizador_id);

  SELECT opa.jugador_id, opa.local_jugador_id
  INTO v_source, v_local
  FROM public.organizer_player_access opa
  WHERE opa.is_active = true
    AND opa.grantee_organizer_id = p_organizador_id
    AND (
      opa.jugador_id = p_jugador_id
      OR opa.local_jugador_id = p_jugador_id
    )
  ORDER BY opa.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_source IS NOT NULL THEN
    SELECT r.rating, r.rating_partidos, r.rating_fiabilidad
    INTO v_canon
    FROM public.riviera_jugadores r
    WHERE r.id = v_source
       OR (v_local IS NOT NULL AND r.id = v_local)
    ORDER BY r.rating_partidos DESC NULLS LAST, r.rating DESC NULLS LAST
    LIMIT 1;

    RETURN QUERY
    SELECT
      v_canon.rating,
      v_canon.rating_partidos,
      v_canon.rating_fiabilidad,
      v_source,
      COALESCE(v_local, p_jugador_id),
      src.organizador_id,
      COALESCE(src_stats.puntos_totales, 0)::integer,
      COALESCE(local_stats.puntos_totales, 0)::integer
    FROM public.riviera_jugadores src
    LEFT JOIN public.jugador_stats src_stats ON src_stats.jugador_id = v_source
    LEFT JOIN public.jugador_stats local_stats
      ON local_stats.jugador_id = COALESCE(v_local, p_jugador_id)
    WHERE src.id = v_source
    LIMIT 1;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    r.rating,
    r.rating_partidos,
    r.rating_fiabilidad,
    r.id,
    r.id,
    r.organizador_id,
    COALESCE(js.puntos_totales, 0)::integer,
    COALESCE(js.puntos_totales, 0)::integer
  FROM public.riviera_jugadores r
  LEFT JOIN public.jugador_stats js ON js.jugador_id = r.id
  WHERE r.id = p_jugador_id
    AND r.organizador_id = p_organizador_id
    AND r.estado = 'activo';
END;
$$;


ALTER FUNCTION "public"."riviera_rating_canonico_para_jugador"("p_organizador_id" "uuid", "p_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_rating_historial_unificado"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_limite" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "fecha" timestamp with time zone, "rating_antes" numeric, "rating_despues" numeric, "delta" numeric, "modo_juego" "text", "descripcion" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_source uuid;
  v_local uuid;
BEGIN
  IF p_jugador_id IS NULL THEN
    RAISE EXCEPTION 'jugador_id requerido'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public._assert_rating_rpc_organizador_caller(p_organizador_id);

  SELECT opa.jugador_id, opa.local_jugador_id
  INTO v_source, v_local
  FROM public.organizer_player_access opa
  WHERE opa.is_active = true
    AND opa.grantee_organizer_id = p_organizador_id
    AND (
      opa.jugador_id = p_jugador_id
      OR opa.local_jugador_id = p_jugador_id
    )
  ORDER BY opa.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_source IS NULL THEN
    IF NOT public.is_master_admin()
       AND auth.uid() IS DISTINCT FROM p_organizador_id THEN
      RAISE EXCEPTION 'No autorizado para historial de este jugador'
        USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.riviera_jugadores r
      WHERE r.id = p_jugador_id
        AND r.organizador_id = p_organizador_id
        AND r.estado = 'activo'
    ) THEN
      RETURN;
    END IF;

    v_source := p_jugador_id;
    v_local := p_jugador_id;
  END IF;

  RETURN QUERY
  SELECT
    rh.id,
    rh.fecha,
    rh.rating_antes,
    rh.rating_despues,
    rh.delta,
    rh.modo_juego,
    rh.descripcion
  FROM public.rating_historial rh
  WHERE rh.jugador_id = v_source
     OR (v_local IS NOT NULL AND rh.jugador_id = v_local)
  ORDER BY rh.fecha DESC
  LIMIT GREATEST(COALESCE(p_limite, 10), 1);
END;
$$;


ALTER FUNCTION "public"."riviera_rating_historial_unificado"("p_organizador_id" "uuid", "p_jugador_id" "uuid", "p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."riviera_repair_orphan_profile_links_high"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_detected integer := 0;
  v_repaired integer := 0;
  v_review integer := 0;
  v_low integer := 0;
  v_row record;
  v_link_id uuid;
  v_repaired_names text[] := '{}';
BEGIN
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo Admin Principal puede ejecutar la reparación de vínculos huérfanos';
  END IF;

  IF to_regprocedure('public._riviera_orphan_profile_audit()') IS NULL THEN
    RAISE EXCEPTION
      'Falta _riviera_orphan_profile_audit — ejecutar career-profile-link-integrity.sql primero';
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE confidence = 'REVIEW'),
    COUNT(*) FILTER (WHERE confidence = 'LOW')
  INTO v_detected, v_review, v_low
  FROM public._riviera_orphan_profile_audit();

  FOR v_row IN
    SELECT *
    FROM public._riviera_orphan_profile_audit()
    WHERE confidence = 'HIGH'
      AND candidate_official_player_key IS NOT NULL
      AND action_sugerida = 'LINK_TO_OFFICIAL'
  LOOP
    INSERT INTO public.riviera_official_player_profile_link (
      official_player_key,
      riviera_jugador_id,
      organizer_id,
      link_source,
      created_by
    )
    VALUES (
      v_row.candidate_official_player_key,
      v_row.orphan_jugador_id,
      v_row.orphan_organizador_id,
      'manual_admin',
      auth.uid()
    )
    ON CONFLICT (riviera_jugador_id) DO NOTHING
    RETURNING id INTO v_link_id;

    IF v_link_id IS NOT NULL THEN
      v_repaired := v_repaired + 1;
      v_repaired_names := array_append(
        v_repaired_names,
        v_row.orphan_nombre || ' → ' || COALESCE(v_row.candidate_riviera_id, '?')
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'detected_orphans', v_detected,
    'repaired', v_repaired,
    'left_review', v_review,
    'left_low', v_low,
    'repaired_players', v_repaired_names
  );
END;
$$;


ALTER FUNCTION "public"."riviera_repair_orphan_profile_links_high"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."riviera_repair_orphan_profile_links_high"() IS 'Crea profile_link para huérfanos HIGH (scoring estricto de career-profile-link-integrity). Idempotente.';



CREATE OR REPLACE FUNCTION "public"."riviera_resolve_event_organizador_ids"("p_duelo_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_torneo_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("evento_id" "uuid", "organizador_id" "uuid", "tipo_evento" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT d.id, d.organizador_id, 'duelo_2v2'::text
  FROM public.duelos_2v2 d
  WHERE cardinality(p_duelo_ids) > 0
    AND d.id = ANY(p_duelo_ids)
  UNION ALL
  SELECT t.id, t.organizador_id, 'torneo_express'::text
  FROM public.torneo_express t
  WHERE cardinality(p_torneo_ids) > 0
    AND t.id = ANY(p_torneo_ids);
$$;


