CREATE OR REPLACE FUNCTION "public"."save_coach_session_preparation"("p_session_id" "uuid", "p_focus" "text" DEFAULT NULL::"text", "p_notes_summary" "text" DEFAULT NULL::"text", "p_message_to_student" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_coach_id uuid;
  v_sess public.coach_sessions%ROWTYPE;
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_trimmed_focus text := NULLIF(btrim(COALESCE(p_focus, '')), '');
  v_trimmed_notes text := NULLIF(btrim(COALESCE(p_notes_summary, '')), '');
  v_trimmed_message text := NULLIF(btrim(COALESCE(p_message_to_student, '')), '');
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_sess
  FROM public.coach_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sesión de coaching no encontrada.');
  END IF;

  IF v_sess.status <> 'SCHEDULED' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Solo se puede preparar una clase en estado programada (SCHEDULED). Estado actual: ' || v_sess.status
    );
  END IF;

  v_coach_id := public.current_riviera_coach_id();
  IF (v_coach_id IS NULL OR v_sess.coach_id <> v_coach_id) AND NOT v_is_master THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No tienes autorización para preparar esta clase. Solo el entrenador asignado puede definir la preparación técnica.'
    );
  END IF;

  UPDATE public.coach_sessions
  SET
    focus = v_trimmed_focus,
    notes_summary = v_trimmed_notes,
    prep_message_to_student = v_trimmed_message,
    updated_at = now()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', v_sess.id,
    'focus', v_trimmed_focus,
    'notes_summary', v_trimmed_notes,
    'prep_message_to_student', v_trimmed_message,
    'message', 'Preparación guardada exitosamente.'
  );
END;
$$;


ALTER FUNCTION "public"."save_coach_session_preparation"("p_session_id" "uuid", "p_focus" "text", "p_notes_summary" "text", "p_message_to_student" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_coach_session_preparation"("p_session_id" "uuid", "p_focus" "text", "p_notes_summary" "text", "p_message_to_student" "text") IS 'Guarda tema, mensaje al alumno y notas privadas de una clase SCHEDULED. No descuenta saldo.';



CREATE OR REPLACE FUNCTION "public"."schedule_coach_class"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_student_id" "uuid", "p_starts_at" timestamp with time zone, "p_duration_minutes" integer DEFAULT 60, "p_court" "text" DEFAULT NULL::"text", "p_focus" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_rel record;
  v_membership record;
  v_bal record;
  v_existing_session record;
  v_session_id uuid;
  v_duration integer;
  v_ends_at timestamptz;
  v_scheduled_count integer;
  v_available_to_schedule integer;
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_trimmed_court text := NULLIF(btrim(COALESCE(p_court, '')), '');
  v_trimmed_focus text := NULLIF(btrim(COALESCE(p_focus, '')), '');
  v_trimmed_notes text := NULLIF(btrim(COALESCE(p_notes, '')), '');
  v_now timestamptz := now();
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  PERFORM public.check_student_only_restriction();

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo el club puede agendar clases.');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organizador_game_modes
    WHERE organizador_id = p_organizador_id AND coaching_enabled = true
  ) AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El club no tiene habilitado el módulo de Coaching.');
  END IF;

  IF p_starts_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La fecha y hora de inicio son requeridas.');
  END IF;

  v_duration := COALESCE(p_duration_minutes, 60);
  IF v_duration < 15 OR v_duration > 360 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La duración debe estar entre 15 y 360 minutos.');
  END IF;

  v_ends_at := p_starts_at + (v_duration || ' minutes')::interval;

  SELECT *
  INTO v_membership
  FROM public.coach_club_memberships
  WHERE organizador_id = p_organizador_id AND coach_id = p_coach_id;

  IF NOT FOUND OR v_membership.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El coach no tiene una membresía activa en este club.');
  END IF;

  SELECT *
  INTO v_rel
  FROM public.coach_player_relationships
  WHERE organizador_id = p_organizador_id
    AND coach_id = p_coach_id
    AND jugador_id = p_student_id
  ORDER BY (status = 'ACTIVE') DESC, created_at DESC
  LIMIT 1;

  IF NOT FOUND OR v_rel.status <> 'ACTIVE' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No existe una relación activa entre el coach y el alumno en este club.');
  END IF;

  IF v_trimmed_key IS NOT NULL THEN
    SELECT *
    INTO v_existing_session
    FROM public.coach_sessions
    WHERE idempotency_key = v_trimmed_key;

    IF FOUND THEN
      IF v_existing_session.organizador_id <> p_organizador_id
         OR v_existing_session.coach_id <> p_coach_id
         OR v_existing_session.jugador_id <> p_student_id
         OR v_existing_session.starts_at <> p_starts_at
         OR v_existing_session.duration_minutes <> v_duration THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de idempotencia: la clave ya fue utilizada con parámetros distintos.'
        );
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'idempotent', true,
        'session_id', v_existing_session.id,
        'starts_at', v_existing_session.starts_at,
        'ends_at', v_existing_session.ends_at,
        'duration_minutes', v_existing_session.duration_minutes,
        'court', v_existing_session.court,
        'message', 'Operación idempotente: la clase ya fue agendada previamente.'
      );
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('coach_schedule:' || p_coach_id::text)::bigint);
  PERFORM pg_advisory_xact_lock(hashtext('student_schedule:' || p_student_id::text)::bigint);
  IF v_trimmed_court IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('court_schedule:' || p_organizador_id::text || ':' || lower(v_trimmed_court))::bigint);
  END IF;

  SELECT id, balance_classes INTO v_bal
  FROM public.coach_player_class_balances
  WHERE relationship_id = v_rel.id
  FOR UPDATE;

  SELECT COUNT(*) INTO v_scheduled_count
  FROM public.coach_sessions
  WHERE relationship_id = v_rel.id
    AND status = 'SCHEDULED';

  v_available_to_schedule := COALESCE(v_bal.balance_classes, 0) - v_scheduled_count;

  IF v_available_to_schedule <= 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El alumno no cuenta con clases disponibles suficientes para agendar. Saldo contratado: ' || COALESCE(v_bal.balance_classes, 0) || ', clases ya reservadas pendientes: ' || v_scheduled_count || '. Asigna o abona más clases antes de agendar.'
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.coach_sessions
    WHERE coach_id = p_coach_id
      AND status = 'SCHEDULED'
      AND tstzrange(starts_at, ends_at) && tstzrange(p_starts_at, v_ends_at)
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El entrenador ya tiene otra clase agendada que se solapa con este horario.'
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.coach_sessions
    WHERE jugador_id = p_student_id
      AND status = 'SCHEDULED'
      AND tstzrange(starts_at, ends_at) && tstzrange(p_starts_at, v_ends_at)
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'El alumno ya tiene otra clase agendada que se solapa con este horario.'
    );
  END IF;

  IF v_trimmed_court IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.coach_sessions
      WHERE organizador_id = p_organizador_id
        AND lower(btrim(court)) = lower(v_trimmed_court)
        AND status = 'SCHEDULED'
        AND tstzrange(starts_at, ends_at) && tstzrange(p_starts_at, v_ends_at)
    ) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'La cancha "' || v_trimmed_court || '" ya está reservada para otra clase en este club durante ese horario.'
      );
    END IF;
  END IF;

  INSERT INTO public.coach_sessions (
    coach_id,
    relationship_id,
    organizador_id,
    jugador_id,
    starts_at,
    ends_at,
    duration_minutes,
    court,
    focus,
    notes_summary,
    status,
    worked_on,
    idempotency_key,
    created_at,
    updated_at
  )
  VALUES (
    p_coach_id,
    v_rel.id,
    p_organizador_id,
    p_student_id,
    p_starts_at,
    v_ends_at,
    v_duration,
    v_trimmed_court,
    v_trimmed_focus,
    v_trimmed_notes,
    'SCHEDULED',
    '{}',
    v_trimmed_key,
    v_now,
    v_now
  )
  RETURNING id INTO v_session_id;

  INSERT INTO public.coach_audit_log (
    actor_auth_user_id,
    action,
    entity_type,
    entity_id,
    payload,
    created_at
  )
  VALUES (
    v_caller,
    'CLASS_SCHEDULED',
    'coach_sessions',
    v_session_id,
    jsonb_build_object(
      'coach_id', p_coach_id,
      'student_id', p_student_id,
      'starts_at', p_starts_at,
      'ends_at', v_ends_at,
      'duration_minutes', v_duration,
      'court', v_trimmed_court,
      'remaining_reservable', (v_available_to_schedule - 1)
    ),
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'session_id', v_session_id,
    'starts_at', p_starts_at,
    'ends_at', v_ends_at,
    'duration_minutes', v_duration,
    'court', v_trimmed_court,
    'remaining_reservable', (v_available_to_schedule - 1),
    'message', 'Clase agendada exitosamente.'
  );
END;
$$;


ALTER FUNCTION "public"."schedule_coach_class"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_student_id" "uuid", "p_starts_at" timestamp with time zone, "p_duration_minutes" integer, "p_court" "text", "p_focus" "text", "p_notes" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_open_game_registration_capacity"("p_mode_type" "text", "p_entity_id" "uuid", "p_capacity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mode text;
  v_cfg public.tournament_open_registration%ROWTYPE;
  v_new_cap int;
  v_confirmed int;
  v_promoted int := 0;
  v_started boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Autenticación requerida';
  END IF;

  v_mode := public._assert_convocatoria_mode_allowed(p_mode_type);

  IF v_mode = 'duelo_2v2' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'capacity_locked',
      'message', 'El cupo de Duelo 2vs2 es fijo (4 jugadores).'
    );
  END IF;

  IF p_entity_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'entity_id_required');
  END IF;

  SELECT * INTO v_cfg
  FROM public.tournament_open_registration
  WHERE mode_type = v_mode AND entity_id = p_entity_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF public._open_reg_organizer_id(v_cfg.mode_type, v_cfg.entity_id) <> v_uid THEN
    RAISE EXCEPTION 'Sin permiso';
  END IF;

  SELECT coalesce(is_started, false) OR coalesce(is_finished, false)
    INTO v_started
  FROM public.tournaments WHERE id = v_cfg.entity_id;

  IF coalesce(v_started, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'tournament_started');
  END IF;

  IF v_cfg.status IN ('closed', 'cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'registration_closed');
  END IF;

  v_new_cap := coalesce(p_capacity, 0);
  IF v_new_cap < 2 OR v_new_cap > 512 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'invalid_capacity',
      'message', 'El cupo debe estar entre 2 y 512 jugadores.'
    );
  END IF;

  IF v_new_cap = v_cfg.capacity THEN
    SELECT count(*)::int INTO v_confirmed
    FROM public.tournament_open_registration_entries
    WHERE registration_id = v_cfg.id AND status = 'confirmed';

    RETURN jsonb_build_object(
      'ok', true,
      'capacity', v_cfg.capacity,
      'confirmed_count', v_confirmed,
      'spots_left', greatest(v_cfg.capacity - v_confirmed, 0),
      'promoted_count', 0,
      'registration_id', v_cfg.id,
      'mode_type', v_cfg.mode_type,
      'entity_id', v_cfg.entity_id
    );
  END IF;

  SELECT count(*)::int INTO v_confirmed
  FROM public.tournament_open_registration_entries
  WHERE registration_id = v_cfg.id AND status = 'confirmed';

  IF v_new_cap < v_confirmed THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'capacity_below_confirmed',
      'confirmed_count', v_confirmed,
      'requested_capacity', v_new_cap,
      'message', format(
        'Ya hay %s confirmados. Saca inscritos en «Administrar inscritos» antes de bajar el cupo a %s.',
        v_confirmed, v_new_cap
      )
    );
  END IF;

  UPDATE public.tournament_open_registration
  SET capacity = v_new_cap, updated_at = now()
  WHERE id = v_cfg.id
  RETURNING * INTO v_cfg;

  -- Promover waitlist FIFO con el helper unificado
  v_promoted := public._open_reg_auto_promote_waitlist(v_cfg.id);

  SELECT count(*)::int INTO v_confirmed
  FROM public.tournament_open_registration_entries
  WHERE registration_id = v_cfg.id AND status = 'confirmed';

  RETURN jsonb_build_object(
    'ok', true,
    'capacity', v_cfg.capacity,
    'confirmed_count', v_confirmed,
    'spots_left', greatest(v_cfg.capacity - v_confirmed, 0),
    'promoted_count', v_promoted,
    'registration_id', v_cfg.id,
    'mode_type', v_cfg.mode_type,
    'entity_id', v_cfg.entity_id
  );
END;
$$;


ALTER FUNCTION "public"."set_open_game_registration_capacity"("p_mode_type" "text", "p_entity_id" "uuid", "p_capacity" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_open_game_registration_capacity"("p_mode_type" "text", "p_entity_id" "uuid", "p_capacity" integer) IS 'Ajusta cupo de convocatoria (reta/americano). Rechaza duelo_2v2. No baja bajo confirmados; al subir promueve waitlist FIFO.';



CREATE OR REPLACE FUNCTION "public"."student_auth_has_password"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM auth.users
    WHERE id = p_user_id
      AND encrypted_password IS NOT NULL
      AND length(encrypted_password) > 0
  );
$$;


ALTER FUNCTION "public"."student_auth_has_password"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."student_auth_has_password"("p_user_id" "uuid") IS 'Indica si el usuario Auth ya definió contraseña. Solo service_role. No devuelve el secreto.';



CREATE OR REPLACE FUNCTION "public"."sustituir_jugador_liga_individual_rotativo"("p_liga_id" "uuid", "p_from_jugador_id" "uuid", "p_to_jugador_id" "uuid", "p_jornada_efectiva_id" "uuid", "p_motivo_categoria" "text", "p_motivo_detalle" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_liga record;
  v_insc record;
  v_jornada record;
  v_motivo text := NULLIF(btrim(COALESCE(p_motivo_categoria, '')), '');
  v_detalle text := NULLIF(btrim(COALESCE(p_motivo_detalle, '')), '');
  v_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_existing record;
  v_conflict_partidos integer;
  v_parejas_updated integer := 0;
  v_parejas_batch integer := 0;
  v_puntos_heredados integer;
  v_sust_id uuid;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF p_liga_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Liga no encontrada.');
  END IF;

  IF p_from_jugador_id IS NULL OR p_to_jugador_id IS NULL OR p_from_jugador_id = p_to_jugador_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Jugadores de origen y destino inválidos.');
  END IF;

  IF v_motivo IS NULL OR v_motivo NOT IN ('lesion', 'baja', 'ausencia', 'otro') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Motivo de sustitución inválido.');
  END IF;

  -- Candado de liga + permiso ANTES de cualquier lectura de sustituciones / idempotencia
  SELECT id, organizador_id, modalidad, estado
  INTO v_liga
  FROM public.ligas
  WHERE id = p_liga_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Liga no encontrada.');
  END IF;

  IF v_liga.organizador_id <> v_caller AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes permiso para sustituir jugadores en esta liga.');
  END IF;

  IF v_liga.modalidad IS DISTINCT FROM 'individual_rotativo' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La sustitución está disponible solo en liga individual con parejas rotativas.');
  END IF;

  IF v_liga.estado = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se puede sustituir en una liga finalizada.');
  END IF;

  -- Idempotencia solo tras validar permisos; nunca revela sustituciones ajenas
  IF v_key IS NOT NULL THEN
    SELECT *
    INTO v_existing
    FROM public.liga_sustituciones
    WHERE idempotency_key = v_key
    FOR UPDATE;

    IF FOUND THEN
      IF v_existing.liga_id IS DISTINCT FROM p_liga_id THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de inscripción o clave duplicada. Recarga e inténtalo de nuevo.'
        );
      END IF;

      IF v_existing.from_jugador_id IS DISTINCT FROM p_from_jugador_id
         OR v_existing.to_jugador_id IS DISTINCT FROM p_to_jugador_id
         OR v_existing.jornada_efectiva_id IS DISTINCT FROM p_jornada_efectiva_id THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de inscripción o clave duplicada. Recarga e inténtalo de nuevo.'
        );
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'idempotent', true,
        'sustitucion_id', v_existing.id,
        'puntos_heredados', v_existing.puntos_heredados,
        'jornada_efectiva_numero', v_existing.jornada_efectiva_numero
      );
    END IF;
  END IF;

  SELECT *
  INTO v_insc
  FROM public.liga_inscripciones
  WHERE liga_id = p_liga_id AND jugador_id = p_from_jugador_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El jugador saliente no está inscrito en esta liga.');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.liga_inscripciones
    WHERE liga_id = p_liga_id AND jugador_id = p_to_jugador_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El jugador entrante ya ocupa una plaza en esta liga.');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.liga_jugadores
    WHERE id = p_to_jugador_id
      AND organizador_id = v_liga.organizador_id
      AND estado = 'activo'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El jugador entrante no pertenece al registro activo del club.');
  END IF;

  SELECT id, liga_id, numero, estado
  INTO v_jornada
  FROM public.liga_jornadas
  WHERE id = p_jornada_efectiva_id AND liga_id = p_liga_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Jornada de ingreso no encontrada.');
  END IF;

  IF v_jornada.estado = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se puede sustituir desde una jornada ya finalizada.');
  END IF;

  -- Conflictos: partidos con resultado en jornadas >= ingreso donde aparece el saliente
  -- (no reescribe historial con marcador; corrige solo futuro sin resultado)
  SELECT count(*)::integer INTO v_conflict_partidos
  FROM public.liga_partidos p
  JOIN public.liga_jornadas j ON j.id = p.jornada_id
  JOIN public.liga_jornada_parejas pr
    ON pr.id IN (p.pareja1_id, p.pareja2_id)
  WHERE j.liga_id = p_liga_id
    AND j.numero >= v_jornada.numero
    AND (pr.jugador1_id = p_from_jugador_id OR pr.jugador2_id = p_from_jugador_id)
    AND (
      p.estado = 'completed'
      OR p.score_pareja1 IS NOT NULL
      OR p.score_pareja2 IS NOT NULL
      OR p.set_scores IS NOT NULL
    );

  IF v_conflict_partidos > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error',
      'Hay partidos con resultado desde esa jornada. Elige una jornada posterior sin marcadores o espera a resolver el conflicto.'
    );
  END IF;

  -- Continuidad de plaza: hereda el total actual de la plaza (sin duplicar plazas)
  v_puntos_heredados := GREATEST(0, COALESCE(v_insc.puntos, 0));

  -- Solo parejas futuras (>= jornada de ingreso); historial con resultado queda intacto
  UPDATE public.liga_jornada_parejas pr
  SET jugador1_id = p_to_jugador_id
  FROM public.liga_jornadas j
  WHERE pr.jornada_id = j.id
    AND j.liga_id = p_liga_id
    AND j.numero >= v_jornada.numero
    AND pr.jugador1_id = p_from_jugador_id;

  GET DIAGNOSTICS v_parejas_batch = ROW_COUNT;
  v_parejas_updated := v_parejas_updated + v_parejas_batch;

  UPDATE public.liga_jornada_parejas pr
  SET jugador2_id = p_to_jugador_id
  FROM public.liga_jornadas j
  WHERE pr.jornada_id = j.id
    AND j.liga_id = p_liga_id
    AND j.numero >= v_jornada.numero
    AND pr.jugador2_id = p_from_jugador_id;

  GET DIAGNOSTICS v_parejas_batch = ROW_COUNT;
  v_parejas_updated := v_parejas_updated + v_parejas_batch;

  UPDATE public.liga_inscripciones
  SET
    jugador_id = p_to_jugador_id,
    puntos_heredados = v_puntos_heredados,
    puntos = v_puntos_heredados,
    ingreso_jornada_numero = v_jornada.numero,
    puntos_ajuste_motivo = NULL,
    puntos_ajuste_at = NULL
  WHERE id = v_insc.id;

  INSERT INTO public.liga_sustituciones (
    liga_id,
    plaza_inscripcion_id,
    from_jugador_id,
    to_jugador_id,
    jornada_efectiva_id,
    jornada_efectiva_numero,
    puntos_heredados,
    motivo_categoria,
    motivo_detalle,
    actor_id,
    idempotency_key
  ) VALUES (
    p_liga_id,
    v_insc.id,
    p_from_jugador_id,
    p_to_jugador_id,
    v_jornada.id,
    v_jornada.numero,
    v_puntos_heredados,
    v_motivo,
    v_detalle,
    v_caller,
    v_key
  )
  RETURNING id INTO v_sust_id;

  RETURN jsonb_build_object(
    'ok', true,
    'sustitucion_id', v_sust_id,
    'plaza_inscripcion_id', v_insc.id,
    'puntos_heredados', v_puntos_heredados,
    'jornada_efectiva_numero', v_jornada.numero,
    'parejas_actualizadas', v_parejas_updated
  );
EXCEPTION
  WHEN unique_violation THEN
    -- Subtransacción completa revertida: si la clave ya existe con los mismos
    -- parámetros (carrera), devolver idempotente sin filtrar datos ajenos.
    IF v_key IS NOT NULL THEN
      SELECT *
      INTO v_existing
      FROM public.liga_sustituciones
      WHERE idempotency_key = v_key;

      IF FOUND
         AND v_existing.liga_id = p_liga_id
         AND v_existing.from_jugador_id = p_from_jugador_id
         AND v_existing.to_jugador_id = p_to_jugador_id
         AND v_existing.jornada_efectiva_id = p_jornada_efectiva_id
         AND (
           v_is_master
           OR EXISTS (
             SELECT 1 FROM public.ligas l
             WHERE l.id = v_existing.liga_id AND l.organizador_id = v_caller
           )
         ) THEN
        RETURN jsonb_build_object(
          'ok', true,
          'idempotent', true,
          'sustitucion_id', v_existing.id,
          'puntos_heredados', v_existing.puntos_heredados,
          'jornada_efectiva_numero', v_existing.jornada_efectiva_numero
        );
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Conflicto de inscripción o clave duplicada. Recarga e inténtalo de nuevo.'
    );
END;
$$;


ALTER FUNCTION "public"."sustituir_jugador_liga_individual_rotativo"("p_liga_id" "uuid", "p_from_jugador_id" "uuid", "p_to_jugador_id" "uuid", "p_jornada_efectiva_id" "uuid", "p_motivo_categoria" "text", "p_motivo_detalle" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_granted_locals_from_source"("p_source_jugador_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_source public.riviera_jugadores%ROWTYPE;
  v_access public.organizer_player_access%ROWTYPE;
  v_updated int := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  SELECT *
  INTO v_source
  FROM public.riviera_jugadores rj
  WHERE rj.id = p_source_jugador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jugador origen no encontrado';
  END IF;

  IF v_caller IS DISTINCT FROM v_source.organizador_id
     AND NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Solo el organizador dueño puede propagar cambios a clubes cedidos';
  END IF;

  FOR v_access IN
    SELECT *
    FROM public.organizer_player_access opa
    WHERE opa.jugador_id = p_source_jugador_id
      AND opa.is_active = true
      AND opa.local_jugador_id IS NOT NULL
  LOOP
    PERFORM public._apply_granted_local_identity_sync(v_access, v_source);
    v_updated := v_updated + 1;
  END LOOP;

  RETURN jsonb_build_object('updated', v_updated);
END;
$$;


ALTER FUNCTION "public"."sync_granted_locals_from_source"("p_source_jugador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_organizador_ranking_oficial_from_players"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_has_public boolean;
BEGIN
  v_org_id := COALESCE(NEW.organizador_id, OLD.organizador_id);
  IF v_org_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.riviera_jugadores rj
    WHERE rj.organizador_id = v_org_id
      AND rj.estado = 'activo'
      AND rj.visible_publico IS TRUE
      AND COALESCE(rj.suma_ranking, true) = true
  ) INTO v_has_public;

  INSERT INTO public.organizador_game_modes (organizador_id, visible_ranking_oficial, updated_at)
  VALUES (v_org_id, v_has_public, now())
  ON CONFLICT (organizador_id) DO UPDATE
  SET visible_ranking_oficial = EXCLUDED.visible_ranking_oficial,
      updated_at = EXCLUDED.updated_at;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."sync_organizador_ranking_oficial_from_players"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."te_balanced_round_robin"("p_pair_ids" "uuid"[]) RETURNS TABLE("local_id" "uuid", "visitante_id" "uuid", "ronda" integer, "orden" integer)
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  n integer;
  lista uuid[];
  working uuid[];
  total integer;
  rondas integer;
  mitad integer;
  r integer;
  i integer;
  ord integer := 1;
  p1 uuid;
  p2 uuid;
  rotated uuid[];
  last_id uuid;
  rotated_len integer;
BEGIN
  n := coalesce(array_length(p_pair_ids, 1), 0);
  IF n < 2 THEN
    RETURN;
  END IF;

  lista := p_pair_ids;
  IF n % 2 <> 0 THEN
    lista := lista || ARRAY[NULL::uuid];
  END IF;

  total := array_length(lista, 1);
  rondas := total - 1;
  mitad := total / 2;
  working := lista;

  FOR r IN 0..(rondas - 1) LOOP
    FOR i IN 0..(mitad - 1) LOOP
      p1 := working[i + 1];
      p2 := working[total - i];
      IF p1 IS NOT NULL AND p2 IS NOT NULL THEN
        local_id := p1;
        visitante_id := p2;
        ronda := r + 1;
        orden := ord;
        ord := ord + 1;
        RETURN NEXT;
      END IF;
    END LOOP;

    IF r < rondas - 1 THEN
      rotated := working[2:total];
      rotated_len := coalesce(array_length(rotated, 1), 0);
      last_id := rotated[rotated_len];
      IF rotated_len > 1 THEN
        rotated := rotated[1:rotated_len - 1];
      ELSE
        rotated := ARRAY[]::uuid[];
      END IF;
      rotated := ARRAY[last_id] || rotated;
      working := ARRAY[working[1]] || rotated;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."te_balanced_round_robin"("p_pair_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."te_build_participantes"("p_local" "uuid", "p_visitante" "uuid") RETURNS "jsonb"
