CREATE OR REPLACE FUNCTION "public"."te_grupo_version_ok"("p_grupo_id" "uuid", "p_expected" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_version integer;
BEGIN
  SELECT version INTO v_version
  FROM public.torneo_express_grupos
  WHERE id = p_grupo_id;

  IF p_expected IS NULL OR p_expected IS DISTINCT FROM v_version THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'STALE_GROUP_VERSION',
      'version', v_version
    );
  END IF;
  RETURN jsonb_build_object('ok', true, 'version', v_version);
END;
$$;


