CREATE OR REPLACE FUNCTION "public"."te_lado_participante_valido"("p_lado" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_lado IS NOT NULL
    AND jsonb_typeof(p_lado) = 'object'
    AND (
      (
        (p_lado ->> 'is_virtual') = 'true'
        AND (p_lado ->> 'player1_id') IS NULL
        AND (p_lado ->> 'player2_id') IS NULL
        AND (p_lado ->> 'player1_name') IS NULL
        AND (p_lado ->> 'player2_name') IS NULL
        AND nullif(btrim(p_lado ->> 'virtual_label'), '') IS NOT NULL
      )
      OR (
        (p_lado ->> 'is_virtual') = 'false'
        AND (p_lado ->> 'player1_id') IS NOT NULL
        AND (p_lado ->> 'player2_id') IS NOT NULL
        AND (p_lado ->> 'player1_id') <> (p_lado ->> 'player2_id')
        AND nullif(btrim(p_lado ->> 'player1_name'), '') IS NOT NULL
        AND nullif(btrim(p_lado ->> 'player2_name'), '') IS NOT NULL
        AND (p_lado ->> 'virtual_label') IS NULL
      )
    );
$$;


ALTER FUNCTION "public"."te_lado_participante_valido"("p_lado" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."te_lock_categoria_editable"("p_torneo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner uuid;
  v_fase text;
  v_estado text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_torneo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOURNAMENT_NOT_FOUND');
  END IF;

  SELECT organizador_id, fase_torneo, estado
    INTO v_owner, v_fase, v_estado
  FROM public.torneo_express
  WHERE id = p_torneo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOURNAMENT_NOT_FOUND');
  END IF;

  IF v_owner IS NULL OR v_owner IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este torneo';
  END IF;

  IF v_estado = 'finalizado' OR v_fase = 'cerrado' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOURNAMENT_NOT_EDITABLE');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.torneo_express_eliminatoria_partidos
    WHERE torneo_id = p_torneo_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ELIMINATORIA_EXISTS');
  END IF;

  IF v_fase IS NOT NULL AND v_fase <> 'grupos' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOURNAMENT_NOT_EDITABLE');
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."te_lock_categoria_editable"("p_torneo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."te_matchup_key"("p_a" "uuid", "p_b" "uuid") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_a IS NULL OR p_b IS NULL THEN NULL
    WHEN p_a::text < p_b::text THEN p_a::text || '|' || p_b::text
    ELSE p_b::text || '|' || p_a::text
  END;
