CREATE OR REPLACE FUNCTION "public"."te_side_composition_matches"("p_expected" "jsonb", "p_pair_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_is_virtual" boolean) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pair uuid;
  v_p1 uuid;
  v_p2 uuid;
  v_virtual boolean;
BEGIN
  IF p_expected IS NULL OR jsonb_typeof(p_expected) <> 'object' THEN
    RETURN false;
  END IF;
  IF jsonb_typeof(p_expected -> 'is_virtual') IS DISTINCT FROM 'boolean' THEN
    RETURN false;
  END IF;

  BEGIN
    v_pair := (p_expected ->> 'pair_id')::uuid;
    v_virtual := (p_expected ->> 'is_virtual')::boolean;
    IF jsonb_typeof(p_expected -> 'player1_id') = 'string' THEN
      v_p1 := (p_expected ->> 'player1_id')::uuid;
    ELSIF jsonb_typeof(p_expected -> 'player1_id') IS DISTINCT FROM 'null' THEN
      RETURN false;
    END IF;
    IF jsonb_typeof(p_expected -> 'player2_id') = 'string' THEN
      v_p2 := (p_expected ->> 'player2_id')::uuid;
    ELSIF jsonb_typeof(p_expected -> 'player2_id') IS DISTINCT FROM 'null' THEN
      RETURN false;
    END IF;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RETURN false;
  END;

  IF v_pair IS NULL OR v_virtual IS NULL THEN
    RETURN false;
  END IF;

  IF v_virtual THEN
    IF v_p1 IS NOT NULL OR v_p2 IS NOT NULL THEN
      RETURN false;
    END IF;
  ELSIF v_p1 IS NULL OR v_p2 IS NULL THEN
    RETURN false;
  END IF;

  RETURN v_pair IS NOT DISTINCT FROM p_pair_id
    AND v_p1 IS NOT DISTINCT FROM p_player1_id
    AND v_p2 IS NOT DISTINCT FROM p_player2_id
    AND v_virtual IS NOT DISTINCT FROM p_is_virtual;
END;
$$;


ALTER FUNCTION "public"."te_side_composition_matches"("p_expected" "jsonb", "p_pair_id" "uuid", "p_player1_id" "uuid", "p_player2_id" "uuid", "p_is_virtual" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."te_slot_pareja_actual"("p_grupo_id" "uuid", "p_pareja_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT gp.pareja_id
  FROM public.torneo_express_grupo_parejas gp
  WHERE gp.grupo_id = p_grupo_id
    AND gp.activa
    AND (
      gp.pareja_id = p_pareja_id
      OR p_pareja_id = ANY (gp.pareja_previa_ids)
    )
  LIMIT 1;
$$;


