CREATE OR REPLACE FUNCTION "public"."trg_notif_partido_programado"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_programado_cambio boolean;
  v_cancha_cambio boolean;
  v_max_ronda integer;
  v_ronda_label text;
  v_torneo_nombre text;
  v_torneo_categoria text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_programado_cambio := NEW.programado_en IS DISTINCT FROM OLD.programado_en;
    v_cancha_cambio := COALESCE(NEW.cancha, '') IS DISTINCT FROM COALESCE(OLD.cancha, '');
    IF NOT (v_programado_cambio OR v_cancha_cambio) THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.programado_en IS NULL AND (NEW.cancha IS NULL OR TRIM(NEW.cancha) = '') THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(MAX(ronda), NEW.ronda)
  INTO v_max_ronda
  FROM public.torneo_express_eliminatoria_partidos
  WHERE torneo_id = NEW.torneo_id;

  v_ronda_label := CASE
    WHEN NEW.ronda = v_max_ronda THEN '🏆 FINAL'
    WHEN NEW.ronda = v_max_ronda - 1 THEN '⚡ SEMIFINAL'
    WHEN NEW.ronda = v_max_ronda - 2 THEN '💥 CUARTOS DE FINAL'
    WHEN NEW.ronda = v_max_ronda - 3 THEN 'OCTAVOS DE FINAL'
    ELSE CONCAT('Ronda ', NEW.ronda::text)
  END;

  SELECT nombre, categoria
  INTO v_torneo_nombre, v_torneo_categoria
  FROM public.torneo_express
  WHERE id = NEW.torneo_id;

  PERFORM public.enqueue_notif_event(
    NEW.torneo_id,
    'partido_programado',
    TG_TABLE_NAME,
    NEW.id,
    COALESCE(NEW.pareja_local_id, NEW.pareja_visitante_id),
    jsonb_build_object(
      'ronda', NEW.ronda,
      'ronda_label', v_ronda_label,
      'orden', NEW.orden,
      'programado_en', NEW.programado_en,
      'cancha', NEW.cancha,
      'torneo_nombre', v_torneo_nombre,
      'torneo_categoria', v_torneo_categoria,
      'pareja_local_id', NEW.pareja_local_id,
      'pareja_visitante_id', NEW.pareja_visitante_id
    )
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_notif_partido_programado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_notif_resultado_partido"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_torneo_id uuid;
  v_resultado_nuevo boolean;
BEGIN
  v_resultado_nuevo := (
    NEW.estado = 'jugado'
    AND (
      TG_OP = 'INSERT'
      OR COALESCE(OLD.estado, '') IS DISTINCT FROM 'jugado'
    )
  );

  IF NOT v_resultado_nuevo THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'torneo_express_partidos' THEN
    SELECT g.torneo_id
    INTO v_torneo_id
    FROM public.torneo_express_grupos g
    WHERE g.id = NEW.grupo_id;
  ELSE
    v_torneo_id := NEW.torneo_id;
  END IF;

  IF v_torneo_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM public.enqueue_notif_event(
    v_torneo_id,
    'resultado_partido',
    TG_TABLE_NAME,
    NEW.id,
    COALESCE(NEW.pareja_local_id, NEW.pareja_visitante_id),
    jsonb_build_object(
      'partido_id', NEW.id,
      'pareja_local_id', NEW.pareja_local_id,
      'pareja_visitante_id', NEW.pareja_visitante_id,
      'puntos_local', NEW.puntos_local,
      'puntos_visitante', NEW.puntos_visitante,
      'ganador_id', NEW.ganador_id,
      'resultado_registrado_en', now(),
      'fase', CASE
        WHEN TG_TABLE_NAME = 'torneo_express_partidos' THEN 'grupos'
        ELSE 'eliminatoria'
      END
    )
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_notif_resultado_partido"() OWNER TO "postgres";


