  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."trg_reverse_official_ledger_on_participacion_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."try_write_riviera_official_ledger"("p_participacion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_p record;
  v_organizador_id uuid;
  v_key uuid;
  v_points integer;
  v_subtipo text;
  v_club_name text;
  v_ledger_id uuid;
  v_prev_points integer;
  v_delta integer;
  v_player_org uuid;
  v_role text := COALESCE(auth.role(), '');
  v_valid_types text[] := ARRAY[
    'reta',
    'torneo_express',
    'liga',
    'americano',
    'duelo_2v2'
  ];
BEGIN
  IF p_participacion_id IS NULL THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'null_participacion_id');
  END IF;

  SELECT
    jp.id,
    jp.jugador_id,
    jp.tipo_evento,
    jp.evento_id,
    jp.evento_nombre,
    jp.puntos_obtenidos,
    jp.metadata,
    jp.created_at
  INTO v_p
  FROM public.jugador_participaciones jp
  WHERE jp.id = p_participacion_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'participacion_not_found');
  END IF;

  -- P0: anon no escribe ledger. authenticated debe poseer el perfil local
  -- (o ser master). service_role / SQL editor (role vacío) siguen para repairs.
  IF v_role = 'anon' THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'not_authenticated');
  END IF;

  IF v_role = 'authenticated' THEN
    SELECT rj.organizador_id INTO v_player_org
    FROM public.riviera_jugadores rj
    WHERE rj.id = v_p.jugador_id;

    IF auth.uid() IS NULL
       OR (
         NOT public.is_master_admin()
         AND (v_player_org IS NULL OR v_player_org IS DISTINCT FROM auth.uid())
       ) THEN
      RETURN jsonb_build_object('status', 'skipped', 'reason', 'permission_denied');
    END IF;
  END IF;

  v_subtipo := v_p.metadata->>'subtipo';
  IF v_subtipo = 'ajuste_manual' THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'ajuste_manual');
  END IF;

  IF NOT (v_p.tipo_evento::text = ANY (v_valid_types)) THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'invalid_event_type',
      'tipo_evento', v_p.tipo_evento
    );
  END IF;

  v_points := GREATEST(0, COALESCE(v_p.puntos_obtenidos, 0));
  IF v_points <= 0 THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'no_positive_points');
  END IF;

  BEGIN
    v_organizador_id := NULLIF(trim(v_p.metadata->>'organizador_id'), '')::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      v_organizador_id := NULL;
  END;

  IF v_organizador_id IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'missing_local_organizador_id'
    );
  END IF;

  IF NOT public._is_official_ranking_emitter(v_organizador_id) THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'organizer_not_authorized');
  END IF;

  v_key := public._resolve_official_player_key(v_p.jugador_id);
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('status', 'skipped', 'reason', 'no_official_identity');
  END IF;

  SELECT coalesce(u.name, u.email, 'Club')
  INTO v_club_name
  FROM public.users u
  WHERE u.id = v_organizador_id;

  SELECT points INTO v_prev_points
  FROM public.riviera_official_points_ledger
  WHERE participacion_id = p_participacion_id;

  IF v_prev_points IS NOT NULL AND v_prev_points = v_points THEN
    RETURN jsonb_build_object(
      'status', 'already_exists',
      'participacion_id', p_participacion_id
    );
  END IF;

  INSERT INTO public.riviera_official_points_ledger (
    official_player_key,
    source_organizer_id,
    source_local_jugador_id,
    participacion_id,
    event_type,
    event_id,
    event_name,
    points,
    source_club_name,
    created_at
  ) VALUES (
    v_key,
    v_organizador_id,
    v_p.jugador_id,
    p_participacion_id,
    v_p.tipo_evento,
    v_p.evento_id,
    v_p.evento_nombre,
    v_points,
    v_club_name,
    COALESCE(v_p.created_at, now())
  )
  ON CONFLICT (participacion_id) DO UPDATE SET
    points = EXCLUDED.points,
    event_name = EXCLUDED.event_name,
    source_club_name = EXCLUDED.source_club_name
  RETURNING id INTO v_ledger_id;

  v_delta := v_points - COALESCE(v_prev_points, 0);

  INSERT INTO public.riviera_official_player_totals (
    official_player_key,
    points_total,
    last_activity_at
  ) VALUES (
    v_key,
    v_delta,
    now()
  )
  ON CONFLICT (official_player_key) DO UPDATE
  SET
    points_total = riviera_official_player_totals.points_total + v_delta,
    last_activity_at = EXCLUDED.last_activity_at,
    updated_at = now();

  RETURN jsonb_build_object(
    'status', CASE WHEN v_prev_points IS NULL THEN 'inserted' ELSE 'updated' END,
    'ledger_id', v_ledger_id,
    'official_player_key', v_key,
    'points', v_points,
    'previous_points', v_prev_points,
    'participacion_id', p_participacion_id
  );
END;
$$;


ALTER FUNCTION "public"."try_write_riviera_official_ledger"("p_participacion_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."try_write_riviera_official_ledger"("p_participacion_id" "uuid") IS 'ROMC-2: registra puntos oficiales desde participación local. source_organizer_id = metadata.organizador_id (club del evento). Idempotente.';



CREATE OR REPLACE FUNCTION "public"."unarchive_coach_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_membership record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes permisos para administrar este club.');
  END IF;

  SELECT id, status INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No se encontró la membresía del entrenador.');
  END IF;

  IF v_membership.status <> 'ARCHIVED' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La membresía no se encuentra archivada.');
  END IF;

  UPDATE public.coach_club_memberships
  SET
    status = 'INACTIVE',
    archived_at = NULL,
    last_edited_by = v_caller,
    last_edited_at = now(),
    updated_at = now()
  WHERE id = v_membership.id;

  INSERT INTO public.coach_club_membership_audit_log (
    membership_id, coach_id, organizador_id, action, performed_by,
    previous_status, new_status, details
  ) VALUES (
    v_membership.id, p_coach_id, p_organizador_id, 'UNARCHIVE_COACH', v_caller,
    'ARCHIVED', 'INACTIVE', jsonb_build_object('unarchived_at', now())
  );

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'INACTIVE',
    'message', 'Entrenador restaurado a la lista como inactivo.'
  );
END;
$$;


ALTER FUNCTION "public"."unarchive_coach_from_club"("p_organizador_id" "uuid", "p_coach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_coach_class_followup"("p_session_id" "uuid", "p_worked_on" "text"[] DEFAULT '{}'::"text"[], "p_improvements" "text" DEFAULT NULL::"text", "p_areas_to_improve" "text" DEFAULT NULL::"text", "p_recommendations" "text" DEFAULT NULL::"text", "p_next_goals" "text" DEFAULT NULL::"text", "p_motivational_message" "text" DEFAULT NULL::"text", "p_private_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_sess public.coach_sessions%ROWTYPE;
  v_rel_status text;
  v_membership_status text;
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_is_coach boolean := false;
  v_private text := NULLIF(btrim(COALESCE(p_private_notes, '')), '');
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  SELECT * INTO v_sess
  FROM public.coach_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sesión no encontrada.');
  END IF;

  IF v_sess.status <> 'COMPLETED' OR v_sess.reverted_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Solo se puede editar el seguimiento de una clase impartida.');
  END IF;

  SELECT r.status INTO v_rel_status
  FROM public.coach_player_relationships r
  WHERE r.id = v_sess.relationship_id;

  IF v_rel_status IS NULL OR v_rel_status NOT IN ('ACTIVE', 'PAUSED') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La relación con el alumno no permite editar este seguimiento.');
  END IF;

  v_is_coach := v_sess.coach_id = public.current_riviera_coach_id();

  IF NOT v_is_coach AND v_sess.organizador_id <> v_caller AND v_is_master IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes autorización para editar el seguimiento de esta clase.');
  END IF;

  SELECT m.status INTO v_membership_status
  FROM public.coach_club_memberships m
  WHERE m.coach_id = v_sess.coach_id
    AND m.organizador_id = v_sess.organizador_id;

  IF v_membership_status IS DISTINCT FROM 'ACTIVE' AND v_is_master IS NOT TRUE AND v_sess.organizador_id <> v_caller THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El coach no tiene una asociación activa con este club.');
  END IF;

  UPDATE public.coach_sessions
  SET
    worked_on = COALESCE(p_worked_on, '{}'),
    improvements = NULLIF(btrim(COALESCE(p_improvements, '')), ''),
    areas_to_improve = NULLIF(btrim(COALESCE(p_areas_to_improve, '')), ''),
    recommendations = NULLIF(btrim(COALESCE(p_recommendations, '')), ''),
    next_goals = NULLIF(btrim(COALESCE(p_next_goals, '')), ''),
    motivational_message = NULLIF(btrim(COALESCE(p_motivational_message, '')), ''),
    followup_updated_at = now(),
    followup_updated_by = v_caller,
    updated_at = now()
  WHERE id = v_sess.id;

  IF v_private IS NULL THEN
    DELETE FROM public.coach_session_private_notes WHERE session_id = v_sess.id;
  ELSE
    INSERT INTO public.coach_session_private_notes (session_id, body, updated_at, updated_by)
    VALUES (v_sess.id, v_private, now(), v_caller)
    ON CONFLICT (session_id) DO UPDATE
      SET body = EXCLUDED.body,
          updated_at = EXCLUDED.updated_at,
          updated_by = EXCLUDED.updated_by;
  END IF;

  PERFORM public.coach_audit_write(
    'update_class_followup',
    'coach_session',
    v_sess.id,
    jsonb_build_object(
      'relationship_id', v_sess.relationship_id,
      'organizador_id', v_sess.organizador_id,
      'coach_id', v_sess.coach_id
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', v_sess.id,
    'followup_updated_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."update_coach_class_followup"("p_session_id" "uuid", "p_worked_on" "text"[], "p_improvements" "text", "p_areas_to_improve" "text", "p_recommendations" "text", "p_next_goals" "text", "p_motivational_message" "text", "p_private_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_coach_club_membership_settings"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_club_fuerzas" "text"[], "p_club_especialidades" "text"[], "p_club_notas" "text", "p_club_disponibilidad" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_membership record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes permisos para administrar coaches en este club.');
  END IF;

  SELECT id, status INTO v_membership
  FROM public.coach_club_memberships
  WHERE coach_id = p_coach_id AND organizador_id = p_organizador_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El entrenador no tiene membresía registrada en este club.');
  END IF;

  -- 1. Actualizar configuración pública del club en coach_club_memberships
  UPDATE public.coach_club_memberships
  SET
    club_fuerzas = p_club_fuerzas,
    club_especialidades = p_club_especialidades,
    club_notas = NULL, -- Notas administrativas privadas aisladas fuera de esta tabla
    last_edited_by = v_caller,
    last_edited_at = now(),
    updated_at = now()
  WHERE id = v_membership.id;

  -- 2. Guardar notas privadas en coach_club_private_notes (inaccesible para el coach)
  INSERT INTO public.coach_club_private_notes (
    organizador_id,
    coach_id,
    club_notas,
    club_disponibilidad,
    last_edited_by,
    last_edited_at
  ) VALUES (
    p_organizador_id,
    p_coach_id,
    p_club_notas,
    p_club_disponibilidad,
    v_caller,
    now()
  )
  ON CONFLICT (organizador_id, coach_id) DO UPDATE SET
    club_notas = EXCLUDED.club_notas,
    club_disponibilidad = EXCLUDED.club_disponibilidad,
    last_edited_by = v_caller,
    last_edited_at = now();

  -- 3. Registrar auditoría
  INSERT INTO public.coach_club_membership_audit_log (
    membership_id, coach_id, organizador_id, action, performed_by,
    previous_status, new_status, details
  ) VALUES (
    v_membership.id, p_coach_id, p_organizador_id, 'UPDATE_SETTINGS', v_caller,
    v_membership.status, v_membership.status,
    jsonb_build_object(
      'fuerzas', p_club_fuerzas,
      'especialidades', p_club_especialidades
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'message', 'Configuración del entrenador actualizada correctamente para este club.'
  );
END;
$$;


ALTER FUNCTION "public"."update_coach_club_membership_settings"("p_organizador_id" "uuid", "p_coach_id" "uuid", "p_club_fuerzas" "text"[], "p_club_especialidades" "text"[], "p_club_notas" "text", "p_club_disponibilidad" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_coach_student_relationship_status"("p_organizador_id" "uuid", "p_relationship_id" "uuid", "p_new_status" "text", "p_reason" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_master boolean := COALESCE(public.is_master_admin(), false);
  v_trimmed_status text := UPPER(btrim(COALESCE(p_new_status, '')));
  v_trimmed_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_trimmed_key text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_rel record;
  v_sess_row record;
  v_coach_id uuid;
  v_cancelled_count integer := 0;
  v_remaining_balance integer := 0;
  v_now timestamptz := now();
  v_session_cancel_reason text;
  v_idem record;
  v_response jsonb;
BEGIN
  -- 1. Autenticación y Autorización
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;

  -- Rechazar expresamente cuentas STUDENT_ONLY
  IF EXISTS (
    SELECT 1 FROM auth.users u
    WHERE u.id = v_caller
      AND (
        u.raw_app_meta_data->>'role' = 'STUDENT_ONLY'
        OR u.raw_app_meta_data->>'account_type' = 'STUDENT_ONLY'
        OR u.raw_user_meta_data->>'account_type' = 'STUDENT_ONLY'
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Las cuentas de alumno no están autorizadas para modificar relaciones de coaching.');
  END IF;

  -- Solo el organizador propietario del club o el administrador maestro pueden modificar la relación
  IF v_caller <> p_organizador_id AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autorizado: solo la administración del club puede modificar el estado de sus alumnos.');
  END IF;

  -- Validar que el club tenga habilitado el módulo de Coaching
  IF NOT EXISTS (
    SELECT 1 FROM public.organizador_game_modes
    WHERE organizador_id = p_organizador_id AND coaching_enabled = true
  ) AND NOT v_is_master THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El club no tiene habilitado el módulo de Coaching.');
  END IF;

  -- 2. Validación de estado solicitado
  IF v_trimmed_status NOT IN ('ACTIVE', 'PAUSED', 'ENDED') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Estado inválido. Los estados permitidos son ACTIVE, PAUSED o ENDED.');
  END IF;

  -- 3. Búsqueda y Bloqueo Concurrente de la Relación en este Club
  SELECT *
  INTO v_rel
  FROM public.coach_player_relationships
  WHERE id = p_relationship_id AND organizador_id = p_organizador_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Relación coach-alumno no encontrada en este club.');
  END IF;

  -- 4. Comprobación de Idempotencia Estricta por Clave
  IF v_trimmed_key IS NOT NULL THEN
    SELECT *
    INTO v_idem
    FROM public.coach_relationship_status_idempotency
    WHERE idempotency_key = v_trimmed_key;

    IF FOUND THEN
      -- Validar que no haya conflicto de parámetros
      IF v_idem.organizador_id <> p_organizador_id
         OR v_idem.relationship_id <> p_relationship_id
         OR v_idem.actor_auth_user_id <> v_caller
         OR v_idem.status_requested <> v_trimmed_status THEN
        RETURN jsonb_build_object(
          'ok', false,
          'error', 'Conflicto de idempotencia: la clave ya fue utilizada con otros parámetros.'
        );
      END IF;

      -- Replay idempotente: devuelve el resultado registrado previamente
      -- SIN alterar el estado actual de la relación (evitando que un reintento tardío
      -- sobrescriba una transición posterior como ACTIVE -> PAUSED -> ACTIVE).
      RETURN v_idem.response_payload || jsonb_build_object(
        'idempotent_replay', true,
        'already_processed', true,
        'current_relationship_status', v_rel.status
      );
    END IF;
  END IF;

  -- Obtener saldo actual de clases para diagnóstico y confirmación
  SELECT COALESCE(balance_classes, 0)
  INTO v_remaining_balance
  FROM public.coach_player_class_balances
  WHERE relationship_id = p_relationship_id;

  -- 5. Si la relación ya se encuentra en el estado solicitado
  IF v_rel.status = v_trimmed_status THEN
    v_response := jsonb_build_object(
      'ok', true,
      'success', true,
      'relationship_id', p_relationship_id,
      'status', v_trimmed_status,
      'previous_status', v_rel.status,
      'already_applied', true,
      'cancelled_scheduled_count', 0,
      'remaining_balance', v_remaining_balance,
      'message', 'La relación ya se encontraba en estado ' || v_trimmed_status || '.'
    );

    IF v_trimmed_key IS NOT NULL THEN
      INSERT INTO public.coach_relationship_status_idempotency (
        idempotency_key,
        organizador_id,
        relationship_id,
        actor_auth_user_id,
        status_requested,
        status_applied,
        cancelled_scheduled_count,
        response_payload,
        created_at
      ) VALUES (
        v_trimmed_key,
        p_organizador_id,
        p_relationship_id,
        v_caller,
        v_trimmed_status,
        v_trimmed_status,
        0,
        v_response,
        v_now
      ) ON CONFLICT (idempotency_key) DO NOTHING;
    END IF;

    RETURN v_response;
  END IF;

  -- 6. Ejecutar Transición de Estado
  IF v_trimmed_status = 'ENDED' THEN
    -- Cancelación segura de sesiones programadas con tratamiento diferenciado
    FOR v_sess_row IN
      SELECT id, starts_at, court, coach_id, jugador_id
      FROM public.coach_sessions
      WHERE relationship_id = p_relationship_id
        AND status = 'SCHEDULED'
      FOR UPDATE
    LOOP
      IF v_sess_row.starts_at >= v_now THEN
        v_session_cancel_reason := 'Relación finalizada por la administración del club: clase futura cancelada'
          || CASE WHEN v_trimmed_reason IS NOT NULL THEN ' (' || v_trimmed_reason || ')' ELSE '.' END;
      ELSE
        v_session_cancel_reason := 'Relación finalizada por la administración del club: clase programada pasada no impartida'
          || CASE WHEN v_trimmed_reason IS NOT NULL THEN ' (' || v_trimmed_reason || ')' ELSE '.' END;
      END IF;

      -- Actualizar sesión a CANCELLED (sin tocar reverted_at/reverted_by, exclusivo de sesiones completadas revertidas)
      UPDATE public.coach_sessions
      SET status = 'CANCELLED',
          cancellation_reason = v_session_cancel_reason,
          updated_at = v_now
      WHERE id = v_sess_row.id;

      v_cancelled_count := v_cancelled_count + 1;

      -- Auditoría individual por cada sesión cancelada
      INSERT INTO public.coach_audit_log (
        actor_auth_user_id,
        action,
        entity_type,
        entity_id,
        payload,
        created_at
      ) VALUES (
        v_caller,
        'CLASS_CANCELLED',
        'coach_sessions',
        v_sess_row.id,
        jsonb_build_object(
          'coach_id', v_sess_row.coach_id,
          'student_id', v_sess_row.jugador_id,
          'relationship_id', p_relationship_id,
          'starts_at', v_sess_row.starts_at,
          'court', v_sess_row.court,
          'reason', v_session_cancel_reason,
          'trigger', 'RELATIONSHIP_ENDED'
        ),
        v_now
      );
    END LOOP;

    -- Actualizar estado de la relación a ENDED
    UPDATE public.coach_player_relationships
    SET status = 'ENDED',
        ended_at = v_now,
        is_primary = false,
        updated_at = v_now
    WHERE id = p_relationship_id;

  ELSIF v_trimmed_status = 'PAUSED' THEN
    UPDATE public.coach_player_relationships
    SET status = 'PAUSED',
        is_primary = false,
        updated_at = v_now
    WHERE id = p_relationship_id;

  ELSIF v_trimmed_status = 'ACTIVE' THEN
    UPDATE public.coach_player_relationships
    SET status = 'ACTIVE',
        ended_at = NULL,
        updated_at = v_now
    WHERE id = p_relationship_id;
  END IF;

  -- 7. Registro en Bitácora de Auditoría para la Relación
  SELECT c.id INTO v_coach_id
  FROM public.riviera_coaches c
  WHERE c.auth_user_id = v_caller
  LIMIT 1;

  INSERT INTO public.coach_audit_log (
    actor_coach_id,
    actor_auth_user_id,
    action,
    entity_type,
    entity_id,
    payload,
    created_at
  ) VALUES (
    v_coach_id,
    v_caller,
    'RELATIONSHIP_STATUS_UPDATE',
    'coach_player_relationships',
    p_relationship_id,
    jsonb_build_object(
      'relationship_id', p_relationship_id,
      'organizador_id', p_organizador_id,
      'coach_id', v_rel.coach_id,
      'jugador_id', v_rel.jugador_id,
      'old_status', v_rel.status,
      'new_status', v_trimmed_status,
      'reason', v_trimmed_reason,
      'idempotency_key', v_trimmed_key,
      'cancelled_scheduled_count', v_cancelled_count,
      'remaining_balance', v_remaining_balance
    ),
    v_now
  );

  -- 8. Construir Respuesta y Guardar Registro de Idempotencia
  v_response := jsonb_build_object(
    'ok', true,
    'success', true,
    'relationship_id', p_relationship_id,
    'status', v_trimmed_status,
    'previous_status', v_rel.status,
    'cancelled_scheduled_count', v_cancelled_count,
    'remaining_balance', v_remaining_balance,
    'message', 'Estado de la relación actualizado a ' || v_trimmed_status || ' exitosamente.'
  );

  IF v_trimmed_key IS NOT NULL THEN
    INSERT INTO public.coach_relationship_status_idempotency (
      idempotency_key,
      organizador_id,
      relationship_id,
      actor_auth_user_id,
      status_requested,
      status_applied,
      cancelled_scheduled_count,
      response_payload,
      created_at
    ) VALUES (
      v_trimmed_key,
      p_organizador_id,
      p_relationship_id,
      v_caller,
      v_trimmed_status,
      v_trimmed_status,
      v_cancelled_count,
      v_response,
      v_now
    ) ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_response;
END;
$$;


ALTER FUNCTION "public"."update_coach_student_relationship_status"("p_organizador_id" "uuid", "p_relationship_id" "uuid", "p_new_status" "text", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_liga_partido_score"("p_partido_id" "uuid", "p_score1" integer, "p_score2" integer, "p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_partido record;
  v_organizador uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_score1 IS NULL OR p_score2 IS NULL OR p_score1 < 0 OR p_score2 < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
  END IF;

  SELECT id, jornada_id, ronda, estado, score_pareja1, score_pareja2
    INTO v_partido
    FROM public.liga_partidos
    WHERE id = p_partido_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT l.organizador_id INTO v_organizador
  FROM public.liga_jornadas j
  JOIN public.ligas l ON l.id = j.liga_id
  WHERE j.id = v_partido.jornada_id;

  IF v_organizador IS NULL OR v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este partido';
  END IF;

  -- Idempotente: mismo marcador ya guardado → éxito sin re-disparar cascada.
  IF v_partido.estado = 'completed'
     AND v_partido.score_pareja1 = p_score1
     AND v_partido.score_pareja2 = p_score2
  THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'unchanged',
      'partido_id', p_partido_id,
      'jornada_id', v_partido.jornada_id,
      'ronda', v_partido.ronda
    );
  END IF;

  IF v_partido.estado = 'completed' AND NOT p_force THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'conflict',
      'score_pareja1', v_partido.score_pareja1,
      'score_pareja2', v_partido.score_pareja2
    );
  END IF;

  UPDATE public.liga_partidos
  SET score_pareja1 = p_score1,
      score_pareja2 = p_score2,
      estado = 'completed'
  WHERE id = p_partido_id;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'updated',
    'partido_id', p_partido_id,
    'jornada_id', v_partido.jornada_id,
    'ronda', v_partido.ronda
  );
END;
$$;


ALTER FUNCTION "public"."update_liga_partido_score"("p_partido_id" "uuid", "p_score1" integer, "p_score2" integer, "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_liga_partido_score_parejas_fijas_playoffs"("p_partido_id" "uuid", "p_score1" integer, "p_score2" integer, "p_set_scores" "jsonb", "p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_partido record;
  v_organizador uuid;
  v_wo boolean;
  v_score1 integer;
  v_score2 integer;
  v_sets jsonb;
  v_sets_len integer;
  v_set1 jsonb;
  v_set2 jsonb;
  v_set3 jsonb;
  v_s1p1 integer;
  v_s1p2 integer;
  v_s2p1 integer;
  v_s2p2 integer;
  v_s3p1 integer;
  v_s3p2 integer;
  v_sets_won_p1 integer;
  v_sets_won_p2 integer;
  v_needs_deciding boolean;
  v_has_stb boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida';
  END IF;

  IF p_set_scores IS NULL
     OR (p_set_scores ->> 'format') IS DISTINCT FROM 'parejas_fijas_playoffs' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
  END IF;

  v_wo := COALESCE((p_set_scores ->> 'wo')::boolean, false);
  v_has_stb := (p_set_scores -> 'stb') IS NOT NULL
               AND jsonb_typeof(p_set_scores -> 'stb') <> 'null';

  IF v_wo THEN
    IF p_score1 IS NULL OR p_score2 IS NULL OR p_score1 < 0 OR p_score2 < 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_score');
    END IF;
    IF NOT (
      (p_score1 = 6 AND p_score2 = 0) OR (p_score1 = 0 AND p_score2 = 6)
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_wo');
    END IF;
    IF v_has_stb THEN
      RETURN jsonb_build_object('ok', false, 'error', 'wo_no_stb');
    END IF;
    v_score1 := p_score1;
    v_score2 := p_score2;
  ELSE
    v_sets := p_set_scores -> 'sets';
    IF jsonb_typeof(v_sets) IS DISTINCT FROM 'array' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'sets_required');
    END IF;

    v_sets_len := jsonb_array_length(v_sets);
    IF v_sets_len IS DISTINCT FROM 2 AND v_sets_len IS DISTINCT FROM 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'sets_required');
    END IF;

    v_set1 := v_sets -> 0;
    v_set2 := v_sets -> 1;

    BEGIN
      v_s1p1 := (v_set1 ->> 'p1')::integer;
      v_s1p2 := (v_set1 ->> 'p2')::integer;
      v_s2p1 := (v_set2 ->> 'p1')::integer;
      v_s2p2 := (v_set2 ->> 'p2')::integer;
    EXCEPTION WHEN others THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_sets');
    END;

    IF v_s1p1 IS NULL OR v_s1p2 IS NULL OR v_s2p1 IS NULL OR v_s2p2 IS NULL
       OR v_s1p1 < 0 OR v_s1p2 < 0 OR v_s2p1 < 0 OR v_s2p2 < 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_sets');
    END IF;

    -- Empate en set permitido (p.ej. por tiempo): nadie suma ese set.
    v_sets_won_p1 :=
      (CASE WHEN v_s1p1 > v_s1p2 THEN 1 ELSE 0 END)
      + (CASE WHEN v_s2p1 > v_s2p2 THEN 1 ELSE 0 END);
    v_sets_won_p2 :=
      (CASE WHEN v_s1p2 > v_s1p1 THEN 1 ELSE 0 END)
      + (CASE WHEN v_s2p2 > v_s2p1 THEN 1 ELSE 0 END);

    v_score1 := v_s1p1 + v_s2p1;
    v_score2 := v_s1p2 + v_s2p2;

    v_needs_deciding := (v_sets_won_p1 = v_sets_won_p2);

    IF v_sets_len = 3 THEN
      -- Set completo decisivo: STB no permitido.
      IF v_has_stb THEN
        RETURN jsonb_build_object('ok', false, 'error', 'stb_not_allowed');
      END IF;

      IF NOT v_needs_deciding THEN
        RETURN jsonb_build_object('ok', false, 'error', 'set3_not_allowed');
      END IF;

      v_set3 := v_sets -> 2;
      BEGIN
        v_s3p1 := (v_set3 ->> 'p1')::integer;
        v_s3p2 := (v_set3 ->> 'p2')::integer;
      EXCEPTION WHEN others THEN
        RETURN jsonb_build_object('ok', false, 'error', 'invalid_sets');
      END;

      IF v_s3p1 IS NULL OR v_s3p2 IS NULL
         OR v_s3p1 < 0 OR v_s3p2 < 0 THEN
        RETURN jsonb_build_object('ok', false, 'error', 'invalid_sets');
      END IF;

      IF v_s3p1 = v_s3p2 THEN
        RETURN jsonb_build_object('ok', false, 'error', 'set3_tie_not_allowed');
      END IF;

      v_sets_won_p1 := v_sets_won_p1 + (CASE WHEN v_s3p1 > v_s3p2 THEN 1 ELSE 0 END);
      v_sets_won_p2 := v_sets_won_p2 + (CASE WHEN v_s3p2 > v_s3p1 THEN 1 ELSE 0 END);
      v_score1 := v_score1 + v_s3p1;
      v_score2 := v_score2 + v_s3p2;

      IF v_sets_won_p1 = v_sets_won_p2 THEN
        RETURN jsonb_build_object('ok', false, 'error', 'match_tie_not_allowed');
      END IF;

    ELSIF v_needs_deciding THEN
      -- Empate tras S1+S2: STB manual (histórico) o falta set decisivo.
      IF NOT v_has_stb THEN
        RETURN jsonb_build_object('ok', false, 'error', 'deciding_set_required');
      END IF;
    ELSE
      -- Victoria directa: STB no permitido.
      IF v_has_stb THEN
        RETURN jsonb_build_object('ok', false, 'error', 'stb_not_allowed');
      END IF;
    END IF;
  END IF;

  SELECT id, jornada_id, ronda, estado, score_pareja1, score_pareja2, set_scores
    INTO v_partido
    FROM public.liga_partidos
    WHERE id = p_partido_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT l.organizador_id INTO v_organizador
  FROM public.liga_jornadas j
  JOIN public.ligas l ON l.id = j.liga_id
  WHERE j.id = v_partido.jornada_id;

  IF v_organizador IS NULL OR v_organizador IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Sin permiso sobre este partido';
  END IF;

  IF v_partido.estado = 'completed'
     AND v_partido.score_pareja1 = v_score1
     AND v_partido.score_pareja2 = v_score2
     AND v_partido.set_scores IS NOT DISTINCT FROM p_set_scores
  THEN
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'unchanged',
      'partido_id', p_partido_id,
      'jornada_id', v_partido.jornada_id
    );
  END IF;

  IF v_partido.estado = 'completed' AND NOT p_force THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'conflict',
      'score_pareja1', v_partido.score_pareja1,
      'score_pareja2', v_partido.score_pareja2,
      'set_scores', v_partido.set_scores
    );
  END IF;

  UPDATE public.liga_partidos
  SET score_pareja1 = v_score1,
      score_pareja2 = v_score2,
      set_scores = p_set_scores,
      estado = 'completed'
  WHERE id = p_partido_id;

  RETURN jsonb_build_object(
    'ok', true,
    'status', 'updated',
    'partido_id', p_partido_id,
    'jornada_id', v_partido.jornada_id,
    'score_pareja1', v_score1,
    'score_pareja2', v_score2
  );
END;
$$;


ALTER FUNCTION "public"."update_liga_partido_score_parejas_fijas_playoffs"("p_partido_id" "uuid", "p_score1" integer, "p_score2" integer, "p_set_scores" "jsonb", "p_force" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_liga_partido_score_parejas_fijas_playoffs"("p_partido_id" "uuid", "p_score1" integer, "p_score2" integer, "p_set_scores" "jsonb", "p_force" boolean) IS 'parejas_fijas_playoffs: sets-first; empate sets → set completo (sets[3]) o STB manual; WO 6-0.';



CREATE OR REPLACE FUNCTION "public"."update_own_coach_profile"("p_profile" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_caller uuid := auth.uid();
  v_coach public.riviera_coaches%ROWTYPE;
  v_foto text := NULLIF(btrim(COALESCE(p_profile->>'foto_url', '')), '');
  v_bio text := NULLIF(btrim(COALESCE(p_profile->>'bio', '')), '');
  v_certs text := NULLIF(btrim(COALESCE(p_profile->>'certificaciones', '')), '');
  v_pos text := NULLIF(lower(btrim(COALESCE(p_profile->>'posicion_juego', ''))), '');
  v_ig text := NULLIF(btrim(COALESCE(p_profile->>'instagram_url', '')), '');
  v_fb text := NULLIF(btrim(COALESCE(p_profile->>'facebook_url', '')), '');
  v_tt text := NULLIF(btrim(COALESCE(p_profile->>'tiktok_url', '')), '');
  v_met text := NULLIF(btrim(COALESCE(p_profile->>'metodologia_ensenanza', '')), '');
  v_enf text := NULLIF(btrim(COALESCE(p_profile->>'enfoque_tecnico', '')), '');
  v_obj text := NULLIF(btrim(COALESCE(p_profile->>'objetivos_alumnos', '')), '');
  v_est text := NULLIF(btrim(COALESCE(p_profile->>'estructura_entrenamientos', '')), '');
  v_edad int;
  v_anos int;
  v_social constant text := '^https?://[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}(/[^[:space:]]*)?$';
  v_allowed text[] := '{}';
  v_fuerzas text[] := '{}';
  v_item text;
  v_clean text;
  v_especialidades text[] := '{}';
  v_areas text[] := '{}';
  v_fortalezas text[] := '{}';
  v_habilidades text[] := '{}';
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Perfil no válido.');
  END IF;

  SELECT * INTO v_coach
  FROM public.riviera_coaches
  WHERE auth_user_id = v_caller
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No tienes un perfil de entrenador.');
  END IF;

  IF v_bio IS NOT NULL AND length(v_bio) > 280 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La presentación puede tener hasta 280 caracteres.');
  END IF;
  IF v_certs IS NOT NULL AND length(v_certs) > 400 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Las certificaciones pueden tener hasta 400 caracteres.');
  END IF;
  IF v_met IS NOT NULL AND length(v_met) > 400 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La metodología puede tener hasta 400 caracteres.');
  END IF;
  IF v_enf IS NOT NULL AND length(v_enf) > 400 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El enfoque puede tener hasta 400 caracteres.');
  END IF;
  IF v_obj IS NOT NULL AND length(v_obj) > 400 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Los objetivos pueden tener hasta 400 caracteres.');
  END IF;
  IF v_est IS NOT NULL AND length(v_est) > 400 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La estructura puede tener hasta 400 caracteres.');
  END IF;

  IF v_pos IS NOT NULL AND v_pos NOT IN ('reves', 'drive', 'ambas') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La posición habitual no es válida.');
  END IF;

  BEGIN
    v_edad := NULLIF(p_profile->>'edad', '')::int;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La edad no es válida.');
  END;
  IF v_edad IS NOT NULL AND (v_edad < 18 OR v_edad > 99) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La edad debe estar entre 18 y 99 años.');
  END IF;

  BEGIN
    v_anos := NULLIF(p_profile->>'anos_experiencia', '')::int;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Los años de experiencia no son válidos.');
  END;
  IF v_anos IS NOT NULL AND (v_anos < 0 OR v_anos > 60) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Los años de experiencia deben estar entre 0 y 60.');
  END IF;

  IF v_foto IS NOT NULL AND (
       length(v_foto) > 500
       OR v_foto !~* '^https://[^[:space:]]+$'
       OR position('/storage/v1/object/public/jugadores-avatars/' || v_caller::text || '/' IN v_foto) = 0
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La fotografía no es válida.');
  END IF;

  IF v_ig IS NOT NULL AND (length(v_ig) > 200 OR v_ig !~* v_social) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El enlace de Instagram no es válido.');
  END IF;
  IF v_fb IS NOT NULL AND (length(v_fb) > 200 OR v_fb !~* v_social) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El enlace de Facebook no es válido.');
  END IF;
  IF v_tt IS NOT NULL AND (length(v_tt) > 200 OR v_tt !~* v_social) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El enlace de TikTok no es válido.');
  END IF;

  IF jsonb_typeof(p_profile->'especialidades') = 'array' THEN
    FOR v_item IN SELECT jsonb_array_elements_text(p_profile->'especialidades') LOOP
      v_clean := left(btrim(v_item), 60);
      IF v_clean <> '' AND NOT v_clean = ANY (v_especialidades) AND cardinality(v_especialidades) < 12 THEN
        v_especialidades := v_especialidades || v_clean;
      END IF;
    END LOOP;
  END IF;
  IF jsonb_typeof(p_profile->'areas_entrenamiento') = 'array' THEN
    FOR v_item IN SELECT jsonb_array_elements_text(p_profile->'areas_entrenamiento') LOOP
      v_clean := left(btrim(v_item), 60);
      IF v_clean <> '' AND NOT v_clean = ANY (v_areas) AND cardinality(v_areas) < 12 THEN
        v_areas := v_areas || v_clean;
      END IF;
    END LOOP;
  END IF;
  IF jsonb_typeof(p_profile->'fortalezas') = 'array' THEN
    FOR v_item IN SELECT jsonb_array_elements_text(p_profile->'fortalezas') LOOP
      v_clean := left(btrim(v_item), 60);
      IF v_clean <> '' AND NOT v_clean = ANY (v_fortalezas) AND cardinality(v_fortalezas) < 12 THEN
        v_fortalezas := v_fortalezas || v_clean;
      END IF;
    END LOOP;
  END IF;
  IF jsonb_typeof(p_profile->'habilidades_principales') = 'array' THEN
    FOR v_item IN SELECT jsonb_array_elements_text(p_profile->'habilidades_principales') LOOP
      v_clean := left(btrim(v_item), 60);
      IF v_clean <> '' AND NOT v_clean = ANY (v_habilidades) AND cardinality(v_habilidades) < 12 THEN
        v_habilidades := v_habilidades || v_clean;
      END IF;
    END LOOP;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT f), '{}')
  INTO v_allowed
  FROM public.coach_club_memberships m
  CROSS JOIN LATERAL unnest(COALESCE(m.club_fuerzas, '{}'::text[])) AS f
  WHERE m.coach_id = v_coach.id
    AND m.status IN ('ACTIVE', 'PENDING')
    AND btrim(f) <> '';

  IF COALESCE(cardinality(v_allowed), 0) = 0 THEN
    v_allowed := COALESCE(v_coach.fuerzas, '{}'::text[]);
  END IF;

  IF jsonb_typeof(p_profile->'fuerzas') = 'array' THEN
    FOR v_item IN SELECT jsonb_array_elements_text(p_profile->'fuerzas') LOOP
      v_clean := btrim(v_item);
      IF v_clean = ANY (v_allowed)
         AND v_clean IN ('open', '1ra_fuerza', '2da_fuerza', '3ra_fuerza', '4ta_fuerza', '5ta_fuerza', '6ta_fuerza')
         AND NOT v_clean = ANY (v_fuerzas) THEN
        v_fuerzas := v_fuerzas || v_clean;
      END IF;
    END LOOP;
  ELSE
    v_fuerzas := COALESCE(v_coach.fuerzas, '{}'::text[]);
  END IF;

  UPDATE public.riviera_coaches
  SET
    foto_url = v_foto,
    bio = v_bio,
    certificaciones = v_certs,
    edad = v_edad,
    anos_experiencia = v_anos,
    posicion_juego = v_pos,
    instagram_url = v_ig,
    facebook_url = v_fb,
    tiktok_url = v_tt,
    especialidades = v_especialidades,
    areas_entrenamiento = v_areas,
    fortalezas = v_fortalezas,
    metodologia_ensenanza = v_met,
    enfoque_tecnico = v_enf,
    objetivos_alumnos = v_obj,
    estructura_entrenamientos = v_est,
    habilidades_principales = v_habilidades,
    fuerzas = v_fuerzas,
    updated_at = now()
  WHERE id = v_coach.id
    AND auth_user_id = v_caller;

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_coach.id,
    'coach_code', v_coach.coach_code,
    'foto_url', v_foto,
    'bio', v_bio,
    'certificaciones', v_certs,
    'edad', v_edad,
    'anos_experiencia', v_anos,
    'posicion_juego', v_pos,
    'instagram_url', v_ig,
    'facebook_url', v_fb,
    'tiktok_url', v_tt,
    'especialidades', to_jsonb(v_especialidades),
    'areas_entrenamiento', to_jsonb(v_areas),
    'fortalezas', to_jsonb(v_fortalezas),
    'metodologia_ensenanza', v_met,
    'enfoque_tecnico', v_enf,
    'objetivos_alumnos', v_obj,
    'estructura_entrenamientos', v_est,
    'habilidades_principales', to_jsonb(v_habilidades),
    'fuerzas', to_jsonb(v_fuerzas)
  );
END;
$_$;


ALTER FUNCTION "public"."update_own_coach_profile"("p_profile" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_student_coaching_profile"("p_foto_url" "text" DEFAULT NULL::"text", "p_update_foto" boolean DEFAULT false, "p_edad" integer DEFAULT NULL::integer, "p_update_edad" boolean DEFAULT false, "p_en_cancha" "text" DEFAULT NULL::"text", "p_update_en_cancha" boolean DEFAULT false, "p_instagram_url" "text" DEFAULT NULL::"text", "p_update_instagram" boolean DEFAULT false, "p_facebook_url" "text" DEFAULT NULL::"text", "p_update_facebook" boolean DEFAULT false, "p_tiktok_url" "text" DEFAULT NULL::"text", "p_update_tiktok" boolean DEFAULT false, "p_sobre_mi" "text" DEFAULT NULL::"text", "p_update_sobre_mi" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_caller uuid := auth.uid();
  v_direct_ids uuid[] := '{}';
  v_official_keys uuid[] := '{}';
  v_target_ids uuid[] := '{}';
  v_clean_en_cancha text := NULLIF(lower(btrim(COALESCE(p_en_cancha, ''))), '');
  v_clean_foto text := NULLIF(btrim(COALESCE(p_foto_url, '')), '');
  v_clean_ig text := NULLIF(btrim(COALESCE(p_instagram_url, '')), '');
  v_clean_fb text := NULLIF(btrim(COALESCE(p_facebook_url, '')), '');
  v_clean_tt text := NULLIF(btrim(COALESCE(p_tiktok_url, '')), '');
  v_clean_sobre text := NULLIF(btrim(COALESCE(p_sobre_mi, '')), '');
  v_social_re constant text := '^https?://[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}(/[^[:space:]]*)?$';
  v_profile jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Usuario no autenticado.');
  END IF;

  IF p_update_edad AND p_edad IS NOT NULL AND (p_edad < 5 OR p_edad > 99) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La edad debe estar entre 5 y 99 años.');
  END IF;

  IF p_update_en_cancha AND v_clean_en_cancha IS NOT NULL
     AND v_clean_en_cancha NOT IN ('reves', 'drive') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Posición en la cancha no válida.');
  END IF;

  IF p_update_foto AND v_clean_foto IS NOT NULL AND (
       length(v_clean_foto) > 500
       OR position('/storage/v1/object/public/jugadores-avatars/' || v_caller::text || '/' IN v_clean_foto) = 0
       OR v_clean_foto !~* '^https://[^[:space:]]+$'
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La fotografía no es válida.');
  END IF;

  IF p_update_instagram AND v_clean_ig IS NOT NULL
     AND (length(v_clean_ig) > 200 OR v_clean_ig !~* v_social_re) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El enlace de Instagram no es válido.');
  END IF;
  IF p_update_facebook AND v_clean_fb IS NOT NULL
     AND (length(v_clean_fb) > 200 OR v_clean_fb !~* v_social_re) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El enlace de Facebook no es válido.');
  END IF;
  IF p_update_tiktok AND v_clean_tt IS NOT NULL
     AND (length(v_clean_tt) > 200 OR v_clean_tt !~* v_social_re) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El enlace de TikTok no es válido.');
  END IF;
  IF p_update_sobre_mi AND v_clean_sobre IS NOT NULL AND char_length(v_clean_sobre) > 200 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'La descripción puede tener hasta 200 caracteres.');
  END IF;

  SELECT COALESCE(array_agg(DISTINCT al.jugador_id), '{}')
  INTO v_direct_ids
  FROM public.coach_student_account_links al
  WHERE al.auth_user_id = v_caller
    AND al.is_active = true;

  IF array_length(v_direct_ids, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'No se encontró un perfil de jugador vinculado a tu cuenta.'
    );
  END IF;

  SELECT COALESCE(array_agg(DISTINCT i.official_player_key), '{}')
  INTO v_official_keys
  FROM public.riviera_official_player_identity i
  WHERE i.canonical_riviera_jugador_id = ANY(v_direct_ids);

  SELECT COALESCE(array_agg(DISTINCT cand.id), v_direct_ids)
  INTO v_target_ids
  FROM (
    SELECT unnest(v_direct_ids) AS id
    UNION
    SELECT i.canonical_riviera_jugador_id
    FROM public.riviera_official_player_identity i
    WHERE array_length(v_official_keys, 1) > 0
      AND i.official_player_key = ANY(v_official_keys)
    UNION
    SELECT l.riviera_jugador_id
    FROM public.riviera_official_player_profile_link l
    WHERE array_length(v_official_keys, 1) > 0
      AND l.official_player_key = ANY(v_official_keys)
  ) cand
  WHERE cand.id IS NOT NULL
    AND (
      cand.id = ANY(v_direct_ids)
      OR NOT EXISTS (
        SELECT 1 FROM public.coach_student_account_links o
        WHERE o.jugador_id = cand.id AND o.auth_user_id <> v_caller
      )
    );

  UPDATE public.riviera_jugadores rj
  SET
    foto_url = CASE WHEN p_update_foto THEN v_clean_foto ELSE rj.foto_url END,
    edad = CASE WHEN p_update_edad THEN p_edad::smallint ELSE rj.edad END,
    en_cancha = CASE WHEN p_update_en_cancha THEN v_clean_en_cancha ELSE rj.en_cancha END,
    instagram_url = CASE WHEN p_update_instagram THEN v_clean_ig ELSE rj.instagram_url END,
    facebook_url = CASE WHEN p_update_facebook THEN v_clean_fb ELSE rj.facebook_url END,
    tiktok_url = CASE WHEN p_update_tiktok THEN v_clean_tt ELSE rj.tiktok_url END,
    coaching_sobre_mi = CASE WHEN p_update_sobre_mi THEN v_clean_sobre ELSE rj.coaching_sobre_mi END
  WHERE rj.id = ANY(v_target_ids);

  SELECT jsonb_build_object(
    'id', rj.id,
    'organizador_id', rj.organizador_id,
    'nombre', rj.nombre,
    'foto_url', rj.foto_url,
    'riviera_id', i.riviera_id,
    'edad', rj.edad,
    'en_cancha', rj.en_cancha,
    'instagram_url', rj.instagram_url,
    'facebook_url', rj.facebook_url,
    'tiktok_url', rj.tiktok_url,
    'coaching_sobre_mi', rj.coaching_sobre_mi
  )
  INTO v_profile
  FROM public.coach_student_account_links al
  JOIN public.riviera_jugadores rj ON rj.id = al.jugador_id
  LEFT JOIN public.riviera_official_player_identity i ON i.canonical_riviera_jugador_id = rj.id
  WHERE al.auth_user_id = v_caller AND al.is_active = true
  ORDER BY (rj.foto_url IS NOT NULL) DESC, al.updated_at DESC NULLS LAST, rj.id
  LIMIT 1;

  RETURN jsonb_build_object('ok', true, 'profile', v_profile);
END;
$_$;


ALTER FUNCTION "public"."update_student_coaching_profile"("p_foto_url" "text", "p_update_foto" boolean, "p_edad" integer, "p_update_edad" boolean, "p_en_cancha" "text", "p_update_en_cancha" boolean, "p_instagram_url" "text", "p_update_instagram" boolean, "p_facebook_url" "text", "p_update_facebook" boolean, "p_tiktok_url" "text", "p_update_tiktok" boolean, "p_sobre_mi" "text", "p_update_sobre_mi" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tournament_courts_and_unassign"("p_tournament_id" "uuid", "p_new_courts" integer, "p_expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner uuid;
  v_old_courts integer;
  v_updated_at timestamptz;
  v_new_updated_at timestamptz;
  v_unassigned integer := 0;
  v_rowcount integer;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_tournament_id');
  END IF;
  IF p_new_courts IS NULL OR p_new_courts < 1 OR p_new_courts > 20 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_courts');
  END IF;

  SELECT user_id, courts, updated_at
    INTO v_owner, v_old_courts, v_updated_at
  FROM public.tournaments
  WHERE id = p_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF auth.uid() IS NULL OR auth.uid() <> v_owner THEN
    IF NOT public.is_master_admin() THEN
      RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
    END IF;
  END IF;

  -- Conflict before any mutation
  IF p_expected_updated_at IS NOT NULL
     AND v_updated_at IS NOT NULL
     AND p_expected_updated_at <> v_updated_at THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'conflict',
      'message', 'La configuración cambió en otra sesión. Recarga los datos antes de guardar.'
    );
  END IF;

  -- 1) Update courts + bump updated_at (explicit; no trigger assumed)
  UPDATE public.tournaments
  SET
    courts = p_new_courts,
    updated_at = now()
  WHERE id = p_tournament_id
    AND (
      p_expected_updated_at IS NULL
      OR updated_at IS NULL
      OR updated_at = p_expected_updated_at
    )
  RETURNING updated_at INTO v_new_updated_at;

  GET DIAGNOSTICS v_rowcount = ROW_COUNT;
  IF v_rowcount = 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'conflict',
      'message', 'La configuración cambió en otra sesión. Recarga los datos antes de guardar.'
    );
  END IF;

  -- 2) Unassign only future/pending on courts that disappear (no auto-reschedule)
  IF p_new_courts < coalesce(v_old_courts, 1) THEN
    BEGIN
      UPDATE public.matches m
      SET court = NULL
      WHERE m.tournament_id = p_tournament_id
        AND m.court IS NOT NULL
        AND m.court > p_new_courts
        AND coalesce(m.pair1_score, m.pair2_score) IS NULL
        AND lower(coalesce(m.status, '')) NOT IN (
          'completed', 'finished', 'finalizado',
          'in_progress', 'playing', 'en_juego', 'live', 'started'
        );
      GET DIAGNOSTICS v_unassigned = ROW_COUNT;
    EXCEPTION
      WHEN not_null_violation THEN
        -- Abort entire transaction (courts update rolls back)
        RAISE EXCEPTION 'matches.court no acepta NULL; no se pudo desasignar de forma segura'
          USING ERRCODE = 'check_violation';
      WHEN undefined_column THEN
        RAISE EXCEPTION 'matches.court no existe'
          USING ERRCODE = 'undefined_column';
    END;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'courts', p_new_courts,
    'unassigned_count', v_unassigned,
    'updated_at', v_new_updated_at
  );
END;
$$;


ALTER FUNCTION "public"."update_tournament_courts_and_unassign"("p_tournament_id" "uuid", "p_new_courts" integer, "p_expected_updated_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_tournament_courts_and_unassign"("p_tournament_id" "uuid", "p_new_courts" integer, "p_expected_updated_at" timestamp with time zone) IS 'Actualiza tournaments.courts y pone court=NULL en pendientes fuera de rango; no toca resultados ni en juego; atómico.';



