    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_updated_at_column"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_open_game_registration"("p_mode_type" "text", "p_entity_id" "uuid", "p_enabled" boolean DEFAULT NULL::boolean, "p_status" "text" DEFAULT NULL::"text", "p_capacity" integer DEFAULT NULL::integer, "p_waitlist_enabled" boolean DEFAULT NULL::boolean, "p_approval_required" boolean DEFAULT NULL::boolean, "p_registration_deadline" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_scheduled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_duration_minutes" integer DEFAULT NULL::integer, "p_category_label" "text" DEFAULT NULL::"text", "p_location_label" "text" DEFAULT NULL::"text", "p_display_rating" boolean DEFAULT NULL::boolean, "p_display_photo" boolean DEFAULT NULL::boolean, "p_display_full_name" boolean DEFAULT NULL::boolean, "p_title_public" "text" DEFAULT NULL::"text", "p_rama_label" "text" DEFAULT NULL::"text") RETURNS "public"."tournament_open_registration"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_row public.tournament_open_registration;
  v_mode text;
  v_tournament uuid;
  v_next_cap int;
  v_confirmed int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticación requerida'; END IF;
  v_mode := public._assert_convocatoria_mode_allowed(p_mode_type);
  IF p_entity_id IS NULL THEN RAISE EXCEPTION 'entity_id requerido'; END IF;

  v_org := public._open_reg_organizer_id(v_mode, p_entity_id);
  IF v_org IS NULL OR v_org <> v_uid THEN
    RAISE EXCEPTION 'Evento no encontrado o sin permiso';
  END IF;

  v_tournament := CASE WHEN v_mode = 'duelo_2v2' THEN NULL ELSE p_entity_id END;

  -- Capacidad destino (duelo fijo 4)
  IF v_mode = 'duelo_2v2' THEN
    v_next_cap := 4;
  ELSIF p_capacity IS NULL THEN
    v_next_cap := NULL; -- keep existing on update / default on insert
  ELSE
    IF p_capacity < 1 OR p_capacity > 64 THEN
      RAISE EXCEPTION 'Cupo fuera de rango (1–64)';
    END IF;
    v_next_cap := p_capacity;
  END IF;

  INSERT INTO public.tournament_open_registration AS tor (
    id, tournament_id, mode_type, entity_id, public_slug, enabled, status,
    capacity, waitlist_enabled, approval_required, registration_deadline,
    scheduled_at, duration_minutes, category_label, location_label,
    display_rating, display_photo, display_full_name, title_public, rama_label
  ) VALUES (
    gen_random_uuid(),
    v_tournament,
    v_mode,
    p_entity_id,
    public._tor_open_reg_slug(),
    coalesce(p_enabled, false),
    coalesce(p_status, 'draft'),
    coalesce(v_next_cap, CASE WHEN v_mode = 'duelo_2v2' THEN 4 ELSE 8 END),
    coalesce(p_waitlist_enabled, true),
    coalesce(p_approval_required, false),
    p_registration_deadline,
    p_scheduled_at,
    p_duration_minutes,
    nullif(trim(coalesce(p_category_label, '')), ''),
    nullif(trim(coalesce(p_location_label, '')), ''),
    coalesce(p_display_rating, true),
    coalesce(p_display_photo, true),
    coalesce(p_display_full_name, true),
    nullif(trim(coalesce(p_title_public, '')), ''),
    nullif(trim(coalesce(p_rama_label, '')), '')
  )
  ON CONFLICT (mode_type, entity_id) DO UPDATE SET
    enabled = coalesce(p_enabled, tor.enabled),
    status = coalesce(p_status, tor.status),
    capacity = CASE
      WHEN v_mode = 'duelo_2v2' THEN 4
      WHEN v_next_cap IS NULL THEN tor.capacity
      ELSE v_next_cap
    END,
    waitlist_enabled = coalesce(p_waitlist_enabled, tor.waitlist_enabled),
    approval_required = coalesce(p_approval_required, tor.approval_required),
    registration_deadline = coalesce(p_registration_deadline, tor.registration_deadline),
    scheduled_at = coalesce(p_scheduled_at, tor.scheduled_at),
    duration_minutes = coalesce(p_duration_minutes, tor.duration_minutes),
    category_label = coalesce(nullif(trim(coalesce(p_category_label, '')), ''), tor.category_label),
    location_label = coalesce(nullif(trim(coalesce(p_location_label, '')), ''), tor.location_label),
    display_rating = coalesce(p_display_rating, tor.display_rating),
    display_photo = coalesce(p_display_photo, tor.display_photo),
    display_full_name = coalesce(p_display_full_name, tor.display_full_name),
    title_public = coalesce(nullif(trim(coalesce(p_title_public, '')), ''), tor.title_public),
    rama_label = coalesce(nullif(trim(coalesce(p_rama_label, '')), ''), tor.rama_label),
    tournament_id = coalesce(tor.tournament_id, v_tournament),
    updated_at = now()
  RETURNING * INTO v_row;

  -- No bajar bajo confirmados (tampoco vía upsert genérico)
  IF v_mode <> 'duelo_2v2' AND v_next_cap IS NOT NULL THEN
    SELECT count(*)::int INTO v_confirmed
    FROM public.tournament_open_registration_entries e
    WHERE e.registration_id = v_row.id AND e.status = 'confirmed';
    IF v_next_cap < v_confirmed THEN
      RAISE EXCEPTION
        'Ya hay % confirmados. Saca inscritos en Administrar inscritos antes de bajar el cupo a %.',
        v_confirmed, v_next_cap;
    END IF;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_open_game_registration"("p_mode_type" "text", "p_entity_id" "uuid", "p_enabled" boolean, "p_status" "text", "p_capacity" integer, "p_waitlist_enabled" boolean, "p_approval_required" boolean, "p_registration_deadline" timestamp with time zone, "p_scheduled_at" timestamp with time zone, "p_duration_minutes" integer, "p_category_label" "text", "p_location_label" "text", "p_display_rating" boolean, "p_display_photo" boolean, "p_display_full_name" boolean, "p_title_public" "text", "p_rama_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_tournament_open_registration"("p_tournament_id" "uuid", "p_enabled" boolean DEFAULT NULL::boolean, "p_status" "text" DEFAULT NULL::"text", "p_capacity" integer DEFAULT NULL::integer, "p_waitlist_enabled" boolean DEFAULT NULL::boolean, "p_approval_required" boolean DEFAULT NULL::boolean, "p_registration_deadline" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_scheduled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_duration_minutes" integer DEFAULT NULL::integer, "p_category_label" "text" DEFAULT NULL::"text", "p_location_label" "text" DEFAULT NULL::"text", "p_display_rating" boolean DEFAULT NULL::boolean, "p_display_photo" boolean DEFAULT NULL::boolean, "p_display_full_name" boolean DEFAULT NULL::boolean) RETURNS "public"."tournament_open_registration"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mode text := 'reta';
BEGIN
  -- Si el torneo está marcado como americano en config, preferir americano
  IF EXISTS (
    SELECT 1 FROM public.tournament_public_config c
    WHERE c.tournament_id = p_tournament_id
      AND (
        c.format = 'americano'
        OR (c.americano_live IS NOT NULL AND c.americano_live <> 'null'::jsonb)
      )
  ) THEN
    v_mode := 'americano';
  END IF;

  RETURN public.upsert_open_game_registration(
    v_mode, p_tournament_id, p_enabled, p_status, p_capacity, p_waitlist_enabled,
    p_approval_required, p_registration_deadline, p_scheduled_at, p_duration_minutes,
    p_category_label, p_location_label, p_display_rating, p_display_photo,
    p_display_full_name, NULL, NULL
  );
END;
$$;


ALTER FUNCTION "public"."upsert_tournament_open_registration"("p_tournament_id" "uuid", "p_enabled" boolean, "p_status" "text", "p_capacity" integer, "p_waitlist_enabled" boolean, "p_approval_required" boolean, "p_registration_deadline" timestamp with time zone, "p_scheduled_at" timestamp with time zone, "p_duration_minutes" integer, "p_category_label" "text", "p_location_label" "text", "p_display_rating" boolean, "p_display_photo" boolean, "p_display_full_name" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_student_invitation"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_clean_token text := btrim(COALESCE(p_token, ''));
  v_hash text;
  v_invitation record;
  v_jugador record;
  v_coach record;
  v_club_name text;
  v_is_existing_account boolean := false;
  v_is_email_verified boolean := false;
BEGIN
  IF v_clean_token = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Token de invitación no proporcionado.');
  END IF;

  v_hash := encode(extensions.digest(v_clean_token::bytea, 'sha256'), 'hex');

  SELECT * INTO v_invitation
  FROM public.coach_student_invitations
  WHERE (token_hash = v_hash OR invitation_token = v_clean_token)
  LIMIT 1;

  IF v_invitation.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Invitación no encontrada o token inválido.');
  END IF;

  IF v_invitation.status = 'ACCEPTED' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'is_already_accepted', true,
      'error', 'Esta invitación ya fue activada previamente. Inicia sesión con tu correo y contraseña.'
    );
  END IF;

  IF v_invitation.status = 'REVOKED' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Esta invitación fue cancelada por el club. Solicita una nueva invitación a tu entrenador o administración.'
    );
  END IF;

  IF v_invitation.expires_at < now() THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Esta invitación ha expirado. Solicita a tu club que te envíe una nueva invitación.'
    );
  END IF;

  IF COALESCE(v_invitation.attempts_count, 0) >= 10 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Demasiados intentos fallidos. Por seguridad, la invitación fue bloqueada. Solicita una nueva.'
    );
  END IF;

  -- Resolver datos de jugador y Riviera ID canónico
  SELECT rj.id, rj.nombre, rj.email, i.riviera_id INTO v_jugador
  FROM public.riviera_jugadores rj
  LEFT JOIN public.riviera_official_player_identity i ON i.canonical_riviera_jugador_id = rj.id
  WHERE rj.id = v_invitation.jugador_id;

  -- Resolver nombre comercial real del club (Hack Pádel, etc.)
  v_club_name := public.get_organizador_display_name(v_invitation.organizador_id);

  SELECT nombre INTO v_coach
  FROM public.riviera_coaches
  WHERE id = v_invitation.coach_id;

  -- Distinción REAL de cuenta activada previamente:
  -- Una cuenta es pre-existente y ya activada SOLO si ya tiene un vínculo activo en coach_student_account_links.
  -- Nunca basarse en auth.users.encrypted_password, pues generateLink inserta un registro técnico con hash.
  SELECT EXISTS (
    SELECT 1 FROM public.coach_student_account_links al
    JOIN auth.users u ON u.id = al.auth_user_id
    WHERE lower(btrim(u.email)) = lower(btrim(v_invitation.email))
      AND al.is_active = true
  ) INTO v_is_existing_account;

  -- Comprobar si el correo ya está verificado en auth.users
  SELECT EXISTS (
    SELECT 1 FROM auth.users
    WHERE lower(btrim(email)) = lower(btrim(v_invitation.email))
      AND email_confirmed_at IS NOT NULL
  ) INTO v_is_email_verified;

  RETURN jsonb_build_object(
    'ok', true,
    'invitation_id', v_invitation.id,
    'email', v_invitation.email,
    'student_name', v_jugador.nombre,
    'riviera_id', v_jugador.riviera_id,
    'club_name', v_club_name,
    'coach_name', v_coach.nombre,
    'expires_at', v_invitation.expires_at,
    'is_existing_account', v_is_existing_account,
    'is_email_verified', v_is_email_verified
  );
END;
$$;


