CREATE OR REPLACE VIEW "public"."_historical_orphan_parent_participaciones" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "jp"."id" AS "participacion_id",
            "jp"."jugador_id",
            "jp"."tipo_evento",
            "jp"."evento_id",
            "jp"."evento_nombre",
            "jp"."puntos_obtenidos",
            "jp"."created_at",
            COALESCE("jp"."metadata", '{}'::"jsonb") AS "metadata",
            COALESCE(("jp"."metadata" ->> 'organizador_id'::"text"), ''::"text") AS "metadata_organizador_id",
            COALESCE(("jp"."metadata" ->> 'club_name'::"text"), ''::"text") AS "metadata_club_name",
            COALESCE(("jp"."metadata" ->> 'integrity_status'::"text"), ''::"text") AS "integrity_status",
            COALESCE(("jp"."metadata" ->> 'repair_required'::"text"), ''::"text") AS "repair_required",
            "public"."_riviera_normalize_evento_nombre"("jp"."evento_nombre") AS "event_name_key",
            "public"."_riviera_historical_event_name_whitelist_hit"("jp"."evento_nombre") AS "event_name_whitelist_hit",
            "public"."_riviera_participacion_parent_lookup_table"(("jp"."tipo_evento")::"text") AS "parent_lookup_table",
            "public"."_riviera_participacion_parent_row_exists"(("jp"."tipo_evento")::"text", ("jp"."evento_id")::"text") AS "parent_row_found",
            "public"."riviera_participacion_expected_host_org"(("jp"."tipo_evento")::"text", ("jp"."evento_id")::"text") AS "expected_host_from_parent",
            "mo"."override_id" AS "manual_override_id",
            "mo"."organizador_id" AS "manual_override_organizador_id",
            "mo"."club_name" AS "manual_override_club_name",
            "mo"."approved_at" AS "manual_override_approved_at",
            "mo"."reason" AS "manual_override_reason"
           FROM ("public"."jugador_participaciones" "jp"
             LEFT JOIN LATERAL "public"."riviera_career_event_host_manual_override"(("jp"."tipo_evento")::"text", ("jp"."evento_id")::"text") "mo"("override_id", "organizador_id", "club_name", "evento_nombre", "approved_by", "approved_at", "reason") ON (true))
          WHERE (COALESCE("jp"."puntos_obtenidos", 0) > 0)
        ), "sibling_stats" AS (
         SELECT "b"."evento_id",
            "b"."tipo_evento",
            ("count"("s"."id"))::integer AS "sibling_total_count",
            ("count"("s"."id") FILTER (WHERE (NULLIF(TRIM(BOTH FROM ("s"."metadata" ->> 'organizador_id'::"text")), ''::"text") IS NOT NULL)))::integer AS "sibling_with_org_count",
            ("count"(DISTINCT NULLIF(TRIM(BOTH FROM ("s"."metadata" ->> 'organizador_id'::"text")), ''::"text")) FILTER (WHERE (NULLIF(TRIM(BOTH FROM ("s"."metadata" ->> 'organizador_id'::"text")), ''::"text") IS NOT NULL)))::integer AS "sibling_distinct_orgs"
           FROM ("base" "b"
             JOIN "public"."jugador_participaciones" "s" ON ((("s"."evento_id" = "b"."evento_id") AND ("s"."tipo_evento" = "b"."tipo_evento"))))
          GROUP BY "b"."evento_id", "b"."tipo_evento"
        ), "sibling_consensus" AS (
         SELECT "s"."evento_id",
            "s"."tipo_evento",
            "mode"() WITHIN GROUP (ORDER BY NULLIF(TRIM(BOTH FROM ("s"."metadata" ->> 'organizador_id'::"text")), ''::"text")) AS "sibling_consensus_org_id"
           FROM "public"."jugador_participaciones" "s"
          WHERE (NULLIF(TRIM(BOTH FROM ("s"."metadata" ->> 'organizador_id'::"text")), ''::"text") IS NOT NULL)
          GROUP BY "s"."evento_id", "s"."tipo_evento"
        ), "audited" AS (
         SELECT "b"."participacion_id",
            "b"."jugador_id",
            "b"."tipo_evento",
            "b"."evento_id",
            "b"."evento_nombre",
            "b"."puntos_obtenidos",
            "b"."created_at",
            "b"."metadata",
            "b"."metadata_organizador_id",
            "b"."metadata_club_name",
            "b"."integrity_status",
            "b"."repair_required",
            "b"."event_name_key",
            "b"."event_name_whitelist_hit",
            "b"."parent_lookup_table",
            "b"."parent_row_found",
            "b"."expected_host_from_parent",
            "b"."manual_override_id",
            "b"."manual_override_organizador_id",
            "b"."manual_override_club_name",
            "b"."manual_override_approved_at",
            "b"."manual_override_reason",
            COALESCE("ss"."sibling_total_count", 0) AS "sibling_total_count",
            COALESCE("ss"."sibling_with_org_count", 0) AS "sibling_with_org_count",
            COALESCE("ss"."sibling_distinct_orgs", 0) AS "sibling_distinct_orgs",
            "sc"."sibling_consensus_org_id",
                CASE
                    WHEN ("b"."parent_row_found" AND ("b"."expected_host_from_parent" IS NOT NULL)) THEN 'EVENT_PARENT'::"text"
                    WHEN ("b"."manual_override_id" IS NOT NULL) THEN 'MANUAL_OVERRIDE'::"text"
                    WHEN (("ss"."sibling_with_org_count" > 0) AND ("ss"."sibling_distinct_orgs" = 1)) THEN 'SIBLING_METADATA'::"text"
                    WHEN ((("b"."metadata" ->> 'repaired_from_orphan_parent'::"text") = 'true'::"text") OR ("b"."integrity_status" = ANY (ARRAY['repaired_orphan_parent'::"text", 'orphan_parent_review'::"text"]))) THEN 'MANUAL_OVERRIDE'::"text"
                    WHEN "b"."event_name_whitelist_hit" THEN 'EVENT_NAME_MAP'::"text"
                    ELSE 'NONE'::"text"
                END AS "expected_host_source"
           FROM (("base" "b"
             LEFT JOIN "sibling_stats" "ss" ON ((("ss"."evento_id" = "b"."evento_id") AND ("ss"."tipo_evento" = "b"."tipo_evento"))))
             LEFT JOIN "sibling_consensus" "sc" ON ((("sc"."evento_id" = "b"."evento_id") AND ("sc"."tipo_evento" = "b"."tipo_evento"))))
        )
 SELECT "a"."participacion_id",
    "a"."jugador_id",
    "rj"."nombre" AS "jugador_nombre",
    "a"."tipo_evento",
    "a"."evento_id",
    "a"."evento_nombre",
    "a"."puntos_obtenidos",
    "a"."created_at",
    "a"."metadata_organizador_id",
    "a"."metadata_club_name",
    "a"."integrity_status",
    "a"."repair_required",
    "a"."parent_lookup_table",
    "a"."parent_row_found",
    "a"."expected_host_from_parent",
    "a"."sibling_total_count",
    "a"."sibling_with_org_count",
    "a"."sibling_distinct_orgs",
    "a"."sibling_consensus_org_id",
    "a"."event_name_key",
    "a"."event_name_whitelist_hit",
    ("a"."manual_override_id" IS NOT NULL) AS "has_manual_override",
    "a"."manual_override_organizador_id",
    "a"."manual_override_club_name",
    "a"."manual_override_approved_at",
    "a"."manual_override_reason",
    "a"."expected_host_source",
        CASE
            WHEN ("a"."parent_row_found" AND ("a"."expected_host_from_parent" IS NOT NULL)) THEN NULL::"text"
            WHEN ("a"."parent_lookup_table" IS NULL) THEN 'unsupported_event_type'::"text"
            WHEN ("a"."sibling_distinct_orgs" > 1) THEN 'conflicting_sibling_metadata'::"text"
            WHEN ((NOT "a"."event_name_whitelist_hit") AND ("a"."sibling_with_org_count" = 0) AND (NULLIF(TRIM(BOTH FROM "a"."metadata_organizador_id"), ''::"text") IS NULL) AND ("a"."expected_host_from_parent" IS NULL)) THEN 'event_name_not_mapped'::"text"
            WHEN (("a"."sibling_with_org_count" = 0) AND (NULLIF(TRIM(BOTH FROM "a"."metadata_organizador_id"), ''::"text") IS NULL) AND ("a"."expected_host_from_parent" IS NULL) AND (NOT "a"."event_name_whitelist_hit")) THEN 'no_sibling_metadata'::"text"
            WHEN (NOT "a"."parent_row_found") THEN 'no_parent_row'::"text"
            WHEN ((NULLIF(TRIM(BOTH FROM "a"."metadata_organizador_id"), ''::"text") IS NULL) AND ("a"."expected_host_from_parent" IS NULL)) THEN 'host_unknown'::"text"
            ELSE NULL::"text"
        END AS "why_not_inferred",
        CASE
            WHEN ("a"."parent_row_found" AND ("a"."expected_host_from_parent" IS NOT NULL)) THEN 'SKIP_PARENT_EXISTS'::"text"
            WHEN (("a"."manual_override_id" IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM "a"."metadata_organizador_id"), ''::"text") IS NOT NULL) AND (TRIM(BOTH FROM "a"."metadata_organizador_id") = ("a"."manual_override_organizador_id")::"text")) THEN 'OK_OVERRIDE_APPLIED'::"text"
            WHEN ("a"."manual_override_id" IS NOT NULL) THEN 'READY_MANUAL_OVERRIDE'::"text"
            WHEN (NULLIF(TRIM(BOTH FROM "a"."metadata_organizador_id"), ''::"text") IS NOT NULL) THEN 'OK_HAS_HOST_METADATA'::"text"
            WHEN ((("a"."metadata" ->> 'repaired_from_orphan_parent'::"text") = 'true'::"text") OR ("a"."integrity_status" = 'repaired_orphan_parent'::"text")) THEN 'OK_MANUAL_REPAIRED'::"text"
            WHEN ("a"."integrity_status" = 'orphan_parent_review'::"text") THEN 'OK_MARKED_HISTORICAL_REVIEW'::"text"
            WHEN (("a"."sibling_with_org_count" > 0) AND ("a"."sibling_distinct_orgs" = 1)) THEN 'CANDIDATE_SIBLING_CONSENSUS'::"text"
            WHEN "a"."event_name_whitelist_hit" THEN 'CANDIDATE_MANUAL_NAME_MAP'::"text"
            WHEN ("a"."parent_lookup_table" IS NULL) THEN 'REVIEW_UNSUPPORTED_TIPO'::"text"
            WHEN ((NOT "a"."parent_row_found") AND ("a"."sibling_with_org_count" = 0)) THEN 'REVIEW_HISTORICO_NO_SOURCE'::"text"
            WHEN ("a"."sibling_distinct_orgs" > 1) THEN 'REVIEW_SIBLING_CONFLICT'::"text"
            ELSE 'REVIEW_HOST_UNKNOWN'::"text"
        END AS "suggested_action"
   FROM ("audited" "a"
     LEFT JOIN "public"."riviera_jugadores" "rj" ON (("rj"."id" = "a"."jugador_id")))
  WHERE ((NOT "a"."parent_row_found") OR ("a"."expected_host_from_parent" IS NULL))
  ORDER BY "a"."evento_nombre", "a"."puntos_obtenidos" DESC;


