CREATE TABLE IF NOT EXISTS "public"."duelos_2v2" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organizador_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "descripcion" "text",
    "estado" "text" DEFAULT 'configuracion'::"text" NOT NULL,
    "pareja_a_j1_id" "uuid",
    "pareja_a_j2_id" "uuid",
    "pareja_a_j1_nombre" "text" DEFAULT ''::"text",
    "pareja_a_j2_nombre" "text" DEFAULT ''::"text",
    "pareja_b_j1_id" "uuid",
    "pareja_b_j2_id" "uuid",
    "pareja_b_j1_nombre" "text" DEFAULT ''::"text",
    "pareja_b_j2_nombre" "text" DEFAULT ''::"text",
    "sets_pareja_a" integer DEFAULT 0 NOT NULL,
    "sets_pareja_b" integer DEFAULT 0 NOT NULL,
    "detalle_sets" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "ganador" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finalizado_at" timestamp with time zone,
    "cancha" "text",
    "programado_en" timestamp with time zone,
    "programado_hasta" timestamp with time zone,
    "es_publico" boolean DEFAULT true NOT NULL,
    "archived_at" timestamp with time zone,
    "lugar" "text",
    "mostrar_lugar" boolean DEFAULT true NOT NULL,
    "categoria" "text",
    "costo" "text",
    "mostrar_costo" boolean DEFAULT false NOT NULL,
    "premio" "text",
    "mostrar_premio" boolean DEFAULT false NOT NULL,
    CONSTRAINT "duelos_2v2_estado_check" CHECK (("estado" = ANY (ARRAY['configuracion'::"text", 'en_juego'::"text", 'finalizado'::"text"]))),
    CONSTRAINT "duelos_2v2_ganador_check" CHECK (("ganador" = ANY (ARRAY['a'::"text", 'b'::"text"])))
);


ALTER TABLE "public"."duelos_2v2" OWNER TO "postgres";


COMMENT ON COLUMN "public"."duelos_2v2"."pareja_a_j1_id" IS 'Slot A1: FK riviera_jugadores. NULL permitido en estado configuracion (convocatoria).';



COMMENT ON COLUMN "public"."duelos_2v2"."es_publico" IS 'Si false, el duelo no es legible por anon.';



COMMENT ON COLUMN "public"."duelos_2v2"."archived_at" IS 'Soft-archive desde Mis retas. NULL = visible en admin. No borra carrera.';



COMMENT ON COLUMN "public"."duelos_2v2"."lugar" IS 'Sede / club donde se juega (ej. Hack Pádel). Independiente del nombre del organizador.';



COMMENT ON COLUMN "public"."duelos_2v2"."mostrar_lugar" IS 'Si true, la convocatoria WhatsApp incluye la línea Lugar. Si false, se omite.';



COMMENT ON COLUMN "public"."duelos_2v2"."categoria" IS 'Descripción libre del encuentro (ej. mixta, verano). Distinto de descripcion (nivel/fuerza).';



COMMENT ON COLUMN "public"."duelos_2v2"."costo" IS 'Texto libre de precio/inscripción (ej. $200 por jugador). Solo se publica si mostrar_costo.';



COMMENT ON COLUMN "public"."duelos_2v2"."mostrar_costo" IS 'Si true, incluir costo/precio en el mensaje de convocatoria WhatsApp. Default false.';



COMMENT ON COLUMN "public"."duelos_2v2"."premio" IS 'Texto libre de premio (ej. Trofeo + pelotas). Solo se publica si mostrar_premio.';



COMMENT ON COLUMN "public"."duelos_2v2"."mostrar_premio" IS 'Si true, incluir premio en el mensaje de convocatoria WhatsApp. Default false.';



