    CONSTRAINT "liga_notificaciones_preferencias_consentimiento_estado_check" CHECK (("consentimiento_estado" = ANY (ARRAY['sin_autorizacion'::"text", 'autorizado'::"text", 'revocado'::"text"])))
);


ALTER TABLE "public"."liga_notificaciones_preferencias" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."liga_notificaciones_queue" (
