    CONSTRAINT "liga_notificaciones_queue_motivo_check" CHECK ((("motivo" IS NULL) OR ("char_length"("motivo") <= 80))),
    CONSTRAINT "liga_notificaciones_queue_origen_check" CHECK (("origen" = ANY (ARRAY['manual'::"text", 'automatico'::"text"]))),
    CONSTRAINT "liga_notificaciones_queue_tipo_check" CHECK (("tipo" = ANY (ARRAY['bienvenida'::"text", 'aviso_general'::"text", 'jornada'::"text", 'cambio_horario'::"text", 'felicitacion'::"text", 'personalizado'::"text", 'resultados_jornada'::"text", 'recordatorio_jornada'::"text"])))
);


ALTER TABLE "public"."liga_notificaciones_queue" OWNER TO "postgres";


COMMENT ON TABLE "public"."liga_notificaciones_queue" IS 'Cola de bienvenida de liga. No guarda el correo. Independiente de Torneo Express.';



