COMMENT ON COLUMN "public"."ligas"."playoff_seeds" IS 'Fotografía congelada seeds 1..N (+ opcional classification_bye = equipo_id)';



COMMENT ON COLUMN "public"."ligas"."playoff_seeded_at" IS 'Timestamp de congelación de playoff_seeds (fase regular cerrada)';



COMMENT ON CONSTRAINT "ligas_modalidad_check" ON "public"."ligas" IS 'Modalidades Liga: individual_rotativo | parejas_fijas | parejas_fijas_playoffs | flex_league';



