    CONSTRAINT "notificaciones_eventos_queue_event_type_check" CHECK (("event_type" = ANY (ARRAY['inscripcion_torneo'::"text", 'bienvenida_torneo'::"text", 'asignacion_grupo'::"text", 'clasifico_eliminatoria_batch'::"text", 'partido_programado'::"text", 'resultado_partido'::"text"])))
);


