CREATE TABLE IF NOT EXISTS "public"."pairs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "player1_id" "uuid",
    "player2_id" "uuid",
    "tournament_id" "uuid" NOT NULL,
    "player1_name" character varying(255),
    "player2_name" character varying(255),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "is_virtual" boolean DEFAULT false NOT NULL,
    "virtual_label" "text",
    CONSTRAINT "pairs_shape_real_or_virtual" CHECK (((("is_virtual" = false) AND ("player1_id" IS NOT NULL) AND ("player2_id" IS NOT NULL) AND ("player1_name" IS NOT NULL) AND ("player2_name" IS NOT NULL) AND ("virtual_label" IS NULL)) OR (("is_virtual" = true) AND ("player1_id" IS NULL) AND ("player2_id" IS NULL) AND ("player1_name" IS NULL) AND ("player2_name" IS NULL) AND ("virtual_label" IS NOT NULL) AND ("btrim"("virtual_label") <> ''::"text"))))
);


