COMMENT ON COLUMN "public"."players"."email_verified" IS 'True cuando el jugador confirmo su email real';



COMMENT ON COLUMN "public"."players"."notif_opt_in_email" IS 'Consentimiento para notificaciones por email';



COMMENT ON COLUMN "public"."players"."notif_opt_in_whatsapp" IS 'Consentimiento para notificaciones por WhatsApp';



COMMENT ON COLUMN "public"."players"."contact_updated_at" IS 'Ultima fecha de actualizacion de contacto';



CREATE OR REPLACE VIEW "public"."pairs_with_contact" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "pair_id",
    "p"."tournament_id",
    "p"."player1_id",
    "p"."player2_id",
    "pl1"."name" AS "player1_name",
    "pl1"."email" AS "player1_email",
    "pl1"."whatsapp_phone" AS "player1_whatsapp",
    "pl1"."email_verified" AS "player1_email_verified",
    "pl1"."notif_opt_in_email" AS "player1_opt_email",
    "pl1"."notif_opt_in_whatsapp" AS "player1_opt_whatsapp",
    "pl2"."name" AS "player2_name",
    "pl2"."email" AS "player2_email",
    "pl2"."whatsapp_phone" AS "player2_whatsapp",
    "pl2"."email_verified" AS "player2_email_verified",
    "pl2"."notif_opt_in_email" AS "player2_opt_email",
    "pl2"."notif_opt_in_whatsapp" AS "player2_opt_whatsapp"
   FROM (("public"."pairs" "p"
     JOIN "public"."players" "pl1" ON (("pl1"."id" = "p"."player1_id")))
     JOIN "public"."players" "pl2" ON (("pl2"."id" = "p"."player2_id")));


ALTER VIEW "public"."pairs_with_contact" OWNER TO "postgres";


COMMENT ON VIEW "public"."pairs_with_contact" IS 'Parejas con datos de contacto y opt-in de ambos jugadores';



CREATE TABLE IF NOT EXISTS "public"."rating_historial" (
