CREATE OR REPLACE VIEW "public"."riviera_jugadores_sitio_oficial" WITH ("security_invoker"='true') AS
 SELECT "rj"."id",
    "rj"."organizador_id",
    "rj"."nombre",
    "rj"."slug",
    "rj"."foto_url",
    "rj"."categoria",
    "rj"."genero",
    "rj"."pais_codigo",
    "rj"."club",
    "rj"."estado",
    "rj"."visible_publico",
    "rj"."suma_ranking",
    "rj"."rating",
    "rj"."rating_partidos",
    "rj"."rating_fiabilidad",
    "rj"."created_at",
    "rj"."updated_at",
    "public"."riviera_official_display_puntos_for_jugador"("rj"."id") AS "puntos_totales",
    COALESCE("js"."total_partidos", 0) AS "total_partidos",
    COALESCE("js"."victorias", 0) AS "victorias"
   FROM ("public"."riviera_jugadores" "rj"
     LEFT JOIN "public"."jugador_stats" "js" ON (("js"."jugador_id" = "rj"."id")))
  WHERE (("rj"."estado" = 'activo'::"public"."riviera_jugador_estado") AND ("rj"."visible_publico" IS TRUE) AND (COALESCE("rj"."suma_ranking", true) = true));


ALTER VIEW "public"."riviera_jugadores_sitio_oficial" OWNER TO "postgres";


COMMENT ON VIEW "public"."riviera_jugadores_sitio_oficial" IS 'Ranking público sitio oficial. security_invoker=true: anon respeta RLS (visible_publico + ranking activo).';



CREATE TABLE IF NOT EXISTS "public"."riviera_official_player_identity" (
    "official_player_key" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "canonical_riviera_jugador_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "riviera_id" "text",
    "riviera_id_serial" bigint,
    "debut_organizer_id" "uuid",
    "debut_at" timestamp with time zone,
    CONSTRAINT "ropi_debut_pair_chk" CHECK (((("debut_organizer_id" IS NULL) AND ("debut_at" IS NULL)) OR (("debut_organizer_id" IS NOT NULL) AND ("debut_at" IS NOT NULL)))),
    CONSTRAINT "ropi_riviera_id_format_chk" CHECK ((("riviera_id" IS NULL) OR ("riviera_id" ~ '^RIV-[0-9]{8}$'::"text"))),
    CONSTRAINT "ropi_riviera_id_pair_chk" CHECK (((("riviera_id" IS NULL) AND ("riviera_id_serial" IS NULL)) OR (("riviera_id" IS NOT NULL) AND ("riviera_id_serial" IS NOT NULL)))),
    CONSTRAINT "ropi_riviera_id_serial_positive_chk" CHECK ((("riviera_id_serial" IS NULL) OR ("riviera_id_serial" >= 1)))
);


ALTER TABLE "public"."riviera_official_player_identity" OWNER TO "postgres";


COMMENT ON TABLE "public"."riviera_official_player_identity" IS 'Contenedor de Carrera Deportiva: identidad permanente del deportista en Riviera. Un official_player_key por persona; perfiles locales enlazados vía profile_link. Riviera ID (riviera_id) = identidad pública legible; official_player_key = llave técnica interna.';



COMMENT ON COLUMN "public"."riviera_official_player_identity"."official_player_key" IS 'Llave técnica interna permanente (UUID). No se muestra al jugador. Acumula ledger, totales y futura Carrera Deportiva.';



COMMENT ON COLUMN "public"."riviera_official_player_identity"."canonical_riviera_jugador_id" IS 'Perfil de registro: riviera_jugadores.id del Organizador de Registro (Debut Riviera). Término legacy en columna; en producto: perfil donde inició la Carrera Deportiva.';



COMMENT ON COLUMN "public"."riviera_official_player_identity"."riviera_id" IS 'Riviera ID — identidad pública permanente del jugador. Formato congelado: RIV-00000001. Nunca cambia, nunca se reutiliza, independiente del UUID interno. Asignado en Sprint 2.0.4+.';



COMMENT ON COLUMN "public"."riviera_official_player_identity"."riviera_id_serial" IS 'Componente numérico del Riviera ID (secuencia global). Par acoplado con riviera_id.';



COMMENT ON COLUMN "public"."riviera_official_player_identity"."debut_organizer_id" IS 'Debut Riviera — Organizador de Registro: primer organizador donde inició la Carrera Deportiva. Inmutable una vez asignado. No implica propiedad del jugador.';



COMMENT ON COLUMN "public"."riviera_official_player_identity"."debut_at" IS 'Debut Riviera — Fecha de Registro: momento en que se abrió la Carrera Deportiva. Inmutable una vez asignado.';



